#include <stdlib.h>
#include <time.h>
#include <pthread.h>

typedef struct TIDB_ROW_RECORD {
    int ROW_ID;
    char* COLUMN_VALUES;
    time_t TIMESTAMP;
} TIDB_ROW_RECORD;

void initialize_list(TIDB_ROW_RECORD** list) {
    *list = (TIDB_ROW_RECORD*)malloc(sizeof(TIDB_ROW_RECORD));
    (*list)->ROW_ID = 0;
    (*list)->COLUMN_VALUES = NULL;
    (*list)->TIMESTAMP = time(NULL);
}

void populate_list(TIDB_ROW_RECORD** list, int num_rows) {
    for (int i = 0; i < num_rows; i++) {
        TIDB_ROW_RECORD* new_row = (TIDB_ROW_RECORD*)malloc(sizeof(TIDB_ROW_RECORD));
        new_row->ROW_ID = i + 1;
        new_row->COLUMN_VALUES = "column_value";
        new_row->TIMESTAMP = time(NULL);
        pthread_mutex_lock(&list_mutex);
        (*list)->next = new_row;
        list = &new_row;
        pthread_mutex_unlock(&list_mutex);
    }
}
