    }

    // Allocate memory for the key array
    key_array = (int *)malloc(num_records * sizeof(int));
    if (key_array == NULL) {
        printf("Error: Failed to allocate memory for key array\n");
        return;
    }

    // Initialize the key array with random values within the specified range
    srand(time(NULL));
    for (int i = 0; i < num_records; i++) {
        key_array[i] = rand() % max_value;
    }

    // Allocate memory for the record array
    record_array = (Record **)malloc(num_records * sizeof(Record));
    if (record_array == NULL) {
        printf("Error: Failed to allocate memory for record array\n");
        return;
    }

    // Initialize each record with a random value within the specified range
    srand(time(NULL));
    for (int i = 0; i < num_records; i++) {
        record_array[i] = malloc(sizeof(Record));
        if (record_array[i] == NULL) {
            printf("Error: Failed to allocate memory for record %d\n", i);
            return;
        }
        record_array[i]->key = rand() % max_value;
    }
}

// Define the function to copy the contents of the 'record' array to another allocated buffer
void copy_records(Record **record_array, int num_records) {
    // Allocate memory for the destination buffer
    Record *dest_buffer = (Record *)malloc(num_records * sizeof(Record));
    if (dest_buffer == NULL) {
        printf("Error: Failed to allocate memory for destination buffer\n");
        return;
    }

    // Copy each record from the source array to the destination buffer
    for (int i = 0; i < num_records; i++) {
        dest_buffer[i] = *record_array[i];
    }
}

// Define the function to free all allocated memory when it is no longer needed
void free_memory(Record **record_array, int num_records) {
    // Free each record in the array
    for (int i = 0; i < num_records; i++) {
        free(record_array[i]);
    }

    // Free the offset and key arrays
    free(offset_array);
    free(key_array);

    // Free the record array
    free(record_array);
}
