#include <openssl/evp.h>
#include <openssl/des.h>
#include <string.h>

bool validate_oauth2_token(const char* token) {
    // Parse the JSON string and extract the required fields
    json_object* obj = json_tokener_parse(token);
    if (!obj) {
        return false;
    }

    const char* access_token = json_object_get_string(json_object_object_get(obj, "access_token"));
    int expires_in = json_object_get_int(json_object_object_get(obj, "expires_in"));
    const char* token_type = json_object_get_string(json_object_object_get(obj, "token_type"));
    const char* refresh_token = json_object_get_string(json_object_object_get(obj, "refresh_token"));

    // Check if the required fields are present and have valid values
    if (!access_token || !expires_in || !token_type) {
        return false;
    }

    if (strcmp(token_type, "Bearer") != 0) {
        return false;
    }

    if (expires_in <= 0) {
        return false;
    }

    // If all required fields are present and have valid values, return true
    return true;
}

EVP_CIPHER* get_cipher(const char* mode) {
    if (!strcmp(mode, "ECB")) {
        return EVP_des_ecb();
    } else if (!strcmp(mode, "EDE")) {
        return EVP_des_ede();
    } else if (!strcmp(mode, "EDE3")) {
        return EVP_des_ede3();
    } else if (!strcmp(mode, "CFB")) {
        return EVP_des_cfb();
    } else {
        // Unknown mode, return NULL
        return NULL;
    }
}
