public class PokemonReport {
    public static Map<String, String> getPokemonReport(Pokemon pokemon) {
        // Retrieve the Pokemon's type using a library function
        String type = pokemon.getType();

        // Use a switch statement to determine the weaknesses based on the Pokemon's type
        Map<String, String> weaknesses = new HashMap<>();
        switch (type) {
            case "Fire":
                weaknesses.put("Water", "Super Effective");
                break;
            case "Water":
                weaknesses.put("Fire", "Super Effective");
                break;
