    algorithms = realloc(algorithms, (num_algorithms + 1) * sizeof(Algorithm));
    if (!algorithms) {
        fprintf(stderr, "Error allocating memory for algorithm list: %s\n", dlerror());
        return -1;
    }
    algorithms[num_algorithms++] = new_algorithm;

    // Close the plugin file
    if (dlclose(handle) == -1) {
        fprintf(stderr, "Error closing plugin file: %s\n", dlerror());
        return -1;
    }

    return 0;
}

// Define a function to unload an algorithm from the list of available algorithms
int unload_algorithm(const char *plugin_file) {
    // Find the algorithm in the list of available algorithms
