    // Remove the algorithm from the list of available algorithms
    Algorithm *algorithm = algorithms[i];
    for (int j = i + 1; j < num_algorithms; j++) {
        algorithms[j - 1] = algorithms[j];
    }
    num_algorithms--;

    // Free the memory allocated to the algorithm structure
    free(algorithm->name);
    free(algorithm);

