#include <openssl/md5.h>
#include <string.h>
#include <stdlib.h>
#include <stdio.h>

void md5_hash(char* input, char* output) {
    // Initialize the MD5 context
    MD5_CTX ctx;
    MD5_Init(&ctx);

    // Process the input data in chunks to manage memory usage effectively
    int chunk_size = 1024 * 1024; // 1 MB
    char* buffer = (char*)malloc(chunk_size);
    FILE* fp = fopen(input, "rb");
    while (!feof(fp)) {
        size_t bytes_read = fread(buffer, 1, chunk_size, fp);
        MD5_Update(&ctx, buffer, bytes_read);
    }
    free(buffer);
    fclose(fp);

    // Finalize the hash and store it in the output parameter
    unsigned char digest[MD5_DIGEST_LENGTH];
    MD5_Final(digest, &ctx);
    for (int i = 0; i < MD5_DIGEST_LENGTH; i++) {
        sprintf(output + i * 2, "%02x", digest[i]);
    }
}
