// Define a worker thread class to handle GET requests concurrently
class WorkerThread {
public:
    WorkerThread(io_service& ioService) : ioService_(ioService) {}

    void operator()() {
        while (true) {
            // Get the next request from the queue
            auto request = requestQueue_.front();
            requestQueue_.pop();

            // Handle the request and update metrics
            handleRequest(request);

            // Check if there are more requests in the queue
            if (!requestQueue_.empty()) {
                // There are more requests, continue processing them
                continue;
            } else {
                // No more requests, exit the thread
                break;
            }
        }
    }

private:
    void handleRequest(const string& request) {
        // Implement request handling logic here
        // ...

        // Update metrics
        ++successfulRequests_;
        totalResponseTime_ += responseTime;
        peakActiveSessions_ = max(peakActiveSessions_, activeSessions_);
    }

private:
    io_service& ioService_;
    queue<string> requestQueue_;
    uint64_t successfulRequests_ = 0;
    uint64_t failedRequests_ = 0;
    uint64_t totalResponseTime_ = 0;
    uint64_t peakActiveSessions_ = 0;
};

// Define a Sandesh client class to handle GET requests concurrently using worker threads
class SandeshClient {
public:
    SandeshClient(io_service& ioService) : ioService_(ioService), threadPool_(maxThreads_) {}

    void start() {
        // Start the server connection and run indefinitely, gracefully handling interruptions and cleaning up resources
        while (true) {
            try {
                // Connect to the server
                socket_.connect(endpoint_);

                // Handle GET requests concurrently using worker threads
                for (auto& thread : threadPool_) {
                    thread = boost::thread(boost::bind(&WorkerThread::operator(), &thread));
                }

                // Wait for the next request
                socket_.wait();

                // Handle the request and update metrics
                handleRequest(socket_.receive());
            } catch (const exception& e) {
                Logging::log("Error: " + string(e.what()), Logging::ErrorType::NETWORK);
            }
        }
    }

private:
    void handleRequest(const string& request) {
        // Implement request handling logic here
        // ...

        // Update metrics
        ++successfulRequests_;
        totalResponseTime_ += responseTime;
        peakActiveSessions_ = max(peakActiveSessions_, activeSessions_);
    }

private:
    io_service& ioService_;
    tcp::socket socket_;
    tcp::endpoint endpoint_;
    vector<WorkerThread> threadPool_;
    uint64_t successfulRequests_ = 0;
    uint64_t failedRequests_ = 0;
    uint64_t totalResponseTime_ = 0;
    uint64_t peakActiveSessions_ = 0;
};

int main() {
    // Initialize the Boost library and create an io_service object
    boost::asio::io_service ioService;

    // Create a Sandesh client instance using the io_service object
    SandeshClient sandeshClient(ioService);

    // Start the server connection and run indefinitely, gracefully handling interruptions and cleaning up resources
    sandeshClient.start();

    return 0;
}
```
This code uses the Boost library to create a Sandesh client capable of handling concurrent GET requests to a server using worker threads. The program manages a pool of worker threads to process requests efficiently, and maintains a detailed report of the following metrics:

* Number of successful requests
