public static IDataReader ExecuteStoredProcedure(IDbConnection connection, string procedureName, List<object> inputParameters, PaginationSettings paginationSettings)
{
    using (var transaction = connection.BeginTransaction())
    {
        try
        {
            var command = new SqlCommand(procedureName, connection);
            command.Transaction = transaction;
            command.CommandType = CommandType.StoredProcedure;

            foreach (var parameter in inputParameters)
            {
                command.Parameters.AddWithValue($"@{parameter.Key}", parameter.Value);
            }

            var reader = command.ExecuteReader();

            if (paginationSettings != null)
            {
                reader = new PaginatedDataReader(reader, paginationSettings);
            }

            transaction.Commit();
            return reader;
        }
        catch (Exception ex)
        {
            transaction.Rollback();
            throw;
        }
    }
}
```']

