const express = require('express');
const router = express.Router();

// Create new resource
router.post('/', async (req, res) => {
  // Validate input data
  if (!req.body.name || !req.body.description) {
    return res.status(400).json({ message: 'Invalid request' });
  }

  // Create new resource in database
  const newResource = await createNewResource(req.body);

  // Return created resource
  res.json(newResource);
});

// Update existing resource
router.put('/:id', async (req, res) => {
  // Validate input data
  if (!req.body.name || !req.body.description) {
    return res.status(400).json({ message: 'Invalid request' });
  }

  // Update existing resource in database
  const updatedResource = await updateResource(req.params.id, req.body);

  // Return updated resource
  res.json(updatedResource);
});

// Delete resource
router.delete('/:id', async (req, res) => {
  // Validate input data
  if (!req.params.id) {
    return res.status(400).json({ message: 'Invalid request' });
  }

  // Delete resource from database
  const deletedResource = await deleteResource(req.params.id);

  // Return deleted resource
  res.json(deletedResource);
});

// Search resources
router.get('/search', async (req, res) => {
  // Validate input data
  if (!req.query.filter || !req.query.page) {
    return res.status(400).json({ message: 'Invalid request' });
  }

  // Search for resources in database
  const searchResults = await searchResources(req.query.filter, req.query.page);

  // Return search results
  res.json(searchResults);
});
