function handleUserRequest($_REQUEST) {
    // Input validation
    if (!validateInput($_REQUEST)) {
        return json_encode(['message' => 'error', 'errors' => $errors]);
    }

    // Check if the user account exists in the database
    if (isset($_REQUEST['id'])) {
        $user = getUserById($_REQUEST['id']);
        if (!$user) {
            return json_encode(['message' => 'error', 'errors' => ['Invalid ID']]);
        }
    }

    // Handle create or update request
    if (isset($_REQUEST['name']) && isset($_REQUEST['email']) && isset($_REQUEST['password'])) {
        $user = new User();
        $user->name = $_REQUEST['name'];
        $user->email = $_REQUEST['email'];
        $user->password = password_hash($_REQUEST['password'], PASSWORD_DEFAULT);
        if (isset($_REQUEST['id'])) {
            // Update user account
            updateUser($user, $_REQUEST['id']);
        } else {
            // Create new user account
            createUser($user);
        }
    }

    // Handle delete request
    if (isset($_REQUEST['sub_action']) && $_REQUEST['sub_action'] === 'delete') {
        $user = getUserById($_REQUEST['id']);
        if (!$user) {
            return json_encode(['message' => 'error', 'errors' => ['Invalid ID']]);
        }
        deleteUser($user);
    }

    // Send email confirmation
    sendEmailConfirmation($_REQUEST['email'], $_REQUEST['name']);

    // Log action
    logAction($_REQUEST['id'], $_REQUEST['action'], $_REQUEST['timestamp']);

    return json_encode(['message' => 'success']);
}

