        $errors[] = 'Name must be less than 50 characters';
    }

    if (!filter_var($input['email'], FILTER_VALIDATE_EMAIL)) {
        $errors[] = 'Invalid email address';
    }

    if (strlen($input['password']) < 8) {
        $errors[] = 'Password must be at least 8 characters long';
    }

    return empty($errors);
}

