    public HttpPostManager(HttpClient httpClient)
    {
        _httpClient = httpClient;
    }

    public async Task<bool> UpdatePageSectionAsync(string userSessionId, string pageSectionId, string htmlContent)
    {
        try
        {
            // Validate the user session to ensure authorization
            if (!ValidateUserSession(userSessionId))
            {
                return false;
            }

            // Update the specified element's HTML content using a service class
            var updateResult = await _httpClient.PostAsync($"api/page-sections/{pageSectionId}", new StringContent(htmlContent, Encoding.UTF8, "application/json"));

            if (!updateResult.IsSuccessStatusCode)
            {
                return false;
            }

            // Return a response indicating whether the page should be refreshed or if there was an issue with the request
            var response = await updateResult.Content.ReadAsStringAsync();
            return response == "refresh";
        }
        catch (Exception ex)
        {
            // Log relevant details for debugging purposes
            Console.WriteLine(ex);
            return false;
        }
    }

    private bool ValidateUserSession(string userSessionId)
    {
        // Implement your own logic to validate the user session here
        return true;
    }
}
