            var minLength = _configuration.GetValue<int>("Password:MinLength");
            var minUppercase = _configuration.GetValue<int>("Password:MinUppercase");
            var minLowercase = _configuration.GetValue<int>("Password:MinLowercase");
            var minNumbers = _configuration.GetValue<int>("Password:MinNumbers");
            var minSpecialCharacters = _configuration.GetValue<int>("Password:MinSpecialCharacters");

