                }
                else if (char.IsLower(c))
                {
                    lowercaseCount++;
                }
                else if (char.IsNumber(c))
                {
                    numberCount++;
                }
                else if (char.IsSymbol(c))
                {
                    specialCharacterCount++;
                }
