function generateNavigationMenu(endpoints) {
  const menu = document.createElement("nav");
  endpoints.forEach((endpoint) => {
    const item = document.createElement("a");
    item.href = endpoint.path;
    item.textContent = endpoint.label;
    if (endpoint.method === "GET") {
      item.classList.add("get-method");
    } else if (endpoint.method === "POST") {
      item.classList.add("post-method");
    } else if (endpoint.method === "PUT") {
      item.classList.add("put-method");
    } else if (endpoint.method === "DELETE") {
      item.classList.add("delete-method");
    }
    menu.appendChild(item);
  });
  return menu;
}
