const moduleLoader = (modules) => {
  const loadedModules = [];
  const failedModules = [];

  // Load modules in specified order
  for (let i = 0; i < modules.length; i++) {
    const moduleName = modules[i];
    try {
      const module = require(moduleName);
      loadedModules.push(module);
    } catch (error) {
      failedModules.push(moduleName);
    }
  }

  // Execute loaded modules in order
  for (let i = 0; i < loadedModules.length; i++) {
    const module = loadedModules[i];
    try {
      module();
    } catch (error) {
      console.log(`Error executing module ${moduleName}: ${error}`);
    }
  }

  // Handle failed modules
  if (failedModules.length > 0) {
    console.log(`Failed to load the following modules: ${failedModules.join(', ')}`);
  }
};
```
