public class TransactionDiscrepancyChecker {
    public static void checkTransactions(List<Transaction> transactions) {
        long startTime = System.nanoTime();
        Map<Long, Long> expectedAmounts = new HashMap<>();
        for (Transaction transaction : transactions) {
            long id = transaction.getId();
            long expectedAmount = transaction.getExpectedAmount();
            long actualAmount = transaction.getActualAmount();
            if (expectedAmount != actualAmount) {
                logDiscrepancy(id, expectedAmount, actualAmount);
            }
        }
        long endTime = System.nanoTime();
        long timeTaken = TimeUnit.NANOSECONDS.toMillis(endTime - startTime);
        System.out.println("Total time taken for discrepancy check: " + timeTaken + "ms");
    }

    private static void logDiscrepancy(long id, long expectedAmount, long actualAmount) {
        System.out.println("Discrepancy found for transaction ID " + id + ": Expected amount = " + expectedAmount + ", Actual amount = " + actualAmount);
    }
}
