import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.TimeUnit;
import java.nio.channels.AsynchronousChannelGroup;
import java.nio.channels.AsynchronousSocketChannel;
import java.nio.channels.CompletionHandler;

public class ConnectionPool {
    private static final int MAX_CONNECTIONS = 10;
    private static final long CONNECTION_TIMEOUT = TimeUnit.SECONDS.toMillis(30);
    private static final ExecutorService EXECUTOR = Executors.newFixedThreadPool(MAX_CONNECTIONS);
    private static final ConcurrentHashMap<String, AsynchronousSocketChannel> POOL = new ConcurrentHashMap<>();

    public static void getConnection(String host, int port) {
        if (POOL.containsKey(host + ":" + port)) {
            return;
        }

        try {
            AsynchronousSocketChannel channel = AsynchronousSocketChannel.open();
            channel.connect(new InetSocketAddress(host, port)).get(CONNECTION_TIMEOUT, TimeUnit.MILLISECONDS);
            POOL.put(host + ":" + port, channel);
        } catch (Exception e) {
            // handle exception
        }
    }

    public static void returnConnection(String host, int port) {
        if (!POOL.containsKey(host + ":" + port)) {
            return;
        }

        try {
            AsynchronousSocketChannel channel = POOL.get(host + ":" + port);
            channel.close();
            POOL.remove(host + ":" + port);
        } catch (Exception e) {
            // handle exception
        }
    }
}
