import os
import hashlib
from PIL import Image

class ImageManager:
    def __init__(self):
        self.cache_dir = "./image_cache"
        if not os.path.exists(self.cache_dir):
            os.makedirs(self.cache_dir)

    def load_image(self, image_url):
        # Check if the image is already cached
        cache_file = self._get_cache_file(image_url)
        if cache_file:
            return Image.open(cache_file)

        # Fetch the image from external source and store it in cache
        response = requests.get(image_url, stream=True)
        with open(cache_file, "wb") as f:
            for chunk in response.iter_content(1024):
                f.write(chunk)

        # Verify the integrity of the cached image by comparing checksums
        expected_checksum = hashlib.sha256(response.content).hexdigest()
        actual_checksum = hashlib.sha256(open(cache_file, "rb").read()).hexdigest()
        if expected_checksum != actual_checksum:
            raise Exception("Checksum mismatch for image {}".format(image_url))

        return Image.open(cache_file)

    def _get_cache_file(self, image_url):
        cache_file = os.path.join(self.cache_dir, hashlib.sha256(image_url.encode("utf-8")).hexdigest() + ".jpg")
        return cache_file if os.path.exists(cache_file) else None
