def update_profile(user_id):
    # Initialize variables for API requests and logging
    api_requests = []
    log_messages = []

    # Fetch data from external APIs
    api1_data = fetch_api1_data(user_id)
    api2_data = fetch_api2_data(user_id)
    api3_data = fetch_api3_data(user_id)

    # Combine data from all APIs
    combined_data = {**api1_data, **api2_data, **api3_data}

    # Update user profile with latest activity status, location, and contact information
    update_profile_status(user_id, combined_data)

    # Log API requests and updates for auditing purposes
    log_messages.append("API request made to fetch data from external APIs")
    log_messages.append("User profile updated with latest activity status, location, and contact information")

    # Handle failed API requests gracefully
    if len(api_requests) > 0:
        for api_request in api_requests:
            try:
                api_request.raise_for_status()
            except requests.exceptions.HTTPError as e:
                log_messages.append("Failed API request: {}".format(e))

    # Return confirmation message indicating whether the profile was successfully updated
    if len(log_messages) == 0:
        return "Profile successfully updated"
    else:
        return "Error updating profile: {}".format(", ".join(log_messages))
