using System;

public class RandomValueGenerator
{
    private float _min;
    private float _max;

    public RandomValueGenerator(float min = 0f, float max = 1f)
    {
        if (min > max)
            throw new ArgumentException("Invalid range", nameof(min));

        _min = min;
        _max = max;
    }

    public float GenerateFloat()
    {
        return Random.Range(_min, _max);
    }

    public int GenerateInt()
    {
        return (int)Random.Range((float)_min, (float)_max);
    }

    public void AdjustRange(float min, float max)
    {
        if (min > max)
            throw new ArgumentException("Invalid range", nameof(min));

        _min = min;
        _max = max;
    }

    public void Reset()
    {
        _min = 0f;
        _max = 1f;
    }

    public override string ToString()
    {
        return $"Range: [{_min}, {_max}]";
    }
}
