#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <unistd.h>
#include <pthread.h>
#include <stdbool.h>
#include <json-c/json.h>
#include <csv.h>

// Define the resource bundle structure
struct ResourceBundle {
    char *path;
    int num_items;
    void *data;
};

// Define the cache structure
struct Cache {
    struct ResourceBundle *bundle;
    bool valid;
};

// Define the logging levels
#define LOG_LEVEL_DEBUG 0
#define LOG_LEVEL_INFO 1
#define LOG_LEVEL_WARN 2
#define LOG_LEVEL_ERROR 3

// Define the logging function
void log(int level, const char *format, ...) {
    va_list args;
    va_start(args, format);
    switch (level) {
        case LOG_LEVEL_DEBUG:
            printf("[DEBUG] ");
            break;
        case LOG_LEVEL_INFO:
            printf("[INFO] ");
            break;
        case LOG_LEVEL_WARN:
            printf("[WARN] ");
            break;
        case LOG_LEVEL_ERROR:
            printf("[ERROR] ");
            break;
    }
    vprintf(format, args);
    va_end(args);
}

// Define the cache management functions
void cache_init(struct Cache *cache) {
    cache->bundle = NULL;
    cache->valid = false;
}

void cache_destroy(struct Cache *cache) {
    if (cache->bundle != NULL) {
        free(cache->bundle);
    }
    cache->valid = false;
}

bool cache_load(struct Cache *cache, const char *path) {
    // Check if the cache is already valid
    if (cache->valid) {
        return true;
    }

    // Load the resource bundle from the file
    struct ResourceBundle *bundle = load_resource_bundle(path);
    if (bundle == NULL) {
        log(LOG_LEVEL_ERROR, "Failed to load resource bundle: %s", strerror(errno));
        return false;
    }

    // Set the cache data and mark it as valid
    cache->bundle = bundle;
    cache->valid = true;

    return true;
}

void cache_invalidate(struct Cache *cache) {
    if (cache->valid) {
        free(cache->bundle);
        cache->valid = false;
    }
}

// Define the resource bundle loading functions
struct ResourceBundle *load_resource_bundle(const char *path) {
    // Open the file and check for errors
    int fd = open(path, O_RDONLY);
    if (fd == -1) {
        log(LOG_LEVEL_ERROR, "Failed to open resource bundle file: %s", strerror(errno));
        return NULL;
    }

    // Determine the file format and load the data accordingly
    struct stat sb;
    if (fstat(fd, &sb) == -1) {
        log(LOG_LEVEL_ERROR, "Failed to determine resource bundle file type: %s", strerror(errno));
        close(fd);
        return NULL;
    }

    // Load the JSON data
    if (S_ISREG(sb.st_mode)) {
        struct json_object *json = json_object_from_file(path);
        if (json == NULL) {
            log(LOG_LEVEL_ERROR, "Failed to parse JSON resource bundle: %s", strerror(errno));
            close(fd);
            return NULL;
        }

        // Create the resource bundle structure and populate it with the data
        struct ResourceBundle *bundle = malloc(sizeof(struct ResourceBundle));
        if (bundle == NULL) {
            log(LOG_LEVEL_ERROR, "Failed to allocate memory for resource bundle: %s", strerror(errno));
            json_object_put(json);
            close(fd);
            return NULL;
        }

        bundle->path = path;
        bundle->num_items = json_object_array_length(json);
        bundle->data = json;

        // Close the file and return the resource bundle structure
        close(fd);
        return bundle;
    }

    // Load the CSV data
    if (S_ISREG(sb.st_mode)) {
        struct csv_parser *csv = csv_parse_file(path, NULL);
        if (csv == NULL) {
            log(LOG_LEVEL_ERROR, "Failed to parse CSV resource bundle: %s", strerror(errno));
            close(fd);
            return NULL;
        }

        // Create the resource bundle structure and populate it with the data
        struct ResourceBundle *bundle = malloc(sizeof(struct ResourceBundle));
        if (bundle == NULL) {
            log(LOG_LEVEL_ERROR, "Failed to allocate memory for resource bundle: %s", strerror(errno));
            csv_parse_free(csv);
            close(fd);
            return NULL;
        }

        bundle->path = path;
        bundle->num_items = csv_get_row_count(csv);
        bundle->data = csv;

        // Close the file and return the resource bundle structure
        close(fd);
        return bundle;
    }

    // Unsupported file format
    log(LOG_LEVEL_ERROR, "Unsupported resource bundle file type: %s", path);
    close(fd);
    return NULL;
}

// Define the resource bundle unloading function
void unload_resource_bundle(struct ResourceBundle *bundle) {
    if (bundle == NULL) {
        return;
    }

    // Free the data and release the memory
    json_object_put(bundle->data);
    free(bundle);
}

// Define the resource bundle caching function
void cache_resource_bundle(struct Cache *cache, struct ResourceBundle *bundle) {
    if (cache == NULL || bundle == NULL) {
        return;
    }

    // Free any existing data and allocate new memory for the bundle
    unload_resource_bundle(cache->bundle);
    cache->bundle = malloc(sizeof(struct ResourceBundle));
    if (cache->bundle == NULL) {
        log(LOG_LEVEL_ERROR, "Failed to allocate memory for resource bundle: %s", strerror(errno));
        return;
    }

    // Copy the data from the bundle and mark it as valid
    memcpy(cache->bundle, bundle, sizeof(struct ResourceBundle));
    cache->valid = true;
}

// Define the resource bundle retrieval function
struct ResourceBundle *get_resource_bundle(const char *path) {
    // Check if the cache is valid and contains the requested data
    struct Cache cache;
    cache_init(&cache);
    if (cache_load(&cache, path)) {
        return cache.bundle;
    }

    // Load the resource bundle from the file and cache it
    struct ResourceBundle *bundle = load_resource_bundle(path);
    if (bundle == NULL) {
        log(LOG_LEVEL_ERROR, "Failed to load resource bundle: %s", strerror(errno));
        return NULL;
    }
    cache_resource_bundle(&cache, bundle);

    // Return the resource bundle structure
    return bundle;
}

// Define the resource bundle unloading function
void unload_resource_bundle(struct ResourceBundle *bundle) {
    if (bundle == NULL) {
        return;
    }

    // Free any existing data and release the memory
    json_object_put(bundle->data);
    free(bundle);
}

// Define the resource bundle retrieval function with asynchronous loading support
struct ResourceBundle *get_resource_bundle_async(const char *path) {
    // Create a new thread to load the resource bundle asynchronously
    pthread_t thread;
    if (pthread_create(&thread, NULL, load_resource_bundle, path)) {
        log(LOG_LEVEL_ERROR, "Failed to create asynchronous loading thread: %s", strerror(errno));
        return NULL;
    }

    // Return the resource bundle structure
    return NULL;
}

// Define the resource bundle unloading function with asynchronous loading support
void unload_resource_bundle_async(struct ResourceBundle *bundle) {
    if (bundle == NULL) {
        return;
    }

    // Free any existing data and release the memory
    json_object_put(bundle->data);
    free(bundle);
}
