char* process_string(const char* input, size_t max_size, char* buffer) {
    // Check if the input string's length exceeds the specified size limit
    size_t input_len = strlen(input);
    if (input_len > max_size) {
        // Allocate a new buffer large enough to store the string with an additional character for the slash, plus one extra byte for the null terminator
        char* new_buffer = malloc((input_len + 2) * sizeof(char));
        if (new_buffer == NULL) {
            // Handle memory allocation failure gracefully
            return NULL;
        }
        strcpy(new_buffer, input);
        new_buffer[input_len] = '/';
        new_buffer[input_len + 1] = '\0';
        buffer = new_buffer;
    } else {
        // Append a slash to the end of the string only if the string does not exceed the size limit
        strcat(buffer, "/");
    }
    return buffer;
}
