typedef struct {
    unsigned short bits_per_sample;
    unsigned short samples_per_pixel;
    unsigned int extra_samples_count;
} tiff_info;

void* processTIFFAndEncrypt(const char* file_path, const char* encryption_command) {
    // Open the TIFF file and parse its information
    TIFF* tif = TIFFOpen(file_path, "r");
    if (!tif) {
        fprintf(stderr, "Error opening TIFF file: %s\n", file_path);
        return NULL;
    }

    // Get the number of bits per sample and samples per pixel
    unsigned short bits_per_sample = 0;
    unsigned short samples_per_pixel = 0;
    if (TIFFGetField(tif, TIFFTAG_BITSPERSAMPLE, &bits_per_sample) == 0 ||
        TIFFGetField(tif, TIFFTAG_SAMPLESPERPIXEL, &samples_per_pixel) == 0) {
        fprintf(stderr, "Error getting bits per sample and samples per pixel\n");
        return NULL;
    }

    // Check if the number of bits per sample is supported
    if (bits_per_sample != 1 && bits_per_sample != 2 && bits_per_sample != 4 &&
        bits_per_sample != 8 && bits_per_sample != 16) {
        fprintf(stderr, "Unsupported number of bits per sample: %d\n", bits_per_sample);
        return NULL;
    }

    // Get the number of extra samples
    unsigned int extra_samples_count = 0;
    if (TIFFGetField(tif, TIFFTAG_EXTRASAMPLES, &extra_samples_count) == 0) {
        fprintf(stderr, "Error getting number of extra samples\n");
        return NULL;
    }

    // Allocate memory for the sample information
    tiff_info* info = (tiff_info*)malloc(sizeof(tiff_info));
    if (!info) {
        fprintf(stderr, "Error allocating memory for sample information\n");
        return NULL;
    }

    // Fill in the sample information structure
    info->bits_per_sample = bits_per_sample;
    info->samples_per_pixel = samples_per_pixel;
    info->extra_samples_count = extra_samples_count;

    // Close the TIFF file
    TIFFClose(tif);

    // Encrypt the sample information using OpenSSL
    EVP_CIPHER_CTX* ctx = NULL;
    int len = 0;
    unsigned char* encrypted_data = NULL;
    if (!EVP_EncryptInit(&ctx, EVP_aes_128_cbc(), encryption_command)) {
        fprintf(stderr, "Error initializing OpenSSL encryption\n");
        return NULL;
    }
    if (!EVP_EncryptUpdate(ctx, encrypted_data, &len, (unsigned char*)info, sizeof(tiff_info))) {
        fprintf(stderr, "Error encrypting sample information\n");
        return NULL;
    }

    // Return a pointer to the cipher object if successful
    return ctx;
}
