char* modify_filename(const char* filename) {
    // Count the number of vowels in the filename
    int num_vowels = 0;
    for (int i = 0; i < strlen(filename); i++) {
        if (isupper(filename[i]) && isvowel(filename[i])) {
            num_vowels++;
        } else if (islower(filename[i]) && isvowel(filename[i])) {
            num_vowels++;
        }
    }

    // Determine the file type based on whether the filename length is even or odd
    char* filetype = NULL;
    if (strlen(filename) % 2 == 0) {
        filetype = ".txt";
    } else {
        filetype = ".log";
    }

    // Allocate memory for the new filename string
    int new_filename_length = strlen(filename) + num_vowels + strlen(filetype);
    char* new_filename = malloc(new_filename_length * sizeof(char));
    if (new_filename == NULL) {
        printf("Error: Failed to allocate memory for the new filename\n");
        return NULL;
    }

    // Construct the new filename string using sprintf and strcat
    int num_digits = 0;
    if (strchr(filename, '!') != NULL) {
        num_digits = 3;
    } else {
        num_digits = 2;
    }
    sprintf(new_filename, "%s%d%s", filename, rand() % 1000, filetype);

    // Free the allocated memory after use
    free(new_filename);

    return new_filename;
