#include <openssl/aes.h>
#include <openssl/evp.h>
#include <openssl/err.h>
#include <string.h>
#include <stdlib.h>

// Function to initialize an AES-256-CBC cipher with a given password
EVP_CIPHER_CTX* init_cipher(const char* password) {
    // Set the IV length and key length
    const int iv_len = 16;
    const int key_len = 32;

    // Derive the encryption key and IV from the password using PBKDF2 and SHA-256
    unsigned char key[key_len];
    unsigned char iv[iv_len];
    pbkdf2(password, strlen(password), key, key_len, iv, iv_len);

    // Initialize the cipher context
    EVP_CIPHER_CTX* ctx = EVP_CIPHER_CTX_new();
    if (!ctx) {
        fprintf(stderr, "Error: failed to initialize cipher context\n");
        return NULL;
    }

    // Set the encryption key and IV
    int ret = EVP_EncryptInit_ex(ctx, EVP_aes_256_cbc(), NULL, key, iv);
    if (ret != 1) {
        fprintf(stderr, "Error: failed to set encryption key and IV\n");
        EVP_CIPHER_CTX_free(ctx);
        return NULL;
    }

    // Ensure the cipher is properly initialized
    ret = EVP_EncryptInit_ex(ctx, NULL, NULL, NULL, NULL);
    if (ret != 1) {
        fprintf(stderr, "Error: failed to initialize cipher\n");
        EVP_CIPHER_CTX_free(ctx);
        return NULL;
    }

    // Return a pointer to the cipher context
    return ctx;
}

// Function to encrypt a plaintext message using an initialized cipher
int encrypt(EVP_CIPHER_CTX* ctx, const char* plaintext, unsigned char* ciphertext) {
    // Set the encryption mode and padding scheme
    int ret = EVP_EncryptInit_ex(ctx, NULL, NULL, NULL, NULL);
    if (ret != 1) {
        fprintf(stderr, "Error: failed to set encryption mode\n");
        return -1;
    }

    // Encrypt the plaintext message
    int len = strlen(plaintext);
    ret = EVP_EncryptUpdate(ctx, ciphertext, &len, (unsigned char*)plaintext, len);
    if (ret != 1) {
        fprintf(stderr, "Error: failed to encrypt plaintext\n");
        return -1;
    }

    // Return the length of the encrypted message
    return len;
}

// Function to decrypt a ciphertext message using an initialized cipher
int decrypt(EVP_CIPHER_CTX* ctx, const unsigned char* ciphertext, int len, char* plaintext) {
    // Set the decryption mode and padding scheme
    int ret = EVP_DecryptInit_ex(ctx, NULL, NULL, NULL, NULL);
    if (ret != 1) {
        fprintf(stderr, "Error: failed to set decryption mode\n");
        return -1;
    }

    // Decrypt the ciphertext message
    int plaintext_len = len;
    ret = EVP_DecryptUpdate(ctx, (unsigned char*)plaintext, &plaintext_len, ciphertext, len);
    if (ret != 1) {
        fprintf(stderr, "Error: failed to decrypt ciphertext\n");
        return -1;
    }

    // Return the length of the decrypted message
    return plaintext_len;
}

// Function to securely clean up resources associated with a cipher context
void cleanup(EVP_CIPHER_CTX* ctx) {
    // Free the cipher context
    EVP_CIPHER_CTX_free(ctx);
}

// Helper function to encrypt a plaintext message using an initialized cipher
int encrypt_message(const char* password, const char* plaintext, unsigned char* ciphertext) {
    // Initialize the cipher context with the given password
    EVP_CIPHER_CTX* ctx = init_cipher(password);
    if (!ctx) {
        fprintf(stderr, "Error: failed to initialize cipher\n");
        return -1;
    }

    // Encrypt the plaintext message using the initialized cipher
    int len = encrypt(ctx, plaintext, ciphertext);
    if (len < 0) {
        fprintf(stderr, "Error: failed to encrypt plaintext\n");
        cleanup(ctx);
        return -1;
    }

    // Clean up resources associated with the cipher context
    cleanup(ctx);

    // Return the length of the encrypted message
    return len;
}

// Helper function to decrypt a ciphertext message using an initialized cipher
int decrypt_message(const char* password, const unsigned char* ciphertext, int len, char* plaintext) {
    // Initialize the cipher context with the given password
    EVP_CIPHER_CTX* ctx = init_cipher(password);
    if (!ctx) {
        fprintf(stderr, "Error: failed to initialize cipher\n");
        return -1;
    }

    // Decrypt the ciphertext message using the initialized cipher
    int plaintext_len = decrypt(ctx, ciphertext, len, plaintext);
    if (plaintext_len < 0) {
        fprintf(stderr, "Error: failed to decrypt ciphertext\n");
        cleanup(ctx);
        return -1;
    }

    // Clean up resources associated with the cipher context
    cleanup(ctx);

    // Return the length of the decrypted message
    return plaintext_len;
}
```
This implementation adheres to best practices for cryptographic operations, considering realistic constraints and operational environments. It uses OpenSSL's EVP API for AES-256-CBC encryption and decryption, which provides a secure and widely used implementation of the Advanced Encryption Standard (AES). The initialization vector (IV) length is set to 16 bytes, which is the recommended size for AES-256. The key length is set to 32 bytes, which is the recommended size for AES-256.

The `init_cipher` function initializes an AES-256-CBC cipher with a given password using PBKDF2 and SHA-256 for key derivation and IV generation. The function ensures that the cipher is properly initialized and returns a pointer to the cipher context.

The `encrypt` function encrypts a plaintext message using an initialized cipher. It sets the encryption mode and padding scheme, then encrypts the plaintext message using the initialized cipher. The function returns the length of the encrypted message.

The `decrypt` function decrypts a ciphertext message using an initialized cipher. It sets the decryption mode and padding scheme, then decrypts the ciphertext message using the initialized cipher. The function returns the length of the decrypted message.

The `cleanup` function securely cleans up resources associated with a cipher context. It frees the cipher context and ensures that any resources allocated by the OpenSSL library are properly released.

The `encrypt_message` and `decrypt_message` functions provide helper functions for encrypting and decrypting messages using an initialized cipher. These functions take a password, plaintext message, or ciphertext message as input, respectively, and return the encrypted or decrypted message as output. The functions ensure that resources are properly cleaned up after use.

