int process_directory(const char* directory, const char* config_file) {
    // Open the configuration file and read its contents
    FILE* config = fopen(config_file, "r");
    if (!config) {
        perror("Error opening configuration file");
        return 1;
    }
    char* config_contents = malloc(sizeof(char) * 1024);
    size_t read_bytes = fread(config_contents, sizeof(char), 1024, config);
    if (read_bytes == 0) {
        perror("Error reading configuration file");
        return 1;
    }
    // Close the configuration file
    fclose(config);

    // Open the directory and iterate over its contents
    DIR* dir = opendir(directory);
    if (!dir) {
        perror("Error opening directory");
        return 1;
    }
    struct dirent* entry;
    while ((entry = readdir(dir)) != NULL) {
        // Check if the file is an image
        char* ext = strrchr(entry->d_name, '.');
        if (ext && !strcmp(ext, ".jpg") || !strcmp(ext, ".jpeg") || !strcmp(ext, ".png")) {
            // Convert the image to grayscale using the third-party library
            char* file_path = malloc(sizeof(char) * 1024);
            sprintf(file_path, "%s/%s", directory, entry->d_name);
            int result = convert_to_grayscale(file_path, config_contents);
            if (result != 0) {
                perror("Error converting image to grayscale");
                return 1;
            }
            // Compress the image using a third-party library
            char* compressed_file_path = malloc(sizeof(char) * 1024);
            sprintf(compressed_file_path, "%s/%s", directory, entry->d_name);
            result = compress_image(compressed_file_path, config_contents);
            if (result != 0) {
                perror("Error compressing image");
                return 1;
            }
            // Save the processed image back to the same directory
            char* new_file_name = malloc(sizeof(char) * 1024);
            sprintf(new_file_name, "%s/%s", directory, entry->d_name);
            result = save_image(compressed_file_path, new_file_name);
            if (result != 0) {
                perror("Error saving processed image");
                return 1;
            }
        }
    }
    // Close the directory
    closedir(dir);

    // Return success
    return 0;
}
