    public static async Task<Process> AddAndStartWebSite(string directoryPath, string siteName)
    {
        // Verify that the directory path is valid and accessible
        if (!Directory.Exists(directoryPath))
        {
            return null;
        }

        // Check if a web.config file exists in the specified directory
        var configFile = Path.Combine(directoryPath, "web.config");
        if (!File.Exists(configFile))
        {
            return null;
        }

        // Create a new process to start the website
        var process = new Process();
        process.StartInfo.FileName = "cmd";
        process.StartInfo.Arguments = $"/c \"cd {directoryPath} && dotnet run\"";
        process.StartInfo.UseShellExecute = false;
        process.StartInfo.RedirectStandardOutput = true;
        process.StartInfo.CreateNoWindow = true;

        // Start the website and wait for it to start up
        try
        {
            process.Start();
            await Task.Delay(5000); // Wait for 5 seconds for the website to start up
        }
        catch (Exception ex)
        {
            Console.WriteLine($"Error starting website: {ex.Message}");
            return null;
        }

        // Return the process object if the website started successfully
        return process;
    }
}
