// Define the structure for the configuration
typedef struct {
    char *token;
    ConnectionSettings *connection_settings;
    void (*callback)(EventType);
} Configuration;

// Define the structure for the connection settings
typedef struct {
    char *server_address;
    int port;
} ConnectionSettings;

// Define the enum for the event types
enum EventType {
    EVENT_CONNECTED,
    EVENT_DISCONNECTED,
    EVENT_DATA_RECEIVED,
    EVENT_DATA_SENT,
};

int validate_configuration(Configuration *config) {
    // Check if the authentication token is neither empty nor NULL
    if (config->token == NULL || strlen(config->token) == 0) {
        return ERROR_INVALID_TOKEN;
    }

    // Verify that the connection settings have a valid server address and port configured
    if (config->connection_settings->server_address == NULL || config->connection_settings->port <= 0) {
        return ERROR_INVALID_CONNECTION;
    }

    // Confirm that the callback function pointer is not NULL and can handle the expected event type
    if (config->callback == NULL || !can_handle_event(config->callback, EVENT_CONNECTED)) {
        return ERROR_INVALID_CALLBACK;
    }

    // Return a success code if all conditions are met
    return 0;
}

// Define the function to check if a callback function can handle an event type
int can_handle_event(void (*callback)(EventType), EventType event) {
    switch (event) {
        case EVENT_CONNECTED:
            return callback != NULL && callback == connected;
        case EVENT_DISCONNECTED:
            return callback != NULL && callback == disconnected;
        case EVENT_DATA_RECEIVED:
            return callback != NULL && callback == data_received;
        case EVENT_DATA_SENT:
            return callback != NULL && callback == data_sent;
    }
}
