public static string DecryptAndDetermineWeaknesses(string encryptedMessage, string key, string iv)
{
    // Decrypt the message using Triple DES encryption with the given key and initialization vector (IV)
    byte[] decryptedBytes = TripleDES.Decrypt(Convert.FromBase64String(encryptedMessage), Encoding.UTF8.GetBytes(key), Encoding.UTF8.GetBytes(iv));
    string decryptedMessage = Encoding.UTF8.GetString(decryptedBytes);

    // Determine the weaknesses of the Pokemon based on its type
    switch (GetPokemonType(decryptedMessage))
    {
        case "Fire":
            return "Weak to Water, Strong to Ground";
        case "Water":
            return "Weak to Fire, Strong to Electric";
        case "Electric":
            return "Weak to Water, Strong to Ice";
        case "Ice":
            return "Weak to Electric, Strong to Ground";
        default:
            throw new Exception("Invalid Pokemon type");
    }
}

private static string GetPokemonType(string message)
{
    // Retrieve the Pokemon's type and name using an external library
    var pokemonDetails = GetPokemonDetails(message);
    return pokemonDetails.Type;
}

private static Dictionary<string, string> GetPokemonDetails(string message)
{
    // Create a new file using the subprocess module to execute sed commands with the modifications
    var process = new Process();
    process.StartInfo.FileName = "sed";
    process.StartInfo.Arguments = "-i 's/.*\\(PokemonType: [A-Za-z ]*\\).*/\\1/'";
    process.StartInfo.UseShellExecute = false;
    process.StartInfo.RedirectStandardOutput = true;
    process.Start();

    // Read the output of the sed command and return it as a dictionary
    var output = process.StandardOutput.ReadToEnd().Trim();
    var details = new Dictionary<string, string>();
    foreach (var line in output.Split('\n'))
    {
        var parts = line.Split(':');
        if (parts.Length == 2)
        {
            details[parts[0].Trim()] = parts[1].Trim();
        }
    }

    return details;
}
