public static byte[] Decrypt(byte[] ciphertext, byte[] key, byte[] iv, PaddingMode padding)
{
    // Validate input parameters
    if (ciphertext == null || ciphertext.Length == 0)
        throw new ArgumentException("Ciphertext cannot be empty", nameof(ciphertext));
    if (key == null || key.Length == 0)
        throw new ArgumentException("Key cannot be empty", nameof(key));
    if (iv == null || iv.Length == 0)
        throw new ArgumentException("IV cannot be empty", nameof(iv));
    if (!Enum.IsDefined(typeof(PaddingMode), padding))
        throw new ArgumentException($"Invalid padding mode: {padding}", nameof(padding));

    // Create AES-CBC decryptor
    using var aes = new AesCbcDecryptor(key, iv);

    // Decrypt ciphertext
    byte[] plaintext;
    try
    {
        plaintext = aes.Decrypt(ciphertext, padding);
    }
    catch (Exception ex)
    {
        // Log error and return null
        Console.WriteLine($"Error decrypting ciphertext: {ex.Message}");
        return null;
    }

    // Return plaintext
    return plaintext;
}
