    private static readonly Dictionary<string, object> _cache = new Dictionary<string, object>();

    public static T LoadConfiguration<T>(string filePath) where T : new()
    {
        if (_cache.ContainsKey(filePath))
        {
            return (T)_cache[filePath];
        }

        XDocument doc = XDocument.Load(filePath);
        XmlSerializer serializer = new XmlSerializer(typeof(T));
        T config = (T)serializer.Deserialize(doc.CreateReader());

        if (!ValidateConfiguration(config))
        {
            throw new Exception("Invalid configuration data");
        }

        _cache[filePath] = config;
        return config;
    }

