const crypto = require('crypto');
const { EVP_CIPHER } = crypto;

function validateOAuth2AccessToken(token) {
  try {
    const tokenObj = JSON.parse(token);
    if (!tokenObj.access_token || !tokenObj.expires_in || !tokenObj.token_type) {
      return false;
    }
    if (tokenObj.token_type !== 'Bearer') {
      return false;
    }
    if (typeof tokenObj.expires_in !== 'number' || tokenObj.expires_in < 0) {
      return false;
    }
    if (tokenObj.refresh_token && typeof tokenObj.refresh_token !== 'string') {
      return false;
    }
    return true;
  } catch (err) {
    return false;
  }
}

function getEVP_CIPHER(mode, key, iv) {
  const cipher = crypto.createCipheriv('des-' + mode, key, iv);
  return new EVP_CIPHER(cipher);
}

function encryptData(data, key, iv, mode) {
  const cipher = getEVP_CIPHER(mode, key, iv);
  return cipher.update(data, 'utf8', 'hex');
}

function decryptData(data, key, iv, mode) {
  const decipher = crypto.createDecipheriv('des-' + mode, key, iv);
  return decipher.update(data, 'hex', 'utf8');
}

function encryptDataWithNullEncryption(data, key, iv, mode) {
  const cipher = getEVP_CIPHER(mode, key, iv);
  return cipher.update(data, 'utf8', 'hex');
}

function decryptDataWithNullEncryption(data, key, iv, mode) {
  const decipher = crypto.createDecipheriv('des-' + mode, key, iv);
  return decipher.update(data, 'hex', 'utf8');
}

module.exports = {
  validateOAuth2AccessToken,
  getEVP_CIPHER,
  encryptData,
  decryptData,
  encryptDataWithNullEncryption,
  decryptDataWithNullEncryption,
};
