        if (CAMELLIA_set_encrypt_key(buf, &camellia_key) == 0) {
            e->property3 = buf;
            fprintf(logfile, "Added Camellia key to edge %d\n", j);
        } else {
            fprintf(errorfile, "Error adding Camellia key to edge %d\n", j);
        }
    }
    for (i = 0; i < num_vertices; i++) {
        vertex *v = g->get_vertex(g, i);
        MD5_CTX md5_ctx;
        if (MD5_Init(&md5_ctx) == 1) {
            v->property4 = buf;
            fprintf(logfile, "Added MD5 hash to vertex %d\n", i);
        } else {
            fprintf(errorfile, "Error adding MD5 hash to vertex %d\n", i);
        }
    }
    for (j = 0; j < num_edges; j++) {
        edge *e = g->get_edge(g, j);
        SHA_CTX sha_ctx;
        if (SHA1_Init(&sha_ctx) == 1) {
            e->property4 = buf;
