use reqwest::Client;

#[derive(Debug, Clone)]
struct ApiConfig {
    endpoint: String,
    timeout: Duration,
    retry_limit: usize,
}

impl Default for ApiConfig {
    fn default() -> Self {
        Self {
            endpoint: "https://example.com/api".to_string(),
            timeout: Duration::from_secs(10),
            retry_limit: 3,
        }
    }
}

#[derive(Debug)]
struct ApiError {
    message: String,
}

impl std::error::Error for ApiError {}

impl std::fmt::Display for ApiError {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        write!(f, "API error: {}", self.message)
    }
}

#[derive(Debug)]
struct DataFetcher {
    config: ApiConfig,
    client: Client,
}

impl DataFetcher {
    fn new() -> Self {
        let config = ApiConfig::default();
        let client = reqwest::Client::new();

        Self { config, client }
    }

    async fn fetch_data(&self) -> Result<String, ApiError> {
        let mut retry_count = 0;
        loop {
            match self.client.get(self.config.endpoint.clone()).send().await {
                Ok(response) => {
                    if response.status() == reqwest::StatusCode::OK {
                        return Ok(response.text().await?);
                    } else {
                        retry_count += 1;
                        if retry_count > self.config.retry_limit {
                            return Err(ApiError {
                                message: format!("Failed to fetch data from API after {} retries", retry_count),
                            });
                        }
                    }
                }
                Err(error) => {
                    retry_count += 1;
                    if retry_count > self.config.retry_limit {
                        return Err(ApiError {
                            message: format!("Failed to fetch data from API after {} retries", retry_count),
                        });
                    }
                }
            }
        }
    }
}

#[derive(Debug)]
struct Processor {
    config: ApiConfig,
    client: Client,
}

impl Processor {
    fn new() -> Self {
        let config = ApiConfig::default();
        let client = reqwest::Client::new();

        Self { config, client }
    }

    async fn process_data(&self, data: String) -> Result<(), ApiError> {
        // Implement the processing logic here
        Ok(())
    }
}

#[tokio::main]
async fn main() {
    let args: Vec<String> = env::args().collect();
    if args.len() < 2 {
        eprintln!("Usage: {} [mode]", args[0]);
        process::exit(1);
    }

    let mode = &args[1];
    match mode.as_str() {
        "fetch" => {
            let fetcher = DataFetcher::new();
            let data = fetcher.fetch_data().await?;
            println!("{}", data);
        }
        "process" => {
            let processor = Processor::new();
            let data = processor.fetch_data().await?;
            processor.process_data(data).await?;
        }
        _ => {
            eprintln!("Invalid mode: {}", mode);
            process::exit(1);
        }
    }
}
```
