use std::collections::HashMap;
use std::sync::{Arc, Mutex};
use std::thread::sleep;
use std::time::Duration;

struct Cache {
    cache: HashMap<String, String>,
    size: usize,
    eviction_policy: EvictionPolicy,
}

enum EvictionPolicy {
    LRU,
    LFU,
    Random,
}

impl Cache {
    fn new(size: usize, eviction_policy: EvictionPolicy) -> Self {
        let cache = HashMap::new();
        Self {
            cache,
            size,
            eviction_policy,
        }
    }

    fn get(&mut self, key: &str) -> Option<String> {
        match self.cache.get(key) {
            Some(value) => Some(value.clone()),
            None => None,
        }
    }

    fn put(&mut self, key: String, value: String) {
        if self.cache.len() >= self.size {
            match self.eviction_policy {
                EvictionPolicy::LRU => {
                    let mut keys = Vec::new();
                    for (k, _) in &self.cache {
                        keys.push(k);
                    }
                    let evicted_key = keys[0];
                    self.cache.remove(&evicted_key);
                }
                EvictionPolicy::LFU => {
                    // TODO: implement LFU eviction policy
                }
                EvictionPolicy::Random => {
                    let mut rng = rand::thread_rng();
                    let evicted_key = self.cache.keys().choose(&mut rng).unwrap();
                    self.cache.remove(evicted_key);
                }
            }
        }
        self.cache.insert(key, value);
    }
}

fn main() {
    let cache = Arc::new(Mutex::new(Cache::new(100, EvictionPolicy::LRU)));
    let mut threads = Vec::new();
    for i in 0..5 {
        let cache_clone = cache.clone();
        threads.push(std::thread::spawn(move || {
            loop {
                let key = format!("key{}", i);
                let value = format!("value{}", i);
                cache_clone.lock().unwrap().put(key, value);
                sleep(Duration::from_secs(1));
            }
        }));
    }
    for thread in threads {
        thread.join();
    }
}
```
This code creates a persistent cache for file metadata using a `HashMap` and a mutex to ensure concurrent access is safe. The cache size is limited by the specified configuration file, and the eviction policy is determined by the `EvictionPolicy` enum. The `get` method returns the value associated with the given key if it exists, or `None` otherwise. The `put` method adds a new entry to the cache if there is space available, or evicts an existing entry according to the specified eviction policy if necessary.

The `main` function creates five threads that repeatedly insert and retrieve entries from the cache using the `get` and `put` methods. The `Arc` and `Mutex` types are used to share the cache between threads safely, and the `sleep` function is used to simulate a background task that periodically cleans up unused entries in the cache.']

