// Function to dynamically rename a file based on specific criteria derived from the original filename
void rename_file(const char* original_filename, int num_digits, const char* new_file_type) {
    // Check if the input parameters are valid
    if (original_filename == NULL || num_digits < 0 || new_file_type == NULL) {
        fprintf(stderr, "Invalid input parameters\n");
        return;
    }

    // Get the original filename and extension
    const char* dot = strrchr(original_filename, '.');
    if (dot == NULL) {
        fprintf(stderr, "Original filename does not have an extension\n");
        return;
    }
    size_t orig_filename_len = dot - original_filename;
    const char* orig_extension = dot + 1;

    // Build the new filename and extension
    size_t new_filename_len = orig_filename_len + num_digits + strlen(new_file_type);
    if (new_filename_len > MAX_FILENAME_LENGTH) {
        fprintf(stderr, "New filename exceeds maximum length\n");
        return;
    }
    char* new_filename = malloc(new_filename_len + 1);
    snprintf(new_filename, new_filename_len + 1, "%.*s%0*d.%s", (int)orig_filename_len, original_filename, num_digits, 0, orig_extension);

    // Rename the file
    if (rename(original_filename, new_filename) != 0) {
        fprintf(stderr, "Failed to rename file: %s\n", strerror(errno));
        free(new_filename);
        return;
    }

    // Clean up
    free(new_filename);
}
