}

// Function to handle large-scale deployments, ensuring that it can scale horizontally by supporting distributed processing across multiple nodes
void* scale_horizontally(void* args) {
    struct config* config = (struct config*)args;
    while (true) {
        // Check if there are any files in the queue that need to be processed
        pthread_mutex_lock(&queue_mutex);
        if (queue_size > 0) {
