}

// Function to support dynamic updates to the configuration file without restarting the processing pipeline, allowing for on-the-fly changes to transcoding and compression settings
void* update_configuration(void* args) {
    struct config* config = (struct config*)args;
    while (true) {
        // Check if there are any files in the queue that need to be processed
        pthread_mutex_lock(&queue_mutex);
        if (queue_size > 0) {
