}

int main(int argc, char* argv[]) {
    if (argc != 5) {
        printf("Usage: %s <directory> <configuration_file> <compression_level> <output_format>\n", argv[0]);
        return 1;
    }

    // Parse the command-line arguments
    char* directory = argv[1];
    char* configuration_file = argv[2];
    int compression_level = atoi(argv[3]);
    int output_format = atoi(argv[4]);

    // Initialize the configuration struct
    struct config config;
    config.directory = directory;
    config.configuration_file = configuration_file;
    config.compression_level = compression_level;
    config.output_format = output_format;

    // Create a queue for storing files to process
    pthread_mutex_init(&queue_mutex, NULL);
    pthread_cond_init(&queue_empty, NULL);
    queue = (char**)malloc(sizeof(char*) * 1024);
    queue_size = 0;

    // Create a thread for handling race conditions when multiple threads are used to process files simultaneously
    pthread_t race_conditions_thread;
    pthread_create(&race_conditions_thread, NULL, handle_race_conditions, &config);

    // Create a thread for managing efficient resource management to prevent system overload
    pthread_t resources_management_thread;
    pthread_create(&resources_management_thread, NULL, manage_resources, &config);

    // Create a thread for detecting and handling incomplete or corrupted files during processing
    pthread_t corruption_detection_thread;
    pthread_create(&corruption_detection_thread, NULL, detect_corruption, &config);

