    // Handle potential delays and incomplete data efficiently

    // Dynamically adjust the number of records based on available memory while maintaining performance
    size_t num_records_adjusted = *num_records;
    if (total_memory > max_memory / 2) {
        num_records_adjusted = max_memory / sizeof(record_t);
    }
    *num_records = num_records_adjusted;

    // Optimize the memory copying process from the initialized 'record' array to a separate buffer
    record_t *buffer = (record_t *)malloc(num_records_adjusted * sizeof(record_t));
    if (buffer == NULL) {
        printf("Error: Failed to allocate memory for buffer\n");
        free(*records);
        return;
    }
    memcpy(buffer, *records, num_records_adjusted * sizeof(record_t));

    // Handle potential memory fragmentation and ensure efficient deallocation of resources when the function is complete
