// Define the cryptographic operation to perform
enum CryptoOperation {
    ENCRYPT,
    DECRYPT,
    HASH
};

// Define the character set for generating random strings
const char *char_set = "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789";

// Function to perform a specified cryptographic operation on a given string parameter
void crypto_operation(char *input, enum CryptoOperation op) {
    // Check if the input is null or empty
    if (input == NULL || strlen(input) == 0) {
        printf("Error: Input cannot be null or empty\n");
        return;
    }

    // Perform the specified cryptographic operation on the input string
    switch (op) {
        case ENCRYPT:
            // Encrypt the input string using AES-256-CBC with a random initialization vector
            EVP_EncryptInit_ex(NULL, EVP_aes_256_cbc(), NULL, NULL, NULL);
            EVP_EncryptUpdate(NULL, input, strlen(input));
            break;
        case DECRYPT:
            // Decrypt the input string using AES-256-CBC with a random initialization vector
            EVP_DecryptInit_ex(NULL, EVP_aes_256_cbc(), NULL, NULL, NULL);
            EVP_DecryptUpdate(NULL, input, strlen(input));
            break;
        case HASH:
            // Hash the input string using SHA-256
            EVP_DigestInit_ex(NULL, EVP_sha256(), NULL);
            EVP_DigestUpdate(NULL, input, strlen(input));
            break;
    }
}

// Function to securely hash a large file up to 1 GB in size given its path
void hash_file(char *path) {
    // Check if the file exists and is readable
    FILE *fp = fopen(path, "r");
    if (fp == NULL) {
        printf("Error: File does not exist or is not readable\n");
        return;
    }

    // Define the buffer size for reading the file in chunks
    const int BUFFER_SIZE = 1024 * 1024; // 1 MB

    // Initialize the hash context and set the input file
    EVP_MD_CTX *ctx = EVP_MD_CTX_create();
    EVP_DigestInit_ex(ctx, EVP_sha256(), NULL);
    EVP_DigestUpdate(ctx, fp);

    // Process the file in chunks to manage memory usage effectively and provide thread-safe operations if multiple instances execute concurrently
    char buffer[BUFFER_SIZE];
    while (fread(buffer, 1, BUFFER_SIZE, fp) > 0) {
        EVP_DigestUpdate(ctx, buffer, BUFFER_SIZE);
    }

    // Close the input file and get the hash result
    fclose(fp);
    unsigned char hash[EVP_MAX_MD_SIZE];
    int hash_len = EVP_DigestFinal_ex(ctx, hash, NULL);

    // Print the hash result in hexadecimal format
    for (int i = 0; i < hash_len; i++) {
        printf("%02x", hash[i]);
    }

    // Clean up the hash context and free the memory
    EVP_MD_CTX_destroy(ctx);
}

// Function to generate a secure random string of specified length using a provided character set
void generate_random_string(int length, const char *char_set) {
    // Check if the character set is null or empty
    if (char_set == NULL || strlen(char_set) == 0) {
        printf("Error: Character set cannot be null or empty\n");
        return;
    }

    // Define the buffer size for generating random strings in chunks
    const int BUFFER_SIZE = 1024 * 1024; // 1 MB

    // Initialize the RNG context and set the character set
    RAND_bytes(NULL, NULL);
    RAND_seed(char_set, strlen(char_set));

    // Generate the random string in chunks to manage memory usage effectively and provide thread-safe operations if multiple instances execute concurrently
    char buffer[BUFFER_SIZE];
    while (length > 0) {
        int chunk_size = length < BUFFER_SIZE ? length : BUFFER_SIZE;
        RAND_bytes(buffer, chunk_size);
        printf("%s", buffer);
        length -= chunk_size;
    }
}
