// Define the AES-256-CBC cipher context structure
typedef struct {
    EVP_CIPHER_CTX *ctx;
    unsigned char key[32];
    unsigned char iv[16];
} aes256cbc_ctx;

// Define the helper functions for encrypting and decrypting messages
void aes256cbc_encrypt(const unsigned char *plaintext, size_t plaintext_len, unsigned char *ciphertext) {
    // Initialize the cipher context with the derived key and IV
    EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();
    EVP_EncryptInit(ctx, EVP_aes_256_cbc(), NULL, &key);
    EVP_CIPHER_CTX_set_padding(ctx, 0);

    // Encrypt the plaintext message using AES-256-CBC
    int len = 0;
    while (len < plaintext_len) {
        int chunk_size = EVP_EncryptUpdate(ctx, ciphertext + len, &plaintext[len], plaintext_len - len);
        if (chunk_size <= 0) {
            break;
        }
        len += chunk_size;
    }

    // Finalize the encryption process and get the ciphertext length
    int ciphertext_len = EVP_EncryptFinal(ctx, ciphertext + len, &plaintext[len]);
    if (ciphertext_len <= 0) {
        return;
    }
    len += ciphertext_len;

    // Clean up the cipher context and return the encrypted message
    EVP_CIPHER_CTX_free(ctx);
    return len;
}

void aes256cbc_decrypt(const unsigned char *ciphertext, size_t ciphertext_len, unsigned char *plaintext) {
    // Initialize the cipher context with the derived key and IV
    EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();
    EVP_DecryptInit(ctx, EVP_aes_256_cbc(), NULL, &key);
    EVP_CIPHER_CTX_set_padding(ctx, 0);

    // Decrypt the ciphertext message using AES-256-CBC
    int len = 0;
    while (len < ciphertext_len) {
        int chunk_size = EVP_DecryptUpdate(ctx, plaintext + len, &ciphertext[len], ciphertext_len - len);
        if (chunk_size <= 0) {
            break;
        }
        len += chunk_size;
    }

    // Finalize the decryption process and get the plaintext length
    int plaintext_len = EVP_DecryptFinal(ctx, plaintext + len, &ciphertext[len]);
    if (plaintext_len <= 0) {
        return;
    }
    len += plaintext_len;

    // Clean up the cipher context and return the decrypted message
    EVP_CIPHER_CTX_free(ctx);
    return len;
}

// Define the main initialization function for AES-256-CBC encryption
void aes256cbc_init(const unsigned char *password, size_t password_len) {
    // Derive the encryption key and IV from the password using PBKDF2 and SHA-256
    EVP_PKEY_CTX *pctx = EVP_PKEY_CTX_new_id(EVP_PKEY_HMAC, NULL);
    EVP_PKEY_derive_init(pctx);
    EVP_PKEY_CTX_set_mac_key(pctx, EVP_sha256(), password, password_len);
    EVP_PKEY_derive(pctx, key, 32);
    EVP_PKEY_CTX_free(pctx);

    // Initialize the cipher context with the derived key and IV
    ctx = EVP_CIPHER_CTX_new();
    EVP_EncryptInit(ctx, EVP_aes_256_cbc(), NULL, &key);
    EVP_CIPHER_CTX_set_padding(ctx, 0);
}

// Define the main cleanup function for AES-256-CBC encryption
void aes256cbc_cleanup() {
    // Clean up the cipher context and free any allocated memory
    EVP_CIPHER_CTX_free(ctx);
}
