#include <stdlib.h>
#include <string.h>
#include <stdio.h>
#include <assert.h>

// Define the entry structure
typedef struct {
    unsigned int id;
    double timestamp;
    char* metadata;
} entry_t;

// Define the cache structure
typedef struct {
    entry_t** entries;
    size_t capacity;
    size_t count;
} cache_t;

// Initialize the cache with a given capacity
void init_cache(cache_t* cache, size_t capacity) {
    assert(cache != NULL);
    cache->entries = (entry_t**)malloc(sizeof(entry_t*) * capacity);
    cache->capacity = capacity;
    cache->count = 0;
}

// Add an entry to the cache
void add_entry(cache_t* cache, entry_t* entry) {
    assert(cache != NULL && entry != NULL);
    if (cache->count == cache->capacity) {
        // Reallocate memory for the entries array
        cache->entries = (entry_t**)realloc(cache->entries, sizeof(entry_t*) * (cache->capacity + 1));
        assert(cache->entries != NULL);
        cache->capacity++;
    }
    // Add the entry to the end of the array
    cache->entries[cache->count++] = entry;
}

// Remove an entry from the cache
void remove_entry(cache_t* cache, size_t index) {
    assert(cache != NULL && index < cache->count);
    // Shift all entries after the specified index to the left
    for (size_t i = index; i < cache->count - 1; i++) {
        cache->entries[i] = cache->entries[i + 1];
    }
    // Decrement the count of entries in the cache
    cache->count--;
}

// Retrieve an entry from the cache by its index
entry_t* get_entry(cache_t* cache, size_t index) {
    assert(cache != NULL && index < cache->count);
    return cache->entries[index];
}

// Free all memory allocated for the cache
void free_cache(cache_t* cache) {
    assert(cache != NULL);
    // Free each entry in the cache
    for (size_t i = 0; i < cache->count; i++) {
        free(cache->entries[i]);
    }
    // Free the entries array
    free(cache->entries);
}

// Define the function to manage memory allocation and initialization for a dynamic collection of 'entry' structures
void manage_memory(size_t capacity, size_t* count) {
    assert(capacity > 0 && count != NULL);
    // Initialize the cache with the specified capacity
    cache_t cache;
    init_cache(&cache, capacity);
    *count = 0;

    while (*count < capacity) {
        // Fetch an entry from the external data source
        entry_t* entry = fetch_entry();

        if (entry != NULL) {
            // Add the entry to the cache
            add_entry(&cache, entry);
            *count = cache.count;
        } else {
            // Handle error condition
            printf("Error: failed to fetch entry from external data source\n");
        }
    }

    while (*count > 0) {
        // Retrieve the oldest entry in the cache
        size_t index = *count - 1;
        entry_t* entry = get_entry(&cache, index);

        if (entry != NULL) {
            // Remove the entry from the cache
            remove_entry(&cache, index);
            *count = cache.count;

            // Free the memory allocated for the entry
            free(entry);
        } else {
            // Handle error condition
            printf("Error: failed to retrieve entry from cache\n");
        }
    }

    // Free all memory allocated for the cache
    free_cache(&cache);
}
