using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using System.Xml;
using System.Xml.XPath;

namespace UtilityLibrary
{
    public static class XmlUtilities
    {
        private const int CHUNK_SIZE = 1024 * 1024; // 1 MB

        public static List<XElement> ParseXml(string xmlFilePath, string xPathQuery)
        {
            return ParseXml(xmlFilePath, xPathQuery, null);
        }

        public static List<XElement> ParseXml(string xmlFilePath, string xPathQuery, string namespaceUri)
        {
            if (!File.Exists(xmlFilePath))
                throw new FileNotFoundException("XML file not found", xmlFilePath);

            var doc = new XmlDocument();
            using (var reader = new StreamReader(xmlFilePath))
            {
                doc.Load(reader);
            }

            if (!string.IsNullOrEmpty(namespaceUri) && !doc.DocumentElement.HasAttribute("xmlns"))
                throw new Exception("Namespace is not defined in the document");

            var navigator = doc.CreateNavigator();
            var xPathNodeIterator = navigator.Select(xPathQuery);

            var elements = new List<XElement>();
            while (xPathNodeIterator.MoveNext())
            {
                var element = xPathNodeIterator.Current;
                if (element != null)
                    elements.Add(new XElement(element));
            }

            return elements;
        }

        public static string GenerateRandomString(int length, string characterSet)
        {
            var random = new Random();
            var builder = new StringBuilder();
            for (var i = 0; i < length; i++)
            {
                var index = random.Next(characterSet.Length);
                builder.Append(characterSet[index]);
            }
            return builder.ToString();
        }

        public static string HashFile(string filePath, int chunkSize)
        {
            if (!File.Exists(filePath))
                throw new FileNotFoundException("File not found", filePath);

            var hash = new SHA256Managed();
            using (var stream = new FileStream(filePath, FileMode.Open, FileAccess.Read, FileShare.ReadWrite))
            {
                var buffer = new byte[chunkSize];
                int read;
                while ((read = stream.Read(buffer, 0, chunkSize)) > 0)
                {
                    hash.TransformBlock(buffer, 0, read, null, 0);
                }
                hash.TransformFinalBlock(buffer, 0, 0);
            }
            return Convert.ToBase64String(hash.Hash);
        }
    }
}
```
