    if (fd == -1) {
        LOG("Error opening file for writing: %s", strerror(errno));
        return NULL;
    }
    ssize_t bytes_written = write(fd, buffer, compressed_size);
    if (bytes_written == -1) {
        LOG("Error writing to file: %s", strerror(errno));
        return NULL;
    }
    if (close(fd)) {
        LOG("Error closing file: %s", strerror(errno));
        return NULL;
    }

    // Free memory allocated for buffer and metadata string
    free(buffer);
    free(metadata);

    // Return success
