                // Fetch data from each source
                airQualityClient.FetchData();
                pollenCountsClient.FetchData();
                noiseLevelsClient.FetchData();

                // Update dashboard with new data
                UpdateDashboard(airQualityClient.GetData(), pollenCountsClient.GetData(), noiseLevelsClient.GetData());

                // Sleep for a short period to avoid overloading the API
                System.Threading.Thread.Sleep(1000);
