import java.util.regex.Pattern;

public class CSVProcessor {
    private static final Pattern DELIMITER_PATTERN = Pattern.compile("\\s*,\\s*");
    private static final char QUOTE_CHARACTER = '"';
    private static final String ESCAPED_QUOTE = "\"\"";

    public List<String[]> processCSV(String filePath, String delimiter, char quoteCharacter) throws Exception {
        List<String[]> data = new ArrayList<>();
        try (BufferedReader reader = new BufferedReader(new FileReader(filePath))) {
            String line;
            while ((line = reader.readLine()) != null) {
                // Handle escaped quotes and quoted fields
                if (quoteCharacter == QUOTE_CHARACTER && line.contains(ESCAPED_QUOTE)) {
                    line = line.replaceAll(ESCAPED_QUOTE, "");
                }
                String[] row = DELIMITER_PATTERN.split(line);
                data.add(row);
            }
        } catch (Exception e) {
            // Handle error handling and logging
            System.out.println("Error processing CSV file: " + e.getMessage());
        }
        return data;
    }
}
```
