        // Log any anomalies and return true
        for (String deviceId : deviceStatuses.keySet()) {
            DeviceStatus status = deviceStatuses.get(deviceId);
            if (!isDeviceStatusValid(status)) {
                logAnomaly(deviceId, status);
            }
        }

        return true;
