void insert_string(forward_list<string>& list, const string& str1, const string& str2) {
    // allocate memory for arrays of 'long' and 'int' values
    long* offsets = new long[list.size()];
    int* keys = new int[list.size()];

    // initialize arrays with random values within specified range
    for (int i = 0; i < list.size(); ++i) {
        offsets[i] = rand() % 100;
        keys[i] = rand() % 100;
    }

    // allocate memory for array of 'record' structures
    record* records = new record[list.size()];

    // initialize each record with a random int value
    for (int i = 0; i < list.size(); ++i) {
        records[i].value = rand() % 100;
    }

    // search for first occurrence of str1 in the forward list
    auto it = find(list.begin(), list.end(), str1);

    // if str1 is found, insert str2 after it
    if (it != list.end()) {
        ++it;
        list.insert_after(it, str2);
    } else {
        // otherwise, append str2 to the end of the list
        list.push_back(str2);
    }

    // free memory for arrays and array of 'record' structures
    delete[] offsets;
    delete[] keys;
    delete[] records;
}
