void insert_string(std::forward_list<std::string>& list, const std::string& str1, const std::string& str2) {
    // Initialize arrays for offset and key values
    long* offsets = new long[list.size()];
    int* keys = new int[list.size()];
    record* records = new record[list.size()];

    // Set the value of each record's double field to a random value within the specified range
    for (int i = 0; i < list.size(); ++i) {
        records[i].value = static_cast<double>(rand()) / RAND_MAX * 100;
    }

    // Search for the first occurrence of str1 in the forward list
    auto it = std::find(list.begin(), list.end(), str1);

    // If str1 is found, insert str2 after it
    if (it != list.end()) {
        ++it;
        list.insert_after(it, str2);
    } else {
        // If str1 is not found, append str2 to the end of the list
        list.push_back(str2);
    }

    // Maintain a running total of all double values in the record array and update it dynamically
    double total = 0;
    for (int i = 0; i < list.size(); ++i) {
        total += records[i].value;
    }

    return;
}
