    if (metrics->num_transactions > 1000000 && current_timestamp - metrics->last_logged_timestamp >= 60000) {
        logTransaction(transaction);
        logMetrics();
        metrics->last_logged_timestamp = current_timestamp;
    }

    // Integrate with an external payment gateway API to verify transaction amounts and update the transaction status based on the response from the API
    struct PaymentGatewayResponse *response = integrateWithPaymentGateway(transaction);
    if (response->status == 200) {
        transaction->status = "success";
    } else {
        transaction->status = "failure";
    }

    // Handle network failures gracefully by retrying failed transactions after a configurable delay, but ensure that no transaction is retried more than three times
    if (transaction->status == "failure") {
        int num_retries = 0;
        while (num_retries < MAX_RETRIES) {
            response = integrateWithPaymentGateway(transaction);
            if (response->status == 200) {
                transaction->status = "success";
                break;
            } else {
                num_retries++;
            }
        }
    }

    // Optimize memory usage by implementing a memory-efficient data structure for storing transaction records within the sliding window, considering that memory allocation failures should not block critical operations
    if (window->size == WINDOW_SIZE) {
        struct Transaction *oldest_transaction = &window->transactions[0];
        for (int i = 1; i < WINDOW_SIZE; i++) {
            if (window->transactions[i].timestamp < oldest_transaction->timestamp) {
                oldest_transaction = &window->transactions[i];
            }
        }
        free(oldest_transaction);
    }

    // Ensure thread safety when handling concurrent transactions, using lock-free data structures if possible to minimize overhead
    pthread_mutex_lock(&metrics->mutex);
    metrics->num_transactions++;
    metrics->avg_weighted_sum += weighted_sum;
    metrics->total_amount += transaction->amount;
    pthread_mutex_unlock(&metrics->mutex);
}

// Define the function to handle transaction duplicates by checking if the transaction ID already exists in the sliding window
int isDuplicateTransaction(struct Transaction *transaction) {
