            if (new_values == NULL) {
                fprintf(stderr, "Error: failed to allocate memory for numerical values\n");
                exit(EXIT_FAILURE);
            }
            values = new_values;
            capacity *= 2;
        }
        values[num_entries].type = INT;
        num_entries++;
    }
    while (fscanf(stdin, "%f", &values[num_entries].num.f) == 1) {
        if (num_entries >= capacity) {
