    float max_float = -FLT_MAX;
    for (int i = 0; i < num_entries; i++) {
        if (values[i].type == INT) {
            if (values[i].num.i > max_int) {
                max_int = values[i].num.i;
            }
        } else if (values[i].type == FLOAT) {
            if (values[i].num.f > max_float) {
                max_float = values[i].num.f;
            }
        }
    }

    // Print the largest integer and floating-point number in the array
    printf("Largest integer: %d\n", max_int);
    printf("Largest floating-point number: %f\n", max_float);

    // Free the memory allocated for the array of numerical values
    free(values);
}
