import json
import requests
from datetime import datetime
from collections import defaultdict

class TrafficMonitor:
    def __init__(self, config_file):
        self.config = json.load(open(config_file))
        self.apis = []
        for api in self.config["apis"]:
            self.apis.append(API(api["url"], api["key"]))
        self.cache = defaultdict(list)

    def fetch_data(self):
        data = {}
        for api in self.apis:
            response = requests.get(api.url, headers={"Authorization": f"Bearer {api.key}"})
            if response.status_code == 200:
                data[api.name] = response.json()
        return data

    def update_cache(self, data):
        for api in self.apis:
            self.cache[api.name].append(data[api.name])

    def get_latest_data(self):
        latest_data = {}
        for api in self.apis:
            if len(self.cache[api.name]) > 0:
                latest_data[api.name] = self.cache[api.name][-1]
        return latest_data

    def adjust_resolution(self, resolution):
        for api in self.apis:
            api.resolution = resolution

    def adjust_refresh_rate(self, refresh_rate):
        for api in self.apis:
            api.refresh_rate = refresh_rate

class API:
    def __init__(self, url, key):
        self.url = url
        self.key = key
        self.resolution = 10
        self.refresh_rate = 30

    def fetch(self):
        response = requests.get(self.url, headers={"Authorization": f"Bearer {self.key}"})
        if response.status_code == 200:
            return response.json()
        else:
            raise Exception("Failed to fetch data from API")

    def update_cache(self, data):
        self.cache[data["timestamp"]] = data

    def get_latest_data(self):
        if len(self.cache) > 0:
            return self.cache[-1]
        else:
            return None

def main():
    config_file = "config.json"
    traffic_monitor = TrafficMonitor(config_file)
    while True:
        data = traffic_monitor.fetch_data()
        traffic_monitor.update_cache(data)
        latest_data = traffic_monitor.get_latest_data()
        print(f"Latest data: {latest_data}")
        time.sleep(traffic_monitor.refresh_rate)

if __name__ == "__main__":
    main()
```
