    char *token_type;
    char *refresh_token;
};

// Define the function to verify the validity of an OAuth2 access token
bool verify_oauth2_token(const char *json) {
    // Parse the JSON string and extract the fields
    struct json_data data = parse_json(json);

    // Validate the presence and correctness of the required fields
    if (data.access_token == NULL || data.expires_in <= 0 || strcmp(data.token_type, "Bearer") != 0) {
        return false;
    }

    // Handle missing or invalid values by returning false
    if (data.refresh_token != NULL && strcmp(data.refresh_token, "") == 0) {
        return false;
    }

    // Return true if all fields are valid
    return true;
}

// Define the function to parse a JSON string and extract the required fields
struct json_data parse_json(const char *json) {
    struct json_data data = {NULL, 0, NULL, NULL};

    // Parse the JSON string using json-c library
    json_object *root = json_tokener_parse(json);
    if (root == NULL) {
        return data;
    }

    // Extract the required fields from the parsed JSON object
    json_object *access_token = json_object_get_object(root, "access_token");
    json_object *expires_in = json_object_get_object(root, "expires_in");
    json_object *token_type = json_object_get_object(root, "token_type");
    json_object *refresh_token = json_object_get_object(root, "refresh_token");

    // Check if the fields are present and valid
    if (access_token == NULL || expires_in == NULL || token_type == NULL) {
        return data;
    }

    // Extract the field values from the JSON objects
    data.access_token = json_object_get_string(access_token);
    data.expires_in = json_object_get_int(expires_in);
    data.token_type = json_object_get_string(token_type);
    if (refresh_token != NULL) {
        data.refresh_token = json_object_get_string(refresh_token);
    }

    // Free the JSON object and return the extracted fields
    json_object_put(root);
    return data;
}
