#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <math.h>
#include <time.h>

#define MAX_LINE_LENGTH 1024
#define MAX_FIELD_COUNT 5

typedef struct {
    char* fields[MAX_FIELD_COUNT];
} line_t;

void process_line(line_t* line) {
    int field_count = strlen(line->fields);
    if (field_count < MAX_FIELD_COUNT) {
        // Treat all available fields as averages
        for (int i = 0; i < field_count; i++) {
            line->fields[i] = malloc(sizeof(float));
            *(line->fields[i]) = atof(line->fields[i]);
        }
    } else {
        // Compute average of last five fields
        float sum = 0.0f;
        for (int i = field_count - MAX_FIELD_COUNT; i < field_count; i++) {
            sum += atof(line->fields[i]);
        }
        line->fields[field_count - 1] = malloc(sizeof(float));
        *(line->fields[field_count - 1]) = sum / MAX_FIELD_COUNT;
    }
}

void process_file(FILE* file) {
    char buffer[MAX_LINE_LENGTH];
    while (fgets(buffer, sizeof(buffer), file)) {
        line_t* line = malloc(sizeof(line_t));
        int field_count = 0;
        for (int i = 0; i < MAX_FIELD_COUNT && buffer[i] != '\n'; i++) {
            if (buffer[i] == ' ') {
                field_count++;
            } else {
                line->fields[field_count - 1] = malloc(sizeof(float));
                *(line->fields[field_count - 1]) = atof(buffer + i);
            }
        }
        process_line(line);
        free(line);
    }
}

int main() {
    FILE* file = fopen("input.txt", "r");
    if (file == NULL) {
        printf("Error opening input file\n");
        return 1;
    }
    process_file(file);
    fclose(file);
    return 0;
}
```
