    // Allocate memory for the offset array
    offset_arr = (long *)malloc(max_records * sizeof(long));
    if (!offset_arr) {
        fprintf(stderr, "Error: Failed to allocate memory for offset array\n");
        exit(EXIT_FAILURE);
    }

    // Allocate memory for the key array
    key_arr = (int *)malloc(max_records * sizeof(int));
    if (!key_arr) {
        fprintf(stderr, "Error: Failed to allocate memory for key array\n");
        exit(EXIT_FAILURE);
    }

    // Allocate memory for the record array
    record_arr = (record **)malloc(max_records * sizeof(record));
    if (!record_arr) {
        fprintf(stderr, "Error: Failed to allocate memory for record array\n");
        exit(EXIT_FAILURE);
    }

    // Initialize the offset array with default values
    for (int i = 0; i < max_records; i++) {
        offset_arr[i] = 0;
    }

    // Initialize the key array with default values
    for (int i = 0; i < max_records; i++) {
        key_arr[i] = 0;
    }

    // Initialize the record array with default values
    for (int i = 0; i < max_records; i++) {
        record_arr[i] = NULL;
    }
}

void free_arrays(long *offset_arr, int *key_arr, record **record_arr) {
    // Free the memory allocated for the offset array
    if (offset_arr) {
        free(offset_arr);
    }

    // Free the memory allocated for the key array
    if (key_arr) {
        free(key_arr);
    }

    // Free the memory allocated for the record array
    if (record_arr) {
        for (int i = 0; i < max_records; i++) {
