            }
        }
        free(record_arr);
    }
}

void add_record(long offset, int key, char *value) {
    // Check if the record is within the valid range
    if (key < INT_MIN || key > INT_MAX) {
        fprintf(stderr, "Error: Record's key value exceeds the valid range\n");
        return;
    }

    // Allocate memory for the new record
