    if (!new_record) {
        fprintf(stderr, "Error: Failed to allocate memory for new record\n");
        return;
    }

    // Initialize the new record with the given values
    new_record->key = key;
    new_record->value = value;

    // Add the new record to the array
    offset_arr[offset]++;
    key_arr[offset] = key;
    record_arr[offset] = new_record;
}

void remove_record(long offset) {
    // Check if the record exists
    if (offset >= max_records || !record_arr[offset]) {
        fprintf(stderr, "Error: Record does not exist\n");
        return;
    }

    // Free the memory allocated for the record
    free(record_arr[offset]);
    record_arr[offset] = NULL;

    // Decrement the offset array
    offset_arr[offset]--;
}

void update_record(long offset, int key, char *value) {
    // Check if the record exists
    if (offset >= max_records || !record_arr[offset]) {
        fprintf(stderr, "Error: Record does not exist\n");
        return;
    }

    // Update the record with the given values
    record_arr[offset]->key = key;
    record_arr[offset]->value = value;
}
