void thread_safe_access(UserRecord* records, int num_users) {
    // Use a mutex to protect the shared data structure from concurrent access
    pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

    // Lock the mutex before accessing or modifying the shared data structure
    pthread_mutex_lock(&mutex);

    // Unlock the mutex after accessing or modifying the shared data structure
    pthread_mutex_unlock(&mutex);
