void dfs_traverse(fsa_state_t *initial_states, int num_initial_states, fsa_sequence_t *sequence, int last_visited_state) {
    // Check if the initial state is already visited
    if (last_visited_state != -1 && sequence->count > 0 && sequence->states[sequence->count - 1]->id == last_visited_state) {
