void* thread_func(void* args) {
    // Cast the input arguments to the appropriate types
    entry_t** entries = (entry_t**)args;
    size_t num_entries = *((size_t*)args + 1);

    // Process each file in the directory concurrently, converting them to grayscale and compressing the resulting images
    for (size_t i = 0; i < num_entries; i++) {
        entry_t* entry = entries[i];
        char* filename = entry->metadata;
