}

// Function to manage a directory of image files, processing all files by converting them to grayscale using a third-party library and compressing the resulting images to reduce file size by at least 70% before saving them back into the same directory
int process_image_directory(char* dirname) {
    // Check if the input parameter is valid
    if (dirname == NULL) {
        return 1;
    }

    // Initialize a dynamic collection of entries to store information about each file in the directory
    entry_t** entries = malloc(sizeof(entry_t*) * 10);
    size_t num_entries = 0;

    // Iterate over all files in the directory and process them concurrently using a thread pool
    DIR* dir = opendir(dirname);
    if (dir == NULL) {
        return 1;
    }
    struct dirent* entry;
    while ((entry = readdir(dir)) != NULL) {
        char* filename = entry->d_name;
        // ...
        if (is_image_file(filename)) {
            entries[num_entries] = malloc(sizeof(entry_t));
            entries[num_entries]->id = num_entries + 1;
            entries[num_entries]->timestamp = time(NULL);
            entries[num_entries]->metadata = filename;
            num_entries++;
        }
    }
    closedir(dir);

    // Manage memory allocation and initialization for the dynamic collection of entries
    manage_entries(entries, &num_entries);

    // Create a thread pool to process each file concurrently
    pthread_t* threads = malloc(sizeof(pthread_t) * num_entries);
    for (size_t i = 0; i < num_entries; i++) {
        entry_t* entry = entries[i];
        char* filename = entry->metadata;
        // ...
        pthread_create(&threads[i], NULL, thread_func, &entry);
    }

    // Wait for all threads to complete and free the memory allocated for the dynamic collection of entries
    for (size_t i = 0; i < num_entries; i++) {
        pthread_join(threads[i], NULL);
    }
    free(threads);
    for (size_t i = 0; i < num_entries; i++) {
        entry_t* entry = entries[i];
        char* filename = entry->metadata;
        // ...
        free(entry);
    }
    free(entries);

    return 0;
}
