namespace DatabaseRandomValueGenerator
{
    public class RandomValueGenerator
    {
        private int _min;
        private int _max;
        private Random _random;

        public RandomValueGenerator(int min, int max)
        {
            if (min > max)
                throw new ArgumentException("Minimum value must be less than or equal to maximum value.");

            _min = min;
            _max = max;
            _random = new Random();
        }

        public float NextFloat()
        {
            return (float)_random.NextDouble() * (_max - _min) + _min;
        }

        public int NextInt()
        {
            return _random.Next(_min, _max);
        }

        public void AdjustRange(int min, int max)
        {
            if (min > max)
                throw new ArgumentException("Minimum value must be less than or equal to maximum value.");

            _min = min;
            _max = max;
        }

        public void ResetToDefault()
        {
            _min = 0;
            _max = 1;
        }

        public override string ToString()
        {
            return $"Range: [{_min}, {_max}]";
        }

        public DataTableReader QueryDatabase(byte[] query)
        {
            // Validate the byte array before sending it to the database.
            if (query == null || query.Length == 0)
                throw new ArgumentException("Query cannot be empty.");

            // Send the byte array to the database server and retrieve the result.
            var result = DatabaseConnection.ExecuteQuery(query);

            // Return a DataTableReader object containing the result of the query.
            return new DataTableReader(result);
        }
    }
}
