// Define the data structure to hold the two arrays of long and int values
typedef struct {
    long *offsets;
    int *keys;
} DataStructure;

// Define a function to initialize the data structure with random values within a specified range
void initDataStructure(DataStructure *ds, int min_value, int max_value, int initial_capacity) {
    // Allocate memory for the two arrays of long and int values
    ds->offsets = (long *)malloc(initial_capacity * sizeof(long));
    ds->keys = (int *)malloc(initial_capacity * sizeof(int));

    // Initialize the two arrays with random values within the specified range
    for (int i = 0; i < initial_capacity; i++) {
        ds->offsets[i] = (long)rand() % (max_value - min_value + 1) + min_value;
        ds->keys[i] = (int)rand() % (max_value - min_value + 1) + min_value;
    }
}

// Define a function to add new records to the data structure, dynamically resizing if necessary
void addRecord(DataStructure *ds, int key, long offset) {
    // Check if the number of records exceeds the current capacity of the data structure
    if (ds->offsets == NULL || ds->keys == NULL || ds->size >= ds->capacity) {
        // If so, dynamically resize the underlying data structures to accommodate additional records
        int new_capacity = ds->capacity * 2;
        long *new_offsets = (long *)realloc(ds->offsets, new_capacity * sizeof(long));
        int *new_keys = (int *)realloc(ds->keys, new_capacity * sizeof(int));
        if (new_offsets == NULL || new_keys == NULL) {
            // If the reallocation fails, handle the error gracefully and return
            printf("Error: Failed to resize data structure\n");
            return;
        }
        ds->offsets = new_offsets;
        ds->keys = new_keys;
        ds->capacity = new_capacity;
    }

    // Add the new record to the end of the data structure
    ds->offsets[ds->size] = offset;
    ds->keys[ds->size] = key;
    ds->size++;
}

// Define a function to retrieve a record from the data structure by its key
int getRecord(DataStructure *ds, int key) {
    // Iterate through the records in the data structure until the specified key is found
    for (int i = 0; i < ds->size; i++) {
        if (ds->keys[i] == key) {
            return i;
        }
    }

    // If the key is not found, return -1 to indicate failure
    return -1;
}

// Define a function to delete a record from the data structure by its key
void deleteRecord(DataStructure *ds, int key) {
    // Find the index of the record with the specified key in the data structure
    int index = getRecord(ds, key);
    if (index == -1) {
        return;
    }

    // Shift all records after the deleted record to fill the gap
    for (int i = index + 1; i < ds->size; i++) {
        ds->offsets[i - 1] = ds->offsets[i];
        ds->keys[i - 1] = ds->keys[i];
    }

    // Decrement the size of the data structure to reflect the deleted record
    ds->size--;
}

// Define a function to free the memory allocated for the data structure
void freeDataStructure(DataStructure *ds) {
    if (ds->offsets != NULL) {
        free(ds->offsets);
    }
    if (ds->keys != NULL) {
        free(ds->keys);
    }
}
