#include <stdlib.h>
#include <string.h>
#include <stdio.h>
#include <stdint.h>
#include <stdbool.h>
#include <assert.h>
#include <md5.h>

// Define the data structure to store records
typedef struct {
    long* offsets;
    int* keys;
    size_t capacity;
    size_t count;
} RecordManager;

// Define a function to initialize the record manager
void initRecordManager(RecordManager* rm, size_t initialCapacity) {
    assert(rm != NULL);
    rm->offsets = malloc(initialCapacity * sizeof(long));
    rm->keys = malloc(initialCapacity * sizeof(int));
    rm->capacity = initialCapacity;
    rm->count = 0;
}

// Define a function to add a new record to the manager
void addRecord(RecordManager* rm, long offset, int key) {
    assert(rm != NULL);
    if (rm->count == rm->capacity) {
        // Dynamically resize the data structures if necessary
        size_t newCapacity = rm->capacity * 2;
        rm->offsets = realloc(rm->offsets, newCapacity * sizeof(long));
        rm->keys = realloc(rm->keys, newCapacity * sizeof(int));
        rm->capacity = newCapacity;
    }
    rm->offsets[rm->count] = offset;
    rm->keys[rm->count] = key;
    rm->count++;
}

// Define a function to compute the MD5 hash of a string
void md5Hash(const char* str, size_t len) {
    assert(str != NULL);
    MD5_CTX ctx;
    MD5Init(&ctx);
    MD5Update(&ctx, (unsigned char*)str, len);
    unsigned char digest[16];
    MD5Final(digest, &ctx);
    for (size_t i = 0; i < 16; i++) {
        printf("%02x", digest[i]);
    }
}

// Define a function to handle external records
void handleExternalRecords(RecordManager* rm, const char* input) {
    assert(rm != NULL);
    assert(input != NULL);
    // Parse the input string and add each record to the manager
    size_t len = strlen(input);
    for (size_t i = 0; i < len; i++) {
        long offset = atol(input + i);
        int key = rand() % 100; // Generate a random value within the specified range
        addRecord(rm, offset, key);
    }
}

// Define a function to clean up the record manager
void destroyRecordManager(RecordManager* rm) {
    assert(rm != NULL);
    free(rm->offsets);
    free(rm->keys);
    rm->capacity = 0;
    rm->count = 0;
}
```
