#define ERROR_HANDLING(condition, message) \
    if (condition) { \
        fprintf(stderr, "Error: %s\n", message); \
        return NULL; \
    }

typedef struct record {
    int key;
    char* value;
} record_t;

void* allocate_memory(size_t size) {
    void* ptr = malloc(size);
    ERROR_HANDLING(ptr == NULL, "Failed to allocate memory");
    return ptr;
}

void free_memory(void* ptr) {
    if (ptr != NULL) {
        free(ptr);
    }
}

record_t** initialize_arrays(size_t num_records, size_t max_size, int valid_range) {
    record_t** offset_array = allocate_memory(num_records * sizeof(long));
    ERROR_HANDLING(offset_array == NULL, "Failed to allocate memory for offset array");

    record_t** key_array = allocate_memory(num_records * sizeof(int));
    ERROR_HANDLING(key_array == NULL, "Failed to allocate memory for key array");

    record_t** value_array = allocate_memory(num_records * sizeof(record_t*));
    ERROR_HANDLING(value_array == NULL, "Failed to allocate memory for value array");

    size_t total_size = 0;

    // Initialize arrays with default values
    for (size_t i = 0; i < num_records; ++i) {
        offset_array[i] = 0;
        key_array[i] = 0;
        value_array[i] = NULL;
    }

    // Validate input parameters and handle errors gracefully
    ERROR_HANDLING(num_records > max_size, "Number of records exceeds maximum size");
    ERROR_HANDLING(valid_range < INT_MIN || valid_range > INT_MAX, "Invalid range for integer values");

    // Allocate memory for each record and initialize its fields
    for (size_t i = 0; i < num_records; ++i) {
        record_t* record = allocate_memory(sizeof(record_t));
        ERROR_HANDLING(record == NULL, "Failed to allocate memory for record");

        // Initialize integer value within range or set to default
        if (record->key < valid_range && record->key > valid_range) {
            record->key = 0;
        }

        // Allocate memory for string and initialize it with a default value
        char* str = allocate_memory(16);
        ERROR_HANDLING(str == NULL, "Failed to allocate memory for string");
        strcpy(str, "Default value");
        record->value = str;

        // Add record to arrays and update total size
        offset_array[i] = (long)record;
        key_array[i] = record->key;
        value_array[i] = record->value;
        total_size += sizeof(record_t);
    }

    // Free memory if any allocation failed during initialization
    if (total_size == 0) {
        free_memory(offset_array);
        free_memory(key_array);
        free_memory(value_array);
        return NULL;
    }

    // Return initialized arrays and total size
    return offset_array;
}

void free_arrays(record_t** offset_array, record_t** key_array, record_t** value_array) {
    if (offset_array != NULL) {
        for (size_t i = 0; i < num_records; ++i) {
            free_memory(offset_array[i]);
            free_memory(key_array[i]);
            free_memory(value_array[i]);
        }
    }
}
