// Define the structure for a user node in the linked list
typedef struct UserNode {
    int id;
    time_t timestamp;
    char *preferences; // hash table of preferences
    struct UserNode *next;
} UserNode;

// Define the structure for the linked list
typedef struct LinkedList {
    UserNode *head;
    UserNode *tail;
} LinkedList;

// Define the function to dynamically allocate memory for and initialize a linked list of user nodes
void init_linked_list(LinkedList *ll, int max_users) {
    ll->head = NULL;
    ll->tail = NULL;

    // Allocate memory for the first node in the linked list
    UserNode *node = (UserNode *)malloc(sizeof(UserNode));
    if (!node) {
        printf("Error: failed to allocate memory for user node\n");
        return;
    }

    // Initialize the first node in the linked list
    node->id = 0;
    node->timestamp = time(NULL);
    node->preferences = NULL;
    node->next = NULL;

    // Set the head and tail pointers to point to the first node
    ll->head = node;
    ll->tail = node;

    // Allocate memory for the remaining nodes in the linked list
    for (int i = 1; i < max_users; i++) {
        UserNode *new_node = (UserNode *)malloc(sizeof(UserNode));
        if (!new_node) {
            printf("Error: failed to allocate memory for user node\n");
            return;
        }

        // Initialize the remaining nodes in the linked list
        new_node->id = i;
        new_node->timestamp = time(NULL);
        new_node->preferences = NULL;
        new_node->next = NULL;

        // Add the new node to the end of the linked list
        ll->tail->next = new_node;
        ll->tail = new_node;
    }
}

// Define the function to free memory for a linked list of user nodes
void free_linked_list(LinkedList *ll) {
    UserNode *current = ll->head;
    while (current != NULL) {
        UserNode *next = current->next;
        free(current);
        current = next;
    }
}

