// Define the structure for TIDB_ROW_RECORD
typedef struct {
    int ROW_ID;
    char* COLUMN_VALUES;
    time_t TIMESTAMP;
} TIDB_ROW_RECORD;

// Define the list of TIDB_ROW_RECORD structures
static pthread_mutex_t record_list_lock = PTHREAD_MUTEX_INITIALIZER;
static int record_count = 0;
static int max_record_count = 10000; // maximum number of records allowed in the list
static TIDB_ROW_RECORD* record_list = NULL;

// Function to initialize and populate the list of TIDB_ROW_RECORD structures
void init_and_populate_record_list(int num_records) {
    // Acquire lock on the record list
    pthread_mutex_lock(&record_list_lock);

    // Check if the list is already initialized and has enough space for the new records
    if (record_list == NULL || record_count + num_records > max_record_count) {
        // If the list is not initialized, allocate memory for it
        if (record_list == NULL) {
            record_list = malloc(sizeof(TIDB_ROW_RECORD) * max_record_count);
        }
        // If the list has reached its maximum capacity, reallocate more memory for it
        else if (record_count + num_records > max_record_count) {
            record_list = realloc(record_list, sizeof(TIDB_ROW_RECORD) * (max_record_count + num_records));
            max_record_count += num_records;
        }
    }

    // Populate the list with new records
    for (int i = 0; i < num_records; i++) {
        record_list[record_count + i].ROW_ID = i;
        record_list[record_count + i].COLUMN_VALUES = malloc(sizeof(char) * 10); // allocate memory for the column values
        sprintf(record_list[record_count + i].COLUMN_VALUES, "%d", i); // populate the column values with the current record ID
        record_list[record_count + i].TIMESTAMP = time(NULL); // set the timestamp to the current system time
    }

    // Update the count of records in the list
    record_count += num_records;

    // Release lock on the record list
    pthread_mutex_unlock(&record_list_lock);
}

// Function to clean up old records from the list periodically
void cleanup_old_records() {
    // Acquire lock on the record list
    pthread_mutex_lock(&record_list_lock);

    // Check if there are any old records in the list
    if (record_count > 0) {
        // Find the oldest record in the list
        int oldest_record = 0;
        for (int i = 1; i < record_count; i++) {
            if (record_list[i].TIMESTAMP < record_list[oldest_record].TIMESTAMP) {
                oldest_record = i;
            }
        }

        // Remove the oldest record from the list
        free(record_list[oldest_record].COLUMN_VALUES); // free the memory allocated for the column values
        memmove(&record_list[oldest_record], &record_list[oldest_record + 1], (record_count - oldest_record - 1) * sizeof(TIDB_ROW_RECORD)); // shift the remaining records to fill the gap
        record_count--; // update the count of records in the list
    }

    // Release lock on the record list
    pthread_mutex_unlock(&record_list_lock);
}
