    pthread_mutex_unlock(&list_lock);
}

// Function to retrieve a record from the list by its row ID
TIDB_ROW_RECORD* get_record(int row_id) {
    pthread_mutex_lock(&list_lock);
    // Check if the row ID is valid and within the range of the list
    if (row_id < 1 || row_id > num_records) {
        return NULL;
    }
    TIDB_ROW_RECORD* record = &records[row_id - 1];
    pthread_mutex_unlock(&list_lock);
    return record;
}

// Function to add a new record to the list
void add_record(TIDB_ROW_RECORD* record) {
    pthread_mutex_lock(&list_lock);
    // Check if the list is already full and needs to be resized
    if (num_records == max_records) {
        max_records += 1000;
        records = realloc(records, sizeof(TIDB_ROW_RECORD) * max_records);
    }
    // Add the new record to the list
    records[num_records].row_id = num_records + 1;
    records[num_records].column_values = malloc(sizeof(char) * 100);
    sprintf(records[num_records].column_values, "Column values for row %d", num_records + 1);
    records[num_records].timestamp = time(NULL);
    num_records++;
    pthread_mutex_unlock(&list_lock);
}

// Function to remove a record from the list by its row ID
void remove_record(int row_id) {
    pthread_mutex_lock(&list_lock);
    // Check if the row ID is valid and within the range of the list
    if (row_id < 1 || row_id > num_records) {
        return;
    }
    // Remove the record from the list
    free(records[row_id - 1].column_values);
    records[row_id - 1] = records[num_records - 1];
    num_records--;
    pthread_mutex_unlock(&list_lock);
}
