// Structure to store network interface statistics
typedef struct NetworkInterfaceStats {
    char *interface_name; // Name of the network interface
    int packet_loss;      // Packet loss percentage
    int throughput;       // Throughput in bytes per second
    int latency;         // Latency in milliseconds
} NetworkInterfaceStats;

// Structure to store a linked list of network interface statistics
typedef struct NetworkInterfaceStatsList {
    NetworkInterfaceStats *stats;  // Pointer to the first element in the list
    size_t count;                  // Number of elements in the list
} NetworkInterfaceStatsList;

// Function to initialize a linked list of network interface statistics
void initNetworkInterfaceStatsList(NetworkInterfaceStatsList *list) {
    list->stats = NULL;
    list->count = 0;
}

// Function to add a new network interface statistics to the linked list
void addNetworkInterfaceStats(NetworkInterfaceStatsList *list, const char *interface_name, int packet_loss, int throughput, int latency) {
    NetworkInterfaceStats *new_stats = malloc(sizeof(NetworkInterfaceStats));
    if (new_stats == NULL) {
        // Handle memory allocation failure gracefully
        return;
    }
    new_stats->interface_name = strdup(interface_name);
    new_stats->packet_loss = packet_loss;
    new_stats->throughput = throughput;
    new_stats->latency = latency;
    list->count++;
    if (list->stats == NULL) {
        list->stats = new_stats;
    } else {
        // Append the new element to the end of the list
        NetworkInterfaceStats *current = list->stats;
        while (current->next != NULL) {
            current = current->next;
        }
        current->next = new_stats;
    }
}

// Function to update an existing network interface statistics in the linked list
void updateNetworkInterfaceStats(NetworkInterfaceStatsList *list, const char *interface_name, int packet_loss, int throughput, int latency) {
    NetworkInterfaceStats *current = list->stats;
    while (current != NULL) {
        if (strcmp(current->interface_name, interface_name) == 0) {
            current->packet_loss = packet_loss;
            current->throughput = throughput;
            current->latency = latency;
            return;
        }
        current = current->next;
    }
}

// Function to retrieve aggregated statistics for all interfaces in the linked list
void getNetworkInterfaceStats(NetworkInterfaceStatsList *list, NetworkInterfaceStats *stats) {
    stats->packet_loss = 0;
    stats->throughput = 0;
    stats->latency = 0;
    NetworkInterfaceStats *current = list->stats;
    while (current != NULL) {
        stats->packet_loss += current->packet_loss;
        stats->throughput += current->throughput;
        stats->latency += current->latency;
        current = current->next;
    }
}
