typedef struct NetworkInterfaceStatsNode {
    NetworkInterfaceStats *stats;
    struct NetworkInterfaceStatsNode *next;
} NetworkInterfaceStatsNode;

// Define the global variables for managing the network interface stats
static NetworkInterfaceStatsNode *head = NULL;
static int num_interfaces = 0;
static int max_num_interfaces = 100000; // maximum number of interfaces to store
static pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER; // mutex for synchronizing access to the linked list

// Function to initialize and manage the network interface stats
