    NetworkInterfaceStatsNode *new_node = malloc(sizeof(NetworkInterfaceStatsNode));
    if (new_node == NULL) {
        // handle allocation failure gracefully
        return;
    }
    new_node->stats = malloc(sizeof(NetworkInterfaceStats));
    if (new_node->stats == NULL) {
        free(new_node);
        // handle allocation failure gracefully
        return;
    }
    new_node->stats->interface_name = interface_name;
    new_node->stats->packet_loss = packet_loss;
    new_node->stats->throughput = throughput;
    new_node->stats->latency = latency;
    new_node->next = NULL;

    pthread_mutex_lock(&mutex);
    if (head == NULL) {
        head = new_node;
    } else {
        NetworkInterfaceStatsNode *curr = head;
        while (curr->next != NULL) {
            curr = curr->next;
        }
        curr->next = new_node;
    }
    num_interfaces++;
    pthread_mutex_unlock(&mutex);
}

// Function to update an existing network interface stat
void updateNetworkInterfaceStat(char *interface_name, int packet_loss, int throughput, int latency) {
    NetworkInterfaceStatsNode *curr = head;
    while (curr != NULL) {
        if (strcmp(curr->stats->interface_name, interface_name) == 0) {
            curr->stats->packet_loss = packet_loss;
            curr->stats->throughput = throughput;
            curr->stats->latency = latency;
            break;
        }
        curr = curr->next;
    }
}

// Function to retrieve aggregated statistics for all interfaces
void getNetworkInterfaceStats(int *num_interfaces, NetworkInterfaceStats **stats) {
    pthread_mutex_lock(&mutex);
    *num_interfaces = num_interfaces;
    *stats = malloc(*num_interfaces * sizeof(NetworkInterfaceStats));
    if (*stats == NULL) {
        // handle allocation failure gracefully
        return;
    }
    int i = 0;
    NetworkInterfaceStatsNode *curr = head;
    while (curr != NULL) {
        memcpy((*stats)[i], curr->stats, sizeof(NetworkInterfaceStats));
        i++;
        curr = curr->next;
    }
    pthread_mutex_unlock(&mutex);
}

// Function to remove the least recently used interface stat when the maximum number of interfaces is exceeded
void removeLeastRecentlyUsedInterfaceStat() {
    NetworkInterfaceStatsNode *curr = head;
    while (curr->next != NULL) {
        curr = curr->next;
    }
    free(curr->stats);
    curr->next = NULL;
}

// Function to limit the maximum number of interfaces that can be stored
