// Function to initialize AES-256-CBC cipher with given password
EVP_CIPHER_CTX* init_cipher(const char* password) {
    // Set IV length and key length to fixed values
    const int iv_len = 16;
    const int key_len = 32;

    // Use SHA-256 hash function to derive encryption key from password
    unsigned char key[key_len];
    SHA256(password, strlen(password), key);

    // Generate secure salt for key derivation
    unsigned char salt[16];
    RAND_bytes(salt, 16);

    // Derive encryption key from password and salt
    unsigned char derived_key[key_len];
    HMAC(EVP_sha256(), salt, 16, key, key_len, derived_key, NULL);

    // Store derived key securely before using it for initialization
    EVP_CIPHER_CTX* ctx = EVP_CIPHER_CTX_new();
    EVP_EncryptInit(ctx, EVP_aes_256_cbc(), derived_key, salt);

    // Enable cipher and return pointer to cipher context
    EVP_EncryptEnable(ctx, 1);
    return ctx;
}

// Function to clean up and disable the cipher when it is no longer needed
void cleanup_cipher(EVP_CIPHER_CTX* ctx) {
    // Disable cipher and free memory used by cipher context
    EVP_EncryptDisable(ctx, 0);
    EVP_CIPHER_CTX_free(ctx);
}
