// Function to generate a new RSA-4096 key pair
RSA* generate_key_pair() {
    // Initialize the OpenSSL library
    ERR_load_crypto_strings();
    OPENSSL_add_all_algorithms_noconf();
    OPENSSL_add_all_ciphers();
    OPENSSL_add_all_digests();

    // Generate a new RSA-4096 key pair
    RSA* rsa = RSA_new();
    BIGNUM* bn = BN_new();
    BN_set_word(bn, RSA_F4);
    RSA_generate_key_ex(rsa, 4096, bn, NULL);

    // Set the key generation parameters to ensure compatibility with various cryptographic protocols
    rsa->flags = RSA_FLAG_CACHE_PUBLIC | RSA_FLAG_CACHE_PRIVATE;
    rsa->method_mod_n = BN_mod_exp;
    rsa->method_mod_p = BN_mod_exp;
    rsa->method_mod_q = BN_mod_exp;

    // Use a secure random number generator to generate the private key
    RAND_seed(RAND_SEED_RDTSC, 1);
    RSA_generate_key_ex(rsa, 4096, bn, NULL);

    // Incorporate a secure key storage mechanism to protect the private key during its lifecycle
    EVP_PKEY* pkey = EVP_PKEY_new();
    EVP_PKEY_assign(pkey, EVP_PKEY_RSA, rsa);
    EVP_PKEY_store_private(pkey, NULL, NULL, 0);

    // Free the memory allocated for the key pair and return the generated key pair
    RSA_free(rsa);
    BN_free(bn);
    return pkey;
}

// Function to encrypt data using the generated key pair
int encrypt(EVP_PKEY* pkey, unsigned char* plaintext, int plaintext_len, unsigned char** ciphertext) {
    // Initialize the OpenSSL library
    ERR_load_crypto_strings();
    OPENSSL_add_all_algorithms_noconf();
    OPENSSL_add_all_ciphers();
    OPENSSL_add_all_digests();

    // Get the public key from the key pair
    RSA* rsa = EVP_PKEY_get1_RSA(pkey);

    // Encrypt the plaintext using the public key
    int ciphertext_len = 0;
    unsigned char* ciphertext = NULL;
    if (plaintext_len > 0) {
        ciphertext_len = RSA_public_encrypt(plaintext_len, plaintext, ciphertext, rsa, RSA_PKCS1_OAEP_PADDING);
        if (ciphertext_len < 0) {
            ERR_print_errors_fp(stderr);
            return -1;
        }
    }

    // Free the memory allocated for the public key and return the encrypted data
    RSA_free(rsa);
    *ciphertext = ciphertext;
    return ciphertext_len;
}

