#include <stdlib.h>
#include <string.h>
#include <stdio.h>
#include <assert.h>
#include <pthread.h>

// Define the entry structure
typedef struct {
    int id;
    double timestamp;
    char* description;
} entry_t;

// Define the cache structure
typedef struct {
    entry_t** entries;
    size_t capacity;
    size_t count;
    pthread_mutex_t mutex;
} cache_t;

// Initialize the cache with a given capacity
void init_cache(cache_t* cache, size_t capacity) {
    cache->entries = (entry_t**)malloc(capacity * sizeof(entry_t*));
    cache->capacity = capacity;
    cache->count = 0;
    pthread_mutex_init(&cache->mutex, NULL);
}

// Add an entry to the cache
void add_to_cache(cache_t* cache, entry_t* entry) {
    pthread_mutex_lock(&cache->mutex);
    if (cache->count < cache->capacity) {
        cache->entries[cache->count++] = entry;
    } else {
        // Evict the oldest entry from the cache
        size_t oldest_index = 0;
        for (size_t i = 1; i < cache->count; i++) {
            if (cache->entries[i]->timestamp < cache->entries[oldest_index]->timestamp) {
                oldest_index = i;
            }
        }
        free(cache->entries[oldest_index]);
        cache->entries[oldest_index] = entry;
    }
    pthread_mutex_unlock(&cache->mutex);
}

// Get an entry from the cache by its ID
entry_t* get_from_cache(cache_t* cache, int id) {
    pthread_mutex_lock(&cache->mutex);
    for (size_t i = 0; i < cache->count; i++) {
        if (cache->entries[i]->id == id) {
            return cache->entries[i];
        }
    }
    pthread_mutex_unlock(&cache->mutex);
    return NULL;
}

// Free the cache
void free_cache(cache_t* cache) {
    for (size_t i = 0; i < cache->count; i++) {
        free(cache->entries[i]);
    }
    pthread_mutex_destroy(&cache->mutex);
}

// Define the function to manage memory allocation and initialization for a dynamic collection of 'entry' objects
void manage_memory(size_t min_capacity, size_t max_capacity) {
    // Initialize the cache with the minimum capacity
    cache_t* cache = (cache_t*)malloc(sizeof(cache_t));
    init_cache(cache, min_capacity);

    // Loop until the maximum capacity is reached
    while (cache->count < max_capacity) {
        // Allocate a new entry and initialize it with default values
        entry_t* entry = (entry_t*)malloc(sizeof(entry_t));
        entry->id = -1;
        entry->timestamp = 0.0;
        entry->description = NULL;

        // Add the entry to the cache
        add_to_cache(cache, entry);
    }

    // Free the cache when it is no longer needed
    free_cache(cache);
}
