void manage_file_operations(file_operation_t *op) {
    // Check if the operation is valid
    if (op->type == READ || op->type == WRITE || op->type == APPEND) {
        // Get the file metadata from the external service or local database
        file_metadata_t *meta = get_file_metadata(op->file_path);
        if (!meta) {
            // Handle error: file not found or permission issue
            return;
        }

        // Check if the operation is within the file size limit
        if (op->offset + op->length > meta->file_size) {
            // Handle error: offset and length exceeds file size
            return;
        }

        // Increment the number of operations for this file
        meta->num_operations++;

        // Perform the operation on the file
        if (op->type == READ) {
            read_file(meta, op);
        } else if (op->type == WRITE) {
            write_file(meta, op);
        } else if (op->type == APPEND) {
            append_file(meta, op);
        }

