void read_file(file_metadata_t *meta, file_operation_t *op) {
    // Open the file for reading
    int fd = open(op->file_path, O_RDONLY);
    if (fd == -1) {
        // Handle error: unable to open file
        return;
    }

    // Seek to the specified offset and read the requested length
    off_t seek_result = lseek(fd, op->offset, SEEK_SET);
    if (seek_result == -1) {
        // Handle error: unable to seek to offset
        close(fd);
        return;
    }
    ssize_t read_result = read(fd, op->buffer, op->length);
    if (read_result == -1) {
        // Handle error: unable to read from file
        close(fd);
        return;
    }

    // Close the file and return the number of bytes read
    close(fd);
}

void write_file(file_metadata_t *meta, file_operation_t *op) {
    // Open the file for writing
    int fd = open(op->file_path, O_WRONLY);
    if (fd == -1) {
        // Handle error: unable to open file
        return;
    }

    // Seek to the specified offset and write the requested length
    off_t seek_result = lseek(fd, op->offset, SEEK_SET);
    if (seek_result == -1) {
        // Handle error: unable to seek to offset
        close(fd);
        return;
    }
    ssize_t write_result = write(fd, op->buffer, op->length);
    if (write_result == -1) {
        // Handle error: unable to write to file
        close(fd);
        return;
    }

    // Close the file and return the number of bytes written
    close(fd);
}

void append_file(file_metadata_t *meta, file_operation_t *op) {
    // Open the file for appending
    int fd = open(op->file_path, O_WRONLY | O_APPEND);
    if (fd == -1) {
        // Handle error: unable to open file
        return;
    }

    // Write the requested length to the end of the file
    ssize_t write_result = write(fd, op->buffer, op->length);
    if (write_result == -1) {
        // Handle error: unable to append to file
        close(fd);
        return;
    }

    // Close the file and return the number of bytes written
    close(fd);
}

