void rename_file(char* original_filename, int num_digits, char* new_file_type, int max_filename_length, bool async) {
    // Validate input parameters
    if (original_filename == NULL || new_file_type == NULL) {
        printf("Error: Invalid input parameters\n");
        return;
    }

    // Get the original file path and name
    char* original_path = strdup(original_filename);
    char* original_name = basename(original_path);

    // Get the new file path and name
    char* new_path = strdup(original_filename);
    char* new_name = strdup(new_file_type);

    // Append the number of digits to the new file name
    int num_digits_len = snprintf(NULL, 0, "%d", num_digits);
    char* num_digits_str = malloc(num_digits_len + 1);
    sprintf(num_digits_str, "%d", num_digits);
    strcat(new_name, num_digits_str);

    // Get the new file extension
    char* new_ext = strrchr(new_name, '.');
    if (new_ext == NULL) {
        printf("Error: Invalid new file type\n");
        return;
    }

    // Check if the resulting filename is too long
    int new_filename_len = strlen(original_path) + strlen(new_name);
    if (new_filename_len > max_filename_length) {
        printf("Error: Resulting filename is too long\n");
        return;
    }

    // Check if the new file path is too long
    struct stat sb;
    if (stat(new_path, &sb) == 0 && S_ISDIR(sb.st_mode)) {
        printf("Error: New file path is a directory\n");
        return;
    }

    // Rename the file
    int ret = 0;
    if (async) {
        pthread_t thread;
        pthread_create(&thread, NULL, rename_file_async, original_path);
    } else {
        ret = rename(original_path, new_path);
    }

    // Handle errors
    if (ret != 0) {
        printf("Error: Failed to rename file\n");
        return;
    }
}

void* rename_file_async(void* arg) {
    char* original_path = (char*)arg;
    int ret = rename(original_path, new_path);
    if (ret != 0) {
        printf("Error: Failed to rename file\n");
        return NULL;
    }
}
```
