struct word_count {
    char *word;
    int count;
};

struct file_stats {
    long character_count;
    long word_count;
    struct word_count *words;
};

void print_usage(char *program_name) {
    printf(USAGE_INFO, program_name);
}

void print_manpage(char *program_name) {
    printf(MANPAGE_INFO, program_name, program_name, program_name, program_name);
}

struct file_stats *parse_file(char *filename) {
    struct file_stats *stats = malloc(sizeof(struct file_stats));
    stats->character_count = 0;
    stats->word_count = 0;
    stats->words = NULL;

    int fd = open(filename, O_RDONLY);
    if (fd == -1) {
        perror("open");
        exit(EXIT_FAILURE);
    }

    char buffer[MAX_LINE_LENGTH];
    while (read(fd, buffer, MAX_LINE_LENGTH) > 0) {
        stats->character_count += strlen(buffer);
        char *token = strtok(buffer, DEFAULT_DELIMITER);
        while (token != NULL) {
            stats->word_count++;
            struct word_count *new_word = malloc(sizeof(struct word_count));
            new_word->word = token;
            new_word->count = 1;
            stats->words = realloc(stats->words, (stats->word_count + 1) * sizeof(struct word_count));
            stats->words[stats->word_count - 1] = new_word;
            token = strtok(NULL, DEFAULT_DELIMITER);
        }
    }

    close(fd);
    return stats;
}

void print_file_stats(struct file_stats *stats) {
    printf("Total number of characters: %ld\n", stats->character_count);
    printf("Total number of words: %ld\n", stats->word_count);
    for (int i = 0; i < stats->word_count; i++) {
        struct word_count *word = stats->words[i];
        printf("%s: %d\n", word->word, word->count);
    }
}

void print_frequency_analysis(struct file_stats *stats) {
    int max_occurrence = 0;
    for (int i = 0; i < stats->word_count; i++) {
        struct word_count *word = stats->words[i];
        if (word->count > max_occurrence) {
            max_occurrence = word->count;
        }
    }

    for (int i = 0; i < max_occurrence + 1; i++) {
        printf("%d: ", i);
        for (int j = 0; j < stats->word_count; j++) {
            struct word_count *word = stats->words[j];
            if (word->count == i) {
                printf("%s ", word->word);
            }
        }
        printf("\n");
    }
}

void print_line_breakdown(struct file_stats *stats) {
    for (int i = 0; i < stats->word_count; i++) {
        struct word_count *word = stats->words[i];
        printf("%s: %d\n", word->word, word->count);
    }
}

void print_timing(struct file_stats *stats) {
    double processing_time = 0;
    double output_generation_time = 0;
    for (int i = 0; i < stats->word_count; i++) {
        struct word_count *word = stats->words[i];
        if (word->count > max_occurrence) {
            max_occurrence = word->count;
        }
    }

    for (int i = 0; i < max_occurrence + 1; i++) {
        printf("%d: ", i);
        for (int j = 0; j < stats->word_count; j++) {
            struct word_count *word = stats->words[j];
            if (word->count == i) {
                printf("%s ", word->word);
            }
        }
        printf("\n");
    }
}

int main(int argc, char **argv) {
    struct file_stats *stats = NULL;
    bool enable_timing = false;
    bool enable_frequency_analysis = false;
    bool enable_line_breakdown = false;
    bool enable_output_file = false;
    char *input_filename = NULL;
    char *output_filename = NULL;
    int c;
    while ((c = getopt(argc, argv, "hcs:o:lf")) != -1) {
        switch (c) {
            case 'h':
                print_usage(argv[0]);
                return 0;
            case 's':
                enable_frequency_analysis = true;
                break;
            case 'o':
                enable_output_file = true;
                output_filename = optarg;
                break;
            case 'l':
                enable_line_breakdown = true;
                break;
            case 'f':
                enable_frequency_analysis = true;
                break;
            case 't':
                enable_timing = true;
                break;
            default:
                print_usage(argv[0]);
                return 1;
        }
    }

    if (optind < argc) {
        input_filename = argv[optind];
    } else {
        print_usage(argv[0]);
        return 1;
    }

    stats = parse_file(input_filename);

    if (enable_timing) {
        struct timeval start, end;
        gettimeofday(&start, NULL);
        if (enable_frequency_analysis) {
            print_frequency_analysis(stats);
        } else if (enable_line_breakdown) {
            print_line_breakdown(stats);
        } else {
            print_file_stats(stats);
        }
        gettimeofday(&end, NULL);
        double processing_time = (double)(end.tv_sec - start.tv_sec) + (double)(end.tv_usec - start.tv_usec) / 1000000;
        printf(TIMING_INFO, processing_time, output_generation_time, processing_time + output_generation_time);
    } else {
        if (enable_frequency_analysis) {
