void modifyFileNameAndGraph(char *filename) {
    // Count the number of vowels in the filename
    int num_vowels = 0;
    for (int i = 0; i < strlen(filename); i++) {
        if (filename[i] == 'a' || filename[i] == 'e' || filename[i] == 'i' || filename[i] == 'o' || filename[i] == 'u') {
            num_vowels++;
        }
    }

    // Determine the file type based on whether the filename length is even or odd
    char *file_type = (strlen(filename) % 2 == 0) ? ".txt" : ".log";

    // Allocate memory for the new filename and ensure proper memory management
    int new_filename_length = strlen(filename) + 3;
    char *new_filename = malloc(new_filename_length);
    if (new_filename == NULL) {
        printf("Error: Failed to allocate memory for new filename\n");
        return;
    }

    // Construct the new filename string using sprintf and strcat
    int num_digits = 2;
    if (strchr(filename, '!') != NULL) {
        num_digits = 3;
    }
    sprintf(new_filename, "%s%0*d%s", filename, num_digits, rand() % 1000, file_type);

    // Interact with the graph database to add vertices and edges
    struct Graph *graph = malloc(sizeof(struct Graph));
    if (graph == NULL) {
        printf("Error: Failed to allocate memory for graph\n");
        return;
    }
    graph->num_vertices = rand() % 10 + 1;
    graph->num_edges = rand() % 10 + 1;
    graph->vertices = malloc(graph->num_vertices * sizeof(struct Vertex));
    if (graph->vertices == NULL) {
        printf("Error: Failed to allocate memory for vertices\n");
        return;
    }
    graph->edges = malloc(graph->num_edges * sizeof(struct Edge));
    if (graph->edges == NULL) {
