        graph->edges[i].target = rand() % graph->num_vertices + 1;
        for (int j = 0; j < 10; j++) {
            graph->edges[i].properties[j] = rand() % 26 + 'a';
        }
    }

    // Free the allocated memory after use
    free(new_filename);
    free(graph);
}
