// Define the function to generate a unique identifier for a given file based on its content hash and directory structure (synchronous version)
void generateIdentifierSync(char* originalFilePath) {
    // Initialize variables
    char* identifier = NULL;
    size_t identifierLength = 0;
    struct stat fileStat;
    int fd;
    off_t fileSize;
    char* buffer;
    int i;

    // Open the file for reading
    if ((fd = open(originalFilePath, O_RDONLY)) == -1) {
        printf("Error opening file: %s\n", strerror(errno));
        return;
    }

    // Get the file size and allocate a buffer to read it
    if (fstat(fd, &fileStat) == -1) {
        printf("Error getting file size: %s\n", strerror(errno));
        close(fd);
        return;
    }
    fileSize = fileStat.st_size;
    buffer = malloc(fileSize);

    // Read the entire file into the buffer
    if (read(fd, buffer, fileSize) == -1) {
        printf("Error reading file: %s\n", strerror(errno));
        close(fd);
        return;
    }

    // Close the file
    close(fd);

    // Generate a hash of the file content
