    // Free the buffer
    free(buffer);

    // Generate the identifier based on the hash and directory structure
    identifierLength = MAX_IDENTIFIER_LENGTH;
    identifier = malloc(identifierLength);
    for (i = 0; i < identifierLength; i++) {
        identifier[i] = hash[i % HASH_SIZE];
    }

    // Free the hash
    free(hash);
}

