    // Allocate memory for the record array
    record_array = (Record**)malloc(num_records * sizeof(Record*));
    if (!record_array) {
        printf("Error: Failed to allocate memory for record array\n");
        free(offset_array);
        free(key_array);
        return;
    }

    // Initialize the offset and key arrays
    for (size_t i = 0; i < num_records; i++) {
        offset_array[i] = rand() % 1000;
        key_array[i] = rand() % 1000;
    }

    // Initialize the record array
    for (size_t i = 0; i < num_records; i++) {
        record_array[i] = malloc(sizeof(Record));
        if (!record_array[i]) {
            printf("Error: Failed to allocate memory for record %zu\n", i);
            free(offset_array);
            free(key_array);
            free(record_array);
            return;
        }
        record_array[i]->key = key_array[i];
    }
}

// Function to clean up memory allocated for the arrays and records
void cleanup_records(long* offset_array, int* key_array, Record** record_array, size_t num_records) {
    // Free the offset array
    free(offset_array);

    // Free the key array
    free(key_array);

    // Free the record array
