#include <stdlib.h>
#include <stdio.h>
#include <string.h>
#include <time.h>

// Define a struct to represent an item
struct item {
    int integer;
    float floating_point;
    char* string;
};

// Define a function to retrieve data from an external source
void retrieve_data(int range[2], float interval[2], char** phrases, int num_phrases) {
    // Initialize the arrays for double precision floats, chars, and struct items
    double* doubles = malloc(sizeof(double) * 3);
    char* strings = malloc(sizeof(char) * 100);
    struct item* items = malloc(sizeof(struct item) * 3);

    // Initialize the random number generator
    srand(time(NULL));

    // Retrieve data from external source and store in arrays
    for (int i = 0; i < 3; i++) {
        doubles[i] = rand() % range[1] + range[0];
        strings[i] = phrases[rand() % num_phrases];
        items[i].integer = rand() % range[1] + range[0];
        items[i].floating_point = (float)rand() / RAND_MAX * interval[1] + interval[0];
        items[i].string = malloc(strlen(strings[i]) + 1);
        strcpy(items[i].string, strings[i]);
    }

    // Print the data to the console for testing purposes
    printf("Doubles: ");
    for (int i = 0; i < 3; i++) {
        printf("%.2f ", doubles[i]);
    }
    printf("\n");
    printf("Strings: ");
    for (int i = 0; i < 3; i++) {
        printf("%s ", strings[i]);
    }
    printf("\n");
    printf("Items: ");
    for (int i = 0; i < 3; i++) {
        printf("{ %d, %.2f, %s } ", items[i].integer, items[i].floating_point, items[i].string);
    }
    printf("\n");

    // Clean up memory
    free(doubles);
    free(strings);
    for (int i = 0; i < 3; i++) {
        free(items[i].string);
    }
    free(items);
}
