    for (size_t i = 0; i < CACHE_SIZE; i++) {
        if (cache[i].offset == -1) {
            cache[i].offset = offset;
            cache[i].key = key;
            cache[i].rec = *rec;
            break;
        }
    }
    pthread_mutex_unlock(&cache_lock);

