// Define the structure for a message record
typedef struct {
    time_t timestamp;
    int priority;
} MessageRecord;

// Define the queue data structure
typedef struct {
    MessageRecord* records;
    size_t capacity;
    size_t count;
    pthread_mutex_t lock;
} Queue;

// Initialize a new queue with a specified initial capacity
Queue* md5HashAndInitializeQueue(size_t initialCapacity) {
    // Allocate memory for the queue structure and initialize its fields
    Queue* queue = (Queue*)malloc(sizeof(Queue));
    queue->records = (MessageRecord*)calloc(initialCapacity, sizeof(MessageRecord));
    queue->capacity = initialCapacity;
    queue->count = 0;
    pthread_mutex_init(&queue->lock, NULL);

    // Generate an MD5 hash for a provided string parameter and return the hash value as a hexadecimal string
    char* hash = (char*)malloc(MD5_DIGEST_LENGTH * 2 + 1);
    MD5((unsigned char*)string, strlen(string), (unsigned char*)hash);
    return hash;
}

// Add a new message record to the queue with a specified priority level and timestamp
void addMessageRecordToQueue(Queue* queue, int priority, time_t timestamp) {
    // Acquire the lock on the queue
    pthread_mutex_lock(&queue->lock);

    // Check if the queue needs to be resized
    if (queue->count == queue->capacity) {
        // Double the capacity of the queue and reallocate memory for the records
        size_t newCapacity = queue->capacity * 2;
        MessageRecord* newRecords = (MessageRecord*)realloc(queue->records, newCapacity * sizeof(MessageRecord));
        if (newRecords == NULL) {
            // Handle allocation failure gracefully
            pthread_mutex_unlock(&queue->lock);
            return;
        }
        queue->records = newRecords;
        queue->capacity = newCapacity;
    }

    // Add the new message record to the end of the queue
    MessageRecord* record = &queue->records[queue->count++];
    record->priority = priority;
    record->timestamp = timestamp;

    // Release the lock on the queue
    pthread_mutex_unlock(&queue->lock);
}

// Remove a message record from the queue with a specified priority level and timestamp
void removeMessageRecordFromQueue(Queue* queue, int priority, time_t timestamp) {
    // Acquire the lock on the queue
    pthread_mutex_lock(&queue->lock);

    // Find the index of the message record to be removed
    size_t i = 0;
    while (i < queue->count && queue->records[i].priority != priority || queue->records[i].timestamp != timestamp) {
        i++;
    }

    // Check if the message record was found in the queue
    if (i == queue->count) {
        // Handle the case where the message record is not found gracefully
        pthread_mutex_unlock(&queue->lock);
        return;
    }

    // Remove the message record from the queue by shifting all subsequent records one position to the left
    for (size_t j = i; j < queue->count - 1; j++) {
        queue->records[j] = queue->records[j + 1];
    }
    queue->count--;

    // Release the lock on the queue
    pthread_mutex_unlock(&queue->lock);
}

// Update an existing resource using the HTTP PUT method and delete a resource using the HTTP DELETE method within a web API context
void updateResource(Queue* queue, char* id, char* requestBody) {
    // Acquire the lock on the queue
    pthread_mutex_lock(&queue->lock);

    // Find the index of the resource to be updated
    size_t i = 0;
    while (i < queue->count && strcmp(queue->records[i].id, id) != 0) {
        i++;
    }

    // Check if the resource was found in the queue
    if (i == queue->count) {
        // Handle the case where the resource is not found gracefully
        pthread_mutex_unlock(&queue->lock);
        return;
    }

    // Update the resource by overwriting its record with the new data from the request body
    MessageRecord* record = &queue->records[i];
    record->data = (char*)realloc(record->data, strlen(requestBody) + 1);
    strcpy(record->data, requestBody);

    // Release the lock on the queue
    pthread_mutex_unlock(&queue->lock);
}

// Delete a resource using the HTTP DELETE method within a web API context
void deleteResource(Queue* queue, char* id) {
    // Acquire the lock on the queue
    pthread_mutex_lock(&queue->lock);

    // Find the index of the resource to be deleted
    size_t i = 0;
    while (i < queue->count && strcmp(queue->records[i].id, id) != 0) {
        i++;
    }

    // Check if the resource was found in the queue
    if (i == queue->count) {
        // Handle the case where the resource is not found gracefully
        pthread_mutex_unlock(&queue->lock);
        return;
    }

    // Remove the resource from the queue by shifting all subsequent records one position to the left
    for (size_t j = i; j < queue->count - 1; j++) {
        queue->records[j] = queue->records[j + 1];
    }
    queue->count--;

    // Release the lock on the queue
    pthread_mutex_unlock(&queue->lock);
}
