typedef struct {
    Entry** entries;
    size_t capacity;
    size_t count;
    pthread_mutex_t mutex;
} Cache;

// Initialize the cache with a given capacity
void initCache(Cache* cache, size_t capacity) {
    cache->entries = (Entry**)malloc(capacity * sizeof(Entry*));
    cache->capacity = capacity;
    cache->count = 0;
    pthread_mutex_init(&cache->mutex, NULL);
}

// Add an entry to the cache if it is not already present
void addToCache(Cache* cache, Entry* entry) {
    pthread_mutex_lock(&cache->mutex);
    for (size_t i = 0; i < cache->count; i++) {
        if (cache->entries[i] == entry) {
            // Entry is already in the cache, do nothing
            pthread_mutex_unlock(&cache->mutex);
            return;
        }
    }
    // Add the new entry to the end of the cache
    cache->entries[cache->count++] = entry;
    pthread_mutex_unlock(&cache->mutex);
}

// Remove an entry from the cache if it is present
void removeFromCache(Cache* cache, Entry* entry) {
    pthread_mutex_lock(&cache->mutex);
    for (size_t i = 0; i < cache->count; i++) {
        if (cache->entries[i] == entry) {
            // Remove the entry from the cache
            cache->entries[i] = NULL;
            pthread_mutex_unlock(&cache->mutex);
            return;
        }
    }
    pthread_mutex_unlock(&cache->mutex);
}

