['```python
import os
import csv
import json
from concurrent.futures import ThreadPoolExecutor
from time import perf_counter
from typing import List, Dict

def read_csv(filepath: str, delimiter: str = ',', encoding: str = 'utf-8') -> List[Dict]:
    """Read a CSV file in chunks to minimize memory usage and handle large files."""
    with open(filepath, 'r', newline='', encoding=encoding) as f:
        reader = csv.reader(f, delimiter=delimiter)
        rows = []
        for row in reader:
            rows.append(row)
        return rows

def read_json(filepath: str, encoding: str = 'utf-8') -> List[Dict]:
    """Read a JSON file and convert it to a list of dictionaries."""
    with open(filepath, 'r', encoding=encoding) as f:
        data = json.load(f)
        return data

def write_csv(filepath: str, rows: List[Dict], delimiter: str = ',', encoding: str = 'utf-8'):
    """Write a list of dictionaries to a CSV file."""
    with open(filepath, 'w', newline='', encoding=encoding) as f:
        writer = csv.writer(f, delimiter=delimiter)
        for row in rows:
            writer.writerow(row)

def write_json(filepath: str, data: List[Dict], encoding: str = 'utf-8'):
    """Write a list of dictionaries to a JSON file."""
    with open(filepath, 'w', encoding=encoding) as f:
        json.dump(data, f)

def read_file(filepath: str, delimiter: str = ',', encoding: str = 'utf-8') -> List[Dict]:
    """Read a file and convert it to a list of dictionaries."""
    if os.path.splitext(filepath)[1] == '.csv':
        return read_csv(filepath, delimiter=delimiter, encoding=encoding)
    elif os.path.splitext(filepath)[1] == '.json':
        return read_json(filepath, encoding=encoding)
    else:
        raise ValueError('Unsupported file format')

def write_file(filepath: str, data: List[Dict], delimiter: str = ',', encoding: str = 'utf-8'):
    """Write a list of dictionaries to a file."""
    if os.path.splitext(filepath)[1] == '.csv':
        return write_csv(filepath, data, delimiter=delimiter, encoding=encoding)
    elif os.path.splitext(filepath)[1] == '.json':
        return write_json(filepath, data, encoding=encoding)
    else:
        raise ValueError('Unsupported file format')

def query_data(filepath: str, query: str, delimiter: str = ',', encoding: str = 'utf-8') -> List[Dict]:
    """Query a dataset and return the results as a list of dictionaries."""
    data = read_file(filepath, delimiter=delimiter, encoding=encoding)
    if query == '':
        return data
    else:
        return [row for row in data if query in row]

def process_data(filepath: str, query: str, delimiter: str = ',', encoding: str = 'utf-8') -> List[Dict]:
    """Process a dataset and return the results as a list of dictionaries."""
    start = perf_counter()
    data = read_file(filepath, delimiter=delimiter, encoding=encoding)
    end = perf_counter()
    print(f'Reading file took {end - start} seconds')
    if query == '':
        return data
    else:
        start = perf_counter()
        results = [row for row in data if query in row]
        end = perf_counter()
        print(f'Querying data took {end - start} seconds')
        return results

def write_results(filepath: str, data: List[Dict], delimiter: str = ',', encoding: str = 'utf-8'):
    """Write the results of a query to a file."""
    with open(filepath, 'w', newline='', encoding=encoding) as f:
        writer = csv.writer(f, delimiter=delimiter)
        for row in data:
            writer.writerow(row)

def read_directory(directory: str, recursive: bool = False, delimiter: str = ',', encoding: str = 'utf-8') -> List[Dict]:
    """Read a directory of files and return the results as a list of dictionaries."""
    data = []
    for root, dirs, files in os.walk(directory):
        for file in files:
            if os.path.splitext(file)[1] == '.csv':
                filepath = os.path.join(root, file)
                data += read_file(filepath, delimiter=delimiter, encoding=encoding)
    return data

def write_directory(directory: str, data: List[Dict], recursive: bool = False, delimiter: str = ',', encoding: str = 'utf-8'):
    """Write the results of a query to a directory of files."""
    for root, dirs, files in os.walk(directory):
        for file in files:
            if os.path.splitext(file)[1] == '.csv':
                filepath = os.path.join(root, file)
                write_file(filepath, data, delimiter=delimiter, encoding=encoding)

def query_directory(directory: str, query: str, recursive: bool = False, delimiter: str = ',', encoding: str = 'utf-8') -> List[Dict]:
    """Query a directory of files and return the results as a list of dictionaries."""
    data = read_directory(directory, recursive=recursive, delimiter=delimiter, encoding=encoding)
    if query == '':
        return data
    else:
        return [row for row in data if query in row]

def process_directory(directory: str, query: str, recursive: bool = False, delimiter: str = ',', encoding: str = 'utf-8') -> List[Dict]:
    """Process a directory of files and return the results as a list of dictionaries."""
    start = perf_counter()
    data = read_directory(directory, recursive=recursive, delimiter=delimiter, encoding=encoding)
    end = perf_counter()
    print(f'Reading directory took {end - start} seconds')
    if query == '':
        return data
    else:
        start = perf_counter()
        results = [row for row in data if query in row]
        end = perf_counter()
        print(f'Querying data took {end - start} seconds')
        return results
