    free(records);

    return NULL;
}

int main(int argc, char* argv[]) {
    if (argc < 2) {
        printf("Usage: %s <file_path>\n", argv[0]);
        return 1;
    }

    // Create a semaphore for synchronizing access to the records
    sem_t* sem = sem_open("/sem", O_CREAT, 0644, 1);
    if (sem == SEM_FAILED) {
        perror("Error creating semaphore");
        return 1;
    }

    // Create a thread for processing the file
    pthread_t thread;
    int ret = pthread_create(&thread, NULL, process_file, argv[1]);
    if (ret != 0) {
        perror("Error creating thread");
        sem_close(sem);
        return 1;
    }

    // Wait for the thread to finish
    ret = pthread_join(thread, NULL);
    if (ret != 0) {
        perror("Error joining thread");
        sem_close(sem);
        return 1;
    }

    // Close the semaphore
    sem_close(sem);

    return 0;
}
