void read_and_transform(char* input_file, char* output_file, char* rules) {
    // Initialize the arrays for storing the data
    double* timestamp_array = malloc(sizeof(double) * 50000);
    char** log_message_array = malloc(sizeof(char*) * 50000);
    struct Event* event_array = malloc(sizeof(struct Event) * 50000);
    int* priority_array = malloc(sizeof(int) * 50000);
    char** metadata_array = malloc(sizeof(char*) * 50000);

    // Initialize the random number generator
    srand(time(NULL));

    // Read the input file and populate the arrays
    FILE* input = fopen(input_file, "rb");
    if (input == NULL) {
        printf("Error: unable to open input file\n");
        return;
    }
    for (int i = 0; i < 50000; i++) {
        // Read the timestamp and event type from the input file
        fread(&timestamp_array[i], sizeof(double), 1, input);
        fread(&event_array[i].event_type, sizeof(int), 1, input);

        // Generate a random payload size for the event
        int payload_size = rand() % 50 + 1;
        event_array[i].payload = malloc(sizeof(char) * payload_size);
        fread(event_array[i].payload, sizeof(char), payload_size, input);

        // Generate a random priority for the event
        priority_array[i] = rand() % 10 + 1;

        // Generate a unique log message and metadata string
        char* log_message = malloc(sizeof(char) * 512);
        sprintf(log_message, "Log message for event %d", i);
        log_message_array[i] = log_message;
        char* metadata = malloc(sizeof(char) * 256);
        sprintf(metadata, "%.3f|%d", timestamp_array[i], event_array[i].event_type);
        metadata_array[i] = metadata;
    }
    fclose(input);

    // Apply the transformation rules to the data
    for (int i = 0; i < 50000; i++) {
        if (strcmp(rules, "rule1") == 0) {
            // Rule 1: transform the event type to a new value
            event_array[i].event_type = rand() % 10 + 1;
        } else if (strcmp(rules, "rule2") == 0) {
            // Rule 2: transform the payload size to a new value
            int new_payload_size = rand() % 50 + 1;
            event_array[i].payload = realloc(event_array[i].payload, sizeof(char) * new_payload_size);
        } else if (strcmp(rules, "rule3") == 0) {
            // Rule 3: transform the priority to a new value
            priority_array[i] = rand() % 10 + 1;
        }
    }

    // Write the transformed data to the output file
    FILE* output = fopen(output_file, "wb");
    if (output == NULL) {
        printf("Error: unable to open output file\n");
        return;
    }
    for (int i = 0; i < 50000; i++) {
        // Write the timestamp and event type to the output file
        fwrite(&timestamp_array[i], sizeof(double), 1, output);
        fwrite(&event_array[i].event_type, sizeof(int), 1, output);

        // Write the payload size and payload data to the output file
        int payload_size = strlen((char*)event_array[i].payload);
        fwrite(&payload_size, sizeof(int), 1, output);
        fwrite(event_array[i].payload, sizeof(char), payload_size, output);

        // Write the priority to the output file
        fwrite(&priority_array[i], sizeof(int), 1, output);

        // Write the log message and metadata string to the output file
        int log_message_length = strlen(log_message_array[i]);
        fwrite(&log_message_length, sizeof(int), 1, output);
        fwrite(log_message_array[i], sizeof(char), log_message_length, output);
        int metadata_length = strlen(metadata_array[i]);
        fwrite(&metadata_length, sizeof(int), 1, output);
        fwrite(metadata_array[i], sizeof(char), metadata_length, output);
    }
    fclose(output);

    // Clean up the memory allocated for the arrays
    free(timestamp_array);
    free(log_message_array);
    free(event_array);
    free(priority_array);
    free(metadata_array);
}
