    size_t capacity, size;
} Buffer;

// Function to allocate and initialize memory for the list of nodes
Node* create_node_list(size_t num_elements) {
    // Check if the number of elements is positive
    if (num_elements <= 0) {
        return NULL;
    }

    // Allocate memory for the list of nodes
    Node* nodes = malloc(sizeof(Node) * num_elements);
    if (!nodes) {
        return NULL;
    }

    // Initialize each node in the list with a custom alignment
    size_t i;
    for (i = 0; i < num_elements; ++i) {
        nodes[i].name = malloc(sizeof(char) * MAX_ALIGNMENT);
        if (!nodes[i].name) {
            free(nodes);
            return NULL;
        }
        nodes[i].priority = 0;
    }

    // Return a pointer to the list of nodes
    return nodes;
}

// Function to allocate and initialize memory for the multi-dimensional array
Grid* create_grid(size_t rows, size_t cols) {
    // Check if the dimensions are positive
    if (rows <= 0 || cols <= 0) {
        return NULL;
    }

    // Allocate memory for the grid
    Grid* grid = malloc(sizeof(Grid));
    if (!grid) {
        return NULL;
    }

    // Initialize each element in the grid with a custom alignment
    size_t i, j;
    for (i = 0; i < rows; ++i) {
        for (j = 0; j < cols; ++j) {
            grid->values[i * cols + j] = 0.0f;
        }
    }

    // Return a pointer to the grid
    return grid;
}

// Function to allocate and initialize memory for the circular buffer
