    size_t capacity;
    size_t count;
    pthread_mutex_t mutex;
} Queue;

// Function to initialize the queue with a given capacity
void initQueue(Queue* queue, size_t capacity) {
    // Allocate memory for the message array
    queue->messages = (Message*)malloc(capacity * sizeof(Message));
    if (!queue->messages) {
        fprintf(stderr, "Failed to allocate memory for message array\n");
        exit(1);
    }

    // Initialize the mutex and set the capacity and count to 0
    pthread_mutex_init(&queue->mutex, NULL);
    queue->capacity = capacity;
    queue->count = 0;
}

// Function to enqueue a message in the queue
void enqueue(Queue* queue, Message* message) {
    // Acquire the mutex lock
    pthread_mutex_lock(&queue->mutex);

    // Check if the queue is full
    if (queue->count == queue->capacity) {
        fprintf(stderr, "Queue is full\n");
        exit(1);
    }

    // Add the message to the end of the queue
    queue->messages[queue->count++] = *message;

    // Release the mutex lock
    pthread_mutex_unlock(&queue->mutex);
}

// Function to dequeue a message from the queue
Message* dequeue(Queue* queue) {
    // Acquire the mutex lock
    pthread_mutex_lock(&queue->mutex);

    // Check if the queue is empty
    if (queue->count == 0) {
        fprintf(stderr, "Queue is empty\n");
        exit(1);
    }

    // Remove the front message from the queue
    Message* message = &queue->messages[0];
    for (size_t i = 0; i < queue->count - 1; i++) {
        queue->messages[i] = queue->messages[i + 1];
    }
    queue->count--;

    // Release the mutex lock
    pthread_mutex_unlock(&queue->mutex);

    return message;
}

