    table->pairs = malloc(sizeof(pair*) * hash_capacity);
    if (!table->pairs) {
        fprintf(stderr, "Failed to allocate memory for pairs in dynamic hash table\n");
        free(table);
        return NULL;
    }

    // Initialize the pairs to empty values
