        if (index < 0 || index >= cache_size) {
            printf("Invalid index\n");
            return NULL;
        }
        return &cache[index];
    }

    // Define the function to add a record to the cache
    void cache_add(record *cache, int cache_size, int cache_capacity, record *record) {
        if (cache_size == cache_capacity) {
            printf("Cache is full\n");
            return;
        }
        cache[cache_size++] = *record;
    }

    // Define the function to remove a record from the cache
