// Dynamic Linked List
typedef struct item {
  char* name;
  float rating;
  struct item* next;
} item_t;

item_t* head = NULL;
int size = 0;

void init_list() {
  head = NULL;
  size = 0;
}

void insert(char* name, float rating) {
  item_t* new_node = malloc(sizeof(item_t));
  new_node->name = strdup(name);
  new_node->rating = rating;
  new_node->next = NULL;

  if (head == NULL) {
    head = new_node;
  } else {
    item_t* current = head;
    while (current->next != NULL) {
      current = current->next;
    }
    current->next = new_node;
  }

  size++;
}

void delete(char* name) {
  if (head == NULL) {
    // Handle empty list
    return;
  }

  item_t* current = head;
  while (current != NULL && strcmp(current->name, name) != 0) {
    current = current->next;
  }

  if (current == NULL) {
    // Handle non-existent node
    return;
  }

  item_t* previous = current->previous;
  if (previous == NULL) {
    head = current->next;
  } else {
    previous->next = current->next;
  }

  free(current);
  size--;
}

void update(char* name, float rating) {
  item_t* current = head;
  while (current != NULL && strcmp(current->name, name) != 0) {
    current = current->next;
  }

  if (current == NULL) {
    // Handle non-existent node
    return;
  }

  current->rating = rating;
}

void traverse() {
  item_t* current = head;
  while (current != NULL) {
    printf("%s: %f\n", current->name, current->rating);
    current = current->next;
  }
}

void free_list() {
  item_t* current = head;
  while (current != NULL) {
    item_t* next = current->next;
    free(current);
    current = next;
  }
  head = NULL;
  size = 0;
}
