// Circular Queue
typedef struct node {
  char* name;
  float rating;
  struct node* next;
} node_t;

node_t* head = NULL;
int size = 0;
int capacity = 0;

void init_queue(int queue_capacity) {
  if (queue_capacity <= 0) {
    // Handle invalid input
    return;
  }
  capacity = queue_capacity;
  head = malloc(sizeof(node_t) * capacity);
  size = 0;
}

void enqueue(char* name, float rating) {
  if (size >= capacity) {
    // Handle overflow
    return;
  }

  node_t* new_node = malloc(sizeof(node_t));
  new_node->name = strdup(name);
  new_node->rating = rating;
  new_node->next = NULL;

  if (head == NULL) {
    head = new_node;
  } else {
    node_t* current = head;
    while (current->next != NULL) {
      current = current->next;
    }
    current->next = new_node;
  }

  size++;
}

void dequeue() {
  if (head == NULL) {
    // Handle empty queue
    return;
  }

  node_t* current = head;
  while (current != NULL && current->next != NULL) {
    current = current->next;
  }

  free(current);
  size--;
}

void check_queue() {
  if (size == 0) {
    // Handle empty queue
    return;
  }

  node_t* current = head;
  while (current != NULL && current->next != NULL) {
    current = current->next;
  }

  if (current == NULL) {
    // Handle non-existent node
    return;
  }
}

void update(char* name, float rating) {
  node_t* current = head;
  while (current != NULL && strcmp(current->name, name) != 0) {
    current = current->next;
  }

  if (current == NULL) {
    // Handle non-existent node
    return;
  }

  current->rating = rating;
}

void free_queue() {
  node_t* current = head;
  while (current != NULL) {
    node_t* next = current->next;
    free(current);
    current = next;
  }
  head = NULL;
  size = 0;
}
