typedef struct {
    char* name;
    int count;
} BookCount;

// Function to dynamically allocate memory for arrays
void allocate_arrays(int num_offsets, int num_keys, int num_records) {
    // Validate input parameters
    if (num_offsets < 0 || num_keys < 0 || num_records < 0) {
        fprintf(stderr, "Invalid input parameters\n");
        return;
    }

    // Allocate memory for arrays
    long* offsets = malloc(num_offsets * sizeof(long));
    int* keys = malloc(num_keys * sizeof(int));
    record* records = malloc(num_records * sizeof(record));

    // Initialize arrays with random values
    srand(time(NULL));
    for (int i = 0; i < num_offsets; i++) {
        offsets[i] = rand() % 1000;
    }
    for (int i = 0; i < num_keys; i++) {
        keys[i] = rand() % 1000;
    }
    for (int i = 0; i < num_records; i++) {
        records[i].value = rand() % 1000;
    }

    // Handle memory allocation errors
    if (!offsets || !keys || !records) {
        fprintf(stderr, "Memory allocation error\n");
        free(offsets);
        free(keys);
        free(records);
        return;
    }
}

// Function to process string input and extract book names
void process_string(const char* text) {
    // Initialize variables for caching and counting
    BookCount* cache = malloc(sizeof(BookCount));
    int count = 0;

    // Loop through each word in the text
    const char* word = strtok(text, " ");
    while (word != NULL) {
        // Check if word is a book name
        bool found_book = false;
        for (int i = 0; i < sizeof(old_testament_books); i++) {
            if (strcmp(word, old_testament_books[i]) == 0) {
                found_book = true;
                break;
            }
        }

        // If word is a book name, increment count and add to cache
        if (found_book) {
            count++;
            cache->name = strdup(word);
            cache->count = 1;
        } else {
            // Check if word is punctuation or special character
            regex_t reg;
            int reti = regcomp(&reg, punctuation_regex, REG_EXTENDED | REG_ICASE);
            if (reti) {
                fprintf(stderr, "Regex compilation failed\n");
                return;
            }
            reti = regexec(&reg, word, 0, NULL, 0);
            regfree(&reg);
            if (!reti) {
                // If word is punctuation or special character, ignore it
                continue;
            }
        }

        // Add cache to list of book names and reset count
        if (cache->count > 0) {
            BookCount* new_cache = malloc(sizeof(BookCount));
            new_cache->name = strdup(cache->name);
            new_cache->count = cache->count;
            cache = new_cache;
            count = 1;
        } else {
            // If word is not a book name, reset count
            count = 0;
        }

        // Move to next word in text
        word = strtok(NULL, " ");
    }

    // Free cache and return list of book names and counts
    free(cache);
