#include <regex.h>

// Define regular expressions for severity levels
const char* SEVERITY_LEVELS[] = {
    "EMERGENCY",
    "ALERT",
    "CRITICAL",
    "ERROR",
    "WARNING",
    "NOTICE",
    "INFO",
    "DEBUG"
};
const int NUM_SEVERITY_LEVELS = sizeof(SEVERITY_LEVELS) / sizeof(char*);

// Define a structure to store log entries
typedef struct {
    char* message;
    char* severity;
} LogEntry;

// Define a function to parse and categorize log events
LogEntry* parseLogEvents(const char* logFile) {
    // Initialize variables for parsing and categorization
    int numEntries = 0;
    int entryIndex = 0;
    regex_t regex;
    regmatch_t matches[NUM_SEVERITY_LEVELS];
    LogEntry* entries = NULL;

    // Compile regular expressions for severity levels
    if (regcomp(&regex, SEVERITY_LEVELS[0], REG_EXTENDED | REG_ICASE) != 0) {
        fprintf(stderr, "Error compiling regular expression\n");
        return NULL;
    }

    // Open log file and read each line
    FILE* file = fopen(logFile, "r");
    if (file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        return NULL;
    }
    char* line = NULL;
    size_t len = 0;
    ssize_t read;
    while ((read = getline(&line, &len, file)) != -1) {
        // Check if line matches any regular expression for severity levels
        int match = regexec(&regex, line, NUM_SEVERITY_LEVELS, matches, 0);
        if (match == REG_NOMATCH) {
            continue;
        }

        // Allocate memory for log entry and initialize fields
        LogEntry* entry = malloc(sizeof(LogEntry));
        entry->message = strdup(line);
        entry->severity = strdup(SEVERITY_LEVELS[match]);

        // Add log entry to list of entries
        if (entries == NULL) {
            entries = malloc(sizeof(LogEntry));
        } else {
            entries = realloc(entries, sizeof(LogEntry) * (numEntries + 1));
        }
        entries[entryIndex++] = entry;
        numEntries++;
    }

    // Clean up resources and return list of log entries
    fclose(file);
    free(line);
    regfree(&regex);
    return entries;
}

