#include <stdlib.h>
#include <stdio.h>
#include <time.h>

typedef struct {
    int value;
    long *long_ptr;
    int *int_ptr;
} record;

void init_arrays(size_t num_records, size_t max_value) {
    // Allocate memory for the arrays
    long *offset_arr = malloc(num_records * sizeof(long));
    int *key_arr = malloc(num_records * sizeof(int));
    record *record_arr = malloc(num_records * sizeof(record));

    // Check for memory allocation failures
    if (offset_arr == NULL || key_arr == NULL || record_arr == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        return;
    }

    // Initialize the arrays with random values within the specified range
    srand(time(NULL));
    for (size_t i = 0; i < num_records; i++) {
        offset_arr[i] = rand() % max_value + 1;
        key_arr[i] = rand() % max_value + 1;
        record_arr[i].value = rand() % max_value + 1;
        record_arr[i].long_ptr = &offset_arr[i];
        record_arr[i].int_ptr = &key_arr[i];
    }

    // Verify that all pointers are correctly allocated and valid
    for (size_t i = 0; i < num_records; i++) {
        if (record_arr[i].long_ptr == NULL || record_arr[i].int_ptr == NULL) {
            fprintf(stderr, "Pointer allocation failed\n");
            return;
        }
    }

    // Dynamic resizing of the arrays if necessary
    size_t new_size = num_records * 2;
    while (new_size > num_records) {
        long *tmp_offset_arr = realloc(offset_arr, new_size * sizeof(long));
        int *tmp_key_arr = realloc(key_arr, new_size * sizeof(int));
        record *tmp_record_arr = realloc(record_arr, new_size * sizeof(record));
        if (tmp_offset_arr == NULL || tmp_key_arr == NULL || tmp_record_arr == NULL) {
            fprintf(stderr, "Memory reallocation failed\n");
            return;
        } else {
            offset_arr = tmp_offset_arr;
            key_arr = tmp_key_arr;
            record_arr = tmp_record_arr;
            num_records *= 2;
        }
    }

    // Release all allocated memory when the function completes execution
    free(offset_arr);
    free(key_arr);
    free(record_arr);
}
```
