typedef struct {
    int key;
    char value[16];
} record;

record* create_records(int num_records) {
    // Check if the number of records is valid
    if (num_records <= 0 || num_records > 10000) {
        return NULL;
    }

    // Allocate memory for the long and int arrays
    long* offsets = malloc(sizeof(long) * num_records);
    int* keys = malloc(sizeof(int) * num_records);
    if (offsets == NULL || keys == NULL) {
        free(offsets);
        free(keys);
        return NULL;
    }

    // Initialize the arrays with zeros
    for (int i = 0; i < num_records; i++) {
        offsets[i] = 0;
        keys[i] = 0;
    }

    // Allocate memory for the record array
    record* records = malloc(sizeof(record) * num_records);
    if (records == NULL) {
        free(offsets);
        free(keys);
        return NULL;
    }

    // Populate the record array with random values and characters
    srand(time(NULL));
    for (int i = 0; i < num_records; i++) {
        records[i].key = rand() % 2000 - 1000;
        for (int j = 0; j < 16; j++) {
            records[i].value[j] = rand() % 95 + 32;
        }
    }

    // Free the memory allocated for the arrays
    free(offsets);
    free(keys);

    return records;
}
