// Custom random number generator
uint32_t rand_num(uint32_t min, uint32_t max) {
    return (rand() % (max - min + 1)) + min;
}

// Structures for data processing pipeline
typedef struct offset_t {
    int64_t value;
} offset_t;

typedef struct key_t {
    int32_t value;
} key_t;

typedef struct record_t {
    offset_t* offset;
    uint32_t value;
} record_t;

// Pipeline state structure
typedef struct pipeline_state {
    offset_t* offsets;
    key_t* keys;
    record_t* records;
    size_t num_offsets;
    size_t num_keys;
    uint32_t min_value;
    uint32_t max_value;
    int64_t min_increment;
} pipeline_state;

// Function to manage memory allocation and initialization for data processing pipeline
pipeline_state* allocate_pipeline(size_t num_offsets, size_t num_keys, uint32_t min_value, uint32_t max_value, int64_t min_increment) {
    // Check for valid input parameters
    if (num_offsets == 0 || num_keys == 0 || min_value > max_value || min_increment < 1) {
        return NULL;
    }

    // Allocate memory for offset array
    size_t offset_size = sizeof(offset_t) * num_offsets;
    offset_t* offsets = (offset_t*)malloc(offset_size);
    if (!offsets) {
        return NULL;
    }

    // Initialize offset array with sequential values starting from 0
    for (size_t i = 0; i < num_offsets; i++) {
        offsets[i].value = i * min_increment;
    }

    // Check for duplicate consecutive elements in the offset array
    for (size_t i = 1; i < num_offsets; i++) {
        if (offsets[i - 1].value + min_increment != offsets[i].value) {
            free(offsets);
            return NULL;
        }
    }

    // Allocate memory for key array
    size_t key_size = sizeof(key_t) * num_keys;
    key_t* keys = (key_t*)malloc(key_size);
    if (!keys) {
        free(offsets);
        return NULL;
    }

    // Initialize key array with unique values within the range [0, num_keys - 1]
    for (size_t i = 0; i < num_keys; i++) {
        keys[i].value = i;
    }

    // Check for duplicate keys in the key array
    for (size_t i = 1; i < num_keys; i++) {
        if (keys[i - 1].value == keys[i].value) {
            free(offsets);
            free(keys);
            return NULL;
        }
    }

    // Allocate memory for record array
    size_t record_size = sizeof(record_t) * num_offsets;
    record_t* records = (record_t*)malloc(record_size);
    if (!records) {
        free(offsets);
        free(keys);
        return NULL;
    }

    // Initialize record array with pointers to corresponding offset values and random values within the range [min_value, max_value]
    for (size_t i = 0; i < num_offsets; i++) {
        records[i].offset = &offsets[i];
        records[i].value = rand_num(min_value, max_value);
    }

    // Check for invalid pointer dereferences and handle them gracefully
    if (records[0].offset == NULL || records[0].value < min_value || records[0].value > max_value) {
        free(offsets);
        free(keys);
        free(records);
        return NULL;
    }

    // Allocate memory for pipeline state structure
    pipeline_state* state = (pipeline_state*)malloc(sizeof(pipeline_state));
    if (!state) {
        free(offsets);
        free(keys);
        free(records);
        return NULL;
    }

    // Initialize pipeline state structure with pointers to allocated structures and user-provided parameters
    state->offsets = offsets;
    state->keys = keys;
    state->records = records;
    state->num_offsets = num_offsets;
    state->num_keys = num_keys;
    state->min_value = min_value;
    state->max_value = max_value;
    state->min_increment = min_increment;

    return state;
}

// Function to handle memory deallocation in case of errors during allocation
void free_pipeline(pipeline_state* state) {
    if (state == NULL) {
        return;
    }

    // Deallocate memory for pipeline state structure
    free(state);

    // Deallocate memory for record array
    free(state->records);

    // Deallocate memory for key array
    free(state->keys);

    // Deallocate memory for offset array
    free(state->offsets);
}
