#include <pthread.h>
#include <errno.h>

#define MAX_CONNECTIONS 10000
#define BUFFER_SIZE 4096
#define TIMEOUT 5 // seconds

// Structure to hold information about each client connection
typedef struct {
    int socket;
    char* buffer;
} ClientConnection;

// Function to handle incoming connections and manage active sessions
void* handle_connections(void* arg) {
    int server_socket = (int)arg;
    while (1) {
        // Accept a new connection from the client
        struct sockaddr_in client_address;
        socklen_t address_length = sizeof(client_address);
        int client_socket = accept(server_socket, (struct sockaddr*)&client_address, &address_length);
        if (client_socket < 0) {
            perror("accept");
            continue;
        }

        // Create a new buffer for the client connection
        char* buffer = malloc(BUFFER_SIZE);
        if (!buffer) {
            perror("malloc");
            close(client_socket);
            continue;
        }

        // Add the new client to the list of active connections
        ClientConnection* connection = malloc(sizeof(ClientConnection));
        connection->socket = client_socket;
        connection->buffer = buffer;
        pthread_mutex_lock(&connections_mutex);
        connections[connection_count++] = connection;
        pthread_mutex_unlock(&connections_mutex);
    }
}

// Function to handle incoming messages from clients and forward them to the server
void* handle_messages(void* arg) {
    int client_socket = (int)arg;
    while (1) {
        // Receive a message from the client
        char* buffer = malloc(BUFFER_SIZE);
        if (!buffer) {
            perror("malloc");
            close(client_socket);
            continue;
        }
        int bytes_received = recv(client_socket, buffer, BUFFER_SIZE, 0);
        if (bytes_received < 0) {
            perror("recv");
            free(buffer);
            close(client_socket);
            continue;
        }

        // Forward the message to the server
        int bytes_sent = send(server_socket, buffer, bytes_received, 0);
        if (bytes_sent < 0) {
            perror("send");
            free(buffer);
            close(client_socket);
            continue;
        }
    }
}

// Function to handle incoming messages from the server and forward them to clients
void* handle_server_messages(void* arg) {
    int client_socket = (int)arg;
    while (1) {
        // Receive a message from the server
        char* buffer = malloc(BUFFER_SIZE);
        if (!buffer) {
            perror("malloc");
            close(client_socket);
            continue;
        }
        int bytes_received = recv(server_socket, buffer, BUFFER_SIZE, 0);
        if (bytes_received < 0) {
            perror("recv");
            free(buffer);
            close(client_socket);
            continue;
        }

        // Forward the message to all connected clients
        pthread_mutex_lock(&connections_mutex);
        for (int i = 0; i < connection_count; i++) {
            ClientConnection* connection = connections[i];
            int bytes_sent = send(connection->socket, buffer, bytes_received, 0);
            if (bytes_sent < 0) {
                perror("send");
                free(buffer);
                close(client_socket);
                continue;
            }
        }
        pthread_mutex_unlock(&connections_mutex);
    }
}

int main() {
    // Create a socket for the server to listen on
    int server_socket = socket(AF_INET, SOCK_STREAM, 0);
    if (server_socket < 0) {
        perror("socket");
        return 1;
    }

    // Set up the address for the server to listen on
    struct sockaddr_in server_address;
    memset(&server_address, 0, sizeof(server_address));
    server_address.sin_family = AF_INET;
    server_address.sin_port = htons(8080);
    server_address.sin_addr.s_addr = INADDR_ANY;

    // Bind the socket to the address and start listening for incoming connections
    if (bind(server_socket, (struct sockaddr*)&server_address, sizeof(server_address)) < 0) {
        perror("bind");
        close(server_socket);
        return 1;
    }
    if (listen(server_socket, MAX_CONNECTIONS) < 0) {
        perror("listen");
        close(server_socket);
        return 1;
    }

    // Create a thread to handle incoming connections and manage active sessions
    pthread_t connection_handler;
    if (pthread_create(&connection_handler, NULL, handle_connections, (void*)server_socket) < 0) {
        perror("pthread_create");
        close(server_socket);
        return 1;
    }

    // Create a thread to handle incoming messages from clients and forward them to the server
    pthread_t message_handler;
    if (pthread_create(&message_handler, NULL, handle_messages, (void*)client_socket) < 0) {
        perror("pthread_create");
        close(server_socket);
        return 1;
    }

    // Create a thread to handle incoming messages from the server and forward them to clients
    pthread_t server_message_handler;
    if (pthread_create(&server_message_handler, NULL, handle_server_messages, (void*)client_socket) < 0) {
        perror("pthread_create");
        close(server_socket);
        return 1;
    }

    // Wait for the threads to finish
    pthread_join(connection_handler, NULL);
    pthread_join(message_handler, NULL);
    pthread_join(server_message_handler, NULL);

    // Close the socket and free resources
    close(server_socket);
    return 0;
}
