// Define the event structure
typedef struct {
    time_t timestamp;
    struct sockaddr_in source_ip;
    char payload[65535]; // maximum size of a packet is 65,535 bytes
} event_t;

// Define the slab allocator for memory pooling
typedef struct {
    void *memory;
    size_t size;
    size_t used;
} slab_allocator_t;

// Initialize the slab allocator with a fixed size of 1024 bytes
slab_allocator_t slab_allocator = {NULL, 1024, 0};

// Function to allocate memory for an event structure
event_t *allocate_event() {
    // Check if there is enough space in the slab allocator
    if (slab_allocator.used + sizeof(event_t) > slab_allocator.size) {
        // If not, reallocate the memory with a larger size
        slab_allocator.memory = realloc(slab_allocator.memory, slab_allocator.size * 2);
        if (slab_allocator.memory == NULL) {
            printf("Error: Failed to allocate memory for event structure\n");
            return NULL;
        }
        slab_allocator.size *= 2;
    }

    // Allocate the memory for the event structure
    event_t *event = (event_t *)(slab_allocator.memory + slab_allocator.used);
    slab_allocator.used += sizeof(event_t);

    return event;
}

// Function to free memory for an event structure
void free_event(event_t *event) {
    // Check if the event is NULL
    if (event == NULL) {
        return;
    }

    // Free the memory for the event structure
    slab_allocator.used -= sizeof(event_t);
}

// Function to read a packet from the simulated network stream and allocate an event structure for it
event_t *read_packet() {
    // Read the header of the packet from the simulated network stream
    char header[sizeof(struct sockaddr_in) + sizeof(time_t)];
    if (fread(header, 1, sizeof(header), stdin) != sizeof(header)) {
        printf("Error: Failed to read header of packet\n");
        return NULL;
    }

    // Extract the timestamp and source IP address from the header
    time_t timestamp = *((time_t *)header);
    struct sockaddr_in source_ip = *((struct sockaddr_in *)(header + sizeof(time_t)));

    // Allocate an event structure for the packet
    event_t *event = allocate_event();
    if (event == NULL) {
        printf("Error: Failed to allocate memory for event structure\n");
        return NULL;
    }

    // Fill in the timestamp and source IP address of the event structure
    event->timestamp = timestamp;
    memcpy(&(event->source_ip), &source_ip, sizeof(struct sockaddr_in));

    // Read the payload of the packet from the simulated network stream
    size_t payload_size = *((size_t *)(header + sizeof(time_t) + sizeof(struct sockaddr_in)));
    if (fread(event->payload, 1, payload_size, stdin) != payload_size) {
        printf("Error: Failed to read payload of packet\n");
        free_event(event);
        return NULL;
    }

    return event;
}

// Function to log memory usage and performance metrics at regular intervals during the execution
void log_metrics() {
    // Log the current timestamp and memory usage
    printf("[%ld] Memory usage: %lu bytes\n", time(NULL), slab_allocator.used);
}

// Function to handle a single packet from the simulated network stream
event_t *handle_packet() {
    // Read the packet from the simulated network stream
    event_t *event = read_packet();
    if (event == NULL) {
        printf("Error: Failed to read packet\n");
        return NULL;
    }

    // Log the memory usage and performance metrics at regular intervals during the execution
    log_metrics();

    return event;
}

// Function to handle multiple packets from the simulated network stream simultaneously
void handle_packets() {
    // Initialize a thread-safe queue for handling packets
    pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
    pthread_cond_t cond = PTHREAD_COND_INITIALIZER;
    queue_t *queue = create_queue(sizeof(event_t *));

    // Create a thread for each packet to be handled
    int num_threads = 0;
    while (1) {
        event_t *event = read_packet();
        if (event == NULL) {
            break;
        }

        // Add the event to the queue
        enqueue(queue, &event);

        // Create a new thread for handling the packet
        pthread_t thread;
        int rc = pthread_create(&thread, NULL, handle_packet, (void *)event);
        if (rc != 0) {
            printf("Error: Failed to create thread\n");
            free_event(event);
            continue;
        }

        // Increment the number of threads
        num_threads++;
    }

    // Wait for all threads to finish handling packets
    while (num_threads > 0) {
        pthread_cond_wait(&cond, &mutex);
        num_threads--;
    }

    // Log the memory usage and performance metrics at regular intervals during the execution
    log_metrics();
}
