            free(offsets);
            return NULL;
        }
        i++;
    }

    // Check for duplicate offsets and reallocate memory if necessary
    size_t j = 0;
    while (j < num_offsets) {
        size_t k = j + 1;
        while (k < num_offsets) {
            if (offsets[j] == offsets[k]) {
                fprintf(stderr, "Error: Duplicate offset detected\n");
                // Reallocate memory to accommodate additional unique offsets
                size_t new_num_offsets = num_offsets + 1;
                offset_t* new_offsets = (offset_t*)realloc(offsets, new_num_offsets * sizeof(offset_t));
                if (!new_offsets) {
                    fprintf(stderr, "Error: Failed to reallocate memory for offsets\n");
                    free(offsets);
                    return NULL;
                }
                // Update the number of offsets and the offset array
                num_offsets = new_num_offsets;
                offsets = new_offsets;
                break;
            }
            k++;
        }
        j++;
    }

    return offsets;
}

