    // Handle errors gracefully if the lock cannot be acquired
    if (py_acquired == NULL) {
        fprintf(stderr, "Error acquiring lock\n");
        return;
    }

    // Perform operations on the shared resource within the locked scope
    printf("Performing operations on %s within a locked scope\n", resource);

    // Release the lock using the Python `release` method
    PyObject* py_released = PyObject_CallMethod(py_lock, "release", NULL);

    // Handle errors gracefully if the lock cannot be released
    if (py_released == NULL) {
        fprintf(stderr, "Error releasing lock\n");
        return;
    }

    // Clean up Python objects
    Py_DECREF(py_module);
    Py_DECREF(py_lock);
    Py_DECREF(py_acquired);
    Py_DECREF(py_released);
}
