        return -1;
    }

    // Search for the element at the given index
    return (*grid)->data[index];
}

// Function to insert an element into the circular buffer
int insert_buffer(buffer_t** buffer, size_t capacity, char* data) {
    // Check if the input is valid
    if (buffer == NULL || *buffer == NULL || capacity <= 0 || data == NULL) {
        return -1;
    }

    // Allocate memory for the new element
    size_t index = (*buffer)->tail % capacity;
    (*buffer)->data[index] = data;

    // Update the tail pointer
    (*buffer)->tail++;

    return 0;
}

// Function to delete an element from the circular buffer
int delete_buffer(buffer_t** buffer, size_t capacity, char* data) {
    // Check if the input is valid
    if (buffer == NULL || *buffer == NULL || capacity <= 0 || data == NULL) {
        return -1;
    }

    // Find the element to delete
    for (size_t i = (*buffer)->head; i < (*buffer)->tail; i++) {
        if ((*buffer)->data[i] == data) {
            // Remove the element from the buffer
            (*buffer)->data[i] = NULL;
            break;
        }
    }

    return 0;
}

// Function to search for an element in the circular buffer by index
int search_buffer(buffer_t** buffer, size_t capacity, char* data) {
    // Check if the input is valid
    if (buffer == NULL || *buffer == NULL || capacity <= 0 || data == NULL) {
        return -1;
    }

    // Search for the element at the given index
    for (size_t i = (*buffer)->head; i < (*buffer)->tail; i++) {
        if ((*buffer)->data[i] == data) {
            return i;
        }
    }

