    for (int i = 0; i < num_records; i++) {
        if (ptrs[i] != NULL) {
            free(ptrs[i]);
        }
    }
}

// Define the function to initialize the memory pool
void init_memory_pool(memory_pool_t *pool, size_t size) {
    pool->size = size;
    pool->num_blocks = 0;
    pool->blocks = NULL;
}

// Define the function to allocate a block of memory from the pool
void *allocate_memory_from_pool(memory_pool_t *pool, size_t size) {
    if (pool->num_blocks == 0) {
        // Allocate a new block of memory if the pool is empty
        pool->blocks = allocate_memory(size);
        pool->num_blocks++;
    } else {
        // Reuse an existing block of memory from the pool
        pool->blocks[pool->num_blocks - 1] = allocate_memory(size);
    }
    return pool->blocks[pool->num_blocks - 1];
}

// Define the function to free a block of memory from the pool
void free_memory_from_pool(memory_pool_t *pool, void *ptr) {
    if (ptr != NULL) {
        // Free the specified block of memory
        free(ptr);
        pool->num_blocks--;
    }
}

// Define the function to allocate memory for multiple arrays concurrently using a memory pool
void *allocate_memory_concurrent_pool(size_t size, int num_records) {
    // Initialize the memory pool if it is not already initialized
    static memory_pool_t pool;
    if (pool.blocks == NULL) {
        init_memory_pool(&pool, MEMORY_POOL_SIZE);
    }

    // Allocate a block of memory from the pool for each array
    void **ptrs = malloc(sizeof(void *) * num_records);
