    // Free each block of memory from the pool
    for (int i = 0; i < num_records; i++) {
        if (ptrs[i] != NULL) {
            free_memory_from_pool(&pool, ptrs[i]);
        }
    }
}

// Define the function to track and report memory usage
void track_memory_usage(size_t size, int num_records) {
