void* getMemoryUsage() {
    // Calculate the total memory usage in bytes
    size_t total_usage = 0;

    // Calculate the peak memory usage in bytes
    size_t peak_usage = 0;

    // Iterate over all allocated memory blocks and calculate their sizes
    for (struct MemoryPool* pool = malloc(sizeof(struct MemoryPool)); pool != NULL; pool = pool->next) {
        total_usage += pool->size;
        if (pool->size > peak_usage) {
            peak_usage = pool->size;
        }
    }

    // Return a struct containing the total memory usage and peak memory usage in bytes
    return (void*) { total_usage, peak_usage };
}

// Function to serialize the data structures into a binary format for persistence and later reuse
void* serialize(void* ptr) {
    // Check if the input pointer is NULL or not
    if (ptr == NULL) {
        return NULL;
    }

    // Cast the input pointer to a struct MemoryPool pointer
    struct MemoryPool* pool = (struct MemoryPool*) ptr;

    // Allocate memory for the serialized data structure using standard library functions
    void* serialized_data = malloc(pool->size);

    // Serialize the data structures into the allocated memory block
    memcpy(serialized_data, pool->block, pool->size);

    // Return a pointer to the serialized data structure
    return (void*) serialized_data;
}

// Function to deserialize the data structures from a binary format for persistence and later reuse
void* deserialize(void* ptr) {
    // Check if the input pointer is NULL or not
    if (ptr == NULL) {
        return NULL;
    }

    // Cast the input pointer to a void pointer
    void* serialized_data = (void*) ptr;

    // Allocate memory for the deserialized data structure using standard library functions
    struct MemoryPool* pool = malloc(sizeof(struct MemoryPool));

    // Deserialize the data structures from the allocated memory block
    memcpy(pool->block, serialized_data, pool->size);

    // Return a pointer to the deserialized data structure
    return (void*) pool;
}
