#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pthread.h>
#include <errno.h>

// Define the task structure
typedef struct {
    char *name;
    time_t timestamp;
    enum status *status;
} task;

// Define the status enumeration
enum status {
    INITIALIZED,
    PROCESSING,
    COMPLETED,
};

// Define the function to dynamically allocate memory for tasks
task* allocate_tasks(int num_tasks) {
    // Allocate memory for the task structures
    task *tasks = (task*)malloc(num_tasks * sizeof(task));
    if (!tasks) {
        fprintf(stderr, "Error: Failed to allocate memory for tasks\n");
        return NULL;
    }

    // Initialize each task structure with random start times and predefined status values
    srand(time(NULL));
    for (int i = 0; i < num_tasks; i++) {
        tasks[i].name = malloc(16);
        if (!tasks[i].name) {
            fprintf(stderr, "Error: Failed to allocate memory for task name\n");
            return NULL;
        }
        snprintf(tasks[i].name, 16, "%08x", rand());
        tasks[i].timestamp = time(NULL);
        tasks[i].status = INITIALIZED;
    }

    // Return the allocated task structures
    return tasks;
}

// Define the function to deallocate memory for tasks
void deallocate_tasks(task *tasks, int num_tasks) {
    // Deallocate memory for each task structure
