// Define the function to process tasks concurrently
void process_tasks(task *tasks, int num_tasks) {
    // Create a mutex to synchronize access to the task structures
    pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

    // Create a thread pool for processing tasks
    pthread_t *threads = (pthread_t*)malloc(num_tasks * sizeof(pthread_t));
    if (!threads) {
        fprintf(stderr, "Error: Failed to allocate memory for threads\n");
        return;
    }

    // Initialize each thread with a task structure and start it
    for (int i = 0; i < num_tasks; i++) {
        pthread_create(&threads[i], NULL, process_task, &tasks[i]);
    }

    // Wait for all threads to finish
    for (int i = 0; i < num_tasks; i++) {
        pthread_join(threads[i], NULL);
