// Memory pool for allocating memory efficiently
struct MemoryPool {
    void *memory;
    size_t size;
};

// Function to initialize the memory pool
void initMemoryPool(struct MemoryPool *pool, size_t size) {
    pool->size = size;
    pool->memory = mmap(NULL, size, PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
}

// Function to allocate memory from the memory pool
void *allocateMemory(struct MemoryPool *pool, size_t size) {
    void *memory = mmap(NULL, size, PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
    if (memory == MAP_FAILED) {
        perror("mmap");
        exit(EXIT_FAILURE);
    }
    return memory;
}

// Function to free memory from the memory pool
void freeMemory(struct MemoryPool *pool, void *memory) {
    munmap(memory, pool->size);
}

