#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pthread.h>

// Define the client structure
typedef struct {
    char *name;
    time_t last_seen_timestamp;
    enum connection_status {CONNECTED, DISCONNECTED} connection_status;
} client;

// Define the list of clients
client **clients = NULL;
size_t num_clients = 0;
pthread_mutex_t clients_lock = PTHREAD_MUTEX_INITIALIZER;

// Initialize the clients list with random last seen timestamps and predefined connection statuses
void init_clients(size_t num_clients) {
    // Allocate memory for the clients list
    clients = (client **)malloc(num_clients * sizeof(client *));
    if (!clients) {
        perror("Failed to allocate memory for clients");
        exit(1);
    }

    // Initialize each client structure with a random last seen timestamp and predefined connection status
    for (size_t i = 0; i < num_clients; i++) {
        clients[i] = (client *)malloc(sizeof(client));
        if (!clients[i]) {
            perror("Failed to allocate memory for client");
            exit(1);
        }
        clients[i]->name = NULL;
        clients[i]->last_seen_timestamp = time(NULL) + rand() % 3600; // random last seen timestamp within the next hour
        clients[i]->connection_status = (rand() % 2 == 0) ? CONNECTED : DISCONNECTED;
    }
}

// Add a new client to the list
void add_client(const char *name, enum connection_status status) {
    // Acquire the clients lock
    pthread_mutex_lock(&clients_lock);

    // Check if the client already exists in the list
    for (size_t i = 0; i < num_clients; i++) {
        if (strcmp(name, clients[i]->name) == 0) {
            pthread_mutex_unlock(&clients_lock);
            return; // client already exists in the list
        }
    }

    // Allocate memory for the new client structure
    client *new_client = (client *)malloc(sizeof(client));
    if (!new_client) {
        perror("Failed to allocate memory for new client");
        exit(1);
    }

    // Initialize the new client structure with the given name and connection status
    new_client->name = strdup(name);
    new_client->last_seen_timestamp = time(NULL);
    new_client->connection_status = status;

    // Add the new client to the list
    clients[num_clients++] = new_client;

    // Release the clients lock
    pthread_mutex_unlock(&clients_lock);
}

// Remove a client from the list
void remove_client(const char *name) {
    // Acquire the clients lock
    pthread_mutex_lock(&clients_lock);

    // Find the client to be removed in the list
    for (size_t i = 0; i < num_clients; i++) {
        if (strcmp(name, clients[i]->name) == 0) {
            // Remove the client from the list
            free(clients[i]);
            clients[i] = NULL;

            // Decrement the number of clients
            num_clients--;

            // Shift all subsequent clients to fill the gap
            for (size_t j = i; j < num_clients; j++) {
                clients[j] = clients[j + 1];
            }

            break;
        }
    }

    // Release the clients lock
    pthread_mutex_unlock(&clients_lock);
}

// Update a client's connection status
void update_client(const char *name, enum connection_status status) {
    // Acquire the clients lock
    pthread_mutex_lock(&clients_lock);

    // Find the client to be updated in the list
    for (size_t i = 0; i < num_clients; i++) {
        if (strcmp(name, clients[i]->name) == 0) {
            // Update the client's connection status
            clients[i]->connection_status = status;
            break;
        }
    }

    // Release the clients lock
    pthread_mutex_unlock(&clients_lock);
}

// Process a batch of client data
void process_batch(size_t num_clients, const char **names, enum connection_status *statuses) {
    // Acquire the clients lock
    pthread_mutex_lock(&clients_lock);

    // Iterate over each client in the batch
    for (size_t i = 0; i < num_clients; i++) {
        const char *name = names[i];
        enum connection_status status = statuses[i];

        // Find the client in the list
        size_t j = 0;
        for (; j < num_clients; j++) {
            if (strcmp(name, clients[j]->name) == 0) {
                break;
            }
        }

        // If the client is not found in the list, add it
        if (j == num_clients) {
            add_client(name, status);
        } else {
            // Update the client's connection status
            clients[j]->connection_status = status;
        }
    }

    // Release the clients lock
    pthread_mutex_unlock(&clients_lock);
}

// Free all memory allocated for the clients list
void free_clients() {
    // Acquire the clients lock
    pthread_mutex_lock(&clients_lock);

    // Iterate over each client in the list and free its memory
    for (size_t i = 0; i < num_clients; i++) {
        free(clients[i]);
    }

    // Free the clients list itself
    free(clients);

    // Release the clients lock
    pthread_mutex_unlock(&clients_lock);
}
