// Define the sensor structure
typedef struct {
    int identifier;
    float temperature_reading;
    time_t last_reading_time;
    enum status { ACTIVE, INACTIVE } status;
} sensor_t;

// Define the list of sensors
static sensor_t *sensors = NULL;

// Define the number of sensors in the list
static int num_sensors = 0;

// Define the maximum number of sensors in the list
#define MAX_SENSORS 10000

// Define the minimum and maximum temperature values
#define MIN_TEMPERATURE -273.15f
#define MAX_TEMPERATURE 1000.0f

// Define the status of each sensor
enum status { ACTIVE, INACTIVE };

// Function to initialize a new sensor structure
void init_sensor(sensor_t *sensor) {
    // Generate a random identifier for the sensor
    int id = rand() % 1000;
    while (id < 0 || id >= MAX_SENSORS) {
        id = rand() % 1000;
    }
    sensor->identifier = id;

    // Generate a random temperature reading for the sensor
    float temp = MIN_TEMPERATURE + (rand() % 1000) / 100.0f;
    while (temp < MIN_TEMPERATURE || temp > MAX_TEMPERATURE) {
        temp = MIN_TEMPERATURE + (rand() % 1000) / 100.0f;
    }
    sensor->temperature_reading = temp;

    // Set the last reading time to the current time
    sensor->last_reading_time = time(NULL);

    // Set the status of the sensor to active
    sensor->status = ACTIVE;
}

// Function to add a new sensor to the list
void add_sensor(sensor_t *sensor) {
    // Check if the list is full
    if (num_sensors >= MAX_SENSORS) {
        return;
    }

    // Allocate memory for the new sensor
    sensors = realloc(sensors, sizeof(sensor_t) * (num_sensors + 1));
    if (!sensors) {
        printf("Error: Failed to allocate memory for new sensor\n");
        return;
    }

    // Initialize the new sensor structure
    init_sensor(&sensors[num_sensors]);

    // Increment the number of sensors in the list
    num_sensors++;
}

// Function to remove a sensor from the list
void remove_sensor(int id) {
    // Find the index of the sensor with the specified identifier
    int i;
    for (i = 0; i < num_sensors; i++) {
        if (sensors[i].identifier == id) {
            break;
        }
    }

    // Check if the sensor was found
    if (i >= num_sensors) {
        return;
    }

    // Remove the sensor from the list
    sensors = realloc(sensors, sizeof(sensor_t) * (num_sensors - 1));
    if (!sensors) {
        printf("Error: Failed to remove sensor\n");
        return;
    }

    // Shift the remaining sensors down one index
    for (int j = i; j < num_sensors - 1; j++) {
        sensors[j] = sensors[j + 1];
    }

    // Decrement the number of sensors in the list
    num_sensors--;
}

// Function to update the status of a sensor
void update_status(int id, enum status new_status) {
    // Find the index of the sensor with the specified identifier
    int i;
    for (i = 0; i < num_sensors; i++) {
        if (sensors[i].identifier == id) {
            break;
        }
    }

    // Check if the sensor was found
    if (i >= num_sensors) {
        return;
    }

    // Update the status of the sensor
    sensors[i].status = new_status;
}

// Function to retrieve a list of all sensors
sensor_t *get_all_sensors() {
    // Allocate memory for the list of sensors
    sensor_t *list = malloc(sizeof(sensor_t) * num_sensors);
    if (!list) {
        printf("Error: Failed to allocate memory for sensor list\n");
        return NULL;
    }

    // Copy the list of sensors from the static array
    memcpy(list, sensors, sizeof(sensor_t) * num_sensors);

    // Return the list of sensors
    return list;
}

// Function to retrieve a specific sensor by identifier
sensor_t *get_sensor(int id) {
    // Find the index of the sensor with the specified identifier
    int i;
    for (i = 0; i < num_sensors; i++) {
        if (sensors[i].identifier == id) {
            break;
        }
    }

    // Check if the sensor was found
    if (i >= num_sensors) {
        return NULL;
    }

    // Return a pointer to the sensor structure
    return &sensors[i];
}

// Function to update the temperature reading of a sensor
void update_temperature(int id, float new_temp) {
    // Find the index of the sensor with the specified identifier
    int i;
    for (i = 0; i < num_sensors; i++) {
        if (sensors[i].identifier == id) {
            break;
        }
    }

    // Check if the sensor was found
    if (i >= num_sensors) {
        return;
    }

    // Update the temperature reading of the sensor
    sensors[i].temperature_reading = new_temp;
}

// Function to update the last reading time of a sensor
void update_last_reading_time(int id, time_t new_time) {
    // Find the index of the sensor with the specified identifier
    int i;
    for (i = 0; i < num_sensors; i++) {
        if (sensors[i].identifier == id) {
            break;
        }
    }

    // Check if the sensor was found
    if (i >= num_sensors) {
        return;
    }

    // Update the last reading time of the sensor
    sensors[i].last_reading_time = new_time;
