            fprintf(stderr, "Error: failed to allocate memory for file path %zu\n", i);
            exit(1);
        }
    }

    // Allocate memory for the array of file metadata
    *metadata = (struct FileMetadata **)malloc(num_files * sizeof(struct FileMetadata));
    if (*metadata == NULL) {
        fprintf(stderr, "Error: failed to allocate memory for file metadata\n");
        exit(1);
    }

    // Initialize the array of file metadata
    for (size_t i = 0; i < num_files; i++) {
        (*metadata)[i].size = 0;
        (*metadata)[i].modification_timestamp = 0;
        (*metadata)[i].attributes = NULL;
        (*metadata)[i].is_being_accessed = false;
    }
}

// Function to dynamically allocate memory for and initialize file attributes
void init_file_attributes(struct FileMetadata *metadata, size_t num_files) {
    // Allocate memory for the array of file attributes
    metadata->attributes = (struct FileAttributes **)malloc(num_files * sizeof(struct FileAttributes));
    if (metadata->attributes == NULL) {
        fprintf(stderr, "Error: failed to allocate memory for file attributes\n");
        exit(1);
    }

    // Initialize the array of file attributes
    for (size_t i = 0; i < num_files; i++) {
        metadata->attributes[i].access_mode = 0;
        metadata->attributes[i].ownership_group = 0;
        metadata->attributes[i].permissions = 0;
        metadata->attributes[i].checksum = 0;
        metadata->attributes[i].compression_status = false;
        metadata->attributes[i].attributes_last_updated = 0;
    }
}

// Function to dynamically allocate memory for and initialize directory entries
void init_directory_entries(struct DirectoryEntry *entries, size_t num_directories) {
    // Allocate memory for the array of directory entries
    entries = (struct DirectoryEntry **)malloc(num_directories * sizeof(struct DirectoryEntry));
    if (entries == NULL) {
        fprintf(stderr, "Error: failed to allocate memory for directory entries\n");
        exit(1);
    }

    // Initialize the array of directory entries
    for (size_t i = 0; i < num_directories; i++) {
        entries[i].refcount = 0;
        entries[i].child_entries = NULL;
        entries[i].is_locked = false;
    }
}

// Function to update file metadata and attributes for a given directory
void update_directory(char *path, struct FileMetadata **metadata, size_t num_files) {
    // Open the directory
    DIR *dir = opendir(path);
    if (dir == NULL) {
        fprintf(stderr, "Error: failed to open directory %s\n", path);
        exit(1);
    }

    // Read each entry in the directory and update the metadata and attributes accordingly
    struct dirent *entry;
    while ((entry = readdir(dir)) != NULL) {
        if (strcmp(entry->d_name, ".") == 0 || strcmp(entry->d_name, "..") == 0) {
            continue;
        }

        // Update the metadata and attributes for this file
        size_t i = 0;
        while (i < num_files && strcmp(metadata[i]->path, entry->d_name) != 0) {
            i++;
        }
        if (i == num_files) {
            fprintf(stderr, "Error: file %s not found in metadata\n", entry->d_name);
            exit(1);
        }
        metadata[i]->size = entry->d_type;
        metadata[i]->modification_timestamp = entry->d_mtime;
        metadata[i]->attributes->access_mode = entry->d_mode;
        metadata[i]->attributes->ownership_group = entry->d_gid;
        metadata[i]->attributes->permissions = entry->d_uid;
        metadata[i]->attributes->checksum = entry->d_checksum;
        metadata[i]->attributes->compression_status = entry->d_compressed;
        metadata[i]->attributes->attributes_last_updated = time(NULL);
    }

    // Close the directory
    closedir(dir);
}

// Function to update file metadata and attributes for a given set of files
void update_files(char **paths, size_t num_files) {
    // Allocate memory for the array of file metadata
    struct FileMetadata *metadata = (struct FileMetadata *)malloc(num_files * sizeof(struct FileMetadata));
    if (metadata == NULL) {
        fprintf(stderr, "Error: failed to allocate memory for file metadata\n");
        exit(1);
    }

    // Initialize the array of file metadata
    for (size_t i = 0; i < num_files; i++) {
        metadata[i].path = paths[i];
        metadata[i].size = 0;
        metadata[i].modification_timestamp = 0;
        metadata[i].attributes = NULL;
        metadata[i].is_being_accessed = false;
    }

    // Update the file metadata and attributes for each directory in the array of paths
    size_t num_directories = num_files / 100;
    if (num_directories == 0) {
        num_directories = 1;
    }
    struct DirectoryEntry *entries = (struct DirectoryEntry *)malloc(num_directories * sizeof(struct DirectoryEntry));
    if (entries == NULL) {
        fprintf(stderr, "Error: failed to allocate memory for directory entries\n");
        exit(1);
    }
    for (size_t i = 0; i < num_directories; i++) {
        init_directory_entries(&entries[i], num_files - i * 100);
    }
    for (size_t i = 0; i < num_directories; i++) {
        update_directory(paths[i], &metadata[i * 100], num_files - i * 100);
    }

    // Free the memory allocated for the array of directory entries
    free(entries);
}
