    void *access_records_func(void *arg) {
        int thread_id = (int)(long)arg;
        for (int i = 0; i < num_records; i++) {
            pthread_mutex_lock(&mutex);
            // Access the record array and perform some operation on it
            printf("Thread %d: Record %d\n", thread_id, record_arr[i].key);
            pthread_mutex_unlock(&mutex);
        }
    }

    // Create each thread and start executing the access_records_func function
    for (int i = 0; i < num_threads; i++) {
        if (pthread_create(&threads[i], NULL, access_records_func, (void *)(long)i)) {
            printf("Error: Failed to create thread %d\n", i);
            free(record_arr);
            return;
        }
    }

    // Wait for each thread to complete and then free the memory
    for (int i = 0; i < num_threads; i++) {
        if (pthread_join(threads[i], NULL)) {
            printf("Error: Failed to join thread %d\n", i);
            free(record_arr);
            return;
        }
    }

    // Free the memory for the record array and the mutex
    free(record_arr);
    pthread_mutex_destroy(&mutex);
}
