// Custom memory allocator for region-based memory management
void* custom_malloc(size_t size) {
    void* ptr = NULL;
    int fd = -1;
    char* file_name = "custom_allocator";

    // Open a file for mmap
    if ((fd = open(file_name, O_RDWR | O_CREAT, 0644)) < 0) {
        perror("open");
        return NULL;
    }

    // Map the file to memory
    ptr = mmap(NULL, size, PROT_READ | PROT_WRITE, MAP_SHARED, fd, 0);
    if (ptr == MAP_FAILED) {
        perror("mmap");
        close(fd);
        return NULL;
    }

    // Close the file descriptor
    close(fd);

    return ptr;
}

// Custom memory deallocator for region-based memory management
void custom_free(void* ptr) {
    munmap(ptr, size);
}

// Structure to store records in the collection
typedef struct record {
    long offset;
    int key;
    void* metadata; // Custom structure for additional metadata
} record_t;

// Structure to store the collection and associated metadata
typedef struct collection {
    size_t capacity;
    size_t count;
    record_t* records;
    void* metadata; // Custom structure for additional metadata
} collection_t;

// Function to initialize the collection
void init_collection(collection_t* coll, size_t capacity) {
    coll->capacity = capacity;
    coll->count = 0;
    coll->records = (record_t*)custom_malloc(sizeof(record_t) * capacity);
    coll->metadata = NULL; // Initialize custom metadata structure
}

// Function to insert a new record into the collection
void insert_record(collection_t* coll, long offset, int key, void* metadata) {
    if (coll->count == coll->capacity) {
        // Reallocate memory for records and metadata
        size_t new_capacity = coll->capacity * 2;
        record_t* new_records = (record_t*)custom_malloc(sizeof(record_t) * new_capacity);
        void* new_metadata = custom_malloc(new_capacity * sizeof(void*));

        // Copy existing records and metadata to the new memory locations
        memcpy(new_records, coll->records, coll->count * sizeof(record_t));
        memcpy(new_metadata, coll->metadata, coll->count * sizeof(void*));

        // Free old memory locations
        custom_free(coll->records);
        custom_free(coll->metadata);

        // Update collection with new memory locations
        coll->records = new_records;
        coll->metadata = new_metadata;
        coll->capacity = new_capacity;
    }

    // Insert the new record at the end of the collection
    coll->records[coll->count].offset = offset;
    coll->records[coll->count].key = key;
    coll->records[coll->count].metadata = metadata;
    coll->count++;
}

// Function to delete a record from the collection
void delete_record(collection_t* coll, long offset) {
    // Find the index of the record to be deleted
    size_t i = 0;
    while (i < coll->count && coll->records[i].offset != offset) {
        i++;
    }

    if (i == coll->count) {
        return; // Record not found
    }

    // Shift all records after the deleted record to fill the gap
    for (size_t j = i + 1; j < coll->count; j++) {
        coll->records[j - 1] = coll->records[j];
    }

    // Decrement the count of records in the collection
    coll->count--;
}

// Function to retrieve a record from the collection
record_t* get_record(collection_t* coll, long offset) {
    // Find the index of the record with the given offset
    size_t i = 0;
    while (i < coll->count && coll->records[i].offset != offset) {
        i++;
    }

    if (i == coll->count) {
        return NULL; // Record not found
    }

    return &coll->records[i];
}

// Function to save the collection to a file or database
void save_collection(collection_t* coll, const char* filename) {
    FILE* fp = fopen(filename, "wb");
    if (fp == NULL) {
        perror("fopen");
        return;
    }

    // Write the number of records in the collection to the file
    size_t num_records = coll->count;
    fwrite(&num_records, sizeof(size_t), 1, fp);

    // Write each record to the file
    for (size_t i = 0; i < coll->count; i++) {
        record_t* rec = &coll->records[i];
        fwrite(&rec->offset, sizeof(long), 1, fp);
        fwrite(&rec->key, sizeof(int), 1, fp);
        fwrite(rec->metadata, sizeof(void*), 1, fp);
    }

    // Close the file
    fclose(fp);
}

