class DatabaseRandomValueGenerator {
private:
    float min;
    float max;
    int minInt;
    int maxInt;
    bool isInclusive;
    bool isExclusive;

public:
    DatabaseRandomValueGenerator(float min, float max, bool isInclusive = true, bool isExclusive = false) {
        this->min = min;
        this->max = max;
        this->isInclusive = isInclusive;
        this->isExclusive = isExclusive;
    }

    float generateRandomFloat() {
        if (this->isInclusive) {
            return min + static_cast<float>(rand()) / RAND_MAX * (max - min);
        } else {
            return min + static_cast<float>(rand()) / RAND_MAX * (max - min - 1);
        }
    }

    int generateRandomInt() {
        if (this->isInclusive) {
            return minInt + rand() % (maxInt - minInt + 1);
        } else {
            return minInt + rand() % (maxInt - minInt);
        }
    }

    void adjustRange(float newMin, float newMax, bool isInclusive = true, bool isExclusive = false) {
        this->min = newMin;
        this->max = newMax;
        this->isInclusive = isInclusive;
        this->isExclusive = isExclusive;
    }

    void resetRange() {
        this->min = 0.0f;
        this->max = 1.0f;
        this->isInclusive = true;
        this->isExclusive = false;
    }

