        fclose(fp);
        return ENOMEM;
    }
    *key_array = malloc(sizeof(int) * num_records);
    if (*key_array == NULL) {
        free(*offset_array);
        fclose(fp);
        return ENOMEM;
    }

    // Allocate memory for the record array
    *record_array = malloc(sizeof(record) * num_records);
    if (*record_array == NULL) {
        free(*offset_array);
        free(*key_array);
        fclose(fp);
        return ENOMEM;
    }

    // Read the data from the file and validate it
    for (long i = 0; i < num_records; i++) {
        if (fread(&((*offset_array)[i]), sizeof(long), 1, fp) != 1 ||
            fread(&((*key_array)[i]), sizeof(int), 1, fp) != 1) {
            fclose(fp);
            free(*offset_array);
            free(*key_array);
            free(*record_array);
            return EIO;
        }
    }

    // Set the value of each record's int field to a random value within a given range
    for (long i = 0; i < num_records; i++) {
        (*record_array)[i].key = rand() % 10 + 1;
