#include <stdlib.h>
#include <stdio.h>
#include <string.h>
#include <time.h>
#include <pthread.h>

// Define the data structures
typedef struct {
    int value;
} record;

typedef struct node {
    int value;
    struct node* prev;
    struct node* next;
} node;

// Define the cache entry structure
typedef struct {
    record* record;
    int index;
} cache_entry;

// Define the function to initialize the data structures
void init_data_structures(int num_records, int num_nodes) {
    // Allocate memory for the arrays
    long* long_array = malloc(num_records * sizeof(long));
    int* int_array = malloc(num_records * sizeof(int));
    record** record_array = malloc(num_records * sizeof(record*));
    double* double_array = malloc(num_nodes * sizeof(double));
    node** node_array = malloc(num_nodes * sizeof(node*));

    // Initialize the arrays and linked list
    for (int i = 0; i < num_records; i++) {
        long_array[i] = rand() % 100;
        int_array[i] = rand() % 100;
        record* new_record = malloc(sizeof(record));
        new_record->value = rand() % 100;
        record_array[i] = new_record;
    }

    for (int i = 0; i < num_nodes; i++) {
        double_array[i] = rand() % 100 / 10.0;
        node* new_node = malloc(sizeof(node));
        new_node->value = rand() % 100;
        new_node->prev = NULL;
        new_node->next = NULL;
        node_array[i] = new_node;
    }

    // Initialize the linked list
    node* head = NULL;
    node* tail = NULL;
    for (int i = 0; i < num_nodes; i++) {
        if (head == NULL) {
            head = node_array[i];
            tail = node_array[i];
        } else {
            tail->next = node_array[i];
            node_array[i]->prev = tail;
            tail = node_array[i];
        }
    }

    // Initialize the cache
    int cache_size = 100;
    cache_entry* cache = malloc(cache_size * sizeof(cache_entry));
    for (int i = 0; i < cache_size; i++) {
        cache[i].record = NULL;
        cache[i].index = -1;
    }

    // Print the linked list
    printf("Linked List: ");
    node* current = head;
    while (current != NULL) {
        printf("%d ", current->value);
        current = current->next;
    }
    printf("\n");
}

// Define the function to free the memory allocated by init_data_structures
void free_memory(long* long_array, int* int_array, record** record_array, double* double_array, node** node_array, cache_entry* cache) {
    // Free the arrays and linked list
    free(long_array);
    free(int_array);
    for (int i = 0; i < num_records; i++) {
        free(record_array[i]);
    }
    free(record_array);
    free(double_array);
    for (int i = 0; i < num_nodes; i++) {
        free(node_array[i]);
    }
    free(node_array);

    // Free the cache
    free(cache);
}

// Define the function to populate the cache
void populate_cache(record** record_array, int num_records) {
    for (int i = 0; i < num_records; i++) {
        cache_entry* new_entry = malloc(sizeof(cache_entry));
        new_entry->record = record_array[i];
        new_entry->index = i;
        cache[i] = new_entry;
    }
}

// Define the function to retrieve a record from the cache
record* get_record_from_cache(int index) {
    if (cache[index].record == NULL) {
        return NULL;
    } else {
        return cache[index].record;
    }
}

// Define the function to add a record to the cache
void add_record_to_cache(record* new_record, int index) {
    cache_entry* new_entry = malloc(sizeof(cache_entry));
    new_entry->record = new_record;
    new_entry->index = index;
    cache[index] = new_entry;
}

// Define the function to remove a record from the cache
void remove_record_from_cache(int index) {
    free(cache[index].record);
    cache[index].record = NULL;
}

// Define the function to update the cache
void update_cache(record** record_array, int num_records) {
    for (int i = 0; i < num_records; i++) {
        if (cache[i].record == NULL || cache[i].index != i) {
            add_record_to_cache(record_array[i], i);
        } else {
            remove_record_from_cache(i);
        }
    }
}

// Define the function to traverse the linked list and print each node's integer value
void traverse_linked_list(node* head) {
    node* current = head;
    while (current != NULL) {
        printf("%d ", current->value);
        current = current->next;
    }
}

// Define the function to handle memory allocation errors gracefully
