void init_arrays(int num_records, int record_size) {
    // Allocate memory for the arrays and linked list
    LargeOffsetArray* large_offset_array = (LargeOffsetArray*)malloc(num_records * sizeof(LargeOffsetArray));
    KeyArray* key_array = (KeyArray*)malloc(num_records * sizeof(KeyArray));
    Record* record_array = (Record*)malloc(num_records * sizeof(Record));
    DoublePrecisionArray* double_precision_array = (DoublePrecisionArray*)malloc(num_records * sizeof(DoublePrecisionArray));
    Node* head = NULL;

    // Initialize the arrays and linked list
    for (int i = 0; i < num_records; i++) {
        large_offset_array[i].large_offset = rand() % 1000000;
