    free(key_array);
    free(record_array);
    free(double_precision_array);
    free(head);

    // Log the function's execution details and any errors encountered
    log_message(LOGGING_LEVEL_DEBUG, "Freed arrays and linked list");
}

void cache_record(Record* record) {
    // Check if the cache is full
    if (cache_size >= CACHE_LIMIT) {
        // Evict the least recently used record from the cache
        Record** evicted_record = &cache[0];
        for (int i = 1; i < CACHE_SIZE; i++) {
            if (cache[i]->last_accessed < (*evicted_record)->last_accessed) {
                evicted_record = &cache[i];
            }
        }
        free(*evicted_record);
        *evicted_record = NULL;
    }

    // Add the record to the cache
    Record** cached_record = &cache[cache_size];
    *cached_record = malloc(sizeof(Record));
    (*cached_record)->value = record->value;
    (*cached_record)->last_accessed = time(NULL);
    cache_size++;
}

void traverse_linked_list() {
    // Traverse the linked list and print each node's integer value
    Node* current = head;
    while (current != NULL) {
        printf("%d\n", current->value);
        current = current->next;
    }
}

void log_message(int logging_level, const char* message, ...) {
