        long_array[i] = rand() % 1000000000;
    }
    for (int i = 0; i < uint64_array_size; i++) {
        uint64_array[i] = rand() % 1000000000;
    }
    for (int i = 0; i < transaction_struct_size; i++) {
        transaction_structs[i].id = rand() % 1000000000;
        transaction_structs[i].status = rand() % 1000000000;
    }
    for (int i = 0; i < double_array_size; i++) {
        double_array[i] = rand() % 1000000000;
    }
    hash_table->capacity = initial_capacity;
    hash_table->size = 0;
    hash_table->rehash_policy = rehash_policy;
    hash_table->table = malloc(sizeof(transaction_t *) * hash_table->capacity);

    // Initialize the cache
    cache_t *cache = malloc(sizeof(cache_t));
    cache->size = 0;
    cache->fees = malloc(sizeof(double) * double_array_size);

    // Log the initialization details
    log(LOGGING_LEVEL_INFO, "Initialized arrays and hash table with sizes: long=%zu, uint64=%zu, transaction=%zu, double=%zu", long_array_size, uint64_array_size, transaction_struct_size, double_array_size);
    log(LOGGING_LEVEL_INFO, "Initialized cache with size: %zu", double_array_size);
}

// Define the function to add a transaction to the hash table and cache
void add_transaction(uint64_t id, int status, double fee) {
    // Check if the transaction already exists in the hash table
    bool exists = false;
    for (int i = 0; i < hash_table->size; i++) {
        if (hash_table->table[i]->id == id) {
            exists = true;
            break;
        }
    }

    // If the transaction does not exist, add it to the hash table and cache
    if (!exists) {
        // Check if the hash table needs to be rehashed
        if (hash_table->size == hash_table->capacity) {
            // Rehash the hash table with a new capacity
            size_t new_capacity = hash_table->capacity * hash_table->rehash_policy;
            transaction_t **new_table = malloc(sizeof(transaction_t *) * new_capacity);
            for (int i = 0; i < hash_table->size; i++) {
                new_table[i] = hash_table->table[i];
            }
            free(hash_table->table);
            hash_table->table = new_table;
            hash_table->capacity = new_capacity;
        }

        // Add the transaction to the hash table and cache
        transaction_t *transaction = malloc(sizeof(transaction_t));
        transaction->id = id;
        transaction->status = status;
        hash_table->table[hash_table->size] = transaction;
        hash_table->size++;
        cache->fees[cache->size] = fee;
        cache->size++;
    } else {
        // Update the existing transaction in the hash table and cache
        for (int i = 0; i < hash_table->size; i++) {
            if (hash_table->table[i]->id == id) {
                hash_table->table[i]->status = status;
                break;
            }
        }
        cache->fees[cache->size] = fee;
        cache->size++;
    }
}

// Define the function to retrieve a transaction from the hash table and cache
void get_transaction(uint64_t id, int *status, double *fee) {
    // Check if the transaction exists in the hash table
    bool exists = false;
    for (int i = 0; i < hash_table->size; i++) {
        if (hash_table->table[i]->id == id) {
            exists = true;
            break;
        }
    }

    // If the transaction exists, retrieve its status and fee from the cache
    if (exists) {
        for (int i = 0; i < hash_table->size; i++) {
            if (hash_table->table[i]->id == id) {
                *status = hash_table->table[i]->status;
                break;
            }
        }
        for (int i = 0; i < cache->size; i++) {
            if (cache->fees[i] == fee) {
                *fee = cache->fees[i];
                break;
            }
        }
    } else {
        // Log an error message if the transaction does not exist in the hash table or cache
        log(LOGGING_LEVEL_ERROR, "Transaction with ID %" PRIu64 " does not exist", id);
    }
}

// Define the function to traverse the hash table and print each transaction ID along with its status
