record* initialize_records(int num_records, char **names) {
    if (num_records <= 0) {
        fprintf(stderr, "Invalid number of records: %d\n", num_records);
        return NULL;
    }

    // Allocate memory for the offset array
    long *offsets = malloc(sizeof(long) * num_records);
    if (offsets == NULL) {
        fprintf(stderr, "Failed to allocate memory for offsets\n");
        return NULL;
    }

    // Allocate memory for the key array
    int *keys = malloc(sizeof(int) * num_records);
    if (keys == NULL) {
        fprintf(stderr, "Failed to allocate memory for keys\n");
        free(offsets);
        return NULL;
    }

    // Allocate memory for the record structures
    record *records = malloc(sizeof(record) * num_records);
    if (records == NULL) {
        fprintf(stderr, "Failed to allocate memory for records\n");
        free(offsets);
        free(keys);
        return NULL;
    }

    // Initialize the offset array with random values within a specified range
    srand(time(NULL));
    for (int i = 0; i < num_records; i++) {
        offsets[i] = rand() % 100 + 1;
    }

    // Initialize the key array with random values within a specified range
    srand(time(NULL));
    for (int i = 0; i < num_records; i++) {
        keys[i] = rand() % 100 + 1;
    }

    // Initialize the record structures with unique substrings of the names list
    int name_index = 0;
    for (int i = 0; i < num_records; i++) {
        records[i].key = keys[i];
        records[i].name = malloc(sizeof(char) * (strlen(names[name_index]) + 1));
        strcpy(records[i].name, names[name_index]);
        name_index++;
    }

    // Free the memory allocated for the names list
    free(names);

    return records;
}
