// Define the data structures for file metadata, attributes, and network status
struct FileMetadata {
    size_t size;
    time_t modification_timestamp;
    struct FileAttributes *attributes;
    int is_accessed;
    int refcount;
};

struct FileAttributes {
    mode_t access_mode;
    gid_t ownership_group;
    uid_t permissions;
    uint32_t checksum;
    bool compression_status;
    time_t attributes_timestamp;
};

struct DirectoryEntry {
    int refcount;
    struct FileMetadata *metadata;
    struct DirectoryEntry *child_entries;
    bool is_locked;
    struct NetworkStatus *network_status;
};

struct NetworkStatus {
    time_t connection_uptime;
    double latency;
    float packet_loss;
    uint64_t throughput;
};

// Define the function to dynamically allocate memory for and initialize the data structures
void init_file_metadata(const char *path, struct FileMetadata **metadata) {
    // Allocate memory for the file metadata structure
    *metadata = malloc(sizeof(struct FileMetadata));
    if (*metadata == NULL) {
        fprintf(stderr, "Failed to allocate memory for file metadata: %s\n", strerror(errno));
        return;
    }

    // Initialize the file size and modification timestamp
    struct stat sb;
    if (stat(path, &sb) == -1) {
        fprintf(stderr, "Failed to get file information: %s\n", strerror(errno));
        free(*metadata);
        return;
    }
    (*metadata)->size = sb.st_size;
    (*metadata)->modification_timestamp = sb.st_mtime;

    // Allocate memory for the file attributes structure and initialize it
    (*metadata)->attributes = malloc(sizeof(struct FileAttributes));
    if ((*metadata)->attributes == NULL) {
        fprintf(stderr, "Failed to allocate memory for file attributes: %s\n", strerror(errno));
        free(*metadata);
        return;
    }
    (*metadata)->attributes->access_mode = sb.st_mode;
    (*metadata)->attributes->ownership_group = sb.st_gid;
    (*metadata)->attributes->permissions = sb.st_uid;
    (*metadata)->attributes->checksum = 0;
    (*metadata)->attributes->compression_status = false;
    (*metadata)->attributes->attributes_timestamp = time(NULL);

    // Initialize the reference count for the metadata structure
    (*metadata)->refcount = 1;

    // Allocate memory for the directory entry structure and initialize it
    struct DirectoryEntry *entry = malloc(sizeof(struct DirectoryEntry));
    if (entry == NULL) {
        fprintf(stderr, "Failed to allocate memory for directory entry: %s\n", strerror(errno));
        free(*metadata);
        return;
    }
    entry->refcount = 1;
    entry->metadata = *metadata;
    entry->child_entries = NULL;
    entry->is_locked = false;
    entry->network_status = NULL;

    // Allocate memory for the network status structure and initialize it
    struct NetworkStatus *status = malloc(sizeof(struct NetworkStatus));
    if (status == NULL) {
        fprintf(stderr, "Failed to allocate memory for network status: %s\n", strerror(errno));
        free(*metadata);
        return;
    }
    status->connection_uptime = 0;
    status->latency = 0.0;
    status->packet_loss = 0.0;
    status->throughput = 0;

    // Set the network status for the directory entry
    entry->network_status = status;
}

// Define the function to dynamically allocate memory for and initialize the data structures in a directory
void init_directory(const char *path, struct DirectoryEntry **entry) {
    // Allocate memory for the directory entry structure
    *entry = malloc(sizeof(struct DirectoryEntry));
    if (*entry == NULL) {
        fprintf(stderr, "Failed to allocate memory for directory entry: %s\n", strerror(errno));
        return;
    }

    // Initialize the reference count for the directory entry structure
    (*entry)->refcount = 1;

    // Allocate memory for the file metadata structure and initialize it
    struct FileMetadata *metadata = malloc(sizeof(struct FileMetadata));
    if (metadata == NULL) {
        fprintf(stderr, "Failed to allocate memory for file metadata: %s\n", strerror(errno));
        free(*entry);
        return;
    }
    init_file_metadata(path, &metadata);
    (*entry)->metadata = metadata;

    // Allocate memory for the child entries list and initialize it
    (*entry)->child_entries = malloc(sizeof(struct DirectoryEntry) * 10);
    if ((*entry)->child_entries == NULL) {
        fprintf(stderr, "Failed to allocate memory for child entries: %s\n", strerror(errno));
        free(*entry);
        return;
    }
    (*entry)->child_entries[0] = NULL;

    // Set the is_locked flag to false
    (*entry)->is_locked = false;
}

// Define the function to dynamically allocate memory for and initialize the data structures in a network drive or external storage device
void init_network_drive(const char *path, struct DirectoryEntry **entry) {
    // Allocate memory for the directory entry structure
    *entry = malloc(sizeof(struct DirectoryEntry));
    if (*entry == NULL) {
        fprintf(stderr, "Failed to allocate memory for directory entry: %s\n", strerror(errno));
        return;
    }

    // Initialize the reference count for the directory entry structure
    (*entry)->refcount = 1;

    // Allocate memory for the file metadata structure and initialize it
    struct FileMetadata *metadata = malloc(sizeof(struct FileMetadata));
    if (metadata == NULL) {
        fprintf(stderr, "Failed to allocate memory for file metadata: %s\n", strerror(errno));
        free(*entry);
        return;
    }
    init_file_metadata(path, &metadata);
    (*entry)->metadata = metadata;

    // Allocate memory for the child entries list and initialize it
    (*entry)->child_entries = malloc(sizeof(struct DirectoryEntry) * 10);
    if ((*entry)->child_entries == NULL) {
        fprintf(stderr, "Failed to allocate memory for child entries: %s\n", strerror(errno));
        free(*entry);
        return;
    }
    (*entry)->child_entries[0] = NULL;

    // Set the is_locked flag to false
    (*entry)->is_locked = false;
}

// Define the function to dynamically allocate memory for and initialize the data structures in a file system
void init_file_system(const char *path, struct DirectoryEntry **root) {
    // Allocate memory for the root directory entry structure
    *root = malloc(sizeof(struct DirectoryEntry));
    if (*root == NULL) {
        fprintf(stderr, "Failed to allocate memory for root directory entry: %s\n", strerror(errno));
        return;
    }

