// Define a structure to store network traffic metrics
typedef struct NetworkTrafficMetrics {
    int interface_index;
    unsigned long long bytes_sent;
    unsigned long long bytes_received;
    double latency;
    double packet_loss;
    double error_rate;
} NetworkTrafficMetrics;

// Define a linked list to store the network traffic metrics
typedef struct NetworkTrafficMetricsList {
    NetworkTrafficMetrics *metrics;
    struct NetworkTrafficMetricsList *next;
} NetworkTrafficMetricsList;

// Define a function to initialize and manage the dynamic collection of network traffic metrics
void init_network_traffic_metrics(int num_interfaces) {
    // Initialize the linked list of network traffic metrics
    NetworkTrafficMetricsList *head = NULL;
    for (int i = 0; i < num_interfaces; i++) {
        NetworkTrafficMetrics *metrics = malloc(sizeof(NetworkTrafficMetrics));
        if (!metrics) {
            printf("Error: Failed to allocate memory for network traffic metrics\n");
            exit(1);
        }
        metrics->interface_index = i;
        metrics->bytes_sent = 0;
        metrics->bytes_received = 0;
        metrics->latency = 0.0;
        metrics->packet_loss = 0.0;
        metrics->error_rate = 0.0;
        head = add_metrics(head, metrics);
    }
}

// Define a function to add new network traffic metrics to the linked list
NetworkTrafficMetricsList *add_metrics(NetworkTrafficMetricsList *head, NetworkTrafficMetrics *metrics) {
    // Create a new node for the network traffic metrics
    NetworkTrafficMetricsList *new_node = malloc(sizeof(NetworkTrafficMetricsList));
    if (!new_node) {
        printf("Error: Failed to allocate memory for new network traffic metrics\n");
        exit(1);
    }
    new_node->metrics = metrics;
    new_node->next = head;
    return new_node;
}

// Define a function to update existing network traffic metrics in the linked list
void update_metrics(NetworkTrafficMetricsList *head, int interface_index, unsigned long long bytes_sent, unsigned long long bytes_received) {
    // Find the node for the specified interface index
    NetworkTrafficMetricsList *node = head;
    while (node && node->metrics->interface_index != interface_index) {
        node = node->next;
    }
    if (!node) {
        printf("Error: Failed to find network traffic metrics for interface index %d\n", interface_index);
        exit(1);
    }
    // Update the bytes sent and received counters
    node->metrics->bytes_sent += bytes_sent;
    node->metrics->bytes_received += bytes_received;
}

// Define a function to retrieve aggregated statistics for all interfaces in the linked list
void get_aggregate_stats(NetworkTrafficMetricsList *head, double *total_bytes_sent, double *total_bytes_received) {
    // Initialize the total bytes sent and received counters to 0
    *total_bytes_sent = 0.0;
    *total_bytes_received = 0.0;
    // Iterate over all nodes in the linked list and accumulate the total bytes sent and received
    NetworkTrafficMetricsList *node = head;
    while (node) {
        *total_bytes_sent += node->metrics->bytes_sent;
        *total_bytes_received += node->metrics->bytes_received;
        node = node->next;
    }
}

// Define a function to limit the maximum amount of bandwidth that can be monitored simultaneously
void limit_bandwidth(NetworkTrafficMetricsList *head, int max_bandwidth) {
    // Calculate the total bytes sent and received for all interfaces
    double total_bytes_sent = 0.0;
    double total_bytes_received = 0.0;
    get_aggregate_stats(head, &total_bytes_sent, &total_bytes_received);
    // If the total bytes sent or received exceeds the maximum bandwidth, prioritize critical interfaces and degrade performance by temporarily suspending monitoring of less critical interfaces
    if (total_bytes_sent > max_bandwidth || total_bytes_received > max_bandwidth) {
        // Sort the linked list in descending order based on bytes sent or received, whichever is greater
        NetworkTrafficMetricsList *node = head;
        while (node->next) {
            if (node->metrics->bytes_sent > node->next->metrics->bytes_sent || node->metrics->bytes_received > node->next->metrics->bytes_received) {
                NetworkTrafficMetricsList *temp = node->next;
                node->next = temp->next;
                temp->next = node;
            } else {
                node = node->next;
            }
        }
        // Iterate over the linked list and suspend monitoring of less critical interfaces until the total bytes sent or received falls below the maximum bandwidth
        while (total_bytes_sent > max_bandwidth || total_bytes_received > max_bandwidth) {
            node = head;
            while (node->next) {
                if (node->metrics->bytes_sent < max_bandwidth / 2 && node->metrics->bytes_received < max_bandwidth / 2) {
                    // Suspend monitoring of this interface for a short period of time to allow other interfaces to take priority
                    sleep(1);
                } else {
                    node = node->next;
                }
            }
        }
    }
}

