// Function to allocate memory for the memory pool
struct MemoryPool* allocateMemory(int num_offsets, int num_keys, int num_records, int num_timestamps) {
    // Validate input parameters
    if (num_offsets < 0 || num_keys < 0 || num_records < 0 || num_timestamps < 0) {
        fprintf(stderr, "Invalid input parameters\n");
        return NULL;
    }

    // Allocate memory for the memory pool
    struct MemoryPool* mempool = malloc(sizeof(struct MemoryPool));
    if (mempool == NULL) {
        fprintf(stderr, "Failed to allocate memory for the memory pool\n");
        return NULL;
    }

    // Allocate memory for the arrays in the memory pool
    mempool->offsets = malloc(num_offsets * sizeof(long));
    mempool->keys = malloc(num_keys * sizeof(int));
    mempool->records = malloc(num_records * sizeof(record_t));
    mempool->timestamps = malloc(num_timestamps * sizeof(timestamp_t));
    mempool->custom_records = malloc(sizeof(custom_record_t) * num_records);

    // Initialize the arrays in the memory pool
    for (int i = 0; i < num_offsets; i++) {
        mempool->offsets[i] = 0;
    }
    for (int i = 0; i < num_keys; i++) {
        mempool->keys[i] = 0;
    }
    for (int i = 0; i < num_records; i++) {
        mempool->records[i].value = 0;
    }
    for (int i = 0; i < num_timestamps; i++) {
        mempool->timestamps[i].timestamp = 0;
    }

    // Initialize the custom records with random values within a specified range
    srand(time(NULL));
    for (int i = 0; i < num_records; i++) {
        int min_value = 1;
        int max_value = 100;
        mempool->custom_records[i].value = rand() % (max_value - min_value + 1) + min_value;
    }

    // Return the memory pool
    return mempool;
}

// Function to free memory for the memory pool
void freeMemory(struct MemoryPool* mempool) {
    if (mempool == NULL) {
        fprintf(stderr, "Invalid input parameters\n");
        return;
    }

    // Free the arrays in the memory pool
    free(mempool->offsets);
    free(mempool->keys);
    free(mempool->records);
    free(mempool->timestamps);
    free(mempool->custom_records);

    // Free the memory pool itself
    free(mempool);
}

// Function to validate that all allocated memory is freed upon normal or error exit
void checkMemoryLeaks() {
    struct MemoryPool* mempool = malloc(sizeof(struct MemoryPool));
    if (mempool == NULL) {
        fprintf(stderr, "Failed to allocate memory for the memory pool\n");
        return;
    }

    // Check that all allocated memory is freed upon normal or error exit
    freeMemory(mempool);
}
