void modifyKickstartConfig(const std::string& configFile, const std::map<std::string, std::string>& placeholders) {
    // Open the Kickstart configuration file for reading and writing
    std::ifstream infile(configFile);
    std::ofstream outfile(configFile, std::ios::app);

    if (!infile.is_open() || !outfile.is_open()) {
        throw std::runtime_error("Failed to open Kickstart configuration file");
    }

    // Read the entire file into a string
    std::string content;
    infile >> content;

    // Replace placeholders with actual values
    for (const auto& placeholder : placeholders) {
        const std::string& key = placeholder.first;
        const std::string& value = placeholder.second;
        size_t pos = 0;
        while ((pos = content.find(key, pos)) != std::string::npos) {
            content.replace(pos, key.length(), value);
            pos += value.length();
        }
    }

    // Add a new line with an encrypted password
    const std::string& password = placeholders.at("password");
    outfile << "encrypted_password=" << encrypt(password) << "\n";

    // Write the modified file back to disk
    outfile << content;
}

