#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pthread.h>
#include <errno.h>

// Define the maximum number of records that can be processed
#define MAX_RECORDS 10000

// Define the file type and extension for the output files
#define FILE_TYPE "txt"
#define FILE_EXTENSION ".txt"

// Define the error log structure
typedef struct {
    time_t timestamp;
    bool condition_met;
    char message[256];
} ErrorLogEntry;

// Define the record structure
typedef struct {
    int value;
    enum State { ACTIVE, INACTIVE } state;
} Record;

// Define the function to process a single file
void process_file(const char* filename) {
    // Allocate memory for the arrays of offsets, keys, and records
    long* offsets = malloc(sizeof(long) * MAX_RECORDS);
    int* keys = malloc(sizeof(int) * MAX_RECORDS);
    Record* records = malloc(sizeof(Record) * MAX_RECORDS);

    // Initialize the arrays with random values and states
    for (int i = 0; i < MAX_RECORDS; i++) {
        offsets[i] = rand() % 100;
        keys[i] = rand() % 100;
        records[i].value = rand() % 100;
        records[i].state = ACTIVE;
    }

    // Loop through the records and set their values based on a separate condition
    for (int i = 0; i < MAX_RECORDS; i++) {
        if (records[i].value > 50) {
            records[i].state = INACTIVE;
        }
    }

    // Allocate memory for the error log structure
    ErrorLogEntry* error_log = malloc(sizeof(ErrorLogEntry) * 10);

    // Loop through the records and log messages to the error log if necessary
    for (int i = 0; i < MAX_RECORDS; i++) {
        if (records[i].state == INACTIVE) {
            snprintf(error_log[i].message, sizeof(error_log[i].message), "Record %d is inactive", i);
            error_log[i].timestamp = time(NULL);
            error_log[i].condition_met = true;
        }
    }

    // Deallocate memory for the arrays and error log structure
    free(offsets);
    free(keys);
    free(records);
    free(error_log);
}

// Define the function to handle multiple file operations in parallel using threads
void process_files(const char** filenames, int num_filenames) {
    // Create a thread pool with the number of threads equal to the number of files
    pthread_t* threads = malloc(sizeof(pthread_t) * num_filenames);

    // Loop through each file and create a new thread for it
    for (int i = 0; i < num_filenames; i++) {
        pthread_create(&threads[i], NULL, process_file, filenames[i]);
    }

    // Wait for all threads to complete before returning
    for (int i = 0; i < num_filenames; i++) {
        pthread_join(threads[i], NULL);
    }

    // Deallocate memory for the thread pool
    free(threads);
}
