// Define a structure to store the statistics of the input data
typedef struct {
    double average;
    double largest;
} Statistics;

// Define a function to read floating-point numbers from standard input and store them in an array
void read_numbers(double **array, int *size) {
    // Initialize the array with an initial capacity of 1,000 elements
    *array = (double *)malloc(sizeof(double) * 1000);
    if (*array == NULL) {
        fprintf(stderr, "Error: unable to allocate memory for input array\n");
        exit(EXIT_FAILURE);
    }
    *size = 0;

    // Read floating-point numbers from standard input until the maximum number of elements is reached or an error occurs
    while (*size < 50000) {
        double num;
        if (scanf("%lf", &num) != 1) {
            fprintf(stderr, "Error: invalid input\n");
            break;
        }

        // Check if the array needs to be resized
        if (*size == *array_capacity) {
            double *new_array = (double *)realloc(*array, sizeof(double) * 2 * *array_capacity);
            if (new_array == NULL) {
                fprintf(stderr, "Error: unable to resize input array\n");
                exit(EXIT_FAILURE);
            }
            *array = new_array;
            *array_capacity *= 2;
        }

        // Store the number in the array
        (*array)[*size] = num;
        (*size)++;
    }
}

// Define a function to find and print the average and largest number in an array of floating-point numbers
void find_largest(double *array, int size) {
    // Calculate the average of the input data
    double sum = 0;
    for (int i = 0; i < size; i++) {
        sum += array[i];
    }
    double average = sum / size;

    // Find the largest number in the input data
    double largest = -INFINITY;
    for (int i = 0; i < size; i++) {
        if (array[i] > largest) {
            largest = array[i];
        }
    }

    // Print the average and largest number
    printf("Average: %f\n", average);
    printf("Largest: %f\n", largest);
}

int main() {
    double *array;
    int size = 0, array_capacity = 1000;

    // Read floating-point numbers from standard input and store them in an array
    read_numbers(&array, &size);

    // Find and print the average and largest number in the array
    find_largest(array, size);

    // Free the memory allocated for the input array
    free(array);

    return 0;
}
