#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <ctype.h>

// Function to validate input filename and return a pointer to the modified filename string
char* modify_filename(const char* filename) {
    // Check if input file is valid
    if (strlen(filename) == 0 || strchr(filename, '.') == NULL) {
        printf("Invalid input filename\n");
        return NULL;
    }

    // Calculate number of digits in the filename and append this count to the new extension
    int num_digits = 0;
    for (int i = 0; i < strlen(filename); i++) {
        if (isdigit(filename[i])) {
            num_digits++;
        }
    }
    char* new_extension = malloc(sizeof(char) * (num_digits + 1));
    sprintf(new_extension, "%d", num_digits);

    // Check for presence of specific characters in the filename and append corresponding letters to the extension
    char* new_filename = malloc(sizeof(char) * (strlen(filename) + strlen(new_extension) + 1));
    int i = 0;
    while (i < strlen(filename)) {
        if (isupper(filename[i])) {
            strcat(new_filename, "A");
        } else if (islower(filename[i])) {
            strcat(new_filename, "a");
        } else if (isdigit(filename[i])) {
            strcat(new_filename, "0");
        } else if (!isalnum(filename[i]) && filename[i] != '.') {
            strcat(new_filename, "S");
        }
        i++;
    }

    // Determine type of file based on its extension and apply additional logic
    char* extension = strrchr(filename, '.');
    if (strcmp(extension, ".txt") == 0) {
        strcat(new_filename, "TXT-");
    } else if (strcmp(extension, ".jpg") == 0 || strcmp(extension, ".jpeg") == 0 || strcmp(extension, ".png") == 0) {
        strcat(new_filename, "IMG");
    } else if (strcmp(extension, ".exe") == 0) {
        strcat(new_filename, "EXEC");
    }

    // Handle filenames up to 256 characters long and ensure new filename does not exceed 512 characters in total length
    if (strlen(new_filename) > 256 || strlen(new_filename) + strlen(extension) > 512) {
        printf("Invalid input filename\n");
        return NULL;
    }

    // Validate the filename to ensure it contains at least one alphanumeric character and at least one period ('.') before proceeding with modifications
    if (!isalnum(filename[0]) || strchr(filename, '.') == NULL) {
        printf("Invalid input filename\n");
        return NULL;
    }

    // Store the new filename in a dynamically allocated buffer and free this buffer manually by the caller after use
    char* modified_filename = malloc(sizeof(char) * (strlen(new_filename) + strlen(extension) + 1));
    sprintf(modified_filename, "%s%s", new_filename, extension);
    free(new_filename);
    free(new_extension);

    // Return a pointer to the modified filename string
    return modified_filename;
}

// Function to handle command line parsing and validate input
int main(int argc, char* argv[]) {
    // Check if valid input file is provided
    if (argc < 2) {
        printf("Usage: %s [options] filename\n", argv[0]);
        return 1;
    }

    // Parse command line options and validate input
    char* filename = argv[1];
    if (!validate_input(filename)) {
        printf("Invalid input filename\n");
        return 1;
    }

    // Modify the filename based on the provided options
    char* modified_filename = modify_filename(filename);
    if (modified_filename == NULL) {
        printf("Error: unable to modify filename\n");
        return 1;
    }

    // Print usage information for --manpage option
    if (strcmp(argv[2], "--manpage") == 0) {
        printf("Usage: %s [options] filename\n", argv[0]);
        printf("Options:\n");
        printf("\t-cs\tCharacter set analysis\n");
        printf("\t-o output_file\tSpecify the destination for the modified filename\n");
        return 0;
    }

    // Print usage information for -cs option
    if (strcmp(argv[2], "-cs") == 0) {
        printf("Usage: %s [options] filename\n", argv[0]);
        printf("Options:\n");
        printf("\t-cs\tCharacter set analysis\n");
        return 0;
    }

    // Print usage information for -o option
    if (strcmp(argv[2], "-o") == 0) {
        printf("Usage: %s [options] filename\n", argv[0]);
        printf("Options:\n");
        printf("\t-o output_file\tSpecify the destination for the modified filename\n");
        return 0;
    }

    // Print usage information if no options are provided
    if (strcmp(argv[2], "") == 0) {
        printf("Usage: %s [options] filename\n", argv[0]);
        printf("Options:\n");
        printf("\t-cs\tCharacter set analysis\n");
        printf("\t-o output_file\tSpecify the destination for the modified filename\n");
        return 0;
    }

    // Print error message if invalid option is provided
    if (strcmp(argv[2], "-cs") != 0 && strcmp(argv[2], "-o") != 0) {
        printf("Invalid option: %s\n", argv[2]);
        return 1;
    }

    // Print modified filename and free the buffer manually by the caller after use
    printf("%s\n", modified_filename);
    free(modified_filename);

    return 0;
}
