                frequency_count.max_frequency = unique_ints.num_ints;
            }
        } else if (isdigit(entry[0]) && isdigit(entry[1])) {
            float num = atof(entry);

            // Add the floating-point number to the dynamic array of unique floating-point numbers
            if (unique_floats.num_floats < MAX_UNIQUE_FLOATS) {
                unique_floats.floats = realloc(unique_floats.floats, sizeof(float) * (unique_floats.num_floats + 1));
                unique_floats.floats[unique_floats.num_floats++] = num;
            } else {
                // Handle memory allocation failure gracefully
                printf("Memory allocation failed for floating-point numbers\n");
            }

            // Update the running count of the most frequent numerical value
            if (frequency_count.max_frequency < unique_floats.num_floats) {
                frequency_count.max_frequency = unique_floats.num_floats;
            }
        } else {
            // Handle unexpected data formats gracefully
            printf("Unexpected data format encountered\n");
        }
    }

    // Flush the intermediate results to a persistent storage solution for auditing and analysis purposes
    flush_intermediate_results(&intermediate_results);
