// Initialize a new hash table with a given capacity
hash_table_t* init_hash_table(size_t capacity) {
    hash_table_t *ht = malloc(sizeof(hash_table_t));
    ht->keys = calloc(capacity, sizeof(uint64_t));
    ht->values = calloc(capacity, sizeof(transaction_t*));
    ht->capacity = capacity;
    ht->size = 0;
    return ht;
}

// Insert a new key-value pair into the hash table
void insert_hash_table(hash_table_t *ht, uint64_t key, transaction_t *value) {
    if (ht->size == ht->capacity) {
        // Resize the hash table if it's full
        size_t new_capacity = ht->capacity * 2;
        ht->keys = realloc(ht->keys, new_capacity * sizeof(uint64_t));
        ht->values = realloc(ht->values, new_capacity * sizeof(transaction_t*));
        ht->capacity = new_capacity;
    }
    ht->keys[ht->size] = key;
    ht->values[ht->size] = value;
    ht->size++;
}

// Look up a value in the hash table by its key
transaction_t* lookup_hash_table(hash_table_t *ht, uint64_t key) {
    for (int i = 0; i < ht->size; i++) {
        if (ht->keys[i] == key) {
            return ht->values[i];
        }
    }
    return NULL;
}

// Free the memory allocated by the hash table
