    tx->fee = generate_random_number(0.0, 100.0);
    return tx;
}

// Add a new transaction to the hash table and cache its fee value
void add_transaction(hash_table_t *ht, uint64_t id, int status) {
    transaction_t *tx = create_transaction(id, status);
    insert_hash_table(ht, id, tx);
    // Add the transaction's fee value to the cache
    long *cache = ht->values[ht->size - 1]->fee;
    if (cache == NULL) {
        cache = init_array(CACHE_SIZE, 0.0, 100.0);
        ht->values[ht->size - 1]->fee = cache;
    }
    cache[id % CACHE_SIZE] = tx->fee;
}

// Retrieve a transaction's fee value from the cache
