    // Initialize a hash table with a capacity of 1000
    hash_table_t *ht = init_hash_table(1000);

    // Add some transactions to the hash table and cache their fee values
    add_transaction(ht, 1, 1);
    add_transaction(ht, 2, 2);
    add_transaction(ht, 3, 3);
    add_transaction(ht, 4, 4);
    add_transaction(ht, 5, 5);

    // Print the transactions in the hash table
    print_transaction(ht, 1);
    print_transaction(ht, 2);
    print_transaction(ht, 3);
    print_transaction(ht, 4);
    print_transaction(ht, 5);

    // Free the memory allocated by the hash table and its contents
    free_hash_table(ht);

