#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/stat.h>
#include <time.h>

// Define constants for file types and extensions
#define FILE_TYPE_TEXT 0
#define FILE_TYPE_EXECUTABLE 1
#define FILE_TYPE_UNKNOWN 2
#define EXTENSION_TXT ".txt"
#define EXTENSION_EXE ".exe"

// Define structure for file metadata
typedef struct {
    char *name;
    long size;
    time_t modtime;
    int type;
} FileMetadata;

// Function to parse command line arguments and validate input
int parseArgs(char **args, int argc) {
    // Check if there are at least two arguments (program name and directory path)
    if (argc < 2) {
        printf("Error: Invalid number of arguments. Please specify a directory path.\n");
        return -1;
    }

    // Validate the directory path
    struct stat dirStat;
    if (stat(args[1], &dirStat) != 0 || !S_ISDIR(dirStat.st_mode)) {
        printf("Error: Invalid directory path. Please specify a valid directory path.\n");
        return -1;
    }

    // Check if the input meets basic requirements (alphanumeric and period)
    for (int i = 0; i < argc; i++) {
        char *arg = args[i];
        int hasAlphaNum = 0, hasPeriod = 0;
        while (*arg != '\0') {
            if (isalnum(*arg)) {
                hasAlphaNum = 1;
            } else if (*arg == '.') {
                hasPeriod = 1;
            }
            arg++;
        }
        if (!hasAlphaNum || !hasPeriod) {
            printf("Error: Invalid input. Please specify a valid directory path.\n");
            return -1;
        }
    }

    // Return success
    return 0;
}

// Function to extract metadata from a file
FileMetadata *extractMetadata(char *filename) {
    FileMetadata *metadata = malloc(sizeof(FileMetadata));
    if (metadata == NULL) {
        printf("Error: Failed to allocate memory for file metadata.\n");
        return NULL;
    }

    // Get file size and modification time
    struct stat fileStat;
    if (stat(filename, &fileStat) != 0) {
        free(metadata);
        return NULL;
    }
    metadata->size = fileStat.st_size / 1024;
    metadata->modtime = fileStat.st_mtime;

    // Get file type based on extension
    char *extension = strrchr(filename, '.');
    if (extension == NULL) {
        free(metadata);
        return NULL;
    }
    if (strcmp(extension, EXTENSION_TXT) == 0) {
        metadata->type = FILE_TYPE_TEXT;
    } else if (strcmp(extension, EXTENSION_EXE) == 0) {
        metadata->type = FILE_TYPE_EXECUTABLE;
    } else {
        metadata->type = FILE_TYPE_UNKNOWN;
    }

    // Return the file metadata
    return metadata;
}

// Function to categorize a file based on its type and modification date
int classifyFile(FileMetadata *metadata) {
    if (metadata == NULL) {
        return -1;
    }

    // Classify text files as "log" if they contain lines starting with "INFO" or "ERROR"
    if (metadata->type == FILE_TYPE_TEXT) {
        char *line = malloc(256);
        FILE *file = fopen(metadata->name, "r");
        while (fgets(line, 256, file) != NULL) {
            if (strncmp(line, "INFO", 4) == 0 || strncmp(line, "ERROR", 5) == 0) {
                metadata->type = FILE_TYPE_LOG;
                break;
            }
        }
        fclose(file);
        free(line);
    }

    // Classify executable files as "utility" if they have been modified within the last 30 days
    if (metadata->type == FILE_TYPE_EXECUTABLE) {
        time_t currentTime = time(NULL);
        if (difftime(currentTime, metadata->modtime) < 30 * 86400) {
            metadata->type = FILE_TYPE_UTILITY;
        }
    }

    // Return the file classification
    return metadata->type;
}

// Function to generate a summary report for all files in a directory
char *generateSummaryReport(char *directoryPath) {
    char *report = malloc(512);
    if (report == NULL) {
        printf("Error: Failed to allocate memory for summary report.\n");
        return NULL;
    }

    // Count the number of log, utility, and unknown files in the directory
    int numLogFiles = 0, numUtilityFiles = 0, numUnknownFiles = 0;
    struct dirent *entry;
    DIR *dir = opendir(directoryPath);
    while ((entry = readdir(dir)) != NULL) {
        char *filename = entry->d_name;
        FileMetadata *metadata = extractMetadata(filename);
        if (metadata == NULL) {
            continue;
        }
        int classification = classifyFile(metadata);
        switch (classification) {
            case FILE_TYPE_LOG:
                numLogFiles++;
                break;
            case FILE_TYPE_UTILITY:
                numUtilityFiles++;
                break;
            default:
                numUnknownFiles++;
                break;
        }
    }
    closedir(dir);

    // Generate the summary report
    sprintf(report, "Log files: %d\nUtility files: %d\nUnknown files: %d", numLogFiles, numUtilityFiles, numUnknownFiles);

    // Return the summary report
    return report;
}

// Function to generate a detailed report for each file in a directory
char *generateDetailedReport(char *directoryPath) {
    char *report = malloc(512);
    if (report == NULL) {
        printf("Error: Failed to allocate memory for detailed report.\n");
        return NULL;
    }

    // Iterate over each file in the directory and generate a detailed report for it
    struct dirent *entry;
    DIR *dir = opendir(directoryPath);
    while ((entry = readdir(dir)) != NULL) {
        char *filename = entry->d_name;
        FileMetadata *metadata = extractMetadata(filename);
        if (metadata == NULL) {
            continue;
        }
        int classification = classifyFile(metadata);
        sprintf(report, "Filename: %s\nSize: %ld KB\nModification date: %s\nClassification: %s", filename, metadata->size, ctime(&metadata->modtime), getClassificationString(classification));
    }
    closedir(dir);

    // Return the detailed report
    return report;
}

// Function to generate a string representation of a file classification
char *getClassificationString(int classification) {
    switch (classification) {
        case FILE_TYPE_LOG:
            return "Log";
        case FILE_TYPE_UTILITY:
            return "Utility";
        default:
            return "Unknown";
    }
}

// Main function to process a directory of files and generate summary and detailed reports based on user-specified criteria
int main(int argc, char **args) {
    // Parse command line arguments and validate input
    if (parseArgs(args, argc) != 0) {
        return -1;
    }

    // Generate summary report for all files in the directory
    char *summaryReport = generateSummaryReport(args[1]);
    if (summaryReport == NULL) {
        printf("Error: Failed to generate summary report.\n");
        return -1;
    }
    printf("%s\n", summaryReport);
    free(summaryReport);

    // Generate detailed reports for each file in the directory
    char *detailedReport = generateDetailedReport(args[1]);
    if (detailedReport == NULL) {
        printf("Error: Failed to generate detailed report.\n");
        return -1;
    }
    printf("%s\n", detailedReport);
    free(detailedReport);

    // Return success
    return 0;
}
```
