    if (file == NULL) {
        printf("Error: unable to open %s for reading\n", filename);
        return NULL;
    }
    fseek(file, 0, SEEK_END);
    long file_size = ftell(file);
    rewind(file);
    char* buffer = malloc(sizeof(char) * (file_size + 1));
    if (buffer == NULL) {
        printf("Error: unable to allocate memory for %s\n", filename);
        fclose(file);
        return NULL;
    }
    size_t bytes_read = fread(buffer, sizeof(char), file_size, file);
    if (bytes_read != file_size) {
        printf("Error: unable to read entire %s\n", filename);
        free(buffer);
        fclose(file);
        return NULL;
    }
    buffer[file_size] = '\0';
    fclose(file);
    return buffer;
}
