#include <openssl/err.h>

// Helper function to fetch a private key and certificate from a specified location
void fetch_private_key_and_certificate(char* location, char** private_key, char** certificate) {
    // Open the file containing the private key and certificate
    FILE* fp = fopen(location, "r");
    if (fp == NULL) {
        printf("Error: unable to open file %s\n", location);
        return;
    }

    // Read the contents of the file into a buffer
    char* buffer = malloc(1024 * 1024);
    size_t length = fread(buffer, 1, 1024 * 1024, fp);
    if (length == 0) {
        printf("Error: unable to read file %s\n", location);
        return;
    }

    // Close the file
    fclose(fp);

    // Parse the buffer as a PEM file and extract the private key and certificate
    X509* x509 = d2i_X509_fp(buffer, length);
    if (x509 == NULL) {
        printf("Error: unable to parse PEM file %s\n", location);
        return;
    }

    // Extract the private key and certificate from the X509 structure
    EVP_PKEY* pkey = X509_get_pubkey(x509);
    if (pkey == NULL) {
        printf("Error: unable to extract private key from PEM file %s\n", location);
        return;
    }

    // Convert the private key and certificate to a PEM format string
    BIO* bio = BIO_new(BIO_s_mem());
    if (bio == NULL) {
        printf("Error: unable to create memory BIO\n");
        return;
    }

    // Write the private key and certificate to the memory BIO
    PEM_write_bio_PrivateKey(bio, pkey, NULL, NULL, 0, NULL, NULL);
    PEM_write_bio_X509(bio, x509);

    // Get the length of the PEM format string
    long len = BIO_pending(bio);

    // Allocate memory for the PEM format string
    *private_key = malloc(len + 1);
    if (*private_key == NULL) {
        printf("Error: unable to allocate memory for private key\n");
        return;
    }

    // Read the PEM format string from the memory BIO
    BIO_read(bio, *private_key, len);
    (*private_key)[len] = '\0';

    // Allocate memory for the certificate
    *certificate = malloc(len + 1);
    if (*certificate == NULL) {
        printf("Error: unable to allocate memory for certificate\n");
        return;
    }

    // Read the PEM format string from the memory BIO
    BIO_read(bio, *certificate, len);
    (*certificate)[len] = '\0';

    // Clean up
    BIO_free(bio);
    X509_free(x509);
    EVP_PKEY_free(pkey);
}

