int main() {
    // Initialize variables
    int *integers = NULL;
    int size = 0;
    int largest = -1;

    // Read integers from standard input until EOF is reached
    while (size < MAX_INTEGERS) {
        // Allocate memory for the next integer
        integers = realloc(integers, sizeof(int) * (size + 1));
        if (!integers) {
            perror("realloc");
            exit(EXIT_FAILURE);
