    ret = fread(private_key, 1024, 1, fp);
    if (ret != 1) {
        perror("fread");
        goto cleanup;
    }

    // Validate the integrity and freshness of the certificate and private key
    SSL_CTX *ctx = SSL_CTX_new(TLS_client_method());
    if (!ctx) {
        perror("SSL_CTX_new");
        goto cleanup;
    }
    SSL *ssl = SSL_new(ctx);
    if (!ssl) {
        perror("SSL_new");
        goto cleanup;
    }
    ret = SSL_use_certificate_file(ssl, certificate, SSL_FILETYPE_PEM);
    if (ret != 1) {
        perror("SSL_use_certificate_file");
        goto cleanup;
    }
    ret = SSL_use_PrivateKey_file(ssl, private_key, SSL_FILETYPE_PEM);
    if (ret != 1) {
        perror("SSL_use_PrivateKey_file");
        goto cleanup;
    }

    // If the certificate and private key are valid, return them
    ret = 0;
    goto cleanup;

cleanup:
    // Free any allocated memory
    free(certificate);
    free(private_key);
    SSL_free(ssl);
    SSL_CTX_free(ctx);

    return ret;
}

// Define the function to integrate the retrieval process with existing system dependencies and handle potential network delays and intermittent connectivity issues
int fetch_oauth_credentials_with_retry(char *file_path) {
    // Initialize variables
    int ret = -1;
    char *certificate = NULL;
    char *private_key = NULL;

    // Retry the OAuth credentials retrieval process with exponential backoff and jitter
    for (int i = 0; i < 5; i++) {
        ret = fetch_oauth_credentials(file_path);
        if (ret == 0) break;
        sleep(pow(2, i));
    }

    // If the OAuth credentials are still not available after retrying, return an error
    if (ret != 0) {
        perror("fetch_oauth_credentials");
        goto cleanup;
    }

    // Return the fetched certificate and private key
    ret = 0;
    goto cleanup;

cleanup:
    // Free any allocated memory
    free(certificate);
    free(private_key);

    return ret;
}

// Define the function to log all operations, including errors and successful transmissions, to a designated log file
void log_operation(char *message) {
    // Open the log file for writing
    FILE *fp = fopen(LOG_FILE_PATH, "a");
    if (!fp) {
        perror("fopen");
        return;
    }

    // Write the log message to the file
    fprintf(fp, "%s\n", message);

    // Close the log file
    fclose(fp);
}
