// Helper function to calculate the average of a list of numbers
double average(int n, double *numbers) {
    double sum = 0;
    for (int i = 0; i < n; i++) {
        sum += numbers[i];
    }
    return sum / n;
}

// Function to read floating-point numbers from standard input and calculate the average
void read_input(double *numbers, int size) {
    for (int i = 0; i < size; i++) {
        printf("Enter number %d: ", i + 1);
        scanf("%lf", &numbers[i]);
    }
}

// Function to process an HTTP request and calculate the sum and product of numerical values in a JSON document
void process_http_request(char *url) {
    CURL *curl;
    CURLcode res;
    curl = curl_easy_init();
    if (curl) {
        curl_easy_setopt(curl, CURLOPT_URL, url);
        curl_easy_setopt(curl, CURLOPT_WRITEFUNCTION, write_data);
        res = curl_easy_perform(curl);
        if (res != CURLE_OK) {
            fprintf(stderr, "curl_easy_perform() failed: %s\n", curl_easy_strerror(res));
        } else {
            printf("JSON document fetched successfully.\n");
        }
    }
}

// Helper function to parse a JSON document and extract numerical values
void parse_json(char *data, double *numbers) {
    int i = 0;
    while (i < size && data[i] != '\0') {
        if (data[i] == '{' || data[i] == '[') {
            // Parse the JSON document and extract numerical values
            numbers[i] = atof(data + i);
            i++;
        } else {
            i++;
        }
    }
}

// Function to calculate the sum and product of numerical values in a JSON document
void calculate_sum_product(char *url) {
    double numbers[size];
    parse_json(url, numbers);
    double average = average(size, numbers);
    printf("Average: %lf\n", average);
}

int main() {
    // Read floating-point numbers from standard input and calculate the average
    double numbers[size];
    read_input(numbers, size);
    double average = average(size, numbers);
    printf("Average: %lf\n", average);

    // Process an HTTP request and calculate the sum and product of numerical values in a JSON document
    char *url = "https://example.com/json_document";
    process_http_request(url);
    calculate_sum_product(url);

    return 0;
}
