#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/stat.h>
#include <unistd.h>
#include <dirent.h>
#include <errno.h>

#define MAX_FILENAME_LENGTH 256
#define MAX_REPORT_LENGTH 512

// Struct to store file metadata
typedef struct {
    char name[MAX_FILENAME_LENGTH];
    long size;
    time_t modtime;
    char type[MAX_FILENAME_LENGTH];
} FileMetadata;

// Function to validate directory path and return a pointer to the directory
char* validateDirectory(char* dirPath) {
    struct stat sb;
    if (stat(dirPath, &sb) == 0 && S_ISDIR(sb.st_mode)) {
        return dirPath;
    } else {
        fprintf(stderr, "Error: Invalid directory path\n");
        exit(1);
    }
}

// Function to validate file name and return a pointer to the file name
char* validateFileName(char* fileName) {
    if (strlen(fileName) > 0 && strchr(fileName, '.') != NULL) {
        return fileName;
    } else {
        fprintf(stderr, "Error: Invalid file name\n");
        exit(1);
    }
}

// Function to extract metadata from a file and store it in a FileMetadata struct
FileMetadata* extractMetadata(char* fileName) {
    // Initialize the FileMetadata struct
    FileMetadata* metadata = malloc(sizeof(FileMetadata));
    strcpy(metadata->name, validateFileName(fileName));
    metadata->size = 0;
    metadata->modtime = 0;
    strcpy(metadata->type, "unknown");

    // Open the file and extract its metadata
    FILE* fp = fopen(fileName, "r");
    if (fp == NULL) {
        fprintf(stderr, "Error: Could not open file %s\n", fileName);
        exit(1);
    }
    fseek(fp, 0, SEEK_END);
    metadata->size = ftell(fp);
    rewind(fp);
    struct stat sb;
    if (fstat(fileno(fp), &sb) == 0) {
        metadata->modtime = sb.st_mtime;
    } else {
        fprintf(stderr, "Error: Could not get file status\n");
        exit(1);
    }
    fclose(fp);

    // Determine the file type based on its extension
    char* ext = strrchr(fileName, '.');
    if (ext != NULL) {
        if (strcmp(ext, ".txt") == 0) {
            metadata->type = "text";
        } else if (strcmp(ext, ".exe") == 0) {
            metadata->type = "utility";
        }
    }

    return metadata;
}

// Function to categorize a file based on its type and size
char* classifyFile(FileMetadata* metadata) {
    if (strcmp(metadata->type, "text") == 0 && strstr(metadata->name, "INFO") != NULL) {
        return "log";
    } else if (strcmp(metadata->type, "utility") == 0 && metadata->modtime > time(NULL) - 30 * 86400) {
        return "utility";
    } else {
        return "unknown";
    }
}

// Function to generate a summary report for all files in the directory
char* generateSummaryReport(char* dirPath, int fileCount, int logFileCount, int utilityFileCount, int unknownFileCount) {
    // Initialize the report string
    char* report = malloc(MAX_REPORT_LENGTH);
    strcpy(report, "Directory: ");
    strcat(report, dirPath);
    strcat(report, "\n");
    strcat(report, "Files: ");
    sprintf(report + strlen(report), "%d", fileCount);
    strcat(report, "\n");
    strcat(report, "Log files: ");
    sprintf(report + strlen(report), "%d", logFileCount);
    strcat(report, "\n");
    strcat(report, "Utility files: ");
    sprintf(report + strlen(report), "%d", utilityFileCount);
    strcat(report, "\n");
    strcat(report, "Unknown files: ");
    sprintf(report + strlen(report), "%d", unknownFileCount);
    strcat(report, "\n");

    return report;
}

// Function to generate a detailed report for each file in the directory
char* generateDetailedReport(FileMetadata* metadata) {
    // Initialize the report string
    char* report = malloc(MAX_REPORT_LENGTH);
    strcpy(report, "Name: ");
    strcat(report, metadata->name);
    strcat(report, "\n");
    strcat(report, "Size: ");
    sprintf(report + strlen(report), "%ld", metadata->size / 1024);
    strcat(report, " KB\n");
    strcat(report, "Modification date: ");
    char* modtimeStr = ctime(&metadata->modtime);
    strcat(report, modtimeStr);
    strcat(report, "\n");
    strcat(report, "Type: ");
    strcat(report, metadata->type);
    strcat(report, "\n");
    strcat(report, "Classification: ");
    char* classification = classifyFile(metadata);
    strcat(report, classification);
    strcat(report, "\n");

    return report;
}

// Main function to process the directory of files and generate reports
int main(int argc, char** argv) {
    // Validate command line arguments
    if (argc < 2) {
        fprintf(stderr, "Error: No directory specified\n");
        exit(1);
    }
    char* dirPath = validateDirectory(argv[1]);

    // Initialize variables to store file metadata and report strings
    int fileCount = 0;
    int logFileCount = 0;
    int utilityFileCount = 0;
    int unknownFileCount = 0;
    char* summaryReport = NULL;
    char* detailedReports = NULL;

    // Iterate over the files in the directory and extract metadata
    DIR* dir = opendir(dirPath);
    if (dir == NULL) {
        fprintf(stderr, "Error: Could not open directory %s\n", dirPath);
        exit(1);
    }
    struct dirent* entry;
    while ((entry = readdir(dir)) != NULL) {
        // Skip hidden files and directories
        if (strncmp(entry->d_name, ".", 1) == 0 || strncmp(entry->d_name, "..", 2) == 0) {
            continue;
        }

        // Extract metadata for the current file
        FileMetadata* metadata = extractMetadata(entry->d_name);
        if (metadata == NULL) {
            fprintf(stderr, "Error: Could not extract metadata for %s\n", entry->d_name);
            exit(1);
        }

        // Increment file count and categorize the file based on its type and size
        fileCount++;
        char* classification = classifyFile(metadata);
        if (strcmp(classification, "log") == 0) {
            logFileCount++;
        } else if (strcmp(classification, "utility") == 0) {
            utilityFileCount++;
        } else {
            unknownFileCount++;
        }

        // Generate detailed report for the current file
        char* detailedReport = generateDetailedReport(metadata);
        if (detailedReport == NULL) {
            fprintf(stderr, "Error: Could not generate detailed report for %s\n", entry->d_name);
            exit(1);
        }
        // Add the detailed report to the list of reports
        char* newReports = realloc(detailedReports, (fileCount + 1) * MAX_REPORT_LENGTH);
        if (newReports == NULL) {
            fprintf(stderr, "Error: Could not allocate memory for detailed report\n");
            exit(1);
        }
        detailedReports = newReports;
        strcat(detailedReports, detailedReport);
    }
    closedir(dir);

    // Generate summary report for all files in the directory
    char* summaryReport = generateSummaryReport(dirPath, fileCount, logFileCount, utilityFileCount, unknownFileCount);
    if (summaryReport == NULL) {
        fprintf(stderr, "Error: Could not generate summary report\n");
        exit(1);
    }

    // Print the summary and detailed reports to stdout
    printf("%s", summaryReport);
    printf("%s", detailedReports);

    // Free memory allocated for the reports
    free(summaryReport);
    free(detailedReports);

    return 0;
}']

