#include <json-c/json.h>

// Structure to store the results of the calculation
typedef struct {
    double sum;
    double product;
} CalculationResults;

// Function to read a list of floating-point numbers from standard input and calculate their average
CalculationResults calculateAverage(int numValues) {
    // Initialize an array to store the values
    float *values = malloc(numValues * sizeof(float));

    // Read the values from standard input
    for (int i = 0; i < numValues; i++) {
        scanf("%f", &values[i]);
    }

    // Calculate the average of the values
    double sum = 0.0;
    for (int i = 0; i < numValues; i++) {
        sum += values[i];
    }
    double average = sum / numValues;

    // Free the memory used by the array
    free(values);

    // Return the results as a structure
    CalculationResults results;
    results.sum = sum;
    results.product = 1.0;
    return results;
}

// Function to process an HTTP request containing the URL of a JSON document and calculate its sum and product
CalculationResults processJsonRequest(const char *url) {
    // Initialize a JSON object to store the parsed data
    json_object *json = json_object_new();

    // Fetch the JSON document from the specified URL
    json_object *response = json_object_from_file(url);

    // Check if there was an error fetching the document
    if (response == NULL) {
        printf("Error: unable to fetch JSON document\n");
        return;
    }

    // Parse the JSON data and extract the numerical values
    json_object *data = json_object_get(response);
    int numValues = json_object_array_length(data);
    float *values = malloc(numValues * sizeof(float));
    for (int i = 0; i < numValues; i++) {
        json_object *value = json_object_array_get_idx(data, i);
        if (!json_is_number(value)) {
            printf("Error: non-numeric value found in JSON document\n");
            return;
        }
        values[i] = json_number_value(value);
    }

    // Calculate the sum and product of the numerical values
    double sum = 0.0;
    for (int i = 0; i < numValues; i++) {
        sum += values[i];
    }
    double product = 1.0;
    for (int i = 0; i < numValues; i++) {
        product *= values[i];
    }

    // Free the memory used by the JSON object and array
    json_object_put(json);
    free(values);

    // Return the results as a structure
    CalculationResults results;
    results.sum = sum;
    results.product = product;
    return results;
}

int main() {
    // Read the number of values to calculate from standard input
    int numValues;
    scanf("%d", &numValues);

    // Calculate the average of the values
    CalculationResults results = calculateAverage(numValues);
    printf("The average is: %f\n", results.sum / results.product);

    // Process an HTTP request containing the URL of a JSON document
    const char *url = "https://example.com/json";
    results = processJsonRequest(url);
    printf("The sum and product of the values in the JSON document are: %f, %f\n", results.sum, results.product);

    return 0;
}
