            fprintf(stderr, "Error: Key %d exceeds the valid range of %d\n", new_key, VALID_RANGE);
            continue;
        }

        // Update the current offset and key
        current_offset += read;
        current_key = new_key;

        // Allocate memory for the record structure
        record *new_record = (record *)malloc(sizeof(record));
        if (new_record == NULL) {
            perror("Error allocating memory for record");
            continue;
        }

        // Initialize the new record with the current offset and key
        new_record->key = current_key;
        new_record->string = strdup(line);

