// Define the function to handle command line arguments and provide usage information if no input files are provided.
void handle_arguments(int argc, char* argv[]) {
    // Implement a mechanism to detect and handle invalid input gracefully
    if (argc < 2) {
        log(1, "Usage: %s [options]", argv[0]);
        return;
