    while (option_index < argc) {
        switch (argv[option_index][1]) {
            case 'h':
                log(1, "Usage: %s [options]", argv[0]);
                break;
            case 'c':
                count_characters(argv[option_index + 1]);
                break;
            case 's':
                count_words(argv[option_index + 1]);
                break;
            case 'o':
                write_word_count(argv[option_index + 2], atoi(argv[option_index + 3]));
                break;
            case 'd':
                DELIMITER = argv[option_index + 1][0];
                break;
            default:
                log(2, "Invalid option: %s", argv[option_index]);
        }
    }
}

int main(int argc, char* argv[]) {
