// Function to handle pagination of query results
void handlePagination(DistributedDatabase* db, int page_number, int items_per_page) {
    // Acquire the mutex for the database
    pthread_mutex_lock(&db->mutex);

    // Calculate the starting index and ending index of the query result set
    int start_index = (page_number - 1) * items_per_page;
    int end_index = page_number * items_per_page;

    // Create a new query result set with the paginated results
    QueryResultSet* results = malloc(sizeof(QueryResultSet));
    results->num_results = 0;
    results->max_results = end_index - start_index;
    results->results = malloc(sizeof(QueryResult) * (end_index - start_index));

    // Iterate over the user profiles in the database and add them to the query result set
    for (int i = 0; i < db->num_profiles; i++) {
        if (i >= start_index && i < end_index) {
            results->results[results->num_results++] = db->profiles[i];
        }
    }

    // Release the mutex for the database
    pthread_mutex_unlock(&db->mutex);
