    results->results = malloc(sizeof(QueryResult) * 10);

    // Iterate over the user profiles in the database and add them to the query result set if they match the search query
    for (int i = 0; i < db->num_profiles; i++) {
        UserProfile* profile = &db->profiles[i];
        if (strstr(profile->name, query) || strstr(profile->email, query)) {
            results->results[results->num_results++] = *profile;
        }
    }

    // Release the mutex for the database
    pthread_mutex_unlock(&db->mutex);
}

