void handleCaching(DistributedDatabase* db, int id) {
    // Acquire the mutex for the database
    pthread_mutex_lock(&db->mutex);

    // Check if the user profile exists in the cache
    bool found = false;
    for (int i = 0; i < db->num_profiles; i++) {
        if (db->profiles[i].id == id) {
            found = true;
            break;
        }
    }

    // If the user profile exists in the cache, return it
    if (found) {
        return db->profiles[i];
    } else {
        // If the user profile does not exist in the cache, query it from the database and add it to the cache
        UserProfile* profile = malloc(sizeof(UserProfile));
        profile->id = id;
        strcpy(profile->name, "");
