    pthread_mutex_lock(&db->mutex);

    // Add the log message to the database
    db->messages[db->num_messages++] = *message;

    // Release the mutex for the database
    pthread_mutex_unlock(&db->mutex);
}

// Function to handle consensus mechanisms for distributed databases
void handleConsensus(DistributedDatabase* db, ConsensusMechanism* mechanism) {
    // Acquire the mutex for the database
    pthread_mutex_lock(&db->mutex);

    // Check if the current node is the leader
    if (mechanism->is_leader) {
        // If the current node is the leader, update the database with the latest information from other nodes
        for (int i = 0; i < db->num_profiles; i++) {
            UserProfile* profile = &db->profiles[i];
            if (profile->id == mechanism->id) {
                profile->name = mechanism->name;
                profile->email = mechanism->email;
                profile->age = mechanism->age;
                profile->address = mechanism->address;
                profile->phone_number = mechanism->phone_number;
            }
        }
    } else {
        // If the current node is not the leader, send an update message to the leader with the latest information from other nodes
        for (int i = 0; i < db->num_profiles; i++) {
            UserProfile* profile = &db->profiles[i];
            if (profile->id == mechanism->id) {
                mechanism->name = profile->name;
                mechanism->email = profile->email;
                mechanism->age = profile->age;
                mechanism->address = profile->address;
                mechanism->phone_number = profile->phone_number;
            }
        }
    }

    // Release the mutex for the database
    pthread_mutex_unlock(&db->mutex);
}
