                           "  -s, --count-words     Count the total number of words in the file\n"
                           "  -o <output file>, --output-file=<output file>\n"
                           "                       Write the word count to this file instead of printing it to stdout\n"
                           "  -d <delimiter>, --delimiter=<delimiter>\n"
                           "                       Specify a custom word delimiter for the word count\n";

