#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <errno.h>
#include <pthread.h>
#include <semaphore.h>

// Define the structure for a record
typedef struct {
    int key;
    char *value;
} Record;

// Define the function to dynamically allocate memory for and initialize three arrays: one for 'long' offset values, one for 'int' keys, and one for 'record' structures containing a single 'int' value and an associated 'char' string.
void init_arrays(int num_records, int max_key, char *delimiter) {
    // Allocate memory for the offset array
    long *offsets = (long *)malloc(num_records * sizeof(long));
    if (!offsets) {
        fprintf(stderr, "Error: failed to allocate memory for offsets\n");
        exit(1);
    }

    // Allocate memory for the key array
    int *keys = (int *)malloc(num_records * sizeof(int));
    if (!keys) {
        fprintf(stderr, "Error: failed to allocate memory for keys\n");
        exit(1);
    }

    // Allocate memory for the record array
    Record *records = (Record *)malloc(num_records * sizeof(Record));
    if (!records) {
        fprintf(stderr, "Error: failed to allocate memory for records\n");
        exit(1);
    }

    // Initialize the offset array
    for (int i = 0; i < num_records; i++) {
        offsets[i] = 0;
    }

    // Initialize the key array
    for (int i = 0; i < num_records; i++) {
        keys[i] = 0;
    }

    // Initialize the record array
    for (int i = 0; i < num_records; i++) {
        records[i].key = 0;
        records[i].value = NULL;
    }

    // Set the maximum key value
    max_key = num_records - 1;

    // Set the delimiter for the record values
    delimiter = " ";
}

// Define the function to handle file operations, including managing permissions and handling non-existent files.
void handle_file(char *filename) {
    int fd = open(filename, O_RDONLY);
    if (fd == -1) {
        perror("Error: failed to open file");
        exit(1);
    }

    // Check the permissions of the file
    struct stat sb;
    if (fstat(fd, &sb) == -1) {
        perror("Error: failed to get file status");
        close(fd);
        exit(1);
    }

    if (!S_ISREG(sb.st_mode)) {
        fprintf(stderr, "Error: file is not a regular file\n");
        close(fd);
        exit(1);
    }

    // Read the contents of the file
    char *buffer = (char *)malloc(sb.st_size + 1);
    if (!buffer) {
        fprintf(stderr, "Error: failed to allocate memory for buffer\n");
        close(fd);
        exit(1);
    }

    ssize_t bytes_read = read(fd, buffer, sb.st_size);
    if (bytes_read == -1) {
        perror("Error: failed to read file");
        free(buffer);
        close(fd);
        exit(1);
    }

    // Close the file descriptor
    close(fd);

    // Process the contents of the file
    process_file(buffer, bytes_read);

    // Free the memory allocated for the buffer
    free(buffer);
}

// Define the function to process the contents of a file.
void process_file(char *buffer, size_t length) {
    // Initialize the offset array and key array
    int num_records = 0;
    int max_key = -1;
    char *delimiter = " ";
    init_arrays(num_records, max_key, delimiter);

    // Parse the contents of the file
    for (int i = 0; i < length; i++) {
        if (buffer[i] == '\n') {
            num_records++;
        }
    }

    // Allocate memory for the record array
    Record *records = (Record *)malloc(num_records * sizeof(Record));
    if (!records) {
        fprintf(stderr, "Error: failed to allocate memory for records\n");
        exit(1);
    }

    // Initialize the record array
    for (int i = 0; i < num_records; i++) {
        records[i].key = 0;
        records[i].value = NULL;
    }

    // Parse the contents of the file and populate the record array
    int current_record = 0;
    for (int i = 0; i < length; i++) {
        if (buffer[i] == '\n') {
            records[current_record].key++;
            records[current_record].value = &buffer[i + 1];
            current_record++;
        }
    }

    // Print the record array
    for (int i = 0; i < num_records; i++) {
        printf("%d: %s\n", records[i].key, records[i].value);
    }

    // Free the memory allocated for the record array
    free(records);
}

// Define the function to handle concurrent execution gracefully.
void handle_concurrent_execution() {
    // Create a semaphore to synchronize access to shared data structures
    sem_t *sem = sem_open("my_sem", O_CREAT, 0644, 1);
    if (sem == SEM_FAILED) {
        perror("Error: failed to create semaphore");
        exit(1);
    }

    // Acquire the semaphore before accessing shared data structures
    if (sem_wait(sem) == -1) {
        perror("Error: failed to acquire semaphore");
        exit(1);
    }

    // Release the semaphore after accessing shared data structures
    if (sem_post(sem) == -1) {
        perror("Error: failed to release semaphore");
        exit(1);
    }
}

