#define BUFFER_SIZE 4096

// Define the struct for storing word counts
typedef struct {
    char *word;
    int count;
} WordCount;

// Define the function to handle errors
void error(const char *msg) {
    perror(msg);
    exit(1);
}

// Define the function to count the number of characters in a file
int count_chars(char *filename) {
    int chars = 0;
    char buffer[BUFFER_SIZE];

    // Open the file for reading
    fd = open(filename, O_RDONLY);
    if (fd == -1) {
        error("Error opening file");
    }

    // Read from the file and count the number of characters
    while (read(fd, buffer, BUFFER_SIZE) > 0) {
        chars += strlen(buffer);
    }

    // Close the file
    close(fd);

    return chars;
}

// Define the function to count the number of words in a file
int count_words(char *filename, char *delim) {
    int words = 0;
    char buffer[BUFFER_SIZE];
    WordCount *word_counts = NULL;

    // Open the file for reading
    fd = open(filename, O_RDONLY);
    if (fd == -1) {
        error("Error opening file");
    }

    // Read from the file and count the number of words
    while (read(fd, buffer, BUFFER_SIZE) > 0) {
        char *token = strtok(buffer, delim);
        while (token != NULL) {
            WordCount *word_count = malloc(sizeof(WordCount));
            word_count->word = token;
            word_count->count = 1;
            if (word_counts == NULL) {
                word_counts = word_count;
            } else {
                WordCount *current = word_counts;
                while (current->next != NULL) {
                    current = current->next;
                }
                current->next = word_count;
            }
            token = strtok(NULL, delim);
        }
    }

    // Close the file
    close(fd);

    // Count the total number of words
    int total_words = 0;
    WordCount *current = word_counts;
    while (current != NULL) {
        total_words += current->count;
        current = current->next;
    }

    return total_words;
}

// Define the function to write the word counts to a file
void write_word_counts(char *filename, WordCount *word_counts) {
    // Open the output file for writing
    int fd = open(filename, O_WRONLY | O_CREAT | O_TRUNC, 0644);
    if (fd == -1) {
        error("Error opening output file");
    }

    // Write the word counts to the file
    WordCount *current = word_counts;
    while (current != NULL) {
        char buffer[BUFFER_SIZE];
        sprintf(buffer, "%s %d\n", current->word, current->count);
        write(fd, buffer, strlen(buffer));
        current = current->next;
    }

    // Close the output file
    close(fd);
}

// Define the function to handle concurrent processing of files using a thread pool
void process_files(char **filenames, int num_files) {
    pthread_t threads[MAX_THREADS];
    WordCount *word_counts = NULL;

    // Create a thread for each file and store the word counts in an array
    for (int i = 0; i < num_files; i++) {
        char *filename = filenames[i];
        pthread_t thread = malloc(sizeof(pthread_t));
        WordCount *word_count = malloc(sizeof(WordCount));
        word_count->word = filename;
        word_count->count = 0;
        if (word_counts == NULL) {
            word_counts = word_count;
        } else {
            WordCount *current = word_counts;
            while (current->next != NULL) {
                current = current->next;
            }
            current->next = word_count;
        }
        pthread_create(&thread, NULL, process_file, filename);
    }

    // Join the threads and add the word counts to the array
    for (int i = 0; i < num_files; i++) {
        WordCount *word_count = malloc(sizeof(WordCount));
        pthread_join(threads[i], (void **)&word_count);
        if (word_counts == NULL) {
            word_counts = word_count;
        } else {
            WordCount *current = word_counts;
            while (current->next != NULL) {
                current = current->next;
            }
            current->next = word_count;
        }
    }
}

// Define the function to process a single file using a thread
void *process_file(void *filename) {
    char *filename = (char *)filename;
    WordCount *word_counts = NULL;

    // Count the number of words in the file
    int total_words = count_words(filename, WORD_DELIM);

    // Create a word count struct for each word and store them in an array
    for (int i = 0; i < total_words; i++) {
        WordCount *word_count = malloc(sizeof(WordCount));
        word_count->word = filename;
        word_count->count = 1;
        if (word_counts == NULL) {
            word_counts = word_count;
        } else {
            WordCount *current = word_counts;
            while (current->next != NULL) {
                current = current->next;
            }
            current->next = word_count;
        }
    }

    // Return the word counts array
    return word_counts;
}

int main(int argc, char **argv) {
    int opt;
    char *output_file = NULL;

    // Parse the command-line arguments
    while ((opt = getopt(argc, argv, "hcs:o:")) != -1) {
        switch (opt) {
            case OPT_HELP:
                printf("Usage: %s [options] file...\n", argv[0]);
                printf("Options:\n");
                printf("\t-h\tPrint this help message and exit\n");
                printf("\t--manpage\tPrint detailed manual page information and exit\n");
                printf("\t-c\tCount the total number of characters in the file(s)\n");
                printf("\t-s\tCount the total number of words in the file(s), with support for a custom delimiter specified by -d\n");
                printf("\t-o FILE\tWrite the word count results to this file instead of printing them to stdout\n");
                return 0;
            case OPT_MANPAGE:
