// Define the function to count the total number of characters in a file
void count_chars(char *filename) {
    // Open the file for reading
    FILE *fp = fopen(filename, "r");
    if (fp == NULL) {
        printf("Error: Failed to open file %s\n", filename);
        exit(1);
    }

    // Read the contents of the file into a buffer
    char *buffer = malloc(sizeof(char) * 1024);
    size_t bytes_read = fread(buffer, sizeof(char), 1024, fp);
    if (bytes_read == 0) {
        printf("Error: Failed to read from file %s\n", filename);
        exit(1);
    }

    // Close the file
    fclose(fp);

    // Count the total number of characters in the buffer
    int num_chars = 0;
    for (int i = 0; i < bytes_read; i++) {
        if (buffer[i] != '\n') {
            num_chars++;
        }
    }

    // Print the total number of characters in the file
    printf("Total number of characters in %s: %d\n", filename, num_chars);
}

