        pthread_create(&threads[i], NULL, process_input_file, &td);
    }

    // Wait for all threads to complete
    for (int i = 0; i < td.num_threads; i++) {
        pthread_join(threads[i], NULL);
    }

    // Clean up the thread pool and free the memory
    free(threads);

    return 0;
}
