#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <errno.h>
#include <stdbool.h>

#define MAX_LINE_LENGTH 1024
#define MAX_KEYWORDS 100
#define OUTPUT_FILE "report.txt"

// Struct to store information about a keyword and its occurrences in the log file
typedef struct {
    char *keyword;
    int frequency;
    int line_numbers[MAX_LINE_LENGTH];
} KeywordInfo;

// Function to read a line from a file and return it as a string
char* readLine(int fd) {
    char buffer[MAX_LINE_LENGTH];
    ssize_t bytes_read = read(fd, buffer, MAX_LINE_LENGTH);
    if (bytes_read < 0) {
        perror("Error reading from file");
        exit(1);
    }
    return strdup(buffer);
}

// Function to check if a keyword is present in a line of text
bool containsKeyword(char *line, char *keyword) {
    return strstr(line, keyword) != NULL;
}

// Function to extract keywords from a log file and store them in an array
void extractKeywords(int fd, KeywordInfo keywords[MAX_KEYWORDS]) {
    // Read the first line of the file
    char *line = readLine(fd);

    // Loop through the rest of the lines
    while (true) {
        // Check if the current line contains a keyword
        for (int i = 0; i < MAX_KEYWORDS; i++) {
            if (containsKeyword(line, keywords[i].keyword)) {
                // If it does, increment the frequency of that keyword
                keywords[i].frequency++;
                // Store the line number where the keyword appears
                keywords[i].line_numbers[keywords[i].frequency - 1] = ftell(fd) / sizeof(char);
            }
        }

        // Read the next line of the file
        char *next_line = readLine(fd);

        // If we've reached the end of the file, break out of the loop
        if (strcmp(next_line, "") == 0) {
            break;
        }
    }
}

// Function to generate a summary report for the extracted keywords
void generateReport(KeywordInfo keywords[MAX_KEYWORDS], char *output_file) {
    // Open the output file in write mode
    FILE *report = fopen(output_file, "w");
    if (report == NULL) {
        perror("Error opening output file");
        exit(1);
    }

    // Write a header to the report
    fprintf(report, "Keyword Frequency\tLine Numbers\n");

    // Loop through each keyword and write its information to the report
    for (int i = 0; i < MAX_KEYWORDS; i++) {
        if (keywords[i].frequency > 0) {
            fprintf(report, "%s\t%d\n", keywords[i].keyword, keywords[i].frequency);
            for (int j = 0; j < keywords[i].frequency; j++) {
                fprintf(report, "\t%ld\n", keywords[i].line_numbers[j]);
            }
        }
    }

    // Close the output file
    fclose(report);
}

int main(int argc, char *argv[]) {
    // Check if the user has specified any command line options
    if (argc == 1) {
        printf("Usage: %s [-h] -k <keywords_file> -o <output_file>\n", argv[0]);
        return 1;
    }

    // Parse the command line options
    char *keywords_file = NULL;
    char *output_file = OUTPUT_FILE;
    for (int i = 1; i < argc; i++) {
        if (strcmp(argv[i], "-h") == 0) {
            printf("Usage: %s [-h] -k <keywords_file> -o <output_file>\n", argv[0]);
            return 1;
        } else if (strcmp(argv[i], "-k") == 0 && i + 1 < argc) {
            keywords_file = argv[i + 1];
            i++;
        } else if (strcmp(argv[i], "-o") == 0 && i + 1 < argc) {
            output_file = argv[i + 1];
            i++;
        }
    }

    // Check if the user has specified a keywords file and an output file
    if (keywords_file == NULL || output_file == NULL) {
        printf("Usage: %s [-h] -k <keywords_file> -o <output_file>\n", argv[0]);
        return 1;
    }

    // Open the keywords file in read mode
    FILE *keywords = fopen(keywords_file, "r");
    if (keywords == NULL) {
        perror("Error opening keywords file");
        exit(1);
    }

    // Read the keywords from the file and store them in an array
    KeywordInfo keywords[MAX_KEYWORDS];
    for (int i = 0; i < MAX_KEYWORDS; i++) {
        char *keyword = readLine(fileno(keywords));
        if (strcmp(keyword, "") == 0) {
            break;
        }
        keywords[i].keyword = keyword;
    }

    // Close the keywords file
    fclose(keywords);

    // Open each log file specified by the user and extract keywords from it
    for (int i = 1; i < argc - 2; i++) {
        char *log_file = argv[i + 2];
        int fd = open(log_file, O_RDONLY);
        if (fd == -1) {
            perror("Error opening log file");
            exit(1);
        }
        extractKeywords(fd, keywords);
        close(fd);
    }

    // Generate a summary report for the extracted keywords
    generateReport(keywords, output_file);

    return 0;
}']

