void init_network_interface_stats(size_t initial_size, size_t max_interfaces) {
    // Initialize the memory pool with the specified initial size and maximum capacity
    MemoryPool *pool = malloc(sizeof(MemoryPool));
    pool->size = initial_size;
    pool->capacity = max_interfaces;
    pool->memory = calloc(initial_size, sizeof(void*));

