    int find_interface_stat(char *interface_name) {
        for (int i = 0; i < pool->size; i++) {
            if (strcmp(stats[i]->interface_name, interface_name) == 0) {
                return i;
            }
        }
        return -1;
    }
}

// Define the function to free the memory allocated for the dynamic array of network interface statistics
void free_network_interface_stats() {
    pthread_mutex_lock(&mutex);

    // Free the memory allocated for each interface statistic in the dynamic array
