// Define a structure to store the results
typedef struct {
    double sum;
    double product;
} result_t;

// Function to calculate the average of an array of floating-point numbers
double average(const double *numbers, int count) {
    double sum = 0.0;
    for (int i = 0; i < count; i++) {
        sum += numbers[i];
    }
    return sum / count;
}

// Function to fetch a JSON document from a URL and extract numerical values
result_t process_json(const char *url) {
    CURL *curl = curl_easy_init();
    if (curl) {
        CURLcode res;
        struct curl_slist *headers = NULL;
        headers = curl_slist_append(headers, "Accept: application/json");
        curl_easy_setopt(curl, CURLOPT_URL, url);
        curl_easy_setopt(curl, CURLOPT_HTTPHEADER, headers);
        curl_easy_setopt(curl, CURLOPT_FOLLOWLOCATION, 1L);
        curl_easy_setopt(curl, CURLOPT_MAXREDIRS, 50L);
        curl_easy_setopt(curl, CURLOPT_TIMEOUT, 30L);
        curl_easy_setopt(curl, CURLOPT_USERAGENT, "libcurl-agent/1.0");
        res = curl_easy_perform(curl);
        if (res != CURLE_OK) {
            fprintf(stderr, "curl_easy_perform() failed: %s\n", curl_easy_strerror(res));
            return NULL;
        }
        long http_code = 0;
        curl_easy_getinfo(curl, CURLINFO_RESPONSE_CODE, &http_code);
        if (http_code != 200) {
            fprintf(stderr, "HTTP response code: %ld\n", http_code);
            return NULL;
        }
        char *json = curl_easy_strdup(curl);
        curl_slist_free_all(headers);
        curl_easy_cleanup(curl);
        if (!json) {
            fprintf(stderr, "Failed to fetch JSON document\n");
            return NULL;
        }
        // Parse the JSON document and extract numerical values
        result_t result = {0.0, 1.0};
        json_error_t error;
        json_t *root = json_loads(json, 0, &error);
        if (!root) {
            fprintf(stderr, "Failed to parse JSON document: %s\n", error.text);
            return NULL;
        }
        json_t *numbers = json_object_get(root, "numbers");
        if (!json_is_array(numbers)) {
            fprintf(stderr, "Invalid JSON format: missing 'numbers' array\n");
            json_decref(root);
            return NULL;
        }
        int count = json_array_size(numbers);
        for (int i = 0; i < count; i++) {
            json_t *number = json_array_get(numbers, i);
            if (!json_is_number(number)) {
                fprintf(stderr, "Invalid JSON format: non-numeric value in 'numbers' array\n");
                json_decref(root);
                return NULL;
            }
            result.sum += json_number_value(number);
            result.product *= json_number_value(number);
        }
        json_decref(root);
        free(json);
        return result;
    } else {
        fprintf(stderr, "Failed to initialize cURL\n");
        return NULL;
    }
}

// Function to read a list of floating-point numbers from standard input and calculate the average
void calculate_average() {
    double *numbers = malloc(sizeof(double) * 1024);
    int count = 0;
    while (scanf("%lf", &numbers[count]) == 1) {
        count++;
        if (count >= 1024) {
            fprintf(stderr, "Too many numbers\n");
            break;
        }
    }
    double average = average(numbers, count);
    printf("Average: %f\n", average);
    free(numbers);
}

// Function to process an HTTP request containing the URL of a JSON document and calculate the sum and product of numerical values in the document
void process_http_request() {
    char url[1024];
    if (scanf("%s", url) != 1) {
        fprintf(stderr, "Invalid HTTP request\n");
        return;
    }
    result_t result = process_json(url);
    if (!result.sum && !result.product) {
        fprintf(stderr, "Failed to fetch JSON document or parse numerical values\n");
        return;
    }
    printf("Sum: %f\n", result.sum);
    printf("Product: %f\n", result.product);
}

