            fprintf(stderr, "Error: unable to open file %s\n", argv[1]);
            return 1;
        }
        while (fscanf(file, "%f", &numbers[numNumbers]) != EOF) {
            numNumbers++;
        }
        fclose(file);
    }
    results.sum = calculateAverage(numbers, numNumbers);

    // Fetch the JSON document and extract numerical values
    if (strcmp(argv[1], "-") == 0) {
        results.product = fetchJSON("https://example.com/json");
    } else {
        FILE *file = fopen(argv[1], "r");
        if (file == NULL) {
            fprintf(stderr, "Error: unable to open file %s\n", argv[1]);
            return 1;
        }
        results.product = fetchJSON("https://example.com/json");
    }

    // Print the results
    printf("Average: %.2f\n", results.sum);
    printf("Product: %d\n", results.product);

    return 0;
}']

