    // Optimize the function for performance, considering factors such as cache locality and minimizing lock contention in the concurrency model
    if (pool->count > 0) {
        printf("Error: %zu bytes of memory still allocated\n", pool->count * sizeof(SensorReading));
        return -1;
    }
}
