    pthread_t thread; // Thread ID
    int id; // Worker thread ID
    struct config *config; // Configuration for this thread
    semaphore_t sem; // Semaphore to signal when data is available
};

// Define the main program structure
struct program {
    int num_threads; // Number of worker threads
    int num_events; // Number of events processed so far
    struct config *config; // Configuration for the program
    struct event *events; // Array of events to process
    pthread_mutex_t mutex; // Mutex to protect the event array
    semaphore_t sem; // Semaphore to signal when data is available
};

// Function to initialize the worker threads
void init_worker_threads(struct program *program) {
    int i;
    for (i = 0; i < program->num_threads; i++) {
        struct worker_thread *thread = &program->workers[i];
        thread->id = i;
        thread->config = program->config;
        semaphore_init(&thread->sem, 0);
    }
}

// Function to start the worker threads
void start_worker_threads(struct program *program) {
    int i;
    for (i = 0; i < program->num_threads; i++) {
        struct worker_thread *thread = &program->workers[i];
        pthread_create(&thread->thread, NULL, process_events, thread);
    }
}

// Function to stop the worker threads
