    int i;
    for (i = 0; i < program->num_threads; i++) {
        struct worker_thread *thread = &program->workers[i];
        pthread_join(thread->thread, NULL);
    }
}

// Function to process events in a worker thread
void *process_events(void *arg) {
    struct worker_thread *thread = (struct worker_thread *)arg;
    struct program *program = thread->config->program;
    while (1) {
        semaphore_wait(&thread->sem);
        pthread_mutex_lock(&program->mutex);
        // Process events in the event array
        int i;
        for (i = 0; i < program->num_events; i++) {
            struct event *event = &program->events[i];
            if (strcmp(event->type, thread->config->event_types) == 0) {
                // Process the event based on the configuration
                process_event(event);
            }
        }
        pthread_mutex_unlock(&program->mutex);
    }
}

// Function to process an event
