    program.num_threads = 4; // Number of worker threads to use
    program.config = &program->config; // Configuration for the program
    program.events = malloc(sizeof(struct event) * 1000); // Array of events to process
    pthread_mutex_init(&program.mutex, NULL); // Initialize the mutex
