// Custom data structures and functions for managing weather stations
struct WeatherStation {
    int id;
    float windSpeed;
    float precipitation;
    float UVIndex;
};

struct WeatherStationList {
    struct WeatherStation* stations;
    size_t numStations;
};

void initWeatherStationList(struct WeatherStationList* list) {
    list->stations = NULL;
    list->numStations = 0;
}

bool addWeatherStation(struct WeatherStationList* list, struct WeatherStation station) {
    // Check if the station already exists in the list
    for (size_t i = 0; i < list->numStations; i++) {
        if (list->stations[i].id == station.id) {
            return false;
        }
    }

    // Allocate memory for the new station
    struct WeatherStation* newStation = malloc(sizeof(struct WeatherStation));
    if (!newStation) {
        perror("malloc");
        return false;
    }

    // Copy the data from the input station to the new station
    memcpy(newStation, &station, sizeof(struct WeatherStation));

    // Add the new station to the list
    list->stations = realloc(list->stations, (list->numStations + 1) * sizeof(struct WeatherStation));
    if (!list->stations) {
        perror("realloc");
        free(newStation);
        return false;
    }
    list->stations[list->numStations++] = newStation;

    return true;
}

bool updateWeatherStation(struct WeatherStationList* list, struct WeatherStation station) {
    // Check if the station exists in the list
    for (size_t i = 0; i < list->numStations; i++) {
        if (list->stations[i].id == station.id) {
            memcpy(&list->stations[i], &station, sizeof(struct WeatherStation));
            return true;
        }
    }

    // If the station doesn't exist in the list, add it
    return addWeatherStation(list, station);
}

bool deleteWeatherStation(struct WeatherStationList* list, int id) {
    // Find the index of the station to be deleted
    size_t i;
    for (i = 0; i < list->numStations; i++) {
        if (list->stations[i].id == id) {
            break;
        }
    }

    // If the station doesn't exist in the list, return false
    if (i == list->numStations) {
        return false;
    }

    // Remove the station from the list
    struct WeatherStation* temp = malloc(sizeof(struct WeatherStation));
    memcpy(temp, &list->stations[i], sizeof(struct WeatherStation));
    free(list->stations[i]);
    for (size_t j = i; j < list->numStations - 1; j++) {
        list->stations[j] = list->stations[j + 1];
    }
    list->numStations--;

    // Free the memory allocated to the deleted station
    free(temp);

    return true;
}

