// Custom memory pool with automatic resizing to minimize heap fragmentation and optimize performance
struct MemoryPool {
    size_t size; // Current size of the pool
    size_t capacity; // Maximum capacity of the pool
    void** data; // Array of pointers to allocated memory blocks
};

// Initialize a new memory pool with the given capacity
static struct MemoryPool* createMemoryPool(size_t capacity) {
    struct MemoryPool* pool = malloc(sizeof(struct MemoryPool));
    if (!pool) {
        return NULL;
    }
    pool->size = 0;
    pool->capacity = capacity;
    pool->data = calloc(capacity, sizeof(void*));
    if (!pool->data) {
        free(pool);
        return NULL;
    }
    return pool;
}

// Resize the memory pool to the given new capacity
static int resizeMemoryPool(struct MemoryPool* pool, size_t newCapacity) {
    void** newData = realloc(pool->data, newCapacity * sizeof(void*));
    if (!newData) {
        return -1;
    }
    pool->capacity = newCapacity;
    pool->data = newData;
    return 0;
}

// Allocate a new memory block from the pool
static void* allocateMemory(struct MemoryPool* pool, size_t size) {
    if (pool->size + size > pool->capacity) {
        // Resize the pool if it's full
        if (resizeMemoryPool(pool, pool->capacity * 2) < 0) {
            return NULL;
        }
    }
    void* data = malloc(size);
    if (!data) {
        return NULL;
    }
    pool->data[pool->size++] = data;
    return data;
}

// Free a memory block from the pool
static void freeMemory(struct MemoryPool* pool, void* data) {
    for (int i = 0; i < pool->size; i++) {
        if (pool->data[i] == data) {
            free(data);
            memmove(&pool->data[i], &pool->data[i + 1], (pool->size - i - 1) * sizeof(void*));
            pool->size--;
            return;
        }
    }
}

// Custom data structure for network interface statistics and file metadata
struct NetworkInterfaceStats {
    char name[IFNAMSIZ]; // Name of the network interface
    uint64_t bytesSent; // Number of bytes sent over the interface
    uint64_t bytesReceived; // Number of bytes received over the interface
    uint64_t packetsSent; // Number of packets sent over the interface
    uint64_t packetsReceived; // Number of packets received over the interface
    double packetLossPercentage; // Percentage of lost packets
    double throughput; // Throughput in bytes per second
    time_t timestamp; // Timestamp of the last update
};

// Custom data structure for file metadata and directory entries
struct FileMetadata {
    char path[PATH_MAX]; // Path to the file or directory
    uint64_t size; // Size of the file in bytes
    time_t timestamp; // Timestamp of the last modification
};

// Custom data structure for aggregated statistics and caching
struct AggregateStats {
    struct NetworkInterfaceStats* networkInterfaces; // Array of network interface statistics
    int numNetworkInterfaces; // Number of network interfaces
    struct FileMetadata* files; // Array of file metadata
    int numFiles; // Number of files
};

// Initialize a new aggregated statistics structure with the given number of network interfaces and files
static struct AggregateStats* createAggregateStats(int numNetworkInterfaces, int numFiles) {
    struct AggregateStats* stats = malloc(sizeof(struct AggregateStats));
    if (!stats) {
        return NULL;
    }
    stats->networkInterfaces = calloc(numNetworkInterfaces, sizeof(struct NetworkInterfaceStats));
    if (!stats->networkInterfaces) {
        free(stats);
        return NULL;
    }
    stats->numNetworkInterfaces = numNetworkInterfaces;
    stats->files = calloc(numFiles, sizeof(struct FileMetadata));
    if (!stats->files) {
        free(stats->networkInterfaces);
        free(stats);
        return NULL;
    }
    stats->numFiles = numFiles;
    return stats;
}

// Add a new network interface to the aggregated statistics structure
static int addNetworkInterface(struct AggregateStats* stats, const char* name) {
    if (stats->numNetworkInterfaces >= MAX_NETWORK_INTERFACES) {
        return -1;
    }
    strncpy(stats->networkInterfaces[stats->numNetworkInterfaces].name, name, IFNAMSIZ);
    stats->numNetworkInterfaces++;
    return 0;
}

// Add a new file to the aggregated statistics structure
static int addFile(struct AggregateStats* stats, const char* path) {
    if (stats->numFiles >= MAX_FILES) {
        return -1;
    }
    strncpy(stats->files[stats->numFiles].path, path, PATH_MAX);
    stats->numFiles++;
    return 0;
}

// Update the network interface statistics for a given interface
static int updateNetworkInterfaceStats(struct AggregateStats* stats, const char* name, uint64_t bytesSent, uint64_t bytesReceived, uint64_t packetsSent, uint64_t packetsReceived) {
    for (int i = 0; i < stats->numNetworkInterfaces; i++) {
        if (strcmp(stats->networkInterfaces[i].name, name) == 0) {
            stats->networkInterfaces[i].bytesSent += bytesSent;
            stats->networkInterfaces[i].bytesReceived += bytesReceived;
            stats->networkInterfaces[i].packetsSent += packetsSent;
            stats->networkInterfaces[i].packetsReceived += packetsReceived;
            return 0;
        }
    }
    return -1;
}

// Update the file metadata for a given file
static int updateFileMetadata(struct AggregateStats* stats, const char* path, uint64_t size, time_t timestamp) {
    for (int i = 0; i < stats->numFiles; i++) {
        if (strcmp(stats->files[i].path, path) == 0) {
            stats->files[i].size += size;
            stats->files[i].timestamp = timestamp;
            return 0;
        }
    }
    return -1;
}

// Retrieve the network interface statistics for a given interface
static struct NetworkInterfaceStats* getNetworkInterfaceStats(struct AggregateStats* stats, const char* name) {
    for (int i = 0; i < stats->numNetworkInterfaces; i++) {
        if (strcmp(stats->networkInterfaces[i].name, name) == 0) {
            return &stats->networkInterfaces[i];
        }
    }
    return NULL;
}

// Retrieve the file metadata for a given file
static struct FileMetadata* getFileMetadata(struct AggregateStats* stats, const char* path) {
    for (int i = 0; i < stats->numFiles; i++) {
        if (strcmp(stats->files[i].path, path) == 0) {
            return &stats->files[i];
        }
    }
    return NULL;
}

// Free the memory allocated for the aggregated statistics structure
static void freeAggregateStats(struct AggregateStats* stats) {
    free(stats->networkInterfaces);
    free(stats->files);
    free(stats);
}

