using namespace std;

// Custom memory pool with automatic resizing
class MemoryPool {
public:
    MemoryPool(size_t size = 0) : size_(size), capacity_(size) {}

    void* allocate(size_t size) {
        if (size > capacity_) {
            // Resize the memory pool to fit the requested allocation
            resize(size);
        }

        // Allocate memory from the pool
        void* ptr = &memory_[pos_];
        pos_ += size;

        return ptr;
    }

private:
    void resize(size_t new_capacity) {
        if (new_capacity > capacity_) {
            // Reallocate the memory pool to fit the requested size
            vector<char> new_memory(new_capacity);
            memcpy(&new_memory[0], &memory_[0], pos_);
            memory_.swap(new_memory);
            capacity_ = new_capacity;
        }
    }

    size_t size_;       // Current size of the pool
    size_t capacity_;   // Maximum size of the pool
    vector<char> memory_;  // Memory pool for allocations
    size_t pos_ = 0;     // Position in the pool for next allocation
};

