class DynamicArray {
public:
    DynamicArray(size_t initialSize = 1024) : capacity_(initialSize), size_(0) {
        data_.reset(new NetworkInterfaceStats[capacity_]);
    }

    ~DynamicArray() {}

    void add(const NetworkInterfaceStats& stats) {
        std::lock_guard<std::mutex> lock(mutex_);
        if (size_ == capacity_) {
            resize();
        }
        data_[size_++] = stats;
    }

    void update(const NetworkInterfaceStats& stats) {
        std::lock_guard<std::mutex> lock(mutex_);
        for (int i = 0; i < size_; ++i) {
            if (data_[i].name == stats.name) {
                data_[i] = stats;
                return;
            }
        }
    }

    NetworkInterfaceStats get(const string& name) const {
        std::lock_guard<std::mutex> lock(mutex_);
        for (int i = 0; i < size_; ++i) {
            if (data_[i].name == name) {
                return data_[i];
            }
        }
        return NetworkInterfaceStats();
    }

private:
    void resize() {
        capacity_ *= 2;
        auto newData = std::make_unique<NetworkInterfaceStats[]>(capacity_);
        for (int i = 0; i < size_; ++i) {
            newData[i] = data_[i];
        }
        data_.swap(newData);
    }

    size_t capacity_;
    size_t size_;
    std::unique_ptr<NetworkInterfaceStats[]> data_;
    std::mutex mutex_;
};

