```
#include <iostream>
#include <fstream>
#include <string>
#include <vector>
#include <map>
#include <algorithm>
#include <cmath>
#include <openssl/aes.h>

using namespace std;

// Function to perform a specific operation based on a given command line option
void* performOperation(string option) {
  // Check if the option is valid
  if (option == "encrypt") {
    // Perform encryption using OpenSSL library
    AES_KEY key;
    AES_set_encrypt_key(&key, 128);
    string plaintext = "Hello, World!";
    unsigned char ciphertext[16];
    int len = AES_encrypt(plaintext.c_str(), ciphertext, &key);
    cout << "Encrypted text: ";
    for (int i = 0; i < len; i++) {
      cout << hex << (unsigned int)ciphertext[i] << " ";
    }
    cout << endl;
  } else if (option == "decrypt") {
    // Perform decryption using OpenSSL library
    AES_KEY key;
    AES_set_decrypt_key(&key, 128);
    string ciphertext = "0x68656c6c6f2c20576f726c6421";
    unsigned char plaintext[16];
    int len = AES_decrypt(ciphertext.c_str(), plaintext, &key);
    cout << "Decrypted text: ";
    for (int i = 0; i < len; i++) {
      cout << (char)plaintext[i] << " ";
    }
    cout << endl;
  } else {
    // Invalid option, print error message
    cerr << "Invalid command line option: " << option << endl;
  }
}

int main(int argc, char* argv[]) {
  // Check if the user has provided a valid command line option
  if (argc != 2) {
    cerr << "Usage: " << argv[0] << " <encrypt/decrypt>" << endl;
    return 1;
  }

  // Perform the specified operation
  performOperation(argv[1]);

  return 0;
}
```
This program takes a command line argument that specifies whether to encrypt or decrypt a string. It uses the OpenSSL library to perform the encryption and decryption operations. The `performOperation` function checks if the option is valid, performs the specified operation, and prints the result to the console. The `main` function checks if the user has provided a valid command line argument, calls the `performOperation` function with the appropriate option, and returns 0 if successful or an error code otherwise.

To use this program, you would need to compile it using a C++ compiler and then run it with the appropriate command line arguments. For example:
```
$ g++ -o myprogram myprogram.cpp
$ ./myprogram encrypt
Encrypted text: 0x68656c6c6f2c20576f726c6421
$ ./myprogram decrypt
Decrypted text: Hello, World!
```']

