void allocate_memory(int num_offsets, int num_keys, int num_records, int num_timestamps, int num_floats) {
    // Validate that parameters are non-negative integers greater than zero
    if (num_offsets < 0 || num_keys < 0 || num_records < 0 || num_timestamps < 0 || num_floats < 0) {
        printf("Invalid input parameters\n");
        return;
    }

    // Allocate memory for the arrays using standard library functions
    long *offsets = (long *)malloc(num_offsets * sizeof(long));
    int *keys = (int *)malloc(num_keys * sizeof(int));
    Record *records = (Record *)malloc(num_records * sizeof(Record));
    Timestamp *timestamps = (Timestamp *)malloc(num_timestamps * sizeof(Timestamp));
    Float *floats = (Float *)malloc(num_floats * sizeof(Float));

    // Initialize the arrays with random values within a specified range
    srand(time(NULL));
