    AES_IV aes_iv;
    PBKDF2_SHA256(password, strlen(password), salt, salt_length, key_length, &aes_key);
    AES_cbc_encrypt(data, data_length, &aes_key, &aes_iv, iv_length);

    // Free all allocated memory upon normal or error exit
    free(offsets);
    free(keys);
