#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <getopt.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <unistd.h>
#include <errno.h>
#include "logging_framework.h"

// Define constants for command line options
#define OPTION_HELP 'h'
#define OPTION_COMPRESS 'c'
#define OPTION_OUTPUT 'o'
#define OPTION_VERBOSE 'v'

// Define structure to hold file statistics
struct file_stats {
    int lines;
    int words;
    int characters;
};

int main(int argc, char *argv[]) {
    // Initialize variables for command line options and file statistics
    struct file_stats stats = {0};
    int option;
    char *output_file = NULL;
    bool verbose = false;
    bool compress = false;

    // Parse command line options
    while ((option = getopt(argc, argv, "hco:v")) != -1) {
        switch (option) {
            case OPTION_HELP:
                printf("Usage: %s [options] <input file>\n", argv[0]);
                printf("Options:\n");
                printf("\t-h\tDisplay basic usage information\n");
                printf("\t-c\tCompress the output of the line, word, and character counts using a simple run-length encoding algorithm before printing\n");
                printf("\t-o <output file>\tRedirect the output to a specified file instead of the console\n");
                printf("\t-v\tEnable verbose mode, which logs additional details such as the progress of the file reading process and the size of the data being processed at each step\n");
                return 0;
            case OPTION_COMPRESS:
                compress = true;
                break;
            case OPTION_OUTPUT:
                output_file = optarg;
                break;
            case OPTION_VERBOSE:
                verbose = true;
                break;
        }
    }

    // Check if input file is specified and exists
    if (optind >= argc) {
        printf("Error: No input file specified\n");
        return 1;
    } else if (access(argv[optind], R_OK) == -1) {
        printf("Error: Input file does not exist or cannot be read\n");
        return 1;
    }

    // Open input file and initialize logging framework
    int fd = open(argv[optind], O_RDONLY);
    if (fd == -1) {
        printf("Error: Could not open input file for reading\n");
        return 1;
    }
    log_init();

    // Read input file line by line and perform operations
    char buffer[BUFSIZ];
    while (read(fd, buffer, BUFSIZ) > 0) {
        // Increment line count
        stats.lines++;

        // Split buffer into words and increment word count
        char *token = strtok(buffer, " ");
        while (token != NULL) {
            stats.words++;
            token = strtok(NULL, " ");
        }

        // Increment character count
        stats.characters += strlen(buffer);
    }

    // Close input file and log statistics
    close(fd);
    log_info("File read complete");
    log_info("Number of lines: %d", stats.lines);
    log_info("Number of words: %d", stats.words);
    log_info("Number of characters: %d", stats.characters);

    // Compress output if requested and redirect to output file if specified
    char *compressed = NULL;
    if (compress) {
        compressed = compress_output(stats);
    }
    if (output_file != NULL) {
        write_to_file(compressed, output_file);
    } else {
        printf("%s", compressed);
    }

    // Clean up and exit
    free(compressed);
    log_info("Program complete");
    return 0;
}

// Compress the output of the line, word, and character counts using a simple run-length encoding algorithm
char *compress_output(struct file_stats stats) {
    // Calculate total number of characters in output
    int total_chars = stats.lines + stats.words + stats.characters;

    // Allocate memory for compressed output
    char *compressed = malloc(total_chars);
    if (compressed == NULL) {
        printf("Error: Could not allocate memory for compressed output\n");
        return NULL;
    }

    // Compress line count
    int line_count = stats.lines;
    sprintf(compressed, "%d", line_count);

    // Compress word count
    char *word_count = malloc(stats.words + 1);
    if (word_count == NULL) {
        printf("Error: Could not allocate memory for compressed output\n");
        return NULL;
    }
    sprintf(word_count, "%d", stats.words);
    strcat(compressed, word_count);
    free(word_count);

    // Compress character count
    char *char_count = malloc(stats.characters + 1);
    if (char_count == NULL) {
        printf("Error: Could not allocate memory for compressed output\n");
        return NULL;
    }
    sprintf(char_count, "%d", stats.characters);
    strcat(compressed, char_count);
    free(char_count);

    // Return compressed output
    return compressed;
}

// Write compressed output to a specified file
void write_to_file(char *output, char *filename) {
    int fd = open(filename, O_WRONLY | O_CREAT, 0644);
    if (fd == -1) {
        printf("Error: Could not open output file for writing\n");
        return;
    }
    write(fd, output, strlen(output));
    close(fd);
}
