Here is a possible implementation of the C program that processes a large, unstructured log file to extract and summarize key performance indicators (KPIs) based on user-defined criteria:
```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <unistd.h>
#include <pthread.h>

// Define the structure to hold the log event data
typedef struct {
    char *event_type;
    time_t timestamp;
} LogEvent;

// Define the structure to hold the KPIs
typedef struct {
    int num_events;
    double avg_latency;
    double max_latency;
    double min_latency;
} KPIs;

// Function to parse the log file and extract the KPIs
void parseLogFile(char *log_file, char *output_file) {
    // Open the log file for reading
    int fd = open(log_file, O_RDONLY);
    if (fd < 0) {
        perror("Error opening log file");
        exit(1);
    }

    // Create a buffer to read the log events from the file
    char *buffer = malloc(BUFSIZ);
    size_t bytes_read;

    // Initialize the KPIs structure
    KPIs kpis;
    memset(&kpis, 0, sizeof(KPIs));

    // Iterate over the log events in the file
    while ((bytes_read = read(fd, buffer, BUFSIZ)) > 0) {
        // Parse the log event from the buffer
        LogEvent *event = parseLogEvent(buffer);
        if (event == NULL) {
            continue;
        }

        // Update the KPIs based on the event type and timestamp
        switch (event->event_type) {
            case 'A':
                kpis.num_events++;
                break;
            case 'B':
                kpis.avg_latency += event->timestamp - kpis.max_latency;
                kpis.max_latency = MAX(event->timestamp, kpis.max_latency);
                kpis.min_latency = MIN(event->timestamp, kpis.min_latency);
                break;
            default:
                break;
        }
    }

    // Close the log file
    close(fd);

    // Write the KPIs to the output file
    FILE *output = fopen(output_file, "w");
    if (output == NULL) {
        perror("Error opening output file");
        exit(1);
    }
    fprintf(output, "%d\n", kpis.num_events);
    fprintf(output, "%f\n", kpis.avg_latency / kpis.num_events);
    fprintf(output, "%f\n", kpis.max_latency);
    fprintf(output, "%f\n", kpis.min_latency);
    fclose(output);
}

// Function to parse a log event from the buffer
LogEvent *parseLogEvent(char *buffer) {
    // Parse the event type and timestamp from the buffer
    char *event_type = strtok(buffer, " ");
    time_t timestamp = atol(strtok(NULL, " "));

    // Create a new LogEvent structure to hold the parsed data
    LogEvent *event = malloc(sizeof(LogEvent));
    event->event_type = event_type;
    event->timestamp = timestamp;

    return event;
}

// Function to calculate the KPIs for a given log file
void calculateKPIs(char *log_file, char *output_file) {
    // Create a new thread to parse the log file and extract the KPIs
    pthread_t thread;
    pthread_create(&thread, NULL, (void *)parseLogFile, log_file);

    // Wait for the thread to complete
    pthread_join(thread, NULL);

    // Write the KPIs to the output file
    FILE *output = fopen(output_file, "w");
    if (output == NULL) {
        perror("Error opening output file");
        exit(1);
    }
    fprintf(output, "%d\n", kpis.num_events);
    fprintf(output, "%f\n", kpis.avg_latency / kpis.num_events);
    fprintf(output, "%f\n", kpis.max_latency);
    fprintf(output, "%f\n", kpis.min_latency);
    fclose(output);
}

int main(int argc, char *argv[]) {
    // Check the command-line arguments
    if (argc < 3) {
        printf("Usage: %s <log file> <output file>\n", argv[0]);
        return 1;
    }

    // Parse the log file and extract the KPIs
    calculateKPIs(argv[1], argv[2]);

    return 0;
}
```
