public class ConfigurationManager {
    private static final Logger LOGGER = Logger.getLogger(ConfigurationManager.class.getName());

    // Custom memory pool with configurable size and automatic resizing
    private static final ConcurrentHashMap<String, ServiceConfig> CONFIG_MAP = new ConcurrentHashMap<>();
    private static final ReentrantLock MUTEX = new ReentrantLock();

    public static void addServiceConfig(String serviceName, String version, String environment) {
        // Data validation before adding or updating configurations ensures valid service versions, accurate timestamps, and consistent environment identifiers
        if (serviceName == null || version == null || environment == null) {
            throw new IllegalArgumentException("Invalid configuration data");
        }

        MUTEX.lock();
        try {
            // Update or add the service configuration to the map
            ServiceConfig config = CONFIG_MAP.get(serviceName);
            if (config == null) {
                config = new ServiceConfig(serviceName, version, environment);
                CONFIG_MAP.put(serviceName, config);
            } else {
                config.setVersion(version);
                config.setEnvironment(environment);
            }
        } finally {
            MUTEX.unlock();
        }
    }

