// Define the function to parse a large binary file
void parse_file(const char* input_file, const char* output_file, const char* rules, int parallel, int log_level) {
    // Open the input file for reading
    int fd = open(input_file, O_RDONLY);
    if (fd < 0) {
        log(LOG_LEVEL_ERROR, "Failed to open input file %s: %s", input_file, strerror(errno));
        return;
    }

    // Get the size of the input file
    struct stat st;
    if (fstat(fd, &st) < 0) {
        log(LOG_LEVEL_ERROR, "Failed to get size of input file %s: %s", input_file, strerror(errno));
        close(fd);
        return;
    }

    // Allocate memory for the input data
    char* input_data = malloc(st.st_size);
    if (input_data == NULL) {
        log(LOG_LEVEL_ERROR, "Failed to allocate memory for input file %s: %s", input_file, strerror(errno));
        close(fd);
        return;
    }

    // Read the input data from the file
    ssize_t num_read = read(fd, input_data, st.st_size);
    if (num_read < 0) {
        log(LOG_LEVEL_ERROR, "Failed to read input file %s: %s", input_file, strerror(errno));
        free(input_data);
        close(fd);
        return;
    }

    // Close the input file
    close(fd);

    // Apply the rules to the input data
    char* output_data = apply_rules(input_data, rules, parallel);
    if (output_data == NULL) {
        log(LOG_LEVEL_ERROR, "Failed to apply rules to input file %s", input_file);
        free(input_data);
        return;
    }

    // Write the output data to a file
    int fd = open(output_file, O_WRONLY | O_CREAT, 0644);
    if (fd < 0) {
        log(LOG_LEVEL_ERROR, "Failed to create output file %s: %s", output_file, strerror(errno));
        free(input_data);
        free(output_data);
        return;
    }

    // Write the output data to the file
    ssize_t num_written = write(fd, output_data, strlen(output_data));
    if (num_written < 0) {
        log(LOG_LEVEL_ERROR, "Failed to write output file %s: %s", output_file, strerror(errno));
        free(input_data);
        free(output_data);
        close(fd);
        return;
    }

    // Close the output file
    close(fd);

    // Cleanup temporary resources and lock files
    cleanup();
}

