// Define a function to compute the MD5 hash of a string
unsigned char* md5_hash(const unsigned char* input, size_t length) {
    // Use the OpenSSL library to compute the MD5 hash
    unsigned char* output = (unsigned char*)malloc(16);
    if (!output) {
        fprintf(stderr, "Failed to allocate memory for MD5 hash\n");
        return NULL;
    }

    EVP_MD_CTX* ctx = EVP_MD_CTX_new();
    if (!ctx) {
        fprintf(stderr, "Failed to create MD5 context\n");
        free(output);
        return NULL;
    }

    int result = EVP_DigestInit_ex(ctx, EVP_md5(), NULL);
    if (result != 1) {
        fprintf(stderr, "Failed to initialize MD5 digest\n");
        EVP_MD_CTX_free(ctx);
        free(output);
        return NULL;
    }

    result = EVP_DigestUpdate(ctx, input, length);
    if (result != 1) {
        fprintf(stderr, "Failed to update MD5 digest\n");
        EVP_MD_CTX_free(ctx);
        free(output);
        return NULL;
    }

    result = EVP_DigestFinal_ex(ctx, output, NULL);
    if (result != 1) {
        fprintf(stderr, "Failed to finalize MD5 digest\n");
        EVP_MD_CTX_free(ctx);
        free(output);
        return NULL;
    }

    EVP_MD_CTX_free(ctx);
    return output;
}

