// Define the structure for a TIDB_ROW_RECORD
typedef struct {
    int row_id;
    char* column_values;
    time_t timestamp;
} TIDB_ROW_RECORD;

// Define the list of TIDB_ROW_RECORD structures
struct tidb_row_record_list {
    TIDB_ROW_RECORD** records;
    int size;
    int capacity;
};

// Function to initialize and populate a list of TIDB_ROW_RECORD structures
void init_tidb_row_record_list(struct tidb_row_record_list* list) {
    // Initialize the list with an initial capacity of 10 records
    list->records = (TIDB_ROW_RECORD**)malloc(sizeof(TIDB_ROW_RECORD*) * 10);
    list->size = 0;
    list->capacity = 10;
}

// Function to add a new record to the list
void add_tidb_row_record(struct tidb_row_record_list* list, int row_id, char* column_values) {
    // Check if the list is full and needs to be resized
    if (list->size == list->capacity) {
        // Double the capacity of the list
        list->capacity *= 2;
        list->records = (TIDB_ROW_RECORD**)realloc(list->records, sizeof(TIDB_ROW_RECORD*) * list->capacity);
    }

    // Create a new record with the current system time as the timestamp
    TIDB_ROW_RECORD* new_record = (TIDB_ROW_RECORD*)malloc(sizeof(TIDB_ROW_RECORD));
    new_record->row_id = row_id;
    new_record->column_values = column_values;
    new_record->timestamp = time(NULL);

    // Add the new record to the list
    list->records[list->size++] = new_record;
}

// Function to remove an expired or unused record from the list
void remove_tidb_row_record(struct tidb_row_record_list* list, int index) {
