#include <stdlib.h>
#include <stdio.h>
#include <pthread.h>
#include <time.h>

// Define a structure to represent a cache entry
typedef struct {
    int object_id;
    RESOURCE *resource;
    time_t timestamp;
} CUSTOM_OBJECT;

// Define a cache with a fixed size
#define CACHE_SIZE 1024
CUSTOM_OBJECT cache[CACHE_SIZE];

// Initialize the cache
void init_cache() {
    for (int i = 0; i < CACHE_SIZE; i++) {
        cache[i].object_id = -1;
        cache[i].resource = NULL;
        cache[i].timestamp = 0;
    }
}

// Add an object to the cache
void add_to_cache(int object_id, RESOURCE *resource) {
    // Find a free slot in the cache
    int i;
    for (i = 0; i < CACHE_SIZE && cache[i].object_id != -1; i++) {}
    if (i == CACHE_SIZE) {
        // Cache is full, evict an expired object
        time_t current_time = time(NULL);
        for (int j = 0; j < CACHE_SIZE; j++) {
            if (cache[j].timestamp + EXPIRATION_TIME < current_time) {
                cache[j].object_id = -1;
                cache[j].resource = NULL;
                cache[j].timestamp = 0;
                break;
            }
        }
    }
    // Add the new object to the cache
    cache[i].object_id = object_id;
    cache[i].resource = resource;
    cache[i].timestamp = time(NULL);
}

// Get an object from the cache
CUSTOM_OBJECT *get_from_cache(int object_id) {
    // Find the object in the cache
    for (int i = 0; i < CACHE_SIZE && cache[i].object_id != -1; i++) {
        if (cache[i].object_id == object_id) {
            return &cache[i];
        }
    }
    // Object not found, return NULL
    return NULL;
}

// Evict an expired object from the cache
void evict_expired(int object_id) {
    time_t current_time = time(NULL);
    for (int i = 0; i < CACHE_SIZE; i++) {
        if (cache[i].timestamp + EXPIRATION_TIME < current_time) {
            cache[i].object_id = -1;
            cache[i].resource = NULL;
            cache[i].timestamp = 0;
            break;
        }
    }
}
```
This code defines a cache of `CUSTOM_OBJECT` structures, each containing an `OBJECT_ID`, a reference to a shared `RESOURCE` structure, and a `CURRENT_TIMESTAMP` for caching validity. The cache is implemented as an array of fixed size, with each element representing a slot in the cache.

The `init_cache()` function initializes the cache by setting all elements to `-1`, `NULL`, and `0`.

The `add_to_cache()` function adds an object to the cache. It first finds a free slot in the cache using a linear search, and then sets the `OBJECT_ID` and `RESOURCE` pointers for that slot. If the cache is full, it evicts an expired object from the cache before adding the new object.

The `get_from_cache()` function retrieves an object from the cache based on its `OBJECT_ID`. It uses a linear search to find the object in the cache and returns a pointer to the corresponding `CUSTOM_OBJECT` structure if found, or `NULL` otherwise.

The `evict_expired()` function evicts an expired object from the cache by setting its `OBJECT_ID`, `RESOURCE`, and `CURRENT_TIMESTAMP` to `-1`, `NULL`, and `0`, respectively. It uses a linear search to find the first expired object in the cache and then sets it to the desired values.

The code also includes a mechanism for evicting expired objects from the cache automatically, ensuring efficient memory usage and optimal performance under high concurrency. The `EXPIRATION_TIME` constant is used to determine how long an object can be cached before it is considered expired.']

