using namespace std;

struct NetworkInterface {
    string name;
    int index;
    double packetLossPercentage;
    double throughput;
    chrono::time_point<chrono::system_clock> timestamp;
};

struct FileMetadata {
    string path;
    long size;
    chrono::time_point<chrono::system_clock> lastModified;
};

class DynamicArray {
public:
    DynamicArray(int initialSize = 10) : size_(initialSize), capacity_(initialSize) {}

    void add(NetworkInterface networkInterface) {
        std::lock_guard<std::mutex> lock(mutex_);
        if (size_ == capacity_) {
            resize();
        }
        data_.push_back(networkInterface);
        size_++;
    }

    void update(NetworkInterface networkInterface) {
        std::lock_guard<std::mutex> lock(mutex_);
        for (int i = 0; i < size_; i++) {
            if (data_[i].name == networkInterface.name) {
                data_[i] = networkInterface;
                return;
            }
        }
    }

    NetworkInterface get(string name) {
        std::lock_guard<std::mutex> lock(mutex_);
        for (int i = 0; i < size_; i++) {
            if (data_[i].name == name) {
                return data_[i];
            }
        }
        return NetworkInterface();
    }

private:
    void resize() {
        capacity_ *= 2;
        vector<NetworkInterface> newData(capacity_);
        for (int i = 0; i < size_; i++) {
            newData[i] = data_[i];
        }
        data_ = move(newData);
    }

    int size_;
    int capacity_;
    vector<NetworkInterface> data_;
    mutex mutex_;
};

