#include <stdlib.h>
#include <stdio.h>
#include <string.h>
#include <pthread.h>

// Define the structure for network interface statistics
typedef struct NetworkInterfaceStats {
    char *interface_name;
    int packet_loss;
    long throughput;
    double latency;
} NetworkInterfaceStats;

// Define the dynamic array for storing network interface statistics
typedef struct NetworkInterfaceStatsArray {
    NetworkInterfaceStats **stats;
    size_t capacity;
    size_t count;
} NetworkInterfaceStatsArray;

// Initialize a new network interface statistics array with a given initial size
NetworkInterfaceStatsArray *network_interface_stats_array_init(size_t initial_capacity) {
    NetworkInterfaceStatsArray *array = malloc(sizeof(NetworkInterfaceStatsArray));
    if (!array) {
        return NULL;
    }
    array->stats = calloc(initial_capacity, sizeof(NetworkInterfaceStats*));
    if (!array->stats) {
        free(array);
        return NULL;
    }
    array->capacity = initial_capacity;
    array->count = 0;
    return array;
}

// Add a new network interface statistics to the array
int network_interface_stats_array_add(NetworkInterfaceStatsArray *array, const char *interface_name, int packet_loss, long throughput, double latency) {
    if (!array || !interface_name) {
        return -1;
    }
    // Check if the array is full and needs to be resized
    if (array->count == array->capacity) {
        size_t new_capacity = array->capacity * 2;
        NetworkInterfaceStats **new_stats = realloc(array->stats, new_capacity * sizeof(NetworkInterfaceStats*));
        if (!new_stats) {
            return -1;
        }
        array->stats = new_stats;
        array->capacity = new_capacity;
    }
    // Create a new network interface statistics object and add it to the array
    NetworkInterfaceStats *stats = malloc(sizeof(NetworkInterfaceStats));
    if (!stats) {
        return -1;
    }
    stats->interface_name = strdup(interface_name);
    stats->packet_loss = packet_loss;
    stats->throughput = throughput;
    stats->latency = latency;
    array->stats[array->count++] = stats;
    return 0;
}

// Update an existing network interface statistics in the array
int network_interface_stats_array_update(NetworkInterfaceStatsArray *array, const char *interface_name, int packet_loss, long throughput, double latency) {
    if (!array || !interface_name) {
        return -1;
    }
    // Find the index of the interface statistics in the array
    size_t i = 0;
    for (i = 0; i < array->count; i++) {
        if (strcmp(array->stats[i]->interface_name, interface_name) == 0) {
            break;
        }
    }
    // If the interface statistics is not found, return an error
    if (i == array->count) {
        return -1;
    }
    // Update the network interface statistics object in the array
    NetworkInterfaceStats *stats = array->stats[i];
    stats->packet_loss = packet_loss;
    stats->throughput = throughput;
    stats->latency = latency;
    return 0;
}

// Retrieve aggregated statistics for all interfaces in the array
void network_interface_stats_array_get_aggregate(NetworkInterfaceStatsArray *array, int *packet_loss, long *throughput, double *latency) {
    if (!array || !packet_loss || !throughput || !latency) {
        return;
    }
    // Initialize the aggregate statistics to zero
    *packet_loss = 0;
    *throughput = 0;
    *latency = 0.0;
    // Iterate over all interface statistics in the array and update the aggregate statistics
    for (size_t i = 0; i < array->count; i++) {
        NetworkInterfaceStats *stats = array->stats[i];
        *packet_loss += stats->packet_loss;
        *throughput += stats->throughput;
        *latency += stats->latency;
    }
}

// Free the memory allocated for a network interface statistics array
void network_interface_stats_array_free(NetworkInterfaceStatsArray *array) {
    if (!array) {
        return;
    }
    // Free the memory allocated for each network interface statistics object in the array
    for (size_t i = 0; i < array->count; i++) {
        NetworkInterfaceStats *stats = array->stats[i];
        free(stats->interface_name);
        free(stats);
    }
    // Free the memory allocated for the array itself
    free(array->stats);
    free(array);
}
