} NetworkInterfaceStats;

// Define a dynamic array to store the network interface statistics
typedef struct NetworkInterfaceStatsArray {
    NetworkInterfaceStats **stats;
    size_t capacity;
    size_t count;
    pthread_mutex_t mutex;
} NetworkInterfaceStatsArray;

// Initialize the dynamic array with a given capacity
void init_network_interface_stats_array(NetworkInterfaceStatsArray *array, size_t capacity) {
    array->capacity = capacity;
    array->count = 0;
    array->mutex = PTHREAD_MUTEX_INITIALIZER;
}

// Add a new network interface statistics to the dynamic array
void add_network_interface_stats(NetworkInterfaceStatsArray *array, const char *interface_name, int packet_loss, long throughput, double latency) {
    pthread_mutex_lock(&array->mutex);
    if (array->count == array->capacity) {
        // Resize the dynamic array if it's full
        size_t new_capacity = array->capacity * 2;
        NetworkInterfaceStats **new_stats = realloc(array->stats, new_capacity * sizeof(NetworkInterfaceStats));
        if (new_stats == NULL) {
            perror("realloc");
            exit(EXIT_FAILURE);
        }
        array->stats = new_stats;
        array->capacity = new_capacity;
    }
    NetworkInterfaceStats *new_stat = malloc(sizeof(NetworkInterfaceStats));
    if (new_stat == NULL) {
        perror("malloc");
        exit(EXIT_FAILURE);
    }
    new_stat->interface_name = strdup(interface_name);
    new_stat->packet_loss = packet_loss;
    new_stat->throughput = throughput;
    new_stat->latency = latency;
    array->stats[array->count++] = new_stat;
    pthread_mutex_unlock(&array->mutex);
}

// Update an existing network interface statistics in the dynamic array
void update_network_interface_stats(NetworkInterfaceStatsArray *array, const char *interface_name, int packet_loss, long throughput, double latency) {
    pthread_mutex_lock(&array->mutex);
    for (size_t i = 0; i < array->count; i++) {
        if (strcmp(array->stats[i]->interface_name, interface_name) == 0) {
            // Update the existing statistics
            array->stats[i]->packet_loss = packet_loss;
            array->stats[i]->throughput = throughput;
            array->stats[i]->latency = latency;
            break;
        }
    }
    pthread_mutex_unlock(&array->mutex);
}

// Retrieve the aggregated statistics for all interfaces in the dynamic array
void get_network_interface_stats(NetworkInterfaceStatsArray *array, NetworkInterfaceStats **stats) {
    pthread_mutex_lock(&array->mutex);
    size_t count = 0;
    for (size_t i = 0; i < array->count; i++) {
        if (strcmp(array->stats[i]->interface_name, interface_name) == 0) {
            // Increment the counter for each matching interface
            count++;
        }
    }
    *stats = malloc(count * sizeof(NetworkInterfaceStats));
    size_t index = 0;
    for (size_t i = 0; i < array->count; i++) {
        if (strcmp(array->stats[i]->interface_name, interface_name) == 0) {
            // Copy the statistics for each matching interface
            memcpy(&(*stats)[index], array->stats[i], sizeof(NetworkInterfaceStats));
            index++;
        }
    }
    pthread_mutex_unlock(&array->mutex);
}

// Free the memory allocated for the dynamic array
void free_network_interface_stats_array(NetworkInterfaceStatsArray *array) {
    pthread_mutex_destroy(&array->mutex);
    for (size_t i = 0; i < array->count; i++) {
        free(array->stats[i]->interface_name);
        free(array->stats[i]);
    }
    free(array->stats);
}
