#include <stdlib.h>
#include <stdio.h>
#include <pthread.h>
#include <time.h>

// Define the cache structure
typedef struct {
    int object_id;
    RESOURCE *resource;
    time_t timestamp;
} CUSTOM_OBJECT;

// Define the cache
CUSTOM_OBJECT *cache = NULL;
int cache_size = 0;
pthread_mutex_t cache_lock = PTHREAD_MUTEX_INITIALIZER;

// Initialize and populate the cache
void init_cache(int max_size) {
    // Allocate memory for the cache
    cache = (CUSTOM_OBJECT *)malloc(sizeof(CUSTOM_OBJECT) * max_size);
    if (!cache) {
        printf("Error: Failed to allocate memory for cache\n");
        return;
    }

    // Initialize the cache size
    cache_size = 0;

    // Initialize the mutex lock
    pthread_mutex_init(&cache_lock, NULL);
}

// Add an object to the cache
void add_object(int object_id, RESOURCE *resource) {
    // Acquire the mutex lock
    pthread_mutex_lock(&cache_lock);

    // Check if the cache is full
    if (cache_size == max_size) {
        // Evict an expired object from the cache
        evict_object();
    }

    // Add the new object to the cache
    cache[cache_size].object_id = object_id;
    cache[cache_size].resource = resource;
    cache[cache_size].timestamp = time(NULL);
    cache_size++;

    // Release the mutex lock
    pthread_mutex_unlock(&cache_lock);
}

// Query an object from the cache without evicting it
CUSTOM_OBJECT *query_object(int object_id) {
    // Acquire the mutex lock
    pthread_mutex_lock(&cache_lock);

    // Search for the object in the cache
    int i;
    for (i = 0; i < cache_size; i++) {
        if (cache[i].object_id == object_id) {
            break;
        }
    }

    // If the object is found, update its timestamp and return it
    if (i < cache_size) {
        cache[i].timestamp = time(NULL);
        pthread_mutex_unlock(&cache_lock);
        return &cache[i];
    }

    // If the object is not found, release the mutex lock and return NULL
    pthread_mutex_unlock(&cache_lock);
    return NULL;
}

// Evict an expired object from the cache
void evict_object() {
    // Acquire the mutex lock
    pthread_mutex_lock(&cache_lock);

    // Find the oldest object in the cache
    int i, j;
    time_t oldest = 0;
    for (i = 0; i < cache_size; i++) {
        if (cache[i].timestamp < oldest || oldest == 0) {
            oldest = cache[i].timestamp;
            j = i;
        }
    }

    // Evict the expired object from the cache
    free(cache[j].resource);
    cache_size--;
    for (i = j; i < cache_size; i++) {
        cache[i] = cache[i + 1];
    }

    // Release the mutex lock
    pthread_mutex_unlock(&cache_lock);
}

// Log every access event with the current timestamp for performance monitoring purposes
void log_access(int object_id) {
    // Acquire the mutex lock
    pthread_mutex_lock(&cache_lock);

    // Update the timestamp of the accessed object
    int i;
    for (i = 0; i < cache_size; i++) {
        if (cache[i].object_id == object_id) {
            break;
        }
    }
    if (i < cache_size) {
        cache[i].timestamp = time(NULL);
    }

    // Release the mutex lock
    pthread_mutex_unlock(&cache_lock);
}

// Handle resource leaks if the cache is ever full and needs to evict entries
void handle_resource_leak() {
    // Acquire the mutex lock
    pthread_mutex_lock(&cache_lock);

    // Evict expired objects from the cache until there is enough space for a new object
    while (cache_size == max_size) {
        evict_object();
    }

    // Release the mutex lock
    pthread_mutex_unlock(&cache_lock);
}
