// Function to perform a specific cryptographic operation based on a given command line option
void* perform_cryptographic_operation(char* input, char* option) {
    // Check if the input string is null or empty
    if (input == NULL || strlen(input) == 0) {
        return NULL;
    }

    // Check if the command line option is valid
    if (strcmp(option, "encrypt") == 0) {
