        EVP_CIPHER_CTX* ctx = EVP_CIPHER_CTX_new();
        EVP_EncryptInit_ex(ctx, EVP_aes_256_cbc(), NULL, NULL, NULL);
        int len = strlen(input);
        unsigned char* encrypted = (unsigned char*)malloc(len + 16 - (len % 16));
        EVP_EncryptUpdate(ctx, encrypted, &len, (unsigned char*)input, len);
        EVP_EncryptFinal_ex(ctx, encrypted + len, &len);
        EVP_CIPHER_CTX_free(ctx);
        return encrypted;
    } else if (strcmp(option, "decrypt") == 0) {
        // Decrypt the input string using AES-256 decryption
        EVP_CIPHER_CTX* ctx = EVP_CIPHER_CTX_new();
        EVP_DecryptInit_ex(ctx, EVP_aes_256_cbc(), NULL, NULL, NULL);
        int len = strlen(input);
        unsigned char* decrypted = (unsigned char*)malloc(len + 16 - (len % 16));
        EVP_DecryptUpdate(ctx, decrypted, &len, (unsigned char*)input, len);
        EVP_DecryptFinal_ex(ctx, decrypted + len, &len);
        EVP_CIPHER_CTX_free(ctx);
        return decrypted;
    } else {
        // Invalid command line option
        return NULL;
    }
}
