    // Evict the object at the specified index
    struct CUSTOM_OBJECT *object = &cache->objects[index];
    free(object->resource);
    cache->size--;

    // Shift all objects after the evicted object to fill the gap
    for (int i = index; i < cache->size; i++) {
        cache->objects[i] = cache->objects[i + 1];
    }

    // Unlock the mutex
    pthread_mutex_unlock(&cache->mutex);
