// Initialize the cache with a maximum size of 1,000 entries
void init_cache(int max_size) {
    cache = (CUSTOM_OBJECT*)malloc(max_size * sizeof(CUSTOM_OBJECT));
    memset(cache, 0, max_size * sizeof(CUSTOM_OBJECT));
    cache_size = max_size;
}

// Add an object to the cache
void add_object(int object_id, void* resource) {
    pthread_mutex_lock(&cache_lock);
    // Check if the cache is full
    if (cache_size == 0) {
        // Evict an entry from the cache using the eviction policy
        CUSTOM_OBJECT* evicted = evict_object(EVICTION_POLICY);
        // Update the timestamp of the evicted object
        evicted->timestamp = time(NULL);
    }
    // Add the new object to the cache
    cache[cache_size].object_id = object_id;
    cache[cache_size].resource = resource;
    cache[cache_size].timestamp = time(NULL);
    cache_size++;
    pthread_mutex_unlock(&cache_lock);
}

// Get an object from the cache by its ID
