void update_resource(int id, void* resource) {
    pthread_mutex_lock(&cache_lock);
    // Search for the object in the cache
    int i;
    for (i = 0; i < cache_size; i++) {
        if (cache[i].object_id == id) {
            break;
        }
    }
    // If the object is found, update its resource and return it
    if (i < cache_size) {
        cache[i].resource = resource;
        pthread_mutex_unlock(&cache_lock);
        return &cache[i];
    }
    // If the object is not found, create a new object with the updated data and add it to the cache
    else {
        CUSTOM_OBJECT* new_object = (CUSTOM_OBJECT*)malloc(sizeof(CUSTOM_OBJECT));
        new_object->object_id = id;
        new_object->resource = resource;
        new_object->timestamp = time(NULL);
        add_object(new_object->object_id, new_object->resource);
        pthread_mutex_unlock(&cache_lock);
        return new_object;
    }
}

// Delete a specified resource by its identifier and return a new resource with default values upon successful deletion
void delete_resource(int id) {
    pthread_mutex_lock(&cache_lock);
    // Search for the object in the cache
    int i;
    for (i = 0; i < cache_size; i++) {
        if (cache[i].object_id == id) {
            break;
        }
    }
    // If the object is found, remove it from the cache and return a new resource with default values
    if (i < cache_size) {
        CUSTOM_OBJECT* deleted = &cache[i];
        memset(deleted, 0, sizeof(CUSTOM_OBJECT));
        deleted->object_id = -1;
        deleted->resource = NULL;
        deleted->timestamp = time(NULL);
        cache_size--;
        pthread_mutex_unlock(&cache_lock);
        return deleted;
    }
    // If the object is not found, return a new resource with default values
    else {
        CUSTOM_OBJECT* deleted = (CUSTOM_OBJECT*)malloc(sizeof(CUSTOM_OBJECT));
        memset(deleted, 0, sizeof(CUSTOM_OBJECT));
        deleted->object_id = -1;
        deleted->resource = NULL;
        deleted->timestamp = time(NULL);
        pthread_mutex_unlock(&cache_lock);
        return deleted;
