Here is a possible implementation of the caching system:
```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

// Define the cache structure
typedef struct {
    int object_id;
    void* resource;
    time_t timestamp;
} custom_object;

// Define the cache parameters
#define CACHE_SIZE 1000
#define GRACE_PERIOD 30 // seconds
#define EVICTION_POLICY LRU

// Define the cache data structure
custom_object* cache = NULL;
pthread_mutex_t cache_lock = PTHREAD_MUTEX_INITIALIZER;

// Initialize the cache
void init_cache() {
    // Allocate memory for the cache
    cache = (custom_object*)malloc(sizeof(custom_object) * CACHE_SIZE);
    if (!cache) {
        printf("Error: failed to allocate memory for cache\n");
        exit(1);
    }

    // Initialize the cache entries
    for (int i = 0; i < CACHE_SIZE; i++) {
        cache[i].object_id = -1;
        cache[i].resource = NULL;
        cache[i].timestamp = 0;
    }
}

// Add an object to the cache
void add_to_cache(int object_id, void* resource) {
    // Acquire the cache lock
    pthread_mutex_lock(&cache_lock);

    // Find a free slot in the cache
    int i;
    for (i = 0; i < CACHE_SIZE && cache[i].object_id != -1; i++) {}

    // If no free slots found, evict an entry using the eviction policy
    if (i == CACHE_SIZE) {
        switch (EVICTION_POLICY) {
            case LRU:
                evict_lru();
                break;
            case LFU:
                evict_lfu();
                break;
            default:
                evict_random();
                break;
        }
    }

    // Add the new object to the cache
    cache[i].object_id = object_id;
    cache[i].resource = resource;
    cache[i].timestamp = time(NULL);

    // Release the cache lock
    pthread_mutex_unlock(&cache_lock);
}

// Evict an entry from the cache using LRU policy
void evict_lru() {
    int i;
    for (i = 0; i < CACHE_SIZE && cache[i].object_id != -1; i++) {}

    // If no entries found, return
    if (i == CACHE_SIZE) {
        return;
    }

    // Evict the oldest entry
    int oldest = i;
    for (int j = i + 1; j < CACHE_SIZE && cache[j].object_id != -1; j++) {
        if (cache[j].timestamp < cache[oldest].timestamp) {
            oldest = j;
        }
    }

    // Evict the entry and update its timestamp
    cache[oldest].object_id = -1;
    cache[oldest].resource = NULL;
    cache[oldest].timestamp = 0;
}

// Evict an entry from the cache using LFU policy
void evict_lfu() {
    int i;
    for (i = 0; i < CACHE_SIZE && cache[i].object_id != -1; i++) {}

    // If no entries found, return
    if (i == CACHE_SIZE) {
        return;
    }

    // Evict the entry with the lowest frequency
    int least_frequent = i;
    for (int j = i + 1; j < CACHE_SIZE && cache[j].object_id != -1; j++) {
        if (cache[j].timestamp < cache[least_frequent].timestamp) {
            least_frequent = j;
        }
    }

    // Evict the entry and update its timestamp
    cache[least_frequent].object_id = -1;
    cache[least_frequent].resource = NULL;
    cache[least_frequent].timestamp = 0;
}

// Evict an entry from the cache using a random policy
void evict_random() {
    int i;
    for (i = 0; i < CACHE_SIZE && cache[i].object_id != -1; i++) {}

    // If no entries found, return
    if (i == CACHE_SIZE) {
        return;
    }

    // Evict a random entry
    int random = rand() % CACHE_SIZE;
    while (cache[random].object_id == -1) {
        random = rand() % CACHE_SIZE;
    }

    // Evict the entry and update its timestamp
    cache[random].object_id = -1;
    cache[random].resource = NULL;
    cache[random].timestamp = 0;
}

// Query the cache for a specific object ID without evicting it from the cache
custom_object* query_cache(int object_id) {
    // Acquire the cache lock
    pthread_mutex_lock(&cache_lock);

    // Find the entry in the cache
    int i;
    for (i = 0; i < CACHE_SIZE && cache[i].object_id != object_id; i++) {}

    // If no entry found, return NULL
    if (i == CACHE_SIZE) {
        pthread_mutex_unlock(&cache_lock);
        return NULL;
    }

    // Update the timestamp of the entry
    cache[i].timestamp = time(NULL);

    // Release the cache lock
    pthread_mutex_unlock(&cache_lock);

    // Return the entry
    return &cache[i];
}

// Update an existing resource using a unique identifier and a request body containing the updated data
custom_object* update_resource(int object_id, void* resource) {
    // Acquire the cache lock
    pthread_mutex_lock(&cache_lock);

    // Find the entry in the cache
    int i;
    for (i = 0; i < CACHE_SIZE && cache[i].object_id != object_id; i++) {}

    // If no entry found, return NULL
    if (i == CACHE_SIZE) {
        pthread_mutex_unlock(&cache_lock);
        return NULL;
    }

    // Update the resource and update its timestamp
    cache[i].resource = resource;
    cache[i].timestamp = time(NULL);

    // Release the cache lock
    pthread_mutex_unlock(&cache_lock);

    // Return the updated entry
    return &cache[i];
}

// Delete a specified resource by its identifier and returns a new resource with default values upon successful deletion
custom_object* delete_resource(int object_id) {
    // Acquire the cache lock
    pthread_mutex_lock(&cache_lock);

    // Find the entry in the cache
    int i;
    for (i = 0; i < CACHE_SIZE && cache[i].object_id != object_id; i++) {}

    // If no entry found, return NULL
    if (i == CACHE_SIZE) {
        pthread_mutex_unlock(&cache_lock);
        return NULL;
    }

    // Evict the entry from the cache
    cache[i].object_id = -1;
    cache[i].resource = NULL;
    cache[i].timestamp = 0;

    // Release the cache lock
    pthread_mutex_unlock(&cache_lock);

    // Return a new resource with default values
    custom_object* new_resource = (custom_object*)malloc(sizeof(custom_object));
    if (!new_resource) {
        printf("Error: failed to allocate memory for new resource\n");
        exit(1);
    }
    new_resource->object_id = -1;
    new_resource->resource = NULL;
    new_resource->timestamp = 0;
    return new_resource;
}
