#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <errno.h>
#include <stdbool.h>
#include <limits.h>
#include <assert.h>

#define MAX_LINE_LENGTH 1024
#define MAX_KEYWORDS 1024
#define MAX_OUTPUT_FILENAME_LENGTH 256

// Struct to represent a keyword and its context in the log file
typedef struct {
    char *keyword;
    char *context;
} KeywordContext;

// Function to read a line from a file and return it as a string
char *read_line(int fd) {
    char *line = malloc(MAX_LINE_LENGTH);
    int bytes_read = read(fd, line, MAX_LINE_LENGTH - 1);
    if (bytes_read == -1) {
        perror("Error reading from file");
        exit(EXIT_FAILURE);
    }
    line[bytes_read] = '\0';
    return line;
}

// Function to parse a log file and extract keywords and their contexts
void parse_log_file(int fd, char **keywords, int num_keywords, KeywordContext *keyword_contexts) {
    // Read the first line of the file
    char *line = read_line(fd);

    // Loop through each line in the file
    while (line != NULL) {
        // Check if any keywords are present in the current line
        for (int i = 0; i < num_keywords; i++) {
            char *keyword = keywords[i];
            char *context = strstr(line, keyword);
            if (context != NULL) {
                // If a keyword is found, add it to the list of keyword contexts
                KeywordContext new_context = {.keyword = keyword, .context = context};
                keyword_contexts[i] = new_context;
            }
        }

        // Read the next line
        free(line);
        line = read_line(fd);
    }
}

// Function to write a summary report of the extracted keywords and their contexts
void generate_report(KeywordContext *keyword_contexts, int num_keywords, char *output_file) {
    // Open the output file for writing
    FILE *out = fopen(output_file, "w");
    if (out == NULL) {
        perror("Error opening output file");
        exit(EXIT_FAILURE);
    }

    // Write a header to the report
    fprintf(out, "Keyword\tContext\n");

    // Loop through each keyword and write its context to the report
    for (int i = 0; i < num_keywords; i++) {
        KeywordContext context = keyword_contexts[i];
        fprintf(out, "%s\t%s\n", context.keyword, context.context);
    }

    // Close the output file
    fclose(out);
}

int main(int argc, char **argv) {
    // Check for the correct number of command line arguments
    if (argc != 4) {
        printf("Usage: %s -k <keywords_file> -o <output_file>\n", argv[0]);
        exit(EXIT_FAILURE);
    }

    // Parse the command line options
    char *keywords_file = NULL;
    char *output_file = NULL;
    for (int i = 1; i < argc - 1; i++) {
        if (strcmp(argv[i], "-k") == 0) {
            keywords_file = argv[++i];
        } else if (strcmp(argv[i], "-o") == 0) {
            output_file = argv[++i];
        }
    }

    // Check that the required command line options were provided
    if (keywords_file == NULL || output_file == NULL) {
        printf("Error: Missing required command line arguments\n");
        exit(EXIT_FAILURE);
    }

    // Open the keywords file for reading
    FILE *keywords = fopen(keywords_file, "r");
    if (keywords == NULL) {
        perror("Error opening keywords file");
        exit(EXIT_FAILURE);
    }

    // Read the list of keywords from the file
    char *line = malloc(MAX_LINE_LENGTH);
    int num_keywords = 0;
    while (fgets(line, MAX_LINE_LENGTH, keywords) != NULL) {
        if (num_keywords >= MAX_KEYWORDS) {
            printf("Error: Too many keywords in file\n");
            exit(EXIT_FAILURE);
        }
        char *keyword = strtok(line, "\n");
        if (keyword != NULL) {
            num_keywords++;
        }
    }
    free(line);

    // Allocate memory for the keyword contexts
    KeywordContext *keyword_contexts = malloc(num_keywords * sizeof(KeywordContext));
    if (keyword_contexts == NULL) {
        perror("Error allocating memory for keyword contexts");
        exit(EXIT_FAILURE);
    }

    // Reset the file pointer to the beginning of the keywords file
    rewind(keywords);

    // Parse each log file and extract the keywords and their contexts
    while (fgets(line, MAX_LINE_LENGTH, keywords) != NULL) {
        char *log_file = strtok(line, "\n");
        if (log_file != NULL) {
            int fd = open(log_file, O_RDONLY);
            if (fd == -1) {
                perror("Error opening log file");
                exit(EXIT_FAILURE);
            }
            parse_log_file(fd, keywords, num_keywords, keyword_contexts);
            close(fd);
        }
    }

    // Generate the summary report of the extracted keywords and their contexts
    generate_report(keyword_contexts, num_keywords, output_file);

    // Clean up memory
    free(keyword_contexts);
    fclose(keywords);

    return 0;
}']

