// Function to parse command line arguments and set global variables accordingly
void parse_args(int argc, char **argv) {
    // Check for help option
    if (argc == 2 && strcmp(argv[1], "--help") == 0) {
        help = true;
        return;
    }

    // Parse KPI file
    if (argc > 2 && strcmp(argv[1], "-k") == 0) {
        kpi_file_specified = true;
        num_kpis = parse_kpi_file(argv[2]);
    } else {
        fprintf(stderr, "Error: KPI file not specified\n");
        exit(1);
