    // Parse data sources
    if (argc > 3 && strcmp(argv[3], "-d") == 0) {
        data_source_specified = true;
        num_data_sources = parse_data_sources(argc - 4, argv + 4);
    } else {
        fprintf(stderr, "Error: Data sources not specified\n");
        exit(1);
    }
}

// Function to parse the KPI file and store the KPIs in a global array
int parse_kpi_file(char *filename) {
    FILE *fp = fopen(filename, "r");
    if (fp == NULL) {
        fprintf(stderr, "Error: Could not open KPI file %s\n", filename);
        exit(1);
    }

    int num_kpis = 0;
    while (!feof(fp)) {
        char line[BUFFER_SIZE];
        fgets(line, BUFFER_SIZE, fp);
        if (strlen(line) > 0 && line[0] != '#') {
            num_kpis++;
        }
    }

    kpis = malloc(num_kpis * sizeof(KPI));
    rewind(fp);
    int i = 0;
    while (!feof(fp)) {
        char line[BUFFER_SIZE];
        fgets(line, BUFFER_SIZE, fp);
        if (strlen(line) > 0 && line[0] != '#') {
            KPI *kpi = &kpis[i++];
            char *token = strtok(line, " ");
            kpi->name = token;
            token = strtok(NULL, " ");
            kpi->value = atof(token);
        }
    }

    fclose(fp);
    return num_kpis;
}

// Function to parse the data sources and store them in a global array
int parse_data_sources(int argc, char **argv) {
    int i = 0;
    while (i < argc) {
        DataSource *ds = &data_sources[i++];
        ds->name = argv[i++];
        ds->fd = open(ds->name, O_RDONLY);
        if (ds->fd == -1) {
            fprintf(stderr, "Error: Could not open data source %s\n", ds->name);
            exit(1);
        }
    }
    return i;
}

// Function to read data from a file descriptor and store it in a buffer
int read_data(int fd, char *buffer) {
    int bytes_read = read(fd, buffer, BUFFER_SIZE);
    if (bytes_read == -1) {
        fprintf(stderr, "Error: Could not read from data source\n");
        exit(1);
    }
    return bytes_read;
}

// Function to parse the data in a buffer and extract the KPI values
