#include <stdlib.h>
#include <stdio.h>
#include <pthread.h>
#include <time.h>

// Define the structure for the cache entry
typedef struct {
    int OBJECT_ID;
    RESOURCE *resource;
    time_t CURRENT_TIMESTAMP;
} CUSTOM_OBJECT;

// Define the cache data structure
typedef struct {
    CUSTOM_OBJECT **objects;
    int size;
    pthread_mutex_t mutex;
} CACHE;

// Initialize the cache with a given size
void init_cache(CACHE *cache, int size) {
    cache->size = size;
    cache->objects = (CUSTOM_OBJECT **)malloc(sizeof(CUSTOM_OBJECT *) * size);
    pthread_mutex_init(&cache->mutex, NULL);
}

// Add a new object to the cache
void add_object(CACHE *cache, int OBJECT_ID, RESOURCE *resource) {
    CUSTOM_OBJECT *new_object = (CUSTOM_OBJECT *)malloc(sizeof(CUSTOM_OBJECT));
    new_object->OBJECT_ID = OBJECT_ID;
    new_object->resource = resource;
    new_object->CURRENT_TIMESTAMP = time(NULL);

    pthread_mutex_lock(&cache->mutex);
    cache->objects[cache->size++] = new_object;
    pthread_mutex_unlock(&cache->mutex);
}

// Get an object from the cache based on its ID
CUSTOM_OBJECT *get_object(CACHE *cache, int OBJECT_ID) {
    CUSTOM_OBJECT *object = NULL;

    pthread_mutex_lock(&cache->mutex);
    for (int i = 0; i < cache->size; i++) {
        if (cache->objects[i]->OBJECT_ID == OBJECT_ID) {
            object = cache->objects[i];
            break;
        }
    }
    pthread_mutex_unlock(&cache->mutex);

    return object;
}

// Evict expired objects from the cache
void evict_expired(CACHE *cache) {
    time_t current_time = time(NULL);

    pthread_mutex_lock(&cache->mutex);
    for (int i = 0; i < cache->size; i++) {
        if (cache->objects[i]->CURRENT_TIMESTAMP + CACHE_EXPIRATION_TIME <= current_time) {
            free(cache->objects[i]);
            cache->objects[i] = NULL;
        }
    }
    pthread_mutex_unlock(&cache->mutex);
}

// Evict objects based on a given criteria
void evict_criteria(CACHE *cache, int (*criteria)(CUSTOM_OBJECT *)) {
    pthread_mutex_lock(&cache->mutex);
    for (int i = 0; i < cache->size; i++) {
        if (criteria(cache->objects[i])) {
            free(cache->objects[i]);
            cache->objects[i] = NULL;
        }
    }
    pthread_mutex_unlock(&cache->mutex);
}

// Clear the entire cache and reset its state
void clear_cache(CACHE *cache) {
    pthread_mutex_lock(&cache->mutex);
    for (int i = 0; i < cache->size; i++) {
        free(cache->objects[i]);
        cache->objects[i] = NULL;
    }
    cache->size = 0;
    pthread_mutex_unlock(&cache->mutex);
}
