#include <stdlib.h>
#include <stdio.h>
#include <pthread.h>
#include <time.h>

// Define a structure to represent a cache entry
typedef struct {
    int object_id;
    RESOURCE *resource;
    time_t timestamp;
} CUSTOM_OBJECT;

// Define a linked list data structure to store the cache entries
typedef struct node {
    CUSTOM_OBJECT *object;
    struct node *next;
} NODE;

// Define a global variable to keep track of the maximum size of the cache
int max_size = 1000;

// Define a function to initialize and populate the cache
void init_cache(CUSTOM_OBJECT **cache) {
    // Allocate memory for the cache
    *cache = (CUSTOM_OBJECT *)malloc(sizeof(CUSTOM_OBJECT) * max_size);

    // Initialize each entry in the cache with a unique object ID and a reference to a shared RESOURCE structure
    for (int i = 0; i < max_size; i++) {
        (*cache)[i].object_id = i + 1;
        (*cache)[i].resource = &RESOURCE;
        (*cache)[i].timestamp = time(NULL);
    }
}

// Define a function to add an object to the cache
void add_to_cache(CUSTOM_OBJECT *object, CUSTOM_OBJECT **cache) {
    // Check if the cache is full
    if (max_size == (*cache)->count) {
        // If the cache is full, remove the oldest entry and replace it with the new object
        NODE *oldest = (*cache)->head;
        while (oldest->next != NULL && oldest->next->object->timestamp < object->timestamp) {
            oldest = oldest->next;
        }
        if (oldest->next == NULL) {
            // If the new object is older than all other objects in the cache, add it to the end of the list
            NODE *new_node = malloc(sizeof(NODE));
            new_node->object = object;
            new_node->next = NULL;
            (*cache)->tail->next = new_node;
            (*cache)->tail = new_node;
        } else {
            // If the new object is older than some but not all other objects in the cache, remove the oldest entry and replace it with the new object
            NODE *oldest_node = oldest->next;
            oldest->next = oldest_node->next;
            free(oldest_node);
            oldest_node->object = object;
        }
    } else {
        // If the cache is not full, add the new object to the end of the list
        NODE *new_node = malloc(sizeof(NODE));
        new_node->object = object;
        new_node->next = NULL;
        (*cache)->tail->next = new_node;
        (*cache)->tail = new_node;
    }
}

// Define a function to remove an object from the cache
void remove_from_cache(int object_id, CUSTOM_OBJECT **cache) {
    // Find the node containing the object with the specified ID
    NODE *node = (*cache)->head;
    while (node != NULL && node->object->object_id != object_id) {
        node = node->next;
    }

    // If the node is found, remove it from the list and free its memory
    if (node != NULL) {
        NODE *prev = (*cache)->head;
        while (prev->next != node) {
            prev = prev->next;
        }
        prev->next = node->next;
        free(node);
    }
}

// Define a function to query the cache for an object with a specific ID
CUSTOM_OBJECT *query_cache(int object_id, CUSTOM_OBJECT **cache) {
    // Find the node containing the object with the specified ID
    NODE *node = (*cache)->head;
    while (node != NULL && node->object->object_id != object_id) {
        node = node->next;
    }

    // If the node is found, return its object
    if (node != NULL) {
        return node->object;
    } else {
        return NULL;
    }
}

// Define a function to evict expired objects from the cache automatically
void evict_expired(CUSTOM_OBJECT **cache) {
    // Find the oldest entry in the cache
    NODE *oldest = (*cache)->head;
    while (oldest->next != NULL && oldest->next->object->timestamp < time(NULL)) {
        oldest = oldest->next;
    }

    // If an expired object is found, remove it from the list and free its memory
    if (oldest->next != NULL) {
        NODE *expired_node = oldest->next;
        oldest->next = expired_node->next;
        free(expired_node);
    }
}
