import java.util.*;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.locks.ReentrantLock;

public class SessionManager {
    private static final int MIN_HEAP_SIZE = 1000;
    private static final int ARRAY_SIZE = 5;
    private static final int STRING_ARRAY_SIZE = 1000;
    private static final int EVENT_ARRAY_SIZE = 1000;
    private static final int INTEGER_ARRAY_SIZE = 1000;
    private static final int USER_OBJECT_ARRAY_SIZE = 1000;

    // Min-heap for session updates
    private PriorityQueue<SessionUpdate> minHeap;

    // Arrays for storing session data
    private double[] doubleArray;
    private String[] stringArray;
    private Event[] eventArray;
    private int[] integerArray;
    private User[] userObjectArray;

    // ConcurrentHashMap for managing concurrent access to shared resources
    private ConcurrentHashMap<String, Session> sessionMap;

    // ReentrantLock for synchronizing access to the min-heap and arrays
    private ReentrantLock lock;

    public SessionManager() {
        this.minHeap = new PriorityQueue<SessionUpdate>(MIN_HEAP_SIZE);
        this.doubleArray = new double[ARRAY_SIZE];
        this.stringArray = new String[STRING_ARRAY_SIZE];
        this.eventArray = new Event[EVENT_ARRAY_SIZE];
        this.integerArray = new int[INTEGER_ARRAY_SIZE];
        this.userObjectArray = new User[USER_OBJECT_ARRAY_SIZE];
        this.sessionMap = new ConcurrentHashMap<String, Session>();
        this.lock = new ReentrantLock();
    }

    public void addSession(String sessionId) {
        lock.lock();
        try {
            // Add the session to the map and initialize its data structures
            Session session = new Session(sessionId);
            sessionMap.put(sessionId, session);
            doubleArray[sessionId] = 0;
            stringArray[sessionId] = "";
            eventArray[sessionId] = null;
            integerArray[sessionId] = 0;
            userObjectArray[sessionId] = null;
        } finally {
            lock.unlock();
        }
    }

    public void updateSession(String sessionId, double value) {
        lock.lock();
        try {
            // Update the session's data structures with the new value
            SessionUpdate update = new SessionUpdate(sessionId, value);
            minHeap.add(update);
            doubleArray[sessionId] += value;
        } finally {
            lock.unlock();
        }
    }

    public void updateSession(String sessionId, String event) {
        lock.lock();
        try {
            // Update the session's data structures with the new event
            SessionUpdate update = new SessionUpdate(sessionId, event);
            minHeap.add(update);
            stringArray[sessionId] += event;
        } finally {
            lock.unlock();
        }
    }

    public void updateSession(String sessionId, int userId) {
        lock.lock();
        try {
            // Update the session's data structures with the new user ID
            SessionUpdate update = new SessionUpdate(sessionId, userId);
            minHeap.add(update);
            integerArray[sessionId] += userId;
        } finally {
            lock.unlock();
        }
    }

    public void updateSession(String sessionId, User user) {
        lock.lock();
        try {
            // Update the session's data structures with the new user object
            SessionUpdate update = new SessionUpdate(sessionId, user);
            minHeap.add(update);
            userObjectArray[sessionId] = user;
        } finally {
            lock.unlock();
        }
    }

    public void removeSession(String sessionId) {
        lock.lock();
        try {
            // Remove the session from the map and its data structures
            Session session = sessionMap.remove(sessionId);
            doubleArray[sessionId] = 0;
            stringArray[sessionId] = "";
            eventArray[sessionId] = null;
            integerArray[sessionId] = 0;
            userObjectArray[sessionId] = null;
        } finally {
            lock.unlock();
        }
    }

    public double getSessionValue(String sessionId) {
        lock.lock();
        try {
            // Return the value of the session's data structures
            return doubleArray[sessionId];
        } finally {
            lock.unlock();
        }
    }

    public String getSessionEvent(String sessionId) {
        lock.lock();
        try {
            // Return the event of the session's data structures
            return stringArray[sessionId];
        } finally {
            lock.unlock();
        }
    }

    public int getSessionUserId(String sessionId) {
        lock.lock();
        try {
            // Return the user ID of the session's data structures
            return integerArray[sessionId];
        } finally {
            lock.unlock();
        }
    }

    public User getSessionUser(String sessionId) {
        lock.lock();
        try {
            // Return the user object of the session's data structures
            return userObjectArray[sessionId];
        } finally {
            lock.unlock();
        }
    }

    public void clearSessions() {
        lock.lock();
        try {
            // Clear all sessions and their data structures
            sessionMap.clear();
            doubleArray = new double[ARRAY_SIZE];
            stringArray = new String[STRING_ARRAY_SIZE];
            eventArray = new Event[EVENT_ARRAY_SIZE];
            integerArray = new int[INTEGER_ARRAY_SIZE];
            userObjectArray = new User[USER_OBJECT_ARRAY_SIZE];
        } finally {
            lock.unlock();
        }
    }
}
