    // Check if the user has specified multiple search criteria
    if (search_criteria[OPT_S1].term != NULL && search_criteria[OPT_MATCH1].term != NULL) {
        for (i = 0; i < argc - 1; i++) {
            char *filename = argv[i + 1];
            search_files(filename, search_criteria);
        }
    } else {
        // Check if the user has specified a custom delimiter for splitting lines into tokens
        if (search_criteria[OPT_D].term != NULL) {
            regex_t reg;
            char *delimiter = search_criteria[OPT_D].term;

            // Compile the regular expression pattern for the delimiter
            if (regcomp(&reg, delimiter, REG_EXTENDED | REG_ICASE) != 0) {
                printf("Error: invalid regular expression pattern\n");
                return 1;
            }

            // Split each line into tokens using the custom delimiter
            for (i = 0; i < argc - 1; i++) {
                char *line = argv[i + 1];
                char *token = strtok(line, delimiter);
                while (token != NULL) {
                    printf("%s\n", token);
                    token = strtok(NULL, delimiter);
                }
            }
        } else {
            // Search for each term in the input file(s)
            for (i = 0; i < argc - 1; i++) {
                char *filename = argv[i + 1];
                search_file(filename, search_criteria[OPT_S1].term, search_criteria[OPT_MATCH1].match);
            }
        }
    }

    // Free the memory allocated for the search criteria array
    free(search_criteria);

    return 0;
}
