    // Iterate through the linked list and write each entry to the file
    struct NetworkEventLogEntry* current = head;
    while (current != NULL) {
        fprintf(file, "%ld %d %s\n", current->timestamp, current->eventType, current->description);
        current = current->next;
    }
}
