```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

// Custom allocator for efficient memory management
void* custom_alloc(size_t size) {
    void* ptr = malloc(size);
    if (!ptr) {
        fprintf(stderr, "Error: Out of memory\n");
        exit(1);
    }
    return ptr;
}

// Linked list node for storing log entries
typedef struct LogEntry {
    time_t timestamp;
    int eventType;
    char* description;
    struct LogEntry* next;
} LogEntry;

// Global variables for the logging system
static LogEntry* head = NULL;
static LogEntry* tail = NULL;
static size_t numEntries = 0;

// Function to add a new log entry to the linked list
void addLogEntry(time_t timestamp, int eventType, char* description) {
    // Allocate memory for the new log entry
    LogEntry* newEntry = custom_alloc(sizeof(LogEntry));
    newEntry->timestamp = timestamp;
    newEntry->eventType = eventType;
    newEntry->description = description;
    newEntry->next = NULL;

    // Add the new log entry to the linked list
    if (head == NULL) {
        head = tail = newEntry;
    } else {
        tail->next = newEntry;
        tail = newEntry;
    }
    numEntries++;
}

// Function to query a specific log entry by its index
LogEntry* getLogEntry(size_t index) {
    if (index >= numEntries) {
        return NULL;
    }
    LogEntry* current = head;
    for (size_t i = 0; i < index; i++) {
        current = current->next;
    }
    return current;
}

// Function to query the number of log entries in the linked list
size_t getNumEntries() {
    return numEntries;
}

// Function to free all memory allocated for the logging system
void freeLoggingSystem() {
    LogEntry* current = head;
    while (current != NULL) {
        LogEntry* next = current->next;
        free(current);
        current = next;
    }
}
