using namespace std;

// Define a custom memory pool class to manage dynamic arrays and data structures
class MemoryPool {
public:
    // Constructor that initializes the memory pool with a configurable size
    MemoryPool(size_t size) : size_(size), used_(0) {}

    // Function to allocate memory from the pool
    void* allocate(size_t size) {
        if (used_ + size > size_) {
            return nullptr;
        }
        void* ptr = &pool_[used_];
        used_ += size;
        return ptr;
    }

    // Function to deallocate memory from the pool
    void deallocate(void* ptr) {
        if (ptr == nullptr) {
            return;
        }
        size_t offset = reinterpret_cast<size_t>(ptr) - reinterpret_cast<size_t>(&pool_[0]);
        used_ -= offset;
    }

private:
    // The memory pool itself
    vector<char> pool_;

    // The size of the memory pool
    size_t size_;

    // The amount of memory currently in use
    size_t used_;
};

