}

// Define a function to add or update data in the memory pool
void addOrUpdateData(Metadata& metadata, MemoryPool& pool) {
    // Allocate memory for the new data structure
    Metadata* newMetadata = reinterpret_cast<Metadata*>(pool.allocate(sizeof(Metadata)));
    if (newMetadata == nullptr) {
        return;
