#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <ctype.h>
#include <unistd.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <pthread.h>
#include <semaphore.h>
#include <errno.h>

#define MAX_KEYWORDS 1024
#define MAX_LINE_LENGTH 1024
#define MAX_PARAGRAPH_LENGTH 512
#define MAX_FILE_SIZE (10 * 1024 * 1024) // 10 MB

// Struct to store keyword information
typedef struct {
    char* keyword;
    int frequency;
    int line_numbers[MAX_LINE_NUMBERS];
} KeywordInfo;

// Struct to store paragraph context
typedef struct {
    char* text;
    int line_number;
} ParagraphContext;

// Global variables
char* keywords_file = NULL;
char* output_file = NULL;
int num_keywords = 0;
KeywordInfo* keyword_info = NULL;
ParagraphContext* paragraph_context = NULL;
sem_t* semaphore = NULL;
pthread_mutex_t* mutex = NULL;

// Function to read keywords from file and store in global variable
void read_keywords(char* filename) {
    FILE* fp = fopen(filename, "r");
    if (fp == NULL) {
        perror("Error opening keywords file");
        exit(1);
    }
    char line[MAX_LINE_LENGTH];
    while (fgets(line, MAX_LINE_LENGTH, fp)) {
        // Remove newline character from end of line
        int len = strlen(line);
        if (line[len - 1] == '\n') {
            line[len - 1] = '\0';
        }
        // Add keyword to global variable
        num_keywords++;
        keyword_info = realloc(keyword_info, sizeof(KeywordInfo) * num_keywords);
        keyword_info[num_keywords - 1].keyword = strdup(line);
        keyword_info[num_keywords - 1].frequency = 0;
    }
    fclose(fp);
}

// Function to process a single log file and extract keywords
void process_log_file(char* filename) {
    FILE* fp = fopen(filename, "r");
    if (fp == NULL) {
        perror("Error opening log file");
        exit(1);
    }
    char line[MAX_LINE_LENGTH];
    int line_number = 0;
    while (fgets(line, MAX_LINE_LENGTH, fp)) {
        // Increment line number
        line_number++;
        // Check for keywords in current line
        for (int i = 0; i < num_keywords; i++) {
            char* keyword = keyword_info[i].keyword;
            int len = strlen(keyword);
            if (strncmp(line, keyword, len) == 0 && isspace(line[len])) {
                // Increment frequency of current keyword
                keyword_info[i].frequency++;
                // Add line number to list of line numbers for current keyword
                int num_lines = keyword_info[i].num_lines;
                keyword_info[i].line_numbers[num_lines] = line_number;
            }
        }
    }
    fclose(fp);
}

// Function to generate report from extracted keywords
void generate_report() {
    // Open output file for writing
    FILE* fp = fopen(output_file, "w");
    if (fp == NULL) {
        perror("Error opening output file");
        exit(1);
    }
    // Write header to output file
    fprintf(fp, "Keyword\tFrequency\tLine Numbers\n");
    for (int i = 0; i < num_keywords; i++) {
        KeywordInfo* keyword_info = &keyword_info[i];
        // Write keyword and frequency to output file
        fprintf(fp, "%s\t%d\t", keyword_info->keyword, keyword_info->frequency);
        // Write line numbers for current keyword to output file
        int num_lines = keyword_info->num_lines;
        for (int j = 0; j < num_lines; j++) {
            fprintf(fp, "%d ", keyword_info->line_numbers[j]);
        }
        // Write newline character to output file
        fprintf(fp, "\n");
    }
    fclose(fp);
}

// Function to handle command line arguments and start processing
void handle_command_line_arguments(int argc, char* argv[]) {
    int c;
    while ((c = getopt(argc, argv, "k:o:")) != -1) {
        switch (c) {
            case 'k':
                keywords_file = optarg;
                break;
            case 'o':
                output_file = optarg;
                break;
            case '?':
                if (optopt == 'k' || optopt == 'o') {
                    fprintf(stderr, "Option -%c requires an argument.\n", optopt);
                } else if (isprint(optopt)) {
                    fprintf(stderr, "Unknown option `-%c'.\n", optopt);
                } else {
                    fprintf(stderr, "Unknown option character `\\x%x'.\n", optopt);
                }
                return;
            default:
                abort();
        }
    }
    // Read keywords from file and store in global variable
    read_keywords(keywords_file);
    // Process each input log file specified by the user
    for (int i = optind; i < argc; i++) {
        process_log_file(argv[i]);
    }
    // Generate report from extracted keywords
    generate_report();
}

// Main function to handle command line arguments and start processing
int main(int argc, char* argv[]) {
    // Initialize semaphore and mutex for thread safety
    semaphore = sem_open("/sem", O_CREAT, 0644, 1);
    if (semaphore == SEM_FAILED) {
        perror("Error creating semaphore");
        exit(1);
    }
    mutex = pthread_mutex_init();
    if (mutex == NULL) {
        perror("Error initializing mutex");
        exit(1);
    }
    // Handle command line arguments and start processing
    handle_command_line_arguments(argc, argv);
    return 0;
}
