// Initialize cache with given capacity
void init_cache(CACHE *cache, size_t capacity) {
    cache->capacity = capacity;
    cache->size = 0;
    cache->objects = (CUSTOM_OBJECT **)malloc(sizeof(CUSTOM_OBJECT *) * capacity);
    pthread_mutex_init(&cache->mutex, NULL);
    pthread_cond_init(&cache->cond, NULL);
}

// Add object to cache
void add_object(CACHE *cache, CUSTOM_OBJECT *object) {
