            object = cache->objects[i];
            break;
        }
    }
    pthread_mutex_unlock(&cache->mutex);
    return object;
}

// Evict oldest object from cache
void evict_object(CACHE *cache, size_t index) {
    if (index >= cache->size) {
        // No objects to evict
        return;
    }
    CUSTOM_OBJECT *object = cache->objects[index];
    free(object);
    memmove(&cache->objects[index], &cache->objects[index + 1], (cache->size - index) * sizeof(CUSTOM_OBJECT *));
    cache->size--;
}

