    pthread_mutex_lock(&cache->mutex);
    if (capacity > cache->capacity) {
        // Increase capacity
        CUSTOM_OBJECT **new_objects = (CUSTOM_OBJECT **)realloc(cache->objects, sizeof(CUSTOM_OBJECT *) * capacity);
        if (new_objects == NULL) {
            pthread_mutex_unlock(&cache->mutex);
            return;
