};

// Define a class to manage the processing of input files
class FileProcessor {
 public:
  // Constructor that takes a list of keywords as input
  FileProcessor(const vector<string>& keywords) : keywords_(keywords) {}

  // Process an input file and extract keywords and their context
  void processFile(ifstream& infile, const string& filename) {
    // Initialize variables for tracking keyword occurrences and context
    map<string, int> keyword_counts;
    set<string> context_set;

    // Read the input file line by line
    string line;
    while (getline(infile, line)) {
      // Tokenize the line into individual words
      vector<string> tokens = tokenize(line);

      // Iterate over each word in the line and check if it is a keyword
      for (const auto& token : tokens) {
        // Check if the word is a keyword
        if (is_keyword(token)) {
          // Increment the count of the keyword
          keyword_counts[token]++;

          // Add the context surrounding the keyword to the set
          add_context(token, tokens);
        }
      }
    }

    // Print the results for each keyword
    for (const auto& [keyword, count] : keyword_counts) {
      cout << "Keyword: " << keyword << ", Count: " << count << endl;
      for (const auto& context : context_set) {
        cout << "\tContext: " << context << endl;
      }
    }
  }

 private:
  // Tokenize a line of text into individual words
  vector<string> tokenize(const string& line) {
    istringstream iss(line);
    vector<string> tokens;
    copy(istream_iterator<string>(iss), istream_iterator<string>(), back_inserter(tokens));
    return tokens;
  }

  // Check if a word is a keyword
  bool is_keyword(const string& word) {
    for (const auto& keyword : keywords_) {
      if (word == keyword) {
        return true;
      }
    }
    return false;
  }

  // Add the context surrounding a keyword to the set
  void add_context(const string& keyword, const vector<string>& tokens) {
    int index = find_keyword_index(keyword, tokens);
    if (index != -1) {
      for (int i = index - 5; i < index + 5; i++) {
        if (i >= 0 && i < tokens.size()) {
          context_set_.insert(tokens[i]);
        }
      }
    }
  }

  // Find the index of a keyword in a vector of strings
  int find_keyword_index(const string& keyword, const vector<string>& tokens) {
    for (int i = 0; i < tokens.size(); i++) {
      if (tokens[i] == keyword) {
        return i;
      }
    }
    return -1;
  }

  // The list of keywords to search for
  vector<string> keywords_;

  // A set to store the context surrounding each keyword
  set<string> context_set_;
};

// Define a class to manage the processing of multiple input files concurrently
class MultiFileProcessor {
 public:
  // Constructor that takes a list of keywords as input
  MultiFileProcessor(const vector<string>& keywords) : keywords_(keywords) {}

  // Process multiple input files concurrently and extract keywords and their context
  void processFiles(const vector<string>& filenames) {
    // Create a thread pool to manage the processing of files
    thread_pool_.resize(filenames.size());

    // Initialize variables for tracking keyword occurrences and context
    map<string, int> keyword_counts;
    set<string> context_set;

    // Iterate over each file and process it concurrently
    for (int i = 0; i < filenames.size(); i++) {
      thread_pool_[i] = std::thread([this, &filenames, i]() {
        ifstream infile(filenames[i]);
        processFile(infile, filenames[i]);
      });
    }

    // Wait for all threads to complete and merge the results
    for (int i = 0; i < thread_pool_.size(); i++) {
      thread_pool_[i].join();
    }

    // Print the results for each keyword
    for (const auto& [keyword, count] : keyword_counts) {
      cout << "Keyword: " << keyword << ", Count: " << count << endl;
      for (const auto& context : context_set) {
        cout << "\tContext: " << context << endl;
      }
    }
  }

 private:
  // The list of keywords to search for
  vector<string> keywords_;

  // A thread pool to manage the processing of files concurrently
  vector<std::thread> thread_pool_;
};

int main(int argc, char* argv[]) {
  // Check if the user has provided any command line arguments
  if (argc == 1) {
    cout << "Usage: " << argv[0] << " -k <keywords_file> -o <output_file>" << endl;
    return 1;
  }

  // Parse the command line arguments and extract the keywords file and output file
  vector<string> filenames;
  string keywords_file, output_file;
  for (int i = 1; i < argc; i++) {
    if (strcmp(argv[i], "-k") == 0) {
      keywords_file = argv[++i];
    } else if (strcmp(argv[i], "-o") == 0) {
      output_file = argv[++i];
    } else {
      filenames.push_back(argv[i]);
    }
  }

  // Check if the user has provided a keywords file and an output file
  if (keywords_file.empty() || output_file.empty()) {
    cout << "Usage: " << argv[0] << " -k <keywords_file> -o <output_file>" << endl;
    return 1;
  }

  // Load the keywords from the file and create a vector of strings
  vector<string> keywords;
  ifstream infile(keywords_file);
  string line;
  while (getline(infile, line)) {
    keywords.push_back(line);
  }

  // Create a FileProcessor object to process the input files
  FileProcessor processor(keywords);

  // Process each file and extract keywords and their context
  for (const auto& filename : filenames) {
    ifstream infile(filename);
    processor.processFile(infile, filename);
  }

  // Create a MultiFileProcessor object to process multiple input files concurrently
  MultiFileProcessor multi_processor(keywords);

  // Process each file and extract keywords and their context
  for (const auto& filename : filenames) {
    ifstream infile(filename);
    multi_processor.processFiles({filename});
  }

  return 0;
}
