    if (!thread_args->is_running) {
        return NULL;
    }
    // Process the input file and extract keywords and contexts
    FILE *file = fopen(input_data->filename, "r");
    if (file == NULL) {
        perror("fopen");
        exit(EXIT_FAILURE);
    }
    char line[MAX_LINE_LEN];
    while (fgets(line, MAX_LINE_LEN, file)) {
        // Extract keywords and contexts from the current line
        for (int i = 0; i < input_data->num_keywords; i++) {
            Keyword *keyword = &input_data->keywords[i];
            if (strstr(line, keyword->keyword)) {
                // Increment the frequency of the current keyword
                keyword->frequency++;
                // Extract context from the current line
                char *context = strstr(line, keyword->keyword);
                int context_len = strlen(context);
                if (input_data->num_contexts < MAX_CONTEXT_LEN) {
                    Context *new_context = &input_data->contexts[input_data->num_contexts++];
                    new_context->filename = input_data->filename;
                    new_context->line_number = line_number(file);
                    new_context->context = malloc(context_len + 1);
                    strncpy(new_context->context, context, context_len);
                    new_context->context[context_len] = '\0';
                } else {
                    printf("Maximum number of contexts reached\n");
                    break;
                }
            }
        }
    }
    fclose(file);
    sem_post(thread_args->semaphore);
    return NULL;
}

void* generate_report(void *args) {
    ThreadArgs *thread_args = (ThreadArgs *) args;
    InputData *input_data = thread_args->input_data;
    sem_wait(thread_args->semaphore);
    if (!thread_args->is_running) {
        return NULL;
    }
    // Generate the report based on the extracted keywords and contexts
    FILE *output_file = fopen(input_data->output_filename, "w");
    if (output_file == NULL) {
        perror("fopen");
        exit(EXIT_FAILURE);
    }
    for (int i = 0; i < input_data->num_keywords; i++) {
        Keyword *keyword = &input_data->keywords[i];
        fprintf(output_file, "%s: %d\n", keyword->keyword, keyword->frequency);
    }
    for (int i = 0; i < input_data->num_contexts; i++) {
        Context *context = &input_data->contexts[i];
        fprintf(output_file, "%s:%d: %s\n", context->filename, context->line_number, context->context);
    }
    fclose(output_file);
    sem_post(thread_args->semaphore);
    return NULL;
}

int main(int argc, char *argv[]) {
    // Parse command line arguments
    if (argc < 2) {
        printf("Usage: %s [-k <keywords_file>] [-o <output_format>] <input_files>\n", argv[0]);
        exit(EXIT_FAILURE);
    }
    char *keywords_filename = DEFAULT_KEYWORDS_FILENAME;
    char *output_format = DEFAULT_OUTPUT_FORMAT;
    int num_input_files = 0;
    for (int i = 1; i < argc - 1; i++) {
        if (!strcmp(argv[i], "-k")) {
            keywords_filename = argv[++i];
        } else if (!strcmp(argv[i], "-o")) {
            output_format = argv[++i];
        } else {
            num_input_files++;
        }
    }
    // Load the list of keywords from a file or command line arguments
    FILE *keywords_file = fopen(keywords_filename, "r");
    if (keywords_file == NULL) {
        perror("fopen");
        exit(EXIT_FAILURE);
    }
    char keyword[MAX_LINE_LEN];
    int num_keywords = 0;
    while (fgets(keyword, MAX_LINE_LEN, keywords_file)) {
        if (num_keywords < MAX_KEYWORDS) {
            Keyword *new_keyword = &input_data->keywords[num_keywords++];
            new_keyword->keyword = malloc(strlen(keyword));
            strcpy(new_keyword->keyword, keyword);
            new_keyword->frequency = 0;
        } else {
            printf("Maximum number of keywords reached\n");
            break;
        }
    }
    fclose(keywords_file);
    // Initialize the input data structure
    InputData *input_data = malloc(sizeof(InputData));
    input_data->num_keywords = num_keywords;
    input_data->output_format = output_format;
    input_data->output_filename = DEFAULT_OUTPUT_FILENAME;
    // Create a semaphore for synchronizing threads
    sem_t *semaphore = malloc(sizeof(sem_t));
    if (sem_init(semaphore, 0, 1) == -1) {
        perror("sem_init");
        exit(EXIT_FAILURE);
    }
    // Create a thread for each input file and start processing
    pthread_t threads[MAX_THREADS];
    int num_threads = 0;
    for (int i = argc - 1; i < argc && num_threads < MAX_THREADS; i++) {
        ThreadArgs *thread_args = malloc(sizeof(ThreadArgs));
        thread_args->thread_id = num_threads++;
        thread_args->semaphore = semaphore;
        thread_args->input_data = input_data;
        thread_args->is_running = true;
        if (pthread_create(&threads[thread_args->thread_id], NULL, process_file, thread_args) != 0) {
            perror("pthread_create");
            exit(EXIT_FAILURE);
        }
    }
    // Wait for all threads to finish processing the input files
    for (int i = 0; i < num_threads; i++) {
        pthread_join(threads[i], NULL);
    }
    // Generate the report based on the extracted keywords and contexts
    ThreadArgs *report_args = malloc(sizeof(ThreadArgs));
    report_args->semaphore = semaphore;
    report_args->input_data = input_data;
    report_args->is_running = true;
    if (pthread_create(&threads[num_threads], NULL, generate_report, report_args) != 0) {
        perror("pthread_create");
        exit(EXIT_FAILURE);
    }
    pthread_join(threads[num_threads], NULL);
    // Clean up resources
    sem_destroy(semaphore);
    free(input_data);
    free(report_args);
    for (int i = 0; i < num_threads + 1; i++) {
        pthread_join(threads[i], NULL);
    }
    return 0;
