// Custom object structure
typedef struct {
    int object_id;
    void* resource;
    time_t timestamp;
} custom_object_t;

// Cache structure
typedef struct {
    custom_object_t** objects;
    size_t capacity;
    size_t size;
    pthread_mutex_t mutex;
} cache_t;

// Initialize and populate the cache
void init_cache(cache_t* cache, size_t capacity) {
    // Allocate memory for the objects array
    cache->objects = (custom_object_t**)malloc(capacity * sizeof(custom_object_t*));
    if (!cache->objects) {
        printf("Error: failed to allocate memory for objects\n");
        exit(1);
    }

    // Initialize the mutex
    pthread_mutex_init(&cache->mutex, NULL);

    // Set the capacity and size of the cache
    cache->capacity = capacity;
    cache->size = 0;
}

// Add an object to the cache
void add_object(cache_t* cache, custom_object_t* object) {
    pthread_mutex_lock(&cache->mutex);

    // Check if the cache is full
    if (cache->size == cache->capacity) {
        // Evict the least recently used object
        evict_object(cache, 0);
    }

    // Add the new object to the end of the array
    cache->objects[cache->size++] = object;

    pthread_mutex_unlock(&cache->mutex);
}

// Evict an object from the cache
void evict_object(cache_t* cache, size_t index) {
    // Check if the index is valid
    if (index >= cache->size) {
        printf("Error: invalid index\n");
        exit(1);
    }

    // Remove the object from the array
    custom_object_t* object = cache->objects[index];
    memmove(&cache->objects[index], &cache->objects[index + 1], (cache->size - index - 1) * sizeof(custom_object_t*));
    cache->size--;

    // Free the memory allocated for the object
    free(object);
}

// Query an object from the cache
custom_object_t* query_object(cache_t* cache, int object_id) {
    pthread_mutex_lock(&cache->mutex);

    // Search for the object in the array
    size_t i;
    for (i = 0; i < cache->size; i++) {
        if (cache->objects[i]->object_id == object_id) {
            break;
        }
    }

    // Check if the object was found
    if (i == cache->size) {
        printf("Error: object not found\n");
        exit(1);
    }

    // Update the timestamp of the object
    cache->objects[i]->timestamp = time(NULL);

    pthread_mutex_unlock(&cache->mutex);

    return cache->objects[i];
}

// Evict expired objects from the cache
void evict_expired_objects(cache_t* cache) {
    // Get the current time
    time_t now = time(NULL);

    pthread_mutex_lock(&cache->mutex);

    // Iterate over the objects in the array
    size_t i;
    for (i = 0; i < cache->size; i++) {
        custom_object_t* object = cache->objects[i];

        // Check if the object is expired
        if (now - object->timestamp > CACHE_EXPIRATION_TIME) {
            evict_object(cache, i);
            i--;
        }
    }

    pthread_mutex_unlock(&cache->mutex);
}

// Persist the cache to disk
void persist_cache(cache_t* cache) {
    // Open a file for writing
    int fd = open("cache.dat", O_WRONLY | O_CREAT, 0644);
    if (fd == -1) {
        printf("Error: failed to open file\n");
        exit(1);
    }

    // Write the cache data to the file
    size_t i;
    for (i = 0; i < cache->size; i++) {
        custom_object_t* object = cache->objects[i];
        write(fd, &object->object_id, sizeof(int));
        write(fd, &object->resource, sizeof(void*));
        write(fd, &object->timestamp, sizeof(time_t));
    }

    // Close the file
    close(fd);
}

// Load the cache from disk
void load_cache(cache_t* cache) {
    // Open a file for reading
    int fd = open("cache.dat", O_RDONLY, 0644);
    if (fd == -1) {
        printf("Error: failed to open file\n");
        exit(1);
    }

    // Read the cache data from the file
    size_t i;
    for (i = 0; i < cache->capacity; i++) {
        custom_object_t* object = malloc(sizeof(custom_object_t));
        read(fd, &object->object_id, sizeof(int));
        read(fd, &object->resource, sizeof(void*));
        read(fd, &object->timestamp, sizeof(time_t));
        add_object(cache, object);
    }

    // Close the file
    close(fd);
}
```
