using namespace std;

// Define a struct to represent a keyword and its context in the log file
struct KeywordContext {
    string keyword;
    int line_number;
    string context;
};

// Define a class to manage the caching of frequently accessed keywords or context snippets
class CacheManager {
public:
    // Constructor initializes the cache with an empty map
    CacheManager() : cache(map<string, vector<KeywordContext>>()) {}

    // Adds a new keyword and its context to the cache if it is not already present
    void add(const string& keyword, const KeywordContext& context) {
        auto it = cache.find(keyword);
        if (it == cache.end()) {
            vector<KeywordContext> contexts;
            contexts.push_back(context);
            cache[keyword] = contexts;
        } else {
            it->second.push_back(context);
        }
    }

    // Returns the cached keyword and its context for a given keyword, or an empty vector if not found
    const vector<KeywordContext>& get(const string& keyword) const {
        auto it = cache.find(keyword);
        return it == cache.end() ? vector<KeywordContext>() : it->second;
    }

private:
    map<string, vector<KeywordContext>> cache;
};

// Define a class to manage the processing of log files and generate a comprehensive summary report
class LogProcessor {
public:
    // Constructor takes a list of keywords as input
    LogProcessor(const vector<string>& keywords) : keywords_(keywords) {}

    // Processes a single log file and returns a map of keyword occurrences
    const map<string, int>& processFile(const string& filename) {
        ifstream infile(filename);
        assert(infile.is_open());

        // Initialize the cache with frequently accessed keywords or context snippets
        CacheManager cache;

        // Iterate through the log file line by line
        int line_number = 0;
        string line;
        while (getline(infile, line)) {
            ++line_number;

            // Check if any of the keywords are present in the current line
            for (const auto& keyword : keywords_) {
                if (line.find(keyword) != string::npos) {
                    KeywordContext context = {keyword, line_number, line};
                    cache.add(keyword, context);
                }
            }
        }

        // Return the cached keyword occurrences for the current log file
        return cache.get();
    }

    // Generates a comprehensive summary report of keyword frequencies and contexts
    void generateReport() {
        // Initialize an empty map to store the keyword frequencies
        map<string, int> frequency_map;

        // Iterate through each log file specified by the user
        for (const auto& filename : filenames_) {
            // Process the current log file and add its keyword occurrences to the frequency map
            const map<string, int>& frequencies = processFile(filename);
            for (const auto& [keyword, count] : frequencies) {
                frequency_map[keyword] += count;
            }
        }

        // Print the comprehensive summary report
        cout << "Keyword Frequencies:" << endl;
        for (const auto& [keyword, count] : frequency_map) {
            cout << keyword << ": " << count << endl;
        }
    }

private:
    vector<string> keywords_; // List of keywords to extract from the log files
    vector<string> filenames_; // List of log file names specified by the user
};

int main(int argc, char** argv) {
    // Check command line arguments for validity and usage instructions
    if (argc < 2 || string(argv[1]) == "--help") {
        cout << "Usage: " << argv[0] << " -k <keywords_file> -o <output_file>" << endl;
        return 0;
    }

    // Initialize the list of keywords and log file names from command line arguments
    vector<string> keywords;
    vector<string> filenames;
    for (int i = 1; i < argc - 1; ++i) {
        if (string(argv[i]) == "-k") {
            keywords = readKeywordsFile(argv[i + 1]);
        } else if (string(argv[i]) == "-o") {
            filenames = readFilenamesFile(argv[i + 1]);
        }
    }

    // Create a LogProcessor instance and generate the comprehensive summary report
    LogProcessor processor(keywords);
    processor.generateReport();

    return 0;
}
