// Define a structure to store network interface statistics
typedef struct NetworkInterfaceStats {
    char *interface_name;
    int packet_loss;
    long throughput;
    double latency;
} NetworkInterfaceStats;

// Define a dynamic array to store the network interface statistics
typedef struct NetworkInterfaceStatsArray {
    NetworkInterfaceStats **stats;
    size_t capacity;
    size_t count;
} NetworkInterfaceStatsArray;

// Initialize a new network interface statistics array with a given initial capacity
NetworkInterfaceStatsArray *network_interface_stats_array_init(size_t initial_capacity) {
    NetworkInterfaceStatsArray *array = malloc(sizeof(NetworkInterfaceStatsArray));
    if (!array) {
        fprintf(stderr, "Error: Failed to allocate memory for network interface statistics array\n");
        return NULL;
    }
    array->stats = calloc(initial_capacity, sizeof(NetworkInterfaceStats *));
    if (!array->stats) {
        fprintf(stderr, "Error: Failed to allocate memory for network interface statistics\n");
        free(array);
        return NULL;
    }
    array->capacity = initial_capacity;
    array->count = 0;
    return array;
}

// Add a new network interface statistics to the array
int network_interface_stats_array_add(NetworkInterfaceStatsArray *array, const char *interface_name, int packet_loss, long throughput, double latency) {
    if (!array || !interface_name) {
        fprintf(stderr, "Error: Invalid arguments\n");
        return -1;
    }
    // Check if the array is full and needs to be resized
    if (array->count == array->capacity) {
        size_t new_capacity = array->capacity * 2;
        NetworkInterfaceStats **new_stats = realloc(array->stats, new_capacity * sizeof(NetworkInterfaceStats *));
        if (!new_stats) {
            fprintf(stderr, "Error: Failed to resize network interface statistics array\n");
            return -1;
        }
        array->stats = new_stats;
        array->capacity = new_capacity;
    }
    // Create a new NetworkInterfaceStats structure and add it to the array
    NetworkInterfaceStats *new_stat = malloc(sizeof(NetworkInterfaceStats));
    if (!new_stat) {
        fprintf(stderr, "Error: Failed to allocate memory for network interface statistics\n");
        return -1;
    }
    new_stat->interface_name = strdup(interface_name);
    new_stat->packet_loss = packet_loss;
    new_stat->throughput = throughput;
    new_stat->latency = latency;
    array->stats[array->count++] = new_stat;
    return 0;
}

// Update an existing network interface statistics in the array
int network_interface_stats_array_update(NetworkInterfaceStatsArray *array, const char *interface_name, int packet_loss, long throughput, double latency) {
    if (!array || !interface_name) {
        fprintf(stderr, "Error: Invalid arguments\n");
        return -1;
    }
    // Find the index of the interface statistics to update
    size_t i = 0;
    for (i = 0; i < array->count; i++) {
        if (strcmp(array->stats[i]->interface_name, interface_name) == 0) {
            break;
        }
    }
    // If the interface statistics was not found, return an error
    if (i == array->count) {
        fprintf(stderr, "Error: Network interface statistics for %s not found\n", interface_name);
        return -1;
    }
    // Update the existing network interface statistics
    array->stats[i]->packet_loss = packet_loss;
    array->stats[i]->throughput = throughput;
    array->stats[i]->latency = latency;
    return 0;
}

// Retrieve the aggregated network interface statistics for all interfaces in the array
NetworkInterfaceStats *network_interface_stats_array_get_aggregate(NetworkInterfaceStatsArray *array) {
    if (!array) {
        fprintf(stderr, "Error: Invalid arguments\n");
        return NULL;
    }
    // Initialize an empty NetworkInterfaceStats structure to store the aggregate statistics
    NetworkInterfaceStats *aggregate = malloc(sizeof(NetworkInterfaceStats));
    if (!aggregate) {
        fprintf(stderr, "Error: Failed to allocate memory for network interface statistics\n");
        return NULL;
    }
    // Initialize the aggregate statistics with default values
    aggregate->interface_name = NULL;
    aggregate->packet_loss = 0;
    aggregate->throughput = 0;
    aggregate->latency = 0.0;
    // Iterate over all network interface statistics in the array and update the aggregate statistics
    for (size_t i = 0; i < array->count; i++) {
        NetworkInterfaceStats *stat = array->stats[i];
        aggregate->packet_loss += stat->packet_loss;
        aggregate->throughput += stat->throughput;
        if (aggregate->latency < stat->latency) {
            aggregate->latency = stat->latency;
        }
    }
    return aggregate;
}

// Free the memory allocated for a network interface statistics array
void network_interface_stats_array_free(NetworkInterfaceStatsArray *array) {
    if (!array) {
        fprintf(stderr, "Error: Invalid arguments\n");
        return;
    }
    // Iterate over all network interface statistics in the array and free their memory
    for (size_t i = 0; i < array->count; i++) {
        NetworkInterfaceStats *stat = array->stats[i];
        free(stat->interface_name);
        free(stat);
    }
    // Free the memory allocated for the network interface statistics array itself
    free(array->stats);
    free(array);
}
