#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <errno.h>
#include <sys/time.h>

// Custom memory pool for dynamic array of NetworkInterfaceStats structures
struct MemoryPool {
    size_t size; // current size of the pool
    size_t capacity; // maximum capacity of the pool
    void** data; // pointer to the start of the pool
};

// NetworkInterfaceStats structure to store detailed metrics for each interface
struct NetworkInterfaceStats {
    char* ifaceName; // name of the network interface
    int packetLoss; // percentage of packets lost
    int throughput; // average throughput in bytes per second
    int latency; // average latency in milliseconds
};

// Function to initialize and manage a dynamic array of NetworkInterfaceStats structures
void initNetworkInterfaceStats(struct MemoryPool* pool, size_t initialSize) {
    if (pool == NULL || initialSize <= 0) {
        return;
    }

    // Initialize the memory pool with the given initial size
    pool->size = initialSize;
    pool->capacity = initialSize;
    pool->data = malloc(initialSize * sizeof(void*));
    if (pool->data == NULL) {
        return;
    }

    // Initialize each element of the array to NULL
    for (size_t i = 0; i < initialSize; i++) {
        pool->data[i] = NULL;
    }
}

// Function to add a new NetworkInterfaceStats structure to the dynamic array
void addNetworkInterfaceStats(struct MemoryPool* pool, const char* ifaceName) {
    if (pool == NULL || ifaceName == NULL) {
        return;
    }

    // Check if there is enough space in the memory pool for a new element
    if (pool->size >= pool->capacity) {
        // Resize the memory pool by 50% to accommodate more elements
        size_t newCapacity = pool->capacity * 1.5;
        void** newData = realloc(pool->data, newCapacity * sizeof(void*));
        if (newData == NULL) {
            return;
        }

        // Update the memory pool with the new data and capacity
        pool->data = newData;
        pool->capacity = newCapacity;
    }

    // Allocate a new NetworkInterfaceStats structure and initialize it
    struct NetworkInterfaceStats* stats = malloc(sizeof(struct NetworkInterfaceStats));
    if (stats == NULL) {
        return;
    }

    // Copy the interface name to the structure
    size_t len = strlen(ifaceName);
    char* ifaceNameCopy = malloc(len + 1);
    if (ifaceNameCopy == NULL) {
        free(stats);
        return;
    }
    memcpy(ifaceNameCopy, ifaceName, len + 1);
    stats->ifaceName = ifaceNameCopy;

    // Set the initial values for packet loss, throughput, and latency
    stats->packetLoss = 0;
    stats->throughput = 0;
    stats->latency = 0;

    // Add the new structure to the memory pool
    pool->data[pool->size++] = stats;
}

// Function to update an existing NetworkInterfaceStats structure in the dynamic array
void updateNetworkInterfaceStats(struct MemoryPool* pool, const char* ifaceName, int packetLoss, int throughput, int latency) {
    if (pool == NULL || ifaceName == NULL) {
        return;
    }

    // Find the structure in the memory pool with the given interface name
    for (size_t i = 0; i < pool->size; i++) {
        struct NetworkInterfaceStats* stats = pool->data[i];
        if (strcmp(stats->ifaceName, ifaceName) == 0) {
            // Update the packet loss, throughput, and latency values
            stats->packetLoss = packetLoss;
            stats->throughput = throughput;
            stats->latency = latency;
            return;
        }
    }
}

// Function to retrieve aggregated statistics for all interfaces in the dynamic array
void getNetworkInterfaceStats(struct MemoryPool* pool, struct NetworkInterfaceStats** stats) {
    if (pool == NULL || stats == NULL) {
        return;
    }

    // Allocate memory for the aggregated statistics structure
    *stats = malloc(sizeof(struct NetworkInterfaceStats));
    if (*stats == NULL) {
        return;
    }

    // Initialize the aggregated statistics structure
    (*stats)->ifaceName = "All Interfaces";
    (*stats)->packetLoss = 0;
    (*stats)->throughput = 0;
    (*stats)->latency = 0;

    // Iterate over all structures in the memory pool and update the aggregated statistics
    for (size_t i = 0; i < pool->size; i++) {
        struct NetworkInterfaceStats* current = pool->data[i];
        (*stats)->packetLoss += current->packetLoss;
        (*stats)->throughput += current->throughput;
        (*stats)->latency += current->latency;
    }
}

// Function to clean up expired or unused records in the dynamic array
void cleanupNetworkInterfaceStats(struct MemoryPool* pool) {
    if (pool == NULL) {
        return;
    }

    // Iterate over all structures in the memory pool and remove any that are expired or unused
    for (size_t i = 0; i < pool->size; i++) {
        struct NetworkInterfaceStats* current = pool->data[i];
        if (current == NULL || current->ifaceName == NULL) {
            // Remove the structure from the memory pool
            memmove(pool->data + i, pool->data + i + 1, sizeof(void*) * (pool->size - i));
            pool->size--;
        }
    }
}

// Function to validate input data before adding or updating interface stats
int validateNetworkInterfaceStats(const char* ifaceName) {
    if (ifaceName == NULL || strlen(ifaceName) > 16) {
        return -EINVAL;
    }

    // Check for invalid characters in the interface name
    for (size_t i = 0; i < strlen(ifaceName); i++) {
        if (!isalnum(ifaceName[i]) && ifaceName[i] != '_') {
            return -EINVAL;
        }
    }

    // Check for duplicate interface names in the memory pool
    for (size_t i = 0; i < pool->size; i++) {
        struct NetworkInterfaceStats* current = pool->data[i];
        if (strcmp(current->ifaceName, ifaceName) == 0) {
            return -EEXIST;
        }
    }

    // No errors found, input data is valid
    return 0;
}

// Function to handle memory allocation failures and invalid inputs gracefully
int handleError(const char* funcName, int errorCode) {
    if (errorCode == -ENOMEM) {
        fprintf(stderr, "Memory allocation failed in %s\n", funcName);
    } else if (errorCode == -EINVAL) {
        fprintf(stderr, "Invalid input data in %s\n", funcName);
    }

    return errorCode;
}

// Function to log changes in network interface statistics
void logNetworkInterfaceStats(struct NetworkInterfaceStats* stats, const char* action) {
    if (stats == NULL || action == NULL) {
        return;
    }

    // Log the change in the network interface statistics
    printf("[%s] %s: %s\n", getCurrentTime(), action, stats->ifaceName);
}

// Function to retrieve the current time as a string
char* getCurrentTime() {
    struct timeval tv;
    gettimeofday(&tv, NULL);
    char* timeStr = malloc(16 * sizeof(char));
    if (timeStr == NULL) {
        return NULL;
    }
    strftime(timeStr, 16, "%Y-%m-%d %H:%M:%S", localtime(&tv.tv_sec));
    return timeStr;
}
