#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <resolv.h>
#include <pthread.h>
#include <stdbool.h>
#include <time.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <errno.h>

#define MAX_CACHE_SIZE 1024
#define CACHE_EXPIRATION_TIME 3600 // seconds
#define RATE_LIMIT 50 // queries per second
#define CONCURRENCY_LIMIT 100 // concurrent queries
#define LOG_FILE "dns_resolver.log"

typedef struct {
    char *hostname;
    int ttl;
    time_t expiration_time;
} cache_entry_t;

cache_entry_t *cache = NULL;
int cache_size = 0;
pthread_mutex_t cache_lock = PTHREAD_MUTEX_INITIALIZER;

void init_cache() {
    cache = (cache_entry_t *)malloc(sizeof(cache_entry_t) * MAX_CACHE_SIZE);
    memset(cache, 0, sizeof(cache_entry_t) * MAX_CACHE_SIZE);
}

void add_to_cache(char *hostname, int ttl) {
    pthread_mutex_lock(&cache_lock);
    cache[cache_size].hostname = hostname;
    cache[cache_size].ttl = ttl;
    cache[cache_size].expiration_time = time(NULL) + CACHE_EXPIRATION_TIME;
    cache_size++;
    pthread_mutex_unlock(&cache_lock);
}

void remove_from_cache(char *hostname) {
    pthread_mutex_lock(&cache_lock);
    for (int i = 0; i < cache_size; i++) {
        if (strcmp(cache[i].hostname, hostname) == 0) {
            memmove(&cache[i], &cache[i + 1], sizeof(cache_entry_t) * (cache_size - i));
            cache_size--;
            break;
        }
    }
    pthread_mutex_unlock(&cache_lock);
}

void update_cache(char *hostname, int ttl) {
    pthread_mutex_lock(&cache_lock);
    for (int i = 0; i < cache_size; i++) {
        if (strcmp(cache[i].hostname, hostname) == 0) {
            cache[i].ttl = ttl;
            cache[i].expiration_time = time(NULL) + CACHE_EXPIRATION_TIME;
            break;
        }
    }
    pthread_mutex_unlock(&cache_lock);
}

void *query_dns(void *args) {
    struct query_args *query = (struct query_args *)args;
    char *hostname = query->hostname;
    int ttl = 0;

    // Check cache first
    pthread_mutex_lock(&cache_lock);
    for (int i = 0; i < cache_size; i++) {
        if (strcmp(cache[i].hostname, hostname) == 0) {
            ttl = cache[i].ttl;
            break;
        }
    }
    pthread_mutex_unlock(&cache_lock);

    // If not in cache, query the name resolution service
    if (ttl == 0) {
        struct addrinfo hints, *res;
        int errcode;

        memset(&hints, 0, sizeof(struct addrinfo));
        hints.ai_family = AF_INET; // IPv4 only for now
        hints.ai_socktype = SOCK_DGRAM;

        if ((errcode = getaddrinfo(hostname, NULL, &hints, &res)) != 0) {
            fprintf(stderr, "getaddrinfo: %s\n", gai_strerror(errcode));
            return NULL;
        }

        // Get the TTL from the first result
        struct addrinfo *result = res;
        ttl = result->ai_ttl;

        freeaddrinfo(res);
    }

    // Add to cache if not already there
    add_to_cache(hostname, ttl);

    return (void *)(intptr_t)ttl;
}

void *query_dns_async(void *args) {
    struct query_args *query = (struct query_args *)args;
    char *hostname = query->hostname;
    int ttl = 0;

    // Check cache first
    pthread_mutex_lock(&cache_lock);
    for (int i = 0; i < cache_size; i++) {
        if (strcmp(cache[i].hostname, hostname) == 0) {
            ttl = cache[i].ttl;
            break;
        }
    }
    pthread_mutex_unlock(&cache_lock);

    // If not in cache, query the name resolution service asynchronously
    if (ttl == 0) {
        struct addrinfo hints, *res;
        int errcode;

        memset(&hints, 0, sizeof(struct addrinfo));
        hints.ai_family = AF_INET; // IPv4 only for now
        hints.ai_socktype = SOCK_DGRAM;

        if ((errcode = getaddrinfo(hostname, NULL, &hints, &res)) != 0) {
            fprintf(stderr, "getaddrinfo: %s\n", gai_strerror(errcode));
            return NULL;
        }

        // Get the TTL from the first result
        struct addrinfo *result = res;
        ttl = result->ai_ttl;

        freeaddrinfo(res);
    }

    // Add to cache if not already there
    add_to_cache(hostname, ttl);

    return (void *)(intptr_t)ttl;
}

int main() {
    init_cache();

    struct query_args args = {"example.com", 0};
    void *result = NULL;

    // Synchronous query
    result = query_dns(&args);
    printf("Synchronous query: %s\n", (char *)(intptr_t)result);

    // Asynchronous query
    pthread_t thread;
    if (pthread_create(&thread, NULL, query_dns_async, &args)) {
        perror("pthread_create");
        return 1;
    }
    pthread_join(thread, &result);
    printf("Asynchronous query: %s\n", (char *)(intptr_t)result);

    // Update cache with new TTL
    update_cache("example.com", 3600);

    return 0;
}
