            printf("\t-i --input\t\tInput file path\n");
            printf("\t-o --output\t\tOutput file path\n");
            printf("\t-c --config\t\tConfiguration file path\n");
            printf("\t-l --loglevel\t\tLogging level (1-5)\n");
            exit(0);
        } else if (!strcmp(argv[i], "-i") || !strcmp(argv[i], "--input")) {
            input_file = argv[++i];
        } else if (!strcmp(argv[i], "-o") || !strcmp(argv[i], "--output")) {
            output_file = argv[++i];
        } else if (!strcmp(argv[i], "-c") || !strcmp(argv[i], "--config")) {
            config_file = argv[++i];
        } else if (!strcmp(argv[i], "-l") || !strcmp(argv[i], "--loglevel")) {
            logging_level = atoi(argv[++i]);
        }
    }
}

// Function to read a file line by line and count the number of lines
void count_lines(char *file_path) {
    // Open the input file in read mode
    int fd = open(file_path, O_RDONLY);
    if (fd == -1) {
        perror("Error opening input file");
        exit(EXIT_FAILURE);
    }

    // Read the input file line by line and count the number of lines
    char buffer[BUFSIZ];
    int num_lines = 0;
    while (read(fd, buffer, BUFSIZ) > 0) {
        if (buffer[strlen(buffer) - 1] == '\n') {
            num_lines++;
        }
    }

    // Close the input file
    close(fd);

    // Print the number of lines to the output file
    printf("Number of lines in %s: %d\n", file_path, num_lines);
}

// Function to filter lines based on a regular expression pattern
void filter_lines(char *file_path) {
    // Open the input file in read mode
    int fd = open(file_path, O_RDONLY);
    if (fd == -1) {
        perror("Error opening input file");
        exit(EXIT_FAILURE);
    }

    // Read the input file line by line and filter lines based on the regular expression pattern
    char buffer[BUFSIZ];
    int num_lines = 0;
    while (read(fd, buffer, BUFSIZ) > 0) {
        if (buffer[strlen(buffer) - 1] == '\n') {
            // Check if the line matches the regular expression pattern
            regex_t regex;
            regcomp(&regex, REGEX_PATTERN, REG_EXTENDED);
            if (regexec(&regex, buffer, 0, NULL, 0) == 0) {
                num_lines++;
            }
        }
    }

    // Close the input file
    close(fd);

    // Print the number of lines to the output file
    printf("Number of lines in %s that match the regular expression pattern: %d\n", file_path, num_lines);
}

// Function to load the configuration file and set default values if necessary
void load_config(char *file_path) {
    // Open the configuration file in read mode
    int fd = open(file_path, O_RDONLY);
    if (fd == -1) {
        perror("Error opening configuration file");
        exit(EXIT_FAILURE);
    }

    // Read the configuration file line by line and set default values if necessary
    char buffer[BUFSIZ];
    while (read(fd, buffer, BUFSIZ) > 0) {
        if (buffer[strlen(buffer) - 1] == '\n') {
            // Check if the line is a comment or an empty line
            if (buffer[0] != '#' && strlen(buffer) > 1) {
                char *token = strtok(buffer, "=");
                if (!strcmp(token, "input_file")) {
                    input_file = token;
                } else if (!strcmp(token, "output_file")) {
                    output_file = token;
                } else if (!strcmp(token, "logging_level")) {
                    logging_level = atoi(token);
                }
            }
        }
    }

    // Close the configuration file
    close(fd);
}

// Function to log errors and performance metrics using an external logging service
void log_errors(char *message) {
    // Open a connection to the logging service
    int fd = open("./log.txt", O_WRONLY | O_CREAT, 0644);
    if (fd == -1) {
        perror("Error opening log file");
        exit(EXIT_FAILURE);
    }

    // Write the error message to the logging service
    write(fd, message, strlen(message));

    // Close the connection to the logging service
    close(fd);
}

// Function to handle large input files efficiently and prevent system crashes
void handle_large_input_files(char *file_path) {
    // Open the input file in read mode
    int fd = open(file_path, O_RDONLY);
    if (fd == -1) {
        perror("Error opening input file");
        exit(EXIT_FAILURE);
    }

    // Read the input file line by line and count the number of lines
    char buffer[BUFSIZ];
    int num_lines = 0;
    while (read(fd, buffer, BUFSIZ) > 0) {
        if (buffer[strlen(buffer) - 1] == '\n') {
            num_lines++;
        }
    }

    // Close the input file
    close(fd);

    // Print the number of lines to the output file
    printf("Number of lines in %s: %d\n", file_path, num_lines);
}

int main(int argc, char *argv[]) {
    // Parse the command line arguments and print usage information if no input file is provided
    parse_args(argc, argv);

    // Load the configuration file and set default values if necessary
    load_config(CONFIG_FILE_PATH);

    // Check if an input file was specified on the command line
    if (input_file != NULL) {
        // Count the number of lines in the input file
        count_lines(input_file);
    } else {
        printf("No input file specified\n");
    }

    // Check if a regular expression pattern was provided on the command line
    if (regex_pattern != NULL) {
        // Filter lines based on the regular expression pattern
        filter_lines(input_file);
    } else {
        printf("No regular expression pattern specified\n");
    }

    // Log errors and performance metrics using an external logging service
    log_errors("Error: No input file specified");

    // Handle large input files efficiently and prevent system crashes
    handle_large_input_files(input_file);

    return 0;
}
