#include <stdlib.h>
#include <string.h>
#include <pthread.h>

typedef struct {
    int id;
    int socket_descriptor;
    time_t last_activity;
} connection_t;

struct connections {
    connection_t* data;
    size_t capacity;
    size_t count;
    pthread_mutex_t mutex;
};

void add_connection(struct connections* connections, int id, int socket_descriptor) {
    // Lock the mutex to prevent concurrent access
    pthread_mutex_lock(&connections->mutex);

    // Check if we need to resize the array
    if (connections->count == connections->capacity) {
        connections->capacity *= 2;
        connections->data = realloc(connections->data, connections->capacity * sizeof(connection_t));
    }

    // Add the new connection to the array
    connections->data[connections->count].id = id;
    connections->data[connections->count].socket_descriptor = socket_descriptor;
    connections->data[connections->count].last_activity = time(NULL);
    connections->count++;

    // Unlock the mutex
    pthread_mutex_unlock(&connections->mutex);
}

void update_connection(struct connections* connections, int id, int socket_descriptor) {
    // Lock the mutex to prevent concurrent access
    pthread_mutex_lock(&connections->mutex);

    // Find the connection in the array
    for (size_t i = 0; i < connections->count; i++) {
        if (connections->data[i].id == id) {
            connections->data[i].socket_descriptor = socket_descriptor;
            connections->data[i].last_activity = time(NULL);
            break;
        }
    }

    // Unlock the mutex
    pthread_mutex_unlock(&connections->mutex);
}

void remove_inactive_connections(struct connections* connections) {
    // Lock the mutex to prevent concurrent access
    pthread_mutex_lock(&connections->mutex);

    // Iterate over the array and remove inactive connections
    for (size_t i = 0; i < connections->count; ) {
        if (time(NULL) - connections->data[i].last_activity > 30) {
            connections->data[i] = connections->data[connections->count - 1];
            connections->count--;
        } else {
            i++;
        }
    }

    // Unlock the mutex
    pthread_mutex_unlock(&connections->mutex);
}
