// Custom memory pool with automatic resizing to minimize heap fragmentation and optimize performance
class MemoryPool {
public:
    MemoryPool(size_t size) : size_(size), capacity_(size), used_(0) {}

    void* allocate(size_t size) {
        if (used_ + size > capacity_) {
            // Automatically resize the pool to accommodate the allocation
            capacity_ = max(capacity_, used_ + size);
            size_t newSize = capacity_ * 2;
            void* newMemory = realloc(memory_, newSize);
            if (newMemory == NULL) {
                throw runtime_error("Failed to allocate memory");
            }
            memory_ = newMemory;
        }

        void* result = memory_ + used_;
        used_ += size;
        return result;
    }

    void deallocate(void* memory) {
        // TODO: Implement deallocation logic
    }

private:
