#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <regex.h>

// Define constants for command line options
#define OPTION_HELP "--help"
#define OPTION_COUNT "--count"
#define OPTION_OUTPUT "--output"
#define OPTION_FILTER "--filter"

// Define default values for configuration settings
#define DEFAULT_OUTPUT_FILE "output.txt"
#define DEFAULT_LOGGING_LEVEL 1

// Define a structure to store command line options and their corresponding values
typedef struct {
    char *option;
    char *value;
} option_t;

// Define a function to parse command line arguments and return an array of option_t structures
option_t* parse_options(int argc, char **argv) {
    // Initialize an array to store the parsed options
    option_t *options = malloc(sizeof(option_t) * (argc - 1));

    // Iterate over the command line arguments and parse each one
    for (int i = 1; i < argc; i++) {
        char *arg = argv[i];
        if (strcmp(arg, OPTION_HELP) == 0 || strcmp(arg, "-h") == 0) {
            options[i - 1].option = OPTION_HELP;
            options[i - 1].value = NULL;
        } else if (strcmp(arg, OPTION_COUNT) == 0 || strcmp(arg, "-c") == 0) {
            options[i - 1].option = OPTION_COUNT;
            options[i - 1].value = NULL;
        } else if (strcmp(arg, OPTION_OUTPUT) == 0 || strcmp(arg, "-o") == 0) {
            options[i - 1].option = OPTION_OUTPUT;
            options[i - 1].value = argv[++i];
        } else if (strcmp(arg, OPTION_FILTER) == 0 || strcmp(arg, "-f") == 0) {
            options[i - 1].option = OPTION_FILTER;
            options[i - 1].value = argv[++i];
        } else {
            // If the argument is not a recognized option, treat it as an input file
            options[i - 1].option = NULL;
            options[i - 1].value = arg;
        }
    }

    return options;
}

// Define a function to read from a file and count the number of lines
int count_lines(FILE *file) {
    int line_count = 0;
    char buffer[BUFSIZ];

    while (fgets(buffer, BUFSIZ, file)) {
        line_count++;
    }

    return line_count;
}

// Define a function to filter lines based on a regular expression pattern
int filter_lines(FILE *file, char *pattern) {
    int line_count = 0;
    char buffer[BUFSIZ];
    regex_t regex;
    regmatch_t match;

    // Compile the regular expression pattern
    if (regcomp(&regex, pattern, REG_EXTENDED | REG_ICASE) != 0) {
        fprintf(stderr, "Error: invalid regular expression pattern\n");
        return -1;
    }

    // Iterate over the lines in the file and count the number of matching lines
    while (fgets(buffer, BUFSIZ, file)) {
        if (regexec(&regex, buffer, 1, &match, 0) == 0) {
            line_count++;
        }
    }

    // Clean up the regular expression pattern
    regfree(&regex);

    return line_count;
}

// Define a function to write output to a file
void write_output(FILE *file, char *output_file) {
    int line_count = 0;
    char buffer[BUFSIZ];

    // Open the output file for writing
    FILE *out_file = fopen(output_file, "w");
    if (out_file == NULL) {
        fprintf(stderr, "Error: unable to open output file\n");
        return;
    }

    // Iterate over the lines in the input files and write them to the output file
    while (fgets(buffer, BUFSIZ, file)) {
        line_count++;
        fprintf(out_file, "%s", buffer);
    }

    // Close the output file
    fclose(out_file);
}

int main(int argc, char **argv) {
    // Parse the command line arguments and store them in an array of option_t structures
    option_t *options = parse_options(argc, argv);

    // Check if the --help or -h option was specified
    if (options[0].option == OPTION_HELP) {
        printf("Usage: %s [OPTIONS]... [INPUT_FILES]...\n", argv[0]);
        printf("\n");
        printf("Options:\n");
        printf("  --help, -h      Display this help message and exit\n");
        printf("  --count, -c     Count the number of lines in each input file\n");
        printf("  --output, -o    Write output to a file (default: %s)\n", DEFAULT_OUTPUT_FILE);
        printf("  --filter, -f    Filter lines based on a regular expression pattern\n");
        return 0;
    }

    // Check if the --count or -c option was specified
    if (options[1].option == OPTION_COUNT) {
        // Iterate over the input files and count the number of lines in each one
        for (int i = 2; i < argc; i++) {
            FILE *file = fopen(argv[i], "r");
            if (file == NULL) {
                fprintf(stderr, "Error: unable to open input file %s\n", argv[i]);
                return 1;
            }
            int line_count = count_lines(file);
            printf("%d lines in %s\n", line_count, argv[i]);
            fclose(file);
        }
    } else {
        // If the --count or -c option was not specified, assume that the user wants to filter lines based on a regular expression pattern
        if (options[2].option == OPTION_FILTER) {
            // Iterate over the input files and filter the lines in each one based on the regular expression pattern
            for (int i = 3; i < argc; i++) {
                FILE *file = fopen(argv[i], "r");
                if (file == NULL) {
                    fprintf(stderr, "Error: unable to open input file %s\n", argv[i]);
                    return 1;
                }
                int line_count = filter_lines(file, options[2].value);
                printf("%d lines in %s match the regular expression pattern\n", line_count, argv[i]);
                fclose(file);
            }
        } else {
            // If no command line options were specified, assume that the user wants to write output to a file
            if (options[3].option == OPTION_OUTPUT) {
                // Iterate over the input files and write the lines in each one to the output file
                for (int i = 4; i < argc; i++) {
                    FILE *file = fopen(argv[i], "r");
                    if (file == NULL) {
                        fprintf(stderr, "Error: unable to open input file %s\n", argv[i]);
                        return 1;
                    }
                    write_output(file, options[3].value);
                    fclose(file);
                }
            } else {
                // If no command line options were specified and no output file was specified, use the default output file name
                FILE *out_file = fopen(DEFAULT_OUTPUT_FILE, "w");
                if (out_file == NULL) {
                    fprintf(stderr, "Error: unable to open output file\n");
                    return 1;
                }
                for (int i = 3; i < argc; i++) {
                    FILE *file = fopen(argv[i], "r");
                    if (file == NULL) {
                        fprintf(stderr, "Error: unable to open input file %s\n", argv[i]);
                        return 1;
                    }
                    write_output(file, out_file);
                    fclose(file);
                }
                fclose(out_file);
            }
        }
    }

    // Clean up the command line options array
    free(options);

    return 0;
}
