        fclose(input_file);
        free(line);
    }

    // Print total number of lines matching regular expression pattern
    if (config.count) {
        printf("Total number of lines matching regular expression pattern: %d\n", line_count);
    }

    // Write output to file if specified
    if (output_file) {
        fprintf(output_file, "Total number of lines matching regular expression pattern: %d\n", line_count);
        fclose(output_file);
    }

    return 0;
}']

