    char* Payload;
} DataPacket;

void init_data_packets(DataPacket** packets, size_t limit) {
    // Initialize the array of data packets
    *packets = (DataPacket*)malloc(sizeof(DataPacket) * limit);
    if (*packets == NULL) {
        fprintf(stderr, "Failed to allocate memory for data packets\n");
        return;
    }

    // Populate the array with random data packets
    size_t i = 0;
    while (i < limit) {
        DataPacket* packet = &(*packets)[i];
        packet->SourceID = rand() % 1000;
        packet->DestinationID = rand() % 1000;
        size_t payload_size = rand() % (1024 * 1024) + 1024; // Random payload size between 1KB and 1MB
        packet->Payload = (char*)malloc(payload_size);
        if (packet->Payload == NULL) {
            fprintf(stderr, "Failed to allocate memory for data packet payload\n");
            break;
        }
        memset(packet->Payload, 0, payload_size);
        i++;
    }
}

void send_data_packets(DataPacket* packets, size_t count) {
    // Send the data packets over HTTP using a Rust HTTP client
    for (size_t i = 0; i < count; i++) {
        DataPacket* packet = &packets[i];
        CURL* curl = curl_easy_init();
        if (curl == NULL) {
            fprintf(stderr, "Failed to initialize HTTP client\n");
            continue;
