        snprintf(url, sizeof(url), "http://example.com/api/data?source=%d&destination=%d", packet->SourceID, packet->DestinationID);
        curl_easy_setopt(curl, CURLOPT_URL, url);
        if (curl_easy_perform(curl) != CURLE_OK) {
            fprintf(stderr, "Failed to send HTTP request\n");
            continue;
        }
        curl_easy_cleanup(curl);
    }
}

int main() {
    // Initialize the array of data packets with a limit of 1000 elements
    DataPacket* packets = NULL;
    init_data_packets(&packets, 1000);

    // Send the data packets over HTTP using a Rust HTTP client
    send_data_packets(packets, 1000);

    // Clean up the memory allocated for the array of data packets
    free(packets);

    return 0;
}
