// Define the structure for the CRC indication PDU
typedef struct {
    RX_UE_INFORMATION_TAG rxUeInformationTag;
    RNTI rnti;
    CRC_INDICATION_REL8_TAG crcIndicationRel8Tag;
} NFAPI_CRC_INDICATION_PDU_T;

// Define the list of CRC indication PDUs
typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *pduList;
    size_t maxSize;
    size_t currentSize;
    pthread_mutex_t mutex;
} NFAPI_CRC_INDICATION_LIST_T;

// Function to create and populate a list of CRC indication PDUs
NFAPI_CRC_INDICATION_LIST_T *createAndPopulateCrcIndicationList(size_t maxSize) {
    // Allocate memory for the list structure
    NFAPI_CRC_INDICATION_LIST_T *list = malloc(sizeof(NFAPI_CRC_INDICATION_LIST_T));
    if (list == NULL) {
        printf("Error: Failed to allocate memory for CRC indication list\n");
        return NULL;
    }

    // Initialize the list structure
    list->pduList = malloc(maxSize * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (list->pduList == NULL) {
        printf("Error: Failed to allocate memory for CRC indication PDUs\n");
        free(list);
        return NULL;
    }
    list->maxSize = maxSize;
    list->currentSize = 0;

    // Initialize the mutex for concurrent access
    pthread_mutex_init(&list->mutex, NULL);

    // Populate the list with random CRC indication PDUs
    for (size_t i = 0; i < maxSize; i++) {
        NFAPI_CRC_INDICATION_PDU_T *pdu = &list->pduList[i];
        pdu->rxUeInformationTag = RX_UE_INFORMATION_TAG_RANDOM();
        pdu->rnti = RNTI_RANDOM();
        pdu->crcIndicationRel8Tag.crCFlag = CRCFLAG_RANDOM();
    }

    // Log the population of the list for debug purposes
    printf("Populated CRC indication list with %zu PDUs\n", maxSize);

    // Validate the integrity of the CRC flags after population
    validateCrcIndicationList(list);

    return list;
}

// Function to add a new CRC indication PDU to the list
bool addCrcIndicationPduToList(NFAPI_CRC_INDICATION_LIST_T *list, NFAPI_CRC_INDICATION_PDU_T *pdu) {
    // Acquire the mutex for concurrent access
    pthread_mutex_lock(&list->mutex);

    // Check if the list is full
    if (list->currentSize == list->maxSize) {
        printf("Error: CRC indication list is full\n");
        pthread_mutex_unlock(&list->mutex);
        return false;
    }

    // Add the new PDU to the list
    list->pduList[list->currentSize++] = *pdu;

    // Release the mutex for concurrent access
    pthread_mutex_unlock(&list->mutex);

    return true;
}

// Function to remove a CRC indication PDU from the list
bool removeCrcIndicationPduFromList(NFAPI_CRC_INDICATION_LIST_T *list, size_t index) {
    // Acquire the mutex for concurrent access
    pthread_mutex_lock(&list->mutex);

    // Check if the list is empty
    if (list->currentSize == 0) {
        printf("Error: CRC indication list is empty\n");
        pthread_mutex_unlock(&list->mutex);
        return false;
    }

    // Remove the PDU from the list
    NFAPI_CRC_INDICATION_PDU_T *pdu = &list->pduList[index];
    memmove(pdu, pdu + 1, (list->currentSize - index - 1) * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    list->currentSize--;

    // Release the mutex for concurrent access
    pthread_mutex_unlock(&list->mutex);

    return true;
}

// Function to validate the integrity of the CRC flags in the list
void validateCrcIndicationList(NFAPI_CRC_INDICATION_LIST_T *list) {
    // Acquire the mutex for concurrent access
    pthread_mutex_lock(&list->mutex);

    // Iterate over the PDUs in the list and validate their CRC flags
    for (size_t i = 0; i < list->currentSize; i++) {
        NFAPI_CRC_INDICATION_PDU_T *pdu = &list->pduList[i];
        if (!validateCrcIndicationPdu(pdu)) {
            printf("Error: CRC flag validation failed for PDU %zu\n", i);
        }
    }

    // Release the mutex for concurrent access
    pthread_mutex_unlock(&list->mutex);
}

// Function to validate a single CRC indication PDU
bool validateCrcIndicationPdu(NFAPI_CRC_INDICATION_PDU_T *pdu) {
    // Check if the CRC flag is valid
    if (pdu->crcIndicationRel8Tag.crCFlag != CRCFLAG_VALID()) {
        return false;
    }

    // Check if the RX UE information tag is valid
    if (pdu->rxUeInformationTag != RX_UE_INFORMATION_TAG_VALID()) {
        return false;
    }

    // Check if the RNTI is valid
    if (pdu->rnti != RNTI_VALID()) {
        return false;
    }

    return true;
}

// Function to free the memory allocated for the list of CRC indication PDUs
void freeCrcIndicationList(NFAPI_CRC_INDICATION_LIST_T *list) {
    // Acquire the mutex for concurrent access
    pthread_mutex_lock(&list->mutex);

    // Free the memory allocated for the list structure and its PDUs
    free(list->pduList);
    free(list);

    // Release the mutex for concurrent access
    pthread_mutex_unlock(&list->mutex);
}
