typedef struct {
    PHY_RX_FRAME_INFO *list;
    int size;
    pthread_mutex_t mutex;
} DYNAMIC_LIST;

// Function to initialize and manage the dynamic list of RX frame information
void init_dynamic_list(DYNAMIC_LIST *list) {
    // Initialize the list with a null pointer and size 0
    list->list = NULL;
    list->size = 0;

    // Initialize the mutex for thread safety
    pthread_mutex_init(&list->mutex, NULL);
}

// Function to add a new RX frame information structure to the dynamic list
void add_rx_frame(DYNAMIC_LIST *list, PHY_RACH_REQUEST rach_request, PHY_RX_FRAME rx_frame) {
    // Lock the mutex for thread safety
    pthread_mutex_lock(&list->mutex);

    // Allocate memory for the new structure
    PHY_RX_FRAME_INFO *new_info = malloc(sizeof(PHY_RX_FRAME_INFO));
    if (new_info == NULL) {
        printf("Error: Failed to allocate memory for RX frame information\n");
        return;
    }

    // Initialize the new structure with the given parameters
    new_info->rach_request = rach_request;
    new_info->rx_frame = rx_frame;

    // Add the new structure to the list
    if (list->size == 0) {
        list->list = new_info;
    } else {
        PHY_RX_FRAME_INFO *last_info = list->list + (list->size - 1);
        last_info->next = new_info;
    }

    // Increment the size of the list
    list->size++;

    // Unlock the mutex
    pthread_mutex_unlock(&list->mutex);
}

// Function to remove a RX frame information structure from the dynamic list
void remove_rx_frame(DYNAMIC_LIST *list, PHY_RACH_REQUEST rach_request) {
    // Lock the mutex for thread safety
    pthread_mutex_lock(&list->mutex);

    // Find the structure with the given RACH sequence and SRP value
    int i;
    for (i = 0; i < list->size; i++) {
        PHY_RX_FRAME_INFO *info = list->list + i;
        if (info->rach_request.RACH_SEQUENCE == rach_request.RACH_SEQUENCE && info->rach_request.SRP == rach_request.SRP) {
            break;
        }
    }

    // If the structure was found, remove it from the list and free its memory
    if (i < list->size) {
        PHY_RX_FRAME_INFO *info = list->list + i;
        if (i == 0) {
            list->list = info->next;
        } else {
            PHY_RX_FRAME_INFO *prev_info = list->list + (i - 1);
            prev_info->next = info->next;
        }
        free(info);
        list->size--;
    }

    // Unlock the mutex
    pthread_mutex_unlock(&list->mutex);
}

// Function to retrieve a RX frame information structure from the dynamic list
PHY_RX_FRAME_INFO *get_rx_frame(DYNAMIC_LIST *list, PHY_RACH_REQUEST rach_request) {
    // Lock the mutex for thread safety
    pthread_mutex_lock(&list->mutex);

    // Find the structure with the given RACH sequence and SRP value
    int i;
    for (i = 0; i < list->size; i++) {
        PHY_RX_FRAME_INFO *info = list->list + i;
        if (info->rach_request.RACH_SEQUENCE == rach_request.RACH_SEQUENCE && info->rach_request.SRP == rach_request.SRP) {
            break;
        }
    }

    // If the structure was found, return it
    if (i < list->size) {
        PHY_RX_FRAME_INFO *info = list->list + i;
        pthread_mutex_unlock(&list->mutex);
        return info;
    }

    // If the structure was not found, return NULL
    pthread_mutex_unlock(&list->mutex);
    return NULL;
}

// Function to validate the integrity of the RACH sequences and SRP values in the dynamic list
void validate_rach_sequences(DYNAMIC_LIST *list) {
    // Lock the mutex for thread safety
    pthread_mutex_lock(&list->mutex);

    // Iterate over all structures in the list and check their RACH sequences and SRP values
    int i;
    for (i = 0; i < list->size; i++) {
        PHY_RX_FRAME_INFO *info = list->list + i;
        if (info->rach_request.RACH_SEQUENCE != info->rx_frame.PHY_RLC_PDU.RACH_SEQUENCE ||
            info->rach_request.SRP != info->rx_frame.PHY_MAC_PDU.SRP) {
            printf("Error: RACH sequence or SRP value mismatch in RX frame information structure\n");
        }
    }

    // Unlock the mutex
    pthread_mutex_unlock(&list->mutex);
}
