// Define the structure for a user session
typedef struct {
    int session_id;
    char client_ip[16];
    time_t last_login;
    void* config; // Session-specific configuration structure
} session_t;

// Define the list of sessions
static session_t* sessions = NULL;
static size_t num_sessions = 0;

// Mutex for thread-safe access to the list of sessions
static pthread_mutex_t session_list_lock = PTHREAD_MUTEX_INITIALIZER;

// Function to add a new session to the list
void add_session(int session_id, const char* client_ip, time_t last_login, void* config) {
    // Lock the mutex before modifying the list of sessions
    pthread_mutex_lock(&session_list_lock);

    // Allocate memory for the new session
    session_t* new_session = malloc(sizeof(session_t));
    if (new_session == NULL) {
        perror("malloc");
        return;
    }

    // Initialize the fields of the new session
    new_session->session_id = session_id;
    strcpy(new_session->client_ip, client_ip);
    new_session->last_login = last_login;
    new_session->config = config;

    // Add the new session to the list of sessions
    if (sessions == NULL) {
        sessions = malloc(sizeof(session_t));
        if (sessions == NULL) {
            perror("malloc");
            return;
        }
        num_sessions = 1;
    } else {
        session_t* new_sessions = realloc(sessions, (num_sessions + 1) * sizeof(session_t));
        if (new_sessions == NULL) {
            perror("realloc");
            return;
        }
        sessions = new_sessions;
        num_sessions++;
    }

    // Unlock the mutex after modifying the list of sessions
    pthread_mutex_unlock(&session_list_lock);
}

// Function to update an existing session in the list
void update_session(int session_id, const char* client_ip, time_t last_login) {
    // Lock the mutex before modifying the list of sessions
    pthread_mutex_lock(&session_list_lock);

    // Find the session with the given ID
    size_t i;
    for (i = 0; i < num_sessions; i++) {
        if (sessions[i].session_id == session_id) {
            break;
        }
    }

    // If the session was found, update its fields
    if (i < num_sessions) {
        sessions[i].client_ip = client_ip;
        sessions[i].last_login = last_login;
    } else {
        printf("Session with ID %d not found\n", session_id);
    }

    // Unlock the mutex after modifying the list of sessions
    pthread_mutex_unlock(&session_list_lock);
}

// Function to safely terminate a session based on inactivity thresholds
void terminate_session(int session_id) {
    // Lock the mutex before modifying the list of sessions
    pthread_mutex_lock(&session_list_lock);

    // Find the session with the given ID
    size_t i;
    for (i = 0; i < num_sessions; i++) {
        if (sessions[i].session_id == session_id) {
            break;
        }
    }

    // If the session was found, terminate it and remove it from the list
    if (i < num_sessions) {
        free(sessions[i].config);
        sessions[i] = sessions[num_sessions - 1];
        num_sessions--;
    } else {
        printf("Session with ID %d not found\n", session_id);
    }

    // Unlock the mutex after modifying the list of sessions
    pthread_mutex_unlock(&session_list_lock);
}

// Function to efficiently evict expired sessions without causing excessive memory fragmentation
void evict_expired_sessions() {
    // Lock the mutex before modifying the list of sessions
    pthread_mutex_lock(&session_list_lock);

    // Find the first session that has not been updated recently
    size_t i;
    for (i = 0; i < num_sessions; i++) {
        if (time(NULL) - sessions[i].last_login > INACTIVITY_THRESHOLD) {
            break;
        }
    }

    // If a session was found, terminate it and remove it from the list
    if (i < num_sessions) {
        free(sessions[i].config);
        sessions[i] = sessions[num_sessions - 1];
        num_sessions--;
    } else {
        printf("No expired sessions found\n");
    }

    // Unlock the mutex after modifying the list of sessions
    pthread_mutex_unlock(&session_list_lock);
}
