```c
#include <stdlib.h>
#include <time.h>
#include <stdio.h>
#include <string.h>
#include <pthread.h>

// Define the structure for the cache entry
typedef struct {
    long offset;
    int key;
    record value;
    timestamp timestamp;
} cache_entry;

// Define the structure for the cache
typedef struct {
    cache_entry *entries;
    size_t num_entries;
    pthread_mutex_t mutex;
} cache;

// Function to initialize the cache
void init_cache(cache *c, size_t num_entries) {
    c->num_entries = num_entries;
    c->entries = (cache_entry *)malloc(sizeof(cache_entry) * num_entries);
    if (!c->entries) {
        fprintf(stderr, "Failed to allocate memory for cache entries\n");
        exit(1);
    }
    pthread_mutex_init(&c->mutex, NULL);
}

// Function to add an entry to the cache
void add_entry(cache *c, long offset, int key, record value, timestamp timestamp) {
    // Lock the mutex before modifying the cache
    pthread_mutex_lock(&c->mutex);

    // Check if the cache is full and needs to be resized
    if (c->num_entries == c->size) {
        // Resize the cache by doubling its size
        c->size *= 2;
        c->entries = (cache_entry *)realloc(c->entries, sizeof(cache_entry) * c->size);
        if (!c->entries) {
            fprintf(stderr, "Failed to resize cache\n");
            exit(1);
        }
    }

    // Add the new entry to the cache
    c->entries[c->num_entries].offset = offset;
    c->entries[c->num_entries].key = key;
    c->entries[c->num_entries].value = value;
    c->entries[c->num_entries].timestamp = timestamp;
    c->num_entries++;

    // Unlock the mutex after modifying the cache
    pthread_mutex_unlock(&c->mutex);
}

// Function to query an entry from the cache without evicting it
cache_entry *query_entry(cache *c, int key) {
    // Lock the mutex before accessing the cache
    pthread_mutex_lock(&c->mutex);

    // Search for the entry in the cache
    for (size_t i = 0; i < c->num_entries; i++) {
        if (c->entries[i].key == key) {
            return &c->entries[i];
        }
    }

    // Unlock the mutex after accessing the cache
    pthread_mutex_unlock(&c->mutex);

    // Return NULL if the entry is not found in the cache
    return NULL;
}

// Function to evict expired entries from the cache
void evict_expired(cache *c) {
    // Lock the mutex before modifying the cache
    pthread_mutex_lock(&c->mutex);

    // Iterate over the cache entries and remove any that have expired
    for (size_t i = 0; i < c->num_entries; i++) {
        if (c->entries[i].timestamp.tv_sec + c->entries[i].timestamp.tv_nsec <= time(NULL)) {
            // Remove the entry from the cache
            memmove(&c->entries[i], &c->entries[i+1], sizeof(cache_entry) * (c->num_entries - i));
            c->num_entries--;
        }
    }

    // Unlock the mutex after modifying the cache
    pthread_mutex_unlock(&c->mutex);
}

// Function to handle conflicts between cached and external resource structures
void handle_conflicts(cache *c, record *external) {
    // Lock the mutex before modifying the cache
    pthread_mutex_lock(&c->mutex);

    // Iterate over the cache entries and compare them to the external resource structure
    for (size_t i = 0; i < c->num_entries; i++) {
        if (c->entries[i].key == external->key) {
            // Compare the values of the cached and external resource structures
            if (c->entries[i].value != external->value) {
                // Handle the conflict by updating the cache entry with the new value from the external source
                c->entries[i].value = external->value;
            }
        } else {
            // Add the new resource structure to the cache if it is not already present
            add_entry(c, external->offset, external->key, external->value, external->timestamp);
        }
    }

    // Unlock the mutex after modifying the cache
    pthread_mutex_unlock(&c->mutex);
}

// Function to handle resource leaks if the cache is ever full and needs to evict entries
void handle_leaks(cache *c) {
    // Lock the mutex before modifying the cache
    pthread_mutex_lock(&c->mutex);

    // Iterate over the cache entries and remove any that have not been accessed recently
    for (size_t i = 0; i < c->num_entries; i++) {
        if (c->entries[i].timestamp.tv_sec + c->entries[i].timestamp.tv_nsec <= time(NULL)) {
            // Remove the entry from the cache
            memmove(&c->entries[i], &c->entries[i+1], sizeof(cache_entry) * (c->num_entries - i));
            c->num_entries--;
        }
    }

    // Unlock the mutex after modifying the cache
    pthread_mutex_unlock(&c->mutex);
}

// Function to dynamically allocate memory for four distinct arrays
void allocate_arrays(size_t num_offsets, size_t num_keys, size_t num_records, size_t num_timestamps) {
    // Validate that the parameters are non-negative integers greater than zero
    if (num_offsets <= 0 || num_keys <= 0 || num_records <= 0 || num_timestamps <= 0) {
        fprintf(stderr, "Invalid number of elements\n");
        exit(1);
    }

    // Allocate memory for the arrays using standard library functions
    long *offsets = (long *)malloc(sizeof(long) * num_offsets);
    int *keys = (int *)malloc(sizeof(int) * num_keys);
    record *records = (record *)malloc(sizeof(record) * num_records);
    timestamp *timestamps = (timestamp *)malloc(sizeof(timestamp) * num_timestamps);

    // Initialize the arrays with random values
    for (size_t i = 0; i < num_offsets; i++) {
        offsets[i] = rand();
    }
    for (size_t i = 0; i < num_keys; i++) {
        keys[i] = rand();
    }
    for (size_t i = 0; i < num_records; i++) {
        records[i].value = rand();
    }
    for (size_t i = 0; i < num_timestamps; i++) {
        timestamps[i].tv_sec = time(NULL);
        timestamps[i].tv_nsec = rand() % 1000000000;
    }
}
