// Define a structure to store network interface statistics
typedef struct NetworkInterfaceStats {
    char *interface_name;
    double packet_loss;
    double throughput;
    double latency;
} NetworkInterfaceStats;

// Define a thread-safe data structure for storing the network interface statistics
typedef struct ThreadSafeNetworkInterfaceStats {
    pthread_mutex_t mutex;
    int size;
    NetworkInterfaceStats *stats;
} ThreadSafeNetworkInterfaceStats;

// Initialize the memory pool with a configurable initial size and maximum number of interfaces
void init_memory_pool(int initial_size, int max_interfaces) {
    // Allocate memory for the memory pool
    void *mem = malloc(initial_size);
    if (mem == NULL) {
        printf("Error: Failed to allocate memory for the memory pool\n");
        exit(1);
    }

    // Initialize the memory pool with the initial size and maximum number of interfaces
    ThreadSafeNetworkInterfaceStats *pool = malloc(sizeof(ThreadSafeNetworkInterfaceStats));
    if (pool == NULL) {
        printf("Error: Failed to allocate memory for the thread-safe network interface statistics\n");
        exit(1);
    }
    pool->mutex = PTHREAD_MUTEX_INITIALIZER;
    pool->size = initial_size;
    pool->stats = mem;
}

// Add a new network interface to the memory pool
void add_interface(char *interface_name) {
    // Acquire the lock on the memory pool
    pthread_mutex_lock(&pool->mutex);

    // Check if there is enough space in the memory pool for the new interface statistics
    if (pool->size + sizeof(NetworkInterfaceStats) > initial_size) {
        // Resize the memory pool to accommodate the new interface statistics
        void *new_mem = realloc(pool->stats, pool->size + sizeof(NetworkInterfaceStats));
        if (new_mem == NULL) {
            printf("Error: Failed to resize the memory pool\n");
            exit(1);
        }
        pool->stats = new_mem;
    }

    // Add the new interface statistics to the memory pool
    NetworkInterfaceStats *new_stats = (NetworkInterfaceStats *)((char *)pool->stats + pool->size);
    new_stats->interface_name = strdup(interface_name);
    new_stats->packet_loss = 0;
    new_stats->throughput = 0;
    new_stats->latency = 0;
    pool->size += sizeof(NetworkInterfaceStats);

    // Release the lock on the memory pool
    pthread_mutex_unlock(&pool->mutex);
}

// Update an existing network interface in the memory pool
void update_interface(char *interface_name, double packet_loss, double throughput, double latency) {
    // Acquire the lock on the memory pool
    pthread_mutex_lock(&pool->mutex);

    // Find the existing network interface statistics in the memory pool
    NetworkInterfaceStats *stats = NULL;
    for (int i = 0; i < pool->size / sizeof(NetworkInterfaceStats); i++) {
        if (strcmp(interface_name, ((NetworkInterfaceStats *)((char *)pool->stats + i))->interface_name) == 0) {
            stats = (NetworkInterfaceStats *)((char *)pool->stats + i);
            break;
        }
    }

    // Update the existing network interface statistics in the memory pool
    if (stats != NULL) {
        stats->packet_loss = packet_loss;
        stats->throughput = throughput;
        stats->latency = latency;
    } else {
        printf("Error: Failed to find existing network interface statistics\n");
    }

    // Release the lock on the memory pool
    pthread_mutex_unlock(&pool->mutex);
}

// Retrieve aggregated statistics for all interfaces in the memory pool
void get_aggregate_stats(double *packet_loss, double *throughput, double *latency) {
    // Acquire the lock on the memory pool
    pthread_mutex_lock(&pool->mutex);

    // Calculate the aggregated statistics for all interfaces in the memory pool
    *packet_loss = 0;
    *throughput = 0;
    *latency = 0;
    for (int i = 0; i < pool->size / sizeof(NetworkInterfaceStats); i++) {
        NetworkInterfaceStats *stats = (NetworkInterfaceStats *)((char *)pool->stats + i);
        *packet_loss += stats->packet_loss;
        *throughput += stats->throughput;
        *latency += stats->latency;
    }

    // Release the lock on the memory pool
    pthread_mutex_unlock(&pool->mutex);
}

// Free the memory pool and all associated resources
void free_memory_pool() {
    // Acquire the lock on the memory pool
    pthread_mutex_lock(&pool->mutex);

    // Free the memory pool and all associated resources
    free(pool->stats);
    free(pool);

    // Release the lock on the memory pool
    pthread_mutex_unlock(&pool->mutex);
}
