// Define the mutex for thread-safe operations
static pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

// Define the expiration time for configurations in seconds
#define EXPIRATION_TIME 3600 // 1 hour

// Add a new configuration to the cache
void addConfiguration(int id, char* name, void* parameters) {
    pthread_mutex_lock(&mutex);
    Configuration* config = malloc(sizeof(Configuration));
    config->id = id;
    config->name = strdup(name);
    config->parameters = parameters;
    cache[id] = config;
    pthread_mutex_unlock(&mutex);
}

// Update an existing configuration in the cache
void updateConfiguration(int id, char* name, void* parameters) {
    pthread_mutex_lock(&mutex);
    Configuration* config = cache[id];
    if (config != NULL) {
        free(config->name);
        config->name = strdup(name);
        config->parameters = parameters;
    }
    pthread_mutex_unlock(&mutex);
}

// Retrieve a configuration from the cache by ID
Configuration* getConfiguration(int id) {
    pthread_mutex_lock(&mutex);
    Configuration* config = cache[id];
    if (config != NULL && config->expirationTime < time(NULL)) {
        // Evict outdated configuration
        free(config->name);
        free(config->parameters);
        free(config);
        cache[id] = NULL;
    }
    pthread_mutex_unlock(&mutex);
    return config;
}

// Evict all outdated configurations from the cache
void evictOutdatedConfigurations() {
    pthread_mutex_lock(&mutex);
    for (int i = 0; i < MAX_CACHE_SIZE; i++) {
        Configuration* config = cache[i];
        if (config != NULL && config->expirationTime < time(NULL)) {
            free(config->name);
            free(config->parameters);
            free(config);
            cache[i] = NULL;
        }
    }
    pthread_mutex_unlock(&mutex);
}
