// Function to count the number of words in a line
int count_words(char *line) {
  int words = 0;
  char *token = strtok(line, " ");
  while (token != NULL) {
    words++;
    token = strtok(NULL, " ");
  }
  return words;
}

// Function to compress a count using a simple run-length encoding algorithm
int compress_count(int count) {
  if (count == 0) {
    return 1;
  } else {
    int i = 2;
    while (i <= count) {
      i *= 2;
    }
    return i / 2;
  }
}

