void init_network_interface_stats(NetworkInterfaceStats **stats, size_t initial_capacity) {
    // Allocate memory for the dynamic array
    *stats = (NetworkInterfaceStats *)malloc(sizeof(NetworkInterfaceStats) * initial_capacity);
    if (*stats == NULL) {
        fprintf(stderr, "Error: Failed to allocate memory for network interface stats\n");
        exit(EXIT_FAILURE);
    }

    // Initialize the dynamic array with null pointers
    for (size_t i = 0; i < initial_capacity; i++) {
