        resize_memory_pool(stats, capacity);
    }

    // Add a new entry to the dynamic array
    (*stats)[(*stats)->used].interface_name = strdup(interface_name);
    (*stats)[(*stats)->used].packet_loss = -1.0;
    (*stats)[(*stats)->used].throughput = -1;
    (*stats)[(*stats)->used].latency = -1;
