}

// Define the function to resize the memory pool when necessary
void resize_memory_pool(NetworkInterfaceStats **stats, size_t *capacity) {
    // Allocate a new memory block with double the capacity of the previous one
    void **new_blocks = (void **)malloc(sizeof(void *) * (*capacity) * 2);
    if (new_blocks == NULL) {
        fprintf(stderr, "Error: Failed to allocate memory for network interface stats\n");
        exit(EXIT_FAILURE);
    }

    // Copy the existing entries from the previous memory block to the new one
    memcpy(new_blocks, *stats, sizeof(NetworkInterfaceStats) * (*capacity));

    // Free the previous memory block and update the pointers
    free(*stats);
    *stats = (NetworkInterfaceStats *)new_blocks;
    *capacity *= 2;
}

