    // Initialize each row record with a valid ROW_ID and COLUMN_VALUES
    for (int i = 0; i < num_rows; i++) {
        rows[i].row_id = i + 1;
        rows[i].num_columns = max_columns;
        rows[i].column_values = (char**)malloc(max_columns * sizeof(char*));
        for (int j = 0; j < max_columns; j++) {
            rows[i].column_values[j] = (char*)malloc(max_description_length);
        }
    }

    // Set the timestamp to the current system time
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    for (int i = 0; i < num_rows; i++) {
        rows[i].timestamp = ts.tv_sec + ts.tv_nsec / 1e9;
    }

    // Return the list of row records
    return rows;
}

// Function to manage dynamic memory allocation and initialization for a collection of 'entry' objects
void* init_entries(int num_entries, int max_identifier, double min_timestamp, double max_timestamp) {
    // Allocate memory for the entry array
