    for (int i = 0; i < num_entries; i++) {
        entries[i].identifier = rand() % max_identifier + 1;
        entries[i].timestamp = min_timestamp + (max_timestamp - min_timestamp) * ((double)rand() / RAND_MAX);
    }

    // Return the initialized entry array and any error codes encountered during execution
    return entries;
}
