    int object_id;
    void* resource;
    time_t timestamp;
} CUSTOM_OBJECT;

// Define the function to initialize and populate the cache
int init_cache(int num_offsets, int num_keys, int num_records, int min_value, int max_value) {
    // Validate input parameters
    if (num_offsets < 0 || num_keys < 0 || num_records < 0) {
        return -1;
    }

    // Allocate memory for the three arrays
    long* offsets = malloc(sizeof(long) * num_offsets);
    int* keys = malloc(sizeof(int) * num_keys);
    CUSTOM_OBJECT* records = malloc(sizeof(CUSTOM_OBJECT) * num_records);

    // Check for memory allocation errors
    if (offsets == NULL || keys == NULL || records == NULL) {
        free(offsets);
        free(keys);
        free(records);
        return -1;
    }

    // Initialize the cache and populate it with random values
    for (int i = 0; i < num_offsets; i++) {
        offsets[i] = rand() % (max_value - min_value + 1) + min_value;
    }
    for (int i = 0; i < num_keys; i++) {
        keys[i] = i;
    }
    for (int i = 0; i < num_records; i++) {
        records[i].object_id = i;
        records[i].resource = NULL;
        records[i].timestamp = time(NULL);
    }

    // Initialize the cache with the random values
    for (int i = 0; i < num_records; i++) {
        CUSTOM_OBJECT* record = &records[i];
        int key = keys[i];
        long offset = offsets[key];
        record->resource = malloc(offset);
        if (record->resource == NULL) {
            free(offsets);
            free(keys);
            free(records);
            return -1;
        }
    }

    // Evict expired objects from the cache automatically
    for (int i = 0; i < num_records; i++) {
        CUSTOM_OBJECT* record = &records[i];
        if (record->timestamp + TIMEOUT < time(NULL)) {
            free(record->resource);
            record->resource = NULL;
        }
    }

    // Return pointers to the three allocated arrays and a status indicator indicating success
    return 0;
}
```
