// Define the structure for network interface statistics
typedef struct NetworkInterfaceStats {
    char *interface_name;
    int packet_loss;
    long throughput;
    double latency;
} NetworkInterfaceStats;

// Define the dynamic array for storing network interface statistics
typedef struct NetworkInterfaceStatsArray {
    NetworkInterfaceStats **stats;
    size_t capacity;
    size_t count;
} NetworkInterfaceStatsArray;

// Initialize a new dynamic array with a given initial capacity
void init_network_interface_stats_array(NetworkInterfaceStatsArray *array, size_t initial_capacity) {
    array->stats = malloc(initial_capacity * sizeof(NetworkInterfaceStats*));
    array->capacity = initial_capacity;
    array->count = 0;
}

// Add a new network interface statistics to the dynamic array
void add_network_interface_stat(NetworkInterfaceStatsArray *array, const char *interface_name, int packet_loss, long throughput, double latency) {
    // Check if the array is full and needs to be resized
    if (array->count == array->capacity) {
        array->capacity *= 2;
        array->stats = realloc(array->stats, array->capacity * sizeof(NetworkInterfaceStats*));
    }

    // Create a new network interface statistics object and add it to the array
    NetworkInterfaceStats *new_stat = malloc(sizeof(NetworkInterfaceStats));
    new_stat->interface_name = strdup(interface_name);
    new_stat->packet_loss = packet_loss;
    new_stat->throughput = throughput;
    new_stat->latency = latency;
    array->stats[array->count++] = new_stat;
}

// Update an existing network interface statistics in the dynamic array
void update_network_interface_stat(NetworkInterfaceStatsArray *array, const char *interface_name, int packet_loss, long throughput, double latency) {
    // Find the index of the network interface statistics to be updated
    size_t i;
    for (i = 0; i < array->count; i++) {
        if (strcmp(array->stats[i]->interface_name, interface_name) == 0) {
            break;
        }
    }

    // Update the network interface statistics object
    NetworkInterfaceStats *stat = array->stats[i];
    stat->packet_loss = packet_loss;
    stat->throughput = throughput;
    stat->latency = latency;
}

// Retrieve aggregated statistics for all network interfaces in the dynamic array
void get_network_interface_stats(NetworkInterfaceStatsArray *array, NetworkInterfaceStats **stats, size_t *count) {
    // Allocate memory for the output array
    *stats = malloc(*count * sizeof(NetworkInterfaceStats));

    // Copy the network interface statistics objects to the output array
    memcpy(*stats, array->stats, *count * sizeof(NetworkInterfaceStats));
}

// Concurrency support: Implement a thread-safe version of the function using locks and mutexes
void add_network_interface_stat_threadsafe(NetworkInterfaceStatsArray *array, const char *interface_name, int packet_loss, long throughput, double latency) {
    // Lock the array to prevent concurrent modifications
    pthread_mutex_lock(&array->mutex);

    // Add the network interface statistics object to the array
    add_network_interface_stat(array, interface_name, packet_loss, throughput, latency);

    // Unlock the array and return
    pthread_mutex_unlock(&array->mutex);
}

// Concurrency support: Implement a thread-safe version of the function using locks and mutexes
void update_network_interface_stat_threadsafe(NetworkInterfaceStatsArray *array, const char *interface_name, int packet_loss, long throughput, double latency) {
    // Lock the array to prevent concurrent modifications
    pthread_mutex_lock(&array->mutex);

    // Update the network interface statistics object in the array
    update_network_interface_stat(array, interface_name, packet_loss, throughput, latency);

    // Unlock the array and return
    pthread_mutex_unlock(&array->mutex);
}

// Resource management: Implement a custom memory pool to minimize overhead of frequent memory allocations and deallocations
void init_memory_pool(MemoryPool *pool, size_t initial_capacity) {
    // Initialize the memory pool with an initial capacity
    pool->capacity = initial_capacity;
    pool->count = 0;
    pool->blocks = malloc(initial_capacity * sizeof(void*));
}

// Resource management: Implement a custom memory pool to minimize overhead of frequent memory allocations and deallocations
void add_memory_pool_block(MemoryPool *pool, size_t block_size) {
    // Check if the pool is full and needs to be resized
    if (pool->count == pool->capacity) {
        pool->capacity *= 2;
        pool->blocks = realloc(pool->blocks, pool->capacity * sizeof(void*));
    }

    // Allocate a new block of memory and add it to the pool
    void *new_block = malloc(block_size);
    pool->blocks[pool->count++] = new_block;
}

// Resource management: Implement a custom memory pool to minimize overhead of frequent memory allocations and deallocations
void remove_memory_pool_block(MemoryPool *pool, size_t block_index) {
    // Check if the block index is valid
    if (block_index >= pool->count) {
        return;
    }

    // Remove the block from the pool and free its memory
    void *removed_block = pool->blocks[block_index];
    memmove(pool->blocks + block_index, pool->blocks + block_index + 1, (pool->count - block_index - 1) * sizeof(void*));
    free(removed_block);
}

// Data validation: Implement comprehensive input validation before adding or updating interface stats
bool validate_network_interface_stat(const char *interface_name, int packet_loss, long throughput, double latency) {
    // Check if the interface name is valid and non-empty
    if (strlen(interface_name) == 0) {
        return false;
    }

    // Check if the packet loss percentage is within the expected range
    if (packet_loss < 0 || packet_loss > 100) {
        return false;
    }

    // Check if the throughput value is non-negative
    if (throughput < 0) {
        return false;
    }

    // Check if the latency value is within the expected range
    if (latency < 0 || latency > 1000) {
        return false;
    }

    // If all checks pass, return true
    return true;
}

// Logging and monitoring: Implement a logging mechanism to record changes in network interface statistics
void log_network_interface_stat(const char *interface_name, int packet_loss, long throughput, double latency) {
