    // Iterate over all entries in the cache and check if their TTL has expired
    for (int i = 0; i < cache->size; i++) {
        struct cache_entry *entry = cache->entries[i];
        if (time(NULL) > entry->expiration) {
            // Remove the expired entry from the cache
            free(entry);
            cache->entries[i] = NULL;
        }
    }
}

