    struct in_addr addr;

    // Check if the name is already cached
    for (int i = 0; i < CACHE_SIZE; i++) {
        if (cache[i].name && strcmp(cache[i].name, name) == 0) {
            addr = cache[i].addr;
            break;
        }
    }

    // If not cached, perform a DNS query and update the cache
    if (!addr.s_addr) {
        struct sockaddr_in server;
        int sockfd;

        // Create a socket for the DNS query
        sockfd = socket(AF_INET, SOCK_DGRAM, 0);
        if (sockfd < 0) {
            perror("socket");
            return NULL;
        }

        // Set up the DNS server address
        memset(&server, 0, sizeof(server));
        server.sin_family = AF_INET;
        server.sin_port = htons(53);
        inet_pton(AF_INET, "8.8.8.8", &server.sin_addr);

        // Send the DNS query
        if (sendto(sockfd, name, strlen(name), 0, (struct sockaddr *)&server, sizeof(server)) < 0) {
            perror("sendto");
            close(sockfd);
            return NULL;
        }

        // Receive the DNS response
        char buf[512];
        struct sockaddr_in client;
        socklen_t addrlen = sizeof(client);
        if (recvfrom(sockfd, buf, sizeof(buf), 0, (struct sockaddr *)&client, &addrlen) < 0) {
            perror("recvfrom");
            close(sockfd);
            return NULL;
        }

        // Parse the DNS response and update the cache
        struct dns_header *hdr = (struct dns_header *)buf;
        if (hdr->qr == 1 && hdr->ancount > 0) {
            struct dns_rr *rr = (struct dns_rr *)(buf + sizeof(struct dns_header));
            for (int i = 0; i < hdr->ancount; i++) {
