// Define the structure for an NFAPI_CRC_INDICATION_PDU_T
typedef struct {
    uint16_t RX_UE_INFORMATION_TAG;
    uint32_t RNTI;
    uint8_t CRC_INDICATION_REL8_TAG[4];
} NFAPI_CRC_INDICATION_PDU_T;

// Define the structure for a linked list node
typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *pdu;
    struct node *next;
} node_t;

// Define the priority queue data structure
typedef struct {
    uint32_t RNTI;
    int32_t priority;
} priority_queue_t;

// Define the logging mechanism
#define LOGGING_BUFFER_SIZE 1024
char logging_buffer[LOGGING_BUFFER_SIZE];

// Define the function to create and populate a list of NFAPI_CRC_INDICATION_PDU_T structures
void create_and_populate_pdu_list(int num_pdus, int max_pdu_size) {
    // Allocate memory for the PDU list
    node_t *head = NULL;
    node_t *tail = NULL;
    NFAPI_CRC_INDICATION_PDU_T *pdu = malloc(max_pdu_size);
    if (pdu == NULL) {
        printf("Error: Failed to allocate memory for PDU list\n");
        return;
    }

    // Populate the PDU list with random data
    srand(time(NULL));
    for (int i = 0; i < num_pdus; i++) {
        pdu->RX_UE_INFORMATION_TAG = rand() % 10000;
        pdu->RNTI = rand() % 1000000000;
        for (int j = 0; j < 4; j++) {
            pdu->CRC_INDICATION_REL8_TAG[j] = rand() % 256;
        }
        node_t *new_node = malloc(sizeof(node_t));
        if (new_node == NULL) {
            printf("Error: Failed to allocate memory for new PDU list node\n");
            return;
        }
        new_node->pdu = pdu;
        new_node->next = NULL;
        if (head == NULL) {
            head = tail = new_node;
        } else {
            tail->next = new_node;
            tail = new_node;
        }
    }

    // Serialize the PDU list into a binary format
    int serialized_size = 0;
    for (node_t *current = head; current != NULL; current = current->next) {
        serialized_size += sizeof(NFAPI_CRC_INDICATION_PDU_T);
    }
    uint8_t *serialized_data = malloc(serialized_size);
    if (serialized_data == NULL) {
        printf("Error: Failed to allocate memory for serialized data\n");
        return;
    }
    int offset = 0;
    for (node_t *current = head; current != NULL; current = current->next) {
        memcpy(serialized_data + offset, current->pdu, sizeof(NFAPI_CRC_INDICATION_PDU_T));
        offset += sizeof(NFAPI_CRC_INDICATION_PDU_T);
    }

    // Verify the integrity of the serialized data
    uint32_t checksum = 0;
    for (int i = 0; i < serialized_size; i++) {
        checksum += serialized_data[i];
    }
    if (checksum != 0) {
        printf("Error: Serialized data integrity check failed\n");
        return;
    }

    // Deserialize the PDU list from the binary format
    int deserialized_size = serialized_size;
    NFAPI_CRC_INDICATION_PDU_T *deserialized_pdu = malloc(deserialized_size);
    if (deserialized_pdu == NULL) {
        printf("Error: Failed to allocate memory for deserialized PDU list\n");
        return;
    }
    memcpy(deserialized_pdu, serialized_data, deserialized_size);

    // Free the serialized data and deserialized PDU list
    free(serialized_data);
    free(deserialized_pdu);
}

// Define the function to add a new PDU to the list from multiple concurrent threads safely
void add_pdu_to_list(NFAPI_CRC_INDICATION_PDU_T *pdu) {
    // Lock the mutex to prevent data corruption
    pthread_mutex_lock(&mutex);

    // Allocate memory for the new node
    node_t *new_node = malloc(sizeof(node_t));
    if (new_node == NULL) {
        printf("Error: Failed to allocate memory for new PDU list node\n");
        return;
    }

    // Add the new node to the end of the list
    node_t *current = head;
    while (current->next != NULL) {
        current = current->next;
    }
    new_node->pdu = pdu;
    new_node->next = NULL;
    current->next = new_node;

    // Unlock the mutex and return
    pthread_mutex_unlock(&mutex);
}

// Define the function to remove a PDU from the list safely
void remove_pdu_from_list(NFAPI_CRC_INDICATION_PDU_T *pdu) {
    // Lock the mutex to prevent data corruption
    pthread_mutex_lock(&mutex);

    // Find the node containing the PDU and remove it from the list
    node_t *current = head;
    while (current != NULL && current->pdu != pdu) {
        current = current->next;
    }
    if (current == NULL) {
        printf("Error: Failed to find PDU in list\n");
        return;
    }
    node_t *previous = current->prev;
    previous->next = current->next;
    free(current);

    // Unlock the mutex and return
    pthread_mutex_unlock(&mutex);
}

// Define the function to update the priority queue based on a new PDU's RNTI value
void update_priority_queue(NFAPI_CRC_INDICATION_PDU_T *pdu) {
    // Lock the mutex to prevent data corruption
    pthread_mutex_lock(&mutex);

    // Find the node containing the PDU and update its priority in the queue
    node_t *current = head;
    while (current != NULL && current->pdu != pdu) {
        current = current->next;
    }
    if (current == NULL) {
        printf("Error: Failed to find PDU in list\n");
        return;
    }
    priority_queue_t *new_node = malloc(sizeof(priority_queue_t));
    new_node->RNTI = pdu->RNTI;
    new_node->priority = current->priority;
    if (head == NULL) {
        head = tail = new_node;
    } else {
        tail->next = new_node;
        tail = new_node;
    }

    // Unlock the mutex and return
    pthread_mutex_unlock(&mutex);
}

// Define the function to log information about a PDU addition or removal
void log_pdu_event(NFAPI_CRC_INDICATION_PDU_T *pdu, bool is_addition) {
    // Lock the mutex to prevent data corruption
    pthread_mutex_lock(&mutex);

    // Log the event information
    if (is_addition) {
        sprintf(logging_buffer, "PDU addition: RX_UE_INFORMATION_TAG=%d, RNTI=%d\n", pdu->RX_UE_INFORMATION_TAG, pdu->RNTI);
    } else {
        sprintf(logging_buffer, "PDU removal: RX_UE_INFORMATION_TAG=%d, RNTI=%d\n", pdu->RX_UE_INFORMATION_TAG, pdu->RNTI);
    }
    printf("%s", logging_buffer);

    // Unlock the mutex and return
    pthread_mutex_unlock(&mutex);
