    FILE *output_stream = NULL;
    int line_count = 0;
    int word_count = 0;
    int character_count = 0;
    bool error = false;

    // Parse the command-line arguments
    while (true) {
        int option_index = 0;
        int c = getopt_long(argc, argv, "hco:", long_options, &option_index);
        if (c == -1) {
            break;
        }
        switch (c) {
            case 'h':
                printf(usage, argv[0]);
                return 0;
            case 'c':
                case_sensitive = true;
                break;
            case 'o':
                output_file = optarg;
                break;
            default:
                handle_error("Error: Invalid option specified");
                return 1;
        }
    }

    // Check if the input file was specified
    if (optind >= argc) {
        handle_error(error_messages[0]);
        return 1;
    }

    // Open the input file for reading
    input_file = fopen(argv[optind], "r");
    if (!input_file) {
        handle_error(error_messages[1]);
        return 1;
    }

    // Check if the output file was specified
    if (output_file == NULL) {
        handle_error(error_messages[0]);
        return 1;
    }

    // Open the output file for writing
    output_stream = fopen(output_file, "w");
    if (!output_stream) {
        handle_error(error_messages[3]);
        return 1;
    }

    // Read from the input file and process each line
    char *line = NULL;
    size_t len = 0;
    ssize_t read;
    while ((read = getline(&line, &len, input_file)) != -1) {
        // Count the number of lines in the file
        line_count++;

        // Split the line into words and count the number of words
        char *word = strtok(line, " ");
        while (word != NULL) {
            word_count++;
            word = strtok(NULL, " ");
        }

        // Count the number of characters in the file
        character_count += read;
    }

    // Close the input and output files
    fclose(input_file);
    fclose(output_stream);

    // Write the aggregated statistics to the output file
    fprintf(output_stream, "Line count: %d\n", line_count);
    fprintf(output_stream, "Word count: %d\n", word_count);
    fprintf(output_stream, "Character count: %d\n", character_count);

    // Return success
    return 0;
}
