// Define the data structure to represent a network connection
typedef struct {
    int id;
    int socket_descriptor;
    time_t last_activity;
    bool active;
} connection_t;

// Define the dynamic array to store all connections
static connection_t* connections = NULL;
static size_t num_connections = 0;
static pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

// Function to add a new connection to the list
int add_connection(int id, int socket_descriptor) {
    // Lock the mutex to prevent concurrent access
    pthread_mutex_lock(&mutex);

    // Check if the connection already exists
    for (size_t i = 0; i < num_connections; i++) {
        if (connections[i].id == id) {
            pthread_mutex_unlock(&mutex);
            return -1;
        }
    }

    // Allocate memory for the new connection
    connection_t* new_connection = malloc(sizeof(connection_t));
    if (!new_connection) {
        pthread_mutex_unlock(&mutex);
        return -1;
    }

    // Initialize the new connection
    new_connection->id = id;
    new_connection->socket_descriptor = socket_descriptor;
    new_connection->last_activity = time(NULL);
    new_connection->active = true;

    // Add the new connection to the list
    connections = realloc(connections, (num_connections + 1) * sizeof(connection_t));
    if (!connections) {
        free(new_connection);
        pthread_mutex_unlock(&mutex);
        return -1;
    }
    connections[num_connections++] = *new_connection;

    // Unlock the mutex and return success
    pthread_mutex_unlock(&mutex);
    return 0;
}

// Function to update an existing connection in the list
int update_connection(int id, int socket_descriptor) {
    // Lock the mutex to prevent concurrent access
    pthread_mutex_lock(&mutex);

    // Find the connection with the given ID
    for (size_t i = 0; i < num_connections; i++) {
        if (connections[i].id == id) {
            connections[i].socket_descriptor = socket_descriptor;
            break;
        }
    }

    // Unlock the mutex and return success
    pthread_mutex_unlock(&mutex);
    return 0;
}

// Function to remove an inactive connection from the list
int remove_connection(int id) {
    // Lock the mutex to prevent concurrent access
    pthread_mutex_lock(&mutex);

    // Find the connection with the given ID
    for (size_t i = 0; i < num_connections; i++) {
        if (connections[i].id == id) {
            connections[i] = connections[--num_connections];
            break;
        }
    }

    // Unlock the mutex and return success
    pthread_mutex_unlock(&mutex);
    return 0;
}

// Function to periodically scan the connection list for expired connections
void scan_connections() {
    time_t current_time = time(NULL);
    size_t num_expired_connections = 0;

    // Lock the mutex to prevent concurrent access
    pthread_mutex_lock(&mutex);

    // Iterate over all connections and check if they are expired
    for (size_t i = 0; i < num_connections; i++) {
        connection_t* connection = &connections[i];
        if (!connection->active && current_time - connection->last_activity > timeout) {
            remove_connection(connection->id);
            num_expired_connections++;
        }
    }

    // Unlock the mutex and return success
    pthread_mutex_unlock(&mutex);
}

// Function to query the number of active connections in the system
size_t get_num_active_connections() {
    size_t num_active_connections = 0;

    // Lock the mutex to prevent concurrent access
    pthread_mutex_lock(&mutex);

    // Iterate over all connections and count the number of active ones
    for (size_t i = 0; i < num_connections; i++) {
        if (connections[i].active) {
            num_active_connections++;
        }
    }

    // Unlock the mutex and return success
    pthread_mutex_unlock(&mutex);
    return num_active_connections;
}

// Function to notify clients when a connection is added, updated, or removed
void notify_clients(int event_type, int id) {
    // Lock the mutex to prevent concurrent access
    pthread_mutex_lock(&mutex);

    // Iterate over all connections and check if they match the given ID
    for (size_t i = 0; i < num_connections; i++) {
        connection_t* connection = &connections[i];
        if (connection->id == id) {
            switch (event_type) {
                case ADD:
                    // Notify clients that a new connection has been added
                    break;
                case UPDATE:
                    // Notify clients that an existing connection has been updated
                    break;
                case REMOVE:
                    // Notify clients that an inactive connection has been removed
                    break;
            }
        }
    }

    // Unlock the mutex and return success
    pthread_mutex_unlock(&mutex);
}
