// Define the structure for user session statistics
typedef struct UserSessionStats {
    int session_id;
    long duration;
    int activity_frequency;
    float resource_utilization;
} UserSessionStats;

// Define the linked list node for storing user session statistics
typedef struct Node {
    UserSessionStats *data;
    struct Node *next;
} Node;

// Define the memory pool structure for managing dynamic memory allocation
typedef struct MemoryPool {
    int size;
    int num_allocations;
    Node *head;
} MemoryPool;

// Define the function to manage user session statistics
void manageUserSessionStats(MemoryPool *pool, UserSessionStats *stats) {
    // Check if the input data is valid
    if (stats->session_id < 0 || stats->duration < 0 || stats->activity_frequency < 0 || stats->resource_utilization < 0) {
        printf("Invalid input data. Skipping...\n");
        return;
    }

    // Acquire the lock for modifying the linked list
    pthread_mutex_lock(&pool->lock);

    // Check if the memory pool is full
    if (pool->num_allocations == pool->size) {
        printf("Memory pool is full. Skipping...\n");
        return;
    }

    // Allocate a new node for storing the user session statistics
    Node *new_node = malloc(sizeof(Node));
    if (new_node == NULL) {
        printf("Failed to allocate memory for new node. Skipping...\n");
        return;
    }

    // Initialize the new node with the input data
    new_node->data = stats;
    new_node->next = pool->head;
    pool->head = new_node;

    // Increment the number of allocations in the memory pool
    pool->num_allocations++;

    // Release the lock for modifying the linked list
    pthread_mutex_unlock(&pool->lock);
}

// Define the function to update user session statistics
void updateUserSessionStats(MemoryPool *pool, int session_id, long duration, int activity_frequency, float resource_utilization) {
    // Acquire the lock for modifying the linked list
    pthread_mutex_lock(&pool->lock);

    // Check if the memory pool is empty
    if (pool->head == NULL) {
        printf("Memory pool is empty. Skipping...\n");
        return;
    }

    // Find the node with the matching session ID
    Node *current_node = pool->head;
    while (current_node != NULL && current_node->data->session_id != session_id) {
        current_node = current_node->next;
    }

    // Check if the node was found
    if (current_node == NULL) {
        printf("Session ID not found. Skipping...\n");
        return;
    }

    // Update the user session statistics with the new data
    current_node->data->duration = duration;
    current_node->data->activity_frequency = activity_frequency;
    current_node->data->resource_utilization = resource_utilization;

    // Release the lock for modifying the linked list
    pthread_mutex_unlock(&pool->lock);
}

// Define the function to retrieve aggregated statistics for all user sessions
void getAggregateStats(MemoryPool *pool, long *total_duration, int *total_activity_frequency, float *total_resource_utilization) {
    // Acquire the lock for reading the linked list
    pthread_mutex_lock(&pool->lock);

    // Initialize the aggregated statistics with zero values
    long total_duration = 0;
    int total_activity_frequency = 0;
    float total_resource_utilization = 0;

    // Iterate over all nodes in the linked list and calculate the aggregated statistics
    Node *current_node = pool->head;
    while (current_node != NULL) {
        total_duration += current_node->data->duration;
        total_activity_frequency += current_node->data->activity_frequency;
        total_resource_utilization += current_node->data->resource_utilization;
        current_node = current_node->next;
    }

    // Release the lock for reading the linked list
    pthread_mutex_unlock(&pool->lock);

    // Return the aggregated statistics
    *total_duration = total_duration;
    *total_activity_frequency = total_activity_frequency;
    *total_resource_utilization = total_resource_utilization;
}

// Define the function to handle memory allocation failures gracefully
void handleMemoryAllocationFailure(MemoryPool *pool) {
    // Acquire the lock for modifying the linked list
    pthread_mutex_lock(&pool->lock);

    // Check if the memory pool is full
    if (pool->num_allocations == pool->size) {
        printf("Memory pool is full. Skipping...\n");
        return;
    }

    // Find the node with the smallest duration and remove it from the linked list
    Node *current_node = pool->head;
    while (current_node != NULL && current_node->next != NULL) {
