using namespace std;

// Struct to represent a keyword and its associated context
struct KeywordContext {
  string keyword;
  set<string> context;
};

// Function to extract keywords from a log file
void extractKeywords(ifstream& infile, vector<KeywordContext>& keywords) {
  // Read the entire log file into memory
  string line;
  while (getline(infile, line)) {
    // Tokenize the line and extract keywords
    istringstream iss(line);
    string token;
    while (iss >> token) {
      if (keywords.find(token) != keywords.end()) {
        // Add the keyword to the set of contexts for that keyword
        keywords[token].context.insert(line);
      } else {
        // Create a new keyword and add it to the map
        KeywordContext kw;
        kw.keyword = token;
        kw.context.insert(line);
        keywords[token] = kw;
      }
    }
  }
}

// Function to generate a summary report for the extracted keywords
void generateReport(const vector<KeywordContext>& keywords, ofstream& outfile) {
  // Write the header for the report
  outfile << "Keyword,Frequency,Line Numbers" << endl;

