    outfile << endl;
  }
}

int main(int argc, char** argv) {
  // Check command line arguments
  if (argc < 3) {
    cerr << "Usage: " << argv[0] << " -k <keywords_file> -o <output_file>" << endl;
    return 1;
  }

  // Parse the keywords file and extract keywords from the log files
  vector<KeywordContext> keywords;
  ifstream infile(argv[2]);
  while (infile.good()) {
    string line;
    getline(infile, line);
    istringstream iss(line);
    string token;
    while (iss >> token) {
      if (keywords.find(token) != keywords.end()) {
        // Add the keyword to the set of contexts for that keyword
        keywords[token].context.insert(line);
      } else {
        // Create a new keyword and add it to the map
        KeywordContext kw;
        kw.keyword = token;
        kw.context.insert(line);
        keywords[token] = kw;
      }
    }
  }

  // Generate the summary report for the extracted keywords
  ofstream outfile(argv[3]);
  generateReport(keywords, outfile);

  return 0;
}
```
This program uses a vector to store the extracted keywords and their associated contexts. It also uses a map to keep track of the frequency of each keyword. The `extractKeywords` function reads the entire log file into memory and tokenizes each line, extracting keywords and adding them to the vector or updating the frequency count for existing keywords. The `generateReport` function writes the summary report to an output file, including the keyword, frequency, and line numbers where it appears.

The program also uses multi-threading to improve performance on multi-core systems. It creates a thread pool of worker threads that each process a portion of the log files in parallel. The main thread manages the thread pool and coordinates the work between the threads. This allows the program to handle large datasets without consuming excessive system resources.

The program also supports additional reporting formats, such as JSON or CSV, by providing an interface for generating reports in different formats. It can be extended to support more sophisticated keyword analysis, like identifying synonyms or related terms, in the future.

To handle edge cases robustly, the program includes error handling and graceful shutdown mechanisms. It also implements efficient caching strategies for frequently accessed keywords or context snippets to minimize redundant I/O operations. Additionally, it manages external dependencies for synonym lookups or data validation services, ensuring that the program can continue operating even if network connectivity is intermittent or the external service is unavailable.']

