#include <iostream>
#include <fstream>
#include <string>
#include <vector>
#include <map>
#include <set>
#include <algorithm>
#include <cassert>

using namespace std;

struct Product {
    string id;
    string name;
    string description;
    double price;
    int stock_level;
    set<string> categories;
    map<string, vector<string>> reviews;
};

class InventorySystem {
public:
    InventorySystem(const string& config_file, const string& data_file) {
        // Load configuration from file
        ifstream config_stream(config_file);
        assert(config_stream.is_open());
        config_stream >> max_products;
        config_stream.close();

        // Load initial product data from file
        ifstream data_stream(data_file);
        assert(data_stream.is_open());
        string line;
        while (getline(data_stream, line)) {
            vector<string> tokens = split(line, ',');
            Product product;
            product.id = tokens[0];
            product.name = tokens[1];
            product.description = tokens[2];
            product.price = stod(tokens[3]);
            product.stock_level = stoi(tokens[4]);
            for (int i = 5; i < tokens.size(); i++) {
                product.categories.insert(tokens[i]);
            }
            products.push_back(product);
        }
        data_stream.close();
    }

    void addProduct(const string& id, const string& name, const string& description, double price, int stock_level, const set<string>& categories) {
        Product product;
        product.id = id;
        product.name = name;
        product.description = description;
        product.price = price;
        product.stock_level = stock_level;
        product.categories = categories;
        products.push_back(product);
    }

    void modifyProduct(const string& id, const string& name, const string& description, double price, int stock_level, const set<string>& categories) {
        for (int i = 0; i < products.size(); i++) {
            if (products[i].id == id) {
                Product product = products[i];
                product.name = name;
                product.description = description;
                product.price = price;
                product.stock_level = stock_level;
                product.categories = categories;
                products[i] = product;
            }
        }
    }

    void retrieveProduct(const string& id) {
        for (int i = 0; i < products.size(); i++) {
            if (products[i].id == id) {
                cout << "Product: " << products[i].name << endl;
                cout << "Description: " << products[i].description << endl;
                cout << "Price: " << products[i].price << endl;
                cout << "Stock level: " << products[i].stock_level << endl;
                cout << "Categories: ";
                for (auto category : products[i].categories) {
                    cout << category << ", ";
                }
                cout << endl;
            }
        }
    }

    void filterProducts(const set<string>& categories, double price_range, const string& language) {
        vector<Product> filtered_products;
        for (int i = 0; i < products.size(); i++) {
            if (categories.empty() || products[i].categories.find(categories) != products[i].categories.end()) {
                if (price_range == -1 || (products[i].price >= price_range && products[i].price <= price_range)) {
                    if (language.empty() || products[i].reviews.find(language) != products[i].reviews.end()) {
                        filtered_products.push_back(products[i]);
                    }
                }
            }
        }
        cout << "Filtered products: ";
        for (int i = 0; i < filtered_products.size(); i++) {
            cout << filtered_products[i].name << ", ";
        }
        cout << endl;
    }

private:
    vector<Product> products;
    int max_products;
};

int main(int argc, char** argv) {
    if (argc < 3) {
        cerr << "Usage: inventory_system --help | -c <config_file> -d <data_file>" << endl;
        return 1;
    }

    string config_file, data_file;
    for (int i = 1; i < argc; i++) {
        if (strcmp(argv[i], "--help") == 0) {
            cout << "Usage: inventory_system --help | -c <config_file> -d <data_file>" << endl;
            return 1;
        } else if (strcmp(argv[i], "-c") == 0 && i + 1 < argc) {
            config_file = argv[i + 1];
        } else if (strcmp(argv[i], "-d") == 0 && i + 1 < argc) {
