// Custom data structure to store network interface statistics
typedef struct NetworkInterfaceStats {
    char *interface_name;
    int packet_loss;
    long throughput;
    long latency;
} NetworkInterfaceStats;

// Thread-safe data structure for managing the dynamic array of interface stats
typedef struct InterfaceStatsArray {
    NetworkInterfaceStats **stats;
    size_t capacity;
    size_t count;
    pthread_mutex_t mutex;
} InterfaceStatsArray;

// Initialize a new instance of the interface stats array
void init_interface_stats_array(InterfaceStatsArray *arr) {
    arr->stats = NULL;
    arr->capacity = 0;
    arr->count = 0;
    pthread_mutex_init(&arr->mutex, NULL);
}

// Add a new interface stats to the array
void add_interface_stats(InterfaceStatsArray *arr, const char *interface_name) {
    NetworkInterfaceStats *new_stats = malloc(sizeof(NetworkInterfaceStats));
    if (!new_stats) {
        perror("Failed to allocate memory for new interface stats");
        return;
    }
    new_stats->interface_name = strdup(interface_name);
    new_stats->packet_loss = 0;
    new_stats->throughput = 0;
    new_stats->latency = 0;
    pthread_mutex_lock(&arr->mutex);
    if (arr->count == arr->capacity) {
        // Resize the array if it's full
        arr->capacity *= 2;
        NetworkInterfaceStats **new_stats = realloc(arr->stats, sizeof(NetworkInterfaceStats *) * arr->capacity);
        if (!new_stats) {
            perror("Failed to resize interface stats array");
            pthread_mutex_unlock(&arr->mutex);
            return;
        }
        arr->stats = new_stats;
    }
    arr->stats[arr->count++] = new_stats;
    pthread_mutex_unlock(&arr->mutex);
}

// Update an existing interface stats in the array
void update_interface_stats(InterfaceStatsArray *arr, const char *interface_name) {
    NetworkInterfaceStats *stats = get_interface_stats(arr, interface_name);
    if (!stats) {
        return;
    }
    // Update the stats with new values
}

// Get an existing interface stats from the array
NetworkInterfaceStats *get_interface_stats(InterfaceStatsArray *arr, const char *interface_name) {
    pthread_mutex_lock(&arr->mutex);
    for (size_t i = 0; i < arr->count; i++) {
        if (!strcmp(arr->stats[i]->interface_name, interface_name)) {
            return arr->stats[i];
        }
    }
    pthread_mutex_unlock(&arr->mutex);
    return NULL;
}

// Delete an existing interface stats from the array
void delete_interface_stats(InterfaceStatsArray *arr, const char *interface_name) {
    NetworkInterfaceStats *stats = get_interface_stats(arr, interface_name);
    if (!stats) {
        return;
    }
    pthread_mutex_lock(&arr->mutex);
    for (size_t i = 0; i < arr->count; i++) {
        if (arr->stats[i] == stats) {
            // Remove the stats from the array
            break;
        }
    }
    pthread_mutex_unlock(&arr->mutex);
}

// Retrieve aggregated statistics for all interfaces in the array
void get_aggregate_stats(InterfaceStatsArray *arr, long *packet_loss, long *throughput, long *latency) {
    pthread_mutex_lock(&arr->mutex);
    *packet_loss = 0;
    *throughput = 0;
    *latency = 0;
    for (size_t i = 0; i < arr->count; i++) {
        *packet_loss += arr->stats[i]->packet_loss;
        *throughput += arr->stats[i]->throughput;
        *latency += arr->stats[i]->latency;
    }
    pthread_mutex_unlock(&arr->mutex);
}
