using System;
using System.IO;
using System.Text;
using OpenSSL;
using CustomLoggingLibrary;

public class FileAnalyzer
{
    private int _minValue;
    private int _maxValue;
    private bool _verboseMode;
    private string _outputFilePath;
    private bool _compressOutput;
    private bool _manPage;
    private readonly OpenSSL.Cipher _cipher;
    private readonly CustomLoggingLibrary.Logger _logger;

    public FileAnalyzer(string[] args)
    {
        ParseCommandLineArguments(args);
        _cipher = new OpenSSL.Cipher();
        _logger = new CustomLoggingLibrary.Logger();
    }

    private void ParseCommandLineArguments(string[] args)
    {
        for (int i = 0; i < args.Length; i++)
        {
            switch (args[i])
            {
                case "-v":
                    _verboseMode = true;
                    break;
                case "-o":
                    if (i + 1 < args.Length)
                    {
                        _outputFilePath = args[i + 1];
                    }
                    else
                    {
                        throw new ArgumentException("Missing output file path");
                    }
                    break;
                case "-cs":
                    _compressOutput = true;
                    break;
                case "--manpage":
                    _manPage = true;
                    break;
            }
        }
    }

    public void AnalyzeFile(string filePath)
    {
        if (_verboseMode)
        {
            _logger.Log("Analyzing file: " + filePath);
        }

        using (var reader = new StreamReader(filePath))
        {
            int lineCount = 0;
            int wordCount = 0;
            int characterCount = 0;

            string line;
            while ((line = reader.ReadLine()) != null)
            {
                lineCount++;
                wordCount += line.Split(' ').Length;
                characterCount += line.Length;
            }

            if (_verboseMode)
            {
                _logger.Log("File stats:");
                _logger.Log("  - Lines: " + lineCount);
                _logger.Log("  - Words: " + wordCount);
                _logger.Log("  - Characters: " + characterCount);
            }

            if (_compressOutput)
            {
                var compressedData = Compress(lineCount, wordCount, characterCount);
                WriteToFile(_outputFilePath, compressedData);
            }
            else
            {
                WriteToFile(_outputFilePath, lineCount + " " + wordCount + " " + characterCount);
            }
        }
    }

    private byte[] Compress(int lineCount, int wordCount, int characterCount)
    {
        var data = new byte[10];
        data[0] = (byte)(lineCount >> 24);
        data[1] = (byte)(lineCount >> 16);
        data[2] = (byte)(lineCount >> 8);
        data[3] = (byte)lineCount;
        data[4] = (byte)(wordCount >> 24);
        data[5] = (byte)(wordCount >> 16);
        data[6] = (byte)(wordCount >> 8);
        data[7] = (byte)wordCount;
        data[8] = (byte)(characterCount >> 24);
        data[9] = (byte)(characterCount >> 16);
        return data;
    }

    private void WriteToFile(string filePath, byte[] data)
    {
        using (var writer = new BinaryWriter(new FileStream(filePath, FileMode.Create)))
        {
            writer.Write(data);
        }
    }

    public int GenerateRandomValue(int minValue, int maxValue)
    {
        if (minValue > maxValue)
        {
            throw new ArgumentException("Min value cannot be greater than max value");
        }

        var random = new Random();
        return random.Next(minValue, maxValue + 1);
    }

    public void AdjustRange(int minValue, int maxValue)
    {
        if (minValue > maxValue)
        {
            throw new ArgumentException("Min value cannot be greater than max value");
        }

        _minValue = minValue;
        _maxValue = maxValue;
    }

    public void ResetRange()
    {
        _minValue = int.MinValue;
        _maxValue = int.MaxValue;
    }

    public bool ValidateRange(int minValue, int maxValue)
    {
        if (minValue > maxValue)
        {
            return false;
        }

        return true;
    }

    public override string ToString()
    {
        return "[" + _minValue + ", " + _maxValue + "]";
    }
}
