    size_t length;
    off_t offset;
} Pattern;

// Define a function to read the list of byte patterns from a file
static bool readPatterns(const char *filename, Pattern **patterns) {
    // Open the file for reading
    int fd = open(filename, O_RDONLY);
    if (fd == -1) {
        perror("Error opening patterns file");
        return false;
    }

    // Read the contents of the file into a buffer
    char *buffer = malloc(sizeof(char) * 4096);
    size_t bytesRead = read(fd, buffer, 4096);
    if (bytesRead == -1) {
        perror("Error reading patterns file");
        close(fd);
        return false;
    }

    // Close the file
    close(fd);

    // Parse the contents of the buffer into a list of byte patterns
    *patterns = malloc(sizeof(Pattern) * 1024);
    size_t numPatterns = 0;
    char *token = strtok(buffer, "\n");
    while (token != NULL) {
        // Parse the token into a byte pattern
        unsigned char *pattern = malloc(sizeof(unsigned char) * 1024);
        size_t length = 0;
        for (size_t i = 0; i < strlen(token); i++) {
            if (isxdigit(token[i])) {
                pattern[length] = (unsigned char)(strtol(&token[i], NULL, 16));
                length++;
            }
        }

        // Add the byte pattern to the list of patterns
        (*patterns)[numPatterns].pattern = pattern;
        (*patterns)[numPatterns].length = length;
        numPatterns++;

        // Get the next token
        token = strtok(NULL, "\n");
    }

    // Free the buffer
    free(buffer);

    return true;
}

// Define a function to process a binary file for pattern matching
static void processFile(const char *filename, Pattern *patterns, size_t numPatterns) {
    // Open the file for reading
    int fd = open(filename, O_RDONLY);
    if (fd == -1) {
        perror("Error opening input file");
        return;
    }

    // Read the contents of the file into a buffer
    char *buffer = malloc(sizeof(char) * 4096);
    size_t bytesRead = read(fd, buffer, 4096);
    if (bytesRead == -1) {
        perror("Error reading input file");
        close(fd);
        return;
    }

    // Close the file
    close(fd);

    // Search for each pattern in the buffer and generate a report
    for (size_t i = 0; i < numPatterns; i++) {
        unsigned char *pattern = patterns[i].pattern;
        size_t length = patterns[i].length;
        off_t offset = 0;
        while ((offset = memmem(buffer + offset, bytesRead - offset, pattern, length)) != NULL) {
            // Print the offset position and surrounding context
            printf("%s: %ld\n", filename, (long)(offset + patterns[i].offset));
            for (size_t j = 0; j < 16; j++) {
                if (j == 8) {
                    printf(" ");
                }
                if (offset - 16 + j >= 0 && offset - 16 + j < bytesRead) {
                    printf("%02x ", buffer[offset - 16 + j]);
                } else {
                    printf("   ");
                }
            }
            for (size_t j = 0; j < length; j++) {
                printf("%02x", pattern[j]);
            }
            printf("\n");

            // Update the offset position for the next search
            offset += length;
        }
    }

    // Free the buffer
    free(buffer);
}

// Define a function to generate a summary report of the pattern matches
static void generateReport(const char *filename, Pattern *patterns, size_t numPatterns) {
    // Open the output file for writing
    int fd = open(filename, O_WRONLY | O_CREAT | O_TRUNC, 0644);
    if (fd == -1) {
        perror("Error opening output file");
        return;
    }

    // Write the header of the report
    char *header = "Offset\tPattern\n";
    write(fd, header, strlen(header));

    // Process each input file for pattern matching and generate a report
    for (size_t i = 0; i < numPatterns; i++) {
        processFile(patterns[i].filename, patterns + i, 1);
    }

    // Close the output file
    close(fd);
}

int main(int argc, char *argv[]) {
    // Check for command line options
    if (argc < 2) {
        printf("Usage: %s [options]...\n", argv[0]);
        return 1;
    }

    // Parse the command line options
    Pattern *patterns = NULL;
    size_t numPatterns = 0;
    const char *outputFile = NULL;
    for (int i = 1; i < argc; i++) {
        if (!strcmp(argv[i], OPTION_HELP)) {
            printf("Usage: %s [options]...\n", argv[0]);
            return 0;
        } else if (!strncmp(argv[i], OPTION_PATTERNS, strlen(OPTION_PATTERNS))) {
            readPatterns(argv[i] + strlen(OPTION_PATTERNS), &patterns);
            numPatterns = 1;
        } else if (!strncmp(argv[i], OPTION_OUTPUT, strlen(OPTION_OUTPUT))) {
            outputFile = argv[i] + strlen(OPTION_OUTPUT);
        }
    }

    // Check for required command line options
    if (patterns == NULL || numPatterns == 0) {
        printf("Error: Missing required option --patterns\n");
        return 1;
    }

    // Generate the summary report of pattern matches
    generateReport(outputFile, patterns, numPatterns);

    return 0;
}']

