#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <ctype.h>
#include <assert.h>
#include <math.h>
#include <time.h>
#include <sys/stat.h>
#include <unistd.h>
#include <stdbool.h>
#include <limits.h>
#include <errno.h>
#include <getopt.h>

#define MAX_FILENAME_LENGTH 256
#define DEFAULT_OUTPUT_FILE "word_frequencies.txt"
#define DEFAULT_NUM_WORDS 10
#define MIN_WORD_LENGTH 3
#define MAX_WORD_LENGTH 25
#define LOGGING_LEVEL 2

// Struct to store word frequencies and their counts
typedef struct {
    char *word;
    int count;
} WordFrequency;

// Function to read a file and return its contents as a string
char *readFile(const char *filename) {
    FILE *file = fopen(filename, "r");
    if (file == NULL) {
        perror("Error opening file");
        exit(EXIT_FAILURE);
    }

    // Get the size of the file
    fseek(file, 0, SEEK_END);
    long fileSize = ftell(file);
    rewind(file);

    // Allocate memory for the contents of the file and read it in
    char *buffer = malloc(fileSize + 1);
    if (buffer == NULL) {
        perror("Error allocating memory");
        exit(EXIT_FAILURE);
    }
    fread(buffer, fileSize, 1, file);
    buffer[fileSize] = '\0';

    // Close the file and return the contents
    fclose(file);
    return buffer;
}

// Function to tokenize a string into individual words
char **tokenizeString(const char *string) {
    int numWords = 0;
    for (int i = 0; i < strlen(string); i++) {
        if (isspace(string[i])) {
            numWords++;
        }
    }

    // Allocate memory for the words and tokenize the string
    char **words = malloc((numWords + 1) * sizeof(char*));
    int wordStart = 0;
    int wordEnd = 0;
    for (int i = 0; i < strlen(string); i++) {
        if (!isspace(string[i])) {
            wordEnd++;
        } else {
            words[numWords] = malloc((wordEnd - wordStart + 1) * sizeof(char));
            memcpy(words[numWords], string + wordStart, wordEnd - wordStart);
            words[numWords][wordEnd - wordStart] = '\0';
            numWords++;
            wordStart = i + 1;
            wordEnd = 0;
        }
    }

    // Add the last word to the list of words
    words[numWords] = malloc((wordEnd - wordStart + 1) * sizeof(char));
    memcpy(words[numWords], string + wordStart, wordEnd - wordStart);
    words[numWords][wordEnd - wordStart] = '\0';
    numWords++;

    return words;
}

// Function to calculate the frequency of a word in a list of words
int getWordFrequency(char *word, char **words) {
    int count = 0;
    for (int i = 0; i < strlen(words); i++) {
        if (strcmp(word, words[i]) == 0) {
            count++;
        }
    }
    return count;
}

// Function to sort a list of word frequencies by frequency descending
void sortWordFrequencies(WordFrequency *frequencies, int numWords) {
    for (int i = 0; i < numWords - 1; i++) {
        for (int j = i + 1; j < numWords; j++) {
            if (frequencies[i].count < frequencies[j].count) {
                WordFrequency temp = frequencies[i];
                frequencies[i] = frequencies[j];
                frequencies[j] = temp;
            }
        }
    }
}

// Function to print the top N most frequently occurring words and their counts
void printTopWords(WordFrequency *frequencies, int numWords) {
    for (int i = 0; i < numWords; i++) {
        printf("%s: %d\n", frequencies[i].word, frequencies[i].count);
    }
}

// Main function to read multiple text files and aggregate word frequencies
int main(int argc, char **argv) {
    // Parse command line arguments
    const char *outputFile = DEFAULT_OUTPUT_FILE;
    int numWords = DEFAULT_NUM_WORDS;
    bool help = false;
    for (int i = 0; i < argc; i++) {
        if (strcmp(argv[i], "--help") == 0) {
            help = true;
        } else if (strcmp(argv[i], "-o") == 0 && i + 1 < argc) {
            outputFile = argv[i + 1];
        } else if (strcmp(argv[i], "-c") == 0 && i + 1 < argc) {
            numWords = atoi(argv[i + 1]);
        }
    }

    // Print help message and exit if requested
    if (help) {
        printf("Usage: %s [-o output_file] [-c num_words] [input_files...]\n", argv[0]);
        return EXIT_SUCCESS;
    }

    // Read input files and aggregate word frequencies
    int numFiles = argc - 1;
    WordFrequency *frequencies = malloc(numWords * sizeof(WordFrequency));
    for (int i = 0; i < numFiles; i++) {
        char *filename = argv[i + 1];
        char *fileContents = readFile(filename);
        char **words = tokenizeString(fileContents);
        free(fileContents);

        // Calculate word frequencies and sort them
        for (int j = 0; j < numWords; j++) {
            WordFrequency frequency = { words[j], getWordFrequency(words[j], words) };
            frequencies[j] = frequency;
        }
        sortWordFrequencies(frequencies, numWords);
    }

    // Print the top N most frequently occurring words and their counts
    printTopWords(frequencies, numWords);

    // Clean up memory
    for (int i = 0; i < numFiles; i++) {
        free(argv[i + 1]);
    }
    free(frequencies);

    return EXIT_SUCCESS;
}']

