#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <unistd.h>
#include <sys/time.h>

// Custom hash table implementation
struct HashTable {
    int size;
    struct Node **nodes;
};

struct Node {
    void *key;
    void *value;
    struct Node *next;
};

struct Cache {
    struct HashTable *hash_table;
    pthread_mutex_t mutex;
    int size;
    int max_size;
    int current_size;
    int eviction_policy;
    int lru_policy;
    int timeout;
};

struct CacheNode {
    struct Node *node;
    struct CacheNode *next;
};

// Hash table functions
int hash(void *key) {
    // Simple hash function for demonstration purposes only
    return (int) key % 100;
}

struct Node *create_node(void *key, void *value) {
    struct Node *node = malloc(sizeof(struct Node));
    node->key = key;
    node->value = value;
    node->next = NULL;
    return node;
}

struct HashTable *create_hash_table(int size) {
    struct HashTable *hash_table = malloc(sizeof(struct HashTable));
    hash_table->size = size;
    hash_table->nodes = calloc(size, sizeof(struct Node*));
    return hash_table;
}

void destroy_node(struct Node *node) {
    free(node);
}

void destroy_hash_table(struct HashTable *hash_table) {
    for (int i = 0; i < hash_table->size; i++) {
        struct Node *node = hash_table->nodes[i];
        while (node != NULL) {
            struct Node *next = node->next;
            destroy_node(node);
            node = next;
        }
    }
    free(hash_table->nodes);
    free(hash_table);
}

// Cache functions
struct Cache *create_cache(int size, int max_size, int eviction_policy, int lru_policy) {
    struct Cache *cache = malloc(sizeof(struct Cache));
    cache->hash_table = create_hash_table(size);
    cache->mutex = PTHREAD_MUTEX_INITIALIZER;
    cache->size = size;
    cache->max_size = max_size;
    cache->current_size = 0;
    cache->eviction_policy = eviction_policy;
    cache->lru_policy = lru_policy;
    return cache;
}

void destroy_cache(struct Cache *cache) {
    pthread_mutex_destroy(&cache->mutex);
    destroy_hash_table(cache->hash_table);
    free(cache);
}

int get_cache_size(struct Cache *cache) {
    return cache->current_size;
}

void set_cache_size(struct Cache *cache, int size) {
    cache->max_size = size;
}

void add_to_cache(struct Cache *cache, void *key, void *value) {
    pthread_mutex_lock(&cache->mutex);
    struct Node *node = create_node(key, value);
    int hash = hash(key);
    struct Node **nodes = &cache->hash_table->nodes[hash];
    while (*nodes != NULL) {
        nodes = &(*nodes)->next;
    }
    *nodes = node;
    cache->current_size++;
    pthread_mutex_unlock(&cache->mutex);
}

void *get_from_cache(struct Cache *cache, void *key) {
    pthread_mutex_lock(&cache->mutex);
    int hash = hash(key);
    struct Node **nodes = &cache->hash_table->nodes[hash];
    while (*nodes != NULL && (*nodes)->key != key) {
        nodes = &(*nodes)->next;
    }
    if (*nodes == NULL) {
        pthread_mutex_unlock(&cache->mutex);
        return NULL;
    }
    void *value = (*nodes)->value;
    pthread_mutex_unlock(&cache->mutex);
    return value;
}

void remove_from_cache(struct Cache *cache, void *key) {
    pthread_mutex_lock(&cache->mutex);
    int hash = hash(key);
    struct Node **nodes = &cache->hash_table->nodes[hash];
    while (*nodes != NULL && (*nodes)->key != key) {
        nodes = &(*nodes)->next;
    }
    if (*nodes == NULL) {
        pthread_mutex_unlock(&cache->mutex);
        return;
    }
    struct Node *node = *nodes;
    *nodes = node->next;
    destroy_node(node);
    cache->current_size--;
    pthread_mutex_unlock(&cache->mutex);
}
```
This implementation uses a custom hash table to store the cache entries, with each entry containing a key and a value. The `add_to_cache` function adds a new entry to the cache, while the `get_from_cache` function retrieves an existing entry from the cache. The `remove_from_cache` function removes an existing entry from the cache.

The cache size is limited by the maximum size specified when creating the cache, and the eviction policy can be set to either LRU (Least Recently Used) or FIFO (First In First Out). When the cache reaches its maximum size, the least recently used entries are removed first.

The `get_cache_size` function returns the current size of the cache, while the `set_cache_size` function sets the maximum size of the cache.

The `add_to_cache` and `remove_from_cache` functions use a mutex to ensure that only one thread can access the cache at a time, preventing race conditions and data corruption. The `get_from_cache` function uses a similar approach to retrieve an entry from the cache while avoiding race conditions.

The `destroy_cache` function destroys the cache and frees all memory allocated for it."]

