typedef struct NetworkInterfaceStats {
    char *interface_name;
    int packet_loss;
    long throughput;
    long latency;
} NetworkInterfaceStats;

// Define a dynamic array to store the network interface statistics
typedef struct NetworkInterfaceStatsArray {
    NetworkInterfaceStats **stats;
    size_t capacity;
    size_t count;
    pthread_mutex_t mutex;
} NetworkInterfaceStatsArray;

// Initialize the dynamic array with a given initial capacity
void network_interface_stats_array_init(NetworkInterfaceStatsArray *arr, size_t init_capacity) {
    arr->stats = malloc(sizeof(NetworkInterfaceStats *) * init_capacity);
    arr->capacity = init_capacity;
    arr->count = 0;
    pthread_mutex_init(&arr->mutex, NULL);
}

// Add a new network interface statistics to the dynamic array
void network_interface_stats_array_add(NetworkInterfaceStatsArray *arr, NetworkInterfaceStats *stats) {
    // Acquire the mutex lock before modifying the array
    pthread_mutex_lock(&arr->mutex);

    // Check if the array needs to be resized
    if (arr->count == arr->capacity) {
        size_t new_capacity = arr->capacity * 2;
        NetworkInterfaceStats **new_stats = realloc(arr->stats, sizeof(NetworkInterfaceStats *) * new_capacity);
        if (!new_stats) {
            // Handle memory allocation failure gracefully
            pthread_mutex_unlock(&arr->mutex);
            return;
        }
        arr->stats = new_stats;
        arr->capacity = new_capacity;
    }

    // Add the new network interface statistics to the array
    arr->stats[arr->count++] = stats;

    // Release the mutex lock after modifying the array
    pthread_mutex_unlock(&arr->mutex);
}

// Update an existing network interface statistics in the dynamic array
void network_interface_stats_array_update(NetworkInterfaceStatsArray *arr, NetworkInterfaceStats *stats) {
    // Acquire the mutex lock before modifying the array
    pthread_mutex_lock(&arr->mutex);

    // Find the index of the existing network interface statistics
    size_t i;
    for (i = 0; i < arr->count; i++) {
        if (strcmp(stats->interface_name, arr->stats[i]->interface_name) == 0) {
            break;
        }
    }

    // Update the existing network interface statistics
    if (i < arr->count) {
        arr->stats[i] = stats;
    } else {
        // Handle invalid input gracefully
        pthread_mutex_unlock(&arr->mutex);
        return;
    }

    // Release the mutex lock after modifying the array
    pthread_mutex_unlock(&arr->mutex);
}

// Retrieve aggregated statistics for all network interfaces in the dynamic array
void network_interface_stats_array_get_aggregate(NetworkInterfaceStatsArray *arr, NetworkInterfaceStats *aggregate) {
    // Acquire the mutex lock before reading the array
    pthread_mutex_lock(&arr->mutex);

    // Initialize the aggregate statistics with zero values
    memset(aggregate, 0, sizeof(NetworkInterfaceStats));

    // Iterate over all network interface statistics in the array
    for (size_t i = 0; i < arr->count; i++) {
        NetworkInterfaceStats *stats = arr->stats[i];
        aggregate->packet_loss += stats->packet_loss;
        aggregate->throughput += stats->throughput;
        aggregate->latency += stats->latency;
    }

    // Release the mutex lock after reading the array
    pthread_mutex_unlock(&arr->mutex);
}
