// Define the structure for a TIDB_ROW_RECORD
typedef struct {
    int row_id;
    char* column_values;
    time_t timestamp;
} TIDB_ROW_RECORD;

// Define the list of TIDB_ROW_RECORD structures
static pthread_mutex_t list_lock = PTHREAD_MUTEX_INITIALIZER;
static TIDB_ROW_RECORD* list = NULL;
static int list_size = 0;

// Function to initialize and populate the list of TIDB_ROW_RECORD structures
void init_list(int size) {
    // Acquire the lock on the list
    pthread_mutex_lock(&list_lock);

    // Allocate memory for the list
    list = (TIDB_ROW_RECORD*)malloc(size * sizeof(TIDB_ROW_RECORD));
    if (!list) {
        perror("Failed to allocate memory for list");
        exit(1);
    }

    // Initialize the list with default values
    for (int i = 0; i < size; i++) {
        list[i].row_id = -1;
        list[i].column_values = NULL;
        list[i].timestamp = time(NULL);
    }

    // Set the size of the list
    list_size = size;

    // Release the lock on the list
    pthread_mutex_unlock(&list_lock);
}

// Function to add a new TIDB_ROW_RECORD structure to the list
void add_record(int row_id, char* column_values) {
    // Acquire the lock on the list
    pthread_mutex_lock(&list_lock);

    // Check if the list is full
    if (list_size == 0) {
        perror("List is full");
        exit(1);
    }

    // Find the first empty slot in the list
    int i;
    for (i = 0; i < list_size && list[i].row_id != -1; i++) {}

    // Add the new record to the list
    list[i].row_id = row_id;
    list[i].column_values = column_values;
    list[i].timestamp = time(NULL);

    // Release the lock on the list
    pthread_mutex_unlock(&list_lock);
}

// Function to remove a TIDB_ROW_RECORD structure from the list
void remove_record(int row_id) {
    // Acquire the lock on the list
    pthread_mutex_lock(&list_lock);

    // Find the record in the list
    int i;
    for (i = 0; i < list_size && list[i].row_id != row_id; i++) {}

    // Check if the record was found
    if (i == list_size) {
        perror("Record not found");
        exit(1);
    }

    // Remove the record from the list
    list[i].row_id = -1;
    list[i].column_values = NULL;
    list[i].timestamp = time(NULL);

    // Release the lock on the list
    pthread_mutex_unlock(&list_lock);
}

// Function to retrieve a TIDB_ROW_RECORD structure from the list
TIDB_ROW_RECORD* get_record(int row_id) {
    // Acquire the lock on the list
    pthread_mutex_lock(&list_lock);

    // Find the record in the list
    int i;
    for (i = 0; i < list_size && list[i].row_id != row_id; i++) {}

    // Check if the record was found
    if (i == list_size) {
        perror("Record not found");
        exit(1);
    }

    // Return a copy of the record
    TIDB_ROW_RECORD* record = malloc(sizeof(TIDB_ROW_RECORD));
    memcpy(record, &list[i], sizeof(TIDB_ROW_RECORD));

    // Release the lock on the list
    pthread_mutex_unlock(&list_lock);

    return record;
}

// Function to update a TIDB_ROW_RECORD structure in the list
void update_record(int row_id, char* column_values) {
    // Acquire the lock on the list
    pthread_mutex_lock(&list_lock);

    // Find the record in the list
    int i;
    for (i = 0; i < list_size && list[i].row_id != row_id; i++) {}

    // Check if the record was found
    if (i == list_size) {
        perror("Record not found");
        exit(1);
    }

    // Update the record in the list
    list[i].column_values = column_values;
    list[i].timestamp = time(NULL);

    // Release the lock on the list
    pthread_mutex_unlock(&list_lock);
}

// Function to clear the list of TIDB_ROW_RECORD structures
void clear_list() {
    // Acquire the lock on the list
    pthread_mutex_lock(&list_lock);

    // Free the memory allocated for the list
    free(list);
    list = NULL;
    list_size = 0;

    // Release the lock on the list
    pthread_mutex_unlock(&list_lock);
}
