#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <semaphore.h>
#include <unistd.h>
#include <sys/time.h>
#include <sys/resource.h>

// Custom memory pool for efficient allocation and deallocation of NetworkInterfaceStats structures
struct MemoryPool {
    size_t capacity; // Total number of elements in the pool
    size_t size; // Current number of used elements in the pool
    struct NetworkInterfaceStats* elements; // Array of NetworkInterfaceStats structures
};

// Custom data structure for storing network interface statistics
struct NetworkInterfaceStats {
    char* ifaceName; // Name of the network interface
    double packetLoss; // Packet loss percentage
    double throughput; // Throughput in bytes per second
    double latency; // Latency in milliseconds
};

// Global variables for managing the memory pool and synchronization
struct MemoryPool* pool = NULL;
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
sem_t semaphore = SEM_INITIALIZER(0);

// Function to initialize the memory pool with a given capacity
void initMemoryPool(size_t capacity) {
    pool = malloc(sizeof(struct MemoryPool));
    if (pool == NULL) {
        perror("malloc");
        exit(EXIT_FAILURE);
    }
    pool->capacity = capacity;
    pool->size = 0;
    pool->elements = calloc(capacity, sizeof(struct NetworkInterfaceStats));
    if (pool->elements == NULL) {
        perror("calloc");
        exit(EXIT_FAILURE);
    }
}

// Function to add a new network interface statistics entry to the pool
void addNetworkInterfaceStats(char* ifaceName, double packetLoss, double throughput, double latency) {
    // Validate input data before adding it to the pool
    if (ifaceName == NULL || packetLoss < 0.0 || throughput < 0.0 || latency < 0.0) {
        fprintf(stderr, "Invalid input data for network interface statistics\n");
        return;
    }

    // Acquire the mutex to ensure thread-safe access to the pool
    pthread_mutex_lock(&mutex);

    // Check if the memory pool needs to be resized
    if (pool->size == pool->capacity) {
        size_t newCapacity = pool->capacity * 2;
        struct NetworkInterfaceStats* newElements = realloc(pool->elements, newCapacity * sizeof(struct NetworkInterfaceStats));
        if (newElements == NULL) {
            perror("realloc");
            exit(EXIT_FAILURE);
        }
        pool->capacity = newCapacity;
        pool->elements = newElements;
    }

    // Add the new network interface statistics entry to the pool
    struct NetworkInterfaceStats* stats = &pool->elements[pool->size++];
    stats->ifaceName = ifaceName;
    stats->packetLoss = packetLoss;
    stats->throughput = throughput;
    stats->latency = latency;

    // Release the mutex to allow other threads to access the pool
    pthread_mutex_unlock(&mutex);
}

// Function to update an existing network interface statistics entry in the pool
void updateNetworkInterfaceStats(char* ifaceName, double packetLoss, double throughput, double latency) {
    // Validate input data before updating it in the pool
    if (ifaceName == NULL || packetLoss < 0.0 || throughput < 0.0 || latency < 0.0) {
        fprintf(stderr, "Invalid input data for network interface statistics\n");
        return;
    }

    // Acquire the mutex to ensure thread-safe access to the pool
    pthread_mutex_lock(&mutex);

    // Find the existing entry in the pool and update its values
    struct NetworkInterfaceStats* stats = NULL;
    for (size_t i = 0; i < pool->size; i++) {
        if (strcmp(pool->elements[i].ifaceName, ifaceName) == 0) {
            stats = &pool->elements[i];
            break;
        }
    }
    if (stats != NULL) {
        stats->packetLoss = packetLoss;
        stats->throughput = throughput;
        stats->latency = latency;
    } else {
        fprintf(stderr, "Network interface statistics entry not found\n");
    }

    // Release the mutex to allow other threads to access the pool
    pthread_mutex_unlock(&mutex);
}

// Function to retrieve aggregated network interface statistics for all interfaces in the pool
void getAggregateNetworkInterfaceStats(struct NetworkInterfaceStats* stats) {
    // Acquire the mutex to ensure thread-safe access to the pool
    pthread_mutex_lock(&mutex);

    // Initialize the output structure with zero values
    memset(stats, 0, sizeof(struct NetworkInterfaceStats));

    // Iterate over all entries in the pool and update the aggregated statistics
    for (size_t i = 0; i < pool->size; i++) {
        struct NetworkInterfaceStats* entry = &pool->elements[i];
        stats->packetLoss += entry->packetLoss;
        stats->throughput += entry->throughput;
        stats->latency += entry->latency;
    }

    // Release the mutex to allow other threads to access the pool
    pthread_mutex_unlock(&mutex);
}

// Function to clean up the memory pool and release all resources
void destroyMemoryPool() {
    free(pool->elements);
    free(pool);
}
