#define VERBOSITY_INFO 1
#define VERBOSITY_WARNING 2
#define VERBOSITY_ERROR 3

// Define the log level for the program
#define LOG_LEVEL VERBOSITY_INFO

// Define the configuration file path
char *config_file_path = NULL;

// Define the verbosity flag
