        this.loggingEnabled = true;
    }

    public void disableLogging() {
        this.loggingFile = null;
        this.loggingEnabled = false;
    }

    private void log(String message, Level level) {
        if (loggingEnabled && loggingFile != null) {
            try {
                Files.write(Paths.get(loggingFile.getAbsolutePath()), message.getBytes(), StandardOpenOption.APPEND);
            } catch (IOException e) {
                LOGGER.log(Level.SEVERE, "Failed to write log message", e);
            }
        }
    }

