    if (cache->size < cache->capacity) {
        cache->objects[cache->size++] = object;
    } else {
        // Evict the least recently used object if necessary
        evict_object(cache, 0);
        cache->objects[cache->size++] = object;
    }
    pthread_mutex_unlock(&cache->mutex);
}

// Get an object from the cache by its ID
CUSTOM_OBJECT *get_object(CACHE *cache, int id) {
    pthread_mutex_lock(&cache->mutex);
    for (size_t i = 0; i < cache->size; i++) {
        if (cache->objects[i]->OBJECT_ID == id) {
            // Update the timestamp of the object
            cache->objects[i]->CURRENT_TIMESTAMP = time(NULL);
            pthread_mutex_unlock(&cache->mutex);
            return cache->objects[i];
        }
    }
    pthread_mutex_unlock(&cache->mutex);
    return NULL;
}

// Evict an object from the cache by its ID
void evict_object(CACHE *cache, int id) {
    pthread_mutex_lock(&cache->mutex);
    for (size_t i = 0; i < cache->size; i++) {
        if (cache->objects[i]->OBJECT_ID == id) {
            // Remove the object from the cache
            cache->objects[i] = NULL;
            cache->size--;
            pthread_mutex_unlock(&cache->mutex);
            return;
        }
    }
    pthread_mutex_unlock(&cache->mutex);
}

// Evict the least recently used object from the cache
void evict_lru(CACHE *cache) {
    pthread_mutex_lock(&cache->mutex);
    size_t lru = 0;
    time_t min_timestamp = time(NULL);
    for (size_t i = 0; i < cache->size; i++) {
        if (cache->objects[i]->CURRENT_TIMESTAMP < min_timestamp) {
            lru = i;
            min_timestamp = cache->objects[i]->CURRENT_TIMESTAMP;
        }
    }
    // Remove the object from the cache
    cache->objects[lru] = NULL;
    cache->size--;
    pthread_mutex_unlock(&cache->mutex);
}

// Evict the least frequently used object from the cache
void evict_lfu(CACHE *cache) {
    pthread_mutex_lock(&cache->mutex);
    size_t lfu = 0;
    int min_frequency = INT_MAX;
    for (size_t i = 0; i < cache->size; i++) {
        if (cache->objects[i]->frequency < min_frequency) {
            lfu = i;
            min_frequency = cache->objects[i]->frequency;
        }
    }
    // Remove the object from the cache
    cache->objects[lfu] = NULL;
    cache->size--;
    pthread_mutex_unlock(&cache->mutex);
}

// Clear the entire cache and reset its state
