// Define the structure for a custom object
typedef struct {
    int object_id;
    void* resource;
    time_t current_timestamp;
} custom_object_t;

// Define the cache structure
typedef struct {
    // The hash table to store the objects
    custom_object_t** objects;
    // The number of objects in the cache
    int num_objects;
    // The maximum size of the cache
    int max_size;
    // The current size of the cache
    int cur_size;
    // The eviction policy (LRU or LFU)
    char* eviction_policy;
} cache_t;

// Define the function to initialize the cache
void init_cache(cache_t* cache, int max_size, char* eviction_policy) {
    // Allocate memory for the hash table
    cache->objects = (custom_object_t**)malloc(max_size * sizeof(custom_object_t*));
    memset(cache->objects, 0, max_size * sizeof(custom_object_t*));
    // Set the maximum size of the cache
    cache->max_size = max_size;
    // Set the current size of the cache to 0
    cache->cur_size = 0;
    // Set the eviction policy
    cache->eviction_policy = eviction_policy;
}

// Define the function to add an object to the cache
void add_object(cache_t* cache, custom_object_t* obj) {
    // Check if the cache is full
    if (cache->cur_size == cache->max_size) {
        // Evict an object from the cache based on the eviction policy
        custom_object_t* evicted_obj = evict_object(cache);
        // Free the memory of the evicted object
        free(evicted_obj);
    }
    // Add the new object to the hash table
    cache->objects[cache->cur_size] = obj;
    // Increment the current size of the cache
    cache->cur_size++;
}

// Define the function to evict an object from the cache
custom_object_t* evict_object(cache_t* cache) {
    // Check if the cache is empty
    if (cache->cur_size == 0) {
        return NULL;
    }
    // Find the object to evict based on the eviction policy
    custom_object_t* evicted_obj = NULL;
    if (strcmp(cache->eviction_policy, "LRU") == 0) {
        // Evict the least recently used object
        int min_timestamp = INT_MAX;
        for (int i = 0; i < cache->cur_size; i++) {
            if (cache->objects[i]->current_timestamp < min_timestamp) {
                evicted_obj = cache->objects[i];
                min_timestamp = evicted_obj->current_timestamp;
            }
        }
    } else if (strcmp(cache->eviction_policy, "LFU") == 0) {
        // Evict the least frequently used object
        int min_frequency = INT_MAX;
        for (int i = 0; i < cache->cur_size; i++) {
            if (cache->objects[i]->current_timestamp < min_frequency) {
                evicted_obj = cache->objects[i];
                min_frequency = evicted_obj->current_timestamp;
            }
        }
    } else {
        // Evict the object with the oldest timestamp
        int min_timestamp = INT_MAX;
        for (int i = 0; i < cache->cur_size; i++) {
            if (cache->objects[i]->current_timestamp < min_timestamp) {
                evicted_obj = cache->objects[i];
                min_timestamp = evicted_obj->current_timestamp;
            }
        }
    }
    // Remove the evicted object from the hash table
    for (int i = 0; i < cache->cur_size; i++) {
        if (cache->objects[i] == evicted_obj) {
            cache->objects[i] = NULL;
            break;
        }
    }
    // Decrement the current size of the cache
    cache->cur_size--;
    return evicted_obj;
}

// Define the function to clear the entire cache and reset its state
void clear_cache(cache_t* cache) {
    // Free the memory of all objects in the hash table
    for (int i = 0; i < cache->max_size; i++) {
        if (cache->objects[i] != NULL) {
            free(cache->objects[i]);
        }
    }
    // Reset the current size of the cache to 0
    cache->cur_size = 0;
}
