#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <semaphore.h>
#include <unistd.h>
#include <sys/types.h>
#include <sys/ipc.h>
#include <sys/shm.h>
#include <sys/msg.h>

// Define the message structure for the queue
struct msg_t {
    long mtype;
    char *payload;
    size_t payload_size;
    time_t timestamp;
};

// Define the shared memory segment for the queue
static int shmid;
static void *shmaddr;

// Define the semaphore for synchronizing access to the queue
static sem_t *sem;

// Define the function to initialize the queue
void init_queue() {
    // Create a shared memory segment for the queue
    shmid = shmget(IPC_PRIVATE, sizeof(struct msg_t), IPC_CREAT | 0644);
    if (shmid < 0) {
        perror("shmget");
        exit(1);
    }

    // Attach the shared memory segment to the address space of the process
    shmaddr = shmat(shmid, NULL, 0);
    if ((void *)shmaddr == (void *)-1) {
        perror("shmat");
        exit(1);
    }

    // Initialize the semaphore for synchronizing access to the queue
    sem = sem_open("/queue_sem", O_CREAT, 0644, 1);
    if (sem == SEM_FAILED) {
        perror("sem_open");
        exit(1);
    }
}

// Define the function to destroy the queue
void destroy_queue() {
    // Detach the shared memory segment from the address space of the process
    shmdt(shmaddr);

    // Remove the shared memory segment
    shmctl(shmid, IPC_RMID, NULL);

    // Close the semaphore for synchronizing access to the queue
    sem_close(sem);
}

// Define the function to enqueue an event in the queue
void enqueue(struct msg_t *event) {
    // Lock the semaphore for synchronizing access to the queue
    sem_wait(sem);

    // Copy the event data into the shared memory segment
    memcpy((char *)shmaddr + sizeof(long), event->payload, event->payload_size);

    // Update the timestamp of the event in the shared memory segment
    *(time_t *)((char *)shmaddr + sizeof(long) + event->payload_size) = event->timestamp;

    // Unlock the semaphore for synchronizing access to the queue
    sem_post(sem);
}

// Define the function to dequeue an event from the queue
struct msg_t *dequeue() {
    struct msg_t *event = NULL;

    // Lock the semaphore for synchronizing access to the queue
    sem_wait(sem);

    // Check if there are any events in the queue
    if (*(long *)shmaddr > 0) {
        // Copy the event data from the shared memory segment
        event = malloc(sizeof(struct msg_t));
        memcpy(event, (char *)shmaddr + sizeof(long), sizeof(struct msg_t));

        // Update the timestamp of the event in the shared memory segment
        *(time_t *)((char *)shmaddr + sizeof(long) + event->payload_size) = 0;

        // Decrement the number of events in the queue
        (*(long *)shmaddr)--;
    }

    // Unlock the semaphore for synchronizing access to the queue
    sem_post(sem);

    return event;
}

// Define the function to reset the queue's state
void reset() {
    // Lock the semaphore for synchronizing access to the queue
    sem_wait(sem);

    // Reset the number of events in the queue
    *(long *)shmaddr = 0;

    // Unlock the semaphore for synchronizing access to the queue
    sem_post(sem);
}
