#include <iostream>
#include <string>
#include <vector>
#include <mutex>
#include <thread>
#include <chrono>
#include <unordered_map>
#include <memory>

class NetworkDeviceManager {
public:
    // Constructor
    NetworkDeviceManager() {}

    // Destructor
    ~NetworkDeviceManager() {}

    // Add a new device to the list of managed devices
    void addDevice(const std::string& deviceId, const std::string& interfaceName) {
        std::lock_guard<std::mutex> lock(_mutex);
        _devices[deviceId] = DeviceInfo{interfaceName};
    }

    // Update the configuration status of a device
    void updateDeviceStatus(const std::string& deviceId, const bool& status) {
        std::lock_guard<std::mutex> lock(_mutex);
        _devices[deviceId].status = status;
    }

    // Disable devices based on connectivity loss criteria
    void disableDevices() {
        std::lock_guard<std::mutex> lock(_mutex);
        for (auto& device : _devices) {
            if (!device.second.status) {
                device.second.disabled = true;
            }
        }
    }

    // Mark inactive devices for re-evaluation
    void markInactiveDevices() {
        std::lock_guard<std::mutex> lock(_mutex);
        for (auto& device : _devices) {
            if (!device.second.status && !device.second.disabled) {
                device.second.inactive = true;
            }
        }
    }

    // Generate detailed logs for debugging purposes
    void generateLogs() {
        std::lock_guard<std::mutex> lock(_mutex);
        for (auto& device : _devices) {
            if (device.second.inactive) {
                std::cout << "Device " << device.first << " is inactive" << std::endl;
            } else if (device.second.disabled) {
                std::cout << "Device " << device.first << " is disabled" << std::endl;
            } else {
                std::cout << "Device " << device.first << " is active" << std::endl;
            }
        }
    }

private:
    struct DeviceInfo {
        std::string interfaceName;
        bool status = true;
        bool disabled = false;
        bool inactive = false;
    };

    // Map of device IDs to their corresponding information
    std::unordered_map<std::string, DeviceInfo> _devices;

    // Mutex for thread-safe operations
    std::mutex _mutex;
};
```
