#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pthread.h>
#include <unistd.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <errno.h>

// Define the cache structure
struct Cache {
    int size; // maximum number of entries in the cache
    int count; // current number of entries in the cache
    struct record *entries; // array of records in the cache
};

// Define the record structure
struct record {
    long key; // unique identifier for the record
    int value; // integer value associated with the record
    timestamp created_at; // creation time of the record
};

// Define the cache operations
void init_cache(struct Cache *cache, int size) {
    cache->size = size;
    cache->count = 0;
    cache->entries = malloc(sizeof(struct record) * size);
}

void add_record(struct Cache *cache, long key, int value) {
    struct record *new_record = malloc(sizeof(struct record));
    new_record->key = key;
    new_record->value = value;
    new_record->created_at = time(NULL);
    cache->entries[cache->count++] = new_record;
}

void remove_record(struct Cache *cache, long key) {
    int i;
    for (i = 0; i < cache->count; i++) {
        if (cache->entries[i]->key == key) {
            free(cache->entries[i]);
            cache->count--;
            break;
        }
    }
}

void evict_record(struct Cache *cache, long key) {
    int i;
    for (i = 0; i < cache->count; i++) {
        if (cache->entries[i]->key == key) {
            free(cache->entries[i]);
            cache->count--;
            break;
        }
    }
}

void query_record(struct Cache *cache, long key) {
    int i;
    for (i = 0; i < cache->count; i++) {
        if (cache->entries[i]->key == key) {
            return cache->entries[i];
        }
    }
}

void log_access(struct Cache *cache, long key, int value) {
    struct record *new_record = malloc(sizeof(struct record));
    new_record->key = key;
    new_record->value = value;
    new_record->created_at = time(NULL);
    cache->entries[cache->count++] = new_record;
}

// Define the main function
int main(int argc, char *argv[]) {
    // Check command line arguments
    if (argc < 3) {
        printf("Usage: %s -k <keywords_file> -o <output_file>\n", argv[0]);
        return 1;
    }

    // Initialize the cache
    struct Cache *cache = malloc(sizeof(struct Cache));
    init_cache(cache, 1000);

    // Process each input log file
    for (int i = 2; i < argc; i++) {
        char *input_file = argv[i];
        FILE *fp = fopen(input_file, "r");
        if (!fp) {
            printf("Error: unable to open input file %s\n", input_file);
            continue;
        }

        // Read the keywords from the keywords file
        char *keywords_file = argv[1];
        FILE *kw_fp = fopen(keywords_file, "r");
        if (!kw_fp) {
            printf("Error: unable to open keywords file %s\n", keywords_file);
            continue;
        }
        char *keyword = malloc(1024);
        while (fgets(keyword, 1024, kw_fp)) {
            // Remove newline character from the keyword
            int len = strlen(keyword);
            if (keyword[len - 1] == '\n') {
                keyword[len - 1] = '\0';
            }

            // Add the keyword to the cache
            add_record(cache, keyword, 0);
        }
        fclose(kw_fp);

        // Process each line in the input file
        char *line = malloc(1024);
        while (fgets(line, 1024, fp)) {
            // Remove newline character from the line
            len = strlen(line);
            if (line[len - 1] == '\n') {
                line[len - 1] = '\0';
            }

            // Check for keywords in the line
            char *token = strtok(line, " ");
            while (token) {
                // Check if the token is a keyword
                struct record *record = query_record(cache, token);
                if (record) {
                    // Increment the value of the keyword
                    record->value++;
                } else {
                    // Add the token as a new keyword
                    add_record(cache, token, 1);
                }
                token = strtok(NULL, " ");
            }
        }
        fclose(fp);

        // Evict expired records from the cache
        for (int i = 0; i < cache->count; i++) {
            if (cache->entries[i]->created_at + 3600 < time(NULL)) {
                evict_record(cache, cache->entries[i]->key);
            }
        }
    }

    // Write the summary report to the output file
    char *output_file = argv[2];
    FILE *fp = fopen(output_file, "w");
    if (!fp) {
        printf("Error: unable to open output file %s\n", output_file);
        return 1;
    }
    for (int i = 0; i < cache->count; i++) {
        fprintf(fp, "%s\t%d\t%ld\n", cache->entries[i]->key, cache->entries[i]->value, cache->entries[i]->created_at);
    }
    fclose(fp);

    // Clean up the cache and return
    free(cache);
    return 0;
}
