#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pthread.h>

// Define the structure for the cache entry
typedef struct {
    int object_id;
    void* resource;
    time_t timestamp;
} custom_object;

// Define the cache structure
typedef struct {
    custom_object** entries;
    size_t capacity;
    pthread_mutex_t mutex;
} cache;

// Initialize and populate the cache
void init_cache(cache* c, size_t capacity) {
    // Allocate memory for the cache entries
    c->entries = (custom_object**)malloc(capacity * sizeof(custom_object*));
    memset(c->entries, 0, capacity * sizeof(custom_object*));

    // Initialize the mutex
    pthread_mutex_init(&c->mutex, NULL);
}

// Add an entry to the cache
void add_entry(cache* c, int object_id, void* resource) {
    // Acquire the lock on the mutex
    pthread_mutex_lock(&c->mutex);

    // Check if the cache is full
    if (c->capacity == 0) {
        // Evict an entry from the cache
        evict_entry(c);
    }

    // Create a new cache entry
    custom_object* entry = (custom_object*)malloc(sizeof(custom_object));
    entry->object_id = object_id;
    entry->resource = resource;
    entry->timestamp = time(NULL);

    // Add the entry to the cache
    c->entries[c->capacity++] = entry;

    // Release the lock on the mutex
    pthread_mutex_unlock(&c->mutex);
}

// Evict an entry from the cache
void evict_entry(cache* c) {
    // Acquire the lock on the mutex
    pthread_mutex_lock(&c->mutex);

    // Find the oldest entry in the cache
    size_t oldest = 0;
    for (size_t i = 1; i < c->capacity; i++) {
        if (c->entries[i]->timestamp < c->entries[oldest]->timestamp) {
            oldest = i;
        }
    }

    // Free the entry and remove it from the cache
    free(c->entries[oldest]);
    c->entries[oldest] = NULL;
    c->capacity--;

    // Release the lock on the mutex
    pthread_mutex_unlock(&c->mutex);
}

// Query the cache for a specific object ID without eviction
custom_object* query_cache(cache* c, int object_id) {
    // Acquire the lock on the mutex
    pthread_mutex_lock(&c->mutex);

    // Find the entry in the cache
    for (size_t i = 0; i < c->capacity; i++) {
        if (c->entries[i]->object_id == object_id) {
            // Update the timestamp of the entry
            c->entries[i]->timestamp = time(NULL);

            // Release the lock on the mutex
            pthread_mutex_unlock(&c->mutex);

            return c->entries[i];
        }
    }

    // Release the lock on the mutex
    pthread_mutex_unlock(&c->mutex);

    return NULL;
}

// Log every access event with the current timestamp for performance monitoring
void log_access(cache* c, int object_id) {
    // Acquire the lock on the mutex
    pthread_mutex_lock(&c->mutex);

    // Find the entry in the cache
    for (size_t i = 0; i < c->capacity; i++) {
        if (c->entries[i]->object_id == object_id) {
            // Update the timestamp of the entry
            c->entries[i]->timestamp = time(NULL);

            // Release the lock on the mutex
            pthread_mutex_unlock(&c->mutex);

            return;
        }
    }

    // Release the lock on the mutex
    pthread_mutex_unlock(&c->mutex);
}

// Main program
int main(int argc, char* argv[]) {
    // Initialize the cache with a capacity of 1000 entries
    cache c;
    init_cache(&c, 1000);

    // Parse command line arguments
    if (argc == 2) {
        // Read the input file line by line and print the number of lines
        FILE* fp = fopen(argv[1], "r");
        int count = 0;
        char line[1024];
        while (fgets(line, sizeof(line), fp) != NULL) {
            // Add an entry to the cache for each line in the file
            add_entry(&c, count++, line);
        }
        printf("Number of lines: %d\n", count);
    } else if (argc == 1) {
        // Print usage information
        printf("Usage: %s [input_file]\n", argv[0]);
    }

    return 0;
}
