// Function to dynamically allocate memory for a list of NFAPI_CRC_INDICATION_PDU_T structures
NFAPI_CRC_INDICATION_PDU_T* allocateNfapiCrcIndicationPduList(int n) {
    // Allocate memory for the list of structures
    NFAPI_CRC_INDICATION_PDU_T* pduList = (NFAPI_CRC_INDICATION_PDU_T*)malloc(n * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!pduList) {
        // Handle error: out of memory
        return NULL;
    }

    // Initialize the list of structures
    for (int i = 0; i < n; i++) {
        pduList[i].rxUeInformationTag = RX_UE_INFORMATION_TAG_INIT;
        pduList[i].rnti = RNTI_INIT;
        pduList[i].crcIndicationRel8Tag.crcFlag = 0;
        pduList[i].crcIndicationRel8Tag.crcValue = 0.0f;
        pduList[i].crcIndicationRel8Tag.crcString = NULL;
    }

    // Return the list of structures
    return pduList;
}

// Function to populate the CRC_INDICATION_REL8_TAG field with random data
void populateCrcIndicationRel8Tag(NFAPI_CRC_INDICATION_PDU_T* pdu) {
    // Generate a random integer between 0 and 100 for the crcFlag field
    int crcFlag = rand() % 100;

    // Generate a random floating-point number within the range [0.0, 1.0] for the crcValue field
    float crcValue = (float)rand() / RAND_MAX;

    // Allocate memory for the string field
    char* crcString = (char*)malloc(strlen(phrases[rand() % (sizeof(phrases) / sizeof(const char*))]) + 1);
    if (!crcString) {
        // Handle error: out of memory
        return;
    }

    // Copy a random phrase from the list into the string field
    strcpy(crcString, phrases[rand() % (sizeof(phrases) / sizeof(const char*))]);

    // Set the crcFlag, crcValue, and crcString fields of the CRC_INDICATION_REL8_TAG structure
    pdu->crcIndicationRel8Tag.crcFlag = crcFlag;
    pdu->crcIndicationRel8Tag.crcValue = crcValue;
    pdu->crcIndicationRel8Tag.crcString = crcString;
}

// Function to retrieve data from an external source and populate the list of NFAPI_CRC_INDICATION_PDU_T structures with random data
NFAPI_CRC_INDICATION_PDU_T* retrieveDataAndPopulateList(int n) {
    // Allocate memory for the list of structures
    NFAPI_CRC_INDICATION_PDU_T* pduList = allocateNfapiCrcIndicationPduList(n);
    if (!pduList) {
        // Handle error: out of memory
        return NULL;
    }

    // Populate the list of structures with random data
    for (int i = 0; i < n; i++) {
        populateCrcIndicationRel8Tag(&pduList[i]);
    }

    // Return the list of structures
    return pduList;
}
