// Define the structure to hold a TIDB_ROW_RECORD
typedef struct {
    int row_id;
    char* column_values;
    time_t timestamp;
} tidb_row_record;

// Define the list of TIDB_ROW_RECORD structures
typedef struct {
    tidb_row_record** records;
    int size;
    int capacity;
} tidb_row_list;

// Initialize and populate a list of TIDB_ROW_RECORD structures
void init_tidb_row_list(tidb_row_list* list) {
    // Allocate memory for the list
    list->records = (tidb_row_record**)malloc(sizeof(tidb_row_record*) * 10);
    list->size = 0;
    list->capacity = 10;

    // Initialize each record with a valid ROW_ID, COLUMN_VALUES, and TIMESTAMP
    for (int i = 0; i < list->capacity; i++) {
        tidb_row_record* record = (tidb_row_record*)malloc(sizeof(tidb_row_record));
        record->row_id = i + 1;
        record->column_values = "example_value";
        record->timestamp = time(NULL);
        list->records[i] = record;
    }
}

// Add a new TIDB_ROW_RECORD structure to the list
void add_tidb_row_record(tidb_row_list* list, int row_id, char* column_values) {
    // Check if the list is full
    if (list->size == list->capacity) {
        // Reallocate memory for the list
        list->records = (tidb_row_record**)realloc(list->records, sizeof(tidb_row_record*) * (list->capacity + 10));
        list->capacity += 10;
    }

    // Create a new record with the given ROW_ID and COLUMN_VALUES
    tidb_row_record* record = (tidb_row_record*)malloc(sizeof(tidb_row_record));
    record->row_id = row_id;
    record->column_values = column_values;
    record->timestamp = time(NULL);

    // Add the new record to the list
    list->records[list->size++] = record;
}

// Remove a TIDB_ROW_RECORD structure from the list by its ROW_ID
void remove_tidb_row_record(tidb_row_list* list, int row_id) {
    // Find the index of the record with the given ROW_ID
    int index = -1;
    for (int i = 0; i < list->size; i++) {
        if (list->records[i]->row_id == row_id) {
            index = i;
            break;
        }
    }

    // Check if the record was found
    if (index != -1) {
        // Remove the record from the list
        tidb_row_record* record = list->records[index];
        for (int i = index; i < list->size - 1; i++) {
            list->records[i] = list->records[i + 1];
        }
        list->size--;

        // Free the memory used by the record
        free(record);
    }
}

// Iterate over the list in reverse order without duplicating the entire structure
void iterate_tidb_row_list_reverse(tidb_row_list* list, void (*callback)(tidb_row_record*)) {
    // Iterate over the list in reverse order
    for (int i = list->size - 1; i >= 0; i--) {
        callback(list->records[i]);
    }
}

// Filter the list based on ROW_ID and return a new list with the filtered records
tidb_row_list* filter_tidb_row_list(tidb_row_list* list, int row_id) {
    // Create a new list to hold the filtered records
    tidb_row_list* filtered_list = (tidb_row_list*)malloc(sizeof(tidb_row_list));
    filtered_list->records = NULL;
    filtered_list->size = 0;
    filtered_list->capacity = 0;

    // Iterate over the list and add records with the given ROW_ID to the filtered list
    for (int i = 0; i < list->size; i++) {
        if (list->records[i]->row_id == row_id) {
            add_tidb_row_record(filtered_list, list->records[i]->row_id, list->records[i]->column_values);
        }
    }

    return filtered_list;
}
