#include <stdlib.h>
#include <pthread.h>
#include <semaphore.h>

// Define the structure for a worker thread
typedef struct {
    pthread_t thread;
    int task_id;
    sem_t *resource_manager;
} WORKER_THREAD;

// Define the function to initialize and manage the pool of worker threads
void init_worker_pool(int num_threads, sem_t *resource_manager) {
    // Initialize an array of worker threads
    WORKER_THREAD *workers = (WORKER_THREAD *)malloc(num_threads * sizeof(WORKER_THREAD));

    // Create a semaphore to manage access to the resource manager
    sem_t *resource_manager_sem = sem_open("resource_manager", O_CREAT, 0644, num_threads);

    // Initialize each worker thread with its task ID and resource manager
    for (int i = 0; i < num_threads; i++) {
        workers[i].task_id = i;
        workers[i].resource_manager = resource_manager;
        pthread_create(&workers[i].thread, NULL, worker_thread, &workers[i]);
    }

    // Wait for all worker threads to finish
    for (int i = 0; i < num_threads; i++) {
        pthread_join(workers[i].thread, NULL);
    }

    // Clean up the semaphore and array of worker threads
    sem_close(resource_manager_sem);
    free(workers);
}

// Define the function to be executed by each worker thread
void *worker_thread(void *arg) {
    WORKER_THREAD *worker = (WORKER_THREAD *)arg;

    // Loop indefinitely, processing tasks as they become available
    while (1) {
        // Acquire a permit from the resource manager semaphore to access the shared resource
        sem_wait(worker->resource_manager);

        // Process the next task with the highest priority
        int task_id = worker->task_id;
        if (task_id < 0) {
            break;
        }

        // Release the permit and continue processing the next task
        sem_post(worker->resource_manager);
    }

    return NULL;
}
