// Define the structure for the custom object
typedef struct {
    uint32_t object_id;
    void* resource;
    uint64_t timestamp;
} custom_object_t;

// Define the cache data structure
typedef struct {
    custom_object_t** objects;
    size_t capacity;
    size_t count;
    pthread_mutex_t mutex;
} cache_t;

// Initialize the cache with a given capacity
void init_cache(cache_t* cache, size_t capacity) {
    cache->objects = malloc(sizeof(custom_object_t*) * capacity);
    memset(cache->objects, 0, sizeof(custom_object_t*) * capacity);
    cache->capacity = capacity;
    cache->count = 0;
    pthread_mutex_init(&cache->mutex, NULL);
}

// Add a new object to the cache
void add_object(cache_t* cache, custom_object_t* object) {
    // Acquire the lock on the mutex
    pthread_mutex_lock(&cache->mutex);

    // Check if the cache is full
    if (cache->count == cache->capacity) {
        // Evict the oldest object from the cache
        custom_object_t* evicted_object = cache->objects[0];
        free(evicted_object);
        memmove(&cache->objects[0], &cache->objects[1], sizeof(custom_object_t*) * (cache->capacity - 1));
        cache->count--;
    }

    // Add the new object to the end of the cache
    cache->objects[cache->count] = object;
    cache->count++;

    // Release the lock on the mutex
    pthread_mutex_unlock(&cache->mutex);
}

// Get an object from the cache by its ID
custom_object_t* get_object(cache_t* cache, uint32_t id) {
    // Acquire the lock on the mutex
    pthread_mutex_lock(&cache->mutex);

    // Iterate over the objects in the cache and find the one with the matching ID
    for (size_t i = 0; i < cache->count; i++) {
        custom_object_t* object = cache->objects[i];
        if (object->object_id == id) {
            // Update the timestamp of the found object
            object->timestamp = get_current_timestamp();
            break;
        }
    }

    // Release the lock on the mutex
    pthread_mutex_unlock(&cache->mutex);
}

// Evict expired objects from the cache
void evict_expired_objects(cache_t* cache) {
    // Acquire the lock on the mutex
    pthread_mutex_lock(&cache->mutex);

    // Iterate over the objects in the cache and find the ones that have expired
    for (size_t i = 0; i < cache->count; i++) {
        custom_object_t* object = cache->objects[i];
        if (get_current_timestamp() - object->timestamp > EXPIRATION_TIME) {
            // Evict the expired object from the cache
            free(object);
            memmove(&cache->objects[i], &cache->objects[i + 1], sizeof(custom_object_t*) * (cache->count - i));
            cache->count--;
        }
    }

    // Release the lock on the mutex
    pthread_mutex_unlock(&cache->mutex);
}

// Get the current timestamp in milliseconds
uint64_t get_current_timestamp() {
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    return (uint64_t)ts.tv_sec * 1000 + (uint64_t)ts.tv_nsec / 1000000;
}
