#include <time.h>

// Define a structure to represent a cache entry
typedef struct {
    int object_id;
    RESOURCE *resource;
    time_t timestamp;
} CUSTOM_OBJECT;

// Define a cache data structure to store the objects
typedef struct {
    CUSTOM_OBJECT **objects;
    size_t capacity;
    size_t count;
    pthread_mutex_t mutex;
} CACHE;

// Initialize the cache with a given capacity and eviction policy
void init_cache(CACHE *cache, size_t capacity, int eviction_policy) {
    cache->capacity = capacity;
    cache->count = 0;
    cache->objects = malloc(sizeof(CUSTOM_OBJECT *) * capacity);
    pthread_mutex_init(&cache->mutex, NULL);
}

// Add a new object to the cache
void add_object(CACHE *cache, int object_id, RESOURCE *resource) {
    CUSTOM_OBJECT *new_object = malloc(sizeof(CUSTOM_OBJECT));
    new_object->object_id = object_id;
    new_object->resource = resource;
    new_object->timestamp = time(NULL);

    pthread_mutex_lock(&cache->mutex);
    if (cache->count < cache->capacity) {
        cache->objects[cache->count++] = new_object;
    } else {
        // Evict the oldest object if the cache is full
        evict_object(cache, 0);
        cache->objects[0] = new_object;
    }
    pthread_mutex_unlock(&cache->mutex);
}

// Get an object from the cache by its ID
CUSTOM_OBJECT *get_object(CACHE *cache, int object_id) {
    CUSTOM_OBJECT *object = NULL;

    pthread_mutex_lock(&cache->mutex);
    for (size_t i = 0; i < cache->count; i++) {
        if (cache->objects[i]->object_id == object_id) {
            object = cache->objects[i];
            break;
        }
    }
    pthread_mutex_unlock(&cache->mutex);

    return object;
}

// Evict an object from the cache by its ID
void evict_object(CACHE *cache, int object_id) {
    CUSTOM_OBJECT *object = NULL;

    pthread_mutex_lock(&cache->mutex);
    for (size_t i = 0; i < cache->count; i++) {
        if (cache->objects[i]->object_id == object_id) {
            object = cache->objects[i];
            break;
        }
    }
    if (object != NULL) {
        // Remove the evicted object from the cache
        for (size_t j = i; j < cache->count - 1; j++) {
            cache->objects[j] = cache->objects[j + 1];
        }
        cache->count--;
    }
    pthread_mutex_unlock(&cache->mutex);
}

// Periodically scan the cache for expired objects and evict them
void *eviction_thread(void *arg) {
    CACHE *cache = (CACHE *)arg;
    while (1) {
        pthread_mutex_lock(&cache->mutex);
        for (size_t i = 0; i < cache->count; i++) {
            if (cache->objects[i]->timestamp + CACHE_EXPIRATION_TIME < time(NULL)) {
                evict_object(cache, cache->objects[i]->object_id);
            }
        }
        pthread_mutex_unlock(&cache->mutex);
        sleep(CACHE_EVICTION_INTERVAL);
    }
}

// Start the eviction thread
void start_eviction_thread(CACHE *cache) {
    pthread_t eviction_thread;
    pthread_create(&eviction_thread, NULL, eviction_thread, cache);
}
