#include <string.h>
#include <pthread.h>
#include <semaphore.h>
#include <unistd.h>
#include <sys/types.h>
#include <sys/ipc.h>
#include <sys/msg.h>
#include <sys/shm.h>
#include <sys/stat.h>
#include <sys/wait.h>
#include <errno.h>
#include <time.h>

// Define the message structure
struct MESSAGE {
    long int message_id;
    int priority;
    time_t timestamp;
    void* payload;
};

// Define the queue structure
struct QUEUE {
    struct MESSAGE* messages[100];
    int head;
    int tail;
    pthread_mutex_t mutex;
    semaphore_t semaphore;
};

// Initialize the queue
void init_queue(struct QUEUE* queue) {
    // Initialize the message array
    for (int i = 0; i < 100; i++) {
        queue->messages[i] = NULL;
    }

    // Initialize the head and tail pointers
    queue->head = 0;
    queue->tail = 0;

    // Initialize the mutex and semaphore
    pthread_mutex_init(&queue->mutex, NULL);
    semaphore_init(&queue->semaphore, 1);
}

// Enqueue a message
void enqueue(struct QUEUE* queue, struct MESSAGE* message) {
    // Acquire the mutex
    pthread_mutex_lock(&queue->mutex);

    // Check if the queue is full
    if (queue->tail == 100) {
        // If the queue is full, wait for a slot to become available
        semaphore_wait(&queue->semaphore);
    }

    // Add the message to the tail of the queue
    queue->messages[queue->tail] = message;
    queue->tail++;

    // Release the mutex
    pthread_mutex_unlock(&queue->mutex);
}

// Dequeue a message
struct MESSAGE* dequeue(struct QUEUE* queue) {
    // Acquire the mutex
    pthread_mutex_lock(&queue->mutex);

    // Check if the queue is empty
    if (queue->head == queue->tail) {
        // If the queue is empty, return NULL
        struct MESSAGE* message = NULL;
        pthread_mutex_unlock(&queue->mutex);
        return message;
    }

    // Remove the head of the queue
    struct MESSAGE* message = queue->messages[queue->head];
    queue->head++;

    // Release the mutex
    pthread_mutex_unlock(&queue->mutex);

    return message;
}

// Update a message in the queue
void update(struct QUEUE* queue, struct MESSAGE* message) {
    // Acquire the mutex
    pthread_mutex_lock(&queue->mutex);

    // Check if the message is in the queue
    int index = 0;
    for (int i = queue->head; i < queue->tail; i++) {
        if (queue->messages[i] == message) {
            index = i;
            break;
        }
    }

    // If the message is not in the queue, return
    if (index == 0) {
        pthread_mutex_unlock(&queue->mutex);
        return;
    }

    // Update the message in the queue
    queue->messages[index] = message;

    // Release the mutex
    pthread_mutex_unlock(&queue->mutex);
}

// Clean up the queue
void cleanup(struct QUEUE* queue) {
    // Acquire the mutex
    pthread_mutex_lock(&queue->mutex);

    // Free the message array
    for (int i = 0; i < 100; i++) {
        free(queue->messages[i]);
    }

    // Release the mutex
    pthread_mutex_unlock(&queue->mutex);
}
