// Function to initialize the server
void initialize_server() {
    // Initialize semaphore and mutex for synchronizing access to shared data structures
    semaphore = sem_open("semaphore", O_CREAT, 0644, MAX_CLIENTS);
    mutex = (pthread_mutex_t*) malloc(sizeof(pthread_mutex_t));
    pthread_mutex_init(mutex, NULL);
    condition = (pthread_cond_t*) malloc(sizeof(pthread_cond_t));
    pthread_cond_init(condition, NULL);

    // Initialize log configuration and server configuration
    read_config_file(CONFIG_FILE);
    configure_server();
}

// Function to handle client connections
void handle_client_connection(client_t* client) {
    // Read log entry from client socket
    char buffer[BUFFER_SIZE];
    int bytes_read = read(client->socket, buffer, BUFFER_SIZE);
    if (bytes_read < 0) {
        perror("Error reading from socket");
        return;
    }

    // Parse log entry and process it
    log_entry_t* entry = parse_log_entry(buffer);
    process_log_entry(entry);
}

// Function to process a log entry
void process_log_entry(log_entry_t* entry) {
    // Check if the log level is within the configured range
    if (strcmp(entry->priority, server_config.min_log_level) < 0 || strcmp(entry->priority, server_config.max_log_level) > 0) {
        return;
    }

    // Check if the log retention policy is met
    time_t current_time = time(NULL);
    struct tm* time_info = localtime(&current_time);
    char* date = asctime(time_info);
    int days_since_epoch = difftime(current_time, 0) / (60 * 60 * 24);
    if (server_config.log_retention_policy == "time-based" && days_since_epoch > server_config.max_log_retention) {
        return;
    }

    // Write log entry to file
    write_log_to_file(entry->message);
}

// Function to write a log message to the log file
