#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <pthread.h>
#include <sys/time.h>
#include <sys/resource.h>

// Define the maximum number of clients that can connect to the server
#define MAX_CLIENTS 10

// Define the maximum number of log entries that can be stored in memory at a time
#define MAX_LOG_ENTRIES 10000

// Define the maximum length of a log entry
#define MAX_LOG_LENGTH 256

// Define the maximum number of worker threads that can be created to process log entries
#define MAX_WORKER_THREADS 4

// Define the maximum execution time for each request in milliseconds
#define MAX_EXECUTION_TIME 10000

// Define the logging level for the server (0 = debug, 1 = info, 2 = warning, 3 = error)
#define LOGGING_LEVEL 1

// Define the log retention policy for the server (0 = keep all logs, 1 = keep only last log entry)
#define LOG_RETENTION_POLICY 0

// Define the execution timeout for each request in milliseconds
#define EXECUTION_TIMEOUT 5000

// Define the configuration file path
#define CONFIG_FILE_PATH "config.txt"

// Define the custom log format
#define CUSTOM_LOG_FORMAT "%d %b %Y %H:%M:%S %z [%p] %t %m (%c) %n"

// Define the output directory for archived logs
#define OUTPUT_DIRECTORY "/var/log/"

// Define the log entry structure
struct LogEntry {
    char *message;
    int priority;
};

// Define the client structure
struct Client {
    int id;
    struct sockaddr_in address;
    pthread_t thread;
    struct LogEntry *log_entries;
    size_t log_entry_count;
};

// Define the worker thread structure
struct WorkerThread {
    pthread_t thread;
    int id;
    struct Client *client;
};

// Define the server structure
struct Server {
    int socket_fd;
    struct sockaddr_in address;
    size_t client_count;
    struct Client clients[MAX_CLIENTS];
    pthread_mutex_t mutex;
    pthread_cond_t cond;
};

// Define the log entry queue structure
struct LogEntryQueue {
    struct LogEntry *log_entries;
    size_t log_entry_count;
    size_t log_entry_capacity;
};

// Define the worker thread queue structure
struct WorkerThreadQueue {
    struct WorkerThread *worker_threads;
    size_t worker_thread_count;
    size_t worker_thread_capacity;
};

// Initialize the server and create a socket for listening to incoming connections
int initialize_server(struct Server *server) {
    // Create a socket for listening to incoming connections
    int socket_fd = socket(AF_INET, SOCK_STREAM, 0);
    if (socket_fd < 0) {
        perror("socket");
        return -1;
    }

    // Set the socket options for reuse address and keep alive
    int enable = 1;
    if (setsockopt(socket_fd, SOL_SOCKET, SO_REUSEADDR, &enable, sizeof(int)) < 0) {
        perror("setsockopt");
        return -1;
    }
    if (setsockopt(socket_fd, SOL_SOCKET, SO_KEEPALIVE, &enable, sizeof(int)) < 0) {
        perror("setsockopt");
        return -1;
    }

    // Bind the socket to a specific address and port
    struct sockaddr_in address = {
        .sin_family = AF_INET,
        .sin_port = htons(8080),
        .sin_addr.s_addr = INADDR_ANY
    };
    if (bind(socket_fd, (struct sockaddr *)&address, sizeof(address)) < 0) {
        perror("bind");
        return -1;
    }

    // Listen for incoming connections
    if (listen(socket_fd, MAX_CLIENTS) < 0) {
        perror("listen");
        return -1;
    }

    server->socket_fd = socket_fd;
    server->address = address;
    server->client_count = 0;

    return 0;
}

// Accept an incoming connection and create a new client structure for it
int accept_connection(struct Server *server, struct Client *client) {
    // Accept the incoming connection
    int socket_fd = accept(server->socket_fd, NULL, NULL);
    if (socket_fd < 0) {
        perror("accept");
        return -1;
    }

    // Create a new client structure for the accepted connection
    client->id = server->client_count++;
    client->address.sin_family = AF_INET;
    client->address.sin_port = htons(8080);
    client->address.sin_addr.s_addr = INADDR_ANY;
    client->thread = 0;
    client->log_entries = NULL;
    client->log_entry_count = 0;

    // Create a new thread for the accepted connection
    pthread_create(&client->thread, NULL, handle_connection, (void *)client);

    return 0;
}

// Handle an incoming connection by reading log entries from the client and processing them
void *handle_connection(void *arg) {
    struct Client *client = (struct Client *)arg;

    // Read log entries from the client until a shutdown message is received
    while (1) {
        // Read the next log entry from the client
        char buffer[MAX_LOG_LENGTH];
        int bytes_read = read(client->socket_fd, buffer, MAX_LOG_LENGTH);
        if (bytes_read < 0) {
            perror("read");
            break;
        } else if (bytes_read == 0) {
            // Shutdown message received from the client
            break;
        }

        // Process the log entry
        process_log_entry(client, buffer);
    }

    return NULL;
}

// Process a log entry by adding it to the log entry queue and scheduling a worker thread for processing
void process_log_entry(struct Client *client, char *buffer) {
    // Add the log entry to the log entry queue
    struct LogEntryQueue *queue = &client->log_entries;
    if (queue->log_entry_count == queue->log_entry_capacity) {
        // Reallocate the log entry array if necessary
        queue->log_entry_capacity += 100;
        queue->log_entries = realloc(queue->log_entries, sizeof(struct LogEntry) * queue->log_entry_capacity);
    }
    struct LogEntry *entry = &queue->log_entries[queue->log_entry_count++];
    entry->message = strdup(buffer);
    entry->priority = 0;

    // Schedule a worker thread for processing the log entry
    struct WorkerThreadQueue *thread_queue = &client->worker_threads;
    if (thread_queue->worker_thread_count == thread_queue->worker_thread_capacity) {
        // Reallocate the worker thread array if necessary
        thread_queue->worker_thread_capacity += 100;
        thread_queue->worker_threads = realloc(thread_queue->worker_threads, sizeof(struct WorkerThread) * thread_queue->worker_thread_capacity);
    }
    struct WorkerThread *thread = &thread_queue->worker_threads[thread_queue->worker_thread_count++];
    thread->id = client->id;
    thread->client = client;
    pthread_create(&thread->thread, NULL, process_log_entry, (void *)thread);
}

// Process a log entry by writing it to the central logging server and archiving it if necessary
void *process_log_entry(void *arg) {
    struct WorkerThread *thread = (struct WorkerThread *)arg;
    struct Client *client = thread->client;

    // Write the log entry to the central logging server
    write_log_entry(client, client->log_entries[thread->id].message);

    // Archive the log entry if necessary
    if (client->log_retention_policy == 1) {
        archive_log_entry(client, client->log_entries[thread->id].message);
    }

    return NULL;
}

// Write a log entry to the central logging server
void write_log_entry(struct Client *client, char *buffer) {
    // Write the log entry to the central logging server
    int bytes_written = write(client->socket_fd, buffer, strlen(buffer));
    if (bytes_written < 0) {
        perror("write");
    }
}

// Archive a log entry by writing it to a file in the output directory
void archive_log_entry(struct Client *client, char *buffer) {
    // Open the output file for appending
    FILE *file = fopen(OUTPUT_DIRECTORY "logs.txt", "a");
    if (file == NULL) {
        perror("fopen");
        return;
    }

    // Write the log entry to the output file
    fprintf(file, "%s\n", buffer);

    // Close the output file
    fclose(file);
}

// Main function for the server
int main() {
    struct Server server;
    initialize_server(&server);

    while (1) {
        // Accept an incoming connection and create a new client structure for it
        struct Client client;
        accept_connection(&server, &client);

        // Handle the incoming connection by reading log entries from the client and processing them
        handle_connection(NULL);
    }

    return 0;
}
```
This program uses a combination of sockets, threads, and mutexes to implement the distributed logging service. It creates a socket for listening to incoming connections on port 8080, and accepts incoming connections using the `accept` function. Each accepted connection is handled by a separate thread that reads log entries from the client and processes them using the `process_log_entry` function. The `process_log_entry` function writes the log entry to the central logging server and archives it if necessary using the `write_log_entry` and `archive_log_entry` functions, respectively.

The program also uses a mutex to ensure that only one thread can access the log entry queue at a time, and a condition variable to signal when new log entries are available for processing. The `accept_connection` function creates a new client structure for each accepted connection and schedules a worker thread for handling the connection using the `pthread_create` function.

The program also uses dynamic memory allocation to allocate memory for the log entry queue, worker thread queue, and other data structures as necessary. It frees all allocated resources upon completion or failure using the `free` function.']

