// Number of connections in the pool
static size_t num_connections = 0;

// Mutex for synchronizing access to the pool
static pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

// Condition variable for signaling when a connection is available
static pthread_cond_t cond = PTHREAD_COND_INITIALIZER;

// Function to initialize the pool of connections
void init_connections(size_t num) {
    // Allocate memory for the connections
    connections = malloc(num * sizeof(Connection));
    if (connections == NULL) {
        perror("malloc");
        exit(1);
    }

    // Initialize each connection in the pool
    for (size_t i = 0; i < num; ++i) {
        connections[i].id = i;
        connections[i].config = NULL;
        connections[i].last_activity = time(NULL);
    }

    // Set the number of connections in the pool
    num_connections = num;
}

// Function to close a connection and return it to the pool
void close_connection(Connection* conn) {
    pthread_mutex_lock(&mutex);

    // Update the last activity time for the connection
    conn->last_activity = time(NULL);

    // Add the connection to the end of the idle list
    connections[conn->id].next = NULL;

    // Signal that a connection is available
    pthread_cond_signal(&cond);

    pthread_mutex_unlock(&mutex);
}

// Function to open a new connection and return it to the caller
Connection* open_connection() {
    pthread_mutex_lock(&mutex);

    // Wait for a connection to become available
    while (num_connections == 0) {
        pthread_cond_wait(&cond, &mutex);
    }

    // Find the first idle connection and remove it from the list
    Connection* conn = connections;
    connections = connections->next;

    // Update the last activity time for the connection
    conn->last_activity = time(NULL);

    pthread_mutex_unlock(&mutex);

