        if (keywords[0].keyword != NULL) {
            // Extract the keywords from the log message
            extract_keywords(log_entries[0].log_message, &keywords[0]);
            // Remove the extracted keywords from the array
            memmove(keywords, keywords + 1, sizeof(KeywordCount) * (MAX_KEYWORD_LENGTH - 1));
        }

        // Check if there are any outputs to generate
        if (output_buffer.length > 0) {
            // Generate the output for the keywords
            generate_output(&keywords[0], &output_buffer);
            // Remove the generated output from the buffer
            memmove(output_buffer.output, output_buffer.output + 1, sizeof(char) * (MAX_OUTPUT_LENGTH - 1));
        }

        // Check if there are any signals to handle
        int signal = sigwait(&sa);
        if (signal == SIGUSR1) {
            // Handle the SIGUSR1 signal by scaling up the thread count
            scale_up();
        } else if (signal == SIGUSR2) {
            // Handle the SIGUSR2 signal by scaling down the thread count
            scale_down();
        }

        // Update the load and thread count based on the current state of the system
        update_load();
        update_thread_count();
    }
}

// Function to process a new log entry
void process_log_entry(LogEntry* entry) {
    // Add the log entry to the array of log entries
    memmove(log_entries + 1, log_entries, sizeof(LogEntry) * (MAX_LOG_ENTRIES - 1));
    log_entries[0] = *entry;
}

// Function to extract keywords from a log message
void extract_keywords(char* log_message, KeywordCount* keywords) {
    // Extract the keywords from the log message
    char* keyword = strtok(log_message, " ");
    while (keyword != NULL) {
        // Add the keyword to the array of keywords
        memmove(keywords + 1, keywords, sizeof(KeywordCount) * (MAX_KEYWORD_LENGTH - 1));
        keywords[0].keyword = keyword;
        keywords[0].count++;
        keyword = strtok(NULL, " ");
    }
}

// Function to generate output for the extracted keywords
void generate_output(KeywordCount* keywords, OutputBuffer* output) {
    // Generate the output for the extracted keywords
    char* output_string = malloc(sizeof(char) * MAX_OUTPUT_LENGTH);
    sprintf(output_string, "Keywords: %s\n", keywords[0].keyword);
    memmove(output->output + 1, output->output, sizeof(char) * (MAX_OUTPUT_LENGTH - 1));
    output->output = output_string;
    output->length++;
}

// Function to handle signals for scaling up and down the thread count
void handle_signal(int signal) {
    // Handle the SIGUSR1 signal by scaling up the thread count
    if (signal == SIGUSR1) {
        scale_up();
    } else if (signal == SIGUSR2) {
        // Handle the SIGUSR2 signal by scaling down the thread count
        scale_down();
    }
}

// Function to scale up the thread count
void scale_up() {
    // Increase the thread count if the load is below a certain threshold
    if (load < THRESHOLD_LOAD) {
        thread_count++;
        update_thread_count();
    }
}

// Function to scale down the thread count
void scale_down() {
    // Decrease the thread count if the load is above a certain threshold
    if (load > THRESHOLD_SCALE) {
        thread_count--;
        update_thread_count();
    }
}

// Function to update the load and thread count based on the current state of the system
void update_load() {
    // Update the load based on the current state of the system
    load = (double)thread_count / MAX_THREADS;
}

// Function to update the thread count based on the current state of the system
void update_thread_count() {
    // Update the thread count based on the current state of the system
    if (load < THRESHOLD_LOAD) {
        thread_count = MAX_THREADS;
    } else if (load > THRESHOLD_SCALE) {
        thread_count = MIN_THREADS;
    }
}

// Function to print a performance report for the program
void print_performance_report() {
    // Print a performance report for the program
    printf("Performance Report\n");
    printf("------------------\n");
    printf("Thread Count: %d\n", thread_count);
    printf("Load: %.2f\n", load);
    printf("Output Buffer Length: %d\n", output_buffer.length);
}
