}

// Define the function to add a task to the cache
void add_to_cache(cache *cache, record *record, int key, long offset) {
    // Implement error handling and resource cleanup mechanisms to ensure robustness under various input conditions
    if (cache == NULL || record == NULL || key < 0 || offset < 0) {
        printf("Error: Invalid task\n");
