// Define data structures for NetworkInterfaceStats and SensorReading
struct NetworkInterfaceStats {
    char *interface_name;
    int packet_loss;
    int throughput;
    int latency;
};

struct SensorReading {
    char *sensor_name;
    float temperature;
    float humidity;
    float pressure;
};

// Define a linked list data structure to store the network interface stats and sensor readings
typedef struct NetworkInterfaceStatsListNode {
    struct NetworkInterfaceStats *stats;
    struct SensorReading *readings;
    struct NetworkInterfaceStatsListNode *next;
} NetworkInterfaceStatsListNode;

// Define a function to add a new network interface stats and sensor readings to the linked list
void add_network_interface_stats(char *interface_name, int packet_loss, int throughput, int latency, char *sensor_name, float temperature, float humidity, float pressure) {
    // Create a new node for the network interface stats and sensor readings
    NetworkInterfaceStatsListNode *new_node = malloc(sizeof(NetworkInterfaceStatsListNode));
    if (new_node == NULL) {
        printf("Memory allocation failed\n");
        return;
    }

    // Initialize the new node with the given data
    new_node->stats = malloc(sizeof(struct NetworkInterfaceStats));
    new_node->readings = malloc(sizeof(struct SensorReading));
    if (new_node->stats == NULL || new_node->readings == NULL) {
        printf("Memory allocation failed\n");
        free(new_node);
        return;
    }
    strcpy(new_node->stats->interface_name, interface_name);
    new_node->stats->packet_loss = packet_loss;
    new_node->stats->throughput = throughput;
    new_node->stats->latency = latency;
    strcpy(new_node->readings->sensor_name, sensor_name);
    new_node->readings->temperature = temperature;
    new_node->readings->humidity = humidity;
    new_node->readings->pressure = pressure;

    // Add the new node to the linked list
    pthread_mutex_lock(&list_mutex);
    if (head == NULL) {
        head = new_node;
    } else {
        tail->next = new_node;
    }
    tail = new_node;
    pthread_mutex_unlock(&list_mutex);
}

// Define a function to update an existing network interface stats and sensor readings in the linked list
void update_network_interface_stats(char *interface_name, int packet_loss, int throughput, int latency, char *sensor_name, float temperature, float humidity, float pressure) {
    // Find the node with the given interface name and sensor name
    NetworkInterfaceStatsListNode *node = head;
    while (node != NULL && strcmp(node->stats->interface_name, interface_name) != 0) {
        node = node->next;
    }
    if (node == NULL) {
        printf("Network interface stats not found\n");
        return;
    }
    while (node != NULL && strcmp(node->readings->sensor_name, sensor_name) != 0) {
        node = node->next;
    }
    if (node == NULL) {
        printf("Sensor readings not found\n");
        return;
    }

    // Update the stats and readings in the node
    node->stats->packet_loss = packet_loss;
    node->stats->throughput = throughput;
    node->stats->latency = latency;
    node->readings->temperature = temperature;
    node->readings->humidity = humidity;
    node->readings->pressure = pressure;
}

// Define a function to retrieve the aggregated statistics for all network interfaces and sensors
void get_aggregate_stats(int *num_interfaces, int *num_sensors, int *packet_loss, int *throughput, int *latency, float *temperature, float *humidity, float *pressure) {
    // Initialize the output variables to zero
    *num_interfaces = 0;
    *num_sensors = 0;
    *packet_loss = 0;
    *throughput = 0;
    *latency = 0;
    *temperature = 0.0f;
    *humidity = 0.0f;
    *pressure = 0.0f;

    // Iterate over the linked list and calculate the aggregated statistics
    NetworkInterfaceStatsListNode *node = head;
    while (node != NULL) {
        *num_interfaces += 1;
        *packet_loss += node->stats->packet_loss;
        *throughput += node->stats->throughput;
        *latency += node->stats->latency;
        *temperature += node->readings->temperature;
        *humidity += node->readings->humidity;
        *pressure += node->readings->pressure;
        node = node->next;
    }
}

