#include <stdlib.h>
#include <pthread.h>
#include <stdio.h>

// Structure to represent a task
typedef struct Task {
    int TASK_ID;
    RESOURCE *resource;
    int priority;
} Task;

// Structure to represent the dynamic list of tasks
typedef struct TaskList {
    Task **tasks;
    size_t capacity;
    size_t count;
    pthread_mutex_t mutex;
} TaskList;

// Function to create a new task list
TaskList *createTaskList() {
    TaskList *list = malloc(sizeof(TaskList));
    if (list == NULL) {
        return NULL;
    }
    list->tasks = malloc(sizeof(Task *) * 10);
    if (list->tasks == NULL) {
        free(list);
        return NULL;
    }
    list->capacity = 10;
    list->count = 0;
    pthread_mutex_init(&list->mutex, NULL);
    return list;
}

// Function to add a new task to the list
void addTask(TaskList *list, int TASK_ID, RESOURCE *resource, int priority) {
    Task *task = malloc(sizeof(Task));
    if (task == NULL) {
        return;
    }
    task->TASK_ID = TASK_ID;
    task->resource = resource;
    task->priority = priority;
    pthread_mutex_lock(&list->mutex);
    if (list->count == list->capacity) {
        Task **new_tasks = realloc(list->tasks, sizeof(Task *) * 2 * list->capacity);
        if (new_tasks == NULL) {
            free(task);
            pthread_mutex_unlock(&list->mutex);
            return;
        }
        list->tasks = new_tasks;
        list->capacity *= 2;
    }
    list->tasks[list->count++] = task;
    pthread_mutex_unlock(&list->mutex);
}

// Function to retrieve the next task from the list
Task *getNextTask(TaskList *list) {
    Task *task = NULL;
    pthread_mutex_lock(&list->mutex);
    if (list->count > 0) {
        task = list->tasks[0];
        for (size_t i = 1; i < list->count; i++) {
            list->tasks[i - 1] = list->tasks[i];
        }
        list->count--;
    }
    pthread_mutex_unlock(&list->mutex);
    return task;
}

// Function to update the priority of a task in the list
void updateTaskPriority(TaskList *list, int TASK_ID, int new_priority) {
    Task *task = NULL;
    pthread_mutex_lock(&list->mutex);
    for (size_t i = 0; i < list->count; i++) {
        if (list->tasks[i]->TASK_ID == TASK_ID) {
            task = list->tasks[i];
            break;
        }
    }
    if (task != NULL) {
        task->priority = new_priority;
        for (size_t i = 0; i < list->count - 1; i++) {
            if (list->tasks[i]->priority > task->priority) {
                Task *tmp = list->tasks[i];
                list->tasks[i] = task;
                list->tasks[i + 1] = tmp;
            }
        }
    }
    pthread_mutex_unlock(&list->mutex);
}

// Function to remove a task from the list
void removeTask(TaskList *list, int TASK_ID) {
    Task *task = NULL;
    pthread_mutex_lock(&list->mutex);
    for (size_t i = 0; i < list->count; i++) {
        if (list->tasks[i]->TASK_ID == TASK_ID) {
            task = list->tasks[i];
            break;
        }
    }
    if (task != NULL) {
        for (size_t i = 0; i < list->count - 1; i++) {
            if (list->tasks[i] == task) {
                Task *tmp = list->tasks[i];
                list->tasks[i] = list->tasks[i + 1];
                list->tasks[i + 1] = tmp;
            }
        }
        list->count--;
    }
    pthread_mutex_unlock(&list->mutex);
}
