import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.TimeUnit;

public class EventStreamProcessor {
  private static final int NUM_THREADS = 10;
  private static final int BUFFER_SIZE = 1024 * 1024; // 1 MB
  private static final int MAX_EVENTS_PER_SECOND = 500000;

  private ExecutorService executor;
  private EventBuffer buffer;
  private EventProcessor processor;

  public EventStreamProcessor() {
    this.executor = Executors.newFixedThreadPool(NUM_THREADS);
    this.buffer = new EventBuffer(BUFFER_SIZE);
    this.processor = new EventProcessor();
  }

  public void start() {
    executor.execute(new Runnable() {
      @Override
      public void run() {
        while (true) {
          try {
            // Read events from the buffer and process them
            List<Event> events = buffer.readEvents();
            processor.processEvents(events);
          } catch (InterruptedException e) {
            // Handle interruption
          }
        }
      }
    });
  }

  public void stop() {
    executor.shutdownNow();
  }

  private class EventBuffer {
    private final int bufferSize;
    private final List<Event> events = new ArrayList<>();

    public EventBuffer(int bufferSize) {
      this.bufferSize = bufferSize;
    }

    public void addEvent(Event event) {
      synchronized (events) {
        if (events.size() >= bufferSize) {
          events.remove(0); // Remove the oldest event
        }
        events.add(event);
      }
    }

    public List<Event> readEvents() {
      synchronized (events) {
        return new ArrayList<>(events);
      }
    }
  }

  private class EventProcessor {
    private final Map<String, Integer> eventCounts = new HashMap<>();

    public void processEvents(List<Event> events) {
      for (Event event : events) {
        // Process the event and update the event counts map
        String eventType = event.getType();
        int count = eventCounts.getOrDefault(eventType, 0);
        count++;
        eventCounts.put(eventType, count);
      }
    }
  }
}
```
