    float frequency;
    char* context;
} item;

// Function to dynamically allocate memory for the arrays
void allocate_memory(int num_keywords, int num_lines) {
    // Allocate memory for the double precision floating-point numbers array
    double* frequencies = (double*)malloc(num_keywords * sizeof(double));
    if (!frequencies) {
        fprintf(stderr, "Error: failed to allocate memory for frequencies\n");
        exit(1);
    }

    // Allocate memory for the char strings array
    char** contexts = (char**)malloc(num_keywords * sizeof(char*));
    if (!contexts) {
        fprintf(stderr, "Error: failed to allocate memory for contexts\n");
        exit(1);
    }

    // Allocate memory for the struct item objects array
    item* items = (item*)malloc(num_lines * sizeof(item));
    if (!items) {
        fprintf(stderr, "Error: failed to allocate memory for items\n");
        exit(1);
    }
}

// Function to process a single log file and extract keywords
void process_log_file(char* filename, int num_keywords, char** keywords) {
    // Open the log file
    FILE* fp = fopen(filename, "r");
    if (!fp) {
        fprintf(stderr, "Error: failed to open file %s\n", filename);
        exit(1);
    }

    // Read the contents of the log file line by line
    char* line = NULL;
    size_t len = 0;
    ssize_t read;
    while ((read = getline(&line, &len, fp)) != -1) {
        // Extract keywords from the current line
        for (int i = 0; i < num_keywords; i++) {
            char* keyword = keywords[i];
            if (strstr(line, keyword)) {
                // Increment the frequency of the keyword
                frequencies[i]++;

                // Store the context of the keyword occurrence
                items[num_lines].context = strdup(line);
                items[num_lines].line_number = num_lines;
                items[num_lines].frequency = frequencies[i];
                num_lines++;
            }
        }
    }

    // Close the log file
    fclose(fp);
}

// Function to generate a summary report of keyword occurrences
void generate_report(int num_keywords, char** keywords, double* frequencies) {
    // Print the header of the report
    printf("Keyword Occurrences Report\n");
    printf("---------------------------\n");

    // Print the frequency and context of each keyword occurrence
    for (int i = 0; i < num_keywords; i++) {
        char* keyword = keywords[i];
        double frequency = frequencies[i];
        printf("%s: %f\n", keyword, frequency);
        for (int j = 0; j < num_lines; j++) {
            item* item = &items[j];
            if (strcmp(item->context, keyword) == 0) {
                printf("    Line %d: %s\n", item->line_number, item->context);
            }
        }
    }
}

