            printf("Error: RNTI value out of range\n");
            array[i].rnti = (array[i].rnti < MIN_RNTI) ? MIN_RNTI : MAX_RNTI;
        }
    }

    // Log statistics about the number of valid and invalid RNTI values processed
    *num_valid_rnti = 0;
    *num_invalid_rnti = 0;
    for (uint32_t i = 0; i < max_structures; i++) {
        if (array[i].rnti >= MIN_RNTI && array[i].rnti <= MAX_RNTI) {
            *num_valid_rnti += 1;
        } else {
            *num_invalid_rnti += 1;
        }
    }

    // Ensure thread safety when accessing and modifying shared data structures
    pthread_mutex_lock(&mutex);

    // Return the array of NFAPI_CRC_INDICATION_PDU_T structures
    return array;
}

// Define a function to free the memory allocated for an array of NFAPI_CRC_INDICATION_PDU_T structures
void free_array(NFAPI_CRC_INDICATION_PDU_T *array) {
    // Ensure thread safety when accessing and modifying shared data structures
    pthread_mutex_lock(&mutex);

    // Free the memory allocated for the array of NFAPI_CRC_INDICATION_PDU_T structures
    free(array);
}
