#define MAX_RAND_VALUE 1000000

typedef struct {
    long offset;
    int key;
    record *record;
} DATA_PROCESSOR;

typedef struct {
    int size;
    int capacity;
    DATA_PROCESSOR *processors;
} PROCESSOR_POOL;

void initialize_and_manage_processor_pool(PROCESSOR_POOL *pool) {
    // Initialize the pool with a default capacity of 1000000 records
    pool->size = 0;
    pool->capacity = 1000000;
    pool->processors = (DATA_PROCESSOR *)malloc(sizeof(DATA_PROCESSOR) * pool->capacity);
    if (!pool->processors) {
        fprintf(stderr, "Failed to allocate memory for processor pool\n");
        exit(1);
    }

    // Initialize each record's int field to a random value within the specified range
    for (int i = 0; i < pool->capacity; i++) {
        pool->processors[i].record = (record *)malloc(sizeof(record));
        if (!pool->processors[i].record) {
            fprintf(stderr, "Failed to allocate memory for record %d\n", i);
            exit(1);
        }
        pool->processors[i].record->int_field = MIN_RAND_VALUE + (rand() % (MAX_RAND_VALUE - MIN_RAND_VALUE));
    }
}

void manage_processor_pool(PROCESSOR_POOL *pool, DATA_STREAM *stream) {
    // Acquire a semaphore to ensure thread-safe operations
    sem_wait(&pool->sem);

    // Check if the pool has reached its maximum capacity
    if (pool->size == pool->capacity) {
        // If so, dynamically adjust the capacity by 10%
        int new_capacity = pool->capacity + (pool->capacity / 10);
        DATA_PROCESSOR *new_processors = (DATA_PROCESSOR *)realloc(pool->processors, sizeof(DATA_PROCESSOR) * new_capacity);
        if (!new_processors) {
            fprintf(stderr, "Failed to reallocate memory for processor pool\n");
            exit(1);
        }
        pool->processors = new_processors;
        pool->capacity = new_capacity;
    }

    // Add the new data stream to the pool
    pool->processors[pool->size].offset = stream->offset;
    pool->processors[pool->size].key = stream->key;
    pool->processors[pool->size].record = stream->record;
    pool->size++;

    // Release the semaphore to allow other threads to access the pool
    sem_post(&pool->sem);
}

void destroy_processor_pool(PROCESSOR_POOL *pool) {
    // Acquire a semaphore to ensure thread-safe operations
    sem_wait(&pool->sem);

    // Free all memory allocated for the pool and its contents
    free(pool->processors);
    pool->processors = NULL;
    pool->size = 0;
    pool->capacity = 0;

    // Release the semaphore to allow other threads to access the pool
    sem_post(&pool->sem);
}
