void set_configuration_value(CONFIGURATION_KEY **config, int key_id, int new_value) {
    // Lock the configuration array to prevent race conditions
    pthread_mutex_lock(&config_mutex);

    // Find the configuration key with the specified ID
    for (int i = 0; i < 10; i++) {
        if ((*config)[i].KEY_ID == key_id) {
            // Update the value of the found key and update the last modified timestamp
            (*config)[i].resource->value = new_value;
            (*config)[i].LAST_MODIFIED_TIMESTAMP = time(NULL);

            // Unlock the configuration array and return
            pthread_mutex_unlock(&config_mutex);
            return;
        }
    }

    // If no matching key is found, unlock the configuration array and return an error code
    pthread_mutex_unlock(&config_mutex);
}

// Function to invalidate outdated configurations automatically
void invalidate_outdated_configurations(CONFIGURATION_KEY **config) {
    // Lock the configuration array to prevent race conditions
    pthread_mutex_lock(&config_mutex);

    // Iterate over each configuration key and check if it has been modified recently
    for (int i = 0; i < 10; i++) {
        if ((*config)[i].LAST_MODIFIED_TIMESTAMP < time(NULL) - 3600) {
            // If the key is outdated, invalidate it by setting its value to NULL and updating the last modified timestamp
            (*config)[i].resource->value = NULL;
            (*config)[i].LAST_MODIFIED_TIMESTAMP = time(NULL);
        }
    }

    // Unlock the configuration array and return
    pthread_mutex_unlock(&config_mutex);
