#include <dirent.h>
#include <fcntl.h>
#include <zlib.h>
#include <lzma.h>

using namespace std;

// Constants
const int MAX_FILENAME_LENGTH = 256;
const int MAX_ARCHIVE_SIZE = 100 * 1024 * 1024 * 1024; // 100 GB
const int DEFAULT_COMPRESSION_LEVEL = 6;
const string DEFAULT_COMPRESSION_ALGORITHM = "lzma";
const string DEFAULT_OUTPUT_FORMAT = "tar";
const string DEFAULT_INPUT_FILES = "";
const string DEFAULT_OUTPUT_ARCHIVE = "";
const int DEFAULT_THREADS = 4;

// Structures
struct FileInfo {
    string filename;
    long size;
};

struct CompressionSettings {
    string algorithm;
    int level;
};

struct ArchiveInfo {
    string format;
    vector<FileInfo> files;
    long totalSize;
};

// Functions
void printUsage() {
    cout << "Usage: file-compressor [options]" << endl;
    cout << "Options:" << endl;
    cout << "\t-i, --input <file1,file2,...>  Input files" << endl;
    cout << "\t-o, --output <archive.tar>     Output archive file" << endl;
    cout << "\t-a, --algorithm <lzma|zlib>     Compression algorithm (default: lzma)" << endl;
    cout << "\t-l, --level <0-9>               Compression level (default: 6)" << endl;
    cout << "\t-f, --format <tar|zip>          Output format (default: tar)" << endl;
    cout << "\t-j, --threads <num>             Number of threads to use (default: 4)" << endl;
}

void parseCommandLineArguments(int argc, char* argv[], vector<string>& inputFiles, string& outputArchive, CompressionSettings& settings) {
    for (int i = 1; i < argc; ++i) {
        if (strcmp(argv[i], "-h") == 0 || strcmp(argv[i], "--help") == 0) {
            printUsage();
            exit(0);
        } else if (strcmp(argv[i], "-i") == 0 || strcmp(argv[i], "--input") == 0) {
            inputFiles = splitString(argv[++i], ',');
        } else if (strcmp(argv[i], "-o") == 0 || strcmp(argv[i], "--output") == 0) {
            outputArchive = argv[++i];
        } else if (strcmp(argv[i], "-a") == 0 || strcmp(argv[i], "--algorithm") == 0) {
            settings.algorithm = argv[++i];
        } else if (strcmp(argv[i], "-l") == 0 || strcmp(argv[i], "--level") == 0) {
            settings.level = atoi(argv[++i]);
        } else if (strcmp(argv[i], "-f") == 0 || strcmp(argv[i], "--format") == 0) {
            settings.format = argv[++i];
        } else if (strcmp(argv[i], "-j") == 0 || strcmp(argv[i], "--threads") == 0) {
            settings.threads = atoi(argv[++i]);
        }
    }
}

vector<string> splitString(const string& s, char delimiter) {
    vector<string> tokens;
    string token;
    istringstream stream(s);
    while (getline(stream, token, delimiter)) {
        tokens.push_back(token);
    }
    return tokens;
}

void validateInputFiles(const vector<string>& inputFiles) {
    for (auto& file : inputFiles) {
        struct stat st;
        if (stat(file.c_str(), &st) == -1) {
            cerr << "Error: File not found: " << file << endl;
            exit(EXIT_FAILURE);
        }
    }
}

void validateOutputArchive(const string& outputArchive) {
    if (outputArchive.empty()) {
        cerr << "Error: Output archive not specified" << endl;
        exit(EXIT_FAILURE);
    }
}

void validateCompressionSettings(const CompressionSettings& settings) {
    if (settings.algorithm != "lzma" && settings.algorithm != "zlib") {
        cerr << "Error: Invalid compression algorithm: " << settings.algorithm << endl;
        exit(EXIT_FAILURE);
    }
    if (settings.level < 0 || settings.level > 9) {
        cerr << "Error: Compression level must be between 0 and 9" << endl;
        exit(EXIT_FAILURE);
    }
}

void validateOutputFormat(const string& format) {
    if (format != "tar" && format != "zip") {
        cerr << "Error: Invalid output format: " << format << endl;
        exit(EXIT_FAILURE);
    }
}

void validateThreads(int threads) {
    if (threads < 1 || threads > 64) {
        cerr << "Error: Number of threads must be between 1 and 64" << endl;
        exit(EXIT_FAILURE);
    }
}

void compressFiles(const vector<string>& inputFiles, const string& outputArchive, CompressionSettings settings) {
    validateInputFiles(inputFiles);
    validateOutputArchive(outputArchive);
    validateCompressionSettings(settings);
    validateOutputFormat(settings.format);
    validateThreads(settings.threads);

    // Create output archive file
    ofstream outFile;
    outFile.open(outputArchive, ios::binary | ios::trunc);
    if (!outFile) {
        cerr << "Error: Could not create output archive file" << endl;
        exit(EXIT_FAILURE);
    }

    // Create temporary files for each input file
    vector<string> tempFiles;
    for (auto& file : inputFiles) {
        string tempFile = "temp-" + file;
        ofstream tempOutFile;
        tempOutFile.open(tempFile, ios::binary | ios::trunc);
        if (!tempOutFile) {
            cerr << "Error: Could not create temporary file for input file: " << file << endl;
            exit(EXIT_FAILURE);
        }
        tempFiles.push_back(tempFile);
    }

    // Compress each input file in parallel using the specified compression algorithm and level
    vector<thread> threads;
    for (int i = 0; i < settings.threads; ++i) {
        int threadIdx = i;
        threads.push_back(thread([&]() {
            while (true) {
                string fileToCompress;
                if (!tempFiles[threadIdx].empty()) {
                    fileToCompress = tempFiles[threadIdx];
                    tempFiles[threadIdx] = "";
                } else {
                    break;
                }
                compressFile(fileToCompress, outFile, settings);
            }
        }));
    }

    // Compress each input file in sequence using the specified compression algorithm and level
    for (int i = 0; i < inputFiles.size(); ++i) {
        string fileToCompress = inputFiles[i];
        if (!tempFiles[i].empty()) {
            compressFile(fileToCompress, outFile, settings);
        } else {
            threads[i].join();
        }
    }

    // Clean up temporary files
    for (auto& file : tempFiles) {
        if (!file.empty()) {
            remove(file.c_str());
        }
    }
}

void compressFile(const string& inputFile, ofstream& outFile, CompressionSettings settings) {
    // Open input file
    ifstream inFile;
    inFile.open(inputFile, ios::binary);
    if (!inFile) {
        cerr << "Error: Could not open input file: " << inputFile << endl;
        exit(EXIT_FAILURE);
    }

    // Get file size and allocate buffer
    inFile.seekg(0, ios::end);
    long fileSize = inFile.tellg();
    char* buffer = new char[fileSize];

    // Read input file into buffer
    inFile.seekg(0, ios::beg);
    inFile.read(buffer, fileSize);

    // Compress buffer using specified compression algorithm and level
    string compressedBuffer;
    if (settings.algorithm == "lzma") {
        lzma_stream strm = LZMA_STREAM_INIT;
        strm.next_in = (unsigned char*)buffer;
        strm.avail_in = fileSize;
        int ret = lzma_easy_encoder(&strm, settings.level, LZMA_PRESET_DEFAULT);
        if (ret != LZMA_OK) {
            cerr << "Error: Could not initialize LZMA encoder" << endl;
            exit(EXIT_FAILURE);
        }
        while (true) {
            char* outBuffer = new char[strm.avail_out];
            strm.next_out = (unsigned char*)outBuffer;
            ret = lzma_code(&strm, LZMA_RUN);
            if (ret != LZMA_OK && ret != LZMA_STREAM_END) {
                cerr << "Error: Could not compress input file" << endl;
                exit(EXIT_FAILURE);
            }
            compressedBuffer.append(outBuffer, strm.avail_out);
            delete[] outBuffer;
            if (ret == LZMA_STREAM_END) {
                break;
            }
        }
    } else if (settings.algorithm == "zlib") {
        z_stream strm = Z_STREAM_INIT;
        strm.next_in = (unsigned char*)buffer;
        strm.avail_in = fileSize;
        int ret = deflateInit2(&strm, settings.level, Z_DEFLATED, 15 + 16, 8, Z_DEFAULT_STRATEGY);
        if (ret != Z_OK) {
            cerr << "Error: Could not initialize zlib compressor" << endl;
            exit(EXIT_FAILURE);
        }
        while (true) {
            char* outBuffer = new char[strm.avail_out];
            strm.next_out = (unsigned char*)outBuffer;
            ret = deflate(&strm, Z_FINISH);
            if (ret != Z_STREAM_END && ret != Z_OK) {
                cerr << "Error: Could not compress input file" << endl;
                exit(EXIT_FAILURE);
            }
            compressedBuffer.append(outBuffer, strm.avail_out);
            delete[] outBuffer;
            if (ret == Z_STREAM_END) {
                break;
            }
        }
    }

    // Write compressed buffer to output file
    outFile.write(compressedBuffer.c_str(), compressedBuffer.size());
}

int main(int argc, char* argv[]) {
    vector<string> inputFiles;
    string outputArchive;
    CompressionSettings settings = {DEFAULT_COMPRESSION_ALGORITHM, DEFAULT_COMPRESSION_LEVEL};

    parseCommandLineArguments(argc, argv, inputFiles, outputArchive, settings);

    compressFiles(inputFiles, outputArchive, settings);

    return 0;
}']

