void initialize_configuration_system(struct CONFIGURATION_SYSTEM *config_sys) {
    // Allocate memory for the configuration keys array
    config_sys->CONFIGURATION_KEYS = (struct CONFIGURATION_KEY **)malloc(sizeof(struct CONFIGURATION_KEY *) * 10);
    if (!config_sys->CONFIGURATION_KEYS) {
