    }

    // Initialize the configuration key structure
    config_key->KEY_ID = 0;
    config_key->RESOURCE = NULL;
    config_key->LAST_MODIFIED_TIMESTAMP = time(NULL);

    // Add the user profile to the configuration system
    config_sys->CONFIGURATION_KEYS[config_sys->NUM_CONFIGURATION_KEYS++] = config_key;

    // Release the mutex for thread-safe operations
    pthread_mutex_unlock(&config_sys->MUTEX);

    return config_key;
}

