// Define the structure for a record in the cache
typedef struct {
    int key;
    long offset;
} Record;

// Define the structure for the cache itself
typedef struct {
    int size; // The current size of the cache
    int capacity; // The maximum capacity of the cache
    pthread_mutex_t mutex; // A mutex to protect the cache from concurrent access
    Record* records; // An array of records in the cache
} Cache;

// Define a function to initialize and manage a distributed cache of CUSTOM_OBJECT structures
void initCache(Cache* cache, int capacity) {
    cache->size = 0;
    cache->capacity = capacity;
    cache->records = (Record*)malloc(sizeof(Record) * capacity);
    pthread_mutex_init(&cache->mutex, NULL);
}

// Define a function to add a new record to the cache
void addRecord(Cache* cache, int key, long offset) {
    // Acquire the mutex to prevent concurrent access
    pthread_mutex_lock(&cache->mutex);

    // Check if the cache is full and needs to be resized
    if (cache->size == cache->capacity) {
        // Resize the cache by 50%
        int newCapacity = cache->capacity * 1.5;
        Record* newRecords = (Record*)realloc(cache->records, sizeof(Record) * newCapacity);
        if (newRecords == NULL) {
            // If the reallocation fails, return without adding the record
            pthread_mutex_unlock(&cache->mutex);
            return;
        }
        cache->capacity = newCapacity;
        cache->records = newRecords;
    }

    // Add the new record to the cache
    cache->records[cache->size].key = key;
    cache->records[cache->size].offset = offset;
    cache->size++;

    // Release the mutex and return
    pthread_mutex_unlock(&cache->mutex);
}

// Define a function to get a record from the cache by key
Record* getRecord(Cache* cache, int key) {
    // Acquire the mutex to prevent concurrent access
    pthread_mutex_lock(&cache->mutex);

    // Search for the record in the cache
    for (int i = 0; i < cache->size; i++) {
        if (cache->records[i].key == key) {
            Record* record = &cache->records[i];
            pthread_mutex_unlock(&cache->mutex);
            return record;
        }
    }

    // If the record is not found, return NULL
    pthread_mutex_unlock(&cache->mutex);
    return NULL;
}

// Define a function to remove an expired record from the cache
void removeExpiredRecord(Cache* cache) {
    // Acquire the mutex to prevent concurrent access
    pthread_mutex_lock(&cache->mutex);

    // Search for the first expired record in the cache
    int i = 0;
    while (i < cache->size && cache->records[i].offset > time(NULL)) {
        i++;
    }

    // If an expired record is found, remove it from the cache
    if (i < cache->size) {
        cache->size--;
        for (int j = i; j < cache->size; j++) {
            cache->records[j] = cache->records[j + 1];
        }
    }

    // Release the mutex and return
    pthread_mutex_unlock(&cache->mutex);
}

// Define a function to clean up the cache periodically
void cleanupCache(Cache* cache) {
    // Acquire the mutex to prevent concurrent access
    pthread_mutex_lock(&cache->mutex);

    // Remove any expired records from the cache
    while (cache->size > 0 && cache->records[0].offset <= time(NULL)) {
        removeExpiredRecord(cache);
    }

    // Release the mutex and return
    pthread_mutex_unlock(&cache->mutex);
}
