void extract_keywords(char *filename, Keyword **keywords) {
    // Open the file for reading
    FILE *file = fopen(filename, "r");
    if (file == NULL) {
        printf("Error: unable to open file %s\n", filename);
        return;
    }

    // Read the file line by line and extract keywords
    char line[1024];
    while (fgets(line, 1024, file) != NULL) {
        // Tokenize the line into words
        char *words[100];
        int num_words = tokenize(line, words);

        // Iterate over each word and check if it is a keyword
        for (int i = 0; i < num_words; i++) {
            char *word = words[i];
            if (is_keyword(word)) {
                // Add the keyword to the list of keywords
                Keyword *new_keyword = malloc(sizeof(Keyword));
                new_keyword->keyword = strdup(word);
                new_keyword->frequency = 1;
                keywords[i] = new_keyword;
            }
        }
    }

    // Close the file
    fclose(file);
}

// Function to tokenize a line into words
int tokenize(char *line, char **words) {
    int num_words = 0;
    char *word = strtok(line, " ");
    while (word != NULL) {
        words[num_words++] = word;
        word = strtok(NULL, " ");
    }
    return num_words;
}

// Function to check if a word is a keyword
int is_keyword(char *word) {
    // Check if the word is in the list of keywords
    for (int i = 0; i < num_keywords; i++) {
        if (strcmp(word, keywords[i]->keyword) == 0) {
            return 1;
        }
    }
    return 0;
}

// Function to extract context for a keyword occurrence
void extract_context(char *filename, Keyword *keyword, Context **contexts) {
    // Open the file for reading
    FILE *file = fopen(filename, "r");
    if (file == NULL) {
        printf("Error: unable to open file %s\n", filename);
        return;
    }

    // Read the file line by line and extract context for the keyword
    char line[1024];
    while (fgets(line, 1024, file) != NULL) {
        // Tokenize the line into words
        char *words[100];
        int num_words = tokenize(line, words);

        // Iterate over each word and check if it is a keyword occurrence
        for (int i = 0; i < num_words; i++) {
            char *word = words[i];
            if (strcmp(word, keyword->keyword) == 0) {
                // Add the context to the list of contexts
                Context *new_context = malloc(sizeof(Context));
                new_context->line_number = i;
                new_context->context = strdup(line);
                contexts[i] = new_context;
            }
        }
    }

    // Close the file
    fclose(file);
}

// Function to generate a report for a keyword
void generate_report(char *keyword, int frequency, Context **contexts) {
    // Print the header of the report
    printf("Keyword: %s\n", keyword);
    printf("Frequency: %d\n", frequency);

    // Iterate over each context and print it
    for (int i = 0; i < num_contexts; i++) {
        Context *context = contexts[i];
        printf("Line Number: %d\n", context->line_number);
        printf("Context: %s\n", context->context);
    }
}

// Main function to process the log files and generate reports
int main(int argc, char **argv) {
    // Check if the command line arguments are valid
    if (argc < 3) {
        printf("Usage: %s -k <keywords_file> -o <output_file>\n", argv[0]);
        return 1;
    }

    // Parse the command line options
    char *keywords_filename = NULL;
    char *output_filename = NULL;
    for (int i = 1; i < argc - 1; i++) {
        if (strcmp(argv[i], "-k") == 0) {
            keywords_filename = argv[i + 1];
        } else if (strcmp(argv[i], "-o") == 0) {
            output_filename = argv[i + 1];
        }
    }

    // Read the list of keywords from the file
    Keyword **keywords = NULL;
    int num_keywords = read_keywords(keywords_filename, &keywords);

    // Extract context for each keyword occurrence
    Context **contexts = malloc(sizeof(Context *) * num_keywords);
    for (int i = 0; i < num_keywords; i++) {
        Keyword *keyword = keywords[i];
        extract_context(argv[1], keyword, &contexts[i]);
    }

    // Generate reports for each keyword
    for (int i = 0; i < num_keywords; i++) {
        Keyword *keyword = keywords[i];
        generate_report(keyword->keyword, keyword->frequency, &contexts[i]);
    }

    // Clean up memory
    free(keywords);
    free(contexts);

    return 0;
}
