// Function to dynamically allocate memory for three arrays: offsets, keys, and records
int* allocate_memory(int num_offsets, int num_keys, int num_records) {
    // Validate input parameters
    if (num_offsets < 0 || num_keys < 0 || num_records < 0) {
        return NULL;
    }

    // Allocate memory for the three arrays
    long* offsets = malloc(sizeof(long) * num_offsets);
    int* keys = malloc(sizeof(int) * num_keys);
    record** records = malloc(sizeof(record*) * num_records);

    // Initialize the value field in each record structure to a random integer within a specified range
    srand(time(NULL));
    for (int i = 0; i < num_records; i++) {
        records[i] = malloc(sizeof(record));
        records[i]->value = rand() % 100 + 1; // random integer within [1, 100]
    }

    // Return pointers to the three allocated arrays along with a status indicator if the operation was successful
    return offsets && keys && records ? offsets : NULL;
}

// Function to free memory allocated by allocate_memory()
void free_memory(int* offsets, int* keys, record** records) {
    // Free memory for the three arrays
    free(offsets);
    free(keys);
    for (int i = 0; i < num_records; i++) {
        free(records[i]);
    }
}
