// Define a structure to represent the shared resource
typedef struct {
    int* data; // Array of integers used for processing and storing data from an external data source
    size_t size; // Size of the array
    pthread_mutex_t mutex; // Mutex for synchronizing access to the shared resource
    pthread_cond_t cond; // Condition variable for signaling changes in the shared resource
} SharedResource;

// Function to initialize the shared resource
void initSharedResource(SharedResource* res) {
    res->data = malloc(sizeof(int) * res->size);
    if (res->data == NULL) {
        fprintf(stderr, "Failed to allocate memory for shared resource\n");
        exit(EXIT_FAILURE);
    }
    pthread_mutex_init(&res->mutex, NULL);
    pthread_cond_init(&res->cond, NULL);
}

// Function to clean up the shared resource
void cleanupSharedResource(SharedResource* res) {
    free(res->data);
    pthread_mutex_destroy(&res->mutex);
    pthread_cond_destroy(&res->cond);
}

// Function to access the shared resource safely
void accessSharedResource(SharedResource* res, int index, int value) {
    // Lock the mutex before accessing the shared resource
    pthread_mutex_lock(&res->mutex);

    // Check if the external data source has provided new data
    if (res->data[index] != value) {
        // Update the shared resource with the new data
        res->data[index] = value;

        // Signal any waiting threads that the shared resource has changed
        pthread_cond_signal(&res->cond);
    }

    // Unlock the mutex after accessing the shared resource
    pthread_mutex_unlock(&res->mutex);
}

// Function to handle potential memory leaks and ensure all resources are properly cleaned up after use
void handleMemoryLeaks(SharedResource* res) {
    if (res->data != NULL) {
        free(res->data);
    }
    pthread_mutex_destroy(&res->mutex);
    pthread_cond_destroy(&res->cond);
}
