#include <iostream>
#include <fstream>
#include <string>
#include <vector>
#include <map>
#include <set>
#include <algorithm>
#include <thread>
#include <mutex>
#include <chrono>

using namespace std;

// Command line options
struct Options {
    string keywords_file;
    string output_file;
};

// Keyword extraction and reporting
class KeywordExtractor {
public:
    KeywordExtractor(const vector<string>& keywords) : keywords_(keywords) {}

    void extractKeywords(ifstream& log_file, map<string, int>& keyword_counts, set<int>& line_numbers) {
        string line;
        while (getline(log_file, line)) {
            for (const auto& keyword : keywords_) {
                if (line.find(keyword) != string::npos) {
                    keyword_counts[keyword]++;
                    line_numbers.insert(log_file.tellg());
                }
            }
        }
    }

private:
    const vector<string>& keywords_;
};

// Report generation
class ReportGenerator {
public:
    ReportGenerator(const map<string, int>& keyword_counts, const set<int>& line_numbers) : keyword_counts_(keyword_counts), line_numbers_(line_numbers) {}

    void generateReport(ofstream& output_file) {
        for (const auto& [keyword, count] : keyword_counts_) {
            output_file << keyword << " - " << count << endl;
            for (const auto& line_number : line_numbers_) {
                output_file << line_number << endl;
            }
        }
    }

private:
    const map<string, int>& keyword_counts_;
    const set<int>& line_numbers_;
};

// Main function
int main(int argc, char** argv) {
    // Parse command line options
    Options options;
    if (argc == 1 || strcmp(argv[1], "--help") == 0) {
        cout << "Usage: " << argv[0] << " -k <keywords_file> -o <output_file>" << endl;
        return 0;
    } else if (strcmp(argv[1], "-k") == 0) {
        options.keywords_file = argv[2];
    } else if (strcmp(argv[1], "-o") == 0) {
        options.output_file = argv[2];
    }

    // Load keywords from file
    vector<string> keywords;
    ifstream keywords_file(options.keywords_file);
    string line;
    while (getline(keywords_file, line)) {
        keywords.push_back(line);
    }

    // Process log files
    map<string, int> keyword_counts;
    set<int> line_numbers;
    for (const auto& file : options.input_files) {
        ifstream log_file(file);
        KeywordExtractor extractor(keywords);
        extractor.extractKeywords(log_file, keyword_counts, line_numbers);
    }

    // Generate report
    ofstream output_file(options.output_file);
    ReportGenerator generator(keyword_counts, line_numbers);
    generator.generateReport(output_file);

    return 0;
}']

