    // Parse command line arguments and read the keywords file
    if (argc < 3) {
        printf("Usage: %s -k <keywords_file> -o <output_file>\n", argv[0]);
        exit(1);
    }
    for (int i=1; i<argc; i++) {
        if (!strcmp(argv[i], "-h") || !strcmp(argv[i], "--help")) {
            printf("Usage: %s -k <keywords_file> -o <output_file>\n", argv[0]);
            exit(1);
        } else if (!strcmp(argv[i], "-k")) {
            keywords_file = argv[++i];
        } else if (!strcmp(argv[i], "-o")) {
            output_file = argv[++i];
        }
    }
