    if (access(options->input_file, R_OK) != 0) {
        is_missing = true;
        error_message = "Input file does not exist or is not readable";
    } else {
        // Get the size of the input file
        struct stat file_stats;
        if (stat(options->input_file, &file_stats) != 0) {
            is_corrupted = true;
            error_message = "Input file is corrupted or missing";
        } else {
            file_size = file_stats.st_size;
        }
    }

    // Check if output file exists and is writable
    if (access(options->output_file, W_OK) != 0) {
        is_missing = true;
        error_message = "Output file does not exist or is not writable";
    }

    // Check if transformation rules are valid
    if (!is_valid_transformation_rules(options->transformation_rules)) {
        is_invalid_format = true;
        error_message = "Invalid transformation rules specified";
    }

    // Check if output format is supported
    if (!is_supported_output_format(options->output_format)) {
        is_invalid_format = true;
        error_message = "Unsupported output format specified";
    }

    // Handle errors and exit
    if (is_missing || is_corrupted || is_invalid_format) {
        log_error(error_message);
        return;
    }

    // Initialize buffer for reading input file
    buffer = malloc(file_size);
    if (!buffer) {
        log_error("Failed to allocate memory for input file");
        return;
