        is_compressed = true;
    }

    // Process input file in chunks
    size_t chunk_size = 1024 * 1024; // 1 MB
    long num_chunks = (file_size + chunk_size - 1) / chunk_size;
    ChunkData* chunks = malloc(num_chunks * sizeof(ChunkData));
    if (!chunks) {
        log_error("Failed to allocate memory for input file chunks");
        return;
    }

    // Initialize chunks and process each chunk independently
    for (int i = 0; i < num_chunks; i++) {
        ChunkData* chunk = &chunks[i];
        chunk->input_chunk = buffer + i * chunk_size;
        chunk->input_chunk_size = chunk_size;
        chunk->output_chunk = malloc(chunk_size);
        if (!chunk->output_chunk) {
            log_error("Failed to allocate memory for output file chunk");
            return;
