        chunk->output_chunk_size = chunk_size;
        chunk->transformations_applied = 0;
    }

    // Process each chunk in parallel if requested
    if (options->parallel_processing) {
        pthread_t* threads = malloc(num_chunks * sizeof(pthread_t));
        if (!threads) {
            log_error("Failed to allocate memory for thread handles");
            return;
        }

        // Initialize semaphore for synchronizing access to output file
        sem_t* sem = sem_open("/output_file", O_CREAT, 0644, num_chunks);
        if (!sem) {
            log_error("Failed to create semaphore");
            return;
