            ChunkData* chunk = &chunks[i];
            pthread_create(&threads[i], NULL, process_chunk, (void*)chunk);
        }

        // Wait for all threads to finish and merge output chunks
        for (int i = 0; i < num_chunks; i++) {
            pthread_join(threads[i], NULL);
        }

        // Close semaphore and free thread handles
        sem_close(sem);
