#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <unistd.h>
#include <pthread.h>
#include <time.h>
#include <math.h>
#include <stdbool.h>

// Define the maximum number of concurrent queries
#define MAX_CONCURRENT_QUERIES 100

// Define the maximum number of DNS servers to use for resolution
#define MAX_DNS_SERVERS 5

// Define the cache size in bytes
#define CACHE_SIZE (1024 * 1024)

// Define the cache entry structure
struct cache_entry {
    char* name;
    int ttl;
    struct sockaddr_in addr;
};

// Define the cache structure
struct cache {
    struct cache_entry** entries;
    size_t capacity;
    size_t count;
};

// Define the DNS server structure
struct dns_server {
    char* name;
    int port;
    struct sockaddr_in addr;
};

// Define the DNS query structure
struct dns_query {
    char* name;
    int type;
    int ttl;
    struct sockaddr_in addr;
};

// Define the DNS response structure
struct dns_response {
    char* name;
    int type;
    int ttl;
    struct sockaddr_in addr;
};

// Define the cache entry comparison function
int compare_cache_entries(const void* a, const void* b) {
    return strcmp(((struct cache_entry*)a)->name, ((struct cache_entry*)b)->name);
}

// Define the DNS server comparison function
int compare_dns_servers(const void* a, const void* b) {
    return strcmp(((struct dns_server*)a)->name, ((struct dns_server*)b)->name);
}

// Define the DNS query comparison function
int compare_dns_queries(const void* a, const void* b) {
    return strcmp(((struct dns_query*)a)->name, ((struct dns_query*)b)->name);
}

// Initialize the cache
void init_cache(struct cache* cache) {
    cache->entries = malloc(sizeof(struct cache_entry*) * CACHE_SIZE);
    cache->capacity = CACHE_SIZE;
    cache->count = 0;
}

// Add an entry to the cache
void add_cache_entry(struct cache* cache, struct cache_entry* entry) {
    if (cache->count < cache->capacity) {
        cache->entries[cache->count++] = entry;
    } else {
        // Evict the least recently used entry from the cache
        int min_ttl = INT_MAX;
        int min_index = -1;
        for (int i = 0; i < cache->capacity; i++) {
            if (cache->entries[i]->ttl < min_ttl) {
                min_ttl = cache->entries[i]->ttl;
                min_index = i;
            }
        }
        free(cache->entries[min_index]);
        cache->entries[min_index] = entry;
    }
}

// Look up an entry in the cache
struct cache_entry* lookup_cache_entry(struct cache* cache, char* name) {
    for (int i = 0; i < cache->count; i++) {
        if (strcmp(cache->entries[i]->name, name) == 0) {
            return cache->entries[i];
        }
    }
    return NULL;
}

// Initialize the DNS server list
void init_dns_server_list(struct dns_server** servers, int num_servers) {
    for (int i = 0; i < num_servers; i++) {
        servers[i] = malloc(sizeof(struct dns_server));
        servers[i]->name = NULL;
        servers[i]->port = 0;
        servers[i]->addr.sin_family = AF_INET;
        servers[i]->addr.sin_port = htons(53);
    }
}

// Add a DNS server to the list
void add_dns_server(struct dns_server** servers, int num_servers, char* name, int port) {
    for (int i = 0; i < num_servers; i++) {
        if (strcmp(servers[i]->name, name) == 0 && servers[i]->port == port) {
            return;
        }
    }
    struct dns_server* server = malloc(sizeof(struct dns_server));
    server->name = strdup(name);
    server->port = port;
    server->addr.sin_family = AF_INET;
    server->addr.sin_port = htons(53);
    servers[num_servers++] = server;
}

// Look up a DNS server in the list
struct dns_server* lookup_dns_server(struct dns_server** servers, int num_servers, char* name) {
    for (int i = 0; i < num_servers; i++) {
        if (strcmp(servers[i]->name, name) == 0) {
            return servers[i];
        }
    }
    return NULL;
}

// Initialize the DNS query list
void init_dns_query_list(struct dns_query** queries, int num_queries) {
    for (int i = 0; i < num_queries; i++) {
        queries[i] = malloc(sizeof(struct dns_query));
        queries[i]->name = NULL;
        queries[i]->type = 0;
        queries[i]->ttl = 0;
    }
}

// Add a DNS query to the list
void add_dns_query(struct dns_query** queries, int num_queries, char* name, int type) {
    for (int i = 0; i < num_queries; i++) {
        if (strcmp(queries[i]->name, name) == 0 && queries[i]->type == type) {
            return;
        }
    }
    struct dns_query* query = malloc(sizeof(struct dns_query));
    query->name = strdup(name);
    query->type = type;
