}

// Look up a DNS query in the list
struct dns_query* lookup_dns_query(struct dns_query** queries, int num_queries, char* name) {
    for (int i = 0; i < num_queries; i++) {
        if (strcmp(queries[i]->name, name) == 0) {
            return queries[i];
        }
    }
    return NULL;
}

// Initialize the DNS response list
void init_dns_response_list(struct dns_response** responses, int num_responses) {
    for (int i = 0; i < num_responses; i++) {
        responses[i] = malloc(sizeof(struct dns_response));
        responses[i]->name = NULL;
        responses[i]->type = 0;
        responses[i]->ttl = 0;
