}

// Add a DNS response to the list
void add_dns_response(struct dns_response** responses, int num_responses, char* name, int type) {
    for (int i = 0; i < num_responses; i++) {
        if (strcmp(responses[i]->name, name) == 0 && responses[i]->type == type) {
            return;
        }
    }
    struct dns_response* response = malloc(sizeof(struct dns_response));
    response->name = strdup(name);
    response->type = type;
    response->ttl = 0;
    responses[num_responses++] = response;
}

// Look up a DNS response in the list
struct dns_response* lookup_dns_response(struct dns_response** responses, int num_responses, char* name) {
    for (int i = 0; i < num_responses; i++) {
        if (strcmp(responses[i]->name, name) == 0) {
            return responses[i];
        }
    }
    return NULL;
}

// Parse an XML document using XPath and dynamically allocate memory for interconnected data structures based on the results
struct dns_response* parseXMLAndAllocateMemory(char* xml, char* xpath) {
    // Initialize the XML parser
    xmlParserCtxtPtr ctxt = xmlNewParserCtxt();
    if (!ctxt) {
        printf("Error: unable to create XML parser context\n");
        return NULL;
    }

    // Parse the XML document using XPath
    xmlDocPtr doc = xmlCtxtReadMemory(ctxt, xml, strlen(xml), "noname.xml", NULL, 0);
    if (!doc) {
        printf("Error: unable to parse XML document\n");
        return NULL;
    }

    // Create a new DNS response structure
    struct dns_response* response = malloc(sizeof(struct dns_response));
    response->name = NULL;
    response->type = 0;
    response->ttl = 0;

    // Iterate over the XML nodes using XPath
    xmlXPathObjectPtr xpathObj = xmlXPathEval(xpath, doc);
    if (!xpathObj) {
        printf("Error: unable to evaluate XPath expression\n");
        return NULL;
    }

    // Iterate over the XML nodes and allocate memory for interconnected data structures based on the results
    xmlNodePtr cur = xpathObj->nodesetval->nodeTab[0];
    while (cur != NULL) {
        if (strcmp(cur->name, "name") == 0) {
            response->name = strdup((char*)xmlNodeGetContent(cur));
        } else if (strcmp(cur->name, "type") == 0) {
            response->type = atoi((char*)xmlNodeGetContent(cur));
        } else if (strcmp(cur->name, "ttl") == 0) {
            response->ttl = atoi((char*)xmlNodeGetContent(cur));
        }
        cur = cur->next;
    }

    // Free the XML parser context and return the DNS response structure
    xmlFreeDoc(doc);
    xmlXPathFreeObject(xpathObj);
    xmlFreeParserCtxt(ctxt);
    return response;
}
