typedef struct {
    int object_id;
    void* resource;
    time_t timestamp;
} custom_object;

// Define a cache data structure to store the custom objects
typedef struct {
    custom_object** objects;
    size_t capacity;
    size_t size;
    pthread_mutex_t mutex;
} cache;

// Initialize and populate the cache with the given number of objects
void init_cache(cache* cache, size_t num_objects) {
    // Allocate memory for the cache data structure
    cache->objects = (custom_object**)malloc(sizeof(custom_object*) * num_objects);
    cache->capacity = num_objects;
    cache->size = 0;

    // Initialize the mutex for thread-safe access to the cache
    pthread_mutex_init(&cache->mutex, NULL);
}

// Add a new custom object to the cache
void add_object(cache* cache, int object_id, void* resource) {
    // Acquire the mutex for thread-safe access to the cache
    pthread_mutex_lock(&cache->mutex);

    // Check if the cache is full and needs to be resized
    if (cache->size == cache->capacity) {
        // Resize the cache by 50%
        cache->capacity *= 1.5;
        cache->objects = (custom_object**)realloc(cache->objects, sizeof(custom_object*) * cache->capacity);
