    // Create a new custom object and add it to the cache
    custom_object* obj = (custom_object*)malloc(sizeof(custom_object));
    obj->object_id = object_id;
    obj->resource = resource;
    obj->timestamp = time(NULL);
    cache->objects[cache->size++] = obj;

    // Release the mutex for thread-safe access to the cache
    pthread_mutex_unlock(&cache->mutex);
}

// Remove an object from the cache by its ID
void remove_object(cache* cache, int object_id) {
    // Acquire the mutex for thread-safe access to the cache
    pthread_mutex_lock(&cache->mutex);

    // Find the index of the object in the cache
    size_t i;
    for (i = 0; i < cache->size; i++) {
        if (cache->objects[i]->object_id == object_id) {
            break;
        }
    }

    // If the object was found, remove it from the cache
    if (i < cache->size) {
        custom_object* obj = cache->objects[i];
        free(obj);
        cache->objects[i] = NULL;
        cache->size--;
    }

    // Release the mutex for thread-safe access to the cache
    pthread_mutex_unlock(&cache->mutex);
}

// Evict expired objects from the cache
void evict_objects(cache* cache) {
    // Acquire the mutex for thread-safe access to the cache
    pthread_mutex_lock(&cache->mutex);

    // Iterate over the objects in the cache and remove any that have expired
    size_t i;
    for (i = 0; i < cache->size; i++) {
        custom_object* obj = cache->objects[i];
        if (obj == NULL) {
            continue;
        }
        time_t current_time = time(NULL);
        if (current_time - obj->timestamp > 300) { // 5 minutes in seconds
            free(obj);
            cache->objects[i] = NULL;
            cache->size--;
        }
    }

    // Release the mutex for thread-safe access to the cache
    pthread_mutex_unlock(&cache->mutex);
}

// Synchronize the cache states between data centers
void synchronize_cache(cache* cache) {
    // Acquire the mutex for thread-safe access to the cache
    pthread_mutex_lock(&cache->mutex);

    // Iterate over the objects in the cache and update their timestamps
    size_t i;
    for (i = 0; i < cache->size; i++) {
        custom_object* obj = cache->objects[i];
        if (obj == NULL) {
            continue;
        }
        time_t current_time = time(NULL);
        obj->timestamp = current_time;
    }

    // Release the mutex for thread-safe access to the cache
    pthread_mutex_unlock(&cache->mutex);
}

// Periodically synchronize the cache states between data centers
void periodic_synchronization(cache* cache) {
    while (1) {
        // Sleep for a random amount of time between 0 and 30 seconds
        sleep(rand() % 30);

        // Synchronize the cache states between data centers
        synchronize_cache(cache);
    }
}

// Log cache hits, misses, evictions, and synchronization events
void log_cache_events(cache* cache) {
    // Acquire the mutex for thread-safe access to the cache
