#include <stdlib.h>
#include <stdio.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

// Define the structure for the cache objects
typedef struct {
    int object_id;
    RESOURCE *resource;
    time_t timestamp;
} CUSTOM_OBJECT;

// Define the cache parameters
#define MAX_CACHE_SIZE 10000
#define MAX_MEMORY_USAGE 50000
#define EVICTION_POLICY LRU
#define GARBAGE_COLLECTION_INTERVAL 300 // in seconds

// Define the cache data structure
typedef struct {
    CUSTOM_OBJECT *objects;
    int size;
    pthread_mutex_t mutex;
} CACHE;

// Initialize the cache
void init_cache(CACHE *cache) {
    // Allocate memory for the cache objects
    cache->objects = (CUSTOM_OBJECT *)malloc(sizeof(CUSTOM_OBJECT) * MAX_CACHE_SIZE);
    if (!cache->objects) {
        printf("Error: Failed to allocate memory for cache\n");
        exit(1);
    }

    // Initialize the mutex for thread-safe operations
    pthread_mutex_init(&cache->mutex, NULL);

    // Set the initial size of the cache
    cache->size = 0;
}

// Add an object to the cache
void add_object(CACHE *cache, int object_id, RESOURCE *resource) {
    pthread_mutex_lock(&cache->mutex);

    // Check if the cache is full
    if (cache->size == MAX_CACHE_SIZE) {
        printf("Error: Cache is full\n");
        exit(1);
    }

    // Allocate memory for the new object
    CUSTOM_OBJECT *new_object = (CUSTOM_OBJECT *)malloc(sizeof(CUSTOM_OBJECT));
    if (!new_object) {
        printf("Error: Failed to allocate memory for new object\n");
        exit(1);
    }

    // Set the fields of the new object
    new_object->object_id = object_id;
    new_object->resource = resource;
    new_object->timestamp = time(NULL);

    // Add the new object to the cache
    cache->objects[cache->size++] = *new_object;

    pthread_mutex_unlock(&cache->mutex);
}

// Get an object from the cache
CUSTOM_OBJECT *get_object(CACHE *cache, int object_id) {
    pthread_mutex_lock(&cache->mutex);

    // Search for the object in the cache
    for (int i = 0; i < cache->size; i++) {
        if (cache->objects[i].object_id == object_id) {
            // Update the timestamp of the found object
            cache->objects[i].timestamp = time(NULL);

            pthread_mutex_unlock(&cache->mutex);
            return &cache->objects[i];
        }
    }

    // If the object is not found, return NULL
    pthread_mutex_unlock(&cache->mutex);
    return NULL;
}

// Evict expired objects from the cache
void evict_expired_objects(CACHE *cache) {
    pthread_mutex_lock(&cache->mutex);

    // Iterate over the cache and remove any expired objects
    for (int i = 0; i < cache->size; i++) {
        if (cache->objects[i].timestamp + GARBAGE_COLLECTION_INTERVAL <= time(NULL)) {
            free(&cache->objects[i]);
            cache->size--;
        }
    }

    pthread_mutex_unlock(&cache->mutex);
}

// Shut down the cache
void shutdown_cache(CACHE *cache) {
    pthread_mutex_destroy(&cache->mutex);
    free(cache->objects);
}
