    cache->objects = (custom_object_t**)malloc(capacity * sizeof(custom_object_t*));
    if (!cache->objects) {
        printf("Error: failed to allocate memory for objects\n");
        exit(1);
    }

    // Initialize the mutex for thread-safe access
    pthread_mutex_init(&cache->mutex, NULL);

    // Set the capacity and eviction policy
    cache->capacity = capacity;
    cache->eviction_policy = eviction_policy;
}

// Add a new object to the cache
void add_object(cache_t* cache, custom_object_t* object) {
    // Acquire the mutex for thread-safe access
    pthread_mutex_lock(&cache->mutex);

    // Check if the cache is full and evict an object if necessary
    if (cache->size == cache->capacity) {
        switch (cache->eviction_policy) {
            case LRU:
                // Evict the least recently used object
                break;
            case FIFO:
                // Evict the first object in the cache
                break;
            default:
                printf("Error: invalid eviction policy\n");
                exit(1);
        }
    }

    // Add the new object to the cache
    cache->objects[cache->size++] = object;

    // Release the mutex
    pthread_mutex_unlock(&cache->mutex);
}

// Get an object from the cache by its ID
custom_object_t* get_object(cache_t* cache, int id) {
    // Acquire the mutex for thread-safe access
    pthread_mutex_lock(&cache->mutex);

    // Search for the object in the cache
    for (size_t i = 0; i < cache->size; i++) {
        if (cache->objects[i]->object_id == id) {
            // Update the timestamp of the found object
            cache->objects[i]->timestamp = time(NULL);

            // Release the mutex and return the found object
            pthread_mutex_unlock(&cache->mutex);
            return cache->objects[i];
        }
    }

    // Release the mutex and return NULL if the object was not found
    pthread_mutex_unlock(&cache->mutex);
    return NULL;
}

// Evict an object from the cache by its ID
void evict_object(cache_t* cache, int id) {
    // Acquire the mutex for thread-safe access
    pthread_mutex_lock(&cache->mutex);

    // Search for the object in the cache
    for (size_t i = 0; i < cache->size; i++) {
        if (cache->objects[i]->object_id == id) {
            // Remove the found object from the cache
            cache->objects[i] = NULL;
            break;
        }
    }

    // Release the mutex
    pthread_mutex_unlock(&cache->mutex);
}

// Monitor the cache performance metrics
void monitor_cache(cache_t* cache) {
    // Acquire the mutex for thread-safe access
    pthread_mutex_lock(&cache->mutex);

    // Calculate the hit rate, miss rate, and average access latency
    double hit_rate = 0;
    double miss_rate = 0;
    double avg_access_latency = 0;
    for (size_t i = 0; i < cache->size; i++) {
        if (cache->objects[i] != NULL) {
            hit_rate++;
            avg_access_latency += time(NULL) - cache->objects[i]->timestamp;
        } else {
            miss_rate++;
        }
    }
    avg_access_latency /= (hit_rate + miss_rate);

    // Print the performance metrics to the console
    printf("Cache hit rate: %f\n", hit_rate / (hit_rate + miss_rate));
    printf("Cache miss rate: %f\n", miss_rate / (hit_rate + miss_rate));
    printf("Average access latency: %f\n", avg_access_latency);

    // Release the mutex
    pthread_mutex_unlock(&cache->mutex);
}

// Custom LRU eviction algorithm
void lru_evict(cache_t* cache) {
    // Acquire the mutex for thread-safe access
    pthread_mutex_lock(&cache->mutex);

    // Find the least recently used object in the cache
    size_t min_timestamp = time(NULL);
    size_t lru_index = 0;
    for (size_t i = 0; i < cache->size; i++) {
        if (cache->objects[i] != NULL && cache->objects[i]->timestamp < min_timestamp) {
            min_timestamp = cache->objects[i]->timestamp;
            lru_index = i;
        }
    }

    // Evict the least recently used object from the cache
    cache->objects[lru_index] = NULL;

    // Release the mutex
    pthread_mutex_unlock(&cache->mutex);
}

// Custom FIFO eviction algorithm
void fifo_evict(cache_t* cache) {
    // Acquire the mutex for thread-safe access
    pthread_mutex_lock(&cache->mutex);

    // Evict the first object in the cache
    cache->objects[0] = NULL;

    // Shift all objects to the left by one position
    for (size_t i = 1; i < cache->size; i++) {
        cache->objects[i - 1] = cache->objects[i];
    }

    // Release the mutex
    pthread_mutex_unlock(&cache->mutex);
}
