public class PokemonDataProcessor {
    public static void main(String[] args) throws Exception {
        // Parse command-line arguments
        if (args.length == 0) {
            System.out.println("Usage: java PokemonDataProcessor [options] <input_file>");
            System.out.println("Options:");
            System.out.println("  --manpage\tDisplay detailed usage instructions");
            System.out.println("  -o <output_file>\tSpecify an output file for results");
            return;
        }

        // Check if input file exists and is a valid Pokemon data file
        File inputFile = new File(args[0]);
        if (!inputFile.exists() || !inputFile.isFile()) {
            System.out.println("Error: Input file does not exist or is not a valid Pokemon data file");
            return;
        }

        // Open input file and output file for reading/writing
        BufferedReader reader = new BufferedReader(new FileReader(inputFile));
        PrintWriter writer = null;
        if (args.length > 1 && args[1].startsWith("-o")) {
            String outputFileName = args[1].substring(2);
            writer = new PrintWriter(outputFileName, "UTF-8");
        } else {
            writer = new PrintWriter(System.out, true);
        }

        // Process input file line by line and write results to output file
        String line;
