// Custom data structure for storing DNS records
typedef struct record {
    int key;
    long offset;
} record_t;

// Function to parse an XML document using XPath and dynamically allocate memory for interconnected data structures
record_t* ParseXMLAndAllocateMemory(const char* xml, const char* xpath) {
    // Initialize variables
    int i = 0;
    long offset = 0;
    record_t* records = NULL;

    // Create a new memory pool for dynamic allocation
    struct mpool *pool = mpool_create(1024);

    // Parse the XML document using XPath
    xmlXPathContextPtr xpathCtx = xmlXPathNewContext(xml);
    xmlXPathObjectPtr xpathObj = xmlXPathEval(xpath, xpathCtx);

    // Iterate over the results and allocate memory for each record
    while (i < xpathObj->nodesetval->nodeNr) {
        xmlNodePtr node = xpathObj->nodesetval->nodeTab[i];
        record_t* record = mpool_alloc(pool, sizeof(record_t));
        record->key = atoi(xmlGetProp(node, "key"));
        record->offset = offset;
        records = realloc(records, (i + 1) * sizeof(record_t));
        records[i] = *record;
        offset += strlen(xmlNodeGetContent(node)) + 1;
        i++;
    }

    // Clean up resources
    xmlXPathFreeObject(xpathObj);
    xmlXPathFreeContext(xpathCtx);
    mpool_destroy(pool);

    return records;
}

