// Define the structure to store user profiles
typedef struct {
    char *username;
    char *email;
    time_t creation_date;
} profile_t;

// Define a hash table to index profiles by username
static GHashTable *profiles = NULL;

// Define a mutex for thread safety
static pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

// Function to add a new user profile
void add_profile(const char *username, const char *email) {
    // Check if the username is already taken
    if (g_hash_table_contains(profiles, username)) {
        printf("Error: Username '%s' is already taken\n", username);
        return;
    }

    // Create a new profile structure and add it to the hash table
    profile_t *new_profile = g_new0(profile_t, 1);
    new_profile->username = g_strdup(username);
    new_profile->email = g_strdup(email);
    new_profile->creation_date = time(NULL);
    g_hash_table_insert(profiles, username, new_profile);
}

// Function to update an existing user profile
void update_profile(const char *username, const char *email) {
    // Check if the username exists in the hash table
    if (!g_hash_table_contains(profiles, username)) {
        printf("Error: Username '%s' does not exist\n", username);
        return;
    }

    // Get the existing profile structure and update its email field
    profile_t *existing_profile = g_hash_table_lookup(profiles, username);
    existing_profile->email = g_strdup(email);
}

// Function to delete a user profile
void delete_profile(const char *username) {
    // Check if the username exists in the hash table
    if (!g_hash_table_contains(profiles, username)) {
        printf("Error: Username '%s' does not exist\n", username);
        return;
    }

    // Get the existing profile structure and remove it from the hash table
    profile_t *existing_profile = g_hash_table_lookup(profiles, username);
    g_hash_table_remove(profiles, username);
}

// Function to list all user profiles
void list_profiles() {
    // Iterate over the hash table and print each profile's information
    GHashTableIter iter;
    gpointer value;
    g_hash_table_iter_init(&iter, profiles);
    while (g_hash_table_iter_next(&iter, NULL, &value)) {
        profile_t *profile = value;
        printf("Username: %s\nEmail: %s\nCreation Date: %s\n", profile->username, profile->email, ctime(&profile->creation_date));
    }
}

// Function to export the current list of profiles to a file
void export_profiles(const char *output_file) {
    // Create a JSON object to store the profile information
    json_object *json = json_object_new_array();

    // Iterate over the hash table and add each profile's information to the JSON object
    GHashTableIter iter;
    gpointer value;
    g_hash_table_iter_init(&iter, profiles);
    while (g_hash_table_iter_next(&iter, NULL, &value)) {
        profile_t *profile = value;
        json_object *json_profile = json_object_new_object();
        json_object_object_add(json_profile, "username", json_object_new_string(profile->username));
        json_object_object_add(json_profile, "email", json_object_new_string(profile->email));
        json_object_object_add(json_profile, "creation_date", json_object_new_int64(profile->creation_date));
        json_object_array_add(json, json_profile);
    }

    // Write the JSON object to the output file
    FILE *output = fopen(output_file, "w");
    if (output == NULL) {
        printf("Error: Could not open output file '%s'\n", output_file);
        return;
    }
    json_object_to_file(output, json);
    fclose(output);
}

// Function to handle command line arguments and execute the appropriate action
void handle_arguments(int argc, char **argv) {
    // Check if the user provided any arguments
    if (argc == 1) {
        printf("Usage: %s [options]\n", argv[0]);
        return;
    }

    // Iterate over the command line options and execute the appropriate action
    for (int i = 1; i < argc; i++) {
        if (strcmp(argv[i], "-a") == 0) {
            // Add a new user profile
            if (argc <= i + 2) {
                printf("Error: Missing username or email\n");
                return;
            }
            add_profile(argv[i + 1], argv[i + 2]);
        } else if (strcmp(argv[i], "-u") == 0) {
            // Update an existing user profile
            if (argc <= i + 2) {
                printf("Error: Missing username or email\n");
                return;
            }
            update_profile(argv[i + 1], argv[i + 2]);
        } else if (strcmp(argv[i], "-d") == 0) {
            // Delete a user profile
            if (argc <= i + 1) {
                printf("Error: Missing username\n");
                return;
            }
            delete_profile(argv[i + 1]);
        } else if (strcmp(argv[i], "-l") == 0) {
            // List all user profiles
            list_profiles();
        } else if (strcmp(argv[i], "-o") == 0) {
            // Export the current list of profiles to a file
            if (argc <= i + 1) {
                printf("Error: Missing output file\n");
                return;
            }
            export_profiles(argv[i + 1]);
        } else if (strcmp(argv[i], "--help") == 0) {
            // Display usage information and options
            printf("Usage: %s [options]\n", argv[0]);
            printf("Options:\n");
            printf("  -a username email    Add a new user profile\n");
            printf("  -u username email    Update an existing user profile\n");
            printf("  -d username         Delete a user profile\n");
            printf("  -l                  List all user profiles\n");
            printf("  -o output_file      Export the current list of profiles to a file\n");
        } else {
            // Display an error message for any invalid options
            printf("Error: Invalid option '%s'\n", argv[i]);
            return;
        }
    }
}

int main(int argc, char **argv) {
    // Initialize the hash table and mutex
    profiles = g_hash_table_new_full(g_str_hash, g_str_equal, g_free, g_free);
    pthread_mutex_init(&lock, NULL);

    // Handle command line arguments and execute the appropriate action
    handle_arguments(argc, argv);

    // Clean up the hash table and mutex
    g_hash_table_destroy(profiles);
    pthread_mutex_destroy(&lock);

    return 0;
}
