public class CacheManager
{
    private readonly Dictionary<int, CUSTOM_OBJECT> _cache = new Dictionary<int, CUSTOM_OBJECT>();
    private readonly object _lock = new object();

    public async Task<bool> UpdateElementAsync(int pageSectionId, int elementId, string htmlContent)
    {
        // Acquire lock to ensure thread-safe operations on cache
        lock (_lock)
        {
            // Check if the element exists in the cache
            if (!_cache.ContainsKey(elementId))
            {
                // If not, create a new CUSTOM_OBJECT structure and add it to the cache
                _cache[elementId] = new CUSTOM_OBJECT()
                {
                    ObjectId = elementId,
                    Resource = new RESOURCE(),
                    CurrentTimestamp = DateTime.UtcNow
                };
            }
        }

        // Update the HTML content of the element in the cache
        _cache[elementId].Resource.HtmlContent = htmlContent;

        // Return a response indicating that the page should be refreshed
        return true;
    }

    public async Task<string> GetElementAsync(int pageSectionId, int elementId)
    {
        // Acquire lock to ensure thread-safe operations on cache
        lock (_lock)
        {
            // Check if the element exists in the cache
            if (!_cache.ContainsKey(elementId))
            {
                // If not, return an empty string
                return "";
            }

            // Return the HTML content of the element from the cache
            return _cache[elementId].Resource.HtmlContent;
        }
    }

    public async Task<bool> RemoveElementAsync(int pageSectionId, int elementId)
    {
        // Acquire lock to ensure thread-safe operations on cache
        lock (_lock)
        {
            // Check if the element exists in the cache
            if (!_cache.ContainsKey(elementId))
            {
                // If not, return false
                return false;
            }

            // Remove the element from the cache
            _cache.Remove(elementId);

            // Return true to indicate success
            return true;
        }
    }
}

public class CUSTOM_OBJECT
{
    public int ObjectId { get; set; }
    public RESOURCE Resource { get; set; }
    public DateTime CurrentTimestamp { get; set; }
}

public class RESOURCE
{
    public string HtmlContent { get; set; }
}
