typedef struct task_list {
    task_t* tasks;
    int num_tasks;
    pthread_mutex_t mutex;
    semaphore_t semaphore;
} task_list_t;

// Function to add a new task to the list
void add_task(task_list_t* list, task_t* task) {
    // Acquire the lock on the task list
    pthread_mutex_lock(&list->mutex);

    // Check if there is enough space in the task list for the new task
    if (list->num_tasks >= MAX_TASKS) {
        printf("Task list is full, cannot add more tasks\n");
        pthread_mutex_unlock(&list->mutex);
        return;
    }

    // Add the new task to the end of the list
    list->tasks[list->num_tasks++] = *task;

    // Release the lock on the task list
    pthread_mutex_unlock(&list->mutex);
}

// Function to remove a task from the list
void remove_task(task_list_t* list, int task_id) {
    // Acquire the lock on the task list
    pthread_mutex_lock(&list->mutex);

    // Find the index of the task with the given ID
    int i;
    for (i = 0; i < list->num_tasks; i++) {
        if (list->tasks[i].task_id == task_id) {
            break;
        }
    }

    // Check if the task was found in the list
    if (i >= list->num_tasks) {
        printf("Task with ID %d not found\n", task_id);
        pthread_mutex_unlock(&list->mutex);
        return;
    }

    // Remove the task from the list by shifting all tasks after it one position to the left
    for (int j = i + 1; j < list->num_tasks; j++) {
        list->tasks[j - 1] = list->tasks[j];
    }
    list->num_tasks--;

    // Release the lock on the task list
    pthread_mutex_unlock(&list->mutex);
}

// Function to execute a task from the list
void execute_task(task_list_t* list, int task_id) {
    // Acquire the lock on the task list
    pthread_mutex_lock(&list->mutex);

    // Find the index of the task with the given ID
    int i;
    for (i = 0; i < list->num_tasks; i++) {
        if (list->tasks[i].task_id == task_id) {
            break;
        }
    }

    // Check if the task was found in the list
    if (i >= list->num_tasks) {
        printf("Task with ID %d not found\n", task_id);
        pthread_mutex_unlock(&list->mutex);
        return;
    }

    // Execute the task by calling its function pointer
    list->tasks[i].function(list->tasks[i].resource);

    // Release the lock on the task list
    pthread_mutex_unlock(&list->mutex);
}

// Function to update the priority of a task in the list
void update_task_priority(task_list_t* list, int task_id, int new_priority) {
    // Acquire the lock on the task list
    pthread_mutex_lock(&list->mutex);

    // Find the index of the task with the given ID
    int i;
    for (i = 0; i < list->num_tasks; i++) {
        if (list->tasks[i].task_id == task_id) {
            break;
        }
    }

    // Check if the task was found in the list
    if (i >= list->num_tasks) {
        printf("Task with ID %d not found\n", task_id);
        pthread_mutex_unlock(&list->mutex);
        return;
    }

    // Update the priority of the task
    list->tasks[i].priority = new_priority;

    // Release the lock on the task list
    pthread_mutex_unlock(&list->mutex);
}

// Function to clear the task list and free all resources
void clear_task_list(task_list_t* list) {
    // Acquire the lock on the task list
    pthread_mutex_lock(&list->mutex);

    // Free all tasks in the list
    for (int i = 0; i < list->num_tasks; i++) {
        free(list->tasks[i].resource);
    }

    // Clear the task list and release the lock
