Here is an example of how you could implement the C program that parses command line arguments and provides detailed usage information if no input file is specified:
```
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <getopt.h>

// Define constants for command line options
#define OPT_MANPAGE 'm'
#define OPT_CS 'c'
#define OPT_O 'o'

// Define structure to hold input file information
typedef struct {
  char *filename;
  int num_lines;
} InputFile;

// Define function to parse command line arguments and populate InputFile structure
InputFile* parse_args(int argc, char **argv) {
  // Initialize InputFile structure
  InputFile *input = malloc(sizeof(InputFile));
  input->filename = NULL;
  input->num_lines = 0;

  // Parse command line arguments using getopt()
  int c;
  while ((c = getopt(argc, argv, "mco:")) != -1) {
    switch (c) {
      case OPT_MANPAGE:
        printf("Usage: %s [options] <input file>\n", argv[0]);
        printf("\n");
        printf("Options:\n");
        printf("  -m, --manpage\tDisplay detailed usage instructions\n");
        printf("  -c, --cs\tSearch mode with case-sensitive matching\n");
        printf("  -o <output file>\tSpecify an output file for results\n");
        exit(0);
      case OPT_CS:
        input->search_mode = SEARCH_MODE_CASE_SENSITIVE;
        break;
      case OPT_O:
        input->output_file = optarg;
        break;
      default:
        if (optarg) {
          input->filename = optarg;
        } else {
          printf("Error: Missing required argument for option %c\n", c);
          exit(1);
        }
    }
  }

  // Check if input file was specified
  if (!input->filename) {
    printf("Error: No input file specified\n");
    exit(1);
  }

  return input;
}

// Define function to read input file line by line and count number of lines
int count_lines(InputFile *input) {
  FILE *file = fopen(input->filename, "r");
  if (!file) {
    printf("Error: Could not open input file %s\n", input->filename);
    exit(1);
  }

  int num_lines = 0;
  char line[256];
  while (fgets(line, sizeof(line), file)) {
    num_lines++;
  }

  fclose(file);
  return num_lines;
}

int main(int argc, char **argv) {
  // Parse command line arguments and populate InputFile structure
  InputFile *input = parse_args(argc, argv);

  // Count number of lines in input file
  int num_lines = count_lines(input);

  // Print total number of lines to stdout
  printf("Total number of lines: %d\n", num_lines);

  return 0;
}
```
This program uses the `getopt()` function from the standard library to parse command line arguments and populate an `InputFile` structure with information about the input file. It also defines a `count_lines()` function that reads the input file line by line and counts the number of lines. The `main()` function then calls `count_lines()` to count the number of lines in the input file and prints the total number of lines to stdout.

Regarding the CUSTOM_OBJECT structure, you can implement a cache using a hash table or a linked list. Here is an example of how you could implement a cache using a hash table:
```
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <pthread.h>

// Define constants for cache parameters
#define CACHE_SIZE 1000
#define GRACE_PERIOD 30

// Define structure to hold cache entry information
typedef struct {
  OBJECT_ID object_id;
  RESOURCE *resource;
  time_t timestamp;
} CacheEntry;

// Define function to initialize and populate cache
void init_cache(CacheEntry **cache) {
  // Allocate memory for cache entries
  *cache = malloc(sizeof(CacheEntry) * CACHE_SIZE);

  // Initialize cache entries with NULL values
  for (int i = 0; i < CACHE_SIZE; i++) {
    (*cache)[i].object_id = -1;
    (*cache)[i].resource = NULL;
    (*cache)[i].timestamp = 0;
  }
}

// Define function to add an entry to the cache
void add_entry(CacheEntry **cache, OBJECT_ID object_id, RESOURCE *resource) {
  // Find first available slot in cache
  int i = 0;
  while ((*cache)[i].object_id != -1 && i < CACHE_SIZE) {
    i++;
  }

  // If no slots are available, evict the oldest entry
  if (i == CACHE_SIZE) {
    int oldest = 0;
    time_t oldest_timestamp = (*cache)[oldest].timestamp;
    for (int j = 1; j < CACHE_SIZE; j++) {
      if ((*cache)[j].timestamp < oldest_timestamp) {
        oldest = j;
        oldest_timestamp = (*cache)[j].timestamp;
      }
    }
    free((*cache)[oldest].resource);
    (*cache)[oldest].object_id = -1;
    (*cache)[oldest].resource = NULL;
    (*cache)[oldest].timestamp = 0;
  }

  // Add new entry to cache
  (*cache)[i].object_id = object_id;
  (*cache)[i].resource = resource;
  (*cache)[i].timestamp = time(NULL);
}

// Define function to query the cache for a specific OBJECT_ID without evicting it from the cache
CacheEntry *query_cache(CacheEntry **cache, OBJECT_ID object_id) {
  // Find entry in cache with matching OBJECT_ID
  int i = 0;
  while ((*cache)[i].object_id != -1 && (*cache)[i].object_id != object_id) {
    i++;
  }

  // If no matching entry is found, return NULL
  if ((*cache)[i].object_id == -1) {
    return NULL;
  }

  // Return cache entry without evicting it from the cache
  CacheEntry *entry = malloc(sizeof(CacheEntry));
  entry->object_id = (*cache)[i].object_id;
  entry->resource = (*cache)[i].resource;
  entry->timestamp = (*cache)[i].timestamp;
  return entry;
}

// Define function to evict expired objects from the cache automatically
void evict_expired(CacheEntry **cache) {
  // Find oldest entry in cache
  int oldest = 0;
  time_t oldest_timestamp = (*cache)[oldest].timestamp;
  for (int i = 1; i < CACHE_SIZE; i++) {
    if ((*cache)[i].timestamp < oldest_timestamp) {
      oldest = i;
      oldest_timestamp = (*cache)[i].timestamp;
    }
  }

  // Evict oldest entry from cache if it has expired
  time_t current_time = time(NULL);
  if (current_time - (*cache)[oldest].timestamp > GRACE_PERIOD) {
    free((*cache)[oldest].resource);
    (*cache)[oldest].object_id = -1;
    (*cache)[oldest].resource = NULL;
    (*cache)[oldest].timestamp = 0;
  }
}
```
This cache implementation uses a hash table to store cache entries. It initializes the cache with `CACHE_SIZE` slots, each of which can hold an `OBJECT_ID`, a reference to a shared `RESOURCE` structure, and a timestamp for caching validity. The `add_entry()` function adds a new entry to the cache by finding the first available slot in the cache and then evicting the oldest entry if no slots are available. The `query_cache()` function returns a cache entry without evicting it from the cache, or NULL if no matching entry is found. The `evict_expired()` function evicts expired objects from the cache automatically by finding the oldest entry in the cache and then evicting it if it has expired.

