void handle_api_request(char* id, char* name, char* email) {
    // Validate the incoming request for correct formatting and data integrity
    if (id == NULL || name == NULL || email == NULL) {
        printf("Invalid API request: missing required fields\n");
        return;
    }

    // Update the cache with the new user information
    update_cache(id, name);
    update_cache(name, email);
}

void log_operation(char* operation, bool success) {
    // Log the operation and its result to the console
    time_t now = time(NULL);
    char* timestamp = ctime(&now);
    printf("%s %s: %s\n", timestamp, operation, success ? "success" : "failure");
}
