#include <iostream>
#include <fstream>
#include <string>
#include <vector>
#include <map>
#include <algorithm>
#include <thread>
#include <mutex>
#include <condition_variable>
#include <chrono>

using namespace std;

// Define the structure to store the sensor data
struct SensorData {
    int timestamp;
    string sensorID;
    float value;
};

// Define the structure to store the anomaly detection results
struct AnomalyResult {
    int timestamp;
    string sensorID;
    string type;
};

// Define the configuration file format
struct ConfigFile {
    map<string, float> thresholds; // Map of threshold values for each sensor type
    vector<string> sensorTypes; // Vector of supported sensor types
};

// Define the function to read the configuration file
ConfigFile readConfigFile(const string& filename) {
    ConfigFile config;
    ifstream file(filename);
    if (file.is_open()) {
        string line;
        while (getline(file, line)) {
            // Parse the line and extract the threshold values for each sensor type
            istringstream iss(line);
            string token;
            vector<float> thresholds;
            while (iss >> token) {
                thresholds.push_back(stof(token));
            }
            // Add the threshold values to the configuration file
            config.thresholds[sensorTypes.back()] = thresholds;
        }
    } else {
        cerr << "Error: unable to open configuration file" << endl;
    }
    return config;
}

// Define the function to read the sensor data from a file
vector<SensorData> readSensorData(const string& filename) {
    vector<SensorData> data;
    ifstream file(filename);
    if (file.is_open()) {
        string line;
        while (getline(file, line)) {
            // Parse the line and extract the sensor data
            istringstream iss(line);
            SensorData datum;
            iss >> datum.timestamp >> datum.sensorID >> datum.value;
            data.push_back(datum);
        }
    } else {
        cerr << "Error: unable to open sensor data file" << endl;
    }
    return data;
}

// Define the function to detect anomalies in the sensor data
vector<AnomalyResult> detectAnomalies(const vector<SensorData>& data, const ConfigFile& config) {
    vector<AnomalyResult> results;
    for (const auto& datum : data) {
        // Check if the value is within the threshold range for the sensor type
        if (datum.value < config.thresholds[datum.sensorID]) {
            AnomalyResult result;
            result.timestamp = datum.timestamp;
            result.sensorID = datum.sensorID;
            result.type = "low";
            results.push_back(result);
        } else if (datum.value > config.thresholds[datum.sensorID]) {
            AnomalyResult result;
            result.timestamp = datum.timestamp;
            result.sensorID = datum.sensorID;
            result.type = "high";
            results.push_back(result);
        }
    }
    return results;
}

// Define the function to write the anomaly detection results to a file
void writeAnomalyResults(const vector<AnomalyResult>& results, const string& filename) {
    ofstream file(filename);
    if (file.is_open()) {
        for (const auto& result : results) {
            file << result.timestamp << "," << result.sensorID << "," << result.type << endl;
        }
    } else {
        cerr << "Error: unable to open anomaly detection results file" << endl;
    }
}

int main(int argc, char* argv[]) {
    // Check the command line arguments
    if (argc < 3) {
        cerr << "Usage: " << argv[0] << " -c <config_file> -s <sensor_files>" << endl;
        return 1;
    }

    // Read the configuration file and sensor data files
    ConfigFile config = readConfigFile(argv[2]);
    vector<SensorData> data;
    for (int i = 3; i < argc; ++i) {
        data.insert(data.end(), readSensorData(argv[i]).begin(), readSensorData(argv[i]).end());
    }

    // Detect anomalies in the sensor data and write the results to a file
    vector<AnomalyResult> results = detectAnomalies(data, config);
    writeAnomalyResults(results, argv[4]);

    return 0;
}']

