// Compression algorithms supported by the utility
enum class CompressionAlgorithm { LZMA, ZLIB, BZIP2 };

// Compression level options for each algorithm
enum class CompressionLevel { FASTEST, FASTER, OPTIMAL };

// Output formats supported by the utility
enum class OutputFormat { TAR, ZIP, CUSTOM };

// Struct to store information about a file being compressed
struct FileInfo {
  string path; // Path of the file
  size_t size; // Size of the file in bytes
};

// Struct to store information about a compression job
struct CompressionJob {
  vector<FileInfo> files; // Vector of files to be compressed
  OutputFormat outputFormat; // Output format for the compressed archive
  CompressionAlgorithm algorithm; // Algorithm used for compression
  CompressionLevel level; // Compression level for the job
};

// Struct to store information about a decompression job
struct DecompressionJob {
  string path; // Path of the compressed archive
  OutputFormat outputFormat; // Output format for the decompressed files
};

// Function to compress a file using the specified algorithm and level
void compressFile(const FileInfo& file, CompressionAlgorithm algorithm, CompressionLevel level) {
  // Open the input file in binary mode
  ifstream inputFile(file.path, ios::binary);
  if (!inputFile.is_open()) {
    cerr << "Error: Could not open input file " << file.path << endl;
    return;
  }

  // Open the output file in binary mode
  ofstream outputFile(file.path + ".compressed", ios::binary);
  if (!outputFile.is_open()) {
    cerr << "Error: Could not open output file " << file.path << endl;
    return;
  }

  // Compress the input file using the specified algorithm and level
  switch (algorithm) {
    case CompressionAlgorithm::LZMA: {
      lzma_stream stream = LZMA_STREAM_INIT;
      lzma_ret ret = lzma_easy_encoder(&stream, level, LZMA_PRESET_DEFAULT);
      if (ret != LZMA_OK) {
        cerr << "Error: Could not initialize LZMA encoder" << endl;
        return;
      }
      ret = lzma_code(stream, inputFile, outputFile);
      if (ret != LZMA_STREAM_END) {
        cerr << "Error: Could not compress file using LZMA" << endl;
        return;
      }
      break;
    }
    case CompressionAlgorithm::ZLIB: {
      z_stream stream = Z_STREAM_INIT;
      int ret = deflateInit(&stream, level);
      if (ret != Z_OK) {
        cerr << "Error: Could not initialize ZLIB compressor" << endl;
        return;
      }
      ret = deflateCopy(&stream, inputFile, outputFile);
      if (ret != Z_STREAM_END) {
        cerr << "Error: Could not compress file using ZLIB" << endl;
        return;
      }
      break;
    }
    case CompressionAlgorithm::BZIP2: {
      bz_stream stream = BZ_STREAM_INIT;
      int ret = BZ2_bzCompressInit(&stream, level, 0, 0);
      if (ret != BZ_OK) {
        cerr << "Error: Could not initialize BZIP2 compressor" << endl;
        return;
      }
      ret = BZ2_bzCompress(&stream, inputFile, outputFile);
      if (ret != BZ_STREAM_END) {
        cerr << "Error: Could not compress file using BZIP2" << endl;
        return;
      }
      break;
    }
  }

  // Close the input and output files
  inputFile.close();
  outputFile.close();
}

// Function to decompress a compressed archive using the specified algorithm
void decompressArchive(const string& path, CompressionAlgorithm algorithm) {
  // Open the input file in binary mode
  ifstream inputFile(path, ios::binary);
  if (!inputFile.is_open()) {
    cerr << "Error: Could not open input file " << path << endl;
    return;
  }

  // Open the output file in binary mode
  ofstream outputFile(path + ".decompressed", ios::binary);
  if (!outputFile.is_open()) {
    cerr << "Error: Could not open output file " << path << endl;
    return;
  }

  // Decompress the input file using the specified algorithm
  switch (algorithm) {
    case CompressionAlgorithm::LZMA: {
      lzma_stream stream = LZMA_STREAM_INIT;
      lzma_ret ret = lzma_easy_decoder(&stream, LZMA_PRESET_DEFAULT);
      if (ret != LZMA_OK) {
        cerr << "Error: Could not initialize LZMA decoder" << endl;
        return;
      }
      ret = lzma_code(stream, inputFile, outputFile);
      if (ret != LZMA_STREAM_END) {
        cerr << "Error: Could not decompress file using LZMA" << endl;
        return;
      }
      break;
    }
    case CompressionAlgorithm::ZLIB: {
      z_stream stream = Z_STREAM_INIT;
      int ret = inflateInit(&stream);
      if (ret != Z_OK) {
        cerr << "Error: Could not initialize ZLIB decompressor" << endl;
        return;
      }
      ret = inflateCopy(&stream, inputFile, outputFile);
      if (ret != Z_STREAM_END) {
        cerr << "Error: Could not decompress file using ZLIB" << endl;
        return;
      }
      break;
    }
    case CompressionAlgorithm::BZIP2: {
      bz_stream stream = BZ_STREAM_INIT;
      int ret = BZ2_bzDecompressInit(&stream, 0, 0);
      if (ret != BZ_OK) {
        cerr << "Error: Could not initialize BZIP2 decompressor" << endl;
        return;
      }
      ret = BZ2_bzDecompress(&stream, inputFile, outputFile);
      if (ret != BZ_STREAM_END) {
        cerr << "Error: Could not decompress file using BZIP2" << endl;
        return;
      }
      break;
    }
  }

  // Close the input and output files
  inputFile.close();
  outputFile.close();
}

// Function to compress a set of files using the specified algorithm and level
void compressFiles(const vector<FileInfo>& files, CompressionAlgorithm algorithm, CompressionLevel level) {
  // Create a new archive file in binary mode
  ofstream archiveFile("archive.compressed", ios::binary);
  if (!archiveFile.is_open()) {
    cerr << "Error: Could not create output file" << endl;
    return;
  }

  // Compress each file using the specified algorithm and level
  for (const FileInfo& file : files) {
    compressFile(file, algorithm, level);
    archiveFile.write(file.path + ".compressed", ios::binary);
  }

  // Close the archive file
  archiveFile.close();
}

// Function to decompress a compressed archive using the specified algorithm
void decompressArchive(const string& path, CompressionAlgorithm algorithm) {
  // Open the input file in binary mode
  ifstream inputFile(path, ios::binary);
  if (!inputFile.is_open()) {
    cerr << "Error: Could not open input file " << path << endl;
    return;
  }

  // Create a new directory to store the decompressed files
  string outputDir = "decompressed";
  create_directory(outputDir);

  // Decompress each file in the archive using the specified algorithm
  while (inputFile.good()) {
    string filePath;
    inputFile >> filePath;
    decompressArchive(filePath, algorithm);
  }

  // Close the input file
  inputFile.close();
}

// Function to handle compression jobs
void handleCompressionJobs(const vector<CompressionJob>& jobs) {
  for (const CompressionJob& job : jobs) {
    compressFiles(job.files, job.algorithm, job.level);
  }
}

// Function to handle decompression jobs
void handleDecompressionJobs(const vector<DecompressionJob>& jobs) {
  for (const DecompressionJob& job : jobs) {
    decompressArchive(job.path, job.algorithm);
  }
}

int main(int argc, char* argv[]) {
  // Parse command line arguments
  vector<CompressionJob> compressionJobs;
  vector<DecompressionJob> decompressionJobs;
  for (int i = 1; i < argc; ++i) {
    if (strcmp(argv[i], "-c") == 0) {
      // Compress files
      string inputPath = argv[++i];
      string outputPath = argv[++i];
      CompressionAlgorithm algorithm = CompressionAlgorithm::LZMA;
      CompressionLevel level = CompressionLevel::OPTIMAL;
      if (strcmp(argv[i], "-a") == 0) {
        algorithm = CompressionAlgorithm::LZMA;
      } else if (strcmp(argv[i], "-z") == 0) {
        algorithm = CompressionAlgorithm::ZLIB;
      } else if (strcmp(argv[i], "-b") == 0) {
        algorithm = CompressionAlgorithm::BZIP2;
      }
      if (strcmp(argv[i], "-l") == 0) {
        level = CompressionLevel::FASTEST;
      } else if (strcmp(argv[i], "-m") == 0) {
        level = CompressionLevel::FASTER;
      } else if (strcmp(argv[i], "-o") == 0) {
        level = CompressionLevel::OPTIMAL;
      }
      compressionJobs.push_back({inputPath, outputPath, algorithm, level});
    } else if (strcmp(argv[i], "-d") == 0) {
      // Decompress files
      string inputPath = argv[++i];
      string outputPath = argv[++i];
      CompressionAlgorithm algorithm = CompressionAlgorithm::LZMA;
      if (strcmp(argv[i], "-a") == 0) {
        algorithm = CompressionAlgorithm::LZMA;
      } else if (strcmp(argv[i], "-z") == 0) {
        algorithm = CompressionAlgorithm::ZLIB;
      } else if (strcmp(argv[i], "-b") == 0) {
        algorithm = CompressionAlgorithm::BZIP2;
      }
      decompressionJobs.push_back({inputPath, outputPath, algorithm});
    }
  }

  // Handle compression jobs
  handleCompressionJobs(compressionJobs);

  // Handle decompression jobs
  handleDecompressionJobs(decompressionJobs);

  return 0;
}
