#include <iostream>
#include <fstream>
#include <string>
#include <vector>
#include <map>
#include <set>
#include <algorithm>
#include <cstdlib>
#include <ctime>
#include <chrono>

using namespace std;

// Command line options
struct Options {
    string keywords_file;
    string output_file;
};

// Keyword structure
struct Keyword {
    string name;
    int frequency;
    set<int> line_numbers;
    vector<string> context;
};

// Log entry structure
struct LogEntry {
    int line_number;
    string message;
};

// Main function
int main(int argc, char* argv[]) {
    // Parse command line options
    Options options = parse_options(argc, argv);

    // Load keywords from file
    vector<Keyword> keywords = load_keywords(options.keywords_file);

    // Process log files
    map<string, vector<LogEntry>> logs;
    for (auto& log : options.logs) {
        process_log(log, keywords, logs);
    }

    // Generate report
    generate_report(options.output_file, logs, keywords);

    return 0;
}

// Parse command line options
Options parse_options(int argc, char* argv[]) {
    Options options;

    for (int i = 1; i < argc; ++i) {
        string arg = argv[i];
        if (arg == "--help") {
            print_usage();
            exit(0);
        } else if (arg.substr(0, 2) == "-k") {
            options.keywords_file = arg.substr(2);
        } else if (arg.substr(0, 2) == "-o") {
            options.output_file = arg.substr(2);
        } else {
            options.logs.push_back(arg);
        }
    }

    return options;
}

// Load keywords from file
vector<Keyword> load_keywords(string file) {
    vector<Keyword> keywords;

    ifstream fin(file);
    string line;
    while (getline(fin, line)) {
        Keyword keyword;
        keyword.name = line;
        keyword.frequency = 0;
        keywords.push_back(keyword);
    }

    return keywords;
}

// Process log file
void process_log(string file, vector<Keyword>& keywords, map<string, vector<LogEntry>>& logs) {
    ifstream fin(file);
    string line;
    int line_number = 0;
    while (getline(fin, line)) {
        ++line_number;
        for (auto& keyword : keywords) {
            if (line.find(keyword.name) != string::npos) {
                keyword.frequency++;
                keyword.line_numbers.insert(line_number);
                keyword.context.push_back(line);
            }
        }
    }

    logs[file] = vector<LogEntry>();
    for (auto& keyword : keywords) {
        LogEntry log_entry;
        log_entry.line_number = keyword.frequency;
        log_entry.message = keyword.name + " appears " + to_string(keyword.frequency) + " times";
        logs[file].push_back(log_entry);
    }
}

// Generate report
void generate_report(string file, map<string, vector<LogEntry>>& logs, vector<Keyword>& keywords) {
    ofstream fout(file);
    for (auto& log : logs) {
        fout << "Log File: " << log.first << endl;
        for (auto& entry : log.second) {
            fout << entry.line_number << ": " << entry.message << endl;
        }
    }
}

// Print usage instructions
void print_usage() {
    cout << "Usage: keyword-extractor [options] <log files>" << endl;
    cout << "Options:" << endl;
    cout << "-k <keywords file>  File containing list of keywords" << endl;
    cout << "-o <output file>   Output file for report" << endl;
}']

