    // Allocate memory for the queue and its tasks
    queue->tasks = (TASK *)malloc(capacity * sizeof(TASK));
    queue->capacity = capacity;
    queue->size = 0;

    // Initialize the mutex for thread-safe operations
    pthread_mutex_init(&queue->mutex, NULL);
}

// Enqueue a task in the queue
void enqueue(QUEUE *queue, TASK task) {
    // Acquire the mutex to ensure thread-safe operations
    pthread_mutex_lock(&queue->mutex);

    // Check if the queue is full
    if (queue->size == queue->capacity) {
        printf("Queue is full, cannot enqueue task\n");
        return;
    }

    // Add the task to the end of the queue
    queue->tasks[queue->size++] = task;

    // Release the mutex
    pthread_mutex_unlock(&queue->mutex);
}

// Dequeue a task from the queue
TASK dequeue(QUEUE *queue) {
    // Acquire the mutex to ensure thread-safe operations
    pthread_mutex_lock(&queue->mutex);

    // Check if the queue is empty
    if (queue->size == 0) {
        printf("Queue is empty, cannot dequeue task\n");
        return;
    }

    // Remove the front task from the queue
    TASK task = queue->tasks[0];
    for (int i = 1; i < queue->size; i++) {
        queue->tasks[i - 1] = queue->tasks[i];
    }
    queue->size--;

    // Release the mutex
    pthread_mutex_unlock(&queue->mutex);

    return task;
}

