#include <iostream>
#include <fstream>
#include <string>
#include <vector>
#include <map>
#include <set>
#include <algorithm>
#include <cstdlib>
#include <ctime>
#include <cmath>

using namespace std;

// Command line options
const string HELP_OPTION = "--help";
const string VERBOSE_OPTION = "-v";
const string OUTPUT_FILE_OPTION = "-o";

// File extensions to process
const set<string> FILE_EXTENSIONS = {".log", ".access", ".error"};

// Error codes to track
const map<int, string> ERROR_CODES = {{404, "Not Found"}, {500, "Internal Server Error"}};

// Output file name
string outputFile;

// Verbose mode flag
bool verboseMode = false;

void printUsage() {
    cout << "Usage: log-summary [options] <directory>" << endl;
    cout << "Options:" << endl;
    cout << "\t" << HELP_OPTION << ": Display usage instructions" << endl;
    cout << "\t" << VERBOSE_OPTION << ": Enable verbose output" << endl;
    cout << "\t" << OUTPUT_FILE_OPTION << " <output_file>: Specify an output file for the report" << endl;
}

void processDirectory(const string& directory) {
    // Get all files in the directory and its subdirectories
    vector<string> files = getFilesInDirectory(directory);

    // Initialize statistics
    int totalLines = 0;
    double averageLineLength = 0.0;
    map<int, int> errorCodes;

    // Process each file
    for (const string& file : files) {
        ifstream inputFile(file);
        if (!inputFile.is_open()) {
            cerr << "Error: Could not open file " << file << endl;
            continue;
        }

        // Read the file line by line
        string line;
        while (getline(inputFile, line)) {
            totalLines++;
            averageLineLength += line.length();

            // Check for error codes
            int code = getErrorCode(line);
            if (code != -1) {
                errorCodes[code]++;
            }
        }
    }

    // Calculate the average line length and write to output file
    if (!outputFile.empty()) {
        ofstream outputFileStream(outputFile, ios::app);
        if (outputFileStream.is_open()) {
            outputFileStream << "Total lines: " << totalLines << endl;
            outputFileStream << "Average line length: " << averageLineLength / totalLines << endl;
            for (const auto& errorCode : errorCodes) {
                outputFileStream << "\t" << errorCode.second << ": " << errorCode.first << endl;
            }
        } else {
            cerr << "Error: Could not open output file " << outputFile << endl;
        }
    }
}

int getErrorCode(const string& line) {
    // Check for specific error codes in the line
    for (const auto& errorCode : ERROR_CODES) {
        if (line.find(errorCode.second) != string::npos) {
            return errorCode.first;
        }
    }

    // Return -1 if no error code found
    return -1;
}

vector<string> getFilesInDirectory(const string& directory) {
    vector<string> files;

    // Get all files in the directory and its subdirectories
    for (const auto& entry : filesystem::directory_iterator(directory)) {
        if (!filesystem::is_directory(entry)) {
            string file = entry.path().string();
            size_t extensionPos = file.find_last_of('.');
            if (extensionPos != string::npos && FILE_EXTENSIONS.count(file.substr(extensionPos))) {
                files.push_back(file);
            }
        }
    }

    return files;
}

int main(int argc, char* argv[]) {
    // Parse command line options
    for (int i = 1; i < argc; i++) {
        string option = argv[i];
        if (option == HELP_OPTION) {
            printUsage();
            return 0;
        } else if (option == VERBOSE_OPTION) {
            verboseMode = true;
        } else if (option.substr(0, OUTPUT_FILE_OPTION.size()) == OUTPUT_FILE_OPTION) {
            outputFile = option.substr(OUTPUT_FILE_OPTION.size());
        } else {
            cerr << "Error: Invalid command line argument " << option << endl;
            return 1;
        }
    }

    // Check if a directory was specified
    if (argc < 2) {
        cerr << "Error: No directory specified" << endl;
        printUsage();
        return 1;
    }

    // Process the directory and its subdirectories
    processDirectory(argv[argc - 1]);

    return 0;
}']

