    pthread_mutex_t mutex;
    sem_t semaphore;
    int num_concurrent_accesses;
} ResourceContentionManager;

// Initialize a priority queue with the given capacity
PriorityQueue* init_priority_queue(int capacity) {
    PriorityQueue* pq = (PriorityQueue*)malloc(sizeof(PriorityQueue));
    pq->tasks = (Task**)malloc(capacity * sizeof(Task*));
    pq->size = 0;
    pq->capacity = capacity;
    pthread_mutex_init(&pq->mutex, NULL);
    sem_init(&pq->semaphore, 0, 1);
    pq->num_pending = 0;
    for (int i = 0; i < 10; i++) {
        pq->avg_processing_time[i] = 0.0;
    }
    return pq;
}

// Enqueue a task with the given priority level and resource reference
void enqueue(PriorityQueue* pq, int priority, void* resource) {
    Task* new_task = (Task*)malloc(sizeof(Task));
    new_task->task_id = pq->size;
    new_task->resource = resource;
    new_task->priority = priority;
    pthread_mutex_lock(&pq->mutex);
    if (pq->size == pq->capacity) {
        // Resize the queue if it is full
        int new_capacity = pq->capacity * 2;
        Task** new_tasks = (Task**)realloc(pq->tasks, new_capacity * sizeof(Task*));
        pq->tasks = new_tasks;
        pq->capacity = new_capacity;
    }
    pq->tasks[pq->size] = new_task;
    pq->size++;
    pthread_mutex_unlock(&pq->mutex);
}

// Dequeue a task with the highest priority level
Task* dequeue(PriorityQueue* pq) {
    Task* task = NULL;
    pthread_mutex_lock(&pq->mutex);
    if (pq->size > 0) {
        // Find the task with the highest priority level
        int max_priority = -1;
        for (int i = 0; i < pq->size; i++) {
            if (max_priority < pq->tasks[i]->priority) {
                max_priority = pq->tasks[i]->priority;
                task = pq->tasks[i];
            }
        }
        // Remove the task from the queue
        for (int i = 0; i < pq->size - 1; i++) {
            if (pq->tasks[i] == task) {
                memmove(pq->tasks + i, pq->tasks + i + 1, (pq->size - i - 1) * sizeof(Task*));
                break;
            }
        }
        pq->size--;
    }
    pthread_mutex_unlock(&pq->mutex);
    return task;
}

// Adjust the priority of a task based on resource availability and completion status
void adjust_priority(PriorityQueue* pq, Task* task) {
    // Check if the task is still pending
    if (task->resource != NULL) {
        // Calculate the new priority level based on resource availability and completion status
        int new_priority = 0;
        for (int i = 0; i < pq->size; i++) {
            if (pq->tasks[i] == task) {
                new_priority = i + 1;
                break;
            }
        }
        // Update the priority level of the task
        pthread_mutex_lock(&pq->mutex);
        task->priority = new_priority;
        pthread_mutex_unlock(&pq->mutex);
    }
}

// Monitor the state of the queue, including the number of pending tasks and average processing time for tasks at each priority level
void monitor_queue(PriorityQueue* pq) {
    // Calculate the number of pending tasks
    int num_pending = 0;
