#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <semaphore.h>
#include <unistd.h>
#include <sys/time.h>
#include <sys/resource.h>
#include <sys/mman.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <errno.h>

// Priority queue data structure
struct task {
    int id;
    struct resource *resource;
    int priority;
};

// Resource contention manager
struct resource_contention_manager {
    pthread_mutex_t mutex;
    semaphore_t semaphore;
    int max_concurrent_tasks;
    int num_concurrent_tasks;
};

// Priority queue structure
struct priority_queue {
    struct task *tasks;
    int size;
    int capacity;
    int head;
    int tail;
    int num_pending_tasks;
    int average_processing_time[10];
    int num_processed_tasks[10];
};

// Logging system
struct logging_system {
    pthread_mutex_t mutex;
    semaphore_t semaphore;
    FILE *file;
};

// Resource structure
struct resource {
    int id;
    int available;
};

// Function to initialize the priority queue
void init_priority_queue(struct priority_queue *queue) {
    // Initialize the tasks array
    queue->tasks = (struct task *)malloc(sizeof(struct task) * 10000);
    memset(queue->tasks, 0, sizeof(struct task) * 10000);

    // Initialize the head and tail pointers
    queue->head = 0;
    queue->tail = 0;

    // Initialize the size and capacity of the queue
    queue->size = 0;
    queue->capacity = 10000;

    // Initialize the number of pending tasks
    queue->num_pending_tasks = 0;

    // Initialize the average processing time for each priority level
    memset(queue->average_processing_time, 0, sizeof(int) * 10);

    // Initialize the number of processed tasks for each priority level
    memset(queue->num_processed_tasks, 0, sizeof(int) * 10);
}

// Function to enqueue a task in the priority queue
void enqueue_task(struct priority_queue *queue, struct task *task) {
    // Acquire the lock on the mutex
    pthread_mutex_lock(&queue->mutex);

    // Check if the queue is full
    if (queue->size == queue->capacity) {
        // If the queue is full, double its capacity
        queue->capacity *= 2;
        queue->tasks = (struct task *)realloc(queue->tasks, sizeof(struct task) * queue->capacity);
    }

    // Add the task to the end of the queue
    queue->tasks[queue->tail] = *task;
    queue->tail++;
    if (queue->tail == queue->capacity) {
        queue->tail = 0;
    }

    // Increment the number of pending tasks
    queue->num_pending_tasks++;

    // Release the lock on the mutex
    pthread_mutex_unlock(&queue->mutex);
}

// Function to dequeue a task from the priority queue
struct task *dequeue_task(struct priority_queue *queue) {
    struct task *task = NULL;

    // Acquire the lock on the mutex
    pthread_mutex_lock(&queue->mutex);

    // Check if there are any pending tasks in the queue
    if (queue->num_pending_tasks > 0) {
        // Get the task with the highest priority
        int max_priority = -1;
        for (int i = 0; i < queue->size; i++) {
            if (queue->tasks[i].priority > max_priority) {
                max_priority = queue->tasks[i].priority;
                task = &queue->tasks[i];
            }
        }

        // Remove the task from the queue
        for (int i = 0; i < queue->size - 1; i++) {
            if (&queue->tasks[i] == task) {
                memcpy(&queue->tasks[i], &queue->tasks[i + 1], sizeof(struct task));
                break;
            }
        }
        queue->tail--;
        if (queue->tail < 0) {
            queue->tail = queue->capacity - 1;
        }

        // Decrement the number of pending tasks
        queue->num_pending_tasks--;
    }

    // Release the lock on the mutex
    pthread_mutex_unlock(&queue->mutex);

    return task;
}

// Function to adjust the priority of a task in the priority queue
void adjust_task_priority(struct priority_queue *queue, struct task *task) {
    // Acquire the lock on the mutex
    pthread_mutex_lock(&queue->mutex);

    // Check if the task is already in the queue
    int index = -1;
    for (int i = 0; i < queue->size; i++) {
        if (&queue->tasks[i] == task) {
            index = i;
            break;
        }
    }

    // If the task is in the queue, adjust its priority
    if (index != -1) {
        int old_priority = queue->tasks[index].priority;
        int new_priority = task->priority;
        if (new_priority > old_priority) {
            // Move the task to a higher priority level
            for (int i = index + 1; i < queue->size; i++) {
                if (queue->tasks[i].priority == new_priority) {
                    memcpy(&queue->tasks[i - 1], &queue->tasks[i], sizeof(struct task));
                    break;
                }
            }
        } else if (new_priority < old_priority) {
            // Move the task to a lower priority level
            for (int i = index - 1; i >= 0; i--) {
                if (queue->tasks[i].priority == new_priority) {
                    memcpy(&queue->tasks[i + 1], &queue->tasks[i], sizeof(struct task));
                    break;
                }
            }
        }
        queue->tasks[index].priority = new_priority;
    }

    // Release the lock on the mutex
    pthread_mutex_unlock(&queue->mutex);
}

// Function to export the current state of the priority queue to a file
void export_priority_queue(struct priority_queue *queue, char *filename) {
    // Acquire the lock on the mutex
    pthread_mutex_lock(&queue->mutex);

    // Open the file for writing
    FILE *file = fopen(filename, "w");
    if (file == NULL) {
        perror("fopen");
        exit(1);
    }

    // Write the number of pending tasks to the file
    fprintf(file, "%d\n", queue->num_pending_tasks);

    // Write each task in the queue to the file
    for (int i = 0; i < queue->size; i++) {
        struct task *task = &queue->tasks[i];
        fprintf(file, "%d %d %d\n", task->id, task->resource->id, task->priority);
    }

    // Close the file
    fclose(file);

    // Release the lock on the mutex
    pthread_mutex_unlock(&queue->mutex);
}

// Function to import the current state of the priority queue from a file
void import_priority_queue(struct priority_queue *queue, char *filename) {
    // Acquire the lock on the mutex
    pthread_mutex_lock(&queue->mutex);

    // Open the file for reading
    FILE *file = fopen(filename, "r");
    if (file == NULL) {
        perror("fopen");
        exit(1);
    }

    // Read the number of pending tasks from the file
    int num_pending_tasks;
    fscanf(file, "%d", &num_pending_tasks);

