    // Close the file
    fclose(file);

    // Release the lock on the mutex
    pthread_mutex_unlock(&queue->mutex);
}

// Function to handle resource contention
void handle_resource_contention(struct priority_queue *queue, struct resource *resource) {
    // Acquire the lock on the mutex
    pthread_mutex_lock(&queue->mutex);

    // Check if there are any tasks waiting for the resource
    int num_waiting_tasks = 0;
    for (int i = 0; i < queue->size; i++) {
        if (queue->tasks[i].resource == resource) {
            num_waiting_tasks++;
        }
    }

    // If there are any tasks waiting for the resource, grant access to the highest priority task
    if (num_waiting_tasks > 0) {
        int max_priority = -1;
        struct task *task = NULL;
        for (int i = 0; i < queue->size; i++) {
            if (queue->tasks[i].resource == resource && queue->tasks[i].priority > max_priority) {
                max_priority = queue->tasks[i].priority;
                task = &queue->tasks[i];
            }
        }
        if (task != NULL) {
            // Grant access to the highest priority task
            pthread_mutex_unlock(&resource->mutex);
            dequeue_task(queue);
            pthread_mutex_lock(&resource->mutex);
        }
    }

    // Release the lock on the mutex
    pthread_mutex_unlock(&queue->mutex);
}

// Function to handle resource exhaustion scenarios
void handle_resource_exhaustion(struct priority_queue *queue, struct resource *resource) {
    // Acquire the lock on the mutex
    pthread_mutex_lock(&queue->mutex);

    // Check if there are any tasks waiting for the resource
    int num_waiting_tasks = 0;
    for (int i = 0; i < queue->size; i++) {
        if (queue->tasks[i].resource == resource) {
            num_waiting_tasks++;
        }
    }

    // If there are any tasks waiting for the resource, notify them that the resource is unavailable
    if (num_waiting_tasks > 0) {
        int max_priority = -1;
        struct task *task = NULL;
        for (int i = 0; i < queue->size; i++) {
            if (queue->tasks[i].resource == resource && queue->tasks[i].priority > max_priority) {
                max_priority = queue->tasks[i].priority;
                task = &queue->tasks[i];
            }
        }
        if (task != NULL) {
            // Notify the highest priority task that the resource is unavailable
            pthread_mutex_unlock(&resource->mutex);
            dequeue_task(queue);
            pthread_mutex_lock(&resource->mutex);
        }
    }

    // Release the lock on the mutex
    pthread_mutex_unlock(&queue->mutex);
}

// Function to handle transient failures in the resource structure
void handle_transient_failure(struct priority_queue *queue, struct resource *resource) {
    // Acquire the lock on the mutex
    pthread_mutex_lock(&queue->mutex);

    // Check if there are any tasks waiting for the resource
    int num_waiting_tasks = 0;
