// Function to track and report resource utilization trends over time
void track_resource_utilization(struct priority_queue *queue, struct resource *resource) {
    // Acquire the lock on the mutex
    pthread_mutex_lock(&queue->mutex);

    // Check if there are any tasks waiting for the resource
    int num_waiting_tasks = 0;
    for (int i = 0; i < queue->size; i++) {
        if (queue->tasks[i].resource == resource) {
