// Define structure for user profile
typedef struct {
    int USER_ID;
    AUTH_TOKEN *auth_token;
    time_t CURRENT_TIMESTAMP;
} USER_PROFILE;

// Define registry of user profiles
USER_PROFILE *user_profiles = NULL;
size_t num_users = 0;
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

// Function to initialize and manage user sessions
void init_and_manage_sessions(USER_PROFILE *user) {
    // Acquire lock on registry of user profiles
    pthread_mutex_lock(&mutex);

    // Check if user is already registered in the registry
    for (size_t i = 0; i < num_users; i++) {
        if (user->USER_ID == user_profiles[i].USER_ID) {
            // Update existing user profile with new auth token and timestamp
            user_profiles[i].auth_token = user->auth_token;
            user_profiles[i].CURRENT_TIMESTAMP = time(NULL);
            break;
        }
    }

    // If user is not registered, add new profile to registry
    if (user->USER_ID != user_profiles[i].USER_ID) {
        USER_PROFILE *new_profile = malloc(sizeof(USER_PROFILE));
        new_profile->USER_ID = user->USER_ID;
        new_profile->auth_token = user->auth_token;
        new_profile->CURRENT_TIMESTAMP = time(NULL);
        user_profiles = realloc(user_profiles, (num_users + 1) * sizeof(USER_PROFILE));
        user_profiles[num_users++] = new_profile;
    }

    // Release lock on registry of user profiles
    pthread_mutex_unlock(&mutex);
}

// Function to automatically log out users whose sessions have expired
void auto_logout() {
    time_t current_time = time(NULL);
    for (size_t i = 0; i < num_users; i++) {
        if (current_time - user_profiles[i].CURRENT_TIMESTAMP > SESSION_EXPIRATION) {
            // Log out user and remove profile from registry
            free(user_profiles[i]);
            memmove(&user_profiles[i], &user_profiles[i + 1], (num_users - i - 1) * sizeof(USER_PROFILE));
            num_users--;
        }
    }
}
