#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <limits.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <unistd.h>
#include <pthread.h>
#include <semaphore.h>
#include <stdbool.h>
#include <json-c/json.h>

#define MAX_FILE_SIZE 1073741824 // 1 GB in bytes
#define CHUNK_SIZE 5242880 // 5 MB in bytes
#define MAX_TRANSFORMATIONS 100
#define MAX_OUTPUT_FORMATS 3

typedef struct {
    char *input_file;
    char *output_file;
    char *transformation_rules;
    int max_transformations;
    bool sequential;
    bool parallel;
    bool compress;
    char output_format[MAX_OUTPUT_FORMATS];
} command_line_args;

void process_file(command_line_args *args) {
    // Open input file and check for errors
    int fd = open(args->input_file, O_RDONLY);
    if (fd == -1) {
        perror("Error opening input file");
        return;
    }

    // Get file size and allocate memory for buffer
    struct stat st;
    fstat(fd, &st);
    off_t file_size = st.st_size;
    char *buffer = malloc(file_size);
    if (buffer == NULL) {
        perror("Error allocating memory for input file");
        return;
    }

    // Read entire file into buffer
    ssize_t bytes_read = read(fd, buffer, file_size);
    if (bytes_read < 0) {
        perror("Error reading input file");
        return;
    }

    // Close input file and check for errors
    close(fd);

    // Initialize output file and check for errors
    fd = open(args->output_file, O_WRONLY | O_CREAT, 0644);
    if (fd == -1) {
        perror("Error opening output file");
        return;
    }

    // Initialize transformation rules and check for errors
    json_object *rules = json_tokener_parse(args->transformation_rules);
    if (rules == NULL) {
        fprintf(stderr, "Invalid transformation rules\n");
        return;
    }

    // Initialize output format and check for errors
    int output_format = -1;
    for (int i = 0; i < MAX_OUTPUT_FORMATS; i++) {
        if (strcmp(args->output_format[i], "json") == 0) {
            output_format = JSON;
            break;
        } else if (strcmp(args->output_format[i], "xml") == 0) {
            output_format = XML;
            break;
        } else if (strcmp(args->output_format[i], "csv") == 0) {
            output_format = CSV;
            break;
        }
    }
    if (output_format == -1) {
        fprintf(stderr, "Invalid output format\n");
        return;
    }

    // Initialize variables for parallel processing
    int num_threads = 0;
    pthread_t *threads = NULL;
    semaphore *sem = NULL;
    if (args->parallel) {
        num_threads = sysconf(_SC_NPROCESSORS_ONLN);
        threads = malloc(num_threads * sizeof(pthread_t));
        sem = sem_open("sem", O_CREAT, 0644, 1);
    }

    // Initialize variables for sequential processing
    int current_byte = 0;
    int num_transformations = 0;
    bool compression = false;
    if (args->sequential) {
        compression = args->compress;
    }

    // Process file in chunks and write results to output file
    while (current_byte < file_size) {
        int chunk_size = CHUNK_SIZE;
        if (chunk_size > file_size - current_byte) {
            chunk_size = file_size - current_byte;
        }

        // Process chunk in parallel or sequentially
        if (args->parallel) {
            pthread_create(&threads[num_threads], NULL, process_chunk, &buffer[current_byte]);
            sem_wait(sem);
            num_transformations += *((int *) threads[num_threads].retval);
            free(threads[num_threads].retval);
        } else {
            int transformations = process_chunk(&buffer[current_byte], chunk_size, args->transformation_rules, output_format, compression);
            num_transformations += transformations;
        }

        // Update current byte and check for errors
        current_byte += chunk_size;
        if (current_byte > file_size) {
            fprintf(stderr, "Error processing file\n");
            return;
        }
    }

    // Close output file and check for errors
    close(fd);

    // Print largest integer found in file
    if (args->sequential) {
        printf("Largest integer found in file: %d\n", num_transformations);
    } else {
        printf("Largest integer found in file: %d\n", *((int *) threads[0].retval));
    }
}

void *process_chunk(void *args) {
    char *buffer = (char *) args;
    int chunk_size = strlen(buffer);
    int num_transformations = 0;

    // Process chunk and apply transformations
    for (int i = 0; i < chunk_size; i++) {
        if (buffer[i] == '1') {
            buffer[i] = '2';
            num_transformations++;
        } else if (buffer[i] == '2') {
            buffer[i] = '3';
            num_transformations++;
        } else if (buffer[i] == '3') {
            buffer[i] = '1';
            num_transformations++;
        }
    }

    // Return number of transformations applied to chunk
    return &num_transformations;
}

