    if (argc < 8) {
        fprintf(stderr, "Usage: %s input_file output_file transformation_rules max_transformations sequential parallel compress output_format\n", argv[0]);
        return 1;
    }
    args.input_file = argv[1];
    args.output_file = argv[2];
    args.transformation_rules = argv[3];
    args.max_transformations = atoi(argv[4]);
    args.sequential = strcmp(argv[5], "true") == 0;
    args.parallel = strcmp(argv[6], "true") == 0;
    args.compress = strcmp(argv[7], "true") == 0;
    for (int i = 8; i < argc; i++) {
