#include <arpa/inet.h>
#include <netdb.h>
#include <sys/socket.h>
#include <sys/types.h>
#include <sys/select.h>
#include <sys/time.h>
#include <errno.h>
#include <pthread.h>
#include <resolv.h>
#include <netinet/in.h>
#include <arpa/nameser.h>
#include <resolv.h>
#include <syslog.h>

#define MAX_CONCURRENT_REQUESTS 1000
#define DNS_TIMEOUT 5 // seconds

typedef struct {
    char *hostname;
    u_char ip[INET6_ADDRSTRLEN];
} dns_request_t;

void *dns_resolver(void *arg) {
    dns_request_t *req = (dns_request_t *) arg;
    struct addrinfo hints, *res;
    int err;

    memset(&hints, 0, sizeof(struct addrinfo));
    hints.ai_family = AF_UNSPEC;
    hints.ai_socktype = SOCK_DGRAM;

    if ((err = getaddrinfo(req->hostname, NULL, &hints, &res)) != 0) {
        syslog(LOG_ERR, "getaddrinfo: %s", gai_strerror(err));
        return NULL;
    }

    struct sockaddr_in *sa = (struct sockaddr_in *) res->ai_addr;
    memcpy(req->ip, &sa->sin_addr.s_addr, INET_ADDRSTRLEN);

    freeaddrinfo(res);

    return NULL;
}

int dns_resolve(char *hostname, u_char ip[INET6_ADDRSTRLEN]) {
    int err;
    pthread_t thread;
    dns_request_t req = {.hostname = hostname};

    if ((err = pthread_create(&thread, NULL, dns_resolver, &req)) != 0) {
        syslog(LOG_ERR, "pthread_create: %s", strerror(err));
        return -1;
    }

    struct timeval tv;
    fd_set readfds;
    FD_ZERO(&readfds);
    FD_SET(thread, &readfds);

    tv.tv_sec = DNS_TIMEOUT;
    tv.tv_usec = 0;

    if ((err = select(thread + 1, &readfds, NULL, NULL, &tv)) <= 0) {
        syslog(LOG_ERR, "select: %s", strerror(err));
        return -1;
    }

    if (!FD_ISSET(thread, &readfds)) {
        syslog(LOG_ERR, "select: no data available");
        return -1;
    }

    pthread_join(thread, NULL);

    memcpy(ip, req.ip, INET6_ADDRSTRLEN);

    return 0;
}
```
