    SESSION_TOKEN *token;
    time_t CURRENT_TIMESTAMP;
} DEVICE_INFORMATION;

// Function to initialize and manage the registry of devices
void init_device_registry() {
    // Create a mutex for thread-safe operations
    pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

    // Initialize an array to hold all device information
    DEVICE_INFORMATION *devices = (DEVICE_INFORMATION *)malloc(sizeof(DEVICE_INFORMATION) * 10);

    // Loop through each device and check if the session has expired
    for (int i = 0; i < 10; i++) {
        pthread_mutex_lock(&mutex);
        if (devices[i].CURRENT_TIMESTAMP + SESSION_EXPIRATION_TIME < time(NULL)) {
            // Disable the device and remove it from the registry
            devices[i].token->enabled = false;
            devices[i] = NULL;
        }
        pthread_mutex_unlock(&mutex);
    }

    // Free the memory allocated for the array
    free(devices);
}

// Function to register a new device and add it to the registry
void register_device(int DEVICE_ID, SESSION_TOKEN *token) {
    // Create a mutex for thread-safe operations
    pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

    // Initialize an array to hold all device information
    DEVICE_INFORMATION *devices = (DEVICE_INFORMATION *)malloc(sizeof(DEVICE_INFORMATION) * 10);

    // Loop through each device and check if the session has expired
    for (int i = 0; i < 10; i++) {
        pthread_mutex_lock(&mutex);
        if (devices[i].token == NULL) {
            // Add the new device to the registry
            devices[i].DEVICE_ID = DEVICE_ID;
            devices[i].token = token;
            devices[i].CURRENT_TIMESTAMP = time(NULL);
            break;
        }
        pthread_mutex_unlock(&mutex);
    }

    // Free the memory allocated for the array
    free(devices);
}
