int main(int argc, char** argv) {
    // Parse command line arguments and initialize program variables
    parse_args(argc, argv);

    // Create a semaphore to synchronize access to the log buffer
    semaphore = sem_open("log_buffer", O_CREAT | O_EXCL, 0644, 1);
    if (semaphore == SEM_FAILED) {
        perror("Failed to create semaphore");
        exit(1);
    }

    // Process each file or directory specified on the command line
    for (int i = 0; i < num_files; i++) {
        char* path = files[i];
        struct stat sb;
        if (stat(path, &sb) == 0 && S_ISDIR(sb.st_mode)) {
            process_directory(path);
        } else {
            process_file(path);
        }
    }

    // Generate a summary report of the processing activities
    generate_summary_report();

    // Clean up and exit the program
    sem_close(semaphore);
    return 0;
}

void parse_args(int argc, char** argv) {
    int c;
    while ((c = getopt(argc, argv, "t:")) != -1) {
        switch (c) {
            case 't':
                num_threads = atoi(optarg);
                if (num_threads < 0 || num_threads > max_num_threads) {
                    fprintf(stderr, "Invalid number of threads: %d\n", num_threads);
                    exit(1);
                }
                break;
            default:
                fprintf(stderr, "Usage: %s [-t num_threads] file1 [file2 ...]\n", argv[0]);
                exit(1);
        }
    }
    if (optind >= argc) {
        fprintf(stderr, "No input files specified\n");
        exit(1);
    }
    num_files = argc - optind;
    files = malloc(num_files * sizeof(char*));
    for (int i = 0; i < num_files; i++) {
        files[i] = strdup(argv[optind + i]);
    }
}

void process_file(char* path) {
    // Open the file and read its contents
    FILE* fp = fopen(path, "r");
    if (fp == NULL) {
        log_error("Failed to open file: %s", path);
        return;
    }
    char line[MAX_LINE_LENGTH];
    while (fgets(line, MAX_LINE_LENGTH, fp)) {
        // Filter lines using a user-provided regular expression
        regex_t* regex = NULL;
        if (regex != NULL) {
            filter_lines(line, regex);
        }
        // Log the line and increment the counters
        log_entry_t entry = {.filename = path, .line_num = 0, .line = strdup(line)};
        sem_wait(semaphore);
        if (log_buffer_index < log_buffer_size) {
            log_buffer[log_buffer_index++] = entry;
        } else {
            // Log buffer is full, flush it and create a new one
            generate_summary_report();
            free(log_buffer);
            log_buffer = malloc(LOG_BUFFER_SIZE * sizeof(log_entry_t));
            log_buffer[0] = entry;
            log_buffer_index = 1;
        }
        sem_post(semaphore);
    }
    fclose(fp);
}

void process_directory(char* path) {
    // Open the directory and read its contents
    DIR* dir = opendir(path);
    if (dir == NULL) {
        log_error("Failed to open directory: %s", path);
        return;
    }
    struct dirent* entry;
    while ((entry = readdir(dir)) != NULL) {
        // Skip hidden files and directories
        if (strncmp(entry->d_name, ".", 1) == 0 || strncmp(entry->d_name, "..", 2) == 0) {
            continue;
        }
        char* filename = malloc(MAX_FILENAME_LENGTH);
        snprintf(filename, MAX_FILENAME_LENGTH, "%s/%s", path, entry->d_name);
        struct stat sb;
        if (stat(filename, &sb) == 0 && S_ISREG(sb.st_mode)) {
            // Process the file in a separate thread
            pthread_t thread;
            int rc = pthread_create(&thread, NULL, process_file, filename);
            if (rc != 0) {
                log_error("Failed to create thread for file: %s", filename);
                free(filename);
                continue;
            }
        } else {
            // Process the directory recursively
            process_directory(filename);
        }
    }
    closedir(dir);
}

void filter_lines(char* line, regex_t* regex) {
