// Define the function to dynamically allocate memory for an array of LTE_DL_CCCH_MESSAGE_TYPE3 structures
LTE_DL_CCCH_MESSAGE_TYPE3* allocate_memory(int num_transactions, int batch_size) {
    // Validate that the parameters are non-negative integers greater than zero
    if (num_transactions < 0 || batch_size < 0) {
        printf("Error: Invalid input parameters\n");
        return NULL;
    }

    // Dynamically allocate memory for an array of LTE_DL_CCCH_MESSAGE_TYPE3 structures
    LTE_DL_CCCH_MESSAGE_TYPE3 *array = (LTE_DL_CCCH_MESSAGE_TYPE3*)malloc(num_transactions * batch_size * sizeof(LTE_DL_CCCH_MESSAGE_TYPE3));
    if (!array) {
        printf("Error: Failed to allocate memory\n");
        return NULL;
    }

    // Initialize the array with random values between specified limits
    for (int i = 0; i < num_transactions * batch_size; i++) {
        array[i].RRC_RECONFIGURATION = rand() % 1000;
        array[i].UE_ID = rand() % 1000000;
        array[i].NAS_PDU = (char*)malloc(sizeof(char) * 100);
        for (int j = 0; j < 100; j++) {
            array[i].NAS_PDU[j] = rand() % 26 + 'A';
        }
    }

    return array;
}

// Define the function to safely load a pre-trained machine learning model from a binary file format
void* load_model(const char *filename) {
    // Open the file in read mode
    FILE *file = fopen(filename, "rb");
    if (!file) {
        printf("Error: Failed to open file\n");
        return NULL;
    }

    // Get the size of the file
    fseek(file, 0, SEEK_END);
    long int size = ftell(file);
    rewind(file);

    // Allocate memory for the model
    void *model = malloc(size);
    if (!model) {
        printf("Error: Failed to allocate memory\n");
        fclose(file);
        return NULL;
    }

    // Read the file into the allocated memory
    size_t read = fread(model, 1, size, file);
    if (read != size) {
        printf("Error: Failed to read file\n");
        free(model);
        fclose(file);
        return NULL;
    }

    // Close the file
    fclose(file);

    return model;
}

