    long* large_offset_array = new long[size];
    int* key_array = new int[size];
    record* record_array = new record[size];
    double* floating_point_array = new double[size];
    struct node* head = NULL;

    // Initialize the arrays and linked list
    for (int i = 0; i < size; i++) {
        large_offset_array[i] = i * 1000;
        key_array[i] = i + 1;
        record_array[i].value = i + 2;
        record_array[i].floating_point_value = (double)i / 10.0;
        struct node* new_node = new struct node;
        new_node->value = i + 3;
        new_node->next = head;
        head = new_node;
    }

    // Return the head pointer of the linked list
    return head;
}

