        return 1;
    }

    // Check if the format is valid
    if (format != "jpg" && format != "png") {
        cout << "Error: Invalid output format" << endl;
        return 1;
    }

    // Initialize a thread-safe random number generator seeded with the current time
    std::random_device rd;
    std::mt19937 gen(rd());
    std::uniform_int_distribution<> dis(0, 100);

    // Initialize a caching mechanism for the record values
    map<int, int> cache;
    mutex mtx;
    condition_variable cv;

    // Initialize a logging mechanism to track the function's execution details and errors
    ofstream log_file("function.log", ios::out);
    if (!log_file) {
        cout << "Error: Failed to open log file" << endl;
        return 1;
    }

    // Initialize a variable to store the head pointer of the linked list
    struct node* head = NULL;

    // Read the input image file and populate the arrays and linked list
    ifstream infile(input_file, ios::binary);
    if (!infile) {
        cout << "Error: Failed to open input file" << endl;
        return 1;
    }
    int size = (int)infile.tellg();
    infile.seekg(0, ios::beg);
    char* buffer = new char[size];
    infile.read(buffer, size);
    for (int i = 0; i < size; i++) {
        // Generate a random integer value within the specified range for initializing 'record' structures
        int key = dis(gen);
        if (cache.find(key) == cache.end()) {
            mtx.lock();
            cache[key] = 1;
            mtx.unlock();
            struct node* new_node = new struct node;
            new_node->value = key;
            new_node->next = head;
            head = new_node;
        }
        // Populate the 'int' fields in each 'record' structure and 'double' precision floating-point numbers within the specified ranges using this generator
        for (int j = 0; j < size; j++) {
            record_array[j].value = key;
            record_array[j].floating_point_value = (double)dis(gen) / 10.0;
        }
    }

    // Convert the input image file to the specified format using a third-party tool
    string command = "convert -quality 90 " + input_file + " " + output_directory + "/" + format;
    system(command.c_str());

    // Create the output file within the specified directory and return 0 if successful, else 1
    ofstream outfile(output_directory + "/" + format, ios::binary);
    if (!outfile) {
        cout << "Error: Failed to create output file" << endl;
        return 1;
    }
    outfile.write(buffer, size);
