// Define the maximum number of input files and options
#define MAX_INPUT_FILES 100
#define MAX_OPTIONS 5

// Define the usage information for the program
static const char *usage = "Usage: text-analyzer [options] <input file(s)>\n" \
                           "\t--help\t\tDisplay this message\n" \
                           "\t-s\t\tSummarize the text content by providing word frequency statistics\n" \
                           "\t-l\t\tList unique words from the input files\n" \
                           "\t-w\t\tWord count each input file individually and print the total word count\n" \
                           "\t-o <filename>\tRedirect the output to the specified filename\n";

// Define the structure for storing the command line options
struct option {
    char *name;
    bool is_set;
};

// Define the function prototypes
void parse_options(int argc, char **argv);
void process_input_files(char **input_files, int num_input_files);
void summarize_text(char **input_files, int num_input_files);
void list_unique_words(char **input_files, int num_input_files);
void word_count(char **input_files, int num_input_files);
void redirect_output(char *filename);

// Define the main function
int main(int argc, char **argv) {
    // Parse the command line options and process the input files
    parse_options(argc, argv);
    process_input_files(argv + 1, argc - 1);

    return 0;
}

// Define the function to parse the command line options
void parse_options(int argc, char **argv) {
    // Initialize the structure for storing the command line options
    struct option options[MAX_OPTIONS];
    memset(options, 0, sizeof(struct option) * MAX_OPTIONS);

    // Iterate over the command line arguments and parse the options
    for (int i = 1; i < argc; ++i) {
        if (strcmp(argv[i], "--help") == 0) {
            printf("%s", usage);
            exit(EXIT_SUCCESS);
        } else if (strcmp(argv[i], "-s") == 0) {
            options[0].is_set = true;
        } else if (strcmp(argv[i], "-l") == 0) {
            options[1].is_set = true;
        } else if (strcmp(argv[i], "-w") == 0) {
            options[2].is_set = true;
        } else if (strcmp(argv[i], "-o") == 0 && i + 1 < argc) {
            options[3].name = argv[++i];
            options[3].is_set = true;
        } else {
            printf("Invalid option: %s\n", argv[i]);
            exit(EXIT_FAILURE);
        }
    }

    // Check if any required options are not set
    for (int i = 0; i < MAX_OPTIONS; ++i) {
        if (!options[i].is_set && strcmp(options[i].name, "--help") != 0) {
            printf("Option %s is required\n", options[i].name);
            exit(EXIT_FAILURE);
        }
    }
}

// Define the function to process the input files
void process_input_files(char **input_files, int num_input_files) {
    // Check if any input files are specified
    if (num_input_files == 0) {
        printf("No input files specified\n");
        exit(EXIT_FAILURE);
    }

    // Process the input files based on the options specified
    for (int i = 0; i < num_input_files; ++i) {
        if (options[0].is_set) {
            summarize_text(input_files, num_input_files);
        } else if (options[1].is_set) {
            list_unique_words(input_files, num_input_files);
        } else if (options[2].is_set) {
            word_count(input_files, num_input_files);
        } else if (options[3].is_set) {
            redirect_output(options[3].name);
        }
    }
}

// Define the function to summarize the text content by providing word frequency statistics
void summarize_text(char **input_files, int num_input_files) {
    // Open the input files and read their contents
    for (int i = 0; i < num_input_files; ++i) {
        FILE *file = fopen(input_files[i], "r");
        if (!file) {
            printf("Error opening file %s: %s\n", input_files[i], strerror(errno));
            exit(EXIT_FAILURE);
        }

        // Read the contents of the file into a buffer
        char *buffer = malloc(sizeof(char) * PATH_MAX);
        size_t bytes_read = fread(buffer, sizeof(char), PATH_MAX, file);
        if (bytes_read == 0) {
            printf("Error reading from file %s: %s\n", input_files[i], strerror(errno));
            exit(EXIT_FAILURE);
        }

        // Close the file and process the contents of the buffer
        fclose(file);
        char *line = strtok(buffer, "\n");
        while (line) {
            // Tokenize the line into words
            char *word = strtok(line, " ");
            while (word) {
                // Increment the frequency of each word in the dictionary
                int freq = 0;
                if (dict_get(word, &freq)) {
                    dict_set(word, ++freq);
                } else {
                    dict_add(word, 1);
                }
                word = strtok(NULL, " ");
            }
            line = strtok(NULL, "\n");
        }

        // Free the buffer and close the file
        free(buffer);
    }

    // Print the word frequency statistics
    dict_print();
}

// Define the function to list unique words from the input files
void list_unique_words(char **input_files, int num_input_files) {
    // Open the input files and read their contents
    for (int i = 0; i < num_input_files; ++i) {
        FILE *file = fopen(input_files[i], "r");
        if (!file) {
            printf("Error opening file %s: %s\n", input_files[i], strerror(errno));
            exit(EXIT_FAILURE);
        }

        // Read the contents of the file into a buffer
        char *buffer = malloc(sizeof(char) * PATH_MAX);
        size_t bytes_read = fread(buffer, sizeof(char), PATH_MAX, file);
        if (bytes_read == 0) {
            printf("Error reading from file %s: %s\n", input_files[i], strerror(errno));
            exit(EXIT_FAILURE);
        }

        // Close the file and process the contents of the buffer
        fclose(file);
        char *line = strtok(buffer, "\n");
        while (line) {
            // Tokenize the line into words
            char *word = strtok(line, " ");
            while (word) {
                // Add each word to a set of unique words
                if (!set_contains(word)) {
                    set_add(word);
                }
                word = strtok(NULL, " ");
            }
            line = strtok(NULL, "\n");
        }

        // Free the buffer and close the file
        free(buffer);
    }

    // Print the unique words from the input files
    set_print();
}

// Define the function to word count each input file individually and print the total word count
void word_count(char **input_files, int num_input_files) {
    // Open the input files and read their contents
    for (int i = 0; i < num_input_files; ++i) {
        FILE *file = fopen(input_files[i], "r");
        if (!file) {
            printf("Error opening file %s: %s\n", input_files[i], strerror(errno));
            exit(EXIT_FAILURE);
        }

        // Read the contents of the file into a buffer
        char *buffer = malloc(sizeof(char) * PATH_MAX);
        size_t bytes_read = fread(buffer, sizeof(char), PATH_MAX, file);
        if (bytes_read == 0) {
            printf("Error reading from file %s: %s\n", input_files[i], strerror(errno));
            exit(EXIT_FAILURE);
        }

        // Close the file and process the contents of the buffer
        fclose(file);
        char *line = strtok(buffer, "\n");
        while (line) {
            // Tokenize the line into words
            char *word = strtok(line, " ");
            while (word) {
                // Increment the word count for each word in the dictionary
                int freq = 0;
                if (dict_get(word, &freq)) {
                    dict_set(word, ++freq);
                } else {
                    dict_add(word, 1);
                }
                word = strtok(NULL, " ");
            }
            line = strtok(NULL, "\n");
        }

        // Free the buffer and close the file
        free(buffer);
    }

    // Print the total word count for each input file
    dict_print();
}

// Define the function to redirect the output to a specified filename
void redirect_output(char *filename) {
    // Open the output file and check if it exists
    FILE *file = fopen(filename, "w");
    if (!file) {
        printf("Error opening file %s: %s\n", filename, strerror(errno));
        exit(EXIT_FAILURE);
    }

    // Redirect the output to the specified file
    setvbuf(stdout, NULL, _IONBF, 0);
    freopen("r", stdout);
}
