#include <fcntl.h>
#include <errno.h>
#include <stdbool.h>
#include <limits.h>
#include <getopt.h>

#define BUFFER_SIZE 4096
#define MAX_LINE_LENGTH 1024

// Struct to store the options and their values
struct option {
    char *name;
    int has_arg;
    int *flag;
    int val;
};

// Function to parse command line arguments
void parse_args(int argc, char **argv) {
    // Initialize variables
    bool count_only_nonempty = false;
    bool suppress_output = false;
    char *output_file = NULL;
    int c;
    while ((c = getopt(argc, argv, "cs:o:")) != -1) {
        switch (c) {
            case 'c':
                count_only_nonempty = true;
                break;
            case 's':
                suppress_output = true;
                break;
            case 'o':
                output_file = optarg;
                break;
            default:
                printf("Usage: %s [-c] [-s] [-o output_file]\n", argv[0]);
                exit(1);
        }
    }
}

// Function to read from an input file line by line and print the number of lines
void count_lines(FILE *input, bool count_only_nonempty, bool suppress_output) {
    // Initialize variables
    int line_count = 0;
    char buffer[BUFFER_SIZE];
    while (fgets(buffer, BUFFER_SIZE, input)) {
        if (!suppress_output) {
            printf("%s", buffer);
        }
        if (count_only_nonempty && strlen(buffer) > 0) {
            line_count++;
        } else {
            line_count++;
        }
    }
    printf("Number of lines: %d\n", line_count);
}

// Function to handle file operations safely and maintain data integrity
void handle_file(FILE *input, FILE *output) {
    // Initialize variables
    int fd = fileno(input);
    struct stat st;
    if (fstat(fd, &st)) {
        perror("Error: failed to get file status");
        exit(1);
    }
    off_t size = st.st_size;
    char *buffer = malloc(BUFFER_SIZE);
    if (!buffer) {
        perror("Error: failed to allocate memory for buffer");
        exit(1);
    }
    while (size > 0) {
        ssize_t bytes_read = read(fd, buffer, BUFFER_SIZE);
        if (bytes_read == -1) {
            perror("Error: failed to read from file");
            exit(1);
        }
        count_lines(input, count_only_nonempty, suppress_output);
        size -= bytes_read;
    }
    free(buffer);
}

int main(int argc, char **argv) {
    // Parse command line arguments
    parse_args(argc, argv);

    // Open input file and handle errors
    FILE *input = fopen(argv[1], "r");
    if (!input) {
        perror("Error: failed to open input file");
        exit(1);
    }

    // Handle output redirection if specified
    FILE *output = NULL;
    if (output_file != NULL) {
        output = fopen(output_file, "w");
        if (!output) {
            perror("Error: failed to open output file");
            exit(1);
        }
    }

    // Handle file operations safely and maintain data integrity
    handle_file(input, output);

    // Close files and free memory
    fclose(input);
    if (output != NULL) {
        fclose(output);
    }
    return 0;
}
```
This code uses the `getopt` function to parse command line arguments. It also includes a `parse_args` function that handles the parsing of options and their values, as well as a `count_lines` function that reads from an input file line by line and prints the number of lines. The `handle_file` function is responsible for handling file operations safely and maintaining data integrity. It uses the `fileno` function to get the file descriptor of the input file, and then reads from the file in chunks using the `read` function. The `count_lines` function is called inside the `handle_file` function to count the number of lines in each chunk. Finally, the code includes error handling for failed file operations and memory allocation.']

