// Define the structure to hold device information
typedef struct {
    int device_id;
    SESSION_TOKEN *session_token;
    time_t current_timestamp;
} DEVICE_INFORMATION;

// Define the registry of devices
static DEVICE_INFORMATION *device_registry = NULL;

// Define the mutex for protecting the registry
static pthread_mutex_t device_registry_mutex = PTHREAD_MUTEX_INITIALIZER;

// Define the condition variable for signaling when a session is expired
static pthread_cond_t session_expired_cv = PTHREAD_COND_INITIALIZER;

// Function to initialize the registry of devices
void init_device_registry() {
    // Allocate memory for the registry
    device_registry = (DEVICE_INFORMATION *)malloc(sizeof(DEVICE_INFORMATION) * 10);
    if (!device_registry) {
        printf("Error: Failed to allocate memory for device registry\n");
        exit(1);
    }

    // Initialize the mutex and condition variable
    pthread_mutex_init(&device_registry_mutex, NULL);
    pthread_cond_init(&session_expired_cv, NULL);
}

// Function to register a new device
void register_device(int device_id, SESSION_TOKEN *session_token) {
    // Acquire the mutex
    pthread_mutex_lock(&device_registry_mutex);

    // Check if the registry is full
    if (device_registry == NULL || device_registry->num_devices >= 10) {
        printf("Error: Registry is full\n");
        pthread_mutex_unlock(&device_registry_mutex);
        return;
    }

    // Add the new device to the registry
    device_registry->num_devices++;
    device_registry[device_registry->num_devices - 1].device_id = device_id;
    device_registry[device_registry->num_devices - 1].session_token = session_token;
    device_registry[device_registry->num_devices - 1].current_timestamp = time(NULL);

    // Release the mutex
    pthread_mutex_unlock(&device_registry_mutex);
}

// Function to authenticate a device
void authenticate_device(int device_id, SESSION_TOKEN *session_token) {
    // Acquire the mutex
    pthread_mutex_lock(&device_registry_mutex);

    // Check if the device is registered
    int i;
    for (i = 0; i < device_registry->num_devices; i++) {
        if (device_registry[i].device_id == device_id) {
            break;
        }
    }
    if (i >= device_registry->num_devices) {
        printf("Error: Device is not registered\n");
        pthread_mutex_unlock(&device_registry_mutex);
        return;
    }

    // Check if the session token is valid
    if (session_token != device_registry[i].session_token) {
        printf("Error: Invalid session token\n");
        pthread_mutex_unlock(&device_registry_mutex);
        return;
    }

    // Update the current timestamp
    device_registry[i].current_timestamp = time(NULL);

    // Release the mutex
    pthread_mutex_unlock(&device_registry_mutex);
}

// Function to remove an expired session from the registry
void remove_expired_session() {
    // Acquire the mutex
    pthread_mutex_lock(&device_registry_mutex);

    // Check if there are any expired sessions
    int i;
    for (i = 0; i < device_registry->num_devices; i++) {
        if (device_registry[i].current_timestamp + SESSION_TIMEOUT <= time(NULL)) {
            break;
        }
    }
    if (i >= device_registry->num_devices) {
        // No expired sessions found, release the mutex and return
        pthread_mutex_unlock(&device_registry_mutex);
        return;
    }

    // Remove the expired session from the registry
    device_registry->num_devices--;
    for (int j = i; j < device_registry->num_devices; j++) {
        device_registry[j] = device_registry[j + 1];
    }

    // Release the mutex and signal the condition variable
    pthread_mutex_unlock(&device_registry_mutex);
    pthread_cond_signal(&session_expired_cv);
}

// Function to trigger a full registry scan and clean-up operation
void trigger_full_scan() {
    // Acquire the mutex
    pthread_mutex_lock(&device_registry_mutex);

    // Check if there are any expired sessions
    int i;
    for (i = 0; i < device_registry->num_devices; i++) {
        if (device_registry[i].current_timestamp + SESSION_TIMEOUT <= time(NULL)) {
            break;
        }
    }
    if (i >= device_registry->num_devices) {
        // No expired sessions found, release the mutex and return
        pthread_mutex_unlock(&device_registry_mutex);
        return;
    }

    // Remove all expired sessions from the registry
    device_registry->num_devices = i;

    // Release the mutex and signal the condition variable
    pthread_mutex_unlock(&device_registry_mutex);
    pthread_cond_signal(&session_expired_cv);
