import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.atomic.AtomicInteger;
import java.util.logging.Logger;

public class TransactionProcessor {
    private static final Logger LOGGER = Logger.getLogger(TransactionProcessor.class.getName());

    // Custom data structure to manage and query discrepancies
    private ConcurrentHashMap<String, Discrepancy> discrepancies = new ConcurrentHashMap<>();

    public void processTransactions(List<Transaction> transactions) {
        for (Transaction transaction : transactions) {
            String key = getKey(transaction);
            Discrepancy discrepancy = discrepancies.get(key);
            if (discrepancy == null) {
                discrepancy = new Discrepancy();
                discrepancies.put(key, discrepancy);
            }
            discrepancy.addTransaction(transaction);
        }
    }

    public void checkDiscrepancies() {
        for (String key : discrepancies.keySet()) {
            Discrepancy discrepancy = discrepancies.get(key);
            if (discrepancy.hasDiscrepancy()) {
                LOGGER.info("Discrepancy found: " + discrepancy.toString());
            }
        }
    }

    public void logDiscrepancies() {
        for (String key : discrepancies.keySet()) {
            Discrepancy discrepancy = discrepancies.get(key);
            LOGGER.info("Discrepancy found: " + discrepancy.toString());
        }
    }

    private String getKey(Transaction transaction) {
        return transaction.getUserId() + "-" + transaction.getDate();
    }

    public static class Discrepancy {
        private AtomicInteger totalTransactions = new AtomicInteger(0);
        private AtomicInteger discrepancyCount = new AtomicInteger(0);
        private long startTime;
        private long endTime;

        public void addTransaction(Transaction transaction) {
            totalTransactions.incrementAndGet();
            if (transaction.getAmount() != transaction.getExpectedAmount()) {
                discrepancyCount.incrementAndGet();
            }
        }

        public boolean hasDiscrepancy() {
            return discrepancyCount.get() > 0;
        }

        @Override
        public String toString() {
            return "Total transactions: " + totalTransactions.get() + ", Discrepancies: " + discrepancyCount.get();
        }
    }
}
```
