        keys->records[i].value = min_value + rand() % (max_value - min_value);
    }

    for (int i = 0; i < num_records; i++) {
        records->records[i].value = min_value + rand() % (max_value - min_value);
    }

    return records;
}

// Function to deallocate memory for three arrays of log records
