    if (!offsets && !keys && !records) {
        return;
    }

    // Deallocate the memory for each array
    free(offsets->records);
    free(keys->records);
    free(records->records);

    // Deallocate the arrays themselves
    free(offsets);
    free(keys);
    free(records);
}
