// Define the structure for MeasurementResults
typedef struct {
    int PRB_ID;
    float SINR;
    float RSRP;
} MeasurementResult;

// Define a linked list node to store MeasurementResults
typedef struct Node {
    MeasurementResult data;
    struct Node* next;
} Node;

// Define the function to dynamically generate a list of MeasurementResults structures
Node* generateMeasurementResults(int num_elements) {
    // Allocate memory for the linked list node
    Node* head = (Node*)malloc(sizeof(Node));
    if (!head) {
        printf("Memory allocation failed\n");
        return NULL;
    }

    // Initialize the linked list node
    head->next = NULL;

    // Allocate memory for each MeasurementResult structure
    int i;
    for (i = 0; i < num_elements; i++) {
        Node* new_node = (Node*)malloc(sizeof(Node));
        if (!new_node) {
            printf("Memory allocation failed\n");
            return NULL;
        }

        // Initialize the MeasurementResult structure
        new_node->data.PRB_ID = i + 1;
        new_node->data.SINR = (float)(i + 1) / 10.0f;
        new_node->data.RSRP = (float)(i + 1) / 20.0f;

        // Add the node to the linked list
        head->next = new_node;
        head = head->next;
    }

    return head;
}

// Define a function to free the memory allocated for the linked list
void freeMeasurementResults(Node* head) {
    // Check if the linked list is empty
    if (!head) {
        return;
    }

    // Free the memory for each node in the linked list
    Node* current = head;
    while (current != NULL) {
        Node* next = current->next;
        free(current);
        current = next;
    }
}

// Define a function to print the contents of the linked list
void printMeasurementResults(Node* head) {
    // Check if the linked list is empty
    if (!head) {
        return;
    }

    // Print the contents of each node in the linked list
    Node* current = head;
    while (current != NULL) {
        printf("PRB_ID: %d, SINR: %.2f, RSRP: %.2f\n", current->data.PRB_ID, current->data.SINR, current->data.RSRP);
        current = current->next;
    }
}

// Define a function to add a new MeasurementResult structure to the linked list
void addMeasurementResult(Node** head_ref, int PRB_ID, float SINR, float RSRP) {
    // Allocate memory for the new node
    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) {
        printf("Memory allocation failed\n");
        return;
    }

    // Initialize the new node
    new_node->data.PRB_ID = PRB_ID;
    new_node->data.SINR = SINR;
    new_node->data.RSRP = RSRP;

    // Add the new node to the linked list
    new_node->next = *head_ref;
    *head_ref = new_node;
}

// Define a function to remove a MeasurementResult structure from the linked list
void removeMeasurementResult(Node** head_ref, int PRB_ID) {
    // Check if the linked list is empty
    if (!*head_ref) {
        return;
    }

    // Find the node to be removed
    Node* current = *head_ref;
    while (current != NULL && current->data.PRB_ID != PRB_ID) {
        current = current->next;
    }

    // Remove the node from the linked list
    if (current == NULL) {
        return;
    }
    Node* temp = current->next;
    free(current);
    current = temp;
}
