// Define the method to initialize and manage the registry of devices
void DeviceRegistryManager(int device_id, SESSION_TOKEN *session_token) {
    // Acquire the mutex for protecting the registry
    pthread_mutex_lock(&device_registry_mutex);

    // Check if the registry is full
    if (device_registry == NULL || device_registry->count >= MAX_DEVICES) {
        // Wait on a full registry condition variable
        pthread_cond_wait(&device_registry_full, &device_registry_mutex);
    }

    // Allocate memory for the new device information structure
    DEVICE_INFORMATION *new_device = (DEVICE_INFORMATION *)malloc(sizeof(DEVICE_INFORMATION));
    if (new_device == NULL) {
        // Handle memory allocation failure gracefully
        pthread_mutex_unlock(&device_registry_mutex);
        return;
    }

    // Initialize the new device information structure
    new_device->device_id = device_id;
    new_device->session_token = session_token;
    new_device->current_timestamp = time(NULL);

    // Add the new device to the registry
    if (device_registry == NULL) {
        device_registry = new_device;
    } else {
        DEVICE_INFORMATION *last_device = device_registry;
        while (last_device->next != NULL) {
            last_device = last_device->next;
        }
        last_device->next = new_device;
    }

    // Increment the count of devices in the registry
    device_registry->count++;

    // Release the mutex for protecting the registry
    pthread_mutex_unlock(&device_registry_mutex);
}

