    while (device != NULL) {
        if (device->device_id == device_id && device->session_token == session_token) {
            // Update the current timestamp for the device
            device->current_timestamp = time(NULL);
            break;
        }
        device = device->next;
    }

    // If the device is not registered, register it
    if (device == NULL) {
        DeviceRegistryManager(device_id, session_token);
    }

    // Release the mutex for protecting the registry
    pthread_mutex_unlock(&device_registry_mutex);
}

