void DeviceRegistryCleaner() {
    // Acquire the mutex for protecting the registry
    pthread_mutex_lock(&device_registry_mutex);

    // Scan the registry for expired sessions and mark them for removal
    DEVICE_INFORMATION *device = device_registry;
    while (device != NULL) {
        if (device->current_timestamp < time(NULL)) {
            // Remove the device from the registry
            DEVICE_INFORMATION *previous_device = device;
            device = device->next;
            previous_device->next = NULL;
            free(previous_device);
