public class TransactionProcessor {
  private static final int MAX_THREADS = 10; // adjust as needed
  private static final long BUFFER_SIZE = 10000L; // adjust as needed
  private static final long MIN_BATCH_SIZE = 100L; // adjust as needed
  private static final long MAX_BATCH_SIZE = 1000L; // adjust as needed
