  private ExecutorService executor;
  private ConcurrentHashMap<String, Transaction> transactions;
  private long totalDiscrepancies;
  private long totalProcessingTime;

  public TransactionProcessor() {
    this.executor = Executors.newFixedThreadPool(MAX_THREADS);
    this.transactions = new ConcurrentHashMap<>();
    this.totalDiscrepancies = 0L;
    this.totalProcessingTime = 0L;
  }

  public void processTransaction(Transaction transaction) {
    executor.submit(() -> {
      long startTime = System.nanoTime();
      try {
        // validate transaction against external data source (if necessary)
        if (validateTransaction(transaction)) {
          // add transaction to buffer
          transactions.put(transaction.getId(), transaction);
          // check for discrepancies in buffer
          checkDiscrepancies();
        } else {
          // log validation failure
          System.out.println("Validation failed for transaction " + transaction.getId());
        }
      } catch (Exception e) {
        // log exception
        System.out.println("Error processing transaction: " + e.getMessage());
      } finally {
        long endTime = System.nanoTime();
        totalProcessingTime += endTime - startTime;
      }
    });
  }

  private boolean validateTransaction(Transaction transaction) {
    // implement validation logic here (if necessary)
    return true;
  }

  private void checkDiscrepancies() {
    long startTime = System.nanoTime();
    try {
      for (String id : transactions.keySet()) {
        Transaction transaction = transactions.get(id);
        // check discrepancy between expected and actual amount
        if (transaction.getExpectedAmount() != transaction.getActualAmount()) {
          totalDiscrepancies++;
          System.out.println("Discrepancy found for transaction " + id);
        }
      }
    } finally {
      long endTime = System.nanoTime();
      totalProcessingTime += endTime - startTime;
    }
  }

  public void flushBuffer() {
    // implement buffer flushing logic here (if necessary)
  }

  public void shutdown() {
    executor.shutdown();
  }
}
