#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <math.h>

// Define the maximum number of elements to be processed
#define MAX_ELEMENTS 100000

// Define the data structure for storing the input values
typedef struct {
    int integer;
    float floating;
} InputValue;

// Function to process the input list and determine the largest integer and floating-point number
void processInput(InputValue *input, int num_elements) {
    // Initialize variables for storing the largest integer and floating-point number
    int largest_integer = INT_MIN;
    float largest_floating = -FLT_MAX;

    // Iterate over each element in the input list
    for (int i = 0; i < num_elements; i++) {
        // Check if the current element is an integer
        if (input[i].integer != INT_MIN) {
            // Update the largest integer if necessary
            if (input[i].integer > largest_integer) {
                largest_integer = input[i].integer;
            }
        } else {
            // Check if the current element is a floating-point number
            if (input[i].floating != -FLT_MAX) {
                // Update the largest floating-point number if necessary
                if (input[i].floating > largest_floating) {
                    largest_floating = input[i].floating;
                }
            } else {
                // Handle non-numeric inputs or incomplete data streams
                printf("Error: Non-numeric input detected. Exiting...\n");
                exit(1);
            }
        }
    }

    // Output statistics about the distribution of integer and floating-point numbers
    printf("Integer distribution:\n");
    for (int i = 0; i < num_elements; i++) {
        if (input[i].integer != INT_MIN) {
            printf("%d ", input[i].integer);
        }
    }
    printf("\nFloating-point distribution:\n");
    for (int i = 0; i < num_elements; i++) {
        if (input[i].floating != -FLT_MAX) {
            printf("%.2f ", input[i].floating);
        }
    }
    printf("\n");

    // Free the dynamically allocated array
    free(input);
}

int main() {
    // Declare variables for storing the input values and the number of elements to be processed
    InputValue *input = NULL;
    int num_elements = 0;

    // Read the input list from standard input
    while (scanf("%d", &num_elements) == 1 && num_elements > 0) {
        // Dynamically allocate an array to store the input values
        input = malloc(sizeof(InputValue) * num_elements);
        if (!input) {
            printf("Error: Memory allocation failed. Exiting...\n");
            exit(1);
        }

        // Read each element in the input list and store it in the array
        for (int i = 0; i < num_elements; i++) {
            scanf("%d", &input[i].integer);
            if (scanf("%f", &input[i].floating) != 1) {
                input[i].floating = -FLT_MAX;
            }
        }

        // Process the input list and determine the largest integer and floating-point number
        processInput(input, num_elements);
    }

    return 0;
}
