#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <limits.h>

// Define a structure to store an integer and its index in the array
struct IntWithIndex {
    int value;
    size_t index;
};

// Function to read integers from standard input and validate them
void readInts(int* arr, size_t* count) {
    // Initialize variables
    size_t i = 0;
    int num;

    // Read integers from standard input until EOF is reached
    while (scanf("%d", &num) != EOF) {
        // Check if the integer is within the specified range
        if (num >= -1000 && num <= 1000) {
            // Store the integer in the array and increment the count
            arr[i++] = num;
            (*count)++;
        } else {
            // If the integer is not within the range, skip it
            continue;
        }
    }
}

// Function to find the largest integer in the array
int findLargest(const int* arr, size_t count) {
    // Initialize variables
    int largest = INT_MIN;
    size_t i;

    // Iterate over the array and find the largest integer
    for (i = 0; i < count; i++) {
        if (arr[i] > largest) {
            largest = arr[i];
        }
    }

    return largest;
}

// Function to output the total count of integers that were successfully validated and stored
void printCount(size_t count) {
    printf("Total count: %zu\n", count);
}

int main() {
    // Define an array to store the integers
    int arr[100];

    // Initialize variables
    size_t i = 0;
    size_t count = 0;

    // Read integers from standard input and validate them
    readInts(arr, &count);

    // Find the largest integer in the array
    int largest = findLargest(arr, count);

    // Output the largest integer and the total count of validated integers
    printf("Largest integer: %d\n", largest);
    printCount(count);

    return 0;
}
```
This code uses a `struct` to store an integer and its index in the array, which allows for efficient storage and retrieval of the integers. The `readInts` function reads integers from standard input until EOF is reached, validates each integer to ensure it falls within the specified range, and stores them in the array. The `findLargest` function finds the largest integer in the array by iterating over it and comparing each element to the current largest value. The `printCount` function outputs the total count of integers that were successfully validated and stored.

The code also handles edge cases such as empty input and invalid data gracefully by checking for EOF when reading integers from standard input, and skipping invalid integers instead of storing them in the array.']

