#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

// Define the maximum size of the linked list
#define MAX_SIZE 10000

// Define the structure for device metadata
typedef struct {
    char *identifier;
    int firmware_version;
    time_t last_update_time;
    enum status {ACTIVE, INACTIVE} status;
} Device;

// Define the structure for network interface statistics
typedef struct {
    double packet_loss;
    double throughput;
    double latency;
} NetworkInterfaceStats;

// Define the linked list node structure
typedef struct Node {
    Device device;
    NetworkInterfaceStats stats;
    struct Node *next;
} Node;

// Define the linked list head pointer
Node *head = NULL;

// Define the mutex lock for thread-safe operations
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

// Function to add a device to the linked list
void addDevice(char *identifier, int firmware_version, time_t last_update_time, enum status status) {
    // Create a new node for the device
    Node *newNode = (Node *)malloc(sizeof(Node));
    if (!newNode) {
        printf("Memory allocation failed\n");
        return;
    }

    // Initialize the node fields
    newNode->device.identifier = identifier;
    newNode->device.firmware_version = firmware_version;
    newNode->device.last_update_time = last_update_time;
    newNode->device.status = status;
    newNode->stats.packet_loss = 0;
    newNode->stats.throughput = 0;
    newNode->stats.latency = 0;

    // Lock the mutex to prevent concurrent access
    pthread_mutex_lock(&lock);

    // Check if the linked list is empty
    if (head == NULL) {
        head = newNode;
    } else {
        // Find the last node in the linked list
        Node *lastNode = head;
        while (lastNode->next != NULL) {
            lastNode = lastNode->next;
        }

        // Add the new node to the end of the linked list
        lastNode->next = newNode;
    }

    // Unlock the mutex
    pthread_mutex_unlock(&lock);
}

// Function to update a device in the linked list
void updateDevice(char *identifier, int firmware_version, time_t last_update_time, enum status status) {
    // Lock the mutex to prevent concurrent access
    pthread_mutex_lock(&lock);

    // Find the node with the matching identifier
    Node *node = head;
    while (node != NULL && strcmp(node->device.identifier, identifier) != 0) {
        node = node->next;
    }

    // Check if the node was found
    if (node == NULL) {
        printf("Device not found\n");
        return;
    }

    // Update the node fields
    node->device.firmware_version = firmware_version;
    node->device.last_update_time = last_update_time;
    node->device.status = status;

    // Unlock the mutex
    pthread_mutex_unlock(&lock);
}

// Function to retrieve a device from the linked list
void getDevice(char *identifier, Device *device) {
    // Lock the mutex to prevent concurrent access
    pthread_mutex_lock(&lock);

    // Find the node with the matching identifier
    Node *node = head;
    while (node != NULL && strcmp(node->device.identifier, identifier) != 0) {
        node = node->next;
    }

    // Check if the node was found
    if (node == NULL) {
        printf("Device not found\n");
        return;
    }

    // Copy the device fields to the output parameter
    strcpy(device->identifier, node->device.identifier);
    device->firmware_version = node->device.firmware_version;
    device->last_update_time = node->device.last_update_time;
    device->status = node->device.status;

    // Unlock the mutex
    pthread_mutex_unlock(&lock);
}

// Function to retrieve network interface statistics for a device from the linked list
void getNetworkInterfaceStats(char *identifier, NetworkInterfaceStats *stats) {
    // Lock the mutex to prevent concurrent access
    pthread_mutex_lock(&lock);

    // Find the node with the matching identifier
    Node *node = head;
    while (node != NULL && strcmp(node->device.identifier, identifier) != 0) {
        node = node->next;
    }

    // Check if the node was found
    if (node == NULL) {
        printf("Device not found\n");
        return;
    }

    // Copy the network interface statistics to the output parameter
    stats->packet_loss = node->stats.packet_loss;
    stats->throughput = node->stats.throughput;
    stats->latency = node->stats.latency;

    // Unlock the mutex
    pthread_mutex_unlock(&lock);
}

// Function to update network interface statistics for a device in the linked list
void updateNetworkInterfaceStats(char *identifier, double packet_loss, double throughput, double latency) {
    // Lock the mutex to prevent concurrent access
    pthread_mutex_lock(&lock);

    // Find the node with the matching identifier
    Node *node = head;
    while (node != NULL && strcmp(node->device.identifier, identifier) != 0) {
        node = node->next;
    }

    // Check if the node was found
    if (node == NULL) {
        printf("Device not found\n");
        return;
    }

    // Update the network interface statistics for the node
    node->stats.packet_loss = packet_loss;
    node->stats.throughput = throughput;
    node->stats.latency = latency;

    // Unlock the mutex
    pthread_mutex_unlock(&lock);
}

// Function to remove a device from the linked list
void removeDevice(char *identifier) {
    // Lock the mutex to prevent concurrent access
    pthread_mutex_lock(&lock);

    // Find the node with the matching identifier
    Node *node = head;
    while (node != NULL && strcmp(node->device.identifier, identifier) != 0) {
        node = node->next;
    }

    // Check if the node was found
    if (node == NULL) {
        printf("Device not found\n");
        return;
    }

    // Remove the node from the linked list
    if (head == node) {
        head = head->next;
    } else {
        Node *prevNode = head;
        while (prevNode->next != node) {
            prevNode = prevNode->next;
        }
        prevNode->next = node->next;
    }

    // Free the memory allocated for the node
    free(node);

    // Unlock the mutex
    pthread_mutex_unlock(&lock);
}

// Function to export device data to a file
void exportDeviceData(char *filename) {
    // Lock the mutex to prevent concurrent access
    pthread_mutex_lock(&lock);

    // Open the output file for writing
    FILE *file = fopen(filename, "w");
    if (file == NULL) {
        printf("Error opening file\n");
        return;
    }

    // Write the device data to the file
    Node *node = head;
    while (node != NULL) {
        fprintf(file, "%s,%d,%ld,%s\n", node->device.identifier, node->device.firmware_version, node->device.last_update_time, node->device.status);
        node = node->next;
    }

    // Close the output file
    fclose(file);

    // Unlock the mutex
    pthread_mutex_unlock(&lock);
}

// Function to import device data from a file
void importDeviceData(char *filename) {
    // Lock the mutex to prevent concurrent access
    pthread_mutex_lock(&lock);

    // Open the input file for reading
    FILE *file = fopen(filename, "r");
    if (file == NULL) {
        printf("Error opening file\n");
        return;
    }

    // Read the device data from the file
    char line[1024];
    while (fgets(line, sizeof(line), file)) {
        // Parse the line and add the device to the linked list
        char *token = strtok(line, ",");
        if (token == NULL) {
            continue;
        }
        char *identifier = token;
        token = strtok(NULL, ",");
        if (token == NULL) {
            continue;
        }
        int firmware_version = atoi(token);
        token = strtok(NULL, ",");
        if (token == NULL) {
            continue;
        }
        time_t last_update_time = atol(token);
        token = strtok(NULL, ",");
        if (token == NULL) {
            continue;
        }
        enum status status = *token;
        addDevice(identifier, firmware_version, last_update_time, status);
    }

    // Close the input file
    fclose(file);

    // Unlock the mutex
    pthread_mutex_unlock(&lock);
}
