import java.util.HashMap;
import java.util.Map;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.locks.Lock;
import java.util.concurrent.locks.ReentrantLock;

public class SessionRegistry {
    private final Map<String, Session> sessions = new ConcurrentHashMap<>();
    private final Lock lock = new ReentrantLock();

    public void addSession(String sessionId, String authToken, long lastActivityTimestamp) {
        lock.lock();
        try {
            sessions.put(sessionId, new Session(authToken, lastActivityTimestamp));
        } finally {
            lock.unlock();
        }
    }

    public void updateSession(String sessionId, String authToken, long lastActivityTimestamp) {
        lock.lock();
        try {
            sessions.get(sessionId).setAuthToken(authToken);
            sessions.get(sessionId).setLastActivityTimestamp(lastActivityTimestamp);
        } finally {
            lock.unlock();
        }
    }

    public void terminateSession(String sessionId) {
        lock.lock();
        try {
            sessions.remove(sessionId);
        } finally {
            lock.unlock();
        }
    }

    public boolean isSessionValid(String sessionId) {
        lock.lock();
        try {
            return sessions.containsKey(sessionId) && sessions.get(sessionId).isValid();
        } finally {
            lock.unlock();
        }
    }

    public void purgeExpiredSessions() {
        lock.lock();
        try {
            long currentTimestamp = System.currentTimeMillis();
            sessions.entrySet().removeIf(e -> e.getValue().getLastActivityTimestamp() < currentTimestamp - 30 * 60 * 1000);
        } finally {
            lock.unlock();
        }
    }

    public void generateAuditLogs() {
        lock.lock();
        try {
            for (Map.Entry<String, Session> entry : sessions.entrySet()) {
                String sessionId = entry.getKey();
                Session session = entry.getValue();
                // Generate audit log entry for session
            }
        } finally {
            lock.unlock();
        }
    }
}

class Session {
    private final String authToken;
    private long lastActivityTimestamp;
    private boolean valid = true;

    public Session(String authToken, long lastActivityTimestamp) {
        this.authToken = authToken;
        this.lastActivityTimestamp = lastActivityTimestamp;
    }

    public String getAuthToken() {
        return authToken;
    }

    public void setAuthToken(String authToken) {
        this.authToken = authToken;
    }

    public long getLastActivityTimestamp() {
        return lastActivityTimestamp;
    }

    public void setLastActivityTimestamp(long lastActivityTimestamp) {
        this.lastActivityTimestamp = lastActivityTimestamp;
    }

    public boolean isValid() {
        return valid;
    }

    public void setValid(boolean valid) {
        this.valid = valid;
    }
}
