    struct TEAM_STRUCTURE *team;
    time_t CURRENT_TIMESTAMP;
} PROJECT;

// Define structure for team members
typedef struct TEAM_STRUCTURE {
    char name[20];
    int id;
} TEAM_STRUCTURE;

// Define registry of projects
PROJECT *projects = NULL;
int num_projects = 0;
pthread_mutex_t project_lock = PTHREAD_MUTEX_INITIALIZER;

// Function to initialize and manage the registry of projects
void init_project(int id, struct TEAM_STRUCTURE *team) {
    // Lock the mutex before accessing the registry
    pthread_mutex_lock(&project_lock);

    // Check if project with given ID already exists
    for (int i = 0; i < num_projects; i++) {
        if (projects[i].PROJECT_ID == id) {
            // Project already exists, update team and timestamp
            projects[i].team = team;
            projects[i].CURRENT_TIMESTAMP = time(NULL);
            break;
        }
    }

    // If project does not exist, add it to the registry
    if (i == num_projects) {
        PROJECT *new_project = malloc(sizeof(PROJECT));
        new_project->PROJECT_ID = id;
        new_project->team = team;
        new_project->CURRENT_TIMESTAMP = time(NULL);
        projects[num_projects++] = new_project;
    }

    // Unlock the mutex after accessing the registry
    pthread_mutex_unlock(&project_lock);
}

// Function to schedule a task for a project
void schedule_task(int id, int task_id) {
    // Lock the mutex before accessing the registry
    pthread_mutex_lock(&project_lock);

    // Find the project with the given ID
    for (int i = 0; i < num_projects; i++) {
        if (projects[i].PROJECT_ID == id) {
            // Schedule the task and update timestamp
            projects[i].CURRENT_TIMESTAMP = time(NULL);
            break;
        }
    }

    // Unlock the mutex after accessing the registry
    pthread_mutex_unlock(&project_lock);
}

// Function to update a task's priority level for a project
void update_priority(int id, int task_id, int new_priority) {
    // Lock the mutex before accessing the registry
    pthread_mutex_lock(&project_lock);

    // Find the project with the given ID
    for (int i = 0; i < num_projects; i++) {
        if (projects[i].PROJECT_ID == id) {
            // Update the task's priority level and update timestamp
            projects[i].CURRENT_TIMESTAMP = time(NULL);
            break;
        }
    }

    // Unlock the mutex after accessing the registry
    pthread_mutex_unlock(&project_lock);
}

// Function to reassign overdue tasks to a backup team
void reassign_tasks() {
    // Lock the mutex before accessing the registry
    pthread_mutex_lock(&project_lock);

    // Iterate through all projects and check for overdue tasks
    for (int i = 0; i < num_projects; i++) {
        if (projects[i].CURRENT_TIMESTAMP + 10 < time(NULL)) {
            // Task is overdue, reassign to backup team
            projects[i].team = &backup_team;
            projects[i].CURRENT_TIMESTAMP = time(NULL);
        }
    }

    // Unlock the mutex after accessing the registry
    pthread_mutex_unlock(&project_lock);
}
