#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

// Define cache entry structure
typedef struct {
    int request_id;
    void *response_handler;
    time_t timestamp;
} cache_entry_t;

// Define cache hash table
static cache_entry_t **cache = NULL;

// Define cache size and expiration duration
#define CACHE_SIZE 1024
#define EXPIRATION_DURATION 3600 // in seconds

// Function to add a new entry to the cache
void add_to_cache(int request_id, void *response_handler) {
    // Check if cache is initialized
    if (cache == NULL) {
        cache = malloc(sizeof(cache_entry_t *) * CACHE_SIZE);
        memset(cache, 0, sizeof(cache_entry_t *) * CACHE_SIZE);
    }

    // Find an empty slot in the cache
    int i;
    for (i = 0; i < CACHE_SIZE && cache[i] != NULL; i++) {}

    // If no empty slots found, evict oldest entry
    if (i == CACHE_SIZE) {
        time_t oldest_timestamp = 0;
        int oldest_index = -1;
        for (int j = 0; j < CACHE_SIZE; j++) {
            if (cache[j] != NULL && cache[j]->timestamp < oldest_timestamp) {
                oldest_timestamp = cache[j]->timestamp;
                oldest_index = j;
            }
        }
        free(cache[oldest_index]);
        cache[oldest_index] = NULL;
    }

    // Add new entry to the cache
    cache_entry_t *new_entry = malloc(sizeof(cache_entry_t));
    new_entry->request_id = request_id;
    new_entry->response_handler = response_handler;
    new_entry->timestamp = time(NULL);
    cache[i] = new_entry;
}

// Function to retrieve an entry from the cache
void *get_from_cache(int request_id) {
    // Check if cache is initialized
    if (cache == NULL) {
        return NULL;
    }

    // Find the requested entry in the cache
    for (int i = 0; i < CACHE_SIZE && cache[i] != NULL; i++) {
        if (cache[i]->request_id == request_id) {
            return cache[i];
        }
    }

    // If entry not found, return NULL
    return NULL;
}

// Function to update an entry in the cache
void update_in_cache(int request_id, void *response_handler) {
    // Check if cache is initialized
    if (cache == NULL) {
        return;
    }

    // Find the requested entry in the cache
    for (int i = 0; i < CACHE_SIZE && cache[i] != NULL; i++) {
        if (cache[i]->request_id == request_id) {
            cache[i]->response_handler = response_handler;
            cache[i]->timestamp = time(NULL);
            return;
        }
    }
}

// Function to invalidate an entry in the cache
void invalidate_in_cache(int request_id) {
    // Check if cache is initialized
    if (cache == NULL) {
        return;
    }

    // Find the requested entry in the cache
    for (int i = 0; i < CACHE_SIZE && cache[i] != NULL; i++) {
        if (cache[i]->request_id == request_id) {
            free(cache[i]);
            cache[i] = NULL;
            return;
        }
    }
}

// Function to evict expired entries from the cache
void evict_expired_entries() {
    // Check if cache is initialized
    if (cache == NULL) {
        return;
    }

    time_t current_timestamp = time(NULL);
    for (int i = 0; i < CACHE_SIZE && cache[i] != NULL; i++) {
        if (current_timestamp - cache[i]->timestamp > EXPIRATION_DURATION) {
            free(cache[i]);
            cache[i] = NULL;
        }
    }
}
