#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <math.h>
#include <time.h>
#include <pthread.h>
#include <semaphore.h>

// Define the structure to store word frequencies
struct WordFrequency {
    char* word;
    int count;
};

// Define the comparison function for sorting word frequencies
int compare_word_frequencies(const void* a, const void* b) {
    struct WordFrequency* wa = (struct WordFrequency*)a;
    struct WordFrequency* wb = (struct WordFrequency*)b;
    return strcmp(wa->word, wb->word);
}

// Define the function to read a file and calculate word frequencies
void* read_file(void* args) {
    // Cast the arguments to the correct type
    char* filename = (char*)args;

    // Open the file for reading
    FILE* file = fopen(filename, "r");
    if (!file) {
        perror("fopen");
        return NULL;
    }

    // Create a hash table to store word frequencies
    struct WordFrequency** freqs = (struct WordFrequency**)malloc(sizeof(struct WordFrequency*) * 1024);
    for (int i = 0; i < 1024; i++) {
        freqs[i] = NULL;
    }

    // Read the file line by line and calculate word frequencies
    char* line = NULL;
    size_t len = 0;
    ssize_t read;
    while ((read = getline(&line, &len, file)) != -1) {
        // Split the line into words using whitespace as a delimiter
        char** words = strsplit(line, " ");
        for (int i = 0; i < 1024; i++) {
            if (words[i] == NULL) break;
            struct WordFrequency* freq = (struct WordFrequency*)malloc(sizeof(struct WordFrequency));
            freq->word = words[i];
            freq->count = 1;
            int index = hash_function(freq->word);
            if (freqs[index] == NULL) {
                freqs[index] = freq;
            } else {
                struct WordFrequency* current = freqs[index];
                while (current->next != NULL) {
                    current = current->next;
                }
                current->next = freq;
            }
        }
    }

    // Sort the word frequencies and output the top N most frequently occurring words
    qsort(freqs, 1024, sizeof(struct WordFrequency*), compare_word_frequencies);
    for (int i = 0; i < 1024; i++) {
        if (freqs[i] == NULL) break;
        printf("%s: %d\n", freqs[i]->word, freqs[i]->count);
    }

    // Clean up the hash table and file
    for (int i = 0; i < 1024; i++) {
        if (freqs[i] == NULL) break;
        struct WordFrequency* current = freqs[i];
        while (current != NULL) {
            struct WordFrequency* next = current->next;
            free(current);
            current = next;
        }
    }
    fclose(file);
    return NULL;
}

// Define the function to split a string into an array of substrings using a delimiter
char** strsplit(const char* str, const char* delim) {
    int count = 0;
    for (int i = 0; str[i] != '\0'; i++) {
        if (strchr(delim, str[i]) != NULL) {
            count++;
        }
    }
    char** result = (char**)malloc(sizeof(char*) * (count + 1));
    for (int i = 0; i < count; i++) {
        result[i] = strtok((char*)str, delim);
        str += strlen(result[i]);
    }
    result[count] = NULL;
    return result;
}

// Define the function to calculate a hash value for a word
int hash_function(const char* word) {
    int hash = 0;
    for (int i = 0; word[i] != '\0'; i++) {
        hash += word[i];
    }
    return hash % 1024;
}

// Define the main function to read multiple files and calculate word frequencies
int main(int argc, char** argv) {
    // Check for command line arguments
    if (argc < 3) {
        printf("Usage: %s [--help] -c <config_file> -o <output_file>\n", argv[0]);
        return 1;
    }

    // Parse the command line options
    char* config_file = NULL;
    char* output_file = NULL;
    for (int i = 1; i < argc - 1; i++) {
        if (strcmp(argv[i], "--help") == 0) {
            printf("Usage: %s [--help] -c <config_file> -o <output_file>\n", argv[0]);
            return 1;
        } else if (strcmp(argv[i], "-c") == 0) {
            config_file = argv[++i];
        } else if (strcmp(argv[i], "-o") == 0) {
            output_file = argv[++i];
        }
    }

    // Load the configuration file and validate it
    FILE* config = fopen(config_file, "r");
    if (!config) {
        perror("fopen");
        return 1;
    }
    char line[256];
    while (fgets(line, sizeof(line), config)) {
        // Check for the configuration file format
        if (strncmp(line, "output_file", 11) == 0) {
            output_file = strtok(line, " ");
        } else if (strncmp(line, "num_threads", 11) == 0) {
            int num_threads = atoi(strtok(NULL, " "));
            pthread_t* threads = (pthread_t*)malloc(sizeof(pthread_t) * num_threads);
            for (int i = 0; i < num_threads; i++) {
                char filename[256];
                sprintf(filename, "%s%d", argv[1], i + 1);
                pthread_create(&threads[i], NULL, read_file, (void*)filename);
            }
            for (int i = 0; i < num_threads; i++) {
                pthread_join(threads[i], NULL);
            }
        } else {
            printf("Invalid configuration file format\n");
            return 1;
        }
    }
    fclose(config);

    // Output the top N most frequently occurring words to the output file
    FILE* out = fopen(output_file, "w");
    if (!out) {
        perror("fopen");
        return 1;
    }
    for (int i = 0; i < 1024; i++) {
        if (freqs[i] == NULL) break;
        printf("%s: %d\n", freqs[i]->word, freqs[i]->count);
        fprintf(out, "%s: %d\n", freqs[i]->word, freqs[i]->count);
    }
    fclose(out);
    return 0;
}
