using System;
using System.Collections.Generic;
using System.Linq;
using System.Text;
using System.Threading.Tasks;

namespace TokenValidator
{
    public class TokenValidator
    {
        private int minValue;
        private int maxValue;

        public TokenValidator(int minValue, int maxValue)
        {
            this.minValue = minValue;
            this.maxValue = maxValue;
        }

        public bool ValidateToken(string tokenJsonString)
        {
            try
            {
                // Parse the JSON string to extract the required fields
                var tokenFields = JsonConvert.DeserializeObject<Dictionary<string, object>>(tokenJsonString);

                // Check if all required fields are present and valid
                if (!tokenFields.ContainsKey("access_token") || !tokenFields.ContainsKey("expires_in") || !tokenFields.ContainsKey("token_type"))
                {
                    return false;
                }

                var accessToken = tokenFields["access_token"];
                var expiresIn = tokenFields["expires_in"];
                var tokenType = tokenFields["token_type"];

                // Check if the token type is 'Bearer' and the expiration time is a positive integer
                if (tokenType != "Bearer" || !int.TryParse(expiresIn, out int expiresInInt) || expiresInInt <= 0)
                {
                    return false;
                }

                // Check if the access token is not empty and has a valid length
                if (string.IsNullOrEmpty(accessToken) || accessToken.Length < 10)
                {
                    return false;
                }

                return true;
            }
            catch (Exception ex)
            {
                // Log the exception and return false to indicate validation failure
                Console.WriteLine($"Error validating token: {ex.Message}");
                return false;
            }
        }

        public float GetRandomFloatValue()
        {
            var random = new Random();
            return (float)random.NextDouble() * (maxValue - minValue) + minValue;
        }

        public int GetRandomIntegerValue()
        {
            var random = new Random();
            return random.Next(minValue, maxValue);
        }

        public override string ToString()
        {
            return $"TokenValidator: Min value={minValue}, Max value={maxValue}";
        }
    }
}
```
