// Struct to store keyword information
struct Keyword {
    char *keyword;
    int frequency;
};

// Struct to store context information
struct Context {
    char *sentence;
    char *paragraph;
};

// Struct to store report information
struct Report {
    struct Keyword *keywords;
    int num_keywords;
    struct Context *contexts;
    int num_contexts;
};

// Function to extract keywords from a file
void extract_keywords(char *filename, struct Report *report) {
    // Open the file for reading
    FILE *file = fopen(filename, "r");
    if (file == NULL) {
        printf("Error: unable to open file %s\n", filename);
        return;
    }

    // Read the file line by line
    char line[MAX_LINE_LEN];
    while (fgets(line, MAX_LINE_LEN, file) != NULL) {
        // Check if the line contains any keywords
        int keyword_found = 0;
        for (int i = 0; i < report->num_keywords; i++) {
            char *keyword = report->keywords[i].keyword;
            if (strstr(line, keyword) != NULL) {
                // Increment the frequency of the keyword
                report->keywords[i].frequency++;
                keyword_found = 1;
                break;
            }
        }

        // If a keyword was found, add the context to the report
        if (keyword_found) {
            struct Context *context = malloc(sizeof(struct Context));
            context->sentence = strdup(line);
            context->paragraph = strdup(report->keywords[i].keyword);
            report->num_contexts++;
            report->contexts = realloc(report->contexts, report->num_contexts * sizeof(struct Context));
            report->contexts[report->num_contexts - 1] = context;
        }
    }

    // Close the file
    fclose(file);
}

// Function to generate a report in JSON format
void generate_json_report(char *filename, struct Report *report) {
    // Open the output file for writing
    FILE *output = fopen(filename, "w");
    if (output == NULL) {
        printf("Error: unable to open output file %s\n", filename);
        return;
    }

    // Write the JSON header
    fprintf(output, "{\n");

    // Write the keywords section
    fprintf(output, "  \"keywords\": [\n");
    for (int i = 0; i < report->num_keywords; i++) {
        struct Keyword *keyword = &report->keywords[i];
        fprintf(output, "    {\"keyword\": \"%s\", \"frequency\": %d}", keyword->keyword, keyword->frequency);
        if (i < report->num_keywords - 1) {
            fprintf(output, ",");
        }
        fprintf(output, "\n");
    }
    fprintf(output, "  ],\n");

    // Write the contexts section
    fprintf(output, "  \"contexts\": [\n");
    for (int i = 0; i < report->num_contexts; i++) {
        struct Context *context = &report->contexts[i];
        fprintf(output, "    {\"sentence\": \"%s\", \"paragraph\": \"%s\"}", context->sentence, context->paragraph);
        if (i < report->num_contexts - 1) {
            fprintf(output, ",");
        }
        fprintf(output, "\n");
    }
    fprintf(output, "  ]\n");

    // Write the JSON footer
    fprintf(output, "}\n");

    // Close the output file
    fclose(output);
}

// Function to generate a report in CSV format
void generate_csv_report(char *filename, struct Report *report) {
    // Open the output file for writing
