// Define the structure for API requests
typedef struct {
    long request_id;
    void (*response_handler)(void*);
    time_t timestamp;
} api_request_t;

// Define the structure for the cache
typedef struct {
    api_request_t** requests;
    int capacity;
    int size;
    pthread_mutex_t mutex;
} cache_t;

// Define the function to manage memory and the dynamic cache
void manage_memory(cache_t* cache) {
    // Allocate memory for the cache
    cache->requests = (api_request_t**)malloc(sizeof(api_request_t*) * cache->capacity);
    if (!cache->requests) {
        printf("Error: Failed to allocate memory for cache\n");
        return;
    }

    // Initialize the mutex for thread safety
    pthread_mutex_init(&cache->mutex, NULL);

    // Set the initial size of the cache to 0
    cache->size = 0;
}

// Define the function to add a new request to the cache
void add_request(api_request_t* request, cache_t* cache) {
    // Acquire the mutex for thread safety
    pthread_mutex_lock(&cache->mutex);

    // Check if the cache is full
    if (cache->size == cache->capacity) {
        // If the cache is full, evict the least recently used request
        api_request_t* lru = cache->requests[0];
        for (int i = 1; i < cache->size; i++) {
            if (cache->requests[i]->timestamp < lru->timestamp) {
                lru = cache->requests[i];
            }
        }
        // Free the memory of the evicted request
        free(lru);
        // Remove the evicted request from the cache
        for (int i = 0; i < cache->size - 1; i++) {
            if (cache->requests[i] == lru) {
                cache->requests[i] = cache->requests[i + 1];
            }
        }
        cache->size--;
    }

    // Add the new request to the cache
    cache->requests[cache->size] = request;
    cache->size++;

    // Release the mutex for thread safety
    pthread_mutex_unlock(&cache->mutex);
}

// Define the function to retrieve a request from the cache
api_request_t* get_request(long request_id, cache_t* cache) {
    // Acquire the mutex for thread safety
    pthread_mutex_lock(&cache->mutex);

    // Search for the requested request in the cache
    api_request_t* request = NULL;
    for (int i = 0; i < cache->size; i++) {
        if (cache->requests[i]->request_id == request_id) {
            request = cache->requests[i];
            break;
        }
    }

    // Release the mutex for thread safety
    pthread_mutex_unlock(&cache->mutex);

    return request;
}

