void invalidate_requests(cache_t* cache) {
    // Acquire the mutex for thread safety
    pthread_mutex_lock(&cache->mutex);

    // Iterate over the requests in the cache and check if they are expired
    for (int i = 0; i < cache->size; i++) {
        api_request_t* request = cache->requests[i];
