public class WeatherDataFetcher {
    private static final Logger logger = Logger.getLogger(WeatherDataFetcher.class.getName());

    // Data fetching and storage
    private static final int CACHE_SIZE = 1000;
    private static final long REFRESH_INTERVAL = Duration.ofMinutes(5);
    private static final String DATABASE_URL = "jdbc:mysql://localhost/weather_data";
    private static final String API_ENDPOINT = "https://api.openweathermap.org/data/2.5/weather?q={location}&appid={API_KEY}";

