            for (int j = 0; j < num_offsets; j++) {
                if (offsets[j] == offset) {
                    keys[j]++;
                    records[j].value++;
                    break;
                }
            }
            book = NULL;
            chap = 0;
            vers = 0;
        }
    }

    // Clean up regular expressions
    regfree(&reg);
    regfree(&chap_reg);
    regfree(&vers_reg);
