                    strcpy(books[j].name, &input[i]);
                    books[j].count++;
                }
            }
        }
    }

    // Clean up list of book names found in input string
    for (int i = 0; i < num_offsets; i++) {
        if (books[i].name != NULL) {
            free(books[i].name);
        }
    }
    free(books);
}

