        return 1;
    }

    // Check if the token handler for the session is invalid
    if (!token_handler_is_valid(sessions[index].token_handler)) {
        return 1;
    }

    return 0;
}

// Define the function to remove a session from the array
void remove_session(int index) {
    // Shift all sessions after the removed session down by one index
    for (int i = index + 1; i < MAX_SESSIONS; i++) {
        sessions[i - 1] = sessions[i];
    }

    // Set the last session to an empty struct
    sessions[MAX_SESSIONS - 1] = (struct session_info) {};
}

// Define the function to update the expiry time for a session
void update_expiry_time(int index) {
    // Generate a new timestamp for the session
    unsigned int new_timestamp = generate_timestamp();

    // Update the expiry time for the session
    sessions[index].expiry_time = new_timestamp;
}

// Define the function to check if all sessions are invalidated
int all_sessions_invalidated() {
    // Check if all sessions have been invalidated
    for (int i = 0; i < MAX_SESSIONS; i++) {
        if (!is_session_invalid(i)) {
            return 0;
        }
    }

    return 1;
}

// Define the function to generate a new timestamp
unsigned int generate_timestamp() {
    // Generate a new timestamp using the seed
    unsigned int new_timestamp = rand_r(&seed) % (time(NULL) + MAX_SESSIONS);

    return new_timestamp;
}
