import java.util.*;
import java.util.regex.Pattern;

public static int countUniqueWords(List<String> words) {
    // Create a hash map to store word occurrences
    Map<String, Integer> wordCounts = new HashMap<>();

    // Iterate over the input list and update the hash map
    for (String word : words) {
        // Remove punctuation and convert to lowercase
        String cleanWord = word.toLowerCase().replaceAll("[^a-zA-Z]", "");

        // Check if the word is a stop word and skip it if necessary
        if (!isStopWord(cleanWord)) {
            // Increment the count for this word in the hash map
            int count = wordCounts.getOrDefault(cleanWord, 0) + 1;
            wordCounts.put(cleanWord, count);
        }
    }

    // Iterate over the hash map and return the number of unique words that appear exactly once
    int uniqueWords = 0;
    for (Map.Entry<String, Integer> entry : wordCounts.entrySet()) {
        if (entry.getValue() == 1) {
            uniqueWords++;
        }
    }
    return uniqueWords;
}

private static boolean isStopWord(String word) {
    // Add more stop words as necessary
    String[] stopWords = {"and", "the"};
    for (String stopWord : stopWords) {
        if (stopWord.equals(word)) {
            return true;
        }
    }
    return false;
}
