// Define the structure for an NFAPI_CRC_INDICATION_PDU_T
typedef struct {
    int rx_ue_information_tag;
    int rnti;
    int crc_indication_rel8_tag;
} nfapi_crc_indication_pdu_t;

// Define the structure for a record
typedef struct {
    int value;
} record;

// Define the memory management subsystem
typedef struct {
    long *offsets;
    int *keys;
    record **records;
    size_t capacity;
    size_t count;
    pthread_mutex_t mutex;
} mem_mgmt_subsys_t;

// Define the configuration for the memory management subsystem
typedef struct {
    int random_value_range;
    int initial_dataset_population_strategy;
} mem_mgmt_config_t;

// Initialize the memory management subsystem
void init_mem_mgmt_subsys(mem_mgmt_subsys_t *subsys, size_t capacity) {
    subsys->offsets = malloc(capacity * sizeof(long));
    subsys->keys = malloc(capacity * sizeof(int));
    subsys->records = malloc(capacity * sizeof(record*));
    subsys->count = 0;
    subsys->capacity = capacity;
    pthread_mutex_init(&subsys->mutex, NULL);
}

// Allocate memory for a new record
void allocate_record(mem_mgmt_subsys_t *subsys) {
    pthread_mutex_lock(&subsys->mutex);
    if (subsys->count == subsys->capacity) {
        // Reallocate the memory for the records array
        size_t new_capacity = subsys->capacity * 2;
        record **new_records = realloc(subsys->records, new_capacity * sizeof(record*));
        if (new_records == NULL) {
            // Handle failed allocation
            pthread_mutex_unlock(&subsys->mutex);
            return;
        }
        subsys->records = new_records;
        subsys->capacity = new_capacity;
    }
    record *new_record = malloc(sizeof(record));
    if (new_record == NULL) {
        // Handle failed allocation
        pthread_mutex_unlock(&subsys->mutex);
        return;
    }
    subsys->records[subsys->count] = new_record;
    subsys->offsets[subsys->count] = 0;
    subsys->keys[subsys->count] = 0;
    subsys->count++;
    pthread_mutex_unlock(&subsys->mutex);
}

// Free memory for a record
void free_record(mem_mgmt_subsys_t *subsys, size_t index) {
    pthread_mutex_lock(&subsys->mutex);
    if (index >= subsys->count) {
        // Handle invalid index
        pthread_mutex_unlock(&subsys->mutex);
        return;
    }
    record *record = subsys->records[index];
    free(record);
    subsys->offsets[index] = 0;
    subsys->keys[index] = 0;
    subsys->count--;
    pthread_mutex_unlock(&subsys->mutex);
}

// Populate the memory management subsystem with a dataset from an external data source
