}

// Free the memory management subsystem
void free_mem_mgmt_subsys(mem_mgmt_subsys_t *subsys) {
    pthread_mutex_destroy(&subsys->mutex);
    free(subsys->offsets);
    free(subsys->keys);
    for (size_t i = 0; i < subsys->count; i++) {
        record *record = subsys->records[i];
        free(record);
    }
    free(subsys->records);
}
