// Define the structure to store session information
typedef struct {
    int session_id;
    void* token_handler;
    time_t timestamp;
} session_t;

// Define the cache size and expiration time for sessions
#define CACHE_SIZE 1000
#define SESSION_EXPIRATION_TIME 3600 // in seconds

// Define the mutex to protect the cache
pthread_mutex_t cache_lock = PTHREAD_MUTEX_INITIALIZER;

// Define the function to add a new session to the cache
void add_session(int session_id, void* token_handler) {
    // Acquire the lock on the cache
    pthread_mutex_lock(&cache_lock);

    // Check if the cache is full
    if (cache_size >= CACHE_SIZE) {
        // Evict the least recently used session from the cache
        evict_session();
    }

    // Add the new session to the cache
    session_t* new_session = malloc(sizeof(session_t));
    new_session->session_id = session_id;
    new_session->token_handler = token_handler;
    new_session->timestamp = time(NULL);
    cache[cache_size++] = new_session;

    // Release the lock on the cache
    pthread_mutex_unlock(&cache_lock);
}

// Define the function to remove a session from the cache
void remove_session(int session_id) {
    // Acquire the lock on the cache
    pthread_mutex_lock(&cache_lock);

    // Find the session in the cache
    int i;
    for (i = 0; i < cache_size; i++) {
        if (cache[i]->session_id == session_id) {
            break;
        }
    }

    // Remove the session from the cache
    if (i < cache_size) {
        free(cache[i]);
        cache[i] = NULL;
        cache_size--;
    }

    // Release the lock on the cache
    pthread_mutex_unlock(&cache_lock);
}

// Define the function to evict a session from the cache
void evict_session() {
    // Acquire the lock on the cache
    pthread_mutex_lock(&cache_lock);

    // Find the least recently used session in the cache
    int i;
    for (i = 0; i < cache_size; i++) {
        if (cache[i]->timestamp < time(NULL) - SESSION_EXPIRATION_TIME) {
            break;
        }
    }

    // Evict the session from the cache
    if (i < cache_size) {
        free(cache[i]);
        cache[i] = NULL;
        cache_size--;
    }

    // Release the lock on the cache
    pthread_mutex_unlock(&cache_lock);
}

// Define the function to check if a session is valid
int is_session_valid(int session_id) {
    // Acquire the lock on the cache
    pthread_mutex_lock(&cache_lock);

    // Find the session in the cache
    int i;
    for (i = 0; i < cache_size; i++) {
        if (cache[i]->session_id == session_id) {
            break;
        }
    }

    // Check if the session is valid
    int valid = 1;
    if (i < cache_size && cache[i]->timestamp > time(NULL) - SESSION_EXPIRATION_TIME) {
        valid = 0;
    }

    // Release the lock on the cache
    pthread_mutex_unlock(&cache_lock);

    return valid;
}
```
