#include <math.h>
#include <time.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <pthread.h>
#include <semaphore.h>
#include <stdbool.h>

#define MAX_FILENAME_LENGTH 256
#define DEFAULT_OUTPUT_FILE "word_frequencies.txt"
#define DEFAULT_NUM_WORDS 10
#define MIN_WORD_LENGTH 3
#define MAX_WORD_LENGTH 20
#define NUM_THREADS 4
#define TIMEOUT 5 // seconds

// Struct to store word frequencies and their counts
typedef struct {
    char *word;
    int count;
} WordFrequency;

// Global variables
char *output_file = DEFAULT_OUTPUT_FILE;
int num_words = DEFAULT_NUM_WORDS;
bool verbose = false;

// Function prototypes
void parse_command_line(int argc, char **argv);
void read_files(char **filenames, int num_files);
void calculate_word_frequencies();
void sort_word_frequencies();
void print_top_words();
void cleanup();

// Main function
int main(int argc, char **argv) {
    // Parse command line arguments
    parse_command_line(argc, argv);

    // Read input files and calculate word frequencies
    read_files(filenames, num_files);
    calculate_word_frequencies();

    // Sort word frequencies and print top words
    sort_word_frequencies();
    print_top_words();

    // Cleanup
    cleanup();

    return 0;
}

// Parse command line arguments
void parse_command_line(int argc, char **argv) {
    int c;
    while ((c = getopt(argc, argv, "o:n:vh")) != -1) {
        switch (c) {
            case 'o':
                output_file = optarg;
                break;
            case 'n':
                num_words = atoi(optarg);
                break;
            case 'v':
                verbose = true;
                break;
            case 'h':
                printf("Usage: %s [-o output_file] [-n num_words] [-v]\n", argv[0]);
                exit(0);
        }
    }
}

// Read input files and calculate word frequencies
void read_files(char **filenames, int num_files) {
    // Initialize variables
    WordFrequency *word_frequencies = (WordFrequency *)malloc(sizeof(WordFrequency) * num_words);
    memset(word_frequencies, 0, sizeof(WordFrequency) * num_words);
    int i;
    for (i = 0; i < num_files; i++) {
        char *filename = filenames[i];
        FILE *file = fopen(filename, "r");
        if (!file) {
            perror("fopen");
            exit(1);
        }
        // Read file line by line and calculate word frequencies
        char *line = NULL;
        size_t len = 0;
        ssize_t read;
        while ((read = getline(&line, &len, file)) != -1) {
            // Remove newline character from end of line
            int length = strlen(line);
            if (length > 0 && line[length - 1] == '\n') {
                line[length - 1] = '\0';
            }
            // Tokenize line and calculate word frequencies
            char *token = strtok(line, " \t\n");
            while (token != NULL) {
                int length = strlen(token);
                if (length >= MIN_WORD_LENGTH && length <= MAX_WORD_LENGTH) {
                    // Convert token to lowercase
                    for (int i = 0; i < length; i++) {
                        token[i] = tolower(token[i]);
                    }
                    // Increment word frequency count
                    int index = -1;
                    for (int j = 0; j < num_words; j++) {
                        if (strcmp(word_frequencies[j].word, token) == 0) {
                            index = j;
                            break;
                        }
                    }
                    if (index != -1) {
                        word_frequencies[index].count++;
                    } else {
                        WordFrequency new_word = {token, 1};
                        word_frequencies[num_words++] = new_word;
                    }
                }
                token = strtok(NULL, " \t\n");
            }
        }
        free(line);
        fclose(file);
    }
}

// Calculate word frequencies and sort them
void calculate_word_frequencies() {
    // Initialize variables
    int i;
    for (i = 0; i < num_words; i++) {
        WordFrequency *word_frequency = &word_frequencies[i];
        word_frequency->count = log(word_frequency->count);
    }
}

// Sort word frequencies and print top words
void sort_word_frequencies() {
    // Initialize variables
    int i;
    for (i = 0; i < num_words; i++) {
        WordFrequency *word_frequency = &word_frequencies[i];
        word_frequency->count = exp(word_frequency->count);
    }
    qsort(word_frequencies, num_words, sizeof(WordFrequency), compare_word_frequencies);
}

// Print top words
void print_top_words() {
    // Initialize variables
    int i;
    for (i = 0; i < num_words; i++) {
        WordFrequency *word_frequency = &word_frequencies[i];
        printf("%s\t%d\n", word_frequency->word, word_frequency->count);
    }
}

// Cleanup
void cleanup() {
    free(word_frequencies);
}

// Comparison function for sorting word frequencies
int compare_word_frequencies(const void *a, const void *b) {
    WordFrequency *word_frequency1 = (WordFrequency *)a;
    WordFrequency *word_frequency2 = (WordFrequency *)b;
    return word_frequency2->count - word_frequency1->count;
}']

