    if (num_records < 0 || batch_size <= 0) {
        fprintf(stderr, "Error: Invalid input parameters\n");
        return NULL;
    }

    // Allocate memory for the array of data records
    DATA_RECORD* data_records = (DATA_RECORD*)malloc(num_records * sizeof(DATA_RECORD));
    if (!data_records) {
        fprintf(stderr, "Error: Failed to allocate memory for data records\n");
        return NULL;
    }

    // Initialize the array of data records
    for (int i = 0; i < num_records; i++) {
        data_records[i].data_source = -1;
        data_records[i].timestamp = -1;
        data_records[i].metadata = NULL;
    }

    return data_records;
}

