// Define a function to process raw data entries from a log file
int process_log_entries(const char* log_file, DATA_RECORD** data_records, int* num_records) {
    // Open the log file for reading
    FILE* fp = fopen(log_file, "r");
    if (!fp) {
        fprintf(stderr, "Error: Failed to open log file\n");
        return -1;
    }

    // Define regular expressions for source type, timestamp range, and metadata fields
    const char* source_type_regex = "^[0-9]+$";
    const char* timestamp_range_regex = "^[0-9]{4}-[0-9]{2}-[0-9]{2} [0-9]{2}:[0-9]{2}:[0-9]{2}$";
    const char* metadata_regex = "^[a-zA-Z0-9_]+$";

    // Initialize variables for tracking performance and errors
    int num_successful_transformations = 0;
    int num_failed_allocations = 0;
    int num_anomalies = 0;

    // Iterate over the log file, processing each entry in a thread-safe manner
    char* line = NULL;
    size_t len = 0;
    ssize_t read;
    while ((read = getline(&line, &len, fp)) != -1) {
        // Parse the log entry using regular expressions
        int source_type = -1;
        long timestamp = -1;
        char* metadata = NULL;
        if (sscanf(line, "%d %ld %s", &source_type, &timestamp, &metadata) != 3) {
            fprintf(stderr, "Error: Failed to parse log entry\n");
            continue;
        }

        // Validate the source type and timestamp range
        if (source_type < 0 || source_type > 1 || timestamp < TIMESTAMP_RANGE_MIN || timestamp > TIMESTAMP_RANGE_MAX) {
            fprintf(stderr, "Error: Invalid source type or timestamp range\n");
            continue;
        }

        // Validate the metadata fields
        if (metadata == NULL || strlen(metadata) == 0 || !regexec(metadata_regex, metadata)) {
            fprintf(stderr, "Error: Invalid metadata field\n");
            continue;
        }

        // Allocate memory for the data record
        DATA_RECORD* data_record = (DATA_RECORD*)malloc(sizeof(DATA_RECORD));
        if (!data_record) {
            fprintf(stderr, "Error: Failed to allocate memory for data record\n");
            num_failed_allocations++;
            continue;
        }

        // Initialize the data record
        data_record->data_source = source_type;
        data_record->timestamp = timestamp;
        data_record->metadata = metadata;

        // Add the data record to the array of data records
        if (*num_records >= 0) {
            (*data_records)[*num_records] = *data_record;
            (*num_records)++;
        } else {
            fprintf(stderr, "Error: Invalid number of data records\n");
            free(data_record);
            continue;
        }

        // Cache the anomalies and data processing details
        cache_anomalies(data_records, num_records);

        // Increment the counters for successful transformations and anomalies detected
        if (source_type == DATA_SOURCE_TYPE_1) {
            num_successful_transformations++;
        } else {
            num_anomalies++;
        }
    }

    // Close the log file
    fclose(fp);

    // Free any allocated memory for the data records
    if (*data_records) {
        free(*data_records);
    }

    // Print performance and error information
    printf("Performance: %d successful transformations, %d failed allocations, %d anomalies detected\n", num_successful_transformations, num_failed_allocations, num_anomalies);

    return 0;
}
