public static String processAndModifyFilename(String filename) {
    // Step 1: Count the number of vowels in the filename
    int numVowels = countVowels(filename);

    // Step 2: Append three random digits to the end of the filename if it contains '!'
    String modifiedFilename;
    if (filename.contains("!")) {
        modifiedFilename = filename + getRandomDigits(3);
    } else {
        modifiedFilename = filename + getRandomDigits(2);
    }

    // Step 3: Determine the file type based on whether the filename length is even or odd
    String fileType;
    if (modifiedFilename.length() % 2 == 0) {
        fileType = ".txt";
    } else {
        fileType = ".log";
    }

    // Step 4: Use sprintf and strcat to construct the new filename string
    String newFilename = String.format("%s%s", modifiedFilename, fileType);

    // Step 5: Return the newly constructed filename as a pointer to a dynamically allocated string
    return newFilename;
}

private static int countVowels(String filename) {
    int numVowels = 0;
    for (char c : filename.toCharArray()) {
        if (c == 'a' || c == 'e' || c == 'i' || c == 'o' || c == 'u') {
            numVowels++;
        }
    }
    return numVowels;
}

private static String getRandomDigits(int numDigits) {
    StringBuilder sb = new StringBuilder();
    for (int i = 0; i < numDigits; i++) {
        sb.append((int)(Math.random() * 10));
    }
    return sb.toString();
}
