    // Release the mutex for thread-safe operations
    pthread_mutex_unlock(&mutex);
}

// Function to deserialize the list of TIDB_ROW_RECORD structures from a binary format
void deserialize(FILE* file) {
    // Acquire the mutex for thread-safe operations
    pthread_mutex_lock(&mutex);

    // Read the number of records in the list from the file
    fread(&num_records, sizeof(size_t), 1, file);

    // Allocate memory for the list of records
    records = (TIDB_ROW_RECORD*) malloc(num_records * sizeof(TIDB_ROW_RECORD));
    if (!records) {
        printf("Error: Failed to allocate memory for the list of records\n");
        pthread_mutex_unlock(&mutex);
        return;
    }

    // Iterate over the list and read each record from the file
    for (size_t i = 0; i < num_records; i++) {
        TIDB_ROW_RECORD* record = &records[i];
        fread(record, sizeof(TIDB_ROW_RECORD), 1, file);
    }

    // Release the mutex for thread-safe operations
    pthread_mutex_unlock(&mutex);
}

// Function to integrate with an external database API for bulk insertion of records into a relational database
void integrate_with_database(void (*callback)(TIDB_ROW_RECORD*)) {
    // Acquire the mutex for thread-safe operations
    pthread_mutex_lock(&mutex);

    // Iterate over the list and call the callback function for each record
    for (size_t i = 0; i < num_records; i++) {
        TIDB_ROW_RECORD* record = &records[i];
        callback(record);
    }

    // Release the mutex for thread-safe operations
    pthread_mutex_unlock(&mutex);
}
