    for (int i = 0; i < size; i++) {
        list[i].row_id = i + 1;
        list[i].timestamp = time(NULL);
        for (int j = 0; j < 10; j++) {
            list[i].column_values[j] = NULL;
        }
    }
}

// Function to insert a new record into the list
void insert_record(tidb_row_record_t* record) {
    // Validate the COLUMN_VALUES before inserting the record
    if (!validate_column_values(record->column_values)) {
        return;
    }

    // Insert the record into the list using a custom allocator
    tidb_row_record_t* new_record = (tidb_row_record_t*)custom_alloc(sizeof(tidb_row_record_t));
    if (!new_record) {
        return;
    }
    memcpy(new_record, record, sizeof(tidb_row_record_t));
    new_record->timestamp = time(NULL);

