    log_insertion(new_record);

    // Add the new record to the end of the list
    if (list) {
        for (int i = 0; i < size; i++) {
            if (!list[i].column_values[j]) {
                list[i].column_values[j] = new_record->column_values[j];
                break;
            }
        }
    }
}

// Function to iterate over the list in both forward and reverse directions
