    if (direction == FORWARD) {
        return list;
    } else {
        return list + size - 1;
    }
}

// Function to serialize the list to a binary format for persistent storage
void serialize(FILE* fp) {
    // Implement a checksum mechanism to ensure data integrity during serialization and deserialization
    unsigned int checksum = 0;
    for (int i = 0; i < size; i++) {
        checksum += list[i].row_id + list[i].timestamp;
    }

    // Write the checksum to the file
    fwrite(&checksum, sizeof(unsigned int), 1, fp);

    // Write the list of TIDB_ROW_RECORD structures to the file
    for (int i = 0; i < size; i++) {
        fwrite(list[i].column_values, sizeof(char*), 10, fp);
        fwrite(&list[i].row_id, sizeof(long), 1, fp);
        fwrite(&list[i].timestamp, sizeof(time_t), 1, fp);
    }
}

// Function to deserialize the list from a binary format for persistent storage
void deserialize(FILE* fp) {
    // Implement a checksum mechanism to ensure data integrity during serialization and deserialization
    unsigned int checksum = 0;
    fread(&checksum, sizeof(unsigned int), 1, fp);

    // Read the list of TIDB_ROW_RECORD structures from the file
    for (int i = 0; i < size; i++) {
        fread(list[i].column_values, sizeof(char*), 10, fp);
        fread(&list[i].row_id, sizeof(long), 1, fp);
        fread(&list[i].timestamp, sizeof(time_t), 1, fp);
    }
}

// Function to integrate with an external database API for bulk insertion of records into a relational database
void insert_into_database(tidb_row_record_t* record) {
    // Handle any errors that arise during this process by retrying operations with exponential backoff
    while (1) {
        try {
            // Insert the record into the external database API
            insert_record(record);
            break;
        } catch (const std::exception& e) {
            // Log the error and retry after a delay
            printf("Error inserting record: %s\n", e.what());
            sleep(pow(2, i));
        }
    }
}
