void populate_crc_indication_pdu(uint16_t N, NFAPI_CRC_INDICATION_PDU_T **array) {
    // Allocate memory for the array of structures
    *array = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T) * N);
    if (*array == NULL) {
        printf("Memory allocation failed\n");
        return;
    }

    // Initialize the RX_UE_INFORMATION_TAG, RNTI, and CRCFLAG for each structure
    for (uint16_t i = 0; i < N; i++) {
        (*array)[i].RX_UE_INFORMATION_TAG = i + 1;
        (*array)[i].RNTI = rand() % 1000000000; // Generate a random RNTI value between 0 and 1 billion
        (*array)[i].CRCFLAG = (rand() % 2) ? true : false; // Set CRCFLAG to true or false randomly
    }
}

// Free the memory allocated for the array of structures when it is no longer needed
void free_crc_indication_pdu(NFAPI_CRC_INDICATION_PDU_T **array) {
    if (*array != NULL) {
        free(*array);
        *array = NULL;
    }
}
