// Define project structure
typedef struct {
    int PROJECT_ID;
    struct TEAM_STRUCTURE *team;
    time_t CURRENT_TIMESTAMP;
} PROJECT;

// Define team structure
typedef struct {
    int TEAM_ID;
    char *TEAM_NAME;
    int AVAILABILITY;
} TEAM_STRUCTURE;

// Define project registry
PROJECT *project_registry = NULL;
int num_projects = 0;
pthread_mutex_t project_lock = PTHREAD_MUTEX_INITIALIZER;

// Function to initialize and manage the registry of projects
void init_project_registry(PROJECT *projects, int num_projects) {
    // Lock the project registry mutex
    pthread_mutex_lock(&project_lock);

    // Initialize the project registry if it is not already initialized
    if (project_registry == NULL) {
        project_registry = malloc(sizeof(PROJECT) * num_projects);
        memset(project_registry, 0, sizeof(PROJECT) * num_projects);
    }

    // Update the number of projects in the registry
    this->num_projects = num_projects;

    // Copy the project information into the registry
    for (int i = 0; i < num_projects; i++) {
        project_registry[i] = projects[i];
    }

    // Unlock the project registry mutex
    pthread_mutex_unlock(&project_lock);
}

// Function to schedule a task for a specific project
void schedule_task(int project_id, int task_id) {
    // Lock the project registry mutex
    pthread_mutex_lock(&project_lock);

    // Find the project in the registry
    PROJECT *project = NULL;
    for (int i = 0; i < num_projects; i++) {
        if (project_registry[i].PROJECT_ID == project_id) {
            project = &project_registry[i];
            break;
        }
    }

    // If the project is not found, return an error
    if (project == NULL) {
        pthread_mutex_unlock(&project_lock);
        printf("Project %d not found\n", project_id);
        return;
    }

    // Schedule the task for the project
    project->CURRENT_TIMESTAMP = time(NULL);
    project->task_ids[project->num_tasks++] = task_id;

    // Unlock the project registry mutex
    pthread_mutex_unlock(&project_lock);
}

// Function to update the status of a task for a specific project
void update_task(int project_id, int task_id, int status) {
    // Lock the project registry mutex
    pthread_mutex_lock(&project_lock);

    // Find the project in the registry
    PROJECT *project = NULL;
    for (int i = 0; i < num_projects; i++) {
        if (project_registry[i].PROJECT_ID == project_id) {
            project = &project_registry[i];
            break;
        }
    }

    // If the project is not found, return an error
    if (project == NULL) {
        pthread_mutex_unlock(&project_lock);
        printf("Project %d not found\n", project_id);
        return;
    }

    // Update the status of the task for the project
    for (int i = 0; i < project->num_tasks; i++) {
        if (project->task_ids[i] == task_id) {
            project->task_statuses[i] = status;
            break;
        }
    }

    // Unlock the project registry mutex
    pthread_mutex_unlock(&project_lock);
}

// Function to handle overdue tasks for a specific project
void handle_overdue_tasks(int project_id) {
    // Lock the project registry mutex
    pthread_mutex_lock(&project_lock);

    // Find the project in the registry
    PROJECT *project = NULL;
    for (int i = 0; i < num_projects; i++) {
        if (project_registry[i].PROJECT_ID == project_id) {
            project = &project_registry[i];
            break;
        }
    }

    // If the project is not found, return an error
    if (project == NULL) {
        pthread_mutex_unlock(&project_lock);
        printf("Project %d not found\n", project_id);
        return;
    }

    // Handle overdue tasks for the project
    for (int i = 0; i < project->num_tasks; i++) {
        if (project->task_statuses[i] == OVERDUE) {
            // Reassign the task to a backup team
            int backup_team_id = get_backup_team(project->TEAM_ID);
            project->TEAM_ID = backup_team_id;
            project->task_statuses[i] = ASSIGNED;
        }
    }

    // Unlock the project registry mutex
    pthread_mutex_unlock(&project_lock);
}

// Function to get a backup team for a specific team
int get_backup_team(int team_id) {
    // Lock the team structure mutex
    pthread_mutex_lock(&team_lock);

    // Find the team in the registry
    TEAM_STRUCTURE *team = NULL;
    for (int i = 0; i < num_teams; i++) {
        if (team_registry[i].TEAM_ID == team_id) {
            team = &team_registry[i];
            break;
        }
    }

    // If the team is not found, return an error
    if (team == NULL) {
        pthread_mutex_unlock(&team_lock);
        printf("Team %d not found\n", team_id);
        return -1;
    }

    // Get a backup team for the team
    int backup_team_id = get_backup_team(team->TEAM_ID);
    if (backup_team_id == -1) {
        pthread_mutex_unlock(&team_lock);
        printf("No backup team found for team %d\n", team_id);
        return -1;
    }

    // Unlock the team structure mutex
    pthread_mutex_unlock(&team_lock);

    return backup_team_id;
}
