typedef struct {
    RESOURCE *resource;
    size_t size;
} POOL_ALLOCATOR;

// Define the cache for storing CUSTOM_OBJECT structures
static CUSTOM_OBJECT *cache = NULL;

// Define the pool allocator for managing RESOURCE instances
static POOL_ALLOCATOR *pool_allocator = NULL;

// Define the mutex for thread-safe operations on the cache
static pthread_mutex_t cache_mutex = PTHREAD_MUTEX_INITIALIZER;

// Initialize the cache and pool allocator
void init_cache() {
    // Allocate memory for the cache
    cache = (CUSTOM_OBJECT *)malloc(sizeof(CUSTOM_OBJECT) * CACHE_SIZE);
    if (!cache) {
        printf("Error: Failed to allocate memory for cache\n");
        return;
    }

    // Initialize the cache elements
    for (int i = 0; i < CACHE_SIZE; i++) {
        cache[i].OBJECT_ID = -1;
        cache[i].resource = NULL;
        cache[i].CURRENT_TIMESTAMP = 0;
    }

    // Allocate memory for the pool allocator
    pool_allocator = (POOL_ALLOCATOR *)malloc(sizeof(POOL_ALLOCATOR) * MAX_ELEMENTS);
    if (!pool_allocator) {
        printf("Error: Failed to allocate memory for pool allocator\n");
        return;
    }

    // Initialize the pool allocator elements
    for (int i = 0; i < MAX_ELEMENTS; i++) {
        pool_allocator[i].resource = NULL;
        pool_allocator[i].size = 0;
    }
}

// Add an element to the cache and update its validity timestamp
void add_element(int OBJECT_ID, RESOURCE *resource) {
    // Acquire the mutex for thread-safe operations on the cache
    pthread_mutex_lock(&cache_mutex);

    // Find an empty slot in the cache
    int i;
    for (i = 0; i < CACHE_SIZE; i++) {
        if (cache[i].OBJECT_ID == -1) {
            break;
        }
    }

    // If no empty slots found, evict the least recently used item
    if (i == CACHE_SIZE) {
        int min = 0;
        for (int j = 0; j < CACHE_SIZE; j++) {
            if (cache[j].CURRENT_TIMESTAMP < cache[min].CURRENT_TIMESTAMP) {
                min = j;
            }
        }
        i = min;
    }

    // Update the element in the cache and update its validity timestamp
    cache[i].OBJECT_ID = OBJECT_ID;
    cache[i].resource = resource;
    cache[i].CURRENT_TIMESTAMP = time(NULL);

    // Release the mutex for thread-safe operations on the cache
    pthread_mutex_unlock(&cache_mutex);
}

// Get an element from the cache by its ID
CUSTOM_OBJECT *get_element(int OBJECT_ID) {
    // Acquire the mutex for thread-safe operations on the cache
    pthread_mutex_lock(&cache_mutex);

    // Find the element in the cache
    int i;
    for (i = 0; i < CACHE_SIZE; i++) {
        if (cache[i].OBJECT_ID == OBJECT_ID) {
            break;
        }
    }

    // If the element is not found, return NULL
    if (i == CACHE_SIZE) {
        pthread_mutex_unlock(&cache_mutex);
        return NULL;
    }

    // Update the validity timestamp of the element
    cache[i].CURRENT_TIMESTAMP = time(NULL);

    // Release the mutex for thread-safe operations on the cache
    pthread_mutex_unlock(&cache_mutex);

    return &cache[i];
}

// Allocate a new RESOURCE instance from the pool allocator
RESOURCE *allocate_resource() {
    // Acquire the mutex for thread-safe operations on the pool allocator
    pthread_mutex_lock(&pool_allocator_mutex);

    // Find an empty slot in the pool allocator
    int i;
    for (i = 0; i < MAX_ELEMENTS; i++) {
        if (pool_allocator[i].resource == NULL) {
            break;
        }
    }

    // If no empty slots found, return NULL
    if (i == MAX_ELEMENTS) {
        pthread_mutex_unlock(&pool_allocator_mutex);
        return NULL;
    }

    // Allocate a new RESOURCE instance from the pool allocator
    RESOURCE *resource = (RESOURCE *)malloc(sizeof(RESOURCE));
    if (!resource) {
        pthread_mutex_unlock(&pool_allocator_mutex);
        return NULL;
    }

    // Update the pool allocator element with the new RESOURCE instance
    pool_allocator[i].resource = resource;
    pool_allocator[i].size = 0;

    // Release the mutex for thread-safe operations on the pool allocator
    pthread_mutex_unlock(&pool_allocator_mutex);

    return resource;
}

// Free a RESOURCE instance from the pool allocator
void free_resource(RESOURCE *resource) {
    // Acquire the mutex for thread-safe operations on the pool allocator
    pthread_mutex_lock(&pool_allocator_mutex);

    // Find the pool allocator element corresponding to the RESOURCE instance
    int i;
    for (i = 0; i < MAX_ELEMENTS; i++) {
        if (pool_allocator[i].resource == resource) {
            break;
        }
    }

    // If the element is not found, return
    if (i == MAX_ELEMENTS) {
        pthread_mutex_unlock(&pool_allocator_mutex);
        return;
    }

    // Free the RESOURCE instance from the pool allocator
    free(resource);
    pool_allocator[i].resource = NULL;
    pool_allocator[i].size = 0;

    // Release the mutex for thread-safe operations on the pool allocator
    pthread_mutex_unlock(&pool_allocator_mutex);
}

// Generate a list of NFAPI_CRC_INDICATION_PDU_T structures, each containing a valid RX_UE_INFORMATION_TAG and RNTI, along with a CRC_INDICATION_REL8_TAG and a randomly set CRCFLAG
void generate_crc_indication_pdu(int num_elements) {
    // Allocate memory for the list of NFAPI_CRC_INDICATION_PDU_T structures
    NFAPI_CRC_INDICATION_PDU_T *list = (NFAPI_CRC_INDICATION_PDU_T *)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T) * num_elements);
    if (!list) {
        printf("Error: Failed to allocate memory for list of NFAPI_CRC_INDICATION_PDU_T structures\n");
        return;
    }

    // Initialize the list of NFAPI_CRC_INDICATION_PDU_T structures
    for (int i = 0; i < num_elements; i++) {
        list[i].RX_UE_INFORMATION_TAG = -1;
        list[i].RNTI = -1;
        list[i].CRC_INDICATION_REL8_TAG = -1;
        list[i].CRCFLAG = 0;
    }

    // Simulate various levels of packet corruption in CRCFLAG values to reflect real-world network conditions
    for (int i = 0; i < num_elements; i++) {
        if (rand() % 10 == 0) {
            list[i].CRCFLAG = 1;
        } else {
            list[i].CRCFLAG = 0;
        }
    }

    // Free the memory allocated for the list of NFAPI_CRC_INDICATION_PDU_T structures
    free(list);
}

// Main function to generate up to 10,000 elements within a one-second time constraint, ensuring minimal memory usage and optimal execution time
int main() {
    // Initialize the cache and pool allocator
    init_cache();

    // Generate up to 10,000 elements within a one-second time constraint
    int num_elements = 0;
    clock_t start = clock();
    while (num_elements < MAX_ELEMENTS && clock() - start < CLOCKS_PER_SEC) {
        // Allocate a new RESOURCE instance from the pool allocator
        RESOURCE *resource = allocate_resource();
        if (!resource) {
            break;
        }

        // Generate a unique OBJECT_ID for the new element
        int OBJECT_ID = rand() % 10000 + 1;

        // Add an element to the cache and update its validity timestamp
        add_element(OBJECT_ID, resource);

        // Generate a list of NFAPI_CRC_INDICATION_PDU_T structures, each containing a valid RX_UE_INFORMATION_TAG and RNTI, along with a CRC_INDICATION_REL8_TAG and a randomly set CRCFLAG
        generate_crc_indication_pdu(100);

        // Free the RESOURCE instance from the pool allocator
        free_resource(resource);

        num_elements++;
    }

    return 0;
}
```
