import java.util.*;
import java.io.*;
import org.apache.commons.lang3.StringUtils;

public class KeyPhraseExtractor {
    public static List<String> extractKeyPhrases(List<File> documents) throws IOException {
        // Initialize a list to store the key phrases
        List<String> keyPhrases = new ArrayList<>();

        // Iterate over each document and extract the key phrases
        for (File document : documents) {
            // Read the contents of the document
            String text = FileUtils.readFileToString(document, StandardCharsets.UTF_8);

            // Tokenize the text into individual words
            List<String> tokens = Arrays.asList(text.split("\\W+"));

            // Remove stop words and short phrases from the token list
            tokens = tokens.stream()
                    .filter(token -> !StopWords.contains(token) && token.length() > 2)
                    .collect(Collectors.toList());

            // Create a set to store unique key phrases
            Set<String> uniquePhrases = new HashSet<>();

            // Iterate over each token and check if it appears exactly once in all documents
            for (String token : tokens) {
                int count = 0;
                for (File document2 : documents) {
                    String text2 = FileUtils.readFileToString(document2, StandardCharsets.UTF_8);
                    if (text2.contains(token)) {
                        count++;
                    }
                }
                if (count == 1) {
                    uniquePhrases.add(token);
                }
            }

            // Add the unique key phrases to the list of key phrases
            keyPhrases.addAll(uniquePhrases);
        }

        return keyPhrases;
    }
}
