#include <iostream>
#include <fstream>
#include <string>
#include <vector>
#include <map>
#include <algorithm>
#include <cstdlib>
#include <ctime>
#include <cmath>
#include <sys/stat.h>
#include <dirent.h>
#include <unistd.h>

using namespace std;

// Command line options
const string HELP_OPTION = "--help";
const string FILE_EXTENSION_OPTION = "-f";
const string OUTPUT_FILE_OPTION = "-o";

// Default values for command line options
const string DEFAULT_OUTPUT_FILE = "report.txt";
const string DEFAULT_FILE_EXTENSION = "";

int main(int argc, char* argv[]) {
    // Check if the user has specified any command line options
    if (argc == 1) {
        cout << "No command line options specified." << endl;
        return 0;
    }

    // Parse the command line options
    string directoryPath = "";
    string fileExtension = DEFAULT_FILE_EXTENSION;
    string outputFile = DEFAULT_OUTPUT_FILE;
    for (int i = 1; i < argc; i++) {
        if (argv[i] == HELP_OPTION) {
            cout << "Usage: " << argv[0] << " [options]" << endl;
            cout << "Options:" << endl;
            cout << "\t" << FILE_EXTENSION_OPTION << "<file extension>\tFilter files by extension (e.g., -f txt)" << endl;
            cout << "\t" << OUTPUT_FILE_OPTION << "<output file>\t\tSpecify output file (default: " << DEFAULT_OUTPUT_FILE << ")" << endl;
            return 0;
        } else if (argv[i] == FILE_EXTENSION_OPTION) {
            i++;
            if (i < argc) {
                fileExtension = argv[i];
            } else {
                cout << "Invalid command line option: " << FILE_EXTENSION_OPTION << endl;
                return 1;
            }
        } else if (argv[i] == OUTPUT_FILE_OPTION) {
            i++;
            if (i < argc) {
                outputFile = argv[i];
            } else {
                cout << "Invalid command line option: " << OUTPUT_FILE_OPTION << endl;
                return 1;
            }
        } else {
            directoryPath = argv[i];
        }
    }

    // Check if the user has specified a valid directory path
    struct stat info;
    if (stat(directoryPath.c_str(), &info) != 0 || !S_ISDIR(info.st_mode)) {
        cout << "Invalid directory path: " << directoryPath << endl;
        return 1;
    }

    // Open the output file
    ofstream outFile(outputFile);
    if (!outFile) {
        cout << "Error opening output file: " << outputFile << endl;
        return 1;
    }

    // Read the directory and generate a report
    vector<string> files = getFilesInDirectory(directoryPath, fileExtension);
    map<string, int> wordCounts;
    for (string file : files) {
        ifstream inFile(file);
        string line;
        while (getline(inFile, line)) {
            vector<string> words = splitString(line, " ");
            for (string word : words) {
                wordCounts[word]++;
            }
        }
    }

    // Generate the report
    outFile << "Total number of words: " << wordCounts.size() << endl;
    for (auto it = wordCounts.begin(); it != wordCounts.end(); ++it) {
        outFile << "\t" << it->first << ": " << it->second << endl;
    }

    // Close the output file
    outFile.close();

    return 0;
}

vector<string> getFilesInDirectory(const string& directoryPath, const string& fileExtension) {
    vector<string> files;
    DIR* dir = opendir(directoryPath.c_str());
    if (dir == NULL) {
        return files;
    }

    struct dirent* entry;
    while ((entry = readdir(dir)) != NULL) {
        string fileName = entry->d_name;
        if (fileExtension.empty() || hasFileExtension(fileName, fileExtension)) {
            files.push_back(directoryPath + "/" + fileName);
        }
    }

    closedir(dir);
    return files;
}

bool hasFileExtension(const string& fileName, const string& fileExtension) {
    size_t extensionIndex = fileName.find_last_of(".");
    if (extensionIndex == string::npos) {
        return false;
    }

    return fileName.substr(extensionIndex + 1) == fileExtension;
}

vector<string> splitString(const string& str, const string& delimiter) {
    vector<string> tokens;
    size_t prev = 0, pos = 0;
    while ((pos = str.find(delimiter, prev)) != string::npos) {
        tokens.push_back(str.substr(prev, pos - prev));
        prev = pos + 1;
    }

    if (prev < str.length()) {
        tokens.push_back(str.substr(prev));
    }

    return tokens;
}']

