    // Allocate memory for the array of DATA_RECORD structures
    DATA_RECORD** data_records = (DATA_RECORD**)malloc(sizeof(DATA_RECORD*) * num_records);
    if (!data_records) {
        fprintf(stderr, "Error: Failed to allocate memory for the array of DATA_RECORD structures\n");
        return NULL;
    }

    // Initialize each element in the array with a new DATA_RECORD structure
    for (int i = 0; i < num_records; i++) {
        data_records[i] = (DATA_RECORD*)malloc(sizeof(DATA_RECORD));
        if (!data_records[i]) {
            fprintf(stderr, "Error: Failed to allocate memory for the DATA_RECORD structure\n");
            return NULL;
        }
