// Define structure for user profile
typedef struct {
    int USER_ID;
    CONFIGURATION_STRUCTURE *config;
    time_t CURRENT_TIMESTAMP;
} USER_PROFILE;

// Define mutex and condition variable for synchronization
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
pthread_cond_t cond = PTHREAD_COND_INITIALIZER;

// Function to manage registry of user profiles
void manage_user_profiles(USER_PROFILE *profile) {
    // Acquire mutex for critical section
    pthread_mutex_lock(&mutex);

    // Check if profile exists in registry
    if (profile->USER_ID == 0) {
        // Profile does not exist, create new one
        USER_PROFILE *new_profile = malloc(sizeof(USER_PROFILE));
        new_profile->USER_ID = profile->USER_ID;
        new_profile->config = profile->config;
        new_profile->CURRENT_TIMESTAMP = profile->CURRENT_TIMESTAMP;
        // Add new profile to registry
        pthread_mutex_unlock(&mutex);
        return;
    } else {
        // Profile exists, update existing one
        USER_PROFILE *existing_profile = malloc(sizeof(USER_PROFILE));
        existing_profile->USER_ID = profile->USER_ID;
        existing_profile->config = profile->config;
        existing_profile->CURRENT_TIMESTAMP = profile->CURRENT_TIMESTAMP;
        // Update existing profile in registry
        pthread_mutex_unlock(&mutex);
        return;
    }
}

// Function to update user settings
void update_user_settings(USER_PROFILE *profile, CONFIGURATION_STRUCTURE *config) {
    // Acquire mutex for critical section
    pthread_mutex_lock(&mutex);

    // Check if profile exists in registry
    if (profile->USER_ID == 0) {
        // Profile does not exist, create new one
        USER_PROFILE *new_profile = malloc(sizeof(USER_PROFILE));
        new_profile->USER_ID = profile->USER_ID;
        new_profile->config = config;
        new_profile->CURRENT_TIMESTAMP = time(NULL);
        // Add new profile to registry
        pthread_mutex_unlock(&mutex);
        return;
    } else {
        // Profile exists, update existing one
        USER_PROFILE *existing_profile = malloc(sizeof(USER_PROFILE));
        existing_profile->USER_ID = profile->USER_ID;
        existing_profile->config = config;
        existing_profile->CURRENT_TIMESTAMP = time(NULL);
        // Update existing profile in registry
        pthread_mutex_unlock(&mutex);
        return;
    }
}

