import java.sql.*;
import java.util.ArrayList;
import java.util.List;

public class SalesReport {
    public static void main(String[] args) throws SQLException {
        // Parse command line arguments
        String databaseUrl = null;
        String queryString = null;
        String outputFile = null;
        for (int i = 0; i < args.length; i++) {
            switch (args[i]) {
                case "--help":
                    printUsage();
                    return;
                case "-d":
                    databaseUrl = args[++i];
                    break;
                case "-q":
                    queryString = args[++i];
                    break;
                case "-o":
                    outputFile = args[++i];
                    break;
            }
        }

        // Validate command line arguments
        if (databaseUrl == null || queryString == null || outputFile == null) {
            System.err.println("Missing required command line argument(s).");
            printUsage();
            return;
        }

        // Connect to the database and execute the query
        Connection conn = DriverManager.getConnection(databaseUrl);
        Statement stmt = conn.createStatement();
        ResultSet rs = stmt.executeQuery(queryString);

        // Process the result set and generate the report
        List<SalesTransaction> transactions = new ArrayList<>();
        while (rs.next()) {
            SalesTransaction transaction = new SalesTransaction();
            transaction.setId(rs.getInt("id"));
            transaction.setDate(rs.getDate("date"));
            transaction.setCustomer(rs.getString("customer"));
            transaction.setProduct(rs.getString("product"));
            transaction.setQuantity(rs.getInt("quantity"));
            transaction.setPrice(rs.getDouble("price"));
            transactions.add(transaction);
        }

        // Generate the report and write it to the output file
        SalesReportWriter writer = new SalesReportWriter();
        writer.writeReport(transactions, outputFile);

        // Close the database connection
        conn.close();
    }

    private static void printUsage() {
        System.out.println("Usage: java SalesReport -d <database_url> -q <query_string> -o <output_file>");
        System.out.println("  --help                   Display this usage information.");
        System.out.println("  -d <database_url>        Database connection URL.");
        System.out.println("  -q <query_string>        SQL query to fetch data.");
        System.out.println("  -o <output_file>         Output file for the report.");
    }
}

class SalesTransaction {
    private int id;
    private Date date;
    private String customer;
    private String product;
    private int quantity;
    private double price;

    // Getters and setters
}

class SalesReportWriter {
    public void writeReport(List<SalesTransaction> transactions, String outputFile) throws IOException {
        try (BufferedWriter writer = new BufferedWriter(new FileWriter(outputFile))) {
            for (SalesTransaction transaction : transactions) {
                writer.write(transaction.getId() + ",");
                writer.write(transaction.getDate().toString() + ",");
                writer.write(transaction.getCustomer() + ",");
                writer.write(transaction.getProduct() + ",");
                writer.write(Integer.toString(transaction.getQuantity()) + ",");
                writer.write(Double.toString(transaction.getPrice()));
                writer.newLine();
            }
        }
    }
}']

