#include <stdlib.h>
#include <stdio.h>
#include <string.h>
#include <pthread.h>

// Define the structure for network interface statistics
typedef struct NetworkInterfaceStats {
    char *interface_name;
    double packet_loss;
    double throughput;
    double latency;
} NetworkInterfaceStats;

// Define the dynamic array for storing network interface statistics
typedef struct NetworkInterfaceStatsArray {
    int size;
    int capacity;
    NetworkInterfaceStats *stats;
} NetworkInterfaceStatsArray;

// Initialize a new network interface statistics array with a given capacity
NetworkInterfaceStatsArray *init_network_interface_stats_array(int capacity) {
    NetworkInterfaceStatsArray *array = malloc(sizeof(NetworkInterfaceStatsArray));
    if (!array) {
        fprintf(stderr, "Failed to allocate memory for network interface statistics array\n");
        return NULL;
    }
    array->size = 0;
    array->capacity = capacity;
    array->stats = malloc(sizeof(NetworkInterfaceStats) * capacity);
    if (!array->stats) {
        fprintf(stderr, "Failed to allocate memory for network interface statistics\n");
        free(array);
        return NULL;
    }
    return array;
}

// Add a new network interface statistics entry to the array
int add_network_interface_stats(NetworkInterfaceStatsArray *array, const char *interface_name, double packet_loss, double throughput, double latency) {
    if (!array || !interface_name) {
        fprintf(stderr, "Invalid input parameters\n");
        return -1;
    }
    // Check if the array is full
    if (array->size == array->capacity) {
        fprintf(stderr, "Network interface statistics array is full\n");
        return -1;
    }
    // Add a new entry to the array
    NetworkInterfaceStats *stats = &array->stats[array->size++];
    stats->interface_name = strdup(interface_name);
    stats->packet_loss = packet_loss;
    stats->throughput = throughput;
    stats->latency = latency;
    return 0;
}

// Update an existing network interface statistics entry in the array
int update_network_interface_stats(NetworkInterfaceStatsArray *array, const char *interface_name, double packet_loss, double throughput, double latency) {
    if (!array || !interface_name) {
        fprintf(stderr, "Invalid input parameters\n");
        return -1;
    }
    // Find the entry in the array
    for (int i = 0; i < array->size; i++) {
        NetworkInterfaceStats *stats = &array->stats[i];
        if (!strcmp(stats->interface_name, interface_name)) {
            stats->packet_loss = packet_loss;
            stats->throughput = throughput;
            stats->latency = latency;
            return 0;
        }
    }
    // If the entry is not found, add a new one
    return add_network_interface_stats(array, interface_name, packet_loss, throughput, latency);
}

// Retrieve aggregated statistics for all interfaces in the array
void get_aggregate_network_interface_stats(NetworkInterfaceStatsArray *array, double *packet_loss, double *throughput, double *latency) {
    if (!array || !packet_loss || !throughput || !latency) {
        fprintf(stderr, "Invalid input parameters\n");
        return;
    }
    // Initialize the aggregated statistics to zero
    *packet_loss = 0.0;
    *throughput = 0.0;
    *latency = 0.0;
    // Iterate over all entries in the array and calculate the aggregated statistics
    for (int i = 0; i < array->size; i++) {
        NetworkInterfaceStats *stats = &array->stats[i];
        *packet_loss += stats->packet_loss;
        *throughput += stats->throughput;
        *latency += stats->latency;
    }
}

// Free the memory allocated for the network interface statistics array
void free_network_interface_stats_array(NetworkInterfaceStatsArray *array) {
    if (!array) {
        return;
    }
    // Free the memory allocated for each entry in the array
    for (int i = 0; i < array->size; i++) {
        NetworkInterfaceStats *stats = &array->stats[i];
        free(stats->interface_name);
    }
    // Free the memory allocated for the array itself
    free(array->stats);
    free(array);
}
