    // Initialize the mutex for thread-safe operations
    pthread_mutex_init(&registry->mutex, NULL);
}

// Function to add a new project to the registry
void add_project(ProjectRegistry* registry, Project* project) {
    // Acquire the lock on the mutex
    pthread_mutex_lock(&registry->mutex);

    // Check if there is enough space in the array for the new project
    if (registry->num_projects >= 10) {
        printf("Error: No more space available in the project registry\n");
        pthread_mutex_unlock(&registry->mutex);
        return;
    }

    // Add the new project to the array
    registry->projects[registry->num_projects++] = project;

    // Release the lock on the mutex
    pthread_mutex_unlock(&registry->mutex);
}

// Function to remove a project from the registry
void remove_project(ProjectRegistry* registry, uint32_t id) {
    // Acquire the lock on the mutex
    pthread_mutex_lock(&registry->mutex);

    // Find the index of the project in the array
    size_t i;
    for (i = 0; i < registry->num_projects; i++) {
        if (registry->projects[i]->id == id) {
            break;
        }
    }

    // Check if the project was found in the array
    if (i >= registry->num_projects) {
        printf("Error: Project with ID %d not found\n", id);
        pthread_mutex_unlock(&registry->mutex);
        return;
    }

    // Remove the project from the array
    for (size_t j = i; j < registry->num_projects - 1; j++) {
        registry->projects[j] = registry->projects[j + 1];
    }
    registry->num_projects--;

    // Release the lock on the mutex
    pthread_mutex_unlock(&registry->mutex);
}

// Function to update a project in the registry
void update_project(ProjectRegistry* registry, Project* project) {
    // Acquire the lock on the mutex
    pthread_mutex_lock(&registry->mutex);

    // Find the index of the project in the array
    size_t i;
    for (i = 0; i < registry->num_projects; i++) {
        if (registry->projects[i]->id == project->id) {
            break;
        }
    }

    // Check if the project was found in the array
    if (i >= registry->num_projects) {
        printf("Error: Project with ID %d not found\n", project->id);
        pthread_mutex_unlock(&registry->mutex);
        return;
    }

    // Update the project in the array
    registry->projects[i] = project;

    // Release the lock on the mutex
    pthread_mutex_unlock(&registry->mutex);
}

// Function to retrieve a project from the registry
Project* get_project(ProjectRegistry* registry, uint32_t id) {
    // Acquire the lock on the mutex
    pthread_mutex_lock(&registry->mutex);

    // Find the index of the project in the array
    size_t i;
    for (i = 0; i < registry->num_projects; i++) {
        if (registry->projects[i]->id == id) {
            break;
        }
    }

    // Check if the project was found in the array
    if (i >= registry->num_projects) {
        printf("Error: Project with ID %d not found\n", id);
        pthread_mutex_unlock(&registry->mutex);
        return NULL;
    }

    // Return a copy of the project
    Project* result = (Project*)malloc(sizeof(Project));
    memcpy(result, registry->projects[i], sizeof(Project));

    // Release the lock on the mutex
    pthread_mutex_unlock(&registry->mutex);

    return result;
}

// Function to retrieve all projects from the registry
void get_all_projects(ProjectRegistry* registry, Project*** projects) {
    // Acquire the lock on the mutex
    pthread_mutex_lock(&registry->mutex);

    // Allocate memory for the array of projects
    *projects = (Project**)malloc(sizeof(Project*) * registry->num_projects);

    // Copy the projects from the registry to the array
    size_t i;
    for (i = 0; i < registry->num_projects; i++) {
        (*projects)[i] = (Project*)malloc(sizeof(Project));
        memcpy((*projects)[i], registry->projects[i], sizeof(Project));
    }

    // Release the lock on the mutex
    pthread_mutex_unlock(&registry->mutex);
}

// Function to retrieve all projects from the registry that are dependent on a given project
void get_dependent_projects(ProjectRegistry* registry, uint32_t id, Project*** projects) {
    // Acquire the lock on the mutex
    pthread_mutex_lock(&registry->mutex);

    // Allocate memory for the array of projects
    *projects = (Project**)malloc(sizeof(Project*) * registry->num_projects);

    // Copy the dependent projects from the registry to the array
    size_t i;
    for (i = 0; i < registry->num_projects; i++) {
        if (registry->projects[i]->dependent_project_id == id) {
            (*projects)[i] = (Project*)malloc(sizeof(Project));
            memcpy((*projects)[i], registry->projects[i], sizeof(Project));
        }
    }

    // Release the lock on the mutex
    pthread_mutex_unlock(&registry->mutex);
}

// Function to retrieve all projects from the registry that are required by a given project
void get_required_projects(ProjectRegistry* registry, uint32_t id, Project*** projects) {
    // Acquire the lock on the mutex
    pthread_mutex_lock(&registry->mutex);

    // Allocate memory for the array of projects
    *projects = (Project**)malloc(sizeof(Project*) * registry->num_projects);

    // Copy the required projects from the registry to the array
    size_t i;
    for (i = 0; i < registry->num_projects; i++) {
        if (registry->projects[i]->required_project_id == id) {
            (*projects)[i] = (Project*)malloc(sizeof(Project));
            memcpy((*projects)[i], registry->projects[i], sizeof(Project));
        }
    }

    // Release the lock on the mutex
    pthread_mutex_unlock(&registry->mutex);
}
