```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <ctype.h>
#include <unistd.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <errno.h>

// Define constants for command line options
#define OPT_HELP 1
#define OPT_KEYWORDS_FILE 2
#define OPT_OUTPUT_FILE 3

// Define a structure to represent a keyword and its associated context
typedef struct {
    char *keyword;
    int line_number;
    char *context;
} KeywordContext;

// Define a function to read the keywords file and populate an array of KeywordContext structures
void read_keywords(char *filename, KeywordContext **keywords) {
    FILE *file = fopen(filename, "r");
    if (file == NULL) {
        printf("Error: unable to open keywords file %s\n", filename);
        exit(1);
    }

    // Read the keywords from the file and populate an array of KeywordContext structures
    char line[256];
    while (fgets(line, sizeof(line), file) != NULL) {
        char *keyword = strtok(line, " \t\n");
        if (keyword == NULL) continue;

        // Create a new KeywordContext structure and populate it with the keyword and its associated context
        KeywordContext *context = malloc(sizeof(KeywordContext));
        context->keyword = strdup(keyword);
        context->line_number = 0;
        context->context = NULL;

        // Add the new KeywordContext structure to the array of keywords
        (*keywords) = realloc((*keywords), sizeof(KeywordContext *) * ((*num_keywords) + 1));
        (*keywords)[(*num_keywords)] = context;
        (*num_keywords)++;
    }

    fclose(file);
}

// Define a function to process a single log file and extract keywords
void process_log_file(char *filename, KeywordContext **keywords, int num_keywords) {
    FILE *file = fopen(filename, "r");
    if (file == NULL) {
        printf("Error: unable to open log file %s\n", filename);
        exit(1);
    }

    // Read the contents of the log file and extract keywords
    char line[256];
    while (fgets(line, sizeof(line), file) != NULL) {
        for (int i = 0; i < num_keywords; i++) {
            KeywordContext *context = (*keywords)[i];
            if (strstr(line, context->keyword)) {
                // Increment the line number of the keyword and add its associated context to the array
                context->line_number++;
                char *new_context = realloc(context->context, sizeof(char *) * ((*num_contexts) + 1));
                new_context[(*num_contexts)] = strdup(line);
                context->context = new_context;
            }
        }
    }

    fclose(file);
}

// Define a function to generate the summary report for the extracted keywords
void generate_report(KeywordContext **keywords, int num_keywords) {
    // Print the header of the report
    printf("Summary Report\n");
    printf("-------------\n");

    // Print the frequency of each keyword and its associated context
    for (int i = 0; i < num_keywords; i++) {
        KeywordContext *context = (*keywords)[i];
        printf("%s: %d\n", context->keyword, context->line_number);
        for (int j = 0; j < context->line_number; j++) {
            printf("    %s\n", context->context[j]);
        }
    }
}

// Define a function to handle command line options and process the log files
void handle_options(int argc, char **argv) {
    // Initialize variables for command line options and keywords file
    int opt;
    char *keywords_file = NULL;
    char *output_file = NULL;
    int num_keywords = 0;
    KeywordContext **keywords = NULL;

    // Parse the command line options
    while ((opt = getopt(argc, argv, "hk:o:")) != -1) {
        switch (opt) {
            case OPT_HELP:
                printf("Usage: %s [-h] [-k <keywords_file>] [-o <output_file>]\n", argv[0]);
                exit(0);
            case OPT_KEYWORDS_FILE:
                keywords_file = optarg;
                break;
            case OPT_OUTPUT_FILE:
                output_file = optarg;
                break;
        }
    }

    // Read the keywords file and populate an array of KeywordContext structures
    if (keywords_file != NULL) {
        read_keywords(keywords_file, &keywords);
        num_keywords = (*num_keywords);
    }

    // Process each log file specified on the command line and extract keywords
    for (int i = optind; i < argc; i++) {
        process_log_file(argv[i], &keywords, &num_keywords);
    }

    // Generate the summary report for the extracted keywords
    generate_report(&keywords, &num_keywords);
}

int main(int argc, char **argv) {
    handle_options(argc, argv);
    return 0;
}
