#define REGEX_CURRENCY "^[A-Z]{3}$"
#define REGEX_TIMESTAMP "^\\d{4}-\\d{2}-\\d{2} \\d{2}:\\d{2}:\\d{2}\\.\\d{6}$"

// Define the pre-trained machine learning model file path
