    private ConcurrentHashMap<String, Transaction> transactions = new ConcurrentHashMap<>();

    public void processTransactions(List<Transaction> transactions) {
        for (Transaction transaction : transactions) {
            String key = getKey(transaction);
            Transaction existingTransaction = transactions.get(key);
            if (existingTransaction != null) {
                // Check for discrepancies between expected and actual amounts
                double expectedAmount = existingTransaction.getExpectedAmount();
                double actualAmount = transaction.getActualAmount();
                if (Math.abs(expectedAmount - actualAmount) > 0.01) {
                    Discrepancy discrepancy = new Discrepancy(key, expectedAmount, actualAmount);
                    discrepancies.put(discrepancy.getKey(), discrepancy);
                }
            } else {
                // Add transaction to the map
                transactions.put(key, transaction);
            }
        }
    }

