// Define a struct to represent a TASK entity
typedef struct {
    int task_id;
    void* resource_pool;
    long execution_timestamp;
} Task;

// Define a struct to represent a RESOURCE_POOL entity
typedef struct {
    int resource_id;
    int available_resources;
} ResourcePool;

// Define a hash table to store the registry of TASK entities
static pthread_mutex_t task_registry_lock = PTHREAD_MUTEX_INITIALIZER;
static Task* task_registry = NULL;

// Function to initialize and manage the registry of TASK entities
void init_task_registry(int num_tasks) {
    // Allocate memory for the hash table
    task_registry = (Task*)malloc(num_tasks * sizeof(Task));
    if (!task_registry) {
        printf("Error: Failed to allocate memory for task registry\n");
        exit(1);
    }

    // Initialize the hash table with NULL values
    for (int i = 0; i < num_tasks; i++) {
        task_registry[i].task_id = -1;
        task_registry[i].resource_pool = NULL;
        task_registry[i].execution_timestamp = -1;
    }
}

// Function to schedule a TASK for execution
void schedule_task(int task_id, void* resource_pool) {
    // Acquire the lock on the hash table
    pthread_mutex_lock(&task_registry_lock);

    // Find the corresponding TASK entity in the hash table
    Task* task = NULL;
    for (int i = 0; i < num_tasks; i++) {
        if (task_registry[i].task_id == task_id) {
            task = &task_registry[i];
            break;
        }
    }

    // If the TASK entity is not found, create a new one
    if (!task) {
        task = (Task*)malloc(sizeof(Task));
        task->task_id = task_id;
        task->resource_pool = resource_pool;
        task->execution_timestamp = -1;
        task_registry[i] = *task;
    }

    // Update the execution timestamp for the TASK entity
    task->execution_timestamp = get_current_time();

    // Release the lock on the hash table
    pthread_mutex_unlock(&task_registry_lock);
}

// Function to update the dependencies of a TASK
void update_dependencies(int task_id, int* dependency_ids) {
    // Acquire the lock on the hash table
    pthread_mutex_lock(&task_registry_lock);

    // Find the corresponding TASK entity in the hash table
    Task* task = NULL;
    for (int i = 0; i < num_tasks; i++) {
        if (task_registry[i].task_id == task_id) {
            task = &task_registry[i];
            break;
        }
    }

    // If the TASK entity is not found, return
    if (!task) {
        pthread_mutex_unlock(&task_registry_lock);
        return;
    }

    // Update the dependencies of the TASK entity
    task->dependency_ids = dependency_ids;

    // Release the lock on the hash table
    pthread_mutex_unlock(&task_registry_lock);
}

// Function to allocate resources for a TASK
void allocate_resources(int task_id, int num_resources) {
    // Acquire the lock on the hash table
    pthread_mutex_lock(&task_registry_lock);

    // Find the corresponding RESOURCE_POOL entity in the hash table
    ResourcePool* resource_pool = NULL;
    for (int i = 0; i < num_tasks; i++) {
        if (task_registry[i].resource_id == task_id) {
            resource_pool = &task_registry[i];
            break;
        }
    }

    // If the RESOURCE_POOL entity is not found, return
    if (!resource_pool) {
        pthread_mutex_unlock(&task_registry_lock);
        return;
    }

    // Allocate resources for the TASK
    resource_pool->available_resources -= num_resources;

    // Release the lock on the hash table
    pthread_mutex_unlock(&task_registry_lock);
}

// Function to deallocate resources for a TASK
void deallocate_resources(int task_id, int num_resources) {
    // Acquire the lock on the hash table
    pthread_mutex_lock(&task_registry_lock);

    // Find the corresponding RESOURCE_POOL entity in the hash table
    ResourcePool* resource_pool = NULL;
    for (int i = 0; i < num_tasks; i++) {
        if (task_registry[i].resource_id == task_id) {
            resource_pool = &task_registry[i];
            break;
        }
    }

    // If the RESOURCE_POOL entity is not found, return
    if (!resource_pool) {
        pthread_mutex_unlock(&task_registry_lock);
        return;
    }

    // Deallocate resources for the TASK
    resource_pool->available_resources += num_resources;

    // Release the lock on the hash table
    pthread_mutex_unlock(&task_registry_lock);
}
