#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <errno.h>
#include <pthread.h>

#define MAX_INPUT_FILES 100
#define MAX_WORDS 10000
#define MAX_WORD_LENGTH 32
#define MAX_FILENAME_LENGTH 256

typedef struct {
    char* filename;
    int fd;
} input_file_t;

typedef struct {
    char* word;
    int count;
} word_count_t;

void print_usage() {
    printf("Usage: text-analyzer [options] <input files>\n");
    printf("Options:\n");
    printf("\t--help\t\tPrint usage information\n");
    printf("\t-s\t\tSummarize text content by providing word frequency statistics\n");
    printf("\t-l\t\tList unique words from the input files, but limit output to 100 unique words per file\n");
    printf("\t-w\t\tWord count each input file individually and print total word count, excluding words shorter than three characters\n");
    printf("\t-o <filename>\tRedirect output to the specified filename\n");
}

void summarize_text(input_file_t* files, int num_files) {
    // Calculate word frequency statistics
    int total_words = 0;
    int top_ten[10];
    for (int i = 0; i < num_files; i++) {
        char buffer[MAX_WORD_LENGTH];
        while (read(files[i].fd, buffer, MAX_WORD_LENGTH) > 0) {
            total_words++;
            if (total_words <= 10) {
                top_ten[total_words - 1] = atoi(buffer);
            }
        }
    }

    // Print word frequency statistics
    printf("Top 10 most frequent words:\n");
    for (int i = 0; i < 10; i++) {
        printf("%d. %s\n", i + 1, top_ten[i]);
    }
}

void list_unique_words(input_file_t* files, int num_files) {
    // Calculate unique words
    char** unique_words = malloc(sizeof(char*) * MAX_WORDS);
    int unique_word_count = 0;
    for (int i = 0; i < num_files; i++) {
        char buffer[MAX_WORD_LENGTH];
        while (read(files[i].fd, buffer, MAX_WORD_LENGTH) > 0) {
            int word_length = strlen(buffer);
            if (word_length >= 3) {
                bool found = false;
                for (int j = 0; j < unique_word_count; j++) {
                    if (strcmp(unique_words[j], buffer) == 0) {
                        found = true;
                        break;
                    }
                }
                if (!found) {
                    unique_words[unique_word_count++] = strdup(buffer);
                }
            }
        }
    }

    // Print unique words
    printf("Unique words:\n");
    for (int i = 0; i < unique_word_count; i++) {
        printf("%s\n", unique_words[i]);
    }
}

void word_count(input_file_t* files, int num_files) {
    // Calculate total word count
    int total_word_count = 0;
    for (int i = 0; i < num_files; i++) {
        char buffer[MAX_WORD_LENGTH];
        while (read(files[i].fd, buffer, MAX_WORD_LENGTH) > 0) {
            int word_length = strlen(buffer);
            if (word_length >= 3) {
                total_word_count++;
            }
        }
    }

    // Print total word count
    printf("Total word count: %d\n", total_word_count);
}

void redirect_output(input_file_t* files, int num_files, char* filename) {
    // Open output file
    int fd = open(filename, O_WRONLY | O_CREAT | O_TRUNC, 0644);
    if (fd == -1) {
        perror("Error opening output file");
        exit(EXIT_FAILURE);
    }

    // Write to output file
    for (int i = 0; i < num_files; i++) {
        char buffer[MAX_WORD_LENGTH];
        while (read(files[i].fd, buffer, MAX_WORD_LENGTH) > 0) {
            write(fd, buffer, strlen(buffer));
        }
    }

    // Close output file
    close(fd);
}

int main(int argc, char* argv[]) {
    if (argc < 2) {
        print_usage();
        exit(EXIT_FAILURE);
    }

    input_file_t files[MAX_INPUT_FILES];
    int num_files = 0;
    for (int i = 1; i < argc; i++) {
        if (strcmp(argv[i], "--help") == 0) {
            print_usage();
            exit(EXIT_SUCCESS);
        } else if (strcmp(argv[i], "-s") == 0) {
            summarize_text(files, num_files);
        } else if (strcmp(argv[i], "-l") == 0) {
            list_unique_words(files, num_files);
        } else if (strcmp(argv[i], "-w") == 0) {
            word_count(files, num_files);
        } else if (strcmp(argv[i], "-o") == 0 && i + 1 < argc) {
            redirect_output(files, num_files, argv[i + 1]);
        } else {
            files[num_files].filename = argv[i];
            files[num_files].fd = open(argv[i], O_RDONLY);
            if (files[num_files].fd == -1) {
                perror("Error opening input file");
                exit(EXIT_FAILURE);
            }
            num_files++;
        }
    }

    return 0;
}
```
