#include <regex>
#include <vector>

using namespace std;

// Function to read a file line by line and count the number of lines
int countLines(const string& filename) {
    ifstream file(filename);
    vector<string> lines;
    string line;
    while (getline(file, line)) {
        lines.push_back(line);
    }
    return lines.size();
}

// Function to filter lines based on a regular expression
void filterLines(const string& filename, const regex& pattern) {
    ifstream file(filename);
    vector<string> lines;
    string line;
    while (getline(file, line)) {
        if (regex_match(line, pattern)) {
            lines.push_back(line);
        }
    }
}

