        filterLines(filename, pattern);
        ofstream outfile(outputFile);
        for (const string& line : lines) {
            outfile << line << endl;
        }
    } else if (!searchTerm.empty()) {
        // Search for a specific term and print the results to the console
        vector<string> lines = countLines(filename);
        for (const string& line : lines) {
            if (caseSensitive) {
                if (line.find(searchTerm) != string::npos) {
                    cout << line << endl;
                }
            } else {
                if (line.find(searchTerm, 0, string::npos) != string::npos) {
                    cout << line << endl;
                }
            }
        }
    } else {
        // Print the total number of lines in the file to the console
        cout << "Total number of lines: " << countLines(filename) << endl;
    }

    return 0;
}
