import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.atomic.AtomicInteger;
import java.util.logging.Logger;

public class TransactionProcessor {
    private static final Logger LOGGER = Logger.getLogger(TransactionProcessor.class.getName());

    // Custom data structure to manage and query discrepancies
    private ConcurrentHashMap<String, Discrepancy> discrepancies = new ConcurrentHashMap<>();

    // Thread-safe mechanism for handling concurrent updates
    public void processTransactions(List<Transaction> transactions) {
        for (Transaction transaction : transactions) {
            String key = generateKey(transaction);
            Discrepancy discrepancy = discrepancies.get(key);
            if (discrepancy == null) {
                discrepancy = new Discrepancy();
                discrepancies.put(key, discrepancy);
            }
            discrepancy.addTransaction(transaction);
        }
    }

    // Logging mechanism for recording time taken and number of discrepancies found per minute
    public void logDiscrepancies() {
        long startTime = System.currentTimeMillis();
        int numDiscrepancies = 0;
        for (String key : discrepancies.keySet()) {
            Discrepancy discrepancy = discrepancies.get(key);
            if (discrepancy.hasDiscrepancy()) {
                LOGGER.info("Discrepancy found: " + discrepancy.toString());
                numDiscrepancies++;
            }
        }
        long endTime = System.currentTimeMillis();
        long timeTaken = endTime - startTime;
        LOGGER.info("Number of discrepancies found per minute: " + numDiscrepancies);
        LOGGER.info("Time taken for processing discrepancies: " + timeTaken + " milliseconds");
    }

    // Filtering transactions based on user-defined criteria
    public List<Transaction> filterTransactions(List<Transaction> transactions, TransactionFilter filter) {
        return transactions.stream()
                .filter(transaction -> filter.isMatch(transaction))
                .collect(Collectors.toList());
    }

    // Custom data structure to manage and query discrepancies
    private class Discrepancy {
        private AtomicInteger numTransactions = new AtomicInteger();
        private double expectedAmount;
        private double actualAmount;

        public void addTransaction(Transaction transaction) {
            numTransactions.incrementAndGet();
            if (expectedAmount == 0) {
                expectedAmount = transaction.getExpectedAmount();
            } else if (actualAmount == 0) {
                actualAmount = transaction.getActualAmount();
            }
        }

        public boolean hasDiscrepancy() {
            return Math.abs(expectedAmount - actualAmount) > 10; // Threshold for discrepancy amount
        }

        @Override
        public String toString() {
            return "Expected: " + expectedAmount + ", Actual: " + actualAmount;
        }
    }
}
