// Define the structure for a user profile
typedef struct {
    int USER_ID;
    char* CONFIGURATION_STRUCTURE;
    time_t CURRENT_TIMESTAMP;
} USER_PROFILE;

// Define the registry of user profiles
USER_PROFILE* registry = NULL;
int registry_size = 0;
pthread_mutex_t registry_lock = PTHREAD_MUTEX_INITIALIZER;

// Function to add a new user profile to the registry
void add_user(int USER_ID, char* CONFIGURATION_STRUCTURE) {
    pthread_mutex_lock(&registry_lock);
    // Check if the user already exists in the registry
    for (int i = 0; i < registry_size; i++) {
        if (registry[i].USER_ID == USER_ID) {
            pthread_mutex_unlock(&registry_lock);
            return;
        }
    }
    // If the user does not exist, add a new entry to the registry
    registry = realloc(registry, (registry_size + 1) * sizeof(USER_PROFILE));
    registry[registry_size].USER_ID = USER_ID;
    registry[registry_size].CONFIGURATION_STRUCTURE = CONFIGURATION_STRUCTURE;
    registry[registry_size].CURRENT_TIMESTAMP = time(NULL);
    registry_size++;
    pthread_mutex_unlock(&registry_lock);
}

// Function to remove a user profile from the registry
void remove_user(int USER_ID) {
    pthread_mutex_lock(&registry_lock);
    // Find the index of the user in the registry
    int i = 0;
    while (i < registry_size && registry[i].USER_ID != USER_ID) {
        i++;
    }
    if (i == registry_size) {
        pthread_mutex_unlock(&registry_lock);
        return;
    }
    // Remove the user from the registry by shifting all subsequent entries back one index
    for (int j = i; j < registry_size - 1; j++) {
        registry[j] = registry[j + 1];
    }
    registry_size--;
    pthread_mutex_unlock(&registry_lock);
}

// Function to update the current timestamp for a user profile in the registry
void update_timestamp(int USER_ID) {
    pthread_mutex_lock(&registry_lock);
    // Find the index of the user in the registry
    int i = 0;
    while (i < registry_size && registry[i].USER_ID != USER_ID) {
        i++;
    }
    if (i == registry_size) {
        pthread_mutex_unlock(&registry_lock);
        return;
    }
    // Update the current timestamp for the user profile
    registry[i].CURRENT_TIMESTAMP = time(NULL);
    pthread_mutex_unlock(&registry_lock);
}

// Function to check if a user is currently logged in
int is_logged_in(int USER_ID) {
    pthread_mutex_lock(&registry_lock);
    // Find the index of the user in the registry
    int i = 0;
    while (i < registry_size && registry[i].USER_ID != USER_ID) {
        i++;
    }
    if (i == registry_size) {
        pthread_mutex_unlock(&registry_lock);
        return 0;
    }
    // Check if the user is currently logged in by checking the current timestamp
    time_t current_timestamp = time(NULL);
    int logged_in = (current_timestamp - registry[i].CURRENT_TIMESTAMP) < 300;
    pthread_mutex_unlock(&registry_lock);
    return logged_in;
}

// Function to simulate varying network latency conditions
void simulate_latency(int latency) {
    // Simulate the specified amount of latency by sleeping for a random amount of time
    int min = 100;
    int max = 500;
    int delay = (rand() % (max - min + 1)) + min;
    usleep(delay * 1000);
}

// Function to detect and log unusual activity patterns
void detect_abuse(int USER_ID) {
    pthread_mutex_lock(&registry_lock);
    // Find the index of the user in the registry
    int i = 0;
    while (i < registry_size && registry[i].USER_ID != USER_ID) {
        i++;
    }
    if (i == registry_size) {
        pthread_mutex_unlock(&registry_lock);
        return;
    }
    // Check for unusual activity patterns by comparing the current timestamp to the previous one
    time_t current_timestamp = time(NULL);
    int delta = (current_timestamp - registry[i].CURRENT_TIMESTAMP) / 60;
    if (delta < 15) {
        // If the user has logged in within the last 15 minutes, log an abuse warning
        printf("WARNING: User %d has logged in too frequently within a short period of time\n", USER_ID);
    }
    pthread_mutex_unlock(&registry_lock);
}
