import java.io.*;
import java.util.concurrent.*;
import java.util.logging.*;

public class OptimizeImageCompression {
    private static final Logger logger = Logger.getLogger(OptimizeImageCompression.class.getName());

    public static String optimizeImageCompression(String imageFilePath) throws IOException, InterruptedException {
        // Initialize variables
        long startTime = System.currentTimeMillis();
        int numThreads = Runtime.getRuntime().availableProcessors();
        ExecutorService executor = Executors.newFixedThreadPool(numThreads);
        String newImageFilePath;

        // Analyze image and determine optimal compression level
        ImageAnalysisTask analysisTask = new ImageAnalysisTask(imageFilePath);
        Future<Integer> analysisResult = executor.submit(analysisTask);
        int optimalCompressionLevel = analysisResult.get();

        // Compress image using optimal compression level
        ImageCompressionTask compressionTask = new ImageCompressionTask(imageFilePath, optimalCompressionLevel);
        Future<String> compressionResult = executor.submit(compressionTask);
        newImageFilePath = compressionResult.get();

        // Clean up temporary files and log results
        analysisTask.cleanup();
        compressionTask.cleanup();
        long endTime = System.currentTimeMillis();
        logger.info("Optimized image compression completed in " + (endTime - startTime) + " milliseconds");

        return newImageFilePath;
    }
}

class ImageAnalysisTask implements Callable<Integer> {
    private String imageFilePath;

    public ImageAnalysisTask(String imageFilePath) {
        this.imageFilePath = imageFilePath;
    }

    @Override
    public Integer call() throws IOException {
        // Initialize variables
        int optimalCompressionLevel = 0;
        long startTime = System.currentTimeMillis();

        // Analyze image and determine optimal compression level
        BufferedImage bufferedImage = ImageIO.read(new File(imageFilePath));
        int width = bufferedImage.getWidth();
        int height = bufferedImage.getHeight();
        int fileSize = new File(imageFilePath).length();
        if (width * height > 1000000) { // Large image, use multi-threading for analysis
            optimalCompressionLevel = analyzeLargeImage(bufferedImage);
        } else { // Small image, use single thread for analysis
            optimalCompressionLevel = analyzeSmallImage(bufferedImage);
        }

        // Clean up temporary files and log results
        long endTime = System.currentTimeMillis();
        logger.info("Image analysis completed in " + (endTime - startTime) + " milliseconds");

        return optimalCompressionLevel;
    }

    private int analyzeLargeImage(BufferedImage bufferedImage) {
        // Initialize variables
        int optimalCompressionLevel = 0;
        long startTime = System.currentTimeMillis();

        // Analyze image in chunks if file size exceeds available RAM
        int chunkSize = (int) Math.ceil(bufferedImage.getWidth() * bufferedImage.getHeight() / Runtime.getRuntime().maxMemory());
        for (int i = 0; i < bufferedImage.getWidth(); i += chunkSize) {
            // Analyze chunk and update optimal compression level
            int currentCompressionLevel = analyzeChunk(bufferedImage, i, Math.min(i + chunkSize, bufferedImage.getWidth()));
            if (currentCompressionLevel > optimalCompressionLevel) {
                optimalCompressionLevel = currentCompressionLevel;
            }
        }

        // Clean up temporary files and log results
        long endTime = System.currentTimeMillis();
        logger.info("Large image analysis completed in " + (endTime - startTime) + " milliseconds");

        return optimalCompressionLevel;
    }

    private int analyzeSmallImage(BufferedImage bufferedImage) {
        // Initialize variables
        int optimalCompressionLevel = 0;
        long startTime = System.currentTimeMillis();

        // Analyze image in a single thread
        for (int i = 0; i < bufferedImage.getWidth(); i++) {
            // Analyze row and update optimal compression level
            int currentCompressionLevel = analyzeRow(bufferedImage, i);
            if (currentCompressionLevel > optimalCompressionLevel) {
                optimalCompressionLevel = currentCompressionLevel;
            }
        }

        // Clean up temporary files and log results
        long endTime = System.currentTimeMillis();
        logger.info("Small image analysis completed in " + (endTime - startTime) + " milliseconds");

        return optimalCompressionLevel;
    }

    private int analyzeChunk(BufferedImage bufferedImage, int xStart, int xEnd) {
        // Initialize variables
        int optimalCompressionLevel = 0;
        long startTime = System.currentTimeMillis();

        // Analyze chunk in a single thread
        for (int i = xStart; i < xEnd; i++) {
            // Analyze row and update optimal compression level
            int currentCompressionLevel = analyzeRow(bufferedImage, i);
            if (currentCompressionLevel > optimalCompressionLevel) {
                optimalCompressionLevel = currentCompressionLevel;
            }
        }

        // Clean up temporary files and log results
        long endTime = System.currentTimeMillis();
        logger.info("Chunk analysis completed in " + (endTime - startTime) + " milliseconds");

        return optimalCompressionLevel;
    }

    private int analyzeRow(BufferedImage bufferedImage, int xStart) {
        // Initialize variables
        int optimalCompressionLevel = 0;
        long startTime = System.currentTimeMillis();

        // Analyze row in a single thread
        for (int i = xStart; i < bufferedImage.getWidth(); i++) {
            // Analyze pixel and update optimal compression level
            int currentCompressionLevel = analyzePixel(bufferedImage, i);
            if (currentCompressionLevel > optimalCompressionLevel) {
                optimalCompressionLevel = currentCompressionLevel;
            }
        }

        // Clean up temporary files and log results
        long endTime = System.currentTimeMillis();
        logger.info("Row analysis completed in " + (endTime - startTime) + " milliseconds");

        return optimalCompressionLevel;
    }

    private int analyzePixel(BufferedImage bufferedImage, int x) {
        // Initialize variables
        int optimalCompressionLevel = 0;
        long startTime = System.currentTimeMillis();

        // Analyze pixel in a single thread
        for (int i = 0; i < bufferedImage.getHeight(); i++) {
            // Analyze color and update optimal compression level
            int currentCompressionLevel = analyzeColor(bufferedImage, x, i);
            if (currentCompressionLevel > optimalCompressionLevel) {
                optimalCompressionLevel = currentCompressionLevel;
            }
        }

        // Clean up temporary files and log results
        long endTime = System.currentTimeMillis();
        logger.info("Pixel analysis completed in " + (endTime - startTime) + " milliseconds");

        return optimalCompressionLevel;
    }

    private int analyzeColor(BufferedImage bufferedImage, int x, int y) {
        // Initialize variables
        int optimalCompressionLevel = 0;
        long startTime = System.currentTimeMillis();

        // Analyze color in a single thread
        Color currentColor = new Color(bufferedImage.getRGB(x, y));
        int red = currentColor.getRed();
        int green = currentColor.getGreen();
        int blue = currentColor.getBlue();
        if (red > 250 && green > 250 && blue > 250) { // White color, high compression level
            optimalCompressionLevel = 10;
        } else if (red < 50 && green < 50 && blue < 50) { // Black color, low compression level
            optimalCompressionLevel = 1;
        } else { // Gray color, medium compression level
            optimalCompressionLevel = 5;
        }

        // Clean up temporary files and log results
        long endTime = System.currentTimeMillis();
        logger.info("Color analysis completed in " + (endTime - startTime) + " milliseconds");

        return optimalCompressionLevel;
    }

    private void cleanup() {
        // Clean up temporary files and log results
        long endTime = System.currentTimeMillis();
        logger.info("Image analysis completed in " + (endTime - startTime) + " milliseconds");
    }
}

class ImageCompressionTask implements Callable<String> {
    private String imageFilePath;
    private int optimalCompressionLevel;

    public ImageCompressionTask(String imageFilePath, int optimalCompressionLevel) {
        this.imageFilePath = imageFilePath;
        this.optimalCompressionLevel = optimalCompressionLevel;
    }

    @Override
    public String call() throws IOException {
        // Initialize variables
        long startTime = System.currentTimeMillis();

        // Compress image using optimal compression level
        BufferedImage bufferedImage = ImageIO.read(new File(imageFilePath));
        int width = bufferedImage.getWidth();
        int height = bufferedImage.getHeight();
        String newImageFilePath = imageFilePath + ".compressed";
        BufferedImage compressedImage = new BufferedImage(width, height, BufferedImage.TYPE_INT_RGB);
        for (int i = 0; i < width; i++) {
            for (int j = 0; j < height; j++) {
                Color currentColor = new Color(bufferedImage.getRGB(i, j));
                int red = currentColor.getRed();
                int green = currentColor.getGreen();
                int blue = currentColor.getBlue();
                if (red > 250 && green > 250 && blue > 250) { // White color, high compression level
                    compressedImage.setRGB(i, j, Color.WHITE.getRGB());
                } else if (red < 50 && green < 50 && blue < 50) { // Black color, low compression level
                    compressedImage.setRGB(i, j, Color.BLACK.getRGB());
                } else { // Gray color, medium compression level
                    int average = (red + green + blue) / 3;
                    compressedImage.setRGB(i, j, new Color(average, average, average).getRGB());
                }
            }
        }
        ImageIO.write(compressedImage, "jpg", new File(newImageFilePath));

        // Clean up temporary files and log results
        long endTime = System.currentTimeMillis();
        logger.info("Image compression completed in " + (endTime - startTime) + " milliseconds");

        return newImageFilePath;
    }
}
