import java.util.concurrent.Executors;
import java.util.concurrent.TimeUnit;

public class DisjointPairs {
    public static int countDisjointPairs(int[] arr) {
        // Initialize the Union-Find data structure
        UnionFind uf = new UnionFind(arr.length);

        // Iterate over each pair of elements in the array
        for (int i = 0; i < arr.length - 1; i++) {
            for (int j = i + 1; j < arr.length; j++) {
                // Check if the two elements are disjoint using the Union-Find data structure
                if (uf.find(i) != uf.find(j)) {
                    // If they are not disjoint, merge them into a single connected component
                    uf.union(i, j);
                }
            }
        }

        // Return the number of connected components in the Union-Find data structure
        return uf.count();
    }

    private static class UnionFind {
        private int[] parent;
        private int[] rank;
        private int count;

        public UnionFind(int n) {
            this.parent = new int[n];
            this.rank = new int[n];
            this.count = n;

            for (int i = 0; i < n; i++) {
                parent[i] = i;
                rank[i] = 1;
            }
        }

        public void union(int x, int y) {
            // Find the roots of the two elements to be merged
            int rootX = find(x);
            int rootY = find(y);

            // If the two elements are already in the same connected component, there is nothing to do
            if (rootX == rootY) {
                return;
            }

            // Merge the two connected components by attaching the smaller one to the larger one
            if (rank[rootX] < rank[rootY]) {
                parent[rootX] = rootY;
            } else if (rank[rootX] > rank[rootY]) {
                parent[rootY] = rootX;
            } else {
                parent[rootY] = rootX;
                rank[rootX]++;
            }

            count--;
        }

        public int find(int x) {
            // Find the root of the element by following the chain of parents until we reach the root
            while (parent[x] != x) {
                parent[x] = parent[parent[x]];
                x = parent[x];
            }
            return x;
        }

        public int count() {
            return count;
        }
    }
}
