// Function to allocate memory for the array and populate it with random data
int allocateAndPopulateCrcIndicationArray(uint32_t N) {
    // Check if the input is valid
    if (N == 0) {
        return -1;
    }

    // Allocate memory for the array
    crcIndicationArray = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T) * N);
    if (crcIndicationArray == NULL) {
        return -2;
    }

    // Populate each structure with random data
    srand(time(NULL));
    for (uint32_t i = 0; i < N; i++) {
        crcIndicationArray[i].RX_UE_INFORMATION_TAG = rand() % 10000;
        crcIndicationArray[i].RNTI = rand() % 100000000;
        crcIndicationArray[i].CRCFLAG = rand() % 256;
        crcIndicationArray[i].CRC_INDICATION_REL8_TAG = rand() % 10000;
    }

    return 0;
}

// Function to add additional metadata for each structure
void addMetadataToCrcIndicationArray(uint32_t N) {
    // Check if the input is valid
    if (N == 0) {
        return;
    }

    // Add metadata to each structure
    for (uint32_t i = 0; i < N; i++) {
        crcIndicationArray[i].timestamp = time(NULL);
        crcIndicationArray[i].sequenceNumber = rand() % 10000;
    }
}

// Function to retrieve an element from the array by index
NFAPI_CRC_INDICATION_PDU_T getElementFromCrcIndicationArray(uint32_t index) {
    // Check if the input is valid
    if (index >= N) {
        return NULL;
    }

    return crcIndicationArray[index];
}

