// Define the structure for an NFAPI_CRC_INDICATION_PDU_T
typedef struct {
    uint16_t RX_UE_INFORMATION_TAG;
    uint32_t RNTI;
    uint8_t CRC_INDICATION_REL8_TAG;
    bool CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

// Define the dynamic array of NFAPI_CRC_INDICATION_PDU_T structures
typedef struct {
    NFAPI_CRC_INDICATION_PDU_T* data;
    size_t capacity;
    size_t size;
} NFAPI_CRC_INDICATION_PDU_ARRAY;

// Function to add a new structure to the array, checking for overflow and resizing if needed
void nfapi_crc_indication_pdu_array_add(NFAPI_CRC_INDICATION_PDU_ARRAY* array, NFAPI_CRC_INDICATION_PDU_T* pdu) {
    // Check for overflow and resize if needed
    if (array->size == array->capacity) {
        array->capacity *= 2;
        array->data = realloc(array->data, sizeof(NFAPI_CRC_INDICATION_PDU_T) * array->capacity);
    }

    // Add the new structure to the end of the array
    array->data[array->size++] = *pdu;
}

// Function to remove a structure from the array by RNTI
void nfapi_crc_indication_pdu_array_remove(NFAPI_CRC_INDICATION_PDU_ARRAY* array, uint32_t rnti) {
    // Find the index of the structure to remove
    size_t i;
    for (i = 0; i < array->size; i++) {
        if (array->data[i].RNTI == rnti) {
            break;
        }
    }

    // If the structure was found, remove it and shift the remaining structures down
    if (i < array->size) {
        memmove(&array->data[i], &array->data[i + 1], sizeof(NFAPI_CRC_INDICATION_PDU_T) * (array->size - i));
        array->size--;
    }
}

// Function to iterate over the array and print all tags and CRC flags
void nfapi_crc_indication_pdu_array_print(NFAPI_CRC_INDICATION_PDU_ARRAY* array) {
    for (size_t i = 0; i < array->size; i++) {
        printf("RX_UE_INFORMATION_TAG: %u\n", array->data[i].RX_UE_INFORMATION_TAG);
        printf("RNTI: %u\n", array->data[i].RNTI);
        printf("CRC_INDICATION_REL8_TAG: %u\n", array->data[i].CRC_INDICATION_REL8_TAG);
        printf("CRCFLAG: %s\n", array->data[i].CRCFLAG ? "true" : "false");
    }
}

// Function to handle memory allocation and deallocation safely, ensuring no memory leaks occur
void nfapi_crc_indication_pdu_array_destroy(NFAPI_CRC_INDICATION_PDU_ARRAY* array) {
    free(array->data);
}
```
