            using (StreamReader reader = new StreamReader(keywordsFile))
            {
                string line;
                while ((line = reader.ReadLine()) != null)
                {
                    keywords.Add(line);
                }
            }

            // Process input files
            foreach (string file in args.Skip(2))
            {
                using (StreamReader reader = new StreamReader(file))
                {
                    string line;
                    while ((line = reader.ReadLine()) != null)
                    {
                        // Check if any keywords are present in the current line
                        bool foundKeyword = false;
                        foreach (string keyword in keywords)
                        {
                            if (line.Contains(keyword))
                            {
                                foundKeyword = true;
                                break;
                            }
                        }

                        // If a keyword is found, extract the context and sentiment analysis
                        if (foundKeyword)
                        {
                            string[] context = line.Split(' ');
                            int sentiment = 0;
                            foreach (string word in context)
                            {
                                if (word == "positive")
                                {
                                    sentiment++;
                                }
                                else if (word == "negative")
                                {
                                    sentiment--;
                                }
                            }

                            // Write the extracted information to the output file
                            using (StreamWriter writer = new StreamWriter(outputFile, true))
                            {
                                writer.WriteLine($"{file}:{line} - {sentiment}");
                            }
                        }
                    }
                }
            }
        }
    }
}
```
This program uses the `StreamReader` and `StreamWriter` classes to read and write text files, respectively. It also uses the `List<string>` class to store the list of keywords and the `foreach` loop to iterate over the input files. The program checks if any keywords are present in each line using the `Contains` method and extracts the context and sentiment analysis using a simple algorithm. Finally, it writes the extracted information to the output file using the `WriteLine` method.

