#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <unistd.h>

// Define the structure for the cache entry
typedef struct {
    uint64_t object_id;
    void* resource;
    time_t timestamp;
} custom_object_t;

// Define the structure for the cache
typedef struct {
    custom_object_t** objects;
    size_t capacity;
    size_t count;
    pthread_mutex_t mutex;
} cache_t;

// Function to initialize the cache
void init_cache(cache_t* cache, size_t capacity) {
    // Allocate memory for the cache objects
    cache->objects = malloc(capacity * sizeof(custom_object_t));
    if (cache->objects == NULL) {
        printf("Error: failed to allocate memory for cache\n");
        exit(1);
    }

    // Initialize the mutex for synchronizing access to the cache
    pthread_mutex_init(&cache->mutex, NULL);

    // Set the capacity and count of the cache
    cache->capacity = capacity;
    cache->count = 0;
}

// Function to add an object to the cache
void add_object(cache_t* cache, uint64_t object_id, void* resource) {
    // Acquire the mutex for synchronizing access to the cache
    pthread_mutex_lock(&cache->mutex);

    // Check if the cache is full
    if (cache->count == cache->capacity) {
        printf("Error: cache is full\n");
        exit(1);
    }

    // Create a new cache entry for the object
    custom_object_t* new_entry = malloc(sizeof(custom_object_t));
    if (new_entry == NULL) {
        printf("Error: failed to allocate memory for cache entry\n");
        exit(1);
    }

    // Initialize the fields of the cache entry
    new_entry->object_id = object_id;
    new_entry->resource = resource;
    new_entry->timestamp = time(NULL);

    // Add the cache entry to the end of the cache
    cache->objects[cache->count++] = new_entry;

    // Release the mutex for synchronizing access to the cache
    pthread_mutex_unlock(&cache->mutex);
}

// Function to remove an object from the cache
void remove_object(cache_t* cache, uint64_t object_id) {
    // Acquire the mutex for synchronizing access to the cache
    pthread_mutex_lock(&cache->mutex);

    // Find the index of the object in the cache
    size_t i;
    for (i = 0; i < cache->count; i++) {
        if (cache->objects[i]->object_id == object_id) {
            break;
        }
    }

    // Check if the object was found in the cache
    if (i == cache->count) {
        printf("Error: object not found in cache\n");
        exit(1);
    }

    // Remove the object from the cache
    custom_object_t* removed_entry = cache->objects[i];
    cache->objects[i] = NULL;
    free(removed_entry);

    // Decrement the count of the cache
    cache->count--;

    // Release the mutex for synchronizing access to the cache
    pthread_mutex_unlock(&cache->mutex);
}

// Function to evict expired objects from the cache
void evict_expired(cache_t* cache) {
    // Acquire the mutex for synchronizing access to the cache
    pthread_mutex_lock(&cache->mutex);

    // Iterate over the cache entries and remove any that have expired
    size_t i;
    for (i = 0; i < cache->count; i++) {
        custom_object_t* entry = cache->objects[i];
        if (entry->timestamp + TIMEOUT <= time(NULL)) {
            remove_object(cache, entry->object_id);
            i--;
        }
    }

    // Release the mutex for synchronizing access to the cache
    pthread_mutex_unlock(&cache->mutex);
}

// Function to persist the state of the cache to disk
void persist(cache_t* cache) {
    // Acquire the mutex for synchronizing access to the cache
    pthread_mutex_lock(&cache->mutex);

    // Open a file for writing and write the cache entries to it
    FILE* fp = fopen("cache.dat", "wb");
    if (fp == NULL) {
        printf("Error: failed to open file for writing\n");
        exit(1);
    }

    // Write the number of cache entries to the file
    size_t num_entries = cache->count;
    fwrite(&num_entries, sizeof(size_t), 1, fp);

    // Write each cache entry to the file
    for (size_t i = 0; i < cache->count; i++) {
        custom_object_t* entry = cache->objects[i];
        fwrite(&entry->object_id, sizeof(uint64_t), 1, fp);
        fwrite(&entry->resource, sizeof(void*), 1, fp);
        fwrite(&entry->timestamp, sizeof(time_t), 1, fp);
    }

    // Close the file and release the mutex for synchronizing access to the cache
    fclose(fp);
    pthread_mutex_unlock(&cache->mutex);
}

// Function to load the state of the cache from disk
void load(cache_t* cache) {
    // Acquire the mutex for synchronizing access to the cache
    pthread_mutex_lock(&cache->mutex);

    // Open a file for reading and read the number of cache entries from it
    FILE* fp = fopen("cache.dat", "rb");
    if (fp == NULL) {
        printf("Error: failed to open file for reading\n");
        exit(1);
    }

    // Read the number of cache entries from the file
    size_t num_entries;
    fread(&num_entries, sizeof(size_t), 1, fp);

    // Allocate memory for the cache objects
    cache->objects = malloc(num_entries * sizeof(custom_object_t));
    if (cache->objects == NULL) {
        printf("Error: failed to allocate memory for cache\n");
        exit(1);
    }

    // Read each cache entry from the file and add it to the cache
    for (size_t i = 0; i < num_entries; i++) {
        custom_object_t* entry = malloc(sizeof(custom_object_t));
        if (entry == NULL) {
            printf("Error: failed to allocate memory for cache entry\n");
            exit(1);
        }

        // Read the fields of the cache entry from the file
        fread(&entry->object_id, sizeof(uint64_t), 1, fp);
        fread(&entry->resource, sizeof(void*), 1, fp);
        fread(&entry->timestamp, sizeof(time_t), 1, fp);

        // Add the cache entry to the end of the cache
        cache->objects[cache->count++] = entry;
    }

    // Close the file and release the mutex for synchronizing access to the cache
    fclose(fp);
    pthread_mutex_unlock(&cache->mutex);
}
