#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <errno.h>
#include <stdbool.h>
#include <pthread.h>

#define MAX_LINE_LENGTH 1024
#define MAX_KEYWORDS 100
#define OUTPUT_FILE "report.txt"

// Struct to store information about a keyword and its occurrences
typedef struct {
    char *keyword;
    int frequency;
    int line_numbers[MAX_LINE_LENGTH];
} KeywordInfo;

// Global variables
char **keywords = NULL;
int num_keywords = 0;
bool help_flag = false;
char *output_file = OUTPUT_FILE;

// Function to parse command line arguments and set global variables
void parse_args(int argc, char **argv) {
    int c;
    while ((c = getopt(argc, argv, "hk:o:")) != -1) {
        switch (c) {
            case 'h':
                help_flag = true;
                break;
            case 'k':
                keywords = optarg;
                num_keywords = strlen(optarg);
                break;
            case 'o':
                output_file = optarg;
                break;
        }
    }
}

// Function to read a file and extract keywords
void *read_file(void *filename) {
    char *file = (char *) filename;
    FILE *fp = fopen(file, "r");
    if (!fp) {
        perror("fopen");
        exit(EXIT_FAILURE);
    }

    // Read file line by line and extract keywords
    char line[MAX_LINE_LENGTH];
    while (fgets(line, MAX_LINE_LENGTH, fp)) {
        for (int i = 0; i < num_keywords; i++) {
            if (strstr(line, keywords[i])) {
                // Increment frequency of keyword and store line number
                KeywordInfo *info = &keyword_infos[i];
                info->frequency++;
                info->line_numbers[info->frequency - 1] = ftell(fp) - strlen(line);
            }
        }
    }

    fclose(fp);
}

// Function to generate a summary report of keyword occurrences
void generate_report() {
    FILE *output = fopen(output_file, "w");
    if (!output) {
        perror("fopen");
        exit(EXIT_FAILURE);
    }

    // Print header for report
    fprintf(output, "Keyword\tFrequency\tLine Numbers\n");

    // Iterate over keyword infos and print report
    for (int i = 0; i < num_keywords; i++) {
        KeywordInfo *info = &keyword_infos[i];
        fprintf(output, "%s\t%d\t", info->keyword, info->frequency);
        for (int j = 0; j < info->frequency; j++) {
            fprintf(output, "%d ", info->line_numbers[j]);
        }
        fprintf(output, "\n");
    }

    fclose(output);
}

// Main function to process input files and generate report
int main(int argc, char **argv) {
    parse_args(argc, argv);

    // Check if help flag is set
    if (help_flag) {
        printf("Usage: %s [-h] -k <keywords_file> -o <output_file>\n", argv[0]);
        return 0;
    }

    // Check if keywords file and output file are specified
    if (!keywords || !output_file) {
        printf("Error: Please specify a keywords file and an output file\n");
        return 1;
    }

    // Load keywords from file
    FILE *keyword_file = fopen(keywords, "r");
    if (!keyword_file) {
        perror("fopen");
        exit(EXIT_FAILURE);
    }
    char line[MAX_LINE_LENGTH];
    while (fgets(line, MAX_LINE_LENGTH, keyword_file)) {
        // Remove newline character from end of line
        int len = strlen(line) - 1;
        if (line[len] == '\n') {
            line[len] = '\0';
        }
        keywords[num_keywords++] = strdup(line);
    }
    fclose(keyword_file);

    // Initialize keyword infos array
    KeywordInfo keyword_infos[MAX_KEYWORDS];
    for (int i = 0; i < num_keywords; i++) {
        keyword_infos[i].keyword = keywords[i];
        keyword_infos[i].frequency = 0;
    }

    // Process input files in parallel using threads
    pthread_t threads[MAX_KEYWORDS];
    for (int i = 0; i < num_keywords; i++) {
        char *filename = argv[i + 2];
        if (!filename) {
            printf("Error: Please specify at least one input file\n");
            return 1;
        }
        pthread_create(&threads[i], NULL, read_file, filename);
    }

    // Join threads and generate report
    for (int i = 0; i < num_keywords; i++) {
        pthread_join(threads[i], NULL);
    }
    generate_report();

    return 0;
}']

