    if (!new_object) {
        perror("Failed to allocate memory for new cache object");
        exit(1);
    }

    // Set the fields of the new object
    new_object->object_id = object_id;
    new_object->resource = resource;
    new_object->timestamp = time(NULL);

    // Acquire the mutex for synchronizing access to the cache
    pthread_mutex_lock(&cache->mutex);

    // Check if the cache is full
    if (cache->count == cache->capacity) {
        // Evict an object from the cache if necessary
        evict_object(cache);
    }

    // Add the new object to the cache
    cache->objects[cache->count++] = new_object;

    // Release the mutex for synchronizing access to the cache
    pthread_mutex_unlock(&cache->mutex);
}

// Function to evict an object from the cache
void evict_object(cache_t* cache) {
    // Find the oldest object in the cache
    size_t oldest_index = 0;
    time_t oldest_timestamp = cache->objects[0]->timestamp;
    for (size_t i = 1; i < cache->count; i++) {
        if (cache->objects[i]->timestamp < oldest_timestamp) {
            oldest_index = i;
            oldest_timestamp = cache->objects[i]->timestamp;
        }
    }

    // Remove the oldest object from the cache
    custom_object_t* evicted_object = cache->objects[oldest_index];
    free(evicted_object);
    cache->count--;
}

// Function to retrieve an object from the cache
custom_object_t* get_object(cache_t* cache, int object_id) {
    // Acquire the mutex for synchronizing access to the cache
    pthread_mutex_lock(&cache->mutex);

    // Find the object in the cache
    size_t index = 0;
    while (index < cache->count && cache->objects[index]->object_id != object_id) {
        index++;
    }

    // If the object is not found, return NULL
    if (index == cache->count) {
        pthread_mutex_unlock(&cache->mutex);
        return NULL;
    }

    // Update the timestamp of the found object
    cache->objects[index]->timestamp = time(NULL);

    // Release the mutex for synchronizing access to the cache
    pthread_mutex_unlock(&cache->mutex);

    return cache->objects[index];
}

// Function to remove an object from the cache
void remove_object(cache_t* cache, int object_id) {
    // Acquire the mutex for synchronizing access to the cache
    pthread_mutex_lock(&cache->mutex);

    // Find the object in the cache
    size_t index = 0;
    while (index < cache->count && cache->objects[index]->object_id != object_id) {
        index++;
    }

    // If the object is not found, return
    if (index == cache->count) {
        pthread_mutex_unlock(&cache->mutex);
        return;
    }

    // Remove the object from the cache
    custom_object_t* removed_object = cache->objects[index];
    free(removed_object);
    cache->count--;

    // Shift all objects after the removed object to fill the gap
    for (size_t i = index; i < cache->count; i++) {
        cache->objects[i] = cache->objects[i + 1];
    }

    // Release the mutex for synchronizing access to the cache
    pthread_mutex_unlock(&cache->mutex);
}

// Function to persist the state of the cache to disk
void persist_cache(cache_t* cache) {
    // Open a file for writing
    int fd = open("cache.dat", O_WRONLY | O_CREAT, 0644);
    if (fd == -1) {
        perror("Failed to open cache file for writing");
        exit(1);
    }

    // Write the number of objects in the cache to the file
    size_t num_objects = cache->count;
    ssize_t bytes_written = write(fd, &num_objects, sizeof(size_t));
    if (bytes_written == -1) {
        perror("Failed to write number of objects to cache file");
        exit(1);
    }

    // Write each object in the cache to the file
    for (size_t i = 0; i < num_objects; i++) {
        custom_object_t* object = cache->objects[i];
        bytes_written = write(fd, object, sizeof(custom_object_t));
        if (bytes_written == -1) {
            perror("Failed to write object to cache file");
            exit(1);
        }
    }

    // Close the file
    close(fd);
}

// Function to load the state of the cache from disk
void load_cache(cache_t* cache) {
    // Open a file for reading
    int fd = open("cache.dat", O_RDONLY, 0644);
    if (fd == -1) {
        perror("Failed to open cache file for reading");
        exit(1);
    }

    // Read the number of objects in the cache from the file
    size_t num_objects;
    ssize_t bytes_read = read(fd, &num_objects, sizeof(size_t));
    if (bytes_read == -1) {
        perror("Failed to read number of objects from cache file");
        exit(1);
    }

    // Read each object in the cache from the file
    for (size_t i = 0; i < num_objects; i++) {
        custom_object_t* object = (custom_object_t*)malloc(sizeof(custom_object_t));
        if (!object) {
            perror("Failed to allocate memory for cache object");
            exit(1);
        }
        bytes_read = read(fd, object, sizeof(custom_object_t));
        if (bytes_read == -1) {
            perror("Failed to read object from cache file");
            exit(1);
        }
        add_object(cache, object->object_id, object->resource);
    }

    // Close the file
    close(fd);
}

// Function to handle errors during persistence
void handle_persistence_error(const char* error) {
    perror("Error during cache persistence");
    exit(1);
}

int main() {
    // Initialize the cache with a capacity of 10 objects
    cache_t cache;
    init_cache(&cache, 10);

    // Load the state of the cache from disk if necessary
    load_cache(&cache);

    // Add an object to the cache
    add_object(&cache, 1, "Hello World");

    // Get an object from the cache
    custom_object_t* object = get_object(&cache, 1);
    if (object) {
        printf("Object found: %s\n", object->resource);
    } else {
        printf("Object not found\n");
    }

    // Remove an object from the cache
    remove_object(&cache, 1);

    // Persist the state of the cache to disk
    persist_cache(&cache);

    return 0;
}']

