#include <stdbool.h>

// Define constants for command line options
#define OPTION_HELP "--help"
#define OPTION_KEYWORDS "--keywords"
#define OPTION_OUTPUT "--output"

// Define constants for file access modes
#define FILE_MODE_READ "r"
#define FILE_MODE_WRITE "w+"

// Define constants for thread synchronization
#define THREAD_SYNC_LOCK 1
#define THREAD_SYNC_UNLOCK 0

// Define constants for memory management
#define MEMORY_POOL_SIZE 1024 * 1024 * 10 // 10 MB
#define MEMORY_ALLOCATION_FAILURE -1

// Define structure to store keyword information
typedef struct {
    char* keyword;
    int frequency;
    int line_number;
    char* context;
} KeywordInfo;

// Define function prototypes
void printUsage();
int processFile(char* file_name, char** keywords, int num_keywords, char* output_file);
void* threadFunction(void* args);
void initializeMemoryPool();
void* allocateMemory(size_t size);
void deallocateMemory(void* memory);
void synchronizeThreads(int lock);
void logMessage(char* message);

// Define global variables
semaphore_t thread_sync;
KeywordInfo** keyword_info;
int num_keywords;
char* output_file;

int main(int argc, char** argv) {
    // Check command line arguments
    if (argc < 3) {
        printUsage();
        return 1;
    }

    // Initialize memory pool and thread synchronization
    initializeMemoryPool();
    pthread_mutex_init(&thread_sync, NULL);

    // Parse command line arguments
    char* keywords_file = NULL;
    char* output_file = NULL;
    int i;
    for (i = 1; i < argc - 1; i++) {
        if (!strcmp(argv[i], OPTION_HELP)) {
            printUsage();
            return 0;
        } else if (!strcmp(argv[i], OPTION_KEYWORDS)) {
            keywords_file = argv[++i];
        } else if (!strcmp(argv[i], OPTION_OUTPUT)) {
            output_file = argv[++i];
        }
    }

    // Load keywords from file
    num_keywords = 0;
    keyword_info = NULL;
    FILE* keywords_fp = fopen(keywords_file, "r");
    if (keywords_fp == NULL) {
        logMessage("Error: Unable to open keywords file.");
        return 1;
    }
    char line[256];
    while (fgets(line, sizeof(line), keywords_fp)) {
        num_keywords++;
        keyword_info = realloc(keyword_info, num_keywords * sizeof(KeywordInfo*));
        if (keyword_info == NULL) {
            logMessage("Error: Unable to allocate memory for keyword information.");
            return 1;
        }
        keyword_info[num_keywords - 1] = malloc(sizeof(KeywordInfo));
        if (keyword_info[num_keywords - 1] == NULL) {
            logMessage("Error: Unable to allocate memory for keyword information.");
            return 1;
        }
        keyword_info[num_keywords - 1]->keyword = strdup(line);
        keyword_info[num_keywords - 1]->frequency = 0;
        keyword_info[num_keywords - 1]->line_number = 0;
        keyword_info[num_keywords - 1]->context = NULL;
    }
    fclose(keywords_fp);

    // Process input files
    int num_files = argc - i;
    char** file_names = malloc(sizeof(char*) * num_files);
    if (file_names == NULL) {
        logMessage("Error: Unable to allocate memory for file names.");
        return 1;
    }
    int j;
    for (j = 0; j < num_files; j++) {
        file_names[j] = argv[i + j];
    }
    pthread_t* threads = malloc(sizeof(pthread_t) * num_files);
    if (threads == NULL) {
        logMessage("Error: Unable to allocate memory for thread handles.");
        return 1;
    }
    int k;
    for (k = 0; k < num_files; k++) {
        pthread_create(&threads[k], NULL, threadFunction, file_names[k]);
    }
    for (k = 0; k < num_files; k++) {
        pthread_join(threads[k], NULL);
    }
    free(threads);

    // Generate report
    FILE* output_fp = fopen(output_file, "w+");
    if (output_fp == NULL) {
        logMessage("Error: Unable to open output file.");
        return 1;
    }
    for (i = 0; i < num_keywords; i++) {
        fprintf(output_fp, "%s\t%d\t%d\n", keyword_info[i]->keyword, keyword_info[i]->frequency, keyword_info[i]->line_number);
    }
    fclose(output_fp);

    // Clean up memory
    for (i = 0; i < num_keywords; i++) {
        free(keyword_info[i]);
    }
    free(keyword_info);
    free(file_names);

    return 0;
}

void printUsage() {
    printf("Usage: %s [options] <input files>\n", argv[0]);
    printf("\t--help\t\tDisplay usage instructions.\n");
    printf("\t--keywords\tFile containing list of keywords to extract.\n");
    printf("\t--output\tOutput file for report.\n");
}

int processFile(char* file_name, char** keywords, int num_keywords, char* output_file) {
    // Open input file
    FILE* input_fp = fopen(file_name, "r");
    if (input_fp == NULL) {
        logMessage("Error: Unable to open input file.");
        return 1;
    }

    // Initialize keyword frequency and line number tracking
    int i;
    for (i = 0; i < num_keywords; i++) {
        keyword_info[i]->frequency = 0;
        keyword_info[i]->line_number = 0;
    }

    // Process input file line by line
    char line[256];
    while (fgets(line, sizeof(line), input_fp)) {
        int j;
        for (j = 0; j < num_keywords; j++) {
            if (strstr(line, keyword_info[j]->keyword) != NULL) {
                keyword_info[j]->frequency++;
                keyword_info[j]->line_number++;
            }
        }
    }
    fclose(input_fp);

    return 0;
}

void* threadFunction(void* args) {
    char* file_name = (char*)args;
    processFile(file_name, keyword_info, num_keywords, output_file);
    return NULL;
}

void initializeMemoryPool() {
    // Allocate memory pool
    void* memory_pool = malloc(MEMORY_POOL_SIZE);
    if (memory_pool == NULL) {
        logMessage("Error: Unable to allocate memory for memory pool.");
        return;
    }

    // Initialize memory pool
    int i;
    for (i = 0; i < MEMORY_POOL_SIZE / sizeof(void*); i++) {
        void** memory_block = (void**)memory_pool + i;
        *memory_block = NULL;
    }
}

void* allocateMemory(size_t size) {
    // Check if memory pool is full
    int i;
    for (i = 0; i < MEMORY_POOL_SIZE / sizeof(void*); i++) {
        void** memory_block = (void**)memory_pool + i;
        if (*memory_block == NULL) {
            break;
        }
    }
    if (i == MEMORY_POOL_SIZE / sizeof(void*)) {
        return NULL;
    }

    // Allocate memory block from pool
    void** memory_block = (void**)memory_pool + i;
    *memory_block = malloc(size);
    if (*memory_block == NULL) {
        logMessage("Error: Unable to allocate memory.");
        return NULL;
    }

    // Return memory block
    return *memory_block;
}

void deallocateMemory(void* memory) {
    // Check if memory is in pool
    int i;
    for (i = 0; i < MEMORY_POOL_SIZE / sizeof(void*); i++) {
        void** memory_block = (void**)memory_pool + i;
        if (*memory_block == memory) {
            break;
        }
    }
    if (i == MEMORY_POOL_SIZE / sizeof(void*)) {
        logMessage("Error: Unable to deallocate memory.");
        return;
    }

    // Deallocate memory block from pool
    void** memory_block = (void**)memory_pool + i;
    free(*memory_block);
    *memory_block = NULL;
}

void synchronizeThreads(int lock) {
    pthread_mutex_lock(&thread_sync);
    if (lock == THREAD_SYNC_LOCK) {
        while (1) {
            int i;
            for (i = 0; i < MEMORY_POOL_SIZE / sizeof(void*); i++) {
                void** memory_block = (void**)memory_pool + i;
                if (*memory_block != NULL) {
                    break;
                }
            }
            if (i == MEMORY_POOL_SIZE / sizeof(void*)) {
                break;
            }
        }
    } else {
        while (1) {
            int i;
            for (i = 0; i < MEMORY_POOL_SIZE / sizeof(void*); i++) {
                void** memory_block = (void**)memory_pool + i;
                if (*memory_block == NULL) {
                    break;
                }
            }
            if (i == MEMORY_POOL_SIZE / sizeof(void*)) {
                break;
            }
        }
    }
    pthread_mutex_unlock(&thread_sync);
}

void logMessage(char* message) {
    printf("%s\n", message);
}
