void print_total(int* arr, size_t n) {
    printf("Total number of valid integers: %zu\n", count_valid(arr, n));
}

// Function to efficiently read a list of integers from standard input
void read_integers(CACHE* cache) {
    // Allocate memory for the array
    int* arr = (int*)malloc(sizeof(int) * 1000);
    if (!arr) {
        printf("Error: failed to allocate memory for integer array\n");
        exit(1);
    }

    // Read the integers from standard input
    size_t i = 0;
    while (scanf("%d", &arr[i]) == 1 && i < 1000) {
        if (arr[i] >= -1000 && arr[i] <= 1000) {
            validate_integer(cache, i, (void*)&arr[i]);
        } else {
            printf("Error: integer out of range\n");
        }
        i++;
    }

    // Print the largest integer in the array
    find_largest(arr, i);

    // Print the total number of valid integers in the array
    print_total(arr, i);

    // Free the memory for the array
    free(arr);
}

// Function to efficiently determine the number of disjoint pairs of elements within an array
void find_pairs(int* arr, size_t n) {
    // Create a Union-Find data structure to keep track of the connected components
    UF uf = new_uf(n);

    // Iterate over the array and check for disjoint pairs
    for (size_t i = 0; i < n; i++) {
        for (size_t j = i + 1; j < n; j++) {
            if (arr[i] == arr[j]) {
                // If the elements are equal, merge their connected components
                uf_union(uf, i, j);
            }
        }
    }

    // Print the number of disjoint pairs found
    printf("Number of disjoint pairs: %zu\n", uf_count(uf));

    // Free the memory for the Union-Find data structure
    free_uf(uf);
}
