#include <iostream>
#include <fstream>
#include <string>
#include <map>
#include <vector>
#include <algorithm>
#include <thread>
#include <mutex>
#include <condition_variable>
#include <chrono>
#include <cstdlib>
#include <ctime>
#include <csignal>

using namespace std;

// Global variables
const string DEFAULT_OUTPUT_FILE = "error_codes.txt";
const int DEFAULT_TOP_N = 10;
const int MAX_THREADS = 8;
const int MIN_THREADS = 2;
const int MAX_RETRY_COUNT = 3;
const int RETRY_DELAY = 5000; // in milliseconds
const string ERROR_CODE_PATTERN = "\\b[A-Z]{4}\\b";

// Struct to store error code and its count
struct ErrorCode {
    string code;
    int count;
};

// Comparator function for sorting error codes by count
bool compareErrorCodes(const ErrorCode& e1, const ErrorCode& e2) {
    return e1.count > e2.count;
}

// Function to extract error code from a log entry
string extractErrorCode(const string& line) {
    smatch matches;
    regex_search(line, matches, regex(ERROR_CODE_PATTERN));
    if (matches.size() > 0) {
        return matches[0].str();
    } else {
        return "";
    }
}

// Function to process a single log file
void processFile(const string& filename, const string& output_file, int top_n) {
    ifstream infile(filename);
    ofstream outfile(output_file, ios::app);
    map<string, int> error_codes;

    // Read the file line by line and extract error codes
    string line;
    while (getline(infile, line)) {
        string code = extractErrorCode(line);
        if (!code.empty()) {
            error_codes[code]++;
        }
    }

    // Sort the error codes by count and write to output file
    vector<ErrorCode> sorted_error_codes;
    for (auto it = error_codes.begin(); it != error_codes.end(); ++it) {
        sorted_error_codes.push_back({it->first, it->second});
    }
    sort(sorted_error_codes.begin(), sorted_error_codes.end(), compareErrorCodes);
    for (int i = 0; i < top_n && i < sorted_error_codes.size(); ++i) {
        outfile << sorted_error_codes[i].code << " : " << sorted_error_codes[i].count << endl;
    }
}

// Function to process multiple log files in parallel
void processFiles(const vector<string>& filenames, const string& output_file, int top_n) {
    // Create a priority queue of file names and their corresponding indices
    priority_queue<pair<int, string>, vector<pair<int, string>>, greater<pair<int, string>>> file_indices;
    for (int i = 0; i < filenames.size(); ++i) {
        file_indices.push({i, filenames[i]});
    }

    // Create a vector of threads to process the files in parallel
    vector<thread> threads;
    for (int i = 0; i < MAX_THREADS && !file_indices.empty(); ++i) {
        string filename = file_indices.top().second;
        int index = file_indices.top().first;
        file_indices.pop();
        threads.push_back(thread([=]() { processFile(filename, output_file, top_n); }));
    }

    // Wait for all threads to finish and join them
    for (auto& t : threads) {
        t.join();
    }
}

// Function to handle SIGINT signal
void sigintHandler(int signum) {
    cout << "Caught SIGINT" << endl;
    exit(signum);
}

int main(int argc, char* argv[]) {
    // Parse command line arguments
    string output_file = DEFAULT_OUTPUT_FILE;
    int top_n = DEFAULT_TOP_N;
    vector<string> filenames;
    for (int i = 1; i < argc; ++i) {
        if (strcmp(argv[i], "-o") == 0 && i + 1 < argc) {
            output_file = argv[++i];
        } else if (strcmp(argv[i], "-c") == 0 && i + 1 < argc) {
            top_n = atoi(argv[++i]);
        } else if (strcmp(argv[i], "--help") == 0) {
            cout << "Usage: " << argv[0] << " [-o output_file] [-c top_n] [log_files]" << endl;
            return 1;
        } else {
            filenames.push_back(argv[i]);
        }
    }

    // Check if any log files are specified
    if (filenames.empty()) {
        cout << "No log files specified" << endl;
        return 1;
    }

    // Set up signal handling for SIGINT
    struct sigaction sa;
    memset(&sa, 0, sizeof(struct sigaction));
    sa.sa_handler = sigintHandler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    // Process the log files in parallel
    processFiles(filenames, output_file, top_n);

    return 0;
}']

